-- ==================== EXTENSIONS ====================
CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pg_cron;
create extension if not exists pg_cron with schema extensions;
create extension if not exists btree_gist;
create extension if not exists pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ==================== ENUM TYPES ====================
CREATE TYPE ad_asset_type AS ENUM ('square_post', 'portrait_story', 'landscape_promo', 'fallback_graphic')
CREATE TYPE ad_job_type AS ENUM ('image_ad', 'video_promo', 'caption_only', 'full_campaign')
CREATE TYPE ad_platform AS ENUM ('x', 'instagram')
CREATE TYPE appeal_category AS ENUM (
        'non_delivery', 
        'not_as_described', 
        'damaged_item', 
        'seller_issue', 
        'buyer_issue', 
        'payment_issue',
        'other'
    )
CREATE TYPE appeal_status AS ENUM (
        'pending', 
        'under_review', 
        'approved', 
        'denied', 
        'escalated', 
        'withdrawn'
    )
CREATE TYPE battle_status AS ENUM (
  'idle',
  'waiting_for_opponent',
  'pending_locked',
  'countdown',
  'active',
  'ended',
  'cancelled'
)
CREATE TYPE bug_alert_category AS ENUM ('livekit', 'broadcast', 'auth', 'database', 'payment', 'chat', 'ui', 'performance', 'security', 'other')
CREATE TYPE bug_alert_severity AS ENUM ('critical', 'high', 'medium', 'low', 'info')
CREATE TYPE bug_alert_status AS ENUM ('active', 'acknowledged', 'resolved', 'dismissed')
CREATE TYPE court_case_status AS ENUM (
            'pending', 'scheduled', 'in_session', 'resolved', 'closed',
            'dismissed', 'warrant_issued', 'inactive', 'appealed',
            'waiting', 'adjourned', 'summoned'
        )
CREATE TYPE public.agency_application_status AS ENUM ('pending', 'approved', 'rejected')
CREATE TYPE public.agency_member_role AS ENUM ('creator', 'leader', 'manager')
CREATE TYPE public.agency_reward_status AS ENUM ('pending', 'available', 'claimed', 'expired', 'revoked')
CREATE TYPE public.agency_reward_type AS ENUM ('bonus_coins', 'badge', 'exclusive_access', 'custom_role', 'merchandise', 'cash_payout', 'tier_milestone')
CREATE TYPE public.agency_tier AS ENUM ('none', 'bronze', 'silver', 'gold', 'legend')
CREATE TYPE public.agency_transaction_type AS ENUM ('stream_hours', 'platform_share', 'verified_viewer', 'user_registration', 'tier_bonus', 'admin_adjustment', 'reward_redemption')
CREATE TYPE public.payout_batch_status AS ENUM ('open', 'locked', 'processing', 'completed', 'cancelled')
CREATE TYPE public.task_cadence AS ENUM ('daily', 'weekly', 'monthly')
CREATE TYPE public.task_metric_type AS ENUM (
            'live_minutes',
            'live_sessions',
            'chat_messages',
            'unique_gifters',
            'returning_gifters',
            'no_strikes',
            'no_fraud'
        )
CREATE TYPE public.task_metric_type AS ENUM (
            'live_minutes',
            'live_sessions',
            'chat_messages',
            'unique_gifters',
            'returning_gifters',
            'no_strikes',
            'no_fraud',
            'gifts_sent',
            'gifts_received',
            'posts_made',
            'shares',
            'battles_won'
        )
CREATE TYPE tracking_event_status AS ENUM (
        'label_created', 
        'accepted', 
        'in_transit', 
        'out_for_delivery', 
        'delivered', 
        'exception', 
        'returned'
    )

-- ==================== SEQUENCES ====================
CREATE SEQUENCE IF
CREATE SEQUENCE IF NOT EXISTS public.beta_feedback_public_seq
CREATE SEQUENCE IF NOT EXISTS public.zip_code_seq
CREATE SEQUENCE auction_lot_number_seq

-- ==================== TABLES ====================
-- Table: user_stats
CREATE TABLE IF NOT EXISTS public.user_stats (
    user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    xp_total BIGINT DEFAULT 0,
    level INT DEFAULT 1,
    xp_to_next_level BIGINT DEFAULT 100,
    xp_progress FLOAT DEFAULT 0,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: support_tickets
CREATE TABLE IF NOT EXISTS public.support_tickets (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    username text,
    email text,
    category text NOT NULL DEFAULT 'general',
    subject text NOT NULL,
    message text NOT NULL,
    status text NOT NULL DEFAULT 'open',
    priority text DEFAULT 'normal',
    created_at timestamptz NOT NULL DEFAULT now(),
    admin_response text,
    admin_id uuid REFERENCES auth.users(id),
    response_at timestamptz,
    resolved_at timestamptz,
    closed_at timestamptz
);

-- Table: mobile_error_logs
CREATE TABLE IF NOT EXISTS public.mobile_error_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    error_message TEXT NOT NULL,
    stack_trace TEXT,
    device_info JSONB DEFAULT '{}'::jsonb,
    page_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: tournaments
CREATE TABLE IF NOT EXISTS public.tournaments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  subtitle TEXT,
  status TEXT NOT NULL CHECK (status IN ('draft', 'upcoming', 'open', 'live', 'ended')),
  season INTEGER DEFAULT 1,
  start_at TIMESTAMPTZ NOT NULL,
  end_at TIMESTAMPTZ,
  prize_pool TEXT,
  rules TEXT,
  description TEXT,
  max_participants INTEGER,
  entry_fee INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: tournament_participants
CREATE TABLE IF NOT EXISTS public.tournament_participants (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  tournament_id UUID NOT NULL REFERENCES public.tournaments(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'eliminated', 'withdrawn', 'winner')),
  joined_at TIMESTAMPTZ DEFAULT NOW(),
  points INTEGER DEFAULT 0,
  score INTEGER DEFAULT 0,
  rank INTEGER,
  stats JSONB DEFAULT '{}'::jsonb,
  UNIQUE(tournament_id, user_id)
);

-- Table: stream_messages
CREATE TABLE IF NOT EXISTS public.stream_messages (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  stream_id UUID REFERENCES public.streams(id) ON DELETE CASCADE NOT NULL,
  user_id UUID REFERENCES auth.users(id) NOT NULL,
  content TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: gifts
CREATE TABLE IF NOT EXISTS public.gifts (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name TEXT NOT NULL,
    icon_url TEXT DEFAULT '🎁',
    animation_url TEXT,
    cost INTEGER DEFAULT 0 NOT NULL,
    category TEXT NOT NULL,
    rarity TEXT DEFAULT 'common',
    class TEXT,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: stream_gifts
CREATE TABLE IF NOT EXISTS public.stream_gifts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    stream_id UUID REFERENCES public.streams(id) ON DELETE CASCADE,
    sender_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
    receiver_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
    gift_id TEXT,
    quantity INTEGER,
    metadata JSONB,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: stream_moderators
CREATE TABLE IF NOT EXISTS public.stream_moderators (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  broadcaster_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, -- The broadcaster who appointed them
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, -- The moderator
  created_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(broadcaster_id, user_id)
);

-- Table: stream_bans
CREATE TABLE IF NOT EXISTS public.stream_bans (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    stream_id UUID REFERENCES public.streams(id) ON DELETE CASCADE,
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    banned_by UUID REFERENCES public.users(id) ON DELETE SET NULL,
    reason TEXT,
    banned_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ
);

-- Table: stream_mutes
CREATE TABLE IF NOT EXISTS public.stream_mutes (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  stream_id UUID REFERENCES public.streams(id) ON DELETE CASCADE,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(stream_id, user_id)
);

-- Table: battles
CREATE TABLE IF NOT EXISTS public.battles (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  challenger_stream_id UUID REFERENCES public.streams(id) NOT NULL,
  opponent_stream_id UUID REFERENCES public.streams(id) NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'ended')),
  winner_stream_id UUID REFERENCES public.streams(id),
  score_challenger INTEGER DEFAULT 0,
  score_opponent INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT now(),
  started_at TIMESTAMPTZ,
  ended_at TIMESTAMPTZ
);

-- Table: conversations
CREATE TABLE IF NOT EXISTS public.conversations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    created_by UUID REFERENCES auth.users(id)
);

-- Table: conversation_members
CREATE TABLE IF NOT EXISTS public.conversation_members (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id UUID REFERENCES public.conversations(id) ON DELETE CASCADE,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    joined_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(conversation_id, user_id)
);

-- Table: conversation_messages
CREATE TABLE IF NOT EXISTS public.conversation_messages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    conversation_id UUID REFERENCES public.conversations(id) ON DELETE CASCADE,
    sender_id UUID REFERENCES auth.users(id),
    body TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    read_at TIMESTAMPTZ
);

-- Table: saved_streams
CREATE TABLE IF NOT EXISTS public.saved_streams (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    stream_id UUID NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
    saved_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    source TEXT DEFAULT 'manual', -- 'manual' | 'auto_stream_end' | 'auto_summary'
    UNIQUE(user_id, stream_id)
);

-- Table: troll_court_evidence
CREATE TABLE IF NOT EXISTS public.troll_court_evidence (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    stream_id UUID NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
    saved_by UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    saved_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    case_title TEXT,
    case_description TEXT,
    evidence_type TEXT DEFAULT 'broadcast', -- 'broadcast', 'chat', 'gift', 'stream_messages'
    video_url TEXT, -- direct recording URL (from streams.recording_url)
    metadata JSONB DEFAULT '{}', -- additional data (duration, viewer_count, category, etc.)
    is_active BOOLEAN DEFAULT true,
    CONSTRAINT unique_stream_evidence UNIQUE (stream_id, saved_by)
);

-- Table: auction_watchlist
CREATE TABLE IF NOT EXISTS public.auction_watchlist (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    auction_show_id UUID NOT NULL REFERENCES public.auction_shows(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(user_id, auction_show_id)
);

-- Table: coin_orders
CREATE TABLE public.coin_orders (
      id uuid primary key default gen_random_uuid(),
      user_id uuid not null references auth.users(id) on delete cascade,
      package_id uuid,
      coins integer not null,
      amount_cents integer not null,
      status text not null default 'created',
      stripe_checkout_session_id text not null,
      stripe_payment_intent_id text,
      paid_at timestamp with time zone,
      fulfilled_at timestamp with time zone,
      created_at timestamp with time zone not null default now(),
      updated_at timestamp with time zone not null default now(),
      constraint coin_orders_status_check check (status in ('created', 'paid', 'fulfilled', 'canceled', 'failed'))
    );

-- Table: stripe_customers
create table if not exists public.stripe_customers (
  user_id uuid primary key references auth.users(id) on delete cascade,
  stripe_customer_id text not null,
  created_at timestamp with time zone not null default now()
);

-- Table: manual_coin_orders
CREATE TABLE IF NOT EXISTS public.manual_coin_orders (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid REFERENCES public.user_profiles(id),
    package_id text NOT NULL,
    amount int NOT NULL,
    price text NOT NULL,
    payment_method text NOT NULL, -- 'cashapp'
    status text DEFAULT 'pending', -- 'pending', 'approved', 'rejected'
    created_at timestamptz DEFAULT now(),
    processed_at timestamptz,
    processed_by uuid REFERENCES public.user_profiles(id)
);

-- Table: coin_ledger
CREATE TABLE IF NOT EXISTS public.coin_ledger (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    delta bigint NOT NULL, -- can be positive or negative
    bucket text NOT NULL, -- 'paid', 'gifted', 'promo', 'loan', 'repayment'
    source text NOT NULL, -- 'coin_purchase', 'gift', 'admin_grant', 'loan_disbursement', 'auto_repay'
    ref_id text, -- external reference ID (e.g. stripe payment id)
    created_at timestamptz DEFAULT now()
);

-- Table: admin_pool_ledger
CREATE TABLE IF NOT EXISTS public.admin_pool_ledger (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  amount NUMERIC(18,3) NOT NULL,
  reason TEXT NOT NULL,
  ref_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: user_event_dismissals
create table if not exists user_event_dismissals (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references vote_events(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (event_id, user_id)
);

-- Table: officer_time_off_requests
create table if not exists officer_time_off_requests (
  id uuid primary key default gen_random_uuid(),
  officer_id uuid not null references user_profiles(id) on delete cascade,
  date date not null,
  reason text,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  reviewed_by uuid references user_profiles(id),
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);

-- Table: loans
CREATE TABLE IF NOT EXISTS public.loans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid REFERENCES auth.users(id),
  principal numeric NOT NULL,
  balance numeric NOT NULL,
  interest_rate numeric DEFAULT 0,
  status text CHECK (status IN ('active','paid','late','defaulted')),
  created_at timestamptz DEFAULT now(),
  due_date timestamptz
);

-- Table: loan_applications
CREATE TABLE IF NOT EXISTS public.loan_applications (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    requested_coins bigint NOT NULL,
    status text NOT NULL DEFAULT 'pending', -- 'approved', 'denied', 'pending'
    auto_approved boolean DEFAULT false,
    reason text,
    created_at timestamptz DEFAULT now()
);

-- Table: bank_tiers
CREATE TABLE IF NOT EXISTS public.bank_tiers (
    id serial PRIMARY KEY,
    tier_name text NOT NULL,
    min_tenure_days int NOT NULL DEFAULT 0,
    max_loan_coins bigint NOT NULL DEFAULT 0,
    created_at timestamptz DEFAULT now()
);

-- Table: family_tasks
CREATE TABLE IF NOT EXISTS public.family_tasks (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    family_id uuid NOT NULL REFERENCES public.troll_families(id) ON DELETE CASCADE,
    task_title text NOT NULL,
    task_description text,
    reward_family_coins integer DEFAULT 0,
    reward_family_xp integer DEFAULT 0,
    goal_value integer DEFAULT 1,
    current_value integer DEFAULT 0,
    metric text NOT NULL,
    status text DEFAULT 'active' CHECK (status IN ('active', 'completed', 'expired')),
    expires_at timestamptz,
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now()
);

-- Table: gift_ledger
CREATE TABLE IF NOT EXISTS public.gift_ledger (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sender_id UUID NOT NULL REFERENCES public.user_profiles(id),
    receiver_id UUID NOT NULL REFERENCES public.user_profiles(id),
    stream_id UUID, -- Optional, if associated with a stream
    gift_id TEXT NOT NULL, -- ID or Slug
    amount INTEGER NOT NULL, -- Cost in Coins
    metadata JSONB DEFAULT '{}'::jsonb,
    status TEXT NOT NULL DEFAULT 'pending', -- pending, processed, failed
    idempotency_key TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    processed_at TIMESTAMPTZ,
    error_message TEXT
);

-- Table: broadcaster_stats
CREATE TABLE IF NOT EXISTS public.broadcaster_stats (
    user_id UUID PRIMARY KEY REFERENCES public.user_profiles(id),
    total_gifts_24h INTEGER DEFAULT 0,
    total_gifts_all_time INTEGER DEFAULT 0,
    last_updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: vehicles_catalog
CREATE TABLE IF NOT EXISTS public.vehicles_catalog (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL UNIQUE,
    slug TEXT NOT NULL,
    model_url TEXT NOT NULL,
    price INTEGER NOT NULL DEFAULT 0,
    tier TEXT,
    style TEXT,
    speed INTEGER,
    armor INTEGER,
    color_from TEXT,
    color_to TEXT,
    image_url TEXT,
    overlay_video_url TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    CONSTRAINT vehicles_catalog_name_key UNIQUE(name),
    CONSTRAINT vehicles_catalog_model_url_key UNIQUE(model_url)
);

-- Table: user_vehicles
CREATE TABLE public.user_vehicles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    catalog_id INTEGER NOT NULL REFERENCES public.vehicles_catalog(id),
    purchased_at TIMESTAMPTZ DEFAULT NOW(),
    condition INTEGER DEFAULT 100, -- 0-100%
    mods JSONB DEFAULT '{}'::jsonb, -- Engine, Handling, Cosmetic upgrades
    is_impounded BOOLEAN DEFAULT FALSE,
    impounded_at TIMESTAMPTZ,
    impound_reason TEXT,
    CONSTRAINT condition_check CHECK (condition >= 0 AND condition <= 100)
);

-- Table: vehicle_loans
CREATE TABLE IF NOT EXISTS public.vehicle_loans (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id),
    vehicle_id UUID NOT NULL REFERENCES public.user_vehicles(id) ON DELETE CASCADE,
    total_amount INTEGER NOT NULL,
    remaining_amount INTEGER NOT NULL,
    monthly_payment INTEGER NOT NULL,
    interest_rate NUMERIC DEFAULT 0.05,
    next_payment_due_at TIMESTAMPTZ,
    last_payment_at TIMESTAMPTZ,
    missed_payments INTEGER DEFAULT 0,
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'paid', 'defaulted', 'repo')),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: user_driver_licenses
CREATE TABLE IF NOT EXISTS public.user_driver_licenses (
    user_id UUID PRIMARY KEY REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    status TEXT DEFAULT 'none',
    suspended_until TIMESTAMPTZ,
    points INTEGER DEFAULT 0,
    issued_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: vehicle_listings
CREATE TABLE IF NOT EXISTS vehicle_listings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  seller_id UUID NOT NULL REFERENCES user_profiles(id),
  vehicle_id INTEGER NOT NULL,
  listing_type TEXT NOT NULL CHECK (listing_type IN ('sale', 'auction')),
  price INTEGER NOT NULL CHECK (price >= 0),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'sold', 'cancelled', 'expired')),
  metadata JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: system_roles
create table if not exists system_roles (
  id uuid primary key default gen_random_uuid(),
  name text unique not null,
  hierarchy_rank int not null default 0,
  is_staff boolean default false,
  is_admin boolean default false,
  description text,
  created_at timestamptz default now()
);

-- Table: user_role_grants
create table if not exists user_role_grants (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references user_profiles(id) on delete cascade,
  role_id uuid references system_roles(id) on delete cascade,
  granted_by uuid references user_profiles(id),
  created_at timestamptz default now(),
  expires_at timestamptz,
  unique(user_id, role_id)
);

-- Table: president_proposals
create table if not exists president_proposals (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text not null,
  type text not null check (type in ('tax', 'event', 'challenge', 'giveaway', 'other')),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'expired')),
  created_by uuid references user_profiles(id),
  created_at timestamptz not null default now(),
  reviewed_by uuid references user_profiles(id),
  reviewed_at timestamptz,
  review_note text,
  metadata jsonb default '{}'::jsonb
);

-- Table: president_audit_logs
create table if not exists president_audit_logs (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references user_profiles(id),
  action text not null,
  target_id uuid, -- Optional target (user, proposal, etc.)
  details jsonb default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- Table: houses_catalog
CREATE TABLE IF NOT EXISTS public.houses_catalog (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    tier INT NOT NULL CHECK (tier BETWEEN 1 AND 5),
    base_price BIGINT NOT NULL,
    rent_slots INT NOT NULL DEFAULT 0,
    power_band TEXT NOT NULL, -- apartment/condo/estate/mansion/landmark
    daily_tax_rate_bps INT NOT NULL DEFAULT 0,
    maintenance_rate_bps INT NOT NULL DEFAULT 0,
    influence_points INT NOT NULL DEFAULT 0,
    feature_flags JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: user_houses
CREATE TABLE IF NOT EXISTS public.user_houses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    house_catalog_id UUID NOT NULL REFERENCES public.houses_catalog(id),
    purchase_price BIGINT NOT NULL DEFAULT 0,
    condition INT DEFAULT 100 CHECK (condition BETWEEN 0 AND 100),
    is_primary BOOL DEFAULT false,
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'delinquent', 'foreclosed', 'auctioned')),
    last_tax_paid_at TIMESTAMPTZ,
    last_maintenance_paid_at TIMESTAMPTZ,
    next_due_at TIMESTAMPTZ,
    influence_active BOOL DEFAULT true,
    feature_flags JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: house_upgrades
CREATE TABLE IF NOT EXISTS public.house_upgrades (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    house_catalog_id UUID REFERENCES public.houses_catalog(id),
    name TEXT NOT NULL,
    price BIGINT NOT NULL,
    effects JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: house_rentals
CREATE TABLE IF NOT EXISTS public.house_rentals (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    landlord_user_id UUID NOT NULL REFERENCES auth.users(id),
    tenant_user_id UUID NOT NULL REFERENCES auth.users(id),
    user_house_id UUID NOT NULL REFERENCES public.user_houses(id),
    rent_amount BIGINT NOT NULL,
    platform_fee_bps INT DEFAULT 1000,
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'late', 'ended', 'evicted')),
    last_paid_at TIMESTAMPTZ,
    next_due_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: car_upgrades
CREATE TABLE IF NOT EXISTS public.car_upgrades (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    description TEXT,
    cost_coins INTEGER NOT NULL,
    value_increase_amount INTEGER NOT NULL, -- How much it adds to car value
    category TEXT NOT NULL, -- 'engine', 'body', 'paint', etc.
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: auction_bids
CREATE TABLE IF NOT EXISTS public.auction_bids (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    auction_id UUID NOT NULL REFERENCES public.asset_auctions(id) ON DELETE CASCADE,
    bidder_user_id UUID NOT NULL REFERENCES auth.users(id),
    amount BIGINT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: house_upgrades_catalog
CREATE TABLE IF NOT EXISTS house_upgrades_catalog (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  description TEXT,
  base_price BIGINT NOT NULL,
  effects JSONB NOT NULL DEFAULT '{}'::jsonb, -- e.g. {"rent_slots_add": 2, "tax_discount_bps": 500}
  icon_name TEXT DEFAULT 'Wrench',
  max_per_house INTEGER DEFAULT 1,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: house_installations
CREATE TABLE IF NOT EXISTS house_installations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_house_id UUID NOT NULL REFERENCES user_houses(id) ON DELETE CASCADE,
  upgrade_id UUID NOT NULL REFERENCES house_upgrades_catalog(id),
  installed_at TIMESTAMPTZ DEFAULT NOW(),
  
  -- Prevent exceeding max_per_house
  -- (This is complex to enforce strictly in pure SQL constraint without a trigger, 
  --  so we'll rely on the purchase RPC for enforcement, but add a unique constraint for the common case of max=1)
  CONSTRAINT unique_upgrade_per_house UNIQUE (user_house_id, upgrade_id)
);

-- Table: battle_participants
CREATE TABLE IF NOT EXISTS public.battle_participants (
    battle_id UUID NOT NULL REFERENCES public.battles(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    team TEXT NOT NULL CHECK (team IN ('challenger', 'opponent')),
    role TEXT NOT NULL CHECK (role IN ('host', 'stage', 'viewer')),
    source_stream_id UUID NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
    seat_index INTEGER,
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    PRIMARY KEY (battle_id, user_id)
);

-- Table: signup_queue
CREATE TABLE public.signup_queue (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email TEXT NOT NULL,
  username TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  notified BOOLEAN DEFAULT false
);

-- Table: task_seasons
CREATE TABLE IF NOT EXISTS public.task_seasons (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    is_active BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT valid_dates CHECK (end_date > start_date)
);

-- Table: task_templates
CREATE TABLE IF NOT EXISTS public.task_templates (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    metric task_metric_type NOT NULL,
    cadence task_cadence NOT NULL,
    default_threshold INTEGER NOT NULL,
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: season_tasks
CREATE TABLE IF NOT EXISTS public.season_tasks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    season_id UUID NOT NULL REFERENCES public.task_seasons(id) ON DELETE CASCADE,
    template_id UUID NOT NULL REFERENCES public.task_templates(id),
    threshold INTEGER NOT NULL,
    bonus_points INTEGER DEFAULT 0, -- Extra weight if we want multi-level bonuses later
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: payout_batches
CREATE TABLE IF NOT EXISTS public.payout_batches (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    week_start DATE NOT NULL, -- Usually Monday
    week_end DATE NOT NULL,   -- Usually Sunday
    payout_date DATE NOT NULL, -- The Friday of that week
    status payout_batch_status DEFAULT 'open',
    total_amount BIGINT DEFAULT 0,
    request_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: creator_goal_boost
CREATE TABLE IF NOT EXISTS public.creator_goal_boost (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    batch_id UUID REFERENCES public.payout_batches(id),
    help_text TEXT,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: troll_wall_post_shares
CREATE TABLE IF NOT EXISTS public.troll_wall_post_shares (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    post_id UUID NOT NULL REFERENCES public.troll_wall_posts(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: broadcast_pinned_products
CREATE TABLE IF NOT EXISTS public.broadcast_pinned_products (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    stream_id UUID NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
    product_id UUID NOT NULL REFERENCES public.shop_items(id) ON DELETE CASCADE,
    pinned_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    pinned_at TIMESTAMPTZ DEFAULT now(),
    is_active BOOLEAN DEFAULT true,
    position INTEGER DEFAULT 1
);

-- Table: shop_orders
CREATE TABLE IF NOT EXISTS public.shop_orders (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    order_number TEXT UNIQUE NOT NULL,
    buyer_id UUID NOT NULL REFERENCES public.profiles(id),
    seller_id UUID NOT NULL REFERENCES public.profiles(id),
    shop_id UUID NOT NULL REFERENCES public.Mai Troll_shops(id),
    
    -- Order Status
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN (
        'pending', 'paid', 'processing', 'shipped', 'delivered', 'completed', 'cancelled', 'refunded'
    )),
    
    -- Pricing
    subtotal INTEGER NOT NULL, -- in coins
    shipping_cost INTEGER DEFAULT 0,
    total_coins INTEGER NOT NULL,
    
    -- Escrow Status
    escrow_status TEXT NOT NULL DEFAULT 'pending' CHECK (escrow_status IN (
        'pending', 'held', 'released', 'refunded'
    )),
    escrow_released_at TIMESTAMPTZ,
    
    -- Shipping
    shipping_name TEXT,
    shipping_address TEXT,
    shipping_city TEXT,
    shipping_state TEXT,
    shipping_zip TEXT,
    shipping_country TEXT DEFAULT 'US',
    tracking_number TEXT,
    carrier TEXT CHECK (carrier IN ('usps', 'ups', 'fedex', 'dhl', 'other')),
    tracking_url TEXT,
    shipped_at TIMESTAMPTZ,
    delivered_at TIMESTAMPTZ,
    estimated_delivery DATE,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    paid_at TIMESTAMPTZ,
    completed_at TIMESTAMPTZ,
    
    -- Metadata
    notes TEXT,
    metadata JSONB DEFAULT '{}'
);

-- Table: transaction_appeals
CREATE TABLE IF NOT EXISTS public.transaction_appeals (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Appeal Reference
    appeal_number SERIAL,
    appeal_token UUID DEFAULT gen_random_uuid(),
    
    -- User who filed the appeal
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE NOT NULL,
    
    -- Related Transaction/Order
    order_id UUID,
    transaction_id UUID,
    shop_id UUID REFERENCES public.Mai Troll_shops(id) ON DELETE SET NULL,
    
    -- Appeal Details
    category appeal_category NOT NULL,
    description TEXT NOT NULL,
    evidence_urls TEXT[], -- Array of image URLs or document links
    desired_resolution TEXT, -- What the appellant wants (refund, replacement, etc.)
    
    -- Status Tracking
    status appeal_status DEFAULT 'pending' NOT NULL,
    
    -- Reviewer Info (Admin or Secretary)
    reviewer_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    reviewed_at TIMESTAMPTZ,
    review_notes TEXT,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    -- Related User (the other party in the transaction)
    related_user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    
    -- Coin amounts involved
    amount_in_dispute BIGINT DEFAULT 0,
    escrow_release_status TEXT DEFAULT 'pending', -- pending, released, refunded, held
    
    -- Constraint
    CONSTRAINT transaction_appeals_status_check CHECK (status IN ('pending', 'under_review', 'approved', 'denied', 'escalated', 'withdrawn'))
);

-- Table: appeal_weekly_limits
CREATE TABLE IF NOT EXISTS public.appeal_weekly_limits (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE NOT NULL,
    week_start_date DATE NOT NULL, -- Monday of the week
    appeals_filed INTEGER DEFAULT 0,
    max_appeals INTEGER DEFAULT 5,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    
    UNIQUE(user_id, week_start_date)
);

-- Table: appeal_actions
CREATE TABLE IF NOT EXISTS public.appeal_actions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    appeal_id UUID REFERENCES public.transaction_appeals(id) ON DELETE CASCADE NOT NULL,
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL, -- Who took the action
    action_type TEXT NOT NULL, -- created, status_changed, evidence_added, note_added, etc.
    previous_status TEXT,
    new_status TEXT,
    notes TEXT,
    metadata JSONB DEFAULT '{}',
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: global_events
CREATE TABLE IF NOT EXISTS public.global_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    type TEXT NOT NULL,
    title TEXT NOT NULL,
    icon TEXT,
    priority INTEGER DEFAULT 1,
    metadata JSONB,
    created_at timestamptz DEFAULT now()
);

-- Table: gifts_catalog
CREATE TABLE IF NOT EXISTS gifts_catalog (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    description TEXT,
    price INTEGER NOT NULL DEFAULT 10,
    model_url TEXT,
    thumbnail_url TEXT,
    rarity TEXT NOT NULL DEFAULT 'common' CHECK (rarity IN ('common', 'uncommon', 'rare', 'epic', 'legendary', 'mythic')),
    animation_type TEXT NOT NULL DEFAULT 'float' CHECK (animation_type IN ('float', 'spin', 'burst', 'drop', 'orbit', 'spotlight', 'fireworks')),
    duration INTEGER NOT NULL DEFAULT 3000,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    is_active BOOLEAN DEFAULT true
);

-- Table: gift_transactions
CREATE TABLE IF NOT EXISTS gift_transactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sender_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    receiver_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    gift_id UUID NOT NULL REFERENCES gifts_catalog(id) ON DELETE RESTRICT,
    session_id UUID,
    coins_spent INTEGER NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: stream_audio_monitoring
CREATE TABLE IF NOT EXISTS stream_audio_monitoring (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    stream_id UUID REFERENCES streams(id) ON DELETE CASCADE,
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    is_monitored BOOLEAN DEFAULT true,
    monitoring_started_at TIMESTAMP DEFAULT NOW(),
    monitoring_ended_at TIMESTAMP,
    total_triggers INTEGER DEFAULT 0,
    last_trigger_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT NOW(),
    updated_at TIMESTAMP DEFAULT NOW()
);

-- Table: family_chat_messages
CREATE TABLE IF NOT EXISTS public.family_chat_messages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    family_id UUID NOT NULL REFERENCES public.troll_families(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    message TEXT NOT NULL,
    message_type VARCHAR(20) NOT NULL DEFAULT 'text' CHECK (message_type IN ('text', 'system', 'call')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ
);

-- Table: family_calls
CREATE TABLE IF NOT EXISTS public.family_calls (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    family_id UUID NOT NULL REFERENCES public.troll_families(id) ON DELETE CASCADE,
    type VARCHAR(20) NOT NULL DEFAULT 'voice' CHECK (type IN ('voice', 'video')),
    created_by UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    is_active BOOLEAN NOT NULL DEFAULT true,
    max_participants INTEGER DEFAULT 8,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ended_at TIMESTAMPTZ
);

-- Table: family_call_members
CREATE TABLE IF NOT EXISTS public.family_call_members (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    call_id UUID NOT NULL REFERENCES public.family_calls(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    left_at TIMESTAMPTZ,
    is_speaking BOOLEAN DEFAULT false,
    is_muted BOOLEAN DEFAULT false,
    is_video_on BOOLEAN DEFAULT false,
    
    -- Unique constraint: user can only be in one active call at a time per family
    UNIQUE(call_id, user_id)
);

-- Table: rtc_sessions
CREATE TABLE IF NOT EXISTS rtc_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  room_name TEXT NOT NULL,
  started_at TIMESTAMPTZ DEFAULT NOW(),
  ended_at TIMESTAMPTZ,
  duration_seconds INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: stream_missions
CREATE TABLE IF NOT EXISTS stream_missions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  mission_template_id UUID REFERENCES mission_templates(id),
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  mission_type TEXT NOT NULL CHECK (mission_type IN ('solo', 'community', 'competitive', 'timed')),
  target_metric TEXT NOT NULL,
  target_value INTEGER NOT NULL,
  current_value INTEGER DEFAULT 0,
  difficulty TEXT NOT NULL DEFAULT 'normal',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'failed', 'expired', 'chained')),
  chain_group TEXT,
  chain_order INTEGER DEFAULT 0,
  starts_at TIMESTAMPTZ DEFAULT now(),
  expires_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  xp_reward INTEGER DEFAULT 0,
  coin_reward INTEGER DEFAULT 0,
  icon TEXT DEFAULT '🎯',
  metadata JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: user_entrance_audio
CREATE TABLE IF NOT EXISTS user_entrance_audio (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  audio_url TEXT NOT NULL,
  audio_name TEXT DEFAULT 'My Entrance',
  duration_seconds REAL NOT NULL CHECK (duration_seconds >= 1 AND duration_seconds <= 6),
  file_size_bytes INTEGER,
  is_active BOOLEAN DEFAULT false,
  is_approved BOOLEAN DEFAULT true, -- moderation
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: broadcast_audio_settings
CREATE TABLE IF NOT EXISTS broadcast_audio_settings (
  stream_id UUID PRIMARY KEY REFERENCES streams(id) ON DELETE CASCADE,
  voice_enabled BOOLEAN DEFAULT true,
  custom_audio_enabled BOOLEAN DEFAULT true,
  min_level_for_voice INTEGER DEFAULT 200,
  min_level_for_custom INTEGER DEFAULT 200,
  cooldown_seconds INTEGER DEFAULT 5,
  max_queue_size INTEGER DEFAULT 10,
  stream_mode TEXT DEFAULT 'standard' CHECK (stream_mode IN ('silent', 'standard', 'premium', 'hype')),
  muted_users UUID[] DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: stream_fan_tiers
CREATE TABLE IF NOT EXISTS stream_fan_tiers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  tier TEXT NOT NULL DEFAULT 'viewer' CHECK (tier IN ('viewer', 'supporter', 'fan', 'superfan', 'legend', 'icon')),
  total_coins_gifted INTEGER DEFAULT 0,
  total_messages INTEGER DEFAULT 0,
  watch_minutes INTEGER DEFAULT 0,
  hype_score INTEGER DEFAULT 0,
  role TEXT DEFAULT NULL, -- hype_leader, judge, co_host, etc.
  contract_active BOOLEAN DEFAULT false,
  contract_started_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(stream_id, user_id)
);

-- Table: stream_energy_meter
CREATE TABLE IF NOT EXISTS stream_energy_meter (
  stream_id UUID PRIMARY KEY REFERENCES streams(id) ON DELETE CASCADE,
  energy_level INTEGER DEFAULT 0 CHECK (energy_level >= 0 AND energy_level <= 100),
  hype_multiplier REAL DEFAULT 1.0,
  last_boost_at TIMESTAMPTZ,
  total_boosts INTEGER DEFAULT 0,
  peak_energy INTEGER DEFAULT 0,
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: stream_awards
CREATE TABLE IF NOT EXISTS stream_awards (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  award_type TEXT NOT NULL, -- mvp, top_gifter, most_active, hype_king, loyal_viewer, rising_star
  user_id UUID NOT NULL REFERENCES auth.users(id),
  title TEXT NOT NULL,
  description TEXT,
  xp_reward INTEGER DEFAULT 0,
  coin_reward INTEGER DEFAULT 0,
  badge_awarded TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: fan_contracts
CREATE TABLE IF NOT EXISTS fan_contracts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  broadcaster_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  fan_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  stream_id UUID REFERENCES streams(id) ON DELETE CASCADE,
  contract_type TEXT NOT NULL DEFAULT 'standard', -- standard, premium, exclusive
  perks JSONB DEFAULT '{}',
  is_active BOOLEAN DEFAULT true,
  started_at TIMESTAMPTZ DEFAULT now(),
  expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: stream_goals
CREATE TABLE IF NOT EXISTS stream_goals (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  goal_type TEXT NOT NULL CHECK (goal_type IN ('coins', 'followers', 'shares', 'subscriptions', 'gifts', 'viewers')),
  title TEXT NOT NULL,
  target_value INTEGER NOT NULL,
  current_value INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT true,
  completed_at TIMESTAMPTZ,
  reward_description TEXT,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: stream_milestones
CREATE TABLE IF NOT EXISTS stream_milestones (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  milestone_type TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  threshold INTEGER NOT NULL,
  is_unlocked BOOLEAN DEFAULT false,
  unlocked_at TIMESTAMPTZ,
  icon TEXT DEFAULT '🏆',
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: stream_polls
CREATE TABLE IF NOT EXISTS stream_polls (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  question TEXT NOT NULL,
  options JSONB NOT NULL, -- [{label: 'A', votes: 0}, {label: 'B', votes: 0}]
  is_active BOOLEAN DEFAULT true,
  total_votes INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT now(),
  expires_at TIMESTAMPTZ,
  created_by UUID REFERENCES auth.users(id)
);

-- Table: order_shipments
CREATE TABLE IF NOT EXISTS order_shipments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid REFERENCES marketplace_purchases(id) ON DELETE CASCADE NOT NULL,
  
  -- Carrier info
  carrier text NOT NULL CHECK (carrier IN ('usps', 'ups', 'fedex', 'dhl', 'other')),
  tracking_number text NOT NULL,
  tracking_url text,
  
  -- Internal status tracking
  tracking_status text DEFAULT 'pending' 
    CHECK (tracking_status IN ('pending', 'label_created', 'accepted', 'in_transit', 'out_for_delivery', 'delivered', 'exception', 'returned')),
  
  -- Carrier's raw status
  carrier_status text,
  carrier_error text,
  
  -- Timestamps
  shipped_date timestamptz,
  delivered_at timestamptz,
  tracking_last_updated_at timestamptz DEFAULT now(),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  
  -- Optional: reference to external tracking API response
  external_tracking_data jsonb,
  
  UNIQUE(order_id)
);

-- Table: tracking_events
CREATE TABLE IF NOT EXISTS tracking_events (
  id uuid primary key default gen_random_uuid(),
  shipment_id uuid REFERENCES order_shipments(id) ON DELETE CASCADE NOT NULL,
  
  -- External event ID from carrier
  external_event_id text,
  
  -- Normalized status
  status text NOT NULL 
    CHECK (status IN ('label_created', 'accepted', 'in_transit', 'out_for_delivery', 'delivered', 'exception', 'returned')),
  
  -- Event details
  description text,
  location text,
  city text,
  state text,
  country text,
  zip_code text,
  
  -- Timestamps
  event_time timestamptz NOT NULL,
  created_at timestamptz DEFAULT now(),
  
  -- Raw carrier data for debugging
  raw_data jsonb
);

-- Table: stream_seats
CREATE TABLE IF NOT EXISTS public.stream_seats (
  stream_id TEXT REFERENCES streams(id) ON DELETE CASCADE,
  seat_index SMALLINT NOT NULL,
  user_id UUID REFERENCES user_profiles(id) ON DELETE SET NULL,
  is_active BOOLEAN DEFAULT false,
  joined_at TIMESTAMPTZ DEFAULT NOW(),
  PRIMARY KEY (stream_id, seat_index)
);

-- Table: games
CREATE TABLE IF NOT EXISTS games (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    type VARCHAR(50) NOT NULL DEFAULT 'troll_us',
    status VARCHAR(50) NOT NULL DEFAULT 'lobby', -- lobby, live, ended
    host_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    stream_id UUID REFERENCES streams(id) ON DELETE CASCADE,
    current_round INTEGER DEFAULT 0,
    prize_pool INTEGER DEFAULT 2000,
    winner_team VARCHAR(20),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    started_at TIMESTAMPTZ,
    ended_at TIMESTAMPTZ
);

-- Table: game_players
CREATE TABLE IF NOT EXISTS game_players (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    game_id UUID NOT NULL REFERENCES games(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    seat_index INTEGER,
    role VARCHAR(20), -- troll, hunter (hidden from other players)
    is_eliminated BOOLEAN DEFAULT FALSE,
    is_seated BOOLEAN DEFAULT FALSE,
    is_muted BOOLEAN DEFAULT FALSE,
    is_alive BOOLEAN DEFAULT TRUE,
    has_voted BOOLEAN DEFAULT FALSE,
    votes_received INTEGER DEFAULT 0,
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(game_id, user_id)
);

-- Table: connected_social_accounts
CREATE TABLE IF NOT EXISTS connected_social_accounts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  platform VARCHAR(20) NOT NULL CHECK (platform IN ('x', 'instagram')),
  platform_user_id VARCHAR(255) NOT NULL,
  platform_username VARCHAR(255),
  platform_display_name VARCHAR(255),
  access_token_encrypted TEXT,
  refresh_token_encrypted TEXT,
  token_expires_at TIMESTAMPTZ,
  account_status VARCHAR(20) DEFAULT 'active' CHECK (account_status IN ('active', 'disconnected', 'expired', 'error')),
  last_synced_at TIMESTAMPTZ,
  permissions JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, platform)
);

-- Table: source_content_refs
CREATE TABLE IF NOT EXISTS source_content_refs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  content_type VARCHAR(50) NOT NULL,
  content_id VARCHAR(255),
  title VARCHAR(500),
  description TEXT,
  url TEXT,
  screenshot_url TEXT,
  thumbnail_url TEXT,
  stats JSONB DEFAULT '{}',
  cta_text VARCHAR(255),
  captured_at TIMESTAMPTZ DEFAULT NOW(),
  created_by UUID REFERENCES auth.users(id)
);

-- Table: ad_generation_jobs
CREATE TABLE IF NOT EXISTS ad_generation_jobs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source_content_id UUID REFERENCES source_content_refs(id),
  job_type VARCHAR(50) NOT NULL CHECK (job_type IN ('image_ad', 'video_promo', 'caption_only', 'full_campaign')),
  job_status VARCHAR(20) DEFAULT 'pending' CHECK (job_status IN ('pending', 'processing', 'completed', 'failed', 'cancelled')),
  template_type VARCHAR(50),
  requested_by UUID REFERENCES auth.users(id),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  error_message TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ad_assets
CREATE TABLE IF NOT EXISTS ad_assets (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id UUID REFERENCES ad_generation_jobs(id),
  asset_type VARCHAR(30) NOT NULL CHECK (asset_type IN ('square_post', 'portrait_story', 'landscape_promo', 'fallback_graphic')),
  file_path TEXT,
  public_url TEXT,
  width INTEGER,
  height INTEGER,
  file_size INTEGER,
  format VARCHAR(20),
  metadata JSONB DEFAULT '{}',
  is_primary BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: ad_videos
CREATE TABLE IF NOT EXISTS ad_videos (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id UUID REFERENCES ad_generation_jobs(id),
  template_type VARCHAR(50) CHECK (template_type IN ('feature_promo', 'live_now_promo', 'event_promo', 'government_promo', 'careers_promo', 'wallet_promo', '3_scene', 'slideshow', 'feature_reveal', 'vertical_reel')),
  file_path TEXT,
  public_url TEXT,
  duration_seconds INTEGER,
  width INTEGER,
  height INTEGER,
  file_size INTEGER,
  format VARCHAR(20),
  metadata JSONB DEFAULT '{}',
  has_audio BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: caption_variants
CREATE TABLE IF NOT EXISTS caption_variants (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  job_id UUID REFERENCES ad_generation_jobs(id),
  caption_style VARCHAR(30) NOT NULL CHECK (caption_style IN ('aggressive', 'clean', 'hype', 'founder', 'short_promo')),
  caption_text TEXT NOT NULL,
  hashtags TEXT,
  mentions TEXT,
  cta_text VARCHAR(255),
  cta_url TEXT,
  is_selected BOOLEAN DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: social_publish_queue
CREATE TABLE IF NOT EXISTS social_publish_queue (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id UUID,
  video_id UUID,
  caption_id UUID REFERENCES caption_variants(id),
  platform VARCHAR(20) NOT NULL CHECK (platform IN ('x', 'instagram')),
  account_id UUID REFERENCES connected_social_accounts(id),
  publish_status VARCHAR(20) DEFAULT 'draft' CHECK (publish_status IN ('draft', 'scheduled', 'publishing', 'published', 'failed', 'archived')),
  scheduled_at TIMESTAMPTZ,
  published_at TIMESTAMPTZ,
  platform_post_id TEXT,
  platform_post_url TEXT,
  utm_params JSONB DEFAULT '{}',
  created_by UUID REFERENCES auth.users(id),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: chat_blocks
CREATE TABLE IF NOT EXISTS public.chat_blocks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  blocked_by uuid REFERENCES public.user_profiles(id),
  expires_at timestamptz NOT NULL,
  reason text,
  created_at timestamptz DEFAULT now()
);

-- Table: stream_kicks
CREATE TABLE IF NOT EXISTS public.stream_kicks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  kicked_by uuid REFERENCES public.user_profiles(id),
  created_by uuid REFERENCES public.user_profiles(id),
  reason text,
  created_at timestamptz DEFAULT now()
);

-- Table: broadcast_restrictions
CREATE TABLE IF NOT EXISTS broadcast_restrictions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
    restricted_by UUID REFERENCES user_profiles(id),
    reason TEXT,
    duration_minutes INTEGER NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: court_participants
CREATE TABLE IF NOT EXISTS public.court_participants (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    court_session_id UUID REFERENCES court_sessions(id) ON DELETE CASCADE,
    user_id UUID REFERENCES user_profiles(id) ON DELETE CASCADE,
    role TEXT DEFAULT 'observer' CHECK (role IN ('judge', 'prosecutor', 'defendant', 'attorney', 'witness', 'observer', 'bailiff', 'clerk')),
    box_number INTEGER, -- Which box they're in (null = not in a box)
    queue_position INTEGER, -- Position in queue (null = not in queue)
    is_hand_raised BOOLEAN DEFAULT false,
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: outbound_clicks
CREATE TABLE IF NOT EXISTS public.outbound_clicks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    url TEXT NOT NULL,
    clicked_at TIMESTAMPTZ DEFAULT NOW(),
    ip_address INET,
    user_agent TEXT,
    referrer TEXT
);

-- Table: houses
CREATE TABLE IF NOT EXISTS public.houses (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  neighborhood_id UUID REFERENCES public.neighborhoods(id) ON DELETE CASCADE,
  owner_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  upgrade_level INTEGER DEFAULT 1,
  condition INTEGER DEFAULT 100 CHECK (condition >= 0 AND condition <= 100),
  is_reposessed BOOLEAN DEFAULT FALSE,
  electric_on BOOLEAN DEFAULT FALSE,
  water_on BOOLEAN DEFAULT FALSE,
  internet_on BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: app_bug_reports
CREATE TABLE IF NOT EXISTS public.app_bug_reports (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  status text DEFAULT 'open',
  severity text DEFAULT 'medium',
  source text NOT NULL,
  page_url text,
  route_path text,
  user_id uuid NULL,
  user_email text NULL,
  user_role text NULL,
  stream_id uuid NULL,
  function_name text NULL,
  table_name text NULL,
  error_code text NULL,
  error_message text NOT NULL,
  error_details text NULL,
  error_hint text NULL,
  stack_trace text NULL,
  request_payload jsonb NULL,
  response_payload jsonb NULL,
  browser_info jsonb NULL,
  app_context jsonb NULL,
  fixed_note text NULL,
  fixed_by uuid NULL,
  fixed_at timestamptz NULL,
  occurrence_count integer DEFAULT 1,
  last_seen_at timestamptz DEFAULT now()
);

-- Table: subscription_tiers
CREATE TABLE IF NOT EXISTS subscription_tiers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL CHECK (LENGTH(name) <= 50),
    price_coins INTEGER NOT NULL CHECK (price_coins >= 0),
    benefits TEXT[] DEFAULT '{}',
    color_hex TEXT DEFAULT '#6B7280',
    icon_name TEXT DEFAULT 'Heart',
    is_active BOOLEAN DEFAULT true,
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    CONSTRAINT subscription_tiers_name_unique UNIQUE(name)
);

-- Table: user_subscriptions
CREATE TABLE IF NOT EXISTS user_subscriptions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    subscriber_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
    broadcaster_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
    tier_id UUID NOT NULL REFERENCES subscription_tiers(id),
    started_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    expires_at TIMESTAMP WITH TIME ZONE,
    is_active BOOLEAN DEFAULT true,
    auto_renew BOOLEAN DEFAULT true,
    total_paid_coins INTEGER NOT NULL DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    
    CONSTRAINT one_subscription_per_pair UNIQUE(subscriber_id, broadcaster_id),
    CONSTRAINT no_self_subscription CHECK (subscriber_id != broadcaster_id)
);

-- Table: subscription_revenue_log
CREATE TABLE IF NOT EXISTS subscription_revenue_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    broadcaster_id UUID NOT NULL REFERENCES user_profiles(id),
    subscription_id UUID NOT NULL REFERENCES user_subscriptions(id),
    amount_coins INTEGER NOT NULL,
    transaction_type TEXT NOT NULL CHECK (
        transaction_type IN ('monthly_fee', 'refund', 'chargeback', 'upgrade')
    ),
    payment_gateway TEXT DEFAULT 'internal',
    status TEXT NOT NULL CHECK (status IN ('pending', 'completed', 'failed', 'refunded')),
    notes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: support_goal_reminder_dismissals
CREATE TABLE IF NOT EXISTS public.support_goal_reminder_dismissals (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    viewer_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    broadcaster_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    stream_id UUID NULL REFERENCES streams(id) ON DELETE SET NULL,
    cashout_tier INTEGER NOT NULL,
    dismissed_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: troll_family_league_seasons
CREATE TABLE IF NOT EXISTS public.troll_family_league_seasons (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    
    -- Season identity
    season_number integer NOT NULL,
    season_start_date date NOT NULL,
    season_end_date date NOT NULL,
    
    -- Status
    is_active boolean DEFAULT true,
    is_completed boolean DEFAULT false,
    
    -- Season metadata
    name text,
    description text,
    theme text,  -- e.g., 'spring', 'summer', 'autumn', 'winter'
    
    -- Timestamps
    created_at timestamp with time zone DEFAULT NOW(),
    ended_at timestamp with time zone,
    
    UNIQUE(season_number),
    UNIQUE(season_start_date, season_end_date)
);

-- Table: troll_family_league_standings
CREATE TABLE IF NOT EXISTS public.troll_family_league_standings (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    season_id uuid NOT NULL REFERENCES public.troll_family_league_seasons(id) ON DELETE CASCADE,
    family_id uuid NOT NULL REFERENCES public.troll_families(id) ON DELETE CASCADE,
    
    -- Rankings and points
    rank integer,
    points integer DEFAULT 0,
    wins integer DEFAULT 0,
    losses integer DEFAULT 0,
    goals_completed integer DEFAULT 0,
    goals_failed integer DEFAULT 0,
    
    -- Activity tracking
    members_active integer DEFAULT 0,
    total_member_activity numeric DEFAULT 0,
    participation_rate numeric DEFAULT 0,  -- 0.0 to 1.0
    
    -- Rewards earned
    coins_earned integer DEFAULT 0,
    xp_earned integer DEFAULT 0,
    bonus_coins integer DEFAULT 0,
    
    -- Metadata
    metadata jsonb DEFAULT '{}'::jsonb,
    
    created_at timestamp with time zone DEFAULT NOW(),
    updated_at timestamp with time zone DEFAULT NOW(),
    
    UNIQUE(season_id, family_id)
);

-- Table: security_events
CREATE TABLE IF NOT EXISTS public.security_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    event_type text NOT NULL,
    severity text NOT NULL DEFAULT 'low' CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'investigating', 'resolved', 'ignored', 'false_positive')),
    user_id uuid NULL,
    actor_id uuid NULL,
    target_user_id uuid NULL,
    stream_id uuid NULL,
    agency_id uuid NULL,
    cashout_id uuid NULL,
    ip_address text NULL,
    user_agent text NULL,
    device_fingerprint text NULL,
    route text NULL,
    source text NOT NULL DEFAULT 'frontend',
    title text NOT NULL,
    description text NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    risk_score integer NOT NULL DEFAULT 0,
    reviewed_by uuid NULL,
    reviewed_at timestamptz NULL,
    resolved_at timestamptz NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Table: security_user_risk_scores
CREATE TABLE IF NOT EXISTS public.security_user_risk_scores (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid NOT NULL UNIQUE,
    risk_score integer NOT NULL DEFAULT 0,
    risk_level text NOT NULL DEFAULT 'low' CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),
    failed_login_count integer NOT NULL DEFAULT 0,
    suspicious_action_count integer NOT NULL DEFAULT 0,
    last_event_at timestamptz NULL,
    last_ip_address text NULL,
    notes text NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Table: security_rate_limits
CREATE TABLE IF NOT EXISTS public.security_rate_limits (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    bucket text NOT NULL,
    identifier text NOT NULL,
    user_id uuid NULL,
    ip_address text NULL,
    action text NOT NULL,
    hit_count integer NOT NULL DEFAULT 1,
    window_start timestamptz NOT NULL DEFAULT now(),
    window_end timestamptz NOT NULL,
    blocked_until timestamptz NULL,
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Table: security_incident_reports
CREATE TABLE IF NOT EXISTS public.security_incident_reports (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    title text NOT NULL,
    severity text NOT NULL DEFAULT 'medium' CHECK (severity IN ('low', 'medium', 'high', 'critical')),
    status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'investigating', 'resolved')),
    created_by uuid NULL,
    assigned_to uuid NULL,
    summary text NULL,
    evidence jsonb NOT NULL DEFAULT '[]'::jsonb,
    actions_taken jsonb NOT NULL DEFAULT '[]'::jsonb,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Table: church_live_sessions
CREATE TABLE IF NOT EXISTS public.church_live_sessions (
