    os TEXT,
    severity TEXT,
    tags JSONB DEFAULT '{}'::jsonb,
    breadcrumbs JSONB DEFAULT '[]'::jsonb,
    request_info JSONB DEFAULT '{}'::jsonb,
    extra JSONB DEFAULT '{}'::jsonb
