-- Table: agency_settings
CREATE TABLE IF NOT EXISTS public.agency_settings (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    key TEXT NOT NULL UNIQUE,
    value JSONB NOT NULL DEFAULT '{}'::jsonb,
    description TEXT,
    updated_by UUID REFERENCES public.user_profiles(id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: page_visibility
CREATE TABLE public.page_visibility (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  route_path TEXT NOT NULL UNIQUE,
  page_name TEXT NOT NULL,
  is_under_construction BOOLEAN NOT NULL DEFAULT false,
  uc_message TEXT DEFAULT 'This page is currently under construction.',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Table: document_types
CREATE TABLE IF NOT EXISTS public.document_types (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  description TEXT,
  category TEXT NOT NULL DEFAULT 'general',
  template_content TEXT,
  required_roles TEXT[] DEFAULT '{}',
  is_active BOOLEAN DEFAULT true,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- Table: documents
CREATE TABLE IF NOT EXISTS public.documents (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  document_type_id UUID REFERENCES public.document_types(id),
  document_type_slug TEXT NOT NULL DEFAULT 'custom',
  title TEXT NOT NULL,
  content TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'pending', 'approved', 'rejected', 'expired', 'archived')),
  priority TEXT DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
  submitted_by UUID REFERENCES public.user_profiles(id),
  submitted_at TIMESTAMP WITH TIME ZONE,
  reviewed_by UUID REFERENCES public.user_profiles(id),
  reviewed_at TIMESTAMP WITH TIME ZONE,
  approved_by UUID REFERENCES public.user_profiles(id),
  approved_at TIMESTAMP WITH TIME ZONE,
  rejected_by UUID REFERENCES public.user_profiles(id),
  rejected_at TIMESTAMP WITH TIME ZONE,
  rejection_reason TEXT,
  assigned_to UUID REFERENCES public.user_profiles(id),
  assigned_at TIMESTAMP WITH TIME ZONE,
  due_date TIMESTAMP WITH TIME ZONE,
  tags TEXT[] DEFAULT '{}',
  metadata JSONB DEFAULT '{}',
  parent_document_id UUID REFERENCES public.documents(id),
  is_template BOOLEAN DEFAULT false,
  template_id UUID REFERENCES public.documents(id),
  version INTEGER DEFAULT 1,
  storage_path TEXT,
  pdf_path TEXT,
  checksum TEXT,
  is_locked BOOLEAN DEFAULT false,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- Table: document_signatures
CREATE TABLE IF NOT EXISTS public.document_signatures (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id UUID NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES public.user_profiles(id),
  username TEXT NOT NULL,
  legal_name TEXT NOT NULL,
  typed_signature TEXT NOT NULL,
  ip_address INET,
  browser_user_agent TEXT,
  signed_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  agreement_version INTEGER NOT NULL DEFAULT 1,
  signature_hash TEXT NOT NULL,
  document_type TEXT NOT NULL,
  is_revoked BOOLEAN DEFAULT false,
  revoked_at TIMESTAMP WITH TIME ZONE,
  revocation_reason TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- Table: document_approvals
CREATE TABLE IF NOT EXISTS public.document_approvals (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id UUID NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE,
  approver_id UUID NOT NULL REFERENCES public.user_profiles(id),
  approver_username TEXT NOT NULL,
  approver_role TEXT NOT NULL,
  approval_type TEXT NOT NULL CHECK (approval_type IN ('initial', 'secondary', 'final', 'override')),
  decision TEXT NOT NULL CHECK (decision IN ('approved', 'rejected', 'returned')),
  comments TEXT,
  required_role TEXT,
  approval_order INTEGER DEFAULT 1,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- Table: document_stamps
CREATE TABLE IF NOT EXISTS public.document_stamps (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id UUID NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE,
  approval_id UUID REFERENCES public.document_approvals(id),
  stamp_id TEXT NOT NULL UNIQUE,
  seal_text TEXT NOT NULL DEFAULT 'maitroll OFFICIAL',
  approver_id UUID NOT NULL REFERENCES public.user_profiles(id),
  approver_username TEXT NOT NULL,
  approver_role TEXT NOT NULL,
  approval_date TIMESTAMP WITH TIME ZONE NOT NULL,
  expiry_date TIMESTAMP WITH TIME ZONE,
  stamp_hash TEXT NOT NULL,
  verification_code TEXT NOT NULL UNIQUE,
  ip_address INET,
  is_valid BOOLEAN DEFAULT true,
  document_checksum TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- Table: document_audit_logs
CREATE TABLE IF NOT EXISTS public.document_audit_logs (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  document_id UUID NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE,
  actor_id UUID REFERENCES public.user_profiles(id),
  actor_username TEXT NOT NULL,
  actor_role TEXT,
  action TEXT NOT NULL CHECK (action IN (
    'document_created', 'document_updated', 'document_signed',
    'document_submitted', 'document_reviewed', 'document_approved',
    'document_rejected', 'document_stamped', 'document_downloaded',
    'document_archived', 'document_assigned', 'document_unassigned',
    'signature_added', 'signature_revoked', 'stamp_applied',
    'version_created', 'document_locked', 'document_unlocked',
    'pdf_generated', 'document_shared', 'approval_override'
  )),
  details JSONB DEFAULT '{}',
  ip_address INET,
  user_agent TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- Table: officer_vote_cycles
create table if not exists officer_vote_cycles (
  id uuid primary key default gen_random_uuid(),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status text not null default 'active' check (status in ('active', 'closed')),
  created_at timestamptz not null default now()
);

-- Table: officer_votes
create table if not exists officer_votes (
  id uuid primary key default gen_random_uuid(),
  cycle_id uuid not null references officer_vote_cycles(id) on delete cascade,
  voter_id uuid not null references auth.users(id) on delete cascade,
  broadcaster_id uuid not null references public.user_profiles(id) on delete cascade,
  created_at timestamptz not null default now()
);

-- Table: events
CREATE TABLE public.events (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  category_id UUID REFERENCES public.event_categories(id),
  category_slug TEXT NOT NULL DEFAULT 'custom_event',

  -- Event timing
  event_date DATE NOT NULL,
  start_time TIME WITH TIME ZONE,
  end_time TIME WITH TIME ZONE,
  timezone TEXT DEFAULT 'UTC',

  -- Media
  banner_image_url TEXT,
  thumbnail_url TEXT,
  event_color TEXT DEFAULT '#8B5CF6',

  -- Creator & ownership
  creator_id UUID NOT NULL REFERENCES public.user_profiles(id),
  creator_username TEXT NOT NULL,

  -- Status
  status TEXT NOT NULL DEFAULT 'upcoming' CHECK (status IN ('upcoming', 'live', 'completed', 'cancelled', 'archived')),

  -- Participation
  max_participants INTEGER,
  registration_locked BOOLEAN DEFAULT false,
  registration_opens_at TIMESTAMP WITH TIME ZONE,
  registration_closes_at TIMESTAMP WITH TIME ZONE,

  -- Visibility & access
  visibility TEXT NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'private', 'invite_only')),
  access_level TEXT DEFAULT 'everyone' CHECK (access_level IN (
    'everyone', 'verified_users', 'founding_officers', 'staff', 'creators', 'agencies',
    'specific_levels', 'specific_users', 'invite_only'
  )),
  min_level INTEGER DEFAULT 1,

  -- Requirements & rules
  requirements TEXT[] DEFAULT '{}',
  rules TEXT,

  -- Location (optional - for virtual/physical events)
  location_type TEXT DEFAULT 'virtual' CHECK (location_type IN ('virtual', 'physical', 'hybrid')),
  location_details TEXT,
  stream_id UUID,

  -- Notification settings
  notifications_enabled BOOLEAN DEFAULT true,
  reminder_7d_sent BOOLEAN DEFAULT false,
  reminder_3d_sent BOOLEAN DEFAULT false,
  reminder_24h_sent BOOLEAN DEFAULT false,
  reminder_1h_sent BOOLEAN DEFAULT false,
  started_notification_sent BOOLEAN DEFAULT false,

  -- Metadata
  metadata JSONB DEFAULT '{}',
  tags TEXT[] DEFAULT '{}',

  -- Timestamps
  created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- Table: event_participants
CREATE TABLE public.event_participants (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.events(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES public.user_profiles(id),
  username TEXT NOT NULL,
  avatar_url TEXT,

  -- Participation status
  status TEXT NOT NULL DEFAULT 'registered' CHECK (status IN (
    'registered', 'confirmed', 'waitlisted', 'attended', 'no_show', 'cancelled', 'banned'
  )),

  -- Registration details
  registered_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
  confirmed_at TIMESTAMP WITH TIME ZONE,
  attended_at TIMESTAMP WITH TIME ZONE,

  -- Additional info
  notes TEXT,
  metadata JSONB DEFAULT '{}',

  UNIQUE(event_id, user_id)
);

-- Table: auction_prediction_settings
CREATE TABLE IF NOT EXISTS auction_prediction_settings (
  id int PRIMARY KEY DEFAULT 1,
  enabled boolean NOT NULL DEFAULT true,
  enabled_global boolean NOT NULL DEFAULT true,
  lock_before_end_seconds int NOT NULL DEFAULT 30,
  reward_crowns_correct_winner int NOT NULL DEFAULT 10,
  reward_crowns_correct_price int NOT NULL DEFAULT 25,
  reward_crowns_combined int NOT NULL DEFAULT 50,
  reward_xp_correct_winner int NOT NULL DEFAULT 100,
  reward_xp_correct_price int NOT NULL DEFAULT 250,
  reward_xp_combined int NOT NULL DEFAULT 500,
  reward_event_points_correct_winner int NOT NULL DEFAULT 5,
  reward_event_points_correct_price int NOT NULL DEFAULT 10,
  reward_event_points_combined int NOT NULL DEFAULT 20,
  min_entries_for_leaderboard int NOT NULL DEFAULT 3,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- Table: auction_predictions
CREATE TABLE IF NOT EXISTS auction_predictions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  auction_show_id uuid NOT NULL REFERENCES auction_shows(id) ON DELETE CASCADE,
  predicted_winner_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  predicted_price int,
  prediction_type text NOT NULL DEFAULT 'combined' CHECK (prediction_type IN ('winner', 'price', 'combined')),
  is_locked boolean NOT NULL DEFAULT false,
  locked_at timestamptz,
  is_correct_winner boolean,
  is_correct_price boolean,
  price_accuracy int,
  submitted_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(user_id, auction_show_id)
);

-- Table: crown_redemptions
CREATE TABLE IF NOT EXISTS public.crown_redemptions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  reward_type TEXT NOT NULL CHECK (reward_type IN ('troll_coins', 'gift_card')),
  crowns_redeemed INTEGER NOT NULL CHECK (crowns_redeemed > 0),
  reward_value TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'fulfilled', 'rejected', 'cancelled')),
  email_sent BOOLEAN DEFAULT FALSE,
  fulfilled_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  fulfilled_at TIMESTAMPTZ,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Table: office_folders
CREATE TABLE IF NOT EXISTS office_folders (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  parent_folder_id UUID REFERENCES office_folders(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: office_documents
CREATE TABLE IF NOT EXISTS office_documents (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  content TEXT NOT NULL DEFAULT '',
  folder_id UUID REFERENCES office_folders(id) ON DELETE SET NULL,
  is_admin_document BOOLEAN DEFAULT false,
  is_read_only BOOLEAN DEFAULT false,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: office_document_versions
CREATE TABLE IF NOT EXISTS office_document_versions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id UUID NOT NULL REFERENCES office_documents(id) ON DELETE CASCADE,
  version_number INTEGER NOT NULL,
  content TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: office_spreadsheets
CREATE TABLE IF NOT EXISTS office_spreadsheets (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  owner_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  folder_id UUID REFERENCES office_folders(id) ON DELETE SET NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: office_spreadsheet_cells
CREATE TABLE IF NOT EXISTS office_spreadsheet_cells (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  spreadsheet_id UUID NOT NULL REFERENCES office_spreadsheets(id) ON DELETE CASCADE,
  sheet_name TEXT NOT NULL,
  cell_reference TEXT NOT NULL,
  row_index INTEGER NOT NULL DEFAULT 0,
  col_index INTEGER NOT NULL DEFAULT 0,
  value TEXT,
  formula TEXT,
  style_json JSONB DEFAULT '{}'::jsonb,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: office_shared_files
CREATE TABLE IF NOT EXISTS office_shared_files (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  file_id UUID NOT NULL,
  file_type TEXT NOT NULL CHECK (file_type IN ('document', 'spreadsheet')),
  owner_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  shared_with_user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  permission_level TEXT NOT NULL CHECK (permission_level IN ('owner', 'editor', 'viewer')),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: office_templates
CREATE TABLE IF NOT EXISTS office_templates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  file_type TEXT NOT NULL CHECK (file_type IN ('document', 'spreadsheet')),
  description TEXT,
  content_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  is_public BOOLEAN DEFAULT true,
  created_by UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: treelz_posts
CREATE TABLE IF NOT EXISTS treelz_posts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  video_url TEXT NOT NULL,
  thumbnail_url TEXT,
  caption TEXT DEFAULT '',
  video_duration_seconds INTEGER DEFAULT 0,
  video_size_bytes BIGINT DEFAULT 0,
  likes_count INTEGER DEFAULT 0,
  comments_count INTEGER DEFAULT 0,
  shares_count INTEGER DEFAULT 0,
  saves_count INTEGER DEFAULT 0,
  views_count INTEGER DEFAULT 0,
  watch_time_seconds BIGINT DEFAULT 0,
  completion_rate NUMERIC(5,2) DEFAULT 0,
  gifts_received INTEGER DEFAULT 0,
  coins_received BIGINT DEFAULT 0,
  is_ai_flagged BOOLEAN DEFAULT false,
  ai_detection_score NUMERIC(5,2) DEFAULT 0,
  ai_review_status TEXT DEFAULT 'pending' CHECK (ai_review_status IN ('pending', 'reviewed', 'cleared', 'actioned')),
  status TEXT DEFAULT 'active' CHECK (status IN ('active', 'hidden', 'removed', 'age_restricted')),
  is_featured BOOLEAN DEFAULT false,
  is_pinned BOOLEAN DEFAULT false,
  is_boosted BOOLEAN DEFAULT false,
  boost_expires_at TIMESTAMP WITH TIME ZONE,
  is_live_promotion BOOLEAN DEFAULT false,
  live_stream_id TEXT,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: treelz_likes
CREATE TABLE IF NOT EXISTS treelz_likes (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  post_id UUID NOT NULL REFERENCES treelz_posts(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  UNIQUE(user_id, post_id)
);

-- Table: treelz_comments
CREATE TABLE IF NOT EXISTS treelz_comments (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  post_id UUID NOT NULL REFERENCES treelz_posts(id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: treelz_saves
CREATE TABLE IF NOT EXISTS treelz_saves (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  post_id UUID NOT NULL REFERENCES treelz_posts(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  UNIQUE(user_id, post_id)
);

-- Table: treelz_shares
CREATE TABLE IF NOT EXISTS treelz_shares (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  post_id UUID NOT NULL REFERENCES treelz_posts(id) ON DELETE CASCADE,
  platform TEXT DEFAULT 'copy_link',
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: treelz_ai_flags
CREATE TABLE IF NOT EXISTS treelz_ai_flags (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  post_id UUID NOT NULL REFERENCES treelz_posts(id) ON DELETE CASCADE,
  flagged_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  confidence NUMERIC(5,2) NOT NULL,
  action_taken TEXT DEFAULT 'pending' CHECK (action_taken IN ('pending', 'cleared', 'removed', 'age_restricted')),
  reviewed_by UUID REFERENCES user_profiles(id),
  reviewed_at TIMESTAMP WITH TIME ZONE
);

-- Table: treelz_upload_bans
CREATE TABLE IF NOT EXISTS treelz_upload_bans (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  reason TEXT NOT NULL,
  banned_until TIMESTAMP WITH TIME ZONE,
  strike_count INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: states
CREATE TABLE IF NOT EXISTS public.states (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    state_code TEXT UNIQUE NOT NULL,
    state_name TEXT NOT NULL,
    battle_points BIGINT DEFAULT 0,
    wins INTEGER DEFAULT 0,
    losses INTEGER DEFAULT 0,
    representative_user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    monthly_points BIGINT DEFAULT 0,
    monthly_wins INTEGER DEFAULT 0,
    monthly_losses INTEGER DEFAULT 0,
    last_month_reset TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: state_members
CREATE TABLE IF NOT EXISTS public.state_members (
    user_id UUID PRIMARY KEY REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    state_code TEXT NOT NULL REFERENCES public.states(state_code) ON DELETE CASCADE,
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    battle_points_earned BIGINT DEFAULT 0,
    battles_participated INTEGER DEFAULT 0,
    battles_won INTEGER DEFAULT 0
);

-- Table: state_battles
CREATE TABLE IF NOT EXISTS public.state_battles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    battle_id UUID REFERENCES public.troll_battles(id) ON DELETE SET NULL,
    state_a TEXT NOT NULL REFERENCES public.states(state_code),
    state_b TEXT NOT NULL REFERENCES public.states(state_code),
    winner_state TEXT REFERENCES public.states(state_code),
    points_awarded INTEGER DEFAULT 0,
    host_user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    challenger_user_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: marketplace_payout_release_requests
CREATE TABLE IF NOT EXISTS marketplace_payout_release_requests (
  id uuid primary key default gen_random_uuid(),
  order_id uuid REFERENCES marketplace_purchases(id) ON DELETE CASCADE NOT NULL,
  seller_id uuid REFERENCES user_profiles(id) ON DELETE CASCADE NOT NULL,

  -- Request details
  tracking_number text NOT NULL,
  tracking_url text,
  carrier text CHECK (carrier IN ('usps', 'ups', 'fedex', 'dhl', 'other')),
  seller_notes text,

  -- Gate info
  completed_sales_count int DEFAULT 0,
  has_open_appeals boolean DEFAULT false,

  -- Status flow: pending -> approved -> rejected -> completed | expired
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'rejected', 'completed', 'expired')),

  -- Admin fields
  reviewed_by uuid REFERENCES user_profiles(id),
  reviewed_at timestamptz,
  admin_notes text,
  rejection_reason text,

  -- Timestamps
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),

  UNIQUE(order_id)
);

-- Table: fast_pay_applications
CREATE TABLE IF NOT EXISTS public.fast_pay_applications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,

  -- Application details
  payout_method text NOT NULL CHECK (payout_method IN ('cash_app', 'paypal', 'venmo')),
  payout_username text NOT NULL,
  payout_email text,
  cashtag text,
  venmo_handle text,

  -- Terms acceptance
  accepted_terms boolean NOT NULL DEFAULT false,
  accepted_fees boolean NOT NULL DEFAULT false,
  accepted_identity_verification boolean NOT NULL DEFAULT false,

  -- Eligibility snapshot at time of application
  user_level int NOT NULL,
  account_age_days int NOT NULL,
  has_verified_identity boolean NOT NULL DEFAULT false,
  has_violations boolean NOT NULL DEFAULT false,
  has_fraud_history boolean NOT NULL DEFAULT false,

  -- Status flow: pending -> under_review -> approved -> rejected
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'under_review', 'approved', 'rejected')),

  -- Admin review
  reviewed_by uuid REFERENCES user_profiles(id),
  reviewed_at timestamptz,
  admin_notes text,
  rejection_reason text,

  -- Timestamps
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  UNIQUE(user_id)
);

-- Table: stream_smoke_events
CREATE TABLE IF NOT EXISTS public.stream_smoke_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  created_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  is_active boolean DEFAULT true,
  seat_count integer DEFAULT 6 CHECK (seat_count >= 1 AND seat_count <= 12),
  raffle_enabled boolean DEFAULT true,
  troll_drop_enabled boolean DEFAULT true,
  song_queue_enabled boolean DEFAULT true,
  dj_user_id uuid REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  started_at timestamptz DEFAULT now(),
  ended_at timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- Table: troll_drops
CREATE TABLE IF NOT EXISTS public.troll_drops (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  created_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  coin_value integer NOT NULL CHECK (coin_value > 0),
  duration_seconds integer NOT NULL CHECK (duration_seconds IN (3, 10, 30)),
  total_bills integer NOT NULL DEFAULT 25 CHECK (total_bills > 0 AND total_bills <= 500),
  status text DEFAULT 'active' CHECK (status IN ('active', 'ended', 'cancelled')),
  started_at timestamptz DEFAULT now(),
  ends_at timestamptz NOT NULL,
  created_at timestamptz DEFAULT now()
);

-- Table: stream_song_requests
CREATE TABLE IF NOT EXISTS public.stream_song_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  requested_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  dj_user_id uuid REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  song_title text NOT NULL,
  artist text,
  song_link text,
  total_cost integer DEFAULT 10,
  dj_share integer DEFAULT 5,
  admin_share integer DEFAULT 5,
  status text DEFAULT 'queued' CHECK (status IN ('queued', 'playing', 'played', 'skipped', 'refunded')),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- Table: stream_raffles
CREATE TABLE IF NOT EXISTS public.stream_raffles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  smoke_event_id uuid REFERENCES public.stream_smoke_events(id) ON DELETE CASCADE,
  created_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  ticket_cost integer DEFAULT 500,
  status text DEFAULT 'active' CHECK (status IN ('active', 'drawing', 'completed', 'cancelled')),
  draw_interval_minutes integer DEFAULT 30,
  current_round integer DEFAULT 1,
  next_draw_at timestamptz NOT NULL,
  started_at timestamptz DEFAULT now(),
  ended_at timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- Table: cashout_tiers
CREATE TABLE IF NOT EXISTS public.cashout_tiers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    coin_amount BIGINT NOT NULL,
    cash_amount NUMERIC(12,2) NOT NULL,
    currency TEXT DEFAULT 'USD',
    processing_fee_percentage NUMERIC(6,2) DEFAULT 2.9,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: broadcast_mod_actions
CREATE TABLE IF NOT EXISTS public.broadcast_mod_actions (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    
    -- Who performed the action
    actor_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    actor_role TEXT DEFAULT 'unknown',
    
    -- Who was targeted
    target_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    
    -- Action details (NO 'ban' - only arrest, warn, mute, disable, etc.)
    action_type TEXT NOT NULL CHECK (action_type IN (
        'disable_chat', 'enable_chat', 'kick', 'arrest',
        'disable_broadcast', 'enable_broadcast',
        'disable_hytrogame', 'enable_hytrogame',
        'disable_seat_joining', 'enable_seat_joining',
        'report', 'mute', 'unmute', 'warn',
        'warning', 'platform_review', 'fine'
    )),
    
    -- Context
    stream_id UUID REFERENCES public.streams(id) ON DELETE SET NULL,
    
    -- Action parameters
    duration_minutes INTEGER,
    reason TEXT,
    severity TEXT,
    bail_amount NUMERIC(12,2),
    
    -- Fine system
    fine_amount NUMERIC(12,2) DEFAULT 0,
    fine_paid BOOLEAN DEFAULT false,
    fine_paid_at TIMESTAMPTZ,
    fine_payment_method TEXT CHECK (fine_payment_method IN ('troll_coins', 'manual', 'waived')),
    fine_waived_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    fine_waived_at TIMESTAMPTZ,
    
    -- Evidence fields
    evidence_urls JSONB DEFAULT '[]'::jsonb,
    evidence_type TEXT CHECK (evidence_type IN ('screenshot', 'video', 'clip', 'chat_logs', 'system_log', 'other')),
    evidence_notes TEXT,
    
    -- Internal moderator notes (staff only, never shown to users)
    internal_notes TEXT,
    
    -- For arrest: whether broadcast was being recorded
    broadcast_recorded BOOLEAN DEFAULT false,
    
    -- Expiration (for timed actions)
    expires_at TIMESTAMPTZ,
    
    -- Status
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'expired', 'revoked', 'completed')),
    
    -- If action was revoked
    revoked_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    revoked_at TIMESTAMPTZ,
    revoke_reason TEXT,
    
    -- Audit fields
    edited_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    edited_at TIMESTAMPTZ,
    edit_count INTEGER DEFAULT 0,
    
    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: user_broadcast_restrictions
CREATE TABLE IF NOT EXISTS public.user_broadcast_restrictions (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    broadcast_disabled BOOLEAN DEFAULT false,
    hytrogame_disabled BOOLEAN DEFAULT false,
    seat_joining_disabled BOOLEAN DEFAULT false,
    chat_disabled BOOLEAN DEFAULT false,
    restricted_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    reason TEXT,
    duration_minutes INTEGER,
    expires_at TIMESTAMPTZ,
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'expired', 'revoked')),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(user_id)
);

-- Table: user_profile_badges
CREATE TABLE IF NOT EXISTS public.user_profile_badges (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    badge_id UUID NOT NULL REFERENCES public.badge_definitions(id) ON DELETE CASCADE,
    earned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    is_featured BOOLEAN NOT NULL DEFAULT false,
    featured_order INT,
    UNIQUE(user_id, badge_id)
);

-- Table: user_profile_roles
CREATE TABLE IF NOT EXISTS public.user_profile_roles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    role_type TEXT NOT NULL CHECK (role_type IN (
        'auctioneer', 'attorney', 'prosecutor', 'journalist', 'news_caster',
        'chief_news_caster', 'troll_officer', 'lead_troll_officer', 'pastor',
        'agency_leader', 'agency_hr', 'agency_hr_manager', 'secretary',
        'ceo_assistant', 'noah_assistant', 'troller', 'seller', 'broadcaster'
    )),
    is_active BOOLEAN NOT NULL DEFAULT true,
    assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    assigned_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    metadata JSONB DEFAULT '{}'::jsonb,
    UNIQUE(user_id, role_type)
);

-- Table: jail_transactions
CREATE TABLE public.jail_transactions (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            jail_id UUID REFERENCES public.jail(id) ON DELETE CASCADE,
            user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE,
            transaction_type TEXT NOT NULL CHECK (transaction_type IN ('message_fee', 'bond', 'appeal_fee', 'refund', 'attorney_fee')),
            amount INTEGER NOT NULL,
            recipient_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
            recipient_type TEXT CHECK (recipient_type IN ('public_pool', 'admin', 'attorney')),
            status TEXT DEFAULT 'completed' CHECK (status IN ('pending', 'completed', 'failed', 'refunded')),
            notes TEXT,
            created_at TIMESTAMPTZ DEFAULT NOW()
        );

-- Table: promo_cards
CREATE TABLE IF NOT EXISTS promo_cards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    token_amount numeric(12,2) NOT NULL,
    user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    source_type text NOT NULL CHECK (source_type IN ('broadcast_start', 'broadcast_watch', 'share_link')),
    issued_at timestamp with time zone NOT NULL DEFAULT now(),
    expires_at timestamp with time zone NOT NULL,
    redeemed_at timestamp with time zone NULL,
    redeemed_by uuid NULL REFERENCES auth.users(id) ON DELETE SET NULL,
    status text NOT NULL DEFAULT 'available' CHECK (status IN ('available', 'redeemed', 'expired')),
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    updated_at timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT promo_cards_pkey PRIMARY KEY (id),
    CONSTRAINT promo_cards_code_key UNIQUE (code),
    CONSTRAINT promo_cards_token_amount_nonnegative CHECK (token_amount >= 0)
);

-- Table: employee_audit_log
create table if not exists public.employee_audit_log (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references auth.users(id) on delete set null,
  target_id uuid references auth.users(id) on delete set null,
  action text not null,
  previous_value jsonb,
  new_value jsonb,
  reason text,
  department text,
  related_record text,
  created_at timestamptz not null default now()
);

-- Table: employee_records
create table if not exists public.employee_records (
  user_id uuid primary key references auth.users(id) on delete cascade,
  employment_status text not null default 'active'
    check (employment_status in ('active','inactive','suspended','terminated')),
  department text,
  job_title text,
  supervisor_id uuid references auth.users(id) on delete set null,
  hire_date timestamptz,
  location_city text,
  location_state text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Table: employee_announcements
create table if not exists public.employee_announcements (
  id uuid primary key default gen_random_uuid(),
  author_id uuid references auth.users(id) on delete set null,
  title text not null,
  body text not null,
  level text not null default 'normal' check (level in ('normal','important','urgent')),
  department text,
  created_at timestamptz not null default now()
);

-- Table: employee_announcement_acks
create table if not exists public.employee_announcement_acks (
  id uuid primary key default gen_random_uuid(),
  announcement_id uuid not null references public.employee_announcements(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  acked_at timestamptz not null default now(),
  unique (announcement_id, user_id)
);

-- Table: employee_tasks
create table if not exists public.employee_tasks (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  assigned_by uuid references auth.users(id) on delete set null,
  assigned_to uuid references auth.users(id) on delete set null,
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  due_date timestamptz,
  status text not null default 'assigned'
    check (status in ('assigned','in_progress','blocked','awaiting_review','completed','cancelled')),
  department text,
  comments jsonb default '[]'::jsonb,
  attachments jsonb default '[]'::jsonb,
  completion_notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Table: employee_reports
create table if not exists public.employee_reports (
  id uuid primary key default gen_random_uuid(),
  report_type text,
  subject text not null,
  description text,
  submitted_by uuid references auth.users(id) on delete set null,
  related_user uuid references auth.users(id) on delete set null,
  related_employee uuid references auth.users(id) on delete set null,
  related_broadcast uuid,
  related_incident uuid,
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  confidential boolean not null default false,
  status text not null default 'submitted'
    check (status in ('submitted','received','under_review','more_info_needed','action_taken','closed','escalated')),
  supervisor_id uuid references auth.users(id) on delete set null,
  responses jsonb default '[]'::jsonb,
  evidence jsonb default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Table: employee_change_requests
create table if not exists public.employee_change_requests (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  body text not null,
  type text not null default 'platform_change' check (type in ('platform_change','workflow','employee_tool')),
  author_id uuid references auth.users(id) on delete set null,
  status text not null default 'open' check (status in ('open','under_review','approved','rejected','implemented')),
  votes integer not null default 0,
  comments jsonb default '[]'::jsonb,
  attachments jsonb default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Table: employee_change_request_votes
create table if not exists public.employee_change_request_votes (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.employee_change_requests(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (request_id, user_id)
);

-- Table: employee_chat_channels
create table if not exists public.employee_chat_channels (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  kind text not null default 'general' check (kind in ('general','department','role','direct')),
  role_scope text[] not null default '{}', -- empty = all employees
  created_at timestamptz not null default now()
);

-- Table: employee_chat_messages
create table if not exists public.employee_chat_messages (
  id uuid primary key default gen_random_uuid(),
  channel_id uuid not null references public.employee_chat_channels(id) on delete cascade,
  sender_id uuid references auth.users(id) on delete set null,
  body text not null,
  parent_id uuid references public.employee_chat_messages(id) on delete cascade,
  reactions jsonb default '{}'::jsonb,
  attachments jsonb default '[]'::jsonb,
  created_at timestamptz not null default now()
);

-- Table: frontend_studio_drafts
create table if not exists public.frontend_studio_drafts (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  config jsonb not null default '{}'::jsonb,
  status text not null default 'draft' check (status in ('draft','approved','published','rolled_back')),
  author_id uuid references auth.users(id) on delete set null,
  approved_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  published_at timestamptz
);

-- Table: employee_payroll_runs
create table if not exists public.employee_payroll_runs (
  id uuid primary key default gen_random_uuid(),
  period_start date not null,
  period_end date not null,
  status text not null default 'draft' check (status in ('draft','approved','paid')),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

-- Table: employee_paystubs
create table if not exists public.employee_paystubs (
  id uuid primary key default gen_random_uuid(),
  run_id uuid references public.employee_payroll_runs(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  pay_period_start date not null,
  pay_period_end date not null,
  pay_date date not null,
  hours numeric not null default 0,
  rate numeric not null default 0,
  gross_pay numeric not null default 0,
  federal_tax numeric not null default 0,
  state_tax numeric not null default 0,
  fica numeric not null default 0,
  medicare numeric not null default 0,
  net_pay numeric not null default 0,
  location_city text,
  location_state text,
  created_at timestamptz not null default now()
);

-- Table: employee_perk_pay
create table if not exists public.employee_perk_pay (
  id uuid primary key default gen_random_uuid(),
  role text not null unique,
  amount numeric not null default 0,
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);

-- Table: employee_disciplinary_actions
create table if not exists public.employee_disciplinary_actions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  action_type text not null,
  reason text not null,
  issued_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);

-- Table: beta_feedback_internal_notes
CREATE TABLE IF NOT EXISTS public.beta_feedback_internal_notes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  feedback_id uuid NOT NULL REFERENCES public.beta_feedback(id) ON DELETE CASCADE,
  moderator_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  note text NOT NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- Table: beta_feedback_audit_log
CREATE TABLE IF NOT EXISTS public.beta_feedback_audit_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  feedback_id uuid NOT NULL REFERENCES public.beta_feedback(id) ON DELETE CASCADE,
  actor_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  action text NOT NULL,
  old_values jsonb,
  new_values jsonb,
  created_at timestamptz DEFAULT now()
);

-- Table: beta_feedback_replies
CREATE TABLE IF NOT EXISTS public.beta_feedback_replies (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  feedback_id uuid NOT NULL REFERENCES public.beta_feedback(id) ON DELETE CASCADE,
  author_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  body text NOT NULL,
  visibility text NOT NULL DEFAULT 'user_visible',
  created_at timestamptz DEFAULT now()
);

-- Table: hr_onboarding_items
CREATE TABLE IF NOT EXISTS public.hr_onboarding_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  document_key text NOT NULL,
  document_name text NOT NULL,
  category text NOT NULL,
  required boolean NOT NULL DEFAULT true,
  status text NOT NULL DEFAULT 'not_sent'
    CHECK (status IN ('not_sent','sent','submitted','approved','rejected','waived')),
  due_date date,
  sent_at timestamptz,
  submitted_at timestamptz,
  reviewed_at timestamptz,
  reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  file_url text,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (employee_id, document_key)
);

-- Table: interviews
CREATE TABLE public.interviews (
      id uuid DEFAULT gen_random_uuid() NOT NULL,
      job_application_id uuid,
      applicant_id uuid NOT NULL,
      position_id text,
      scheduled_date date NOT NULL,
      scheduled_time time without time zone NOT NULL,
      duration_minutes integer DEFAULT 30 NOT NULL,
      interviewer_id uuid,
      instructions text,
      internal_notes text,
      call_room_id uuid,
      status text DEFAULT 'scheduled'::text NOT NULL,
      created_by uuid,
      created_at timestamptz DEFAULT now() NOT NULL,
      updated_at timestamptz DEFAULT now() NOT NULL,
      CONSTRAINT interviews_pkey PRIMARY KEY (id),
      CONSTRAINT interviews_status_check
        CHECK (status = ANY (ARRAY[
          'scheduled'::text, 'in_progress'::text, 'completed'::text,
          'cancelled'::text, 'no_show'::text
        ]))
    );

-- Table: employee_document_templates
CREATE TABLE IF NOT EXISTS public.employee_document_templates (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  document_key text NOT NULL,
  document_name text NOT NULL,
  category text NOT NULL,
  description text,
  required boolean DEFAULT true,
  applies_to_roles text[],
  applies_to_categories text[],
  sort_order integer DEFAULT 0,
  active boolean DEFAULT true,
  created_at timestamptz DEFAULT now() NOT NULL,
  updated_at timestamptz DEFAULT now() NOT NULL,
  CONSTRAINT employee_document_templates_pkey PRIMARY KEY (id),
  CONSTRAINT employee_document_templates_key_unique UNIQUE (document_key)
);

-- Table: universe_events
CREATE TABLE IF NOT EXISTS public.universe_events (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  title TEXT NOT NULL,
  event_date DATE NOT NULL,
  scheduled_start TIMESTAMPTZ NOT NULL,
  timezone TEXT NOT NULL DEFAULT 'America/Denver',
  registration_opens_at TIMESTAMPTZ,
  registration_closes_at TIMESTAMPTZ,
  seat_lock_at TIMESTAMPTZ,
  check_in_opens_at TIMESTAMPTZ,
  room_opens_at TIMESTAMPTZ,
  opponent_reveal_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft','registration_open','registration_closed','seat_locked','check_in','room_open','active','paused','completed','cancelled','rescheduled')),
  current_round_id UUID,
  champion_user_id UUID,
  default_round_duration_seconds INTEGER NOT NULL DEFAULT 600,
  ability_settings JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT chk_universe_event_mountain_time CHECK (timezone = 'America/Denver')
);

-- Table: universe_registrations
CREATE TABLE IF NOT EXISTS public.universe_registrations (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.universe_events(id) ON DELETE CASCADE,
  captain_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft','submitted','confirmed','matched','scheduled','checked_in','active','completed','withdrawn','cancelled','disqualified','no_show')),
  registered_at TIMESTAMPTZ,
  confirmed_at TIMESTAMPTZ,
  matched_at TIMESTAMPTZ,
  scheduled_battle_at TIMESTAMPTZ,
  attendance_confirmed BOOLEAN NOT NULL DEFAULT false,
  rules_accepted BOOLEAN NOT NULL DEFAULT false,
  withdrawn_at TIMESTAMPTZ,
  cancelled_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_registration_event_captain UNIQUE (event_id, captain_user_id)
);

-- Table: universe_calendar_entries
CREATE TABLE IF NOT EXISTS public.universe_calendar_entries (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID REFERENCES public.universe_events(id) ON DELETE CASCADE,
  match_id UUID REFERENCES public.universe_match_assignments(id) ON DELETE CASCADE,
  user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  entry_type TEXT NOT NULL
    CHECK (entry_type IN ('event','registration','match','reminder','check_in','reveal','completed','cancelled')),
  title TEXT NOT NULL,
  scheduled_start TIMESTAMPTZ,
  timezone TEXT NOT NULL DEFAULT 'America/Denver',
  opponent_visible BOOLEAN NOT NULL DEFAULT false,
  public_details JSONB NOT NULL DEFAULT '{}'::jsonb,
  private_details JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT chk_universe_calendar_mountain_time CHECK (timezone = 'America/Denver')
);

-- Table: universe_team_seats
CREATE TABLE IF NOT EXISTS public.universe_team_seats (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.universe_events(id) ON DELETE CASCADE,
  registration_id UUID NOT NULL REFERENCES public.universe_registrations(id) ON DELETE CASCADE,
  match_id UUID REFERENCES public.universe_match_assignments(id) ON DELETE SET NULL,
  captain_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  seat_number INTEGER NOT NULL CHECK (seat_number IN (1,2,3)),
  invited_user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'empty'
    CHECK (status IN ('empty','invited','accepted','declined','removed','expired','checked_in','connected','disconnected','locked')),
  invited_at TIMESTAMPTZ,
  responded_at TIMESTAMPTZ,
  accepted_at TIMESTAMPTZ,
  declined_at TIMESTAMPTZ,
  removed_at TIMESTAMPTZ,
  checked_in_at TIMESTAMPTZ,
  connected_at TIMESTAMPTZ,
  disconnected_at TIMESTAMPTZ,
  locked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  -- One seat number per registration (max 3 seats per captain)
  CONSTRAINT uq_universe_seat_registration_number UNIQUE (registration_id, seat_number),
  -- One invited user per event-team (captain + event). A user cannot occupy
  -- two seat slots on the same captain's team.
  CONSTRAINT uq_universe_seat_invited_event UNIQUE (event_id, captain_user_id, invited_user_id)
);

-- Table: universe_queue
CREATE TABLE IF NOT EXISTS public.universe_queue (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.universe_events(id) ON DELETE CASCADE,
  registration_id UUID NOT NULL REFERENCES public.universe_registrations(id) ON DELETE CASCADE,
  captain_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'registered'
    CHECK (status IN ('registered','confirmed','matched','scheduled','waiting','next','battling','eliminated','withdrawn','disqualified','winner')),
  accepted_seat_one UUID,
  accepted_seat_two UUID,
  accepted_seat_three UUID,
  entered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_queue_event_registration UNIQUE (event_id, registration_id)
);

-- Table: universe_rounds
CREATE TABLE IF NOT EXISTS public.universe_rounds (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.universe_events(id) ON DELETE CASCADE,
  round_number INTEGER NOT NULL,
  match_id UUID REFERENCES public.universe_match_assignments(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','active','finalizing','completed','cancelled')),
  started_at TIMESTAMPTZ,
  ends_at TIMESTAMPTZ,
  server_end_at TIMESTAMPTZ,
  winner_side TEXT CHECK (winner_side IN ('A','B')),
  winning_captain_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  losing_captain_id UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  actual_duration_seconds INTEGER,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_round_event_number UNIQUE (event_id, round_number)
);

-- Table: universe_round_teams
CREATE TABLE IF NOT EXISTS public.universe_round_teams (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  round_id UUID NOT NULL REFERENCES public.universe_rounds(id) ON DELETE CASCADE,
  event_id UUID NOT NULL REFERENCES public.universe_events(id) ON DELETE CASCADE,
  side TEXT NOT NULL CHECK (side IN ('A','B')),
  captain_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  seat_one_user_id UUID,
  seat_two_user_id UUID,
  seat_three_user_id UUID,
  team_status TEXT NOT NULL DEFAULT 'active'
    CHECK (team_status IN ('active','disconnected','eliminated','forfeited','no_show')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_round_team_side UNIQUE (round_id, side)
);

-- Table: universe_round_scores
CREATE TABLE IF NOT EXISTS public.universe_round_scores (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  round_id UUID NOT NULL REFERENCES public.universe_rounds(id) ON DELETE CASCADE,
  team_id UUID NOT NULL REFERENCES public.universe_round_teams(id) ON DELETE CASCADE,
  captain_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  actual_score BIGINT NOT NULL DEFAULT 0,
  displayed_score BIGINT NOT NULL DEFAULT 0,
  captain_score_contribution BIGINT NOT NULL DEFAULT 0,
  seat_one_score_contribution BIGINT NOT NULL DEFAULT 0,
  seat_two_score_contribution BIGINT NOT NULL DEFAULT 0,
  seat_three_score_contribution BIGINT NOT NULL DEFAULT 0,
  unique_gifters INTEGER NOT NULL DEFAULT 0,
  highest_single_gift BIGINT NOT NULL DEFAULT 0,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_round_score_team UNIQUE (round_id, team_id),
  CONSTRAINT chk_universe_round_score_nonneg CHECK (actual_score >= 0 AND displayed_score >= 0)
);

-- Table: universe_abilities
CREATE TABLE IF NOT EXISTS public.universe_abilities (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.universe_events(id) ON DELETE CASCADE,
  match_id UUID REFERENCES public.universe_match_assignments(id) ON DELETE SET NULL,
  round_id UUID REFERENCES public.universe_rounds(id) ON DELETE CASCADE,
  awarded_to_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  awarded_to_team_id UUID REFERENCES public.universe_round_teams(id) ON DELETE CASCADE,
  ability_type TEXT NOT NULL
    CHECK (ability_type IN ('triple_gifts','timer_troll','hidden_challenger_score','turtle_mode','troll_mode','officer_fee','scramble_score')),
  target_team_id UUID REFERENCES public.universe_round_teams(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'awarded'
    CHECK (status IN ('awarded','available','activating','active','revealing','expired','consumed','cancelled','invalidated')),
  duration_seconds INTEGER NOT NULL DEFAULT 0,
  activated_at TIMESTAMPTZ,
  reveal_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  consumed_at TIMESTAMPTZ,
  effect_payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: universe_event_results
CREATE TABLE IF NOT EXISTS public.universe_event_results (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_id UUID NOT NULL REFERENCES public.universe_events(id) ON DELETE CASCADE,
  champion_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  champion_seat_one UUID,
  champion_seat_two UUID,
  champion_seat_three UUID,
  total_rounds_won INTEGER NOT NULL DEFAULT 0,
  total_actual_score BIGINT NOT NULL DEFAULT 0,
  team_gift_total BIGINT NOT NULL DEFAULT 0,
  captain_contribution BIGINT NOT NULL DEFAULT 0,
  seat_one_contribution BIGINT NOT NULL DEFAULT 0,
  seat_two_contribution BIGINT NOT NULL DEFAULT 0,
  seat_three_contribution BIGINT NOT NULL DEFAULT 0,
  unique_supporters INTEGER NOT NULL DEFAULT 0,
  highest_single_gift BIGINT NOT NULL DEFAULT 0,
  longest_winning_streak INTEGER NOT NULL DEFAULT 0,
  final_battle_result TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: universe_showdown_battles
CREATE TABLE IF NOT EXISTS public.universe_showdown_battles (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_date DATE NOT NULL,
  scheduled_start TIMESTAMPTZ NOT NULL,
  timezone TEXT NOT NULL DEFAULT 'America/Denver',
  capacity INTEGER NOT NULL DEFAULT 30,
  registered_count INTEGER NOT NULL DEFAULT 0,
  guest_count INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'open'
    CHECK (status IN ('open','full','sealed','active','completed','cancelled')),
  is_overflow BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_showdown_date UNIQUE (event_date),
  CONSTRAINT chk_universe_showdown_mountain_time CHECK (timezone = 'America/Denver'),
  CONSTRAINT chk_universe_showdown_capacity CHECK (capacity > 0 AND capacity <= 30)
);

-- Table: universe_showdown_signups
CREATE TABLE IF NOT EXISTS public.universe_showdown_signups (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  battle_id UUID NOT NULL REFERENCES public.universe_showdown_battles(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  battle_name TEXT NOT NULL,
  is_guest BOOLEAN NOT NULL DEFAULT false,
  invited_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  seat_index INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active','withdrawn','removed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_showdown_signup_battle_user UNIQUE (battle_id, user_id),
  CONSTRAINT chk_universe_showdown_seat CHECK (seat_index >= 0 AND seat_index <= 30)
);

-- Table: universe_showdown_invites
CREATE TABLE IF NOT EXISTS public.universe_showdown_invites (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  battle_id UUID NOT NULL REFERENCES public.universe_showdown_battles(id) ON DELETE CASCADE,
  inviter_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  invited_user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','accepted','declined','removed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_showdown_invite UNIQUE (battle_id, inviter_user_id, invited_user_id)
);

-- Table: universe_showdown_dates
CREATE TABLE IF NOT EXISTS public.universe_showdown_dates (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  event_date DATE NOT NULL,
  scheduled_start TIMESTAMPTZ NOT NULL,
  timezone TEXT NOT NULL DEFAULT 'America/Denver',
  is_overflow BOOLEAN NOT NULL DEFAULT false,
  capacity INTEGER NOT NULL DEFAULT 30,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  CONSTRAINT uq_universe_showdown_date_cfg UNIQUE (event_date),
  CONSTRAINT chk_universe_showdown_cfg_mountain CHECK (timezone = 'America/Denver')
);

-- Table: stream_capacity_queue
CREATE TABLE IF NOT EXISTS stream_capacity_queue (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
    user_id UUID REFERENCES profiles(id) ON DELETE CASCADE,
    guest_id TEXT, -- For guest users (TC-* format)
    status TEXT NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting', 'cancelled', 'expired')),
    requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    -- Ensure only one active queue entry per user per stream
    UNIQUE(stream_id, user_id, status) DEFERRABLE INITIALLY DEFERRED,
    UNIQUE(stream_id, guest_id, status) DEFERRABLE INITIALLY DEFERRED,

    -- At least one of user_id or guest_id must be provided
    CHECK (user_id IS NOT NULL OR guest_id IS NOT NULL)
);

-- Table: saved_cards
create table if not exists public.saved_cards (
  id uuid primary key default gen_random_uuid(),

  -- User relationship
  user_id uuid not null references public.user_profiles(id) on delete cascade,

  -- Square integration (required for charging)
  square_customer_id text not null,  -- Square customer ID
  square_card_id text not null,      -- Square card-on-file ID (starts with 'ccof:')

  -- Card metadata (for display/UI)
  brand text not null,               -- 'Visa', 'Mastercard', 'American Express', etc.
  last_4 text not null,              -- Last 4 digits for display
  exp_month integer not null,        -- Expiration month (1-12)
  exp_year integer not null,         -- Expiration year (4 digits)

  -- Status and preferences
  status text not null default 'active',  -- 'active', 'expired', 'disabled'
  is_default boolean not null default false,

  -- Timestamps
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Table: admin_app_settings
CREATE TABLE IF NOT EXISTS public.admin_app_settings (
    setting_key TEXT PRIMARY KEY,
    setting_value JSONB NOT NULL,
    description TEXT,
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    updated_by UUID REFERENCES auth.users(id)
);

-- Table: broadcast_officers
CREATE TABLE IF NOT EXISTS broadcast_officers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  broadcaster_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  officer_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  UNIQUE(broadcaster_id, officer_id)
);

-- Table: troll_battles
CREATE TABLE IF NOT EXISTS public.troll_battles (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    player1_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    player2_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    player1_score INTEGER DEFAULT 0,
    player2_score INTEGER DEFAULT 0,
    status TEXT CHECK (status IN ('pending', 'active', 'completed', 'cancelled')) DEFAULT 'pending',
    start_time TIMESTAMP WITH TIME ZONE,
    end_time TIMESTAMP WITH TIME ZONE,
    winner_id UUID REFERENCES public.user_profiles(id),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: pitch_contests
CREATE TABLE IF NOT EXISTS public.pitch_contests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title TEXT,
    description TEXT,
    status TEXT,
    created_by UUID REFERENCES public.user_profiles(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: creator_migration_claims
CREATE TABLE public.creator_migration_claims (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    platform_name TEXT NOT NULL,
    platform_user_id TEXT NOT NULL,
    platform_profile_url TEXT,
    proof_screenshot_url TEXT,
    verification_status TEXT DEFAULT 'pending', -- pending, approved, rejected
    rejection_reason TEXT,
    reviewed_by UUID REFERENCES public.user_profiles(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(user_id)
);

-- Table: user_credit
CREATE TABLE IF NOT EXISTS public.user_credit (
  user_id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  score INTEGER NOT NULL DEFAULT 400 CHECK (score >= 0 AND score <= 800),
  tier TEXT NOT NULL DEFAULT 'Building',
  trend_7d SMALLINT NOT NULL DEFAULT 0, -- -1, 0, +1
  loan_reliability NUMERIC(5,2) NOT NULL DEFAULT 0, -- explanatory submetric (0-100)
  components JSONB, -- optional debug/admin detail
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_event_at TIMESTAMPTZ
);

-- Table: credit_events
CREATE TABLE IF NOT EXISTS public.credit_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL,
  delta INTEGER NOT NULL,
  event_key TEXT, -- idempotency key
  source_table TEXT, -- e.g., loan_payments, moderation_actions
  source_id UUID,
  metadata JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: badge_catalog
create table if not exists badge_catalog (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  description text not null,
  category text not null,
  icon_url text null,
  rarity text not null default 'common',
  sort_order int not null default 100,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

-- Table: user_badges
create table if not exists user_badges (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  badge_id uuid not null references badge_catalog(id) on delete cascade,
  earned_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  unique(user_id, badge_id)
);

-- Table: daily_login_posts
CREATE TABLE IF NOT EXISTS public.daily_login_posts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  post_id UUID NOT NULL REFERENCES public.troll_wall_posts(id) ON DELETE CASCADE,
  coins_earned INTEGER NOT NULL DEFAULT 0 CHECK (coins_earned >= 0 AND coins_earned <= 100),
  posted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: admin_settings
CREATE TABLE IF NOT EXISTS public.admin_settings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    setting_key TEXT NOT NULL UNIQUE,
    setting_value JSONB DEFAULT '{}',
    description TEXT,
    updated_by UUID REFERENCES auth.users(id),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: pool_donations
CREATE TABLE IF NOT EXISTS public.pool_donations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES auth.users(id),
    amount NUMERIC(18, 2) NOT NULL CHECK (amount > 0),
    message TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: coin_audit_log
CREATE TABLE IF NOT EXISTS public.coin_audit_log (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid REFERENCES public.user_profiles(id),
    action text NOT NULL,
    details jsonb DEFAULT '{}'::jsonb,
    created_at timestamptz DEFAULT now()
);

-- Table: sidebar_updates
CREATE TABLE IF NOT EXISTS public.sidebar_updates (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    path TEXT NOT NULL,
    category TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    active BOOLEAN DEFAULT TRUE
);

-- Table: user_sidebar_views
CREATE TABLE IF NOT EXISTS public.user_sidebar_views (
    user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
    path TEXT NOT NULL,
    last_viewed_at TIMESTAMPTZ DEFAULT NOW(),
    PRIMARY KEY (user_id, path)
);

-- Table: service_listings
CREATE TABLE IF NOT EXISTS public.service_listings (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    business_id UUID NOT NULL REFERENCES public.business_profiles(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    description TEXT,
    price_type TEXT CHECK (price_type IN ('fixed', 'hourly', 'quote', 'free')) DEFAULT 'quote',
    price_coins INTEGER,
    price_usd NUMERIC,
    category TEXT,
    subcategory TEXT,
    is_remote BOOLEAN DEFAULT false,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    city TEXT,
    state TEXT,
    duration_minutes INTEGER,
    images JSONB DEFAULT '[]',
    status TEXT CHECK (status IN ('active', 'paused', 'flagged')) DEFAULT 'active',
    views INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: paypal_transactions
CREATE TABLE IF NOT EXISTS public.paypal_transactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id),
    paypal_order_id TEXT NOT NULL UNIQUE,
    paypal_capture_id TEXT,
    amount NUMERIC,
    currency TEXT,
    coins BIGINT,
    status TEXT NOT NULL, -- 'completed', 'credited'
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: marketplace_reviews
CREATE TABLE IF NOT EXISTS public.marketplace_reviews (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    order_id UUID NOT NULL,
    seller_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    buyer_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    listing_id UUID,
    listing_type TEXT CHECK (listing_type IN ('marketplace', 'vehicle', 'service')) DEFAULT 'marketplace',
    rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
    comment TEXT,
    images JSONB DEFAULT '[]',
    delivery_rating INTEGER CHECK (delivery_rating >= 1 AND delivery_rating <= 5),
    item_as_described BOOLEAN DEFAULT true,
    would_recommend BOOLEAN DEFAULT true,
    is_verified_purchase BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    
    CONSTRAINT unique_order_seller_review UNIQUE (order_id, seller_id)
);

-- Table: pitches
CREATE TABLE IF NOT EXISTS public.pitches (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    contest_id UUID REFERENCES public.pitch_contests(id) ON DELETE CASCADE NOT NULL,
    user_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    title TEXT NOT NULL,
    description TEXT,
    status TEXT DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
    vote_count INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: revenue_splits
CREATE TABLE IF NOT EXISTS public.revenue_splits (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pitch_id UUID REFERENCES public.pitches(id) ON DELETE CASCADE NOT NULL,
    recipient_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    percentage NUMERIC NOT NULL CHECK (percentage > 0 AND percentage <= 100),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: church_passages
CREATE TABLE IF NOT EXISTS public.church_passages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    date DATE NOT NULL UNIQUE,
    reference TEXT NOT NULL,
    text TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- Table: church_prayers
CREATE TABLE IF NOT EXISTS public.church_prayers (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT now(),
    likes_count INTEGER DEFAULT 0
);

-- Table: church_prayer_likes
CREATE TABLE IF NOT EXISTS public.church_prayer_likes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    prayer_id UUID NOT NULL REFERENCES public.church_prayers(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(prayer_id, user_id)
