-- Table: church_sermon_notes
CREATE TABLE IF NOT EXISTS public.church_sermon_notes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pastor_id UUID NOT NULL REFERENCES public.user_profiles(id),
    date DATE NOT NULL,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(pastor_id, date)
);

-- Table: audit_logs
CREATE TABLE IF NOT EXISTS audit_logs (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    action text NOT NULL,
    user_id uuid REFERENCES public.user_profiles(id),
    target_id uuid,
    details jsonb,
    created_at timestamptz DEFAULT now(),
    ip_address text
);

-- Table: officer_shift_slots
CREATE TABLE IF NOT EXISTS public.officer_shift_slots (
    id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
    officer_id uuid REFERENCES public.user_profiles(id),
    shift_date date NOT NULL,
    shift_start_time time NOT NULL,
    shift_end_time time NOT NULL,
    status text CHECK (status IN ('scheduled', 'active', 'completed', 'cancelled')) DEFAULT 'scheduled',
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now()
);

-- Table: officer_chat_messages
CREATE TABLE IF NOT EXISTS officer_chat_messages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  sender_id UUID REFERENCES user_profiles(id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  message_type TEXT DEFAULT 'chat', -- chat, alert, command
  priority TEXT DEFAULT 'normal', -- normal, high, urgent
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: stream_reports
CREATE TABLE IF NOT EXISTS stream_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL, -- Can reference streams(id) but sometimes we might keep reports for deleted streams
  reporter_id UUID REFERENCES user_profiles(id),
  reason TEXT NOT NULL,
  status TEXT DEFAULT 'pending', -- pending, resolved, dismissed
  created_at TIMESTAMPTZ DEFAULT NOW(),
  resolved_at TIMESTAMPTZ,
  resolved_by UUID REFERENCES user_profiles(id)
);

-- Table: admin_for_week_queue
CREATE TABLE IF NOT EXISTS public.admin_for_week_queue (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    status TEXT DEFAULT 'pending', -- pending, active, completed
    amount_paid INTEGER DEFAULT 100000
);

-- Table: properties
CREATE TABLE IF NOT EXISTS public.properties (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    owner_id UUID REFERENCES public.user_profiles(id), -- Null means System/Bank owned
    type_id TEXT REFERENCES public.property_types(id) DEFAULT 'apartment',
    name TEXT NOT NULL,
    address TEXT,
    rent_amount INTEGER NOT NULL,
    utility_cost INTEGER NOT NULL,
    is_for_rent BOOLEAN DEFAULT true,
    description TEXT,
    image_url TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: leases
CREATE TABLE IF NOT EXISTS public.leases (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    property_id UUID REFERENCES public.properties(id),
    tenant_id UUID REFERENCES public.user_profiles(id),
    start_date TIMESTAMPTZ DEFAULT NOW(),
    end_date TIMESTAMPTZ,
    rent_due_day INTEGER DEFAULT 1,
    last_rent_paid_at TIMESTAMPTZ,
    last_utility_paid_at TIMESTAMPTZ,
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'ended', 'evicted')),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(property_id, tenant_id, status)
);

-- Table: rent_payment_log
CREATE TABLE IF NOT EXISTS public.rent_payment_log (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    lease_id UUID REFERENCES public.leases(id),
    tenant_id UUID REFERENCES public.user_profiles(id),
    amount_paid INTEGER NOT NULL,
    rent_portion INTEGER NOT NULL,
    utility_portion INTEGER NOT NULL,
    tax_portion INTEGER NOT NULL, -- 10% of rent
    landlord_portion INTEGER NOT NULL, -- 90% of rent
    paid_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: apartment_applications
CREATE TABLE IF NOT EXISTS public.apartment_applications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    property_id UUID REFERENCES public.properties(id),
    applicant_id UUID REFERENCES public.user_profiles(id),
    status TEXT DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
    message TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: bank_loans
CREATE TABLE IF NOT EXISTS public.bank_loans (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.user_profiles(id),
    loan_type TEXT NOT NULL CHECK (loan_type IN ('rent_loan', 'deposit_loan')),
    amount INTEGER NOT NULL,
    remaining_balance INTEGER NOT NULL,
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'paid', 'defaulted')),
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: user_purchases
CREATE TABLE IF NOT EXISTS user_purchases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  item_type VARCHAR(50) NOT NULL,
  item_id VARCHAR(255) NOT NULL,
  item_name VARCHAR(255),
  purchase_price INTEGER NOT NULL,
  is_active BOOLEAN DEFAULT false,
  purchased_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  expires_at TIMESTAMP,
  metadata JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Table: user_active_items
CREATE TABLE IF NOT EXISTS user_active_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  item_category VARCHAR(50) NOT NULL,
  item_id VARCHAR(255) NOT NULL,
  activated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, item_category)
);

-- Table: user_avatar_customization
CREATE TABLE IF NOT EXISTS user_avatar_customization (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  head_item_id VARCHAR(50),
  face_item_id VARCHAR(50),
  body_item_id VARCHAR(50),
  legs_item_id VARCHAR(50),
  feet_item_id VARCHAR(50),
  accessories_ids TEXT[],
  skin_tone VARCHAR(50),
  hair_color VARCHAR(50),
  beard_style VARCHAR(50),
  avatar_config JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id)
);

-- Table: troll_mart_clothing
CREATE TABLE IF NOT EXISTS troll_mart_clothing (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name VARCHAR(255) NOT NULL,
  category VARCHAR(50) NOT NULL,
  item_code VARCHAR(50) UNIQUE NOT NULL,
  price_coins INTEGER NOT NULL,
  image_url TEXT,
  model_url TEXT,
  description TEXT,
  rarity VARCHAR(50) DEFAULT 'common',
  is_active BOOLEAN DEFAULT true,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Table: user_troll_mart_purchases
CREATE TABLE IF NOT EXISTS user_troll_mart_purchases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  clothing_id UUID NOT NULL REFERENCES troll_mart_clothing(id) ON DELETE CASCADE,
  purchased_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(user_id, clothing_id)
);

-- Table: troll_wars_tasks
CREATE TABLE IF NOT EXISTS public.troll_wars_tasks (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    task_id TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    description TEXT,
    tier TEXT DEFAULT 'easy',
    category TEXT DEFAULT 'general',
    progress_type TEXT DEFAULT 'count',
    target_value INTEGER DEFAULT 1,
    is_repeatable BOOLEAN DEFAULT false,
    reset_cycle TEXT DEFAULT 'weekly',
    is_active BOOLEAN DEFAULT true,
    reward_schema JSONB DEFAULT '{}',
    completion_conditions JSONB DEFAULT '{}',
    dependencies TEXT[] DEFAULT '{}',
    failure_conditions JSONB DEFAULT '{}',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Table: troll_post_reactions
CREATE TABLE IF NOT EXISTS public.troll_post_reactions (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    post_id UUID REFERENCES public.troll_posts(id) ON DELETE CASCADE,
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    reaction_type TEXT DEFAULT 'like',
    created_at TIMESTAMPTZ DEFAULT now(),
    UNIQUE(post_id, user_id, reaction_type)
);

-- Table: troll_posts
CREATE TABLE IF NOT EXISTS public.troll_posts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE NOT NULL,
    content TEXT,
    post_type TEXT DEFAULT 'text',
    image_url TEXT,
    video_url TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: president_elections
create table if not exists president_elections (
  id uuid primary key default gen_random_uuid(),
  status text not null check (status in ('draft', 'open', 'closed', 'finalized', 'void')),
  starts_at timestamptz not null default now(),
  ends_at timestamptz not null,
  created_by uuid references user_profiles(id),
  created_at timestamptz not null default now(),
  winner_candidate_id uuid,
  metadata jsonb default '{}'::jsonb
);

-- Table: president_votes
create table if not exists president_votes (
  id uuid primary key default gen_random_uuid(),
  election_id uuid references president_elections(id),
  candidate_id uuid references president_candidates(id),
  voter_id uuid references user_profiles(id),
  created_at timestamptz default now()
);

-- Table: president_appointments
create table if not exists president_appointments (
  id uuid primary key default gen_random_uuid(),
  president_user_id uuid not null references user_profiles(id),
  vice_president_user_id uuid not null references user_profiles(id),
  starts_at timestamptz not null default now(),
  ends_at timestamptz not null,
  status text not null default 'active' check (status in ('active', 'removed', 'expired')),
  created_at timestamptz not null default now(),
  removed_at timestamptz,
  removed_by uuid references user_profiles(id),
  metadata jsonb default '{}'::jsonb
);

-- Table: user_vehicle_upgrades
CREATE TABLE IF NOT EXISTS public.user_vehicle_upgrades (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_vehicle_id UUID REFERENCES public.user_vehicles(id) ON DELETE CASCADE,
    upgrade_id UUID REFERENCES public.car_upgrades(id) ON DELETE CASCADE,
    installed_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(user_vehicle_id, upgrade_id)
);

-- Table: stream_seat_sessions
CREATE TABLE IF NOT EXISTS public.stream_seat_sessions (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    stream_id UUID NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    seat_index INTEGER NOT NULL,
    price_paid INTEGER DEFAULT 0,
    joined_at TIMESTAMPTZ DEFAULT now(),
    left_at TIMESTAMPTZ,
    status TEXT NOT NULL CHECK (status IN ('active', 'left', 'kicked', 'disconnected')),
    kick_reason TEXT
);

-- Table: stream_viewers
CREATE TABLE IF NOT EXISTS public.stream_viewers (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    stream_id UUID REFERENCES public.streams(id) ON DELETE CASCADE,
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    joined_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (stream_id, user_id)
);

-- Table: court_sessions
CREATE TABLE IF NOT EXISTS public.court_sessions (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    case_id UUID NOT NULL,
    status TEXT DEFAULT 'waiting',
    started_by UUID,
    started_at TIMESTAMPTZ,
    ended_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: court_session_state
CREATE TABLE IF NOT EXISTS public.court_session_state (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    case_id UUID NOT NULL UNIQUE,
    phase TEXT DEFAULT 'waiting',
    status TEXT DEFAULT 'active',
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: court_summons
CREATE TABLE IF NOT EXISTS public.court_summons (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    case_id UUID REFERENCES public.court_cases(id) ON DELETE CASCADE,
    served_to UUID REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    served_at TIMESTAMPTZ DEFAULT NOW(),
    served_by UUID REFERENCES public.user_profiles(id) ON DELETE SET NULL,
    status TEXT DEFAULT 'pending' CHECK (status IN ('pending', 'served', 'accepted', 'rejected', 'expired')),
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: user_follows
CREATE TABLE IF NOT EXISTS public.user_follows (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    follower_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    following_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE(follower_id, following_id)
);

-- Table: user_abilities
CREATE TABLE IF NOT EXISTS public.user_abilities (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  ability_id TEXT NOT NULL,
  quantity INTEGER NOT NULL DEFAULT 1,
  cooldown_until TIMESTAMPTZ,
  won_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(user_id, ability_id)
);

-- Table: broadcast_active_effects
CREATE TABLE IF NOT EXISTS public.broadcast_active_effects (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id TEXT NOT NULL,
  ability_id TEXT NOT NULL,
  activator_id UUID NOT NULL REFERENCES public.user_profiles(id),
  activator_username TEXT NOT NULL,
  target_user_id UUID REFERENCES public.user_profiles(id),
  target_username TEXT,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  data JSONB DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Table: broadcast_ability_logs
CREATE TABLE IF NOT EXISTS public.broadcast_ability_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id TEXT NOT NULL,
  ability_id TEXT NOT NULL,
  activator_id UUID NOT NULL REFERENCES public.user_profiles(id),
  activator_username TEXT NOT NULL,
  target_user_id UUID REFERENCES public.user_profiles(id),
  target_username TEXT,
  amount INTEGER,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Table: daily_free_spins
CREATE TABLE IF NOT EXISTS public.daily_free_spins (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  spins_date DATE NOT NULL DEFAULT CURRENT_DATE,
  spins_used INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(user_id, spins_date)
);

-- Table: trollmers_tournament_participants
CREATE TABLE IF NOT EXISTS public.trollmers_tournament_participants (
    tournament_id UUID NOT NULL REFERENCES public.trollmers_monthly_tournaments(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    seed INTEGER,
    status TEXT NOT NULL DEFAULT 'qualified' CHECK (status IN ('qualified', 'active', 'eliminated', 'winner')),
    joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (tournament_id, user_id)
);

-- Table: trollmers_tournament_battles
CREATE TABLE IF NOT EXISTS public.trollmers_tournament_battles (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tournament_id UUID NOT NULL REFERENCES public.trollmers_monthly_tournaments(id) ON DELETE CASCADE,
    battle_id UUID REFERENCES public.battles(id) ON DELETE SET NULL,
    round INTEGER NOT NULL CHECK (round > 0),
    bracket_position INTEGER NOT NULL,
    participant1_id UUID REFERENCES public.user_profiles(id),
    participant2_id UUID REFERENCES public.user_profiles(id),
    winner_id UUID REFERENCES public.user_profiles(id),
    status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'completed')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: trollmers_weekly_leaderboard
CREATE TABLE IF NOT EXISTS public.trollmers_weekly_leaderboard (
    week_start DATE NOT NULL,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    battles_played INTEGER NOT NULL DEFAULT 0,
    wins INTEGER NOT NULL DEFAULT 0,
    losses INTEGER NOT NULL DEFAULT 0,
    draws INTEGER NOT NULL DEFAULT 0,
    coins_earned BIGINT NOT NULL DEFAULT 0,
    score BIGINT NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (week_start, user_id)
);

-- Table: trollmers_weekly_payouts
CREATE TABLE IF NOT EXISTS public.trollmers_weekly_payouts (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    week_start DATE NOT NULL,
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    rank INTEGER NOT NULL CHECK (rank BETWEEN 1 AND 3),
    payout_coins BIGINT NOT NULL CHECK (payout_coins >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (week_start, rank)
);

-- Table: officer_performance
CREATE TABLE IF NOT EXISTS public.officer_performance (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    officer_id uuid REFERENCES auth.users(id),
    zip_code_id uuid REFERENCES public.zip_codes(id),
    warnings_issued integer DEFAULT 0,
    temp_bans integer DEFAULT 0,
    perm_bans integer DEFAULT 0,
    resolved_cases integer DEFAULT 0,
    escalations_to_lead integer DEFAULT 0,
    false_reports integer DEFAULT 0,
    abuse_flags integer DEFAULT 0,
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now()
);

-- Table: officer_corruption_flags
CREATE TABLE IF NOT EXISTS public.officer_corruption_flags (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    officer_id uuid REFERENCES auth.users(id),
    reason text NOT NULL,
    severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high')),
    resolved boolean DEFAULT false,
    created_at timestamptz DEFAULT now()
);

-- Table: officer_payroll_logs
CREATE TABLE IF NOT EXISTS public.officer_payroll_logs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    officer_id uuid NOT NULL REFERENCES auth.users(id),
    role text NOT NULL,
    pay_period_start date NOT NULL,
    pay_period_end date NOT NULL,
    base_pay bigint NOT NULL DEFAULT 0,
    bonus_pay bigint NOT NULL DEFAULT 0,
    total_paid bigint NOT NULL DEFAULT 0,
    status text NOT NULL CHECK (status IN ('paid', 'prorated', 'skipped', 'frozen')),
    reason text,
    pool_balance_before bigint,
    pool_balance_after bigint,
    created_at timestamptz NOT NULL DEFAULT now(),
    metadata jsonb NOT NULL DEFAULT '{}'::jsonb
);

-- Table: stock_transactions
CREATE TABLE IF NOT EXISTS stock_transactions (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
            stock_id UUID REFERENCES stocks(id) ON DELETE CASCADE,
            transaction_type VARCHAR(10) CHECK (transaction_type IN ('buy', 'sell')),
            shares DECIMAL(20,8),
            price_per_share DECIMAL(15,2),
            total_amount DECIMAL(20,2),
            coins_before DECIMAL(20,2),
            coins_after DECIMAL(20,2),
            created_at TIMESTAMPTZ DEFAULT NOW()
        );

-- Table: user_advertisements
CREATE TABLE IF NOT EXISTS public.user_advertisements (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    subtitle TEXT,
    description TEXT,
    image_url TEXT NOT NULL,
    link_url TEXT,
    status TEXT NOT NULL DEFAULT 'pending', -- pending, approved, denied, expired
    cost_paid BIGINT NOT NULL DEFAULT 1000,
    submitted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    approved_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,
    denied_at TIMESTAMP WITH TIME ZONE,
    denied_reason TEXT,
    approved_by UUID REFERENCES public.user_profiles(id),
    clicks_count INTEGER DEFAULT 0,
    impressions_count INTEGER DEFAULT 0,
    placement TEXT NOT NULL DEFAULT 'any' -- any, sidebar, banner
);

-- Table: stream_settings
CREATE TABLE IF NOT EXISTS public.stream_settings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  paid_chat_enabled BOOLEAN DEFAULT false,
  paid_chat_type TEXT DEFAULT 'per_user',
  paid_chat_price INTEGER DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(stream_id)
);

-- Table: tcps_messages
CREATE TABLE public.tcps_messages (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  conversation_id UUID NOT NULL,
  sender_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  sender_profile JSONB,
  read_at TIMESTAMPTZ,
  is_deleted BOOLEAN DEFAULT FALSE
);

-- Table: small_installment_purchases
CREATE TABLE IF NOT EXISTS public.small_installment_purchases (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id             UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    -- Purchase details
    original_price      BIGINT NOT NULL,          -- ⚠  must be < 100 troll coins
    purchase_context    TEXT NOT NULL,             -- 'shop_purchase' | 'insurance_purchase' | …
    item_type           TEXT,                      -- coinTransactions type
    item_id             TEXT,
    item_name           TEXT,
    -- Payment progress
    total_paid          BIGINT NOT NULL DEFAULT 0,
    remaining_balance   BIGINT GENERATED ALWAYS AS (GREATEST(0, original_price - total_paid)) STORED,
    milestone_level     SMALLINT NOT NULL DEFAULT 0,   -- 0=0%,1=25%,2=50%,3=75%,4=100%
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    fully_paid_at       TIMESTAMPTZ,
    -- Audit
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at          TIMESTAMPTZ               -- 30-day inactivity grace period
);

-- Table: stream_audience_presence
CREATE TABLE IF NOT EXISTS public.stream_audience_presence (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  stream_id TEXT NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES user_profiles(id) ON DELETE CASCADE,
  username TEXT NOT NULL,
  avatar_url TEXT,
  joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  left_at TIMESTAMPTZ,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  gift_total INTEGER NOT NULL DEFAULT 0,
  seat_id INTEGER, -- References stream_seats.seat_index (integer)
  role TEXT NOT NULL DEFAULT 'audience' CHECK (role IN ('audience', 'seat', 'broadcaster')),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(stream_id, user_id)
);

-- Table: admin_actions_log
CREATE TABLE IF NOT EXISTS public.admin_actions_log (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    admin_user_id UUID REFERENCES public.user_profiles(id) NOT NULL,
    target_user_id UUID REFERENCES public.user_profiles(id),
    action_type TEXT NOT NULL,
    reason TEXT,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: city_events
CREATE TABLE IF NOT EXISTS public.city_events (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    event_type TEXT NOT NULL, -- 'double_xp', 'themed_night', etc.
    label TEXT NOT NULL,
    active_until TIMESTAMPTZ NOT NULL,
    created_by UUID REFERENCES public.user_profiles(id),
    created_at TIMESTAMPTZ DEFAULT NOW(),
    is_active BOOLEAN DEFAULT true
);

-- Table: user_presence
CREATE TABLE IF NOT EXISTS public.user_presence (
  user_id UUID PRIMARY KEY REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  is_online BOOLEAN NOT NULL DEFAULT true,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Table: bug_alerts
CREATE TABLE IF NOT EXISTS bug_alerts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  
  -- Core fields
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  severity bug_alert_severity DEFAULT 'medium',
  category bug_alert_category DEFAULT 'other',
  status bug_alert_status DEFAULT 'active',
  
  -- Reporter info
  reported_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  reported_by_username TEXT,
  
  -- Affected entities
  affected_users TEXT[] DEFAULT '{}',
  affected_components TEXT[] DEFAULT '{}',
  
  -- Error details
  error_message TEXT,
  stack_trace TEXT,
  user_agent TEXT,
  page_url TEXT,
  
  -- Additional metadata (JSON for flexibility)
  metadata JSONB DEFAULT '{}',
  
  -- Resolution tracking
  acknowledged_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  acknowledged_at TIMESTAMPTZ,
  resolved_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  resolved_at TIMESTAMPTZ,
  admin_notes TEXT
);

-- Table: neighbors_events
CREATE TABLE IF NOT EXISTS neighbors_events (
