-- Table: role_earning_rules
CREATE TABLE IF NOT EXISTS public.role_earning_rules (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    role_key text NOT NULL UNIQUE,
    role_label text NOT NULL,
