-- Table: court_cases
CREATE TABLE IF NOT EXISTS public.court_cases (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    plaintiff_id UUID REFERENCES public.user_profiles(id), -- Landlord or System
    defendant_id UUID REFERENCES public.user_profiles(id), -- Tenant
    lease_id UUID REFERENCES public.leases(id),
    case_type TEXT NOT NULL CHECK (case_type IN ('non_payment', 'eviction', 'lease_violation')),
    status TEXT DEFAULT 'open' CHECK (status IN ('open', 'ruled', 'dismissed')),
    details TEXT,
    ruling TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table: marketplace_items
CREATE TABLE IF NOT EXISTS public.marketplace_items (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    seller_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    description TEXT,
    price_coins INTEGER,
    price_usd NUMERIC,
    category TEXT,
    subcategory TEXT,
    condition TEXT CHECK (condition IN ('new', 'like_new', 'good', 'fair', 'poor')),
    delivery_type TEXT CHECK (delivery_type IN ('shipping', 'pickup', 'both')) DEFAULT 'both',
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    city TEXT,
    state TEXT,
    images JSONB DEFAULT '[]',
    stock INTEGER DEFAULT 1,
    status TEXT CHECK (status IN ('active', 'sold', 'hidden', 'flagged')) DEFAULT 'active',
    is_vehicle BOOLEAN DEFAULT false,
    views INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Table: president_candidates
create table if not exists president_candidates (
  id uuid primary key default gen_random_uuid(),
  election_id uuid not null references president_elections(id) on delete cascade,
  user_id uuid not null references user_profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected', 'withdrawn')),
  banner_path text not null,
  display_name text,
  slogan text,
  statement text,
  created_at timestamptz not null default now(),
  approved_by uuid references user_profiles(id),
  approved_at timestamptz,
  unique(election_id, user_id)
);

-- Table: user_leagues
CREATE TABLE IF NOT EXISTS public.user_leagues (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    description TEXT,
    creator_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    max_members INT DEFAULT 50,
    is_active BOOLEAN DEFAULT true,
    is_public BOOLEAN DEFAULT true,
    league_type TEXT DEFAULT 'standard' CHECK (league_type IN ('standard', 'competitive', 'casual', 'tournament')),
    icon_emoji TEXT DEFAULT '🏆',
    color TEXT DEFAULT '#8b5cf6',
    league_score BIGINT DEFAULT 0,
    league_level INT DEFAULT 1,
    member_count INT DEFAULT 1,
    requirements JSONB DEFAULT '{"min_level": 0, "invite_only": false}'::jsonb,
    metadata JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- ==================== VIEWS ====================
-- View: active_safety_alerts_view
CREATE OR REPLACE VIEW active_safety_alerts_view AS
SELECT 
    sa.id,
    sa.stream_id,
    sa.user_id,
    up.username as user_username,
    s.title as stream_title,
    sa.trigger_type,
    sa.trigger_phrase,
    sa.alert_level,
    sa.audio_chunk_timestamp,
    sa.created_at,
    sa.reviewed_by,
    reviewer.username as reviewer_username,
    sa.action_taken,
    sa.reviewed_at,
    sam.total_triggers,
    CASE 
        WHEN sa.alert_level = 3 THEN 'HIGH PRIORITY'
        WHEN sa.alert_level = 2 THEN 'FLAGGED'
        ELSE 'NOTIFICATION'
    END as alert_status
FROM safety_alerts sa
JOIN user_profiles up ON sa.user_id = up.id
LEFT JOIN streams s ON sa.stream_id = s.id
LEFT JOIN user_profiles reviewer ON sa.reviewed_by = reviewer.id
LEFT JOIN stream_audio_monitoring sam ON sa.stream_id = sam.stream_id
WHERE sa.reviewed_by IS NULL
ORDER BY sa.alert_level DESC, sa.created_at DESC;

-- View: admin_view_active_streams
CREATE OR REPLACE VIEW public.admin_view_active_streams AS
SELECT 
    COUNT(*) as active_streams_count,
    COALESCE(SUM(viewer_count), 0) as total_viewers
FROM public.streams
WHERE is_live = true;

-- View: earnings_view
CREATE OR REPLACE VIEW earnings_view AS
WITH gift_earnings AS (
    SELECT 
      receiver_id AS user_id,
      DATE_TRUNC('month', created_at) AS month,
      SUM(coins_spent) AS total_coins_earned,
      COUNT(id) AS gift_count
    FROM gifts
    GROUP BY receiver_id, DATE_TRUNC('month', created_at)
  ),
  transaction_earnings AS (
    SELECT 
      user_id,
      DATE_TRUNC('month', created_at) AS month,
      SUM(amount) AS total_coins_earned,
      COUNT(id) AS transaction_count
    FROM coin_transactions
    WHERE type IN ('gift_receive', 'stream_income', 'referral_bonus') 
      AND amount > 0
    GROUP BY user_id, DATE_TRUNC('month', created_at)
  ),
  combined_earnings AS (
    SELECT 
      COALESCE(g.user_id, t.user_id) AS user_id,
      COALESCE(g.month, t.month) AS month,
      COALESCE(g.total_coins_earned, 0) + COALESCE(t.total_coins_earned, 0) AS total_coins,
      COALESCE(g.gift_count, 0) + COALESCE(t.transaction_count, 0) AS transaction_count
    FROM gift_earnings g
    FULL OUTER JOIN transaction_earnings t 
      ON g.user_id = t.user_id AND g.month = t.month
  ),
  payout_summary AS (
    SELECT 
      user_id,
      DATE_TRUNC('month', created_at) AS month,
      SUM(CASE WHEN status = 'paid' THEN COALESCE(cash_amount, 0) ELSE 0 END) AS paid_out_usd,
      SUM(CASE WHEN status = 'pending' THEN COALESCE(cash_amount, 0) ELSE 0 END) AS pending_usd,
      SUM(CASE WHEN status = 'approved' THEN COALESCE(cash_amount, 0) ELSE 0 END) AS approved_usd,
      COUNT(*) FILTER (WHERE status = 'paid') AS paid_count,
      COUNT(*) FILTER (WHERE status = 'pending') AS pending_count
    FROM payout_requests
    GROUP BY user_id, DATE_TRUNC('month', created_at)
  ),
  yearly_payouts AS (
    SELECT 
      user_id,
      DATE_PART('year', created_at)::int AS year,
      SUM(COALESCE(cash_amount, 0)) AS total_paid_usd,
      COUNT(*) AS payout_count
    FROM payout_requests
    WHERE status = 'paid'
    GROUP BY user_id, DATE_PART('year', created_at)
  )
SELECT 
  p.id,
  p.username,
  p.total_earned_coins,
  p.troll_coins,
  COALESCE(ce.total_coins, 0) AS current_month_earnings,
  COALESCE(ce.transaction_count, 0) AS current_month_transactions,
  COALESCE(ps.paid_out_usd, 0) AS current_month_paid_out,
  COALESCE(ps.pending_usd, 0) AS current_month_pending,
  COALESCE(ps.approved_usd, 0) AS current_month_approved,
  COALESCE(ps.paid_count, 0) AS current_month_paid_count,
  COALESCE(ps.pending_count, 0) AS current_month_pending_count,
  COALESCE(yp.total_paid_usd, 0) AS yearly_paid_usd,
  COALESCE(yp.payout_count, 0) AS yearly_payout_count,
  COALESCE(yp.year, DATE_PART('year', NOW())::int) AS tax_year,
  CASE 
    WHEN COALESCE(yp.total_paid_usd, 0) >= 600 THEN 'over_threshold'
    WHEN COALESCE(yp.total_paid_usd, 0) >= 500 THEN 'nearing_threshold'
    ELSE 'below_threshold'
  END AS irs_threshold_status,
  (SELECT MAX(pr.created_at) FROM payout_requests pr WHERE pr.user_id = p.id AND pr.status = 'paid') AS last_payout_at,
  (SELECT COUNT(*) FROM payout_requests pr WHERE pr.user_id = p.id AND pr.status = 'pending') AS pending_requests_count,
  (SELECT SUM(COALESCE(pr.cash_amount, 0)) FROM payout_requests pr WHERE pr.user_id = p.id AND pr.status = 'paid') AS lifetime_paid_usd
FROM user_profiles p
LEFT JOIN combined_earnings ce 
  ON ce.user_id = p.id 
  AND ce.month = DATE_TRUNC('month', NOW())
LEFT JOIN payout_summary ps 
  ON ps.user_id = p.id 
  AND ps.month = DATE_TRUNC('month', NOW())
LEFT JOIN yearly_payouts yp 
  ON yp.user_id = p.id 
  AND yp.year = DATE_PART('year', NOW())::int
WHERE p.is_broadcaster = true OR p.total_earned_coins > 0;

-- View: monthly_earnings_breakdown
CREATE OR REPLACE VIEW monthly_earnings_breakdown AS
SELECT 
  p.id AS user_id,
  p.username,
  DATE_TRUNC('month', g.created_at) AS month,
  SUM(g.coins_spent) AS coins_earned_from_gifts,
  COUNT(DISTINCT g.id) AS gift_count,
  COUNT(DISTINCT g.sender_id) AS unique_gifters,
  SUM(CASE WHEN g.gift_type = 'paid' THEN g.coins_spent ELSE 0 END) AS paid_coins_earned,
  SUM(CASE WHEN g.gift_type = 'free' THEN g.coins_spent ELSE 0 END) AS free_coins_earned
FROM user_profiles p
JOIN gifts g ON g.receiver_id = p.id
WHERE p.is_broadcaster = true OR p.total_earned_coins > 0
GROUP BY p.id, p.username, DATE_TRUNC('month', g.created_at)
ORDER BY month DESC, coins_earned_from_gifts DESC;

-- View: officer_rankings
CREATE OR REPLACE VIEW public.officer_rankings AS
SELECT
    officer_id,
    SUM(resolved_cases)
    - SUM(false_reports)
    - SUM(abuse_flags * 5)
    - SUM(escalations_to_lead * 2)
    AS performance_score
FROM public.officer_performance
GROUP BY officer_id;

-- View: payout_history_view
CREATE OR REPLACE VIEW public.payout_history_view AS
SELECT
    id,
    user_id,
    COALESCE(requested_coins, coins_redeemed, 0) AS coins_redeemed,
    COALESCE(amount_usd, cash_amount, 0) AS cash_amount,
    status,
    created_at,
    processed_at,
    'manual' AS type,
    NULL::uuid AS run_id
FROM
    public.payout_requests
UNION ALL
SELECT
    id,
    user_id,
    amount_coins AS coins_redeemed,
    amount_usd AS cash_amount,
    status,
    created_at,
    processed_at,
    'automated' AS type,
    run_id
FROM
    public.payouts;

-- View: president_treasury_balance
create or replace view president_treasury_balance as
select
  currency,
  coalesce(sum(amount_cents), 0) as balance_cents
from president_treasury_ledger
group by currency;

-- View: stream_monitoring_status_view
CREATE OR REPLACE VIEW stream_monitoring_status_view AS
SELECT 
    s.id as stream_id,
    s.title,
    s.category,
    up.id as user_id,
    up.username as broadcaster_name,
    s.is_live,
    s.current_viewers,
    sam.is_monitored,
    sam.monitoring_started_at,
    sam.total_triggers,
    sam.last_trigger_at,
    (SELECT COUNT(*) FROM safety_alerts 
     WHERE stream_id = s.id 
     AND reviewed_by IS NULL) as pending_alerts,
    (SELECT MAX(alert_level) FROM safety_alerts 
     WHERE stream_id = s.id 
     AND created_at > NOW() - INTERVAL '24 hours') as highest_alert_level
FROM streams s
JOIN user_profiles up ON s.user_id = up.id
LEFT JOIN stream_audio_monitoring sam ON s.id = sam.stream_id
WHERE s.is_live = true;

-- View: universe_showdown_public
CREATE OR REPLACE VIEW public.universe_showdown_public AS
SELECT
  b.id AS battle_id,
  b.event_date,
  b.scheduled_start,
  b.capacity,
  b.registered_count,
  b.guest_count,
  b.status AS battle_status,
  b.is_overflow,
  s.id AS signup_id,
  s.battle_name,
  s.is_guest,
  s.seat_index,
  s.status AS signup_status,
  s.created_at
FROM public.universe_showdown_battles b
JOIN public.universe_showdown_signups s ON s.battle_id = b.id
WHERE s.status = 'active' AND b.status <> 'cancelled';

-- View: universe_showdown_queue
CREATE OR REPLACE VIEW public.universe_showdown_queue AS
SELECT
  b.id AS battle_id,
  b.scheduled_start,
  s.id AS signup_id,
  s.battle_name,
  s.is_guest,
  s.seat_index,
  row_number() OVER (PARTITION BY b.id ORDER BY s.seat_index ASC) AS queue_position
FROM public.universe_showdown_battles b
JOIN public.universe_showdown_signups s ON s.battle_id = b.id
WHERE s.status = 'active' AND b.status IN ('open','full','sealed')
ORDER BY b.scheduled_start ASC, s.seat_index ASC;

-- View: user_earning_summary
CREATE OR REPLACE VIEW public.user_earning_summary AS
SELECT
    user_id,
    -- Total earned (lifetime)
    COALESCE(SUM(CASE WHEN status IN ('pending', 'approved', 'paid') THEN amount_coins ELSE 0 END), 0) as total_earned_coins,
    -- Pending earnings
    COALESCE(SUM(CASE WHEN status = 'pending' THEN amount_coins ELSE 0 END), 0) as pending_coins,
    -- Paid earnings
    COALESCE(SUM(CASE WHEN status = 'paid' THEN amount_coins ELSE 0 END), 0) as paid_coins,
    -- This week
    COALESCE(SUM(CASE WHEN status IN ('pending', 'approved', 'paid') AND created_at >= date_trunc('week', current_date) THEN amount_coins ELSE 0 END), 0) as week_earned_coins,
    -- This month
    COALESCE(SUM(CASE WHEN status IN ('pending', 'approved', 'paid') AND created_at >= date_trunc('month', current_date) THEN amount_coins ELSE 0 END), 0) as month_earned_coins,
    -- Last paid date
    MAX(CASE WHEN status = 'paid' THEN paid_at ELSE NULL::timestamptz END) as last_paid_at,
    -- Event counts
    COUNT(*) as total_events,
    COUNT(CASE WHEN status = 'pending' THEN 1 END) as pending_events,
    COUNT(CASE WHEN status = 'paid' THEN 1 END) as paid_events
FROM public.user_earning_events
GROUP BY user_id;

-- View: user_location_intelligence_view
CREATE OR REPLACE VIEW user_location_intelligence_view AS
SELECT 
    up.id as user_id,
    up.username,
    up.role,
    au.email,
    uit.ip_address,
    uit.city,
    uit.state,
    uit.region,
    uit.country,
    uit.country_code,
    uit.latitude,
    uit.longitude,
    uit.isp,
    uit.organization,
    uit.timezone,
    uit.geolocation_source as source,
    uit.created_at as last_seen
FROM user_ip_tracking uit
JOIN user_profiles up ON uit.user_id = up.id
JOIN auth.users au ON up.id = au.id
ORDER BY uit.created_at DESC;

-- View: v_dealership_catalog
CREATE OR REPLACE VIEW public.v_dealership_catalog AS
SELECT
    vc.id,
    vc.name,
    vc.tier,
    vc.price as base_price,
    vc.image as image_url,
    vc.model_url,
    di.quantity as quantity,
    CASE
        WHEN vc.tier = 'Starter' THEN 10
        WHEN vc.tier = 'Street' THEN 20
        WHEN vc.tier = 'Mid' THEN 30
        WHEN vc.tier = 'Luxury' THEN 50
        WHEN vc.tier = 'Super' THEN 100
        WHEN vc.tier = 'Hyper' THEN 120
        WHEN vc.tier = 'Legendary' THEN 150
        ELSE 10
    END as insurance_rate_bps,
    CASE
        WHEN vc.tier = 'Starter' THEN 100
        WHEN vc.tier = 'Street' THEN 200
        WHEN vc.tier = 'Mid' THEN 500
        WHEN vc.tier = 'Luxury' THEN 1000
        WHEN vc.tier = 'Super' THEN 5000
        WHEN vc.tier = 'Hyper' THEN 7000
        WHEN vc.tier = 'Legendary' THEN 10000
        ELSE 100
    END as registration_fee,
    4 as exposure_level
FROM public.dealership_inventory di
JOIN public.vehicles_catalog vc ON vc.id = di.catalog_id
WHERE di.dealership = 'KTAuto'
  AND di.status = 'active'
  AND di.quantity > 0;

-- View: v_user_profiles_complete
CREATE OR REPLACE VIEW public.v_user_profiles_complete AS
SELECT 
    up.*,
    pc.theme_color,
    pc.accent_color,
    pc.background_style,
    pc.background_image_url,
    pc.card_style,
    pc.featured_badge_id,
    pc.featured_broadcast_id,
    pc.featured_podcast_id,
    pc.featured_stream_id,
    pc.featured_marketplace_item_id,
    ps.total_broadcasts,
    ps.total_broadcast_duration_minutes,
    ps.total_broadcast_viewers,
    ps.total_broadcast_gifts_received,
    ps.total_podcasts,
    ps.total_podcast_episodes,
    ps.total_podcast_listens,
    ps.total_marketplace_items,
    ps.total_marketplace_sales,
    ps.total_marketplace_revenue_coins,
    ps.total_achievements,
    ps.achievement_points,
    ps.last_broadcast_at,
    ps.last_podcast_at,
    ps.last_marketplace_sale_at
FROM public.user_profiles up
LEFT JOIN public.profile_customization pc ON pc.user_id = up.id
LEFT JOIN public.profile_statistics ps ON ps.user_id = up.id;

-- View: zip_crime_dashboard
CREATE OR REPLACE VIEW public.zip_crime_dashboard AS
SELECT
    z.id,
    z.code,
    z.officer_id,
    z.lead_officer_id,
    z.active_stream_count,
    z.crime_score,
    CASE
        WHEN z.crime_score <= 10 THEN 'Safe'
        WHEN z.crime_score <= 25 THEN 'Moderate'
        WHEN z.crime_score <= 50 THEN 'High'
        ELSE 'Critical'
    END AS crime_level,
    officer.username AS officer_username,
    lead.username AS lead_officer_username,
    (SELECT COUNT(*) FROM public.streams s WHERE s.is_live = true AND s.zip_code_id = z.id) AS active_streams,
    (SELECT COUNT(*) FROM public.zip_crime_events e WHERE e.zip_code_id = z.id AND e.created_at >= now() - interval '7 days') AS violations_last_7_days
FROM public.zip_codes z
LEFT JOIN public.user_profiles officer ON officer.id = z.officer_id
LEFT JOIN public.user_profiles lead ON lead.id = z.lead_officer_id;

