RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  IF COALESCE(NEW.bond_posted, false) = true
     AND COALESCE(OLD.bond_posted, false) = false THEN
    NEW.status := 'released_pending_trial';
    NEW.release_time := LEAST(COALESCE(NEW.release_time, NOW()), NOW());
