CREATE OR REPLACE FUNCTION public.get_pride_week()
RETURNS INT AS $$
DECLARE
    v_day INT;
BEGIN
    -- EXTRACT(MONTH) returns 6 for June (1-indexed)
    IF EXTRACT(MONTH FROM now()) != 6 THEN
        RETURN 0;
    END IF;
    v_day := EXTRACT(DAY FROM now());
