-- Function: add_ad_to_queue
CREATE OR REPLACE FUNCTION public.add_ad_to_queue(p_ad_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_position INTEGER;
    v_current_active UUID;
BEGIN
    -- Move current active ad to queued (if any)
    UPDATE public.user_advertisements
    SET 
        status = 'queued',
        is_active_slot = false
    WHERE status = 'active';

    -- Get max queue position for the new ad
    SELECT COALESCE(MAX(queue_position), 0) + 1 INTO v_position
    FROM public.user_advertisements
    WHERE status IN ('queued', 'active');

    -- Activate the new ad
    UPDATE public.user_advertisements
    SET 
        status = 'active',
        queue_position = v_position,
        is_active_slot = true,
        slot_start_time = NOW()
    WHERE id = p_ad_id;

    RETURN jsonb_build_object('success', true, 'queue_position', v_position);
END;
$$;

-- Function: add_beta_feedback_internal_note
CREATE OR REPLACE FUNCTION public.add_beta_feedback_internal_note(
  p_feedback_id uuid,
  p_note text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET statement_timeout = '10s'
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_note text := btrim(COALESCE(p_note, ''));
  v_id uuid;
BEGIN
  IF v_actor IS NULL OR NOT public.is_beta_feedback_moderator(v_actor) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  IF char_length(v_note) < 1 OR char_length(v_note) > 5000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Note must be 1-5000 characters');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.beta_feedback WHERE id = p_feedback_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not found');
  END IF;
  INSERT INTO public.beta_feedback_internal_notes (feedback_id, moderator_id, note)
  VALUES (p_feedback_id, v_actor, v_note) RETURNING id INTO v_id;
  PERFORM public.log_beta_feedback_audit(p_feedback_id, v_actor, 'internal_note',
    NULL, jsonb_build_object('note_id', v_id));
  RETURN jsonb_build_object('success', true, 'note_id', v_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: add_beta_feedback_reply
CREATE OR REPLACE FUNCTION public.add_beta_feedback_reply(
  p_feedback_id uuid,
  p_body text,
  p_visibility text DEFAULT 'user_visible'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET statement_timeout = '10s'
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_feedback public.beta_feedback%ROWTYPE;
  v_body text := btrim(COALESCE(p_body, ''));
  v_visibility text := btrim(COALESCE(p_visibility, 'user_visible'));
  v_id uuid;
  v_row public.beta_feedback_replies%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF v_visibility NOT IN ('user_visible','staff_only') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid visibility');
  END IF;
  IF char_length(v_body) < 1 OR char_length(v_body) > 5000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reply must be 1-5000 characters');
  END IF;
  SELECT * INTO v_feedback FROM public.beta_feedback WHERE id = p_feedback_id;
  IF v_feedback.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not found');
  END IF;

  IF v_visibility = 'staff_only' THEN
    IF NOT public.is_beta_feedback_moderator(v_actor) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;
  ELSE
    IF v_feedback.user_id <> v_actor THEN
      RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;
    IF public.is_user_chat_disabled(v_actor) THEN
      RETURN jsonb_build_object('success', false, 'error', 'chat_disabled');
    END IF;
  END IF;

  INSERT INTO public.beta_feedback_replies (feedback_id, author_id, body, visibility)
  VALUES (p_feedback_id, v_actor, v_body, v_visibility) RETURNING * INTO v_row;

  UPDATE public.beta_feedback SET updated_at = now() WHERE id = p_feedback_id;

  IF v_visibility = 'staff_only' THEN
    PERFORM public.log_beta_feedback_audit(p_feedback_id, v_actor, 'staff_reply', NULL, NULL);
  ELSE
    PERFORM public.log_beta_feedback_audit(p_feedback_id, v_actor, 'user_reply', NULL, NULL);
    PERFORM public.notify_beta_feedback_user(p_feedback_id, 'beta_feedback_reply',
      'New reply to your feedback', 'A moderator replied to your feedback ' || v_feedback.public_id || '.');
  END IF;

  RETURN jsonb_build_object('success', true, 'reply', to_jsonb(v_row));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: add_free_coins
CREATE OR REPLACE FUNCTION public.add_free_coins(
    p_user_id uuid,
    p_amount int
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT public.troll_bank_credit_coins(
        p_user_id,
        p_amount,
        'promo',
        'troll_surprise',
        NULL,
        jsonb_build_object('legacy_function', 'add_free_coins')
    ) INTO v_result;
END;
$$;

-- Function: add_troll_coins
CREATE OR REPLACE FUNCTION public.add_troll_coins(
    user_id uuid,
    amount int
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_result jsonb;
BEGIN
    -- Call the centralized Troll Bank function
    -- Default bucket to 'paid' (or 'promo' if we want to be safe, but level rewards usually feel 'earned')
    -- Let's use 'promo' for level rewards as they are 'free' money essentially.
    -- However, legacy behavior might expect them to be spendable everywhere. 
    -- 'paid' bucket is safest for general compatibility, but 'promo' is better for economy.
    -- Let's stick to 'promo' for rewards to distinguish from purchased coins.
    
    SELECT public.troll_bank_credit_coins(
        user_id,
        amount,
        'promo',  -- Level up rewards are promotional
        'level_reward',
        NULL,     -- No external ref ID
        jsonb_build_object('legacy_function', 'add_troll_coins')
    ) INTO v_result;
END;
$$;

-- Function: admin_approve_marketplace_release
CREATE OR REPLACE FUNCTION admin_approve_marketplace_release(
  p_request_id uuid,
  p_admin_id uuid,
  p_admin_notes text DEFAULT null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_req marketplace_payout_release_requests%ROWTYPE;
  v_order marketplace_purchases%ROWTYPE;
  v_release_result text;
BEGIN
  SELECT * INTO v_req FROM marketplace_payout_release_requests WHERE id = p_request_id;
  IF v_req IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request not found');
  END IF;

  IF v_req.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request is not pending');
  END IF;

  -- Get order
  SELECT * INTO v_order FROM marketplace_purchases WHERE id = v_req.order_id;
  IF v_order IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  -- Release the marketplace payout hold and credit seller earnings via release_marketplace_payout
  SELECT release_marketplace_payout(v_order.id, 'admin_manual_approval', p_admin_id)
    INTO v_release_result;

  IF v_release_result IS DISTINCT FROM 'Payout released successfully' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Payout release failed',
      'details', v_release_result
    );
  END IF;

  -- Update request status only after successful payout release
  UPDATE marketplace_payout_release_requests
  SET status = 'approved',
      reviewed_by = p_admin_id,
      reviewed_at = now(),
      admin_notes = p_admin_notes,
      updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('success', true, 'message', 'Payout released and seller credited');
END;
$$;

-- Function: admin_approve_redemption
CREATE OR REPLACE FUNCTION public.admin_approve_redemption(
  p_redemption_id UUID,
  p_admin_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_redemption RECORD;
BEGIN
  -- Verify admin or secretary
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = p_admin_id
      AND (
        is_admin = true
        OR role IN ('admin', 'secretary', 'Secretary', 'Troll_City_Secretary', 'Executive_Secretary')
      )
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;

  -- Lock and fetch redemption
  SELECT * INTO v_redemption
  FROM public.crown_redemptions
  WHERE id = p_redemption_id
  FOR UPDATE;

  IF v_redemption IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Redemption not found');
  END IF;

  IF v_redemption.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Redemption is not pending');
  END IF;

  UPDATE public.crown_redemptions
  SET status = 'approved',
      updated_at = now()
  WHERE id = p_redemption_id;

  RETURN jsonb_build_object('success', true, 'status', 'approved');
END;
$$;

-- Function: admin_assign_zip_officers
CREATE OR REPLACE FUNCTION public.admin_assign_zip_officers(
    p_zip_id uuid,
    p_officer_id uuid,
    p_lead_officer_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
SET row_security = off
AS $$
DECLARE
    v_old_officer uuid;
    v_old_lead uuid;
BEGIN
    IF NOT public.is_admin_user(auth.uid()) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Admin only');
    END IF;

    SELECT officer_id, lead_officer_id
    INTO v_old_officer, v_old_lead
    FROM public.zip_codes
    WHERE id = p_zip_id
    FOR UPDATE;

    IF v_old_officer IS NOT NULL AND v_old_officer <> p_officer_id THEN
        UPDATE public.user_profiles
        SET assigned_zip_count = GREATEST(COALESCE(assigned_zip_count, 0) - 1, 0)
        WHERE id = v_old_officer;
    END IF;

    IF v_old_lead IS NOT NULL AND v_old_lead <> p_lead_officer_id THEN
        UPDATE public.user_profiles
        SET assigned_zip_count = GREATEST(COALESCE(assigned_zip_count, 0) - 1, 0)
        WHERE id = v_old_lead;
    END IF;

    UPDATE public.zip_codes
    SET officer_id = p_officer_id,
        lead_officer_id = p_lead_officer_id
    WHERE id = p_zip_id;

    IF p_officer_id IS NOT NULL AND (v_old_officer IS NULL OR v_old_officer <> p_officer_id) THEN
        UPDATE public.user_profiles
        SET assigned_zip_count = COALESCE(assigned_zip_count, 0) + 1
        WHERE id = p_officer_id;
    END IF;

    IF p_lead_officer_id IS NOT NULL AND (v_old_lead IS NULL OR v_old_lead <> p_lead_officer_id) THEN
        UPDATE public.user_profiles
        SET assigned_zip_count = COALESCE(assigned_zip_count, 0) + 1
        WHERE id = p_lead_officer_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'zip_id', p_zip_id);
END;
$$;

-- Function: admin_create_announcement
CREATE OR REPLACE FUNCTION public.admin_create_announcement(
    p_title TEXT,
    p_message TEXT,
    p_duration_hours INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID := auth.uid();
    v_is_admin BOOLEAN;
BEGIN
    SELECT (role = 'temp_city_admin' OR role = 'admin' OR role = 'super_admin') INTO v_is_admin
    FROM public.user_profiles WHERE id = v_actor_id;

    IF NOT v_is_admin THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    INSERT INTO public.city_announcements (title, message, created_by, starts_at, ends_at)
    VALUES (p_title, p_message, v_actor_id, NOW(), NOW() + (p_duration_hours || ' hours')::INTERVAL);

    PERFORM public.log_admin_action(
        'create_announcement',
        NULL,
        'governance',
        'Created city announcement',
        jsonb_build_object('title', p_title, 'duration', p_duration_hours)
    );

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: admin_create_poll
CREATE OR REPLACE FUNCTION public.admin_create_poll(
    p_question TEXT,
    p_options JSONB,
    p_duration_minutes INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID := auth.uid();
    v_poll_id UUID;
BEGIN
    -- Permission Check
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = v_actor_id 
        AND (role IN ('admin', 'temp_city_admin') OR is_admin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    INSERT INTO public.city_polls (question, options, created_by, expires_at)
    VALUES (p_question, p_options, v_actor_id, NOW() + (p_duration_minutes || ' minutes')::INTERVAL)
    RETURNING id INTO v_poll_id;

    -- Log Action
    PERFORM public.log_admin_action('create_poll', NULL, 'Created poll: ' || p_question, jsonb_build_object('poll_id', v_poll_id));

    RETURN jsonb_build_object('success', true, 'poll_id', v_poll_id);
END;
$$;

-- Function: admin_create_vehicle
CREATE OR REPLACE FUNCTION public.admin_create_vehicle(
  p_vehicle_id TEXT,
  p_name TEXT,
  p_tier TEXT DEFAULT 'Common',
  p_base_price NUMERIC DEFAULT 0,
  p_buyback_percentage NUMERIC DEFAULT 75,
  p_image_url TEXT DEFAULT NULL,
  p_description TEXT DEFAULT NULL,
  p_stock_quantity INTEGER DEFAULT -1
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  -- Check admin permission
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid()
    AND (is_admin = true OR role IN ('admin', 'superadmin'))
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Admin access required');
  END IF;

  INSERT INTO public.vehicle_catalog (
    vehicle_id,
    name,
    tier,
    base_price,
    buyback_percentage,
    image_url,
    description,
    stock_quantity
  ) VALUES (
    p_vehicle_id,
    p_name,
    p_tier,
    p_base_price,
    p_buyback_percentage,
    p_image_url,
    p_description,
    p_stock_quantity
  )
  ON CONFLICT (vehicle_id) DO UPDATE SET
    name = EXCLUDED.name,
    tier = EXCLUDED.tier,
    base_price = EXCLUDED.base_price,
    buyback_percentage = EXCLUDED.buyback_percentage,
    image_url = EXCLUDED.image_url,
    description = EXCLUDED.description,
    stock_quantity = EXCLUDED.stock_quantity,
    is_active = true;

  RETURN json_build_object('success', true, 'vehicle_id', p_vehicle_id);
END;
$$;

-- Function: admin_delete_vehicle
CREATE OR REPLACE FUNCTION public.admin_delete_vehicle(
  p_vehicle_id TEXT
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  -- Check admin permission
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid()
    AND (is_admin = true OR role IN ('admin', 'superadmin'))
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Admin access required');
  END IF;

  UPDATE public.vehicle_catalog
  SET is_active = false
  WHERE vehicle_id = p_vehicle_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Vehicle not found');
  END IF;

  RETURN json_build_object('success', true, 'vehicle_id', p_vehicle_id);
END;
$$;

-- Function: admin_fulfill_redemption
CREATE OR REPLACE FUNCTION public.admin_fulfill_redemption(
  p_redemption_id UUID,
  p_admin_id UUID,
  p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_redemption RECORD;
BEGIN
  -- Verify admin
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = p_admin_id AND (is_admin = true OR role = 'admin')
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;

  SELECT * INTO v_redemption
  FROM public.crown_redemptions
  WHERE id = p_redemption_id
  FOR UPDATE;

  IF v_redemption IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Redemption not found');
  END IF;

  IF v_redemption.status != 'approved' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Redemption must be approved first');
  END IF;

  UPDATE public.crown_redemptions
  SET status = 'fulfilled',
      fulfilled_by = p_admin_id,
      fulfilled_at = now(),
      email_sent = true,
      notes = COALESCE(p_notes, notes),
      updated_at = now()
  WHERE id = p_redemption_id;

  RETURN jsonb_build_object('success', true, 'status', 'fulfilled');
END;
$$;

-- Function: admin_get_all_referrals
CREATE OR REPLACE FUNCTION public.admin_get_all_referrals()
RETURNS TABLE (
  user_id uuid,
  username text,
  avatar_url text,
  referred_by_id uuid,
  referred_by_username text,
  troll_coins bigint,
  total_earned_coins bigint,
  onboarding_complete boolean,
  is_qualified_referral boolean,
  qualified_referral_at timestamptz,
  is_founding_partner boolean,
  founding_partner_rank integer,
  referred_user_bonus_active boolean,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  SELECT
    up.id AS user_id,
    up.username,
    up.avatar_url,
    up.referred_by_user_id AS referred_by_id,
    ref.username AS referred_by_username,
    COALESCE(up.troll_coins, 0) AS troll_coins,
    COALESCE(up.total_earned_coins, 0) AS total_earned_coins,
    COALESCE(up.onboarding_complete, false) AS onboarding_complete,
    COALESCE(up.is_qualified_referral, false) AS is_qualified_referral,
    up.qualified_referral_at,
    COALESCE(up.founding_partner, false) AS is_founding_partner,
    up.founding_partner_rank,
    COALESCE(up.referred_user_bonus_active, false) AS referred_user_bonus_active,
    up.created_at
  FROM public.user_profiles up
  LEFT JOIN public.user_profiles ref ON ref.id = up.referred_by_user_id
  WHERE up.referred_by_user_id IS NOT NULL
  ORDER BY up.created_at DESC;
END;
$$;

-- Function: admin_get_all_referrers
CREATE OR REPLACE FUNCTION public.admin_get_all_referrers()
RETURNS TABLE (
  user_id uuid,
  username text,
  avatar_url text,
  total_referrals integer,
  qualified_referrals integer,
  is_founding_partner boolean,
  founding_partner_rank integer,
  is_empire_partner boolean,
  partner_status text
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  SELECT
    up.id AS user_id,
    up.username,
    up.avatar_url,
    (SELECT COUNT(*)::integer FROM public.user_profiles r WHERE r.referred_by_user_id = up.id) AS total_referrals,
    (SELECT COUNT(*)::integer FROM public.user_profiles r WHERE r.referred_by_user_id = up.id AND r.is_qualified_referral = true) AS qualified_referrals,
    COALESCE(up.founding_partner, false) AS is_founding_partner,
    up.founding_partner_rank,
    COALESCE(up.is_empire_partner, false) AS is_empire_partner,
    up.partner_status
  FROM public.user_profiles up
  WHERE EXISTS (
    SELECT 1 FROM public.user_profiles r WHERE r.referred_by_user_id = up.id
  )
  ORDER BY up.founding_partner_rank NULLS LAST, up.created_at ASC;
END;
$$;

-- Function: admin_get_referral_overview
CREATE OR REPLACE FUNCTION public.admin_get_referral_overview()
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_total_referrals integer;
  v_qualified_referrals integer;
  v_onboarding_incomplete integer;
  v_founding_partners integer;
  v_referred_with_bonus integer;
  v_total_bonus_coins bigint;
BEGIN
  SELECT COUNT(*) INTO v_total_referrals
  FROM public.user_profiles
  WHERE referred_by_user_id IS NOT NULL;

  SELECT COUNT(*) INTO v_qualified_referrals
  FROM public.user_profiles
  WHERE is_qualified_referral = true;

  SELECT COUNT(*) INTO v_onboarding_incomplete
  FROM public.user_profiles
  WHERE referred_by_user_id IS NOT NULL
    AND (onboarding_complete = false OR onboarding_complete IS NULL);

  SELECT COUNT(*) INTO v_founding_partners
  FROM public.user_profiles
  WHERE founding_partner = true;

  SELECT COUNT(*) INTO v_referred_with_bonus
  FROM public.user_profiles
  WHERE referred_user_bonus_active = true;

  SELECT COALESCE(SUM(
    COALESCE(up.troll_coins, 0)
  ), 0) INTO v_total_bonus_coins
  FROM public.user_profiles up
  WHERE up.referred_by_user_id IS NOT NULL
    AND up.is_qualified_referral = true;

  RETURN json_build_object(
    'total_referrals', v_total_referrals,
    'qualified_referrals', v_qualified_referrals,
    'onboarding_incomplete', v_onboarding_incomplete,
    'founding_partners', v_founding_partners,
    'referred_with_bonus', v_referred_with_bonus,
    'total_bonus_coins', v_total_bonus_coins
  );
END;
$$;

-- Function: admin_get_vehicle_stats
CREATE OR REPLACE FUNCTION public.admin_get_vehicle_stats()
RETURNS TABLE (
  vehicle_id TEXT,
  vehicle_name TEXT,
  total_purchases BIGINT,
  total_sales BIGINT,
  currently_owned BIGINT,
  total_coins_spent NUMERIC,
  total_coins_returned NUMERIC,
  net_coin_sink NUMERIC
)
LANGUAGE sql
SECURITY DEFINER
AS $$
  -- Check admin permission (will throw if not admin)
  SELECT 1 FROM public.user_profiles
  WHERE id = auth.uid()
  AND (is_admin = true OR role IN ('admin', 'superadmin'));

  SELECT
    vc.vehicle_id,
    vc.name as vehicle_name,
    COUNT(uva.id) FILTER (WHERE uva.status = 'owned' OR uva.status = 'sold') as total_purchases,
    COUNT(uva.id) FILTER (WHERE uva.status = 'sold') as total_sales,
    COUNT(uva.id) FILTER (WHERE uva.status = 'owned') as currently_owned,
    COALESCE(SUM(uva.purchase_price) FILTER (WHERE uva.status = 'owned' OR uva.status = 'sold'), 0) as total_coins_spent,
    COALESCE(SUM(uva.sale_price) FILTER (WHERE uva.status = 'sold'), 0) as total_coins_returned,
    COALESCE(SUM(uva.purchase_price) FILTER (WHERE uva.status = 'owned' OR uva.status = 'sold'), 0) - 
    COALESCE(SUM(uva.sale_price) FILTER (WHERE uva.status = 'sold'), 0) as net_coin_sink
  FROM public.vehicle_catalog vc
  LEFT JOIN public.user_vehicle_assets uva ON vc.id = uva.catalog_id
  GROUP BY vc.id, vc.vehicle_id, vc.name
  ORDER BY vc.base_price ASC;
$$;

