-- Function: admin_grant_temp_coins
CREATE OR REPLACE FUNCTION public.admin_grant_temp_coins(
    p_target_user_id UUID,
    p_amount INTEGER,
    p_reason TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID := auth.uid();
    v_is_admin BOOLEAN;
BEGIN
    -- Check permissions
    SELECT (role = 'temp_city_admin' OR role = 'admin' OR role = 'super_admin') INTO v_is_admin
    FROM public.user_profiles WHERE id = v_actor_id;

    IF NOT v_is_admin THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Update target balance
    UPDATE public.user_profiles
    SET temp_admin_coins_balance = temp_admin_coins_balance + p_amount
    WHERE id = p_target_user_id;

    -- Log action
    PERFORM public.log_admin_action(
        'grant_temp_coins',
        p_target_user_id,
        'economy',
        p_reason,
        jsonb_build_object('amount', p_amount)
    );

    RETURN jsonb_build_object('success', true, 'amount', p_amount);
END;
$$;

-- Function: admin_kick_user
CREATE OR REPLACE FUNCTION public.admin_kick_user(
    p_stream_id UUID,
    p_target_id UUID,
    p_reason TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID := auth.uid();
BEGIN
    -- Permission Check
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = v_actor_id 
        AND (role IN ('admin', 'temp_city_admin') OR is_admin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Insert into stream_bans (Kick implies temporary ban from stream)
    INSERT INTO public.stream_bans (stream_id, user_id, reason)
    VALUES (p_stream_id, p_target_id, p_reason)
    ON CONFLICT (stream_id, user_id) DO UPDATE SET reason = p_reason;

    -- Also mark seat as kicked if applicable (best effort)
    UPDATE public.stream_seat_sessions 
    SET status = 'kicked', kick_reason = p_reason, left_at = NOW()
    WHERE stream_id = p_stream_id AND user_id = p_target_id AND status = 'active';

    -- Log Action
    PERFORM public.log_admin_action('kick_user', p_target_id, p_reason, jsonb_build_object('stream_id', p_stream_id));

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: admin_mute_user
CREATE OR REPLACE FUNCTION public.admin_mute_user(
    p_stream_id UUID,
    p_target_id UUID,
    p_reason TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID := auth.uid();
BEGIN
    -- Permission Check
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = v_actor_id 
        AND (role IN ('admin', 'temp_city_admin') OR is_admin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Call existing mute (if available) or insert directly
    INSERT INTO public.stream_mutes (stream_id, user_id)
    VALUES (p_stream_id, p_target_id)
    ON CONFLICT (stream_id, user_id) DO NOTHING;

    -- Log Action
    PERFORM public.log_admin_action('mute_user', p_target_id, p_reason, jsonb_build_object('stream_id', p_stream_id));

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: admin_process_payout
CREATE OR REPLACE FUNCTION public.admin_process_payout(
    p_payout_id UUID,
    p_admin_id UUID,
    p_action TEXT,
    p_payment_reference TEXT DEFAULT NULL,
    p_admin_notes TEXT DEFAULT NULL,
    p_rejection_reason TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_payout RECORD;
    v_user RECORD;
    v_payout_coins BIGINT;
BEGIN
    -- Verify admin role
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = p_admin_id
        AND (role IN ('admin', 'superadmin', 'secretary') OR is_admin = TRUE)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: admin role required');
    END IF;

    -- Get the payout request
    SELECT * INTO v_payout
    FROM public.payout_requests
    WHERE id = p_payout_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Payout request not found.');
    END IF;

    -- Get user profile
    SELECT * INTO v_user
    FROM public.user_profiles
    WHERE id = v_payout.user_id;

    -- In the no-fee system, coin_amount = payout_coins (exact tier amount)
    v_payout_coins := COALESCE(v_payout.payout_coins, v_payout.coin_amount);

    IF p_action = 'approve' THEN
        IF v_payout.status NOT IN ('pending', 'reviewed') THEN
            RETURN jsonb_build_object('success', false, 'error', 'Payout is not in a reviewable status.');
        END IF;

        UPDATE public.payout_requests
        SET status = 'approved',
            approved_by = p_admin_id::text,
            approved_at = NOW(),
            admin_id = p_admin_id,
            notes = COALESCE(p_admin_notes, notes),
            updated_at = NOW()
        WHERE id = p_payout_id;

        PERFORM public.create_notification(
            v_payout.user_id,
            'cashout_approved',
            'Cashout Approved',
            format('Your cashout request for $%s has been approved and is being processed.', v_payout.cash_amount),
            jsonb_build_object('payout_id', p_payout_id)
        );

        RETURN jsonb_build_object('success', true, 'message', 'Payout approved.');

    ELSIF p_action = 'pay' THEN
        IF v_payout.status != 'approved' THEN
            RETURN jsonb_build_object('success', false, 'error', 'Payout must be approved before marking as paid.');
        END IF;

        UPDATE public.payout_requests
        SET status = 'paid',
            paid_at = NOW(),
            processed_at = NOW(),
            processed_by = p_admin_id,
            payment_reference = COALESCE(p_payment_reference, payment_reference),
            notes = COALESCE(p_admin_notes, notes),
            updated_at = NOW()
        WHERE id = p_payout_id;

        -- Release reserved cashout coins (exact tier amount, no fee)
        UPDATE public.user_profiles
        SET cashout_reserved_coins = GREATEST(0, COALESCE(cashout_reserved_coins, 0) - v_payout_coins),
            updated_at = NOW()
        WHERE id = v_payout.user_id;

        PERFORM public.create_notification(
            v_payout.user_id,
            'cashout_paid',
            'Cashout Paid!',
            format('Your cashout of $%s has been sent via %s to %s.', v_payout.cash_amount, v_payout.provider_type, v_payout.provider_username),
            jsonb_build_object('payout_id', p_payout_id)
        );

        RETURN jsonb_build_object('success', true, 'message', 'Payout marked as paid.');

    ELSIF p_action = 'reject' THEN
        IF v_payout.status NOT IN ('pending', 'reviewed', 'approved') THEN
            RETURN jsonb_build_object('success', false, 'error', 'Cannot reject payout in current status.');
        END IF;

        -- Return reserved coins to cashout escrow (exact tier amount)
        UPDATE public.user_profiles
        SET cashout_reserved_coins = GREATEST(0, COALESCE(cashout_reserved_coins, 0) - v_payout_coins),
            cashout_coins = COALESCE(cashout_coins, 0) + v_payout_coins,
            updated_at = NOW()
        WHERE id = v_payout.user_id;

        UPDATE public.payout_requests
        SET status = 'rejected',
            rejection_reason = COALESCE(p_rejection_reason, 'Rejected by admin.'),
            processed_at = NOW(),
            processed_by = p_admin_id,
            notes = COALESCE(p_admin_notes, notes),
            updated_at = NOW()
        WHERE id = p_payout_id;

        PERFORM public.create_notification(
            v_payout.user_id,
            'cashout_rejected',
            'Cashout Rejected',
            format('Your cashout request was rejected. Reason: %s. Your coins have been returned to your balance.', COALESCE(p_rejection_reason, 'No reason provided.')),
            jsonb_build_object('payout_id', p_payout_id)
        );

        RETURN jsonb_build_object('success', true, 'message', 'Payout rejected and coins returned.');

    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'Invalid action. Use approve, pay, or reject.');
    END IF;
END;
$$;

-- Function: admin_reject_marketplace_release
CREATE OR REPLACE FUNCTION admin_reject_marketplace_release(
  p_request_id uuid,
  p_admin_id uuid,
  p_rejection_reason text DEFAULT null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_req marketplace_payout_release_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_req FROM marketplace_payout_release_requests WHERE id = p_request_id;
  IF v_req IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request not found');
  END IF;

  IF v_req.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Request is not pending');
  END IF;

  UPDATE marketplace_payout_release_requests
  SET status = 'rejected',
      reviewed_by = p_admin_id,
      reviewed_at = now(),
      rejection_reason = COALESCE(p_rejection_reason, ''),
      updated_at = now()
  WHERE id = p_request_id;

  RETURN jsonb_build_object('success', true, 'message', 'Request rejected');
END;
$$;

-- Function: admin_reject_redemption
CREATE OR REPLACE FUNCTION public.admin_reject_redemption(
  p_redemption_id UUID,
  p_admin_id UUID,
  p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_redemption RECORD;
BEGIN
  -- Verify admin or secretary
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = p_admin_id
      AND (
        is_admin = true
        OR role IN ('admin', 'secretary', 'Secretary', 'Troll_City_Secretary', 'Executive_Secretary')
      )
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;

  SELECT * INTO v_redemption
  FROM public.crown_redemptions
  WHERE id = p_redemption_id
  FOR UPDATE;

  IF v_redemption IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Redemption not found');
  END IF;

  IF v_redemption.status NOT IN ('pending', 'approved') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot reject this redemption');
  END IF;

  -- Bypass security trigger for coin updates
  PERFORM set_config('app.bypass_coin_protection', 'true', true);

  -- Refund battle_crowns
  UPDATE public.user_profiles
  SET battle_crowns = COALESCE(battle_crowns, 0) + v_redemption.crowns_redeemed,
      updated_at = now()
  WHERE id = v_redemption.user_id;

  UPDATE public.crown_redemptions
  SET status = 'rejected',
      fulfilled_by = p_admin_id,
      fulfilled_at = now(),
      notes = COALESCE(p_notes, notes),
      updated_at = now()
  WHERE id = p_redemption_id;

  -- Notify user about rejection
  INSERT INTO public.notifications (user_id, type, title, message, metadata, is_read, created_at)
  VALUES (
    v_redemption.user_id,
    'refund_issued',
    'Crown Redemption Rejected',
    'Your ' || v_redemption.reward_value || ' redemption was rejected. ' || v_redemption.crowns_redeemed || ' crowns have been refunded.',
    jsonb_build_object(
      'redemption_id', p_redemption_id,
      'reward_value', v_redemption.reward_value,
      'crowns_refunded', v_redemption.crowns_redeemed
    ),
    false,
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'status', 'rejected',
    'crowns_refunded', v_redemption.crowns_redeemed
  );
END;
$$;

-- Function: admin_set_officer_rank
CREATE OR REPLACE FUNCTION public.admin_set_officer_rank(
    p_officer_id uuid,
    p_rank text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
SET row_security = off
AS $$
BEGIN
    IF NOT public.is_admin_user(auth.uid()) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Admin only');
    END IF;

    IF p_rank NOT IN (
        'troll_officer', 'lead_officer', 'ceo',
        'probationary_officer', 'senior_officer',
        'Officer-PT', 'Officer-FT'
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Invalid rank');
    END IF;

    UPDATE public.user_profiles
    SET officer_rank = p_rank
    WHERE id = p_officer_id;

    RETURN jsonb_build_object('success', true, 'officer_id', p_officer_id, 'rank', p_rank);
END;
$$;

-- Function: admin_suspend_officer
CREATE OR REPLACE FUNCTION public.admin_suspend_officer(
    p_officer_id uuid,
    p_reason text DEFAULT 'admin_suspension'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
SET row_security = off
AS $$
BEGIN
    IF NOT public.is_admin_user(auth.uid()) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Admin only');
    END IF;

    UPDATE public.user_profiles
    SET is_officer_active = false,
        officer_rank = 'troll_officer'
    WHERE id = p_officer_id;

    INSERT INTO public.officer_corruption_flags (officer_id, reason, severity)
    VALUES (p_officer_id, p_reason, 'high');

    RETURN jsonb_build_object('success', true, 'officer_id', p_officer_id, 'status', 'suspended');
END;
$$;

-- Function: admin_toggle_founding_partner
CREATE OR REPLACE FUNCTION public.admin_toggle_founding_partner(p_user_id uuid, p_grant boolean)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_current_count integer;
  v_next_rank integer;
BEGIN
  IF p_grant THEN
    -- Check if spots available
    SELECT COUNT(*) INTO v_current_count
    FROM public.user_profiles
    WHERE founding_partner = true;

    IF v_current_count >= 15 THEN
      RAISE EXCEPTION 'All 15 founding partner spots are taken';
    END IF;

    v_next_rank := v_current_count + 1;

    UPDATE public.user_profiles
    SET founding_partner = true,
        founding_partner_rank = v_next_rank,
        is_empire_partner = true,
        empire_partner = true,
        partner_status = 'active'
    WHERE id = p_user_id;
  ELSE
    UPDATE public.user_profiles
    SET founding_partner = false,
        founding_partner_rank = NULL
    WHERE id = p_user_id;
  END IF;

  RETURN true;
END;
$$;

-- Function: admin_toggle_referred_bonus
CREATE OR REPLACE FUNCTION public.admin_toggle_referred_bonus(p_user_id uuid, p_active boolean)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  UPDATE public.user_profiles
  SET referred_user_bonus_active = p_active
  WHERE id = p_user_id;

  RETURN true;
END;
$$;

-- Function: admin_trigger_event
CREATE OR REPLACE FUNCTION public.admin_trigger_event(
    p_event_type TEXT,
    p_label TEXT,
    p_duration_minutes INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID := auth.uid();
    v_event_id UUID;
BEGIN
    -- Permission Check
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = v_actor_id 
        AND (role IN ('admin', 'temp_city_admin') OR is_admin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    INSERT INTO public.city_events (event_type, label, created_by, active_until)
    VALUES (p_event_type, p_label, v_actor_id, NOW() + (p_duration_minutes || ' minutes')::INTERVAL)
    RETURNING id INTO v_event_id;

    -- Log Action
    PERFORM public.log_admin_action('trigger_event', NULL, 'Triggered event: ' || p_label, jsonb_build_object('event_id', v_event_id, 'type', p_event_type));

    RETURN jsonb_build_object('success', true, 'event_id', v_event_id);
END;
$$;

-- Function: admin_update_user_role
CREATE OR REPLACE FUNCTION public.admin_update_user_role(
    p_target_user_id UUID,
    p_new_role TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_admin_role TEXT;
BEGIN
    -- Verify caller is an admin
    SELECT role INTO v_admin_role FROM public.user_profiles WHERE id = auth.uid();
    
    IF v_admin_role NOT IN ('admin', 'secretary', 'lead_troll_officer') AND 
       NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND is_admin = true) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
    END IF;

    -- Set bypass flag
    PERFORM set_config('app.bypass_coin_protection', 'true', true);

    UPDATE public.user_profiles
    SET role = p_new_role, updated_at = NOW()
    WHERE id = p_target_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: admin_update_vehicle
CREATE OR REPLACE FUNCTION public.admin_update_vehicle(
  p_vehicle_id TEXT,
  p_name TEXT DEFAULT NULL,
  p_tier TEXT DEFAULT NULL,
  p_base_price NUMERIC DEFAULT NULL,
  p_buyback_percentage NUMERIC DEFAULT NULL,
  p_image_url TEXT DEFAULT NULL,
  p_description TEXT DEFAULT NULL,
  p_stock_quantity INTEGER DEFAULT NULL,
  p_is_active BOOLEAN DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  -- Check admin permission
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid()
    AND (is_admin = true OR role IN ('admin', 'superadmin'))
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Admin access required');
  END IF;

  UPDATE public.vehicle_catalog
  SET
    name = COALESCE(p_name, name),
    tier = COALESCE(p_tier, tier),
    base_price = COALESCE(p_base_price, base_price),
    buyback_percentage = COALESCE(p_buyback_percentage, buyback_percentage),
    image_url = COALESCE(p_image_url, image_url),
    description = COALESCE(p_description, description),
    stock_quantity = COALESCE(p_stock_quantity, stock_quantity),
    is_active = COALESCE(p_is_active, is_active)
  WHERE vehicle_id = p_vehicle_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Vehicle not found');
  END IF;

  RETURN json_build_object('success', true, 'vehicle_id', p_vehicle_id);
END;
$$;

-- Function: admin_waive_court_fine
CREATE OR REPLACE FUNCTION public.admin_waive_court_fine(
    p_payment_id UUID,
    p_reason TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID := auth.uid();
    v_is_admin BOOLEAN;
    v_target_user_id UUID;
BEGIN
    SELECT (role = 'temp_city_admin' OR role = 'admin' OR role = 'super_admin') INTO v_is_admin
    FROM public.user_profiles WHERE id = v_actor_id;

    IF NOT v_is_admin THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Get target user from payment
    SELECT defendant_id INTO v_target_user_id FROM public.court_payments WHERE id = p_payment_id;

    -- Update payment status
    UPDATE public.court_payments
    SET status = 'waived' -- Assuming 'waived' is valid or we set to 'failed' with reason
    WHERE id = p_payment_id;
    
    -- If 'waived' is not in constraint, we might need to alter type or use 'failed'
    -- Let's check constraints safely. If 'waived' fails, we'll delete it.
    -- Better: Just Delete it for now as "Waive" implies it's gone.
    DELETE FROM public.court_payments WHERE id = p_payment_id;

    -- Log
    PERFORM public.log_admin_action(
        'waive_fine',
        v_target_user_id,
        'economy',
        p_reason,
        jsonb_build_object('payment_id', p_payment_id)
    );

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: aggregate_stream_analytics
CREATE OR REPLACE FUNCTION public.aggregate_stream_analytics()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  WITH days AS (
    SELECT generate_series((current_date - interval '30 days')::date, current_date, interval '1 day')::date AS date
  ),
  viewer_sessions AS (
    SELECT
      j.created_at::date AS date,
      j.stream_id,
      j.user_id,
      GREATEST(
        0,
        FLOOR(EXTRACT(EPOCH FROM (
          LEAST(
            COALESCE((
              SELECT MIN(l.created_at)
              FROM public.stream_analytics_events l
              WHERE l.stream_id = j.stream_id
                AND l.user_id = j.user_id
                AND l.event_type = 'leave'
                AND l.created_at > j.created_at
            ), now()),
            j.created_at + interval '30 minutes'
          ) - j.created_at
        )) / 60)
      )::bigint AS minutes
    FROM public.stream_analytics_events j
    WHERE j.event_type = 'join'
      AND j.created_at >= current_date - interval '30 days'
  ),
  viewer_daily AS (
    SELECT
      date,
      COALESCE(SUM(minutes), 0)::bigint AS total_viewer_minutes,
      COUNT(DISTINCT user_id)::bigint AS unique_viewers
    FROM viewer_sessions
    GROUP BY date
  ),
  stream_sessions AS (
    SELECT
      s.created_at::date AS date,
      s.stream_id,
      GREATEST(
        0,
        FLOOR(EXTRACT(EPOCH FROM (
          LEAST(
            COALESCE((
              SELECT MIN(e.created_at)
              FROM public.stream_analytics_events e
              WHERE e.stream_id = s.stream_id
                AND e.event_type = 'stream_end'
                AND e.created_at > s.created_at
            ), now()),
            s.created_at + interval '12 hours'
          ) - s.created_at
        )) / 60)
      )::bigint AS minutes
    FROM public.stream_analytics_events s
    WHERE s.event_type = 'stream_start'
      AND s.created_at >= current_date - interval '30 days'
  ),
  stream_daily AS (
    SELECT
      date,
      COALESCE(SUM(minutes), 0)::bigint AS total_stream_minutes,
      COUNT(DISTINCT stream_id)::bigint AS unique_streams
    FROM stream_sessions
    GROUP BY date
  ),
  gift_daily AS (
    SELECT
      created_at::date AS date,
      COUNT(*)::bigint AS total_gifts_count,
      COALESCE(SUM(GREATEST(COALESCE(gift_amount, 0), 0)), 0)::bigint AS total_gift_coins,
      COUNT(DISTINCT user_id)::bigint AS gift_users
    FROM public.stream_analytics_events
    WHERE event_type = 'gift'
      AND created_at >= current_date - interval '30 days'
    GROUP BY created_at::date
  ),
  concurrent_points AS (
    SELECT
      created_at::date AS date,
      SUM(CASE WHEN event_type = 'join' THEN 1 WHEN event_type = 'leave' THEN -1 ELSE 0 END)
        OVER (PARTITION BY stream_id, created_at::date ORDER BY created_at, id) AS concurrent_viewers
    FROM public.stream_analytics_events
    WHERE event_type IN ('join', 'leave')
      AND created_at >= current_date - interval '30 days'
  ),
  peak_daily AS (
    SELECT
      date,
      GREATEST(COALESCE(MAX(concurrent_viewers), 0), 0)::bigint AS peak_concurrent_viewers
    FROM concurrent_points
    GROUP BY date
  )
  INSERT INTO public.stream_analytics_daily (
    date,
    total_viewer_minutes,
    total_stream_minutes,
    total_gifts_count,
    total_gift_coins,
    unique_viewers,
    unique_streams,
    avg_watch_time_per_user,
    avg_stream_duration,
    avg_gifts_per_user,
    peak_concurrent_viewers
  )
  SELECT
    d.date,
    COALESCE(v.total_viewer_minutes, 0),
    COALESCE(s.total_stream_minutes, 0),
    COALESCE(g.total_gifts_count, 0),
    COALESCE(g.total_gift_coins, 0),
    COALESCE(v.unique_viewers, 0),
    COALESCE(s.unique_streams, 0),
    CASE WHEN COALESCE(v.unique_viewers, 0) > 0 THEN ROUND(COALESCE(v.total_viewer_minutes, 0)::numeric / v.unique_viewers, 2) ELSE 0 END,
    CASE WHEN COALESCE(s.unique_streams, 0) > 0 THEN ROUND(COALESCE(s.total_stream_minutes, 0)::numeric / s.unique_streams, 2) ELSE 0 END,
    CASE WHEN COALESCE(g.gift_users, 0) > 0 THEN ROUND(COALESCE(g.total_gifts_count, 0)::numeric / g.gift_users, 2) ELSE 0 END,
    COALESCE(p.peak_concurrent_viewers, 0)
  FROM days d
  LEFT JOIN viewer_daily v ON v.date = d.date
  LEFT JOIN stream_daily s ON s.date = d.date
  LEFT JOIN gift_daily g ON g.date = d.date
  LEFT JOIN peak_daily p ON p.date = d.date
  ON CONFLICT (date) DO UPDATE
  SET total_viewer_minutes = EXCLUDED.total_viewer_minutes,
      total_stream_minutes = EXCLUDED.total_stream_minutes,
      total_gifts_count = EXCLUDED.total_gifts_count,
      total_gift_coins = EXCLUDED.total_gift_coins,
      unique_viewers = EXCLUDED.unique_viewers,
      unique_streams = EXCLUDED.unique_streams,
      avg_watch_time_per_user = EXCLUDED.avg_watch_time_per_user,
      avg_stream_duration = EXCLUDED.avg_stream_duration,
      avg_gifts_per_user = EXCLUDED.avg_gifts_per_user,
      peak_concurrent_viewers = EXCLUDED.peak_concurrent_viewers;
END;
$$;

-- Function: apply_for_agency_from_family
CREATE OR REPLACE FUNCTION public.apply_for_agency_from_family(
    p_family_id UUID,
    p_message TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_settings public.agency_platform_settings;
    v_application_fee INTEGER;
    v_monthly_fee INTEGER;
    v_total_fee INTEGER;
    v_balance INTEGER;
    v_family RECORD;
    v_agency_id UUID;
    v_application_id UUID;
    v_slug TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    SELECT *
    INTO v_family
    FROM public.troll_families
    WHERE id = p_family_id
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Family not found';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.troll_family_members
        WHERE family_id = p_family_id
          AND user_id = v_user_id
          AND lower(COALESCE(role, '')) IN ('leader', 'co-leader', 'co_leader')
    ) THEN
        RAISE EXCEPTION 'Only the family leader or co-leader can convert this family to an agency';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM public.agency_applications
        WHERE applicant_id = v_user_id
          AND content_type = 'family_conversion'
          AND status IN ('pending', 'approved')
    ) THEN
        RAISE EXCEPTION 'You already have a pending or approved family-to-agency conversion request';
    END IF;

    SELECT *
    INTO v_settings
    FROM public.agency_platform_settings
    ORDER BY updated_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agency platform settings are not configured';
    END IF;

    v_application_fee := GREATEST(COALESCE(v_settings.application_fee_coins, 0), 25000);
    v_monthly_fee := GREATEST(COALESCE(v_settings.monthly_fee_coins, 0), 10000);
    v_total_fee := v_application_fee + v_monthly_fee;

    IF v_settings.agency_hr_manager_user_id IS NULL THEN
        RAISE EXCEPTION 'Agency HR Manager recipient account is not configured';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = v_settings.agency_hr_manager_user_id) THEN
        RAISE EXCEPTION 'Agency HR Manager recipient profile was not found';
    END IF;

    SELECT troll_coins
    INTO v_balance
    FROM public.user_profiles
    WHERE id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User profile was not found';
    END IF;

    IF v_total_fee > 0 AND COALESCE(v_balance, 0) < v_total_fee THEN
        RAISE EXCEPTION 'Insufficient Troll Coins to pay the agency startup and monthly fees';
    END IF;

    v_slug := trim(both '-' from lower(regexp_replace(COALESCE(v_family.name, 'family'), '[^a-z0-9]+', '-', 'gi')));
    IF v_slug = '' THEN
        v_slug := 'family';
    END IF;
    v_slug := v_slug || '-' || substring(md5(uuid_generate_v4()::text), 1, 8);

    INSERT INTO public.agencies (
        owner_id,
        name,
        slug,
        bio,
        status,
        default_split_percent,
        created_at,
        updated_at
    )
    VALUES (
        v_user_id,
        COALESCE(v_family.name, 'Converted Family'),
        v_slug,
        COALESCE(v_family.description, NULL),
        'pending',
        10,
        NOW(),
        NOW()
    )
    RETURNING id INTO v_agency_id;

    INSERT INTO public.agency_members (
        agency_id,
        user_id,
        role,
        status
    )
    VALUES (
        v_agency_id,
        v_user_id,
        'owner',
        'active'
    );

    IF v_total_fee > 0 THEN
        UPDATE public.user_profiles
        SET troll_coins = troll_coins - v_total_fee,
            total_spent_coins = COALESCE(total_spent_coins, 0) + v_total_fee
        WHERE id = v_user_id;

        UPDATE public.user_profiles
        SET troll_coins = troll_coins + v_total_fee,
            total_earned_coins = COALESCE(total_earned_coins, 0) + v_total_fee
        WHERE id = v_settings.agency_hr_manager_user_id;

        IF v_application_fee > 0 THEN
            INSERT INTO public.agency_billing_events (
                agency_id,
                billing_type,
                amount_coins,
                status,
                payer_user_id,
                recipient_user_id,
                created_by,
                paid_at,
                metadata
            )
            VALUES (
                v_agency_id,
                'application_fee',
                v_application_fee,
                'paid',
                v_user_id,
                v_settings.agency_hr_manager_user_id,
                v_user_id,
                NOW(),
                jsonb_build_object(
                    'source', 'apply_for_agency_from_family',
                    'family_id', p_family_id,
                    'note', 'Paid family conversion application fee'
                )
            );
        END IF;

        IF v_monthly_fee > 0 THEN
            INSERT INTO public.agency_billing_events (
                agency_id,
                billing_type,
                amount_coins,
                status,
                payer_user_id,
                recipient_user_id,
                created_by,
                paid_at,
                metadata
            )
            VALUES (
                v_agency_id,
                'monthly_fee',
                v_monthly_fee,
                'paid',
                v_user_id,
                v_settings.agency_hr_manager_user_id,
                v_user_id,
                NOW(),
                jsonb_build_object(
                    'source', 'apply_for_agency_from_family',
                    'family_id', p_family_id,
                    'note', 'Paid first monthly agency fee'
                )
            );

            UPDATE public.agencies
            SET last_monthly_fee_paid_at = NOW(),
                monthly_fee_status = 'paid'
            WHERE id = v_agency_id;
        END IF;
    END IF;

    INSERT INTO public.agency_applications (
        agency_id,
        applicant_id,
        message,
        content_type,
        status,
        application_fee_paid
    )
    VALUES (
        v_agency_id,
        v_user_id,
        COALESCE(nullif(btrim(p_message), ''), 'Family-to-agency conversion request'),
        'family_conversion',
        'pending',
        v_application_fee > 0
    )
    RETURNING id INTO v_application_id;

    RETURN jsonb_build_object(
        'success', true,
        'agency_id', v_agency_id,
        'application_id', v_application_id,
        'application_fee_coins', v_application_fee,
        'monthly_fee_coins', v_monthly_fee,
        'total_fee_coins', v_total_fee,
        'family_id', p_family_id
    );
END;
$$;

-- Function: apply_for_agency_with_fee
CREATE OR REPLACE FUNCTION public.apply_for_agency_with_fee(
    p_name TEXT,
    p_bio TEXT DEFAULT NULL,
    p_default_split_percent INTEGER DEFAULT 10
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_settings public.agency_platform_settings;
    v_application_fee INTEGER;
    v_monthly_fee INTEGER;
    v_total_fee INTEGER;
    v_balance INTEGER;
    v_agency_id UUID;
    v_application_id UUID;
    v_slug TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF btrim(COALESCE(p_name, '')) = '' THEN
        RAISE EXCEPTION 'Agency name is required';
    END IF;

    IF p_default_split_percent < 0 OR p_default_split_percent > 15 THEN
        RAISE EXCEPTION 'Default split must be between 0 and 15';
    END IF;

    SELECT *
    INTO v_settings
    FROM public.agency_platform_settings
    ORDER BY updated_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agency platform settings are not configured';
    END IF;

    v_application_fee := GREATEST(COALESCE(v_settings.application_fee_coins, 0), 25000);
    v_monthly_fee := GREATEST(COALESCE(v_settings.monthly_fee_coins, 0), 10000);
    v_total_fee := v_application_fee + v_monthly_fee;

    IF v_settings.agency_hr_manager_user_id IS NULL THEN
        RAISE EXCEPTION 'Agency HR Manager recipient account is not configured';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = v_settings.agency_hr_manager_user_id) THEN
        RAISE EXCEPTION 'Agency HR Manager recipient profile was not found';
    END IF;

    SELECT troll_coins
    INTO v_balance
    FROM public.user_profiles
    WHERE id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User profile was not found';
    END IF;

    IF v_total_fee > 0 AND COALESCE(v_balance, 0) < v_total_fee THEN
        RAISE EXCEPTION 'Insufficient Troll Coins to pay the agency startup and monthly fees';
    END IF;

    v_slug := trim(both '-' from lower(regexp_replace(COALESCE(p_name, 'agency'), '[^a-z0-9]+', '-', 'gi')));
    IF v_slug = '' THEN
        v_slug := 'agency';
    END IF;
    v_slug := v_slug || '-' || substring(md5(uuid_generate_v4()::text), 1, 8);

    INSERT INTO public.agencies (
        owner_id,
        name,
        slug,
        bio,
        status,
        default_split_percent,
        created_at,
        updated_at
    )
    VALUES (
        v_user_id,
        btrim(p_name),
        v_slug,
        nullif(btrim(COALESCE(p_bio, '')), ''),
        'pending',
        p_default_split_percent,
        NOW(),
        NOW()
    )
    RETURNING id INTO v_agency_id;

    INSERT INTO public.agency_members (
        agency_id,
        user_id,
        role,
        status
    )
    VALUES (
        v_agency_id,
        v_user_id,
        'owner',
        'active'
    );

    IF v_total_fee > 0 THEN
        UPDATE public.user_profiles
        SET troll_coins = troll_coins - v_total_fee,
            total_spent_coins = COALESCE(total_spent_coins, 0) + v_total_fee
        WHERE id = v_user_id;

        UPDATE public.user_profiles
        SET troll_coins = troll_coins + v_total_fee,
            total_earned_coins = COALESCE(total_earned_coins, 0) + v_total_fee
        WHERE id = v_settings.agency_hr_manager_user_id;

        IF v_application_fee > 0 THEN
            INSERT INTO public.agency_billing_events (
                agency_id,
                billing_type,
                amount_coins,
                status,
                payer_user_id,
                recipient_user_id,
                created_by,
                paid_at,
                metadata
            )
            VALUES (
                v_agency_id,
                'application_fee',
                v_application_fee,
                'paid',
                v_user_id,
                v_settings.agency_hr_manager_user_id,
                v_user_id,
                NOW(),
                jsonb_build_object(
                    'source', 'apply_for_agency_with_fee',
                    'note', 'Paid agency application fee'
                )
            );
        END IF;

        IF v_monthly_fee > 0 THEN
            INSERT INTO public.agency_billing_events (
                agency_id,
                billing_type,
                amount_coins,
                status,
                payer_user_id,
                recipient_user_id,
                created_by,
                paid_at,
                metadata
            )
            VALUES (
                v_agency_id,
                'monthly_fee',
                v_monthly_fee,
                'paid',
                v_user_id,
                v_settings.agency_hr_manager_user_id,
                v_user_id,
                NOW(),
                jsonb_build_object(
                    'source', 'apply_for_agency_with_fee',
                    'note', 'Paid first monthly agency fee'
                )
            );

            UPDATE public.agencies
            SET last_monthly_fee_paid_at = NOW(),
                monthly_fee_status = 'paid'
            WHERE id = v_agency_id;
        END IF;
    END IF;

    INSERT INTO public.agency_applications (
        agency_id,
        applicant_id,
        message,
        content_type,
        status,
        application_fee_paid
    )
    VALUES (
        v_agency_id,
        v_user_id,
        'Paid agency application submission',
        'new_agency',
        'pending',
        v_application_fee > 0
    )
    RETURNING id INTO v_application_id;

    RETURN jsonb_build_object(
        'success', true,
        'agency_id', v_agency_id,
        'application_id', v_application_id,
        'application_fee_coins', v_application_fee,
        'monthly_fee_coins', v_monthly_fee,
        'total_fee_coins', v_total_fee,
        'agency_hr_manager_user_id', v_settings.agency_hr_manager_user_id
    );
END;
$$;

-- Function: apply_for_gaming_agency_loan
CREATE OR REPLACE FUNCTION public.apply_for_gaming_agency_loan(
  p_amount numeric
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_existing_active_loan boolean;
  v_existing_pending_loan boolean;
  v_loan_id uuid;
  v_current_balance numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Unauthorized: not signed in');
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN json_build_object('success', false, 'error', 'Invalid loan amount');
  END IF;

  IF p_amount > 5000 THEN
    RETURN json_build_object('success', false, 'error', 'Loan amount cannot exceed 5,000 TC');
  END IF;

  -- Check for existing active loan
  SELECT EXISTS(
    SELECT 1 FROM public.loans
    WHERE user_id = v_user_id AND status = 'active' AND loan_type = 'gaming_agency'
  ) INTO v_existing_active_loan;

  IF v_existing_active_loan THEN
    RETURN json_build_object('success', false, 'error', 'You already have an active gaming loan. Pay it off first.');
  END IF;

  -- Check for pending loan application
  SELECT EXISTS(
    SELECT 1 FROM public.loan_applications
    WHERE user_id = v_user_id AND status = 'pending'
  ) INTO v_existing_pending_loan;

  IF v_existing_pending_loan THEN
    RETURN json_build_object('success', false, 'error', 'You already have a pending loan application.');
  END IF;

  -- Create the loan record
  INSERT INTO public.loans (user_id, principal, balance, status, loan_type)
  VALUES (v_user_id, p_amount, p_amount, 'active', 'gaming_agency')
  RETURNING id INTO v_loan_id;

  -- Also insert into loan_applications for tracking
  INSERT INTO public.loan_applications (user_id, requested_coins, status, auto_approved, reason)
  VALUES (v_user_id, p_amount, 'approved', true, 'Gaming Agency Loan - auto-approved');

  -- Get current balance for logging
  SELECT COALESCE(ui.troll_coins, 0) INTO v_current_balance
  FROM public.user_profiles ui WHERE ui.id = v_user_id;

  -- Note: The actual coin crediting and credit card processing
  -- is handled by the application layer (PayPal) or admin
  -- This RPC just creates the loan record

  RETURN json_build_object(
    'success', true,
    'loan_id', v_loan_id,
    'amount', p_amount,
    'message', 'Gaming agency loan created successfully. No cashouts until loan is paid off.',
    'current_balance', v_current_balance
  );
END;
$$;

-- Function: apply_troll_pass_bundle
CREATE OR REPLACE FUNCTION public.apply_troll_pass_bundle(
    p_user_id uuid
)
RETURNS timestamptz
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_new_expiry timestamptz;
    v_coins int := 1500; -- Bundle includes 1500 coins
    v_bank_result json;
BEGIN
    -- 1. Credit Coins using Troll Bank (Atomic, handles loan repayment if any)
    SELECT public.troll_bank_credit_coins(
        p_user_id,
        v_coins,
        'paid', -- Treat as paid coins since Troll Pass is purchased
        'troll_pass_bundle',
        NULL, -- No specific ref_id passed here, could be added if needed
        jsonb_build_object('item', 'Troll Pass Bundle')
    ) INTO v_bank_result;

    -- 2. Update Expiry (Extend if active, set new if expired)
    SELECT 
        CASE 
            WHEN troll_pass_expires_at > now() THEN troll_pass_expires_at + interval '30 days'
            ELSE now() + interval '30 days'
        END
    INTO v_new_expiry
    FROM public.user_profiles
    WHERE id = p_user_id;

    -- Handle case where user might not be found (unlikely) or null date
    IF v_new_expiry IS NULL THEN
        v_new_expiry := now() + interval '30 days';
    END IF;

    UPDATE public.user_profiles
    SET troll_pass_expires_at = v_new_expiry
    WHERE id = p_user_id;

    RETURN v_new_expiry;
END;
$$;

-- Function: apply_vehicle_upgrade
CREATE OR REPLACE FUNCTION public.apply_vehicle_upgrade(p_vehicle_id UUID, p_upgrade_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_cost INTEGER;
    v_balance INTEGER;
    v_upgrade_exists BOOLEAN;
    v_upgrade_record RECORD;
BEGIN
    v_user_id := auth.uid();
    
    -- Get Upgrade Cost
    SELECT * INTO v_upgrade_record FROM public.car_upgrades WHERE id = p_upgrade_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Upgrade not found');
    END IF;
    
    v_cost := v_upgrade_record.cost;

    -- Check Balance
    SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    IF v_balance < v_cost THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient funds');
    END IF;

    -- Deduct
    UPDATE public.user_profiles SET troll_coins = troll_coins - v_cost WHERE id = v_user_id;

    -- User Ledger
    INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, metadata)
    VALUES (v_user_id, -v_cost, 'spend', 'vehicle_upgrade', 'Applied ' || v_upgrade_record.name, jsonb_build_object('vehicle_id', p_vehicle_id));

    -- Officer Ledger
    INSERT INTO public.officer_pay_ledger (source_type, source_id, coin_amount, metadata)
    VALUES ('vehicle_purchase', p_vehicle_id::text, v_cost, jsonb_build_object('user_id', v_user_id, 'upgrade_name', v_upgrade_record.name)); 
    -- Note: Mapping upgrade to 'vehicle_purchase' category or adding 'vehicle_upgrade' to check constraint if needed.
    -- Constraint above allows: 'vehicle_purchase', 'vehicle_registration', 'vehicle_insurance', 'vehicle_tax'.
    -- I'll map it to 'vehicle_purchase' for now as it's part of the car value, or I should update the constraint.
    -- Let's stick to the constraint I defined: 'vehicle_purchase'.

    -- Install
    INSERT INTO public.user_vehicle_upgrades (user_vehicle_id, upgrade_id)
    VALUES (p_vehicle_id, p_upgrade_id)
    ON CONFLICT (user_vehicle_id, upgrade_id) DO NOTHING;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: appoint_vice_president
CREATE OR REPLACE FUNCTION public.appoint_vice_president(p_user_id UUID)
RETURNS VOID
SECURITY DEFINER
LANGUAGE plpgsql
AS $$
DECLARE
  v_pres_expires TIMESTAMPTZ;
  v_vp_role_id UUID;
  v_target_username TEXT;
BEGIN
  -- Check President
  SELECT urg.expires_at INTO v_pres_expires
  FROM user_role_grants urg
  JOIN system_roles sr ON urg.role_id = sr.id
  WHERE urg.user_id = auth.uid() 
  AND sr.name = 'president'
  AND (urg.expires_at IS NULL OR urg.expires_at > NOW());
  
  IF v_pres_expires IS NULL THEN
    RAISE EXCEPTION 'Not President';
  END IF;
  
  -- Get Target Username for Logging
  SELECT username INTO v_target_username FROM user_profiles WHERE id = p_user_id;
  
  -- Remove existing VP
  UPDATE president_appointments
  SET status = 'removed', removed_at = NOW(), removed_by = auth.uid()
  WHERE status = 'active';
  
  SELECT id INTO v_vp_role_id FROM system_roles WHERE name = 'vice_president';
  
  -- Expire existing VP role grants
  UPDATE user_role_grants
  SET expires_at = NOW()
  WHERE role_id = v_vp_role_id AND (expires_at IS NULL OR expires_at > NOW());
  
  -- Create Appointment
  INSERT INTO president_appointments (
    president_user_id, 
    vice_president_user_id, 
    starts_at, 
    ends_at, 
    status
  ) VALUES (
    auth.uid(),
    p_user_id,
    NOW(),
    v_pres_expires, -- VP term aligns with President's remaining term
    'active'
  );
  
  -- Grant Role
  INSERT INTO user_role_grants (user_id, role_id, expires_at)
  VALUES (p_user_id, v_vp_role_id, v_pres_expires);

  -- Log to Government Actions Log
  PERFORM public.log_government_action(
    auth.uid(),
    'president',
    'appoint_vp',
    p_user_id::text,
    jsonb_build_object(
        'target_username', v_target_username,
        'term_ends_at', v_pres_expires
    )
  );
END;
$$;

-- Function: approve_agency_application_atomic
CREATE OR REPLACE FUNCTION public.approve_agency_application_atomic(
    p_application_id UUID,
    p_approved_by UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
    v_application public.agency_applications;
    v_settings public.agency_platform_settings;
    v_actor_role TEXT;
    v_applicant_balance INTEGER;
    v_application_fee INTEGER;
    v_monthly_fee INTEGER;
    v_total_fee INTEGER;
    v_member_updated INTEGER;
BEGIN
    IF p_approved_by IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Approval actor is required'
        );
    END IF;

    SELECT *
    INTO v_application
    FROM public.agency_applications
    WHERE id = p_application_id
      AND status = 'pending'
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Application not found or already reviewed'
        );
    END IF;

    IF v_application.agency_id IS NULL OR v_application.applicant_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Application is missing agency_id or applicant_id'
        );
    END IF;

    SELECT role
    INTO v_actor_role
    FROM public.agency_members
    WHERE agency_id = v_application.agency_id
      AND user_id = p_approved_by
      AND (status = 'active' OR is_active = true)
    LIMIT 1;

    IF v_actor_role IS NULL OR v_actor_role NOT IN ('owner', 'manager') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'You do not have permission to approve agency applications'
        );
    END IF;

    SELECT *
    INTO v_settings
    FROM public.agency_platform_settings
    ORDER BY updated_at DESC
    LIMIT 1
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Agency platform settings are not configured'
        );
    END IF;

    IF v_settings.agency_hr_manager_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Agency HR Manager recipient account is not configured'
        );
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = v_settings.agency_hr_manager_user_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Agency HR Manager recipient profile was not found'
        );
    END IF;

    v_application_fee := GREATEST(COALESCE(v_settings.application_fee_coins, 0), 25000);
    v_monthly_fee := GREATEST(COALESCE(v_settings.monthly_fee_coins, 0), 10000);
    v_total_fee := v_application_fee + v_monthly_fee;

    SELECT troll_coins
    INTO v_applicant_balance
    FROM public.user_profiles
    WHERE id = v_application.applicant_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Applicant profile not found'
        );
    END IF;

    IF v_total_fee > 0 AND COALESCE(v_applicant_balance, 0) < v_total_fee THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Insufficient Troll Coins to pay agency application fee'
        );
    END IF;

    UPDATE public.user_profiles
    SET troll_coins = troll_coins - v_total_fee,
        total_spent_coins = COALESCE(total_spent_coins, 0) + v_total_fee,
        updated_at = NOW()
    WHERE id = v_application.applicant_id
      AND COALESCE(troll_coins, 0) >= v_total_fee;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Insufficient Troll Coins to pay agency application fee'
        );
    END IF;

    IF v_application_fee > 0 THEN
        INSERT INTO public.agency_billing_events (
            agency_id, billing_type, amount_coins, status,
            payer_user_id, recipient_user_id, created_by, paid_at, metadata
        ) VALUES (
            v_application.agency_id, 'application_fee', v_application_fee, 'paid',
            v_application.applicant_id, v_settings.agency_hr_manager_user_id,
            p_approved_by, NOW(),
            jsonb_build_object(
                'source', 'approve_agency_application_atomic',
                'application_id', p_application_id,
                'application_fee_coins', v_application_fee,
                'monthly_fee_coins', v_monthly_fee
            )
        );
    END IF;

    IF v_monthly_fee > 0 THEN
        INSERT INTO public.agency_billing_events (
            agency_id, billing_type, amount_coins, status,
            payer_user_id, recipient_user_id, created_by, paid_at, metadata
        ) VALUES (
            v_application.agency_id, 'monthly_fee', v_monthly_fee, 'paid',
            v_application.applicant_id, v_settings.agency_hr_manager_user_id,
            p_approved_by, NOW(),
            jsonb_build_object(
                'source', 'approve_agency_application_atomic',
                'application_id', p_application_id,
                'application_fee_coins', v_application_fee,
                'monthly_fee_coins', v_monthly_fee
            )
        );

        UPDATE public.agencies
        SET last_monthly_fee_paid_at = NOW(),
            monthly_fee_status = 'paid',
            updated_at = NOW()
        WHERE id = v_application.agency_id;
    END IF;

    UPDATE public.agency_applications
    SET status = 'approved',
        reviewed_by = p_approved_by,
        reviewed_at = NOW(),
        application_fee_paid = true
    WHERE id = p_application_id;

    -- Update existing member or insert new one, handling both schema variants
    UPDATE public.agency_members
    SET role = 'creator',
        status = 'active',
        is_active = true,
        removed_at = NULL,
        joined_at = COALESCE(joined_at, NOW()),
        created_at = COALESCE(created_at, NOW())
    WHERE agency_id = v_application.agency_id
      AND user_id = v_application.applicant_id;

    GET DIAGNOSTICS v_member_updated = ROW_COUNT;

    IF v_member_updated = 0 THEN
        INSERT INTO public.agency_members (
            agency_id, user_id, role, status, is_active, joined_at
        ) VALUES (
            v_application.agency_id,
            v_application.applicant_id,
            'creator',
            'active',
            true,
            NOW()
        );
    END IF;

    INSERT INTO public.agency_enforcement_actions (
        agency_id, actor_id, target_user_id, action_type, reason, metadata
    ) VALUES (
        v_application.agency_id, p_approved_by, v_application.applicant_id,
        'application_approved', 'Approved agency application and charged fees',
        jsonb_build_object(
            'application_id', p_application_id,
            'application_fee_coins', v_application_fee,
            'monthly_fee_coins', v_monthly_fee,
            'total_fee_coins', v_total_fee
        )
    );

    INSERT INTO public.agency_activity_logs (
        agency_id, actor_id, target_user_id, action, metadata
    ) VALUES (
        v_application.agency_id, p_approved_by, v_application.applicant_id,
        'application_approved',
        jsonb_build_object(
            'application_id', p_application_id,
            'application_fee_coins', v_application_fee,
            'monthly_fee_coins', v_monthly_fee,
            'total_fee_coins', v_total_fee
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'agency_id', v_application.agency_id,
        'fee_charged_amount', v_total_fee,
        'application_fee_coins', v_application_fee,
        'monthly_fee_coins', v_monthly_fee
    );
END;
$$;

-- Function: approve_creator_claim
CREATE OR REPLACE FUNCTION public.approve_creator_claim(
    p_claim_id UUID,
    p_admin_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
BEGIN
    -- Check permissions
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = p_admin_id 
        AND (role IN ('admin', 'secretary', 'lead_troll_officer') OR is_admin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Get applicant ID
    SELECT user_id INTO v_user_id FROM public.creator_migration_claims WHERE id = p_claim_id;
    
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Claim not found');
    END IF;

    -- Update Claim Status
    UPDATE public.creator_migration_claims
    SET verification_status = 'approved',
        reviewed_by = p_admin_id,
        updated_at = NOW()
    WHERE id = p_claim_id;

    -- Update User Profile (Founder Badge, Boost, Broadcaster)
    UPDATE public.user_profiles
    SET 
        is_broadcaster = true,
        role = 'founder', 
        updated_at = NOW()
    WHERE id = v_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: approve_document
CREATE OR REPLACE FUNCTION public.approve_document(
  p_document_id UUID,
  p_approver_id UUID,
  p_comments TEXT DEFAULT NULL,
  p_ip_address INET DEFAULT NULL,
  p_user_agent TEXT DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_document RECORD;
  v_approver RECORD;
  v_stamp_id TEXT;
  v_verification_code TEXT;
  v_stamp_hash TEXT;
  v_document_checksum TEXT;
  v_approval_id UUID;
BEGIN
  -- Get document
  SELECT * INTO v_document FROM public.documents WHERE id = p_document_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Document not found');
  END IF;

  -- Check document is in approvable state
  IF v_document.status NOT IN ('pending', 'draft') THEN
    RETURN json_build_object('success', false, 'error', 'Document cannot be approved. Status: ' || v_document.status);
  END IF;

  -- Get approver profile
  SELECT * INTO v_approver FROM public.user_profiles WHERE id = p_approver_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Approver not found');
  END IF;

  -- Check approver has approval rights
  IF NOT (v_approver.is_admin = true OR v_approver.role IN ('admin', 'ceo', 'founder', 'owner', 'moderator', 'staff', 'lead_troll_officer')) THEN
    RETURN json_build_object('success', false, 'error', 'You do not have approval privileges');
  END IF;

  -- Check document is not already approved
  IF v_document.status = 'approved' THEN
    RETURN json_build_object('success', false, 'error', 'Document is already approved');
  END IF;

  -- Generate stamp values
  v_stamp_id := public.generate_stamp_id();
  v_verification_code := public.generate_verification_code();
  v_document_checksum := public.compute_document_checksum(v_document.content, v_document.title, v_document.submitted_by);
  v_stamp_hash := ENCODE(DIGEST(
    v_stamp_id || '|' || p_approver_id::TEXT || '|' || p_document_id::TEXT || '|' || v_document_checksum || '|' || NOW()::TEXT,
    'sha256'
  ), 'hex');

  -- Create approval record
  INSERT INTO public.document_approvals (
    document_id, approver_id, approver_username, approver_role,
    approval_type, decision, comments
  ) VALUES (
    p_document_id, p_approver_id, v_approver.username, v_approver.role,
    'final', 'approved', p_comments
  ) RETURNING id INTO v_approval_id;

  -- Create stamp
  INSERT INTO public.document_stamps (
    document_id, approval_id, stamp_id, seal_text,
    approver_id, approver_username, approver_role,
    approval_date, stamp_hash, verification_code,
    ip_address, document_checksum
  ) VALUES (
    p_document_id, v_approval_id, v_stamp_id, 'maitroll OFFICIAL',
    p_approver_id, v_approver.username, v_approver.role,
    now(), v_stamp_hash, v_verification_code,
    p_ip_address, v_document_checksum
  );

  -- Update document
  UPDATE public.documents SET
    status = 'approved',
    approved_by = p_approver_id,
    approved_at = now(),
    is_locked = true,
    checksum = v_document_checksum,
    updated_at = now()
  WHERE id = p_document_id;

  -- Log the event
  PERFORM public.log_document_event(
    p_document_id, p_approver_id, v_approver.username, v_approver.role,
    'document_approved',
    jsonb_build_object('stamp_id', v_stamp_id, 'verification_code', v_verification_code, 'comments', p_comments),
    p_ip_address, p_user_agent
  );

  RETURN json_build_object(
    'success', true,
    'stamp_id', v_stamp_id,
    'verification_code', v_verification_code,
    'stamp_hash', v_stamp_hash
  );
END;
$$;

-- Function: approve_family_agency_conversion
CREATE OR REPLACE FUNCTION public.approve_family_agency_conversion(
    p_application_id UUID,
    p_actor_id UUID,
    p_reason TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
    v_app public.agency_applications;
    v_actor_role TEXT;
    v_actor_is_hr BOOLEAN;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_actor_id THEN
        RAISE EXCEPTION 'Authentication required for the requesting actor';
    END IF;

    SELECT a.*
    INTO v_app
    FROM public.agency_applications a
    WHERE a.id = p_application_id
      AND a.status = 'pending'
      AND a.content_type = 'family_conversion'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Family conversion request not found or already reviewed';
    END IF;

    SELECT lower(COALESCE(role, ''))
    INTO v_actor_role
    FROM public.user_profiles
    WHERE id = p_actor_id
    LIMIT 1;

    SELECT COALESCE((SELECT is_admin FROM public.user_profiles WHERE id = p_actor_id), false)
    INTO v_actor_is_hr;

    IF v_actor_is_hr IS NOT TRUE AND COALESCE(v_actor_role, '') NOT IN ('admin', 'agency hr manager', 'agency_hr_manager') THEN
        RAISE EXCEPTION 'You do not have permission to approve family conversion requests';
    END IF;

    UPDATE public.agency_applications
    SET status = 'approved',
        reviewed_by = p_actor_id,
        reviewed_at = NOW()
    WHERE id = p_application_id;

    UPDATE public.agencies
    SET status = 'approved',
        updated_at = NOW()
    WHERE id = v_app.agency_id;

    UPDATE public.agency_members
    SET role = 'creator',
        status = 'active',
        removed_at = NULL
    WHERE agency_id = v_app.agency_id
      AND user_id = v_app.applicant_id;

    IF NOT FOUND THEN
        INSERT INTO public.agency_members (
            agency_id,
            user_id,
            role,
            status
        )
        VALUES (
            v_app.agency_id,
            v_app.applicant_id,
            'creator',
            'active'
        );
    END IF;

    INSERT INTO public.agency_enforcement_actions (
        agency_id,
        actor_id,
        target_user_id,
        action_type,
        reason,
        metadata
    )
    VALUES (
        v_app.agency_id,
        p_actor_id,
        v_app.applicant_id,
        'application_approved',
        COALESCE(nullif(btrim(p_reason), ''), 'Family conversion approved'),
        jsonb_build_object('application_id', p_application_id, 'source', 'family_conversion')
    );

    INSERT INTO public.agency_activity_logs (
        agency_id,
        actor_id,
        target_user_id,
        action,
        metadata
    )
    VALUES (
        v_app.agency_id,
        p_actor_id,
        v_app.applicant_id,
        'family_conversion_approved',
        jsonb_build_object('application_id', p_application_id, 'reason', COALESCE(nullif(btrim(p_reason), ''), 'Family conversion approved'))
    );

    RETURN jsonb_build_object(
        'success', true,
        'application_id', p_application_id,
        'agency_id', v_app.agency_id
    );
END;
$$;

-- Function: approve_officer_application
CREATE OR REPLACE FUNCTION approve_officer_application(p_user_id UUID)
RETURNS JSON AS $$
DECLARE
  v_app_id UUID;
BEGIN
  -- Permission check handled by RLS/Security Definier (assuming admin calls this)
  IF NOT is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: Admin only';
  END IF;

  -- Find pending application
  SELECT id INTO v_app_id FROM applications WHERE user_id = p_user_id AND type = 'troll_officer' AND status = 'pending';
  
  -- Update user role
  UPDATE user_profiles 
  SET role = 'troll_officer',
      is_troll_officer = true,
      is_officer_active = true,
      updated_at = NOW()
  WHERE id = p_user_id;

  -- Update application if exists
  IF v_app_id IS NOT NULL THEN
    UPDATE applications SET status = 'approved', reviewed_by = auth.uid(), reviewed_at = NOW() WHERE id = v_app_id;
  END IF;

  -- Notification
  INSERT INTO notifications (user_id, type, title, message)
  VALUES (p_user_id, 'application_result', 'Officer Application Approved', 'Welcome to the force! You are now a Troll Officer.');

  RETURN json_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Approve Lead Officer Application
DROP FUNCTION IF EXISTS approve_lead_officer_application(UUID, UUID);
CREATE OR REPLACE FUNCTION approve_lead_officer_application(p_application_id UUID, p_reviewer_id UUID)
RETURNS JSON AS $$
DECLARE
  v_user_id UUID;
BEGIN
  IF NOT is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: Admin only';
  END IF;

  SELECT user_id INTO v_user_id FROM applications WHERE id = p_application_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Application not found');
  END IF;

  -- Update User Role
  UPDATE user_profiles
  SET role = 'lead_officer',
      is_lead_officer = true,
      is_officer_active = true,
      updated_at = NOW()
  WHERE id = v_user_id;

  -- Update Application
  UPDATE applications
  SET status = 'approved',
      reviewed_by = p_reviewer_id,
      reviewed_at = NOW()
  WHERE id = p_application_id;

  -- Notification
  INSERT INTO notifications (user_id, type, title, message)
  VALUES (v_user_id, 'application_result', 'Lead Officer Application Approved', 'Congratulations! You have been promoted to Lead Officer.');

  RETURN json_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Deny Application (Generic)
DROP FUNCTION IF EXISTS deny_application(UUID, UUID, TEXT);
CREATE OR REPLACE FUNCTION deny_application(p_app_id UUID, p_reviewer_id UUID, p_reason TEXT DEFAULT NULL)
RETURNS JSON AS $$
DECLARE
  v_user_id UUID;
  v_type TEXT;
BEGIN
  IF NOT is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: Admin only';
  END IF;

  SELECT user_id, type INTO v_user_id, v_type FROM applications WHERE id = p_app_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Application not found');
  END IF;

  UPDATE applications
  SET status = 'rejected',
      reviewed_by = p_reviewer_id,
      reviewed_at = NOW(),
      notes = p_reason
  WHERE id = p_app_id;

  -- Notification
  INSERT INTO notifications (user_id, type, title, message)
  VALUES (v_user_id, 'application_result', 'Application Denied', 'Your application for ' || v_type || ' has been denied. Reason: ' || COALESCE(p_reason, 'No reason provided.'));

  RETURN json_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- General Approve Application Dispatcher
DROP FUNCTION IF EXISTS approve_application(UUID, UUID);
CREATE OR REPLACE FUNCTION approve_application(p_app_id UUID, p_reviewer_id UUID)
RETURNS JSON AS $$
DECLARE
  v_type TEXT;
  v_user_id UUID;
BEGIN
  -- Permission check
  IF NOT is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Access denied: Admin only';
  END IF;

  SELECT type, user_id INTO v_type, v_user_id FROM applications WHERE id = p_app_id;
  
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Application not found');
  END IF;

  IF v_type = 'seller' THEN
    -- Delegate to seller specific logic
    RETURN approve_seller_application(p_app_id, p_reviewer_id);
  ELSIF v_type = 'troll_officer' THEN
    -- Delegate to officer specific logic
    RETURN approve_officer_application(v_user_id);
  ELSIF v_type = 'lead_officer' THEN
    RETURN approve_lead_officer_application(p_app_id, p_reviewer_id);
  ELSE
    -- Generic approval
    UPDATE applications 
    SET status = 'approved', 
        reviewed_by = p_reviewer_id, 
        reviewed_at = NOW() 
    WHERE id = p_app_id;
    
    -- Generic Notification
    INSERT INTO notifications (user_id, type, title, message)
    VALUES (v_user_id, 'application_result', 'Application Approved', 'Your application for ' || v_type || ' has been approved.');

    RETURN json_build_object('success', true);
  END IF;
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- Create system_backup_requests table for tracking backup operations
CREATE TABLE IF NOT EXISTS system_backup_requests (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  requested_by UUID REFERENCES user_profiles(id),
  status TEXT DEFAULT 'pending', -- pending, processing, completed, failed
  created_at TIMESTAMPTZ DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  details JSONB
);

ALTER TABLE system_backup_requests ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Admins can manage backup requests" ON system_backup_requests;
CREATE POLICY "Admins can manage backup requests" ON system_backup_requests
  FOR ALL USING (
    EXISTS (SELECT 1 FROM user_profiles WHERE id = auth.uid() AND (role = 'admin' OR is_admin = true))
  );

-- Function to simulate backup processing (optional, for demo purposes if no real worker exists yet)
-- In a real system, an external worker/Edge Function would pick this up.
CREATE OR REPLACE FUNCTION trigger_manual_backup(p_admin_id UUID)
RETURNS UUID AS $$
DECLARE
  v_id UUID;
BEGIN
  -- Check admin
  IF NOT EXISTS (SELECT 1 FROM user_profiles WHERE id = p_admin_id AND (role = 'admin' OR is_admin = true)) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  INSERT INTO system_backup_requests (requested_by, status, details)
  VALUES (p_admin_id, 'pending', '{"type": "manual_full_dump"}')
  RETURNING id INTO v_id;
  
  RETURN v_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- Ensure stream_reports table exists for Admin Reports Panel
CREATE TABLE IF NOT EXISTS stream_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL, -- Can reference streams(id) but sometimes we might keep reports for deleted streams
  reporter_id UUID REFERENCES user_profiles(id),
  reason TEXT NOT NULL,
  status TEXT DEFAULT 'pending', -- pending, resolved, dismissed
  created_at TIMESTAMPTZ DEFAULT NOW(),
  resolved_at TIMESTAMPTZ,
  resolved_by UUID REFERENCES user_profiles(id)
);

-- Index for faster admin lookups
CREATE INDEX IF NOT EXISTS idx_stream_reports_status ON stream_reports(status);
CREATE INDEX IF NOT EXISTS idx_stream_reports_created_at ON stream_reports(created_at);

-- RLS
ALTER TABLE stream_reports ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone can insert reports" ON stream_reports;
CREATE POLICY "Anyone can insert reports" ON stream_reports
  FOR INSERT WITH CHECK (auth.uid() = reporter_id);

DROP POLICY IF EXISTS "Admins and Mods can view reports" ON stream_reports;
CREATE POLICY "Admins and Mods can view reports" ON stream_reports
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM user_profiles WHERE id = auth.uid() AND (role IN ('admin', 'moderator') OR is_admin = true))
  );

DROP POLICY IF EXISTS "Admins and Mods can update reports" ON stream_reports;
CREATE POLICY "Admins and Mods can update reports" ON stream_reports
  FOR UPDATE USING (
    EXISTS (SELECT 1 FROM user_profiles WHERE id = auth.uid() AND (role IN ('admin', 'moderator') OR is_admin = true))
  );

CREATE OR REPLACE FUNCTION assign_officer_patrol(
  p_officer_id UUID,
  p_patrol_type TEXT,
  p_instructions TEXT,
  p_priority INTEGER DEFAULT 1
) RETURNS UUID AS $$
DECLARE
  v_id UUID;
BEGIN
