-- Function: approve_treasury_payout_run
CREATE OR REPLACE FUNCTION public.approve_treasury_payout_run(p_payout_run_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_uid uuid;
  v_allowed boolean := false;
  v_treasury_id uuid;
  v_balance bigint;
  v_total_amount bigint;
BEGIN
  v_uid := auth.uid();

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_profiles
    WHERE id = v_uid
      AND (
        role IN ('admin', 'president', 'owner')
        OR is_admin = true
        OR role = 'ceo'
        OR troll_role IN ('admin', 'president', 'owner', 'ceo')
      )
  ) INTO v_allowed;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Only admins, CEOs, or the president can approve weekly treasury payout runs';
  END IF;

  UPDATE public.treasury_payout_runs
  SET status = 'approved',
      approved_by = v_uid,
      approved_at = now(),
      updated_at = now()
  WHERE id = p_payout_run_id
    AND status = 'draft'
  RETURNING id INTO p_payout_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Only draft treasury payout runs can be approved';
  END IF;

  SELECT id, balance_coins
    INTO v_treasury_id, v_balance
  FROM public.troll_city_treasury
  ORDER BY created_at ASC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.troll_city_treasury (treasury_name, balance_coins, total_earned_coins, total_distributed_coins, status)
    VALUES ('maitroll Treasury', 0, 0, 0, 'active')
    RETURNING id, balance_coins INTO v_treasury_id, v_balance;
  END IF;

  SELECT COALESCE(SUM(amount_coins), 0)
    INTO v_total_amount
  FROM public.treasury_payout_items
  WHERE payout_run_id = p_payout_run_id
    AND status = 'pending';

  IF v_total_amount > v_balance THEN
    RAISE EXCEPTION 'Insufficient treasury balance to approve this payout run';
  END IF;

  INSERT INTO public.treasury_transactions (
    treasury_id,
    transaction_type,
    source_type,
    source_id,
    direction,
    amount_coins,
    balance_before,
    balance_after,
    created_by,
    details
  )
  VALUES (
    v_treasury_id,
    'correction',
    'payout_run_approval',
    p_payout_run_id,
    'credit',
    0,
    v_balance,
    v_balance,
    v_uid,
    jsonb_build_object('action', 'approved', 'payout_run_id', p_payout_run_id)
  );

  RETURN jsonb_build_object(
    'payout_run_id', p_payout_run_id,
    'status', 'approved'
  );
END;
$$;

-- Function: assign_broadofficer
CREATE OR REPLACE FUNCTION public.assign_broadofficer(
    p_stream_id  uuid,
    p_officer_id uuid
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_actor        uuid := auth.uid();
    v_owner        uuid;
    v_already      boolean := false;
BEGIN
    IF v_actor IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;
    IF p_stream_id IS NULL OR p_officer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Missing stream or officer');
    END IF;

    SELECT user_id INTO v_owner FROM public.streams WHERE id = p_stream_id;
    IF v_owner IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Stream not found');
    END IF;

    -- Only the stream owner (or admin) may assign officers for this stream
    IF NOT public.is_stream_owner_or_admin(p_stream_id, v_actor) THEN
        RETURN jsonb_build_object('success', false, 'error', 'You do not control this stream');
    END IF;

    IF p_officer_id = v_owner THEN
        RETURN jsonb_build_object('success', false, 'error', 'The broadcaster is already the host');
    END IF;

    -- Detect duplicate assignment (idempotent) to prevent duplicate messages
    SELECT EXISTS (
        SELECT 1 FROM public.broadcast_officers
        WHERE broadcaster_id = v_owner AND officer_id = p_officer_id AND stream_id = p_stream_id
    ) INTO v_already;

    IF NOT v_already THEN
        INSERT INTO public.broadcast_officers (broadcaster_id, officer_id, stream_id)
        VALUES (v_owner, p_officer_id, p_stream_id)
        ON CONFLICT (broadcaster_id, officer_id, stream_id) DO NOTHING;
    END IF;

    RETURN jsonb_build_object('success', true, 'already_assigned', v_already);
END;
$$;

-- Function: assign_document
CREATE OR REPLACE FUNCTION public.assign_document(
  p_document_id UUID,
  p_assign_to_user_id UUID,
  p_assigned_by_user_id UUID
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_assigner RECORD;
  v_assignee RECORD;
BEGIN
  SELECT * INTO v_assigner FROM public.user_profiles WHERE id = p_assigned_by_user_id;
  IF NOT (v_assigner.is_admin = true OR v_assigner.role IN ('admin', 'ceo', 'founder', 'owner', 'lead_troll_officer', 'staff')) THEN
    RETURN json_build_object('success', false, 'error', 'Insufficient privileges to assign documents');
  END IF;

  SELECT username INTO v_assignee FROM public.user_profiles WHERE id = p_assign_to_user_id;
  IF v_assignee IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Assignee not found');
  END IF;

  UPDATE public.documents SET
    assigned_to = p_assign_to_user_id,
    assigned_at = now(),
    updated_at = now()
  WHERE id = p_document_id;

  -- Grant access
  INSERT INTO public.document_access (document_id, user_id, access_level, granted_by)
  VALUES (p_document_id, p_assign_to_user_id, 'approve', p_assigned_by_user_id)
  ON CONFLICT (document_id, user_id) DO UPDATE SET access_level = 'approve', is_active = true;

  PERFORM public.log_document_event(
    p_document_id, p_assigned_by_user_id, v_assigner.username, v_assigner.role,
    'document_assigned',
    jsonb_build_object('assigned_to', v_assignee)
  );

  RETURN json_build_object('success', true);
END;
$$;

-- Function: assistant_forward_payout_batch
CREATE OR REPLACE FUNCTION public.assistant_forward_payout_batch(
    p_payout_ids UUID[],
    p_assistant_id UUID,
    p_assistant_username TEXT,
    p_batch_label TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_batch_id UUID;
    v_week_end DATE;
    v_total_coins BIGINT := 0;
    v_total_cash NUMERIC(12,2) := 0;
    v_request_count INT := 0;
BEGIN
    -- Validate all payouts are in pending status
    IF EXISTS (
        SELECT 1 FROM public.payout_requests
        WHERE id = ANY(p_payout_ids)
          AND status != 'pending'
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'All payouts must be in pending status. One or more are not pending.'
        );
    END IF;

    -- Calculate totals
    SELECT COALESCE(SUM(coin_amount), 0), COALESCE(SUM(cash_amount), 0), COUNT(*)
    INTO v_total_coins, v_total_cash, v_request_count
    FROM public.payout_requests
    WHERE id = ANY(p_payout_ids);

    -- Determine week end (Friday)
    v_week_end := date_trunc('week', CURRENT_DATE)::date + INTERVAL '4 days';

    -- Create the batch
    INSERT INTO public.payout_batches (
        week_end,
        payout_date,
        status,
        total_requests,
        total_usd,
        created_at
    ) VALUES (
        v_week_end,
        CURRENT_DATE,
        'open',
        v_request_count,
        v_total_cash,
        NOW()
    ) RETURNING id INTO v_batch_id;

    -- Update all payouts to link to batch and mark as forwarded
    UPDATE public.payout_requests
    SET batch_id = v_batch_id,
        forwarded_to_admin = TRUE,
        forwarded_to_admin_at = NOW(),
        reviewed_by_assistant_id = p_assistant_id,
        reviewed_by_assistant_username = p_assistant_username,
        assistant_reviewed_at = NOW(),
        status = 'reviewed',
        updated_at = NOW()
    WHERE id = ANY(p_payout_ids);

    RETURN jsonb_build_object(
        'success', true,
        'batch_id', v_batch_id,
        'batch_label', COALESCE(p_batch_label, 'Batch ' || v_batch_id::text),
        'total_requests', v_request_count,
        'total_coins', v_total_coins,
        'total_cash', v_total_cash,
        'week_end', v_week_end,
        'message', format('Payout batch created with %s requests totaling $%s. Forwarded to admin Operations & Control Deck.', v_request_count, v_total_cash)
    );
END;
$$;

-- Function: assistant_review_user_coins
CREATE OR REPLACE FUNCTION public.assistant_review_user_coins(
    p_user_id UUID,
    p_week_start DATE DEFAULT NULL,
    p_week_end DATE DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_week_start DATE;
    v_week_end DATE;
    v_user_info JSONB;
BEGIN
    v_week_start := COALESCE(p_week_start, date_trunc('week', CURRENT_DATE)::date);
    v_week_end := COALESCE(p_week_end, v_week_start + INTERVAL '6 days');

    -- Get user profile info
    SELECT jsonb_build_object(
        'user_id', up.id,
        'username', up.username,
        'display_name', up.display_name,
        'role', up.role,
        'troll_coins', up.troll_coins,
        'reserved_troll_coins', up.reserved_troll_coins,
        'current_balance', COALESCE(up.troll_coins, 0) - COALESCE(up.reserved_troll_coins, 0)
    ) INTO v_user_info
    FROM public.user_profiles up
    WHERE up.id = p_user_id;

    IF v_user_info IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'User not found');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'user', v_user_info,
        'week_start', v_week_start,
        'week_end', v_week_end,
        'working_earnings', (
            SELECT COALESCE(jsonb_agg(e.* ORDER BY e.created_at DESC), '[]'::jsonb)
            FROM public.weekly_working_earnings e
            WHERE e.user_id = p_user_id
              AND e.week_start >= v_week_start
              AND e.week_end <= v_week_end
        ),
        'coin_transactions', (
            SELECT COALESCE(jsonb_agg(t.* ORDER BY t.created_at DESC), '[]'::jsonb)
            FROM public.coin_transactions t
            WHERE t.user_id = p_user_id
              AND t.created_at >= v_week_start
              AND t.created_at <= (v_week_end + INTERVAL '1 day')
        ),
        'total_earned_this_week', (
            SELECT COALESCE(SUM(amount_coins), 0)
            FROM public.weekly_working_earnings
            WHERE user_id = p_user_id
              AND week_start >= v_week_start
              AND week_end <= v_week_end
              AND status IN ('pending', 'converted')
        ),
        'total_cashed_out_this_week', (
            SELECT COALESCE(SUM(coin_amount), 0)
            FROM public.payout_requests
            WHERE user_id = p_user_id
              AND created_at >= v_week_start
              AND created_at <= (v_week_end + INTERVAL '1 day')
              AND status NOT IN ('rejected')
        )
    );
END;
$$;

-- Function: award_game_coins
CREATE OR REPLACE FUNCTION award_game_coins(
  p_user_id UUID,
  p_game_type VARCHAR(50),
  p_match_id UUID,
  p_amount INTEGER DEFAULT 10
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_result JSONB;
  v_wallet_id UUID;
  v_existing_match RECORD;
  v_current_balance INTEGER;
BEGIN
  -- Validate inputs
  IF p_user_id IS NULL OR p_game_type IS NULL OR p_match_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Missing required parameters');
  END IF;

  IF p_amount <= 0 OR p_amount > 100 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid coin amount');
  END IF;

  -- Verify match exists and is valid
  SELECT * INTO v_existing_match
  FROM game_matches
  WHERE id = p_match_id 
    AND game_type = p_game_type
    AND winner_id = p_user_id
    AND reward_claimed = FALSE;

  IF v_existing_match IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid match or reward already claimed');
  END IF;

  -- Get or create user wallet
  SELECT id INTO v_wallet_id
  FROM wallets
  WHERE user_id = p_user_id;

  IF v_wallet_id IS NULL THEN
    -- Create wallet if doesn't exist
    INSERT INTO wallets (user_id, balance)
    VALUES (p_user_id, 0)
    RETURNING id INTO v_wallet_id;
  END IF;

  -- Get current balance
  SELECT balance INTO v_current_balance
  FROM wallets
  WHERE id = v_wallet_id;

  -- Update wallet balance
  UPDATE wallets
  SET balance = balance + p_amount,
      updated_at = NOW()
  WHERE id = v_wallet_id;

  -- Record transaction
  INSERT INTO wallet_transactions (
    wallet_id,
    user_id,
    amount,
    transaction_type,
    description,
    metadata
  ) VALUES (
    v_wallet_id,
    p_user_id,
    p_amount,
    'game_reward',
    format('Won %s game', p_game_type),
    jsonb_build_object(
      'game_type', p_game_type,
      'match_id', p_match_id,
      'previous_balance', v_current_balance
    )
  );

  -- Mark reward as claimed in match record
  UPDATE game_matches
  SET reward_claimed = TRUE, coins_awarded = p_amount
  WHERE id = p_match_id;

  -- Return success
  RETURN jsonb_build_object(
    'success', true,
    'coins_awarded', p_amount,
    'new_balance', v_current_balance + p_amount,
    'match_id', p_match_id
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: award_league_points
CREATE OR REPLACE FUNCTION public.award_league_points(
    p_user_id UUID,
    p_event_type TEXT,
    p_points INTEGER,
    p_stream_id UUID DEFAULT NULL,
    p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_event public.league_events%ROWTYPE;
  v_award INTEGER := GREATEST(COALESCE(p_points, 0), 0);
  v_multiplier NUMERIC := 1;
  v_increment INTEGER := COALESCE((p_metadata->>'increment')::INTEGER, 1);
  v_xp BIGINT := COALESCE((p_metadata->>'xp')::BIGINT, 0);
BEGIN
  IF p_user_id IS NULL OR p_event_type IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Missing user or event type');
  END IF;

  SELECT * INTO v_event FROM public.get_active_league_event();
  IF NOT FOUND THEN
    SELECT * INTO v_event FROM public.create_system_league_event();
  END IF;

  IF v_event.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'No active league event');
  END IF;

  v_multiplier := COALESCE(v_event.points_multiplier, 1);
  v_award := CEIL(v_award * v_multiplier)::INTEGER;

  INSERT INTO public.league_points (user_id, league_event_id, stream_id, event_type, points, metadata)
  VALUES (p_user_id, v_event.id, p_stream_id, p_event_type, v_award, p_metadata);

  PERFORM public.refresh_league_leaderboard(v_event.id);
  PERFORM public.update_user_mission_progress(p_user_id, p_event_type, v_increment, p_metadata);

  IF v_xp > 0 AND EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'grant_xp') THEN
    PERFORM public.grant_xp(p_user_id, v_xp, 'league_points', v_event.id::text, p_metadata);
  END IF;

  RETURN jsonb_build_object(
      'success', true,
      'user_id', p_user_id,
      'league_event_id', v_event.id,
      'awarded_points', v_award,
      'event_type', p_event_type
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'award_league_points failed: %', SQLERRM;
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- Function: ban_user
CREATE OR REPLACE FUNCTION public.ban_user(
  target UUID,
  minutes INTEGER,
  reason TEXT,
  acting_admin_id UUID DEFAULT NULL
) RETURNS JSONB AS $$
DECLARE
  v_actor_id UUID;
  v_actor_role TEXT;
  v_is_admin BOOLEAN;
  v_is_lead BOOLEAN;
  v_is_officer BOOLEAN;
  v_target_is_admin BOOLEAN;
  v_until TIMESTAMPTZ;
BEGIN
  v_actor_id := auth.uid();

  -- Service Role Bypass
  IF auth.role() = 'service_role' AND acting_admin_id IS NOT NULL THEN
      v_actor_id := acting_admin_id;
  END IF;

  -- Actor permissions
  SELECT role, is_admin, is_lead_officer, is_troll_officer
  INTO v_actor_role, v_is_admin, v_is_lead, v_is_officer
  FROM public.user_profiles
  WHERE id = v_actor_id;

  IF NOT (v_is_admin OR v_is_lead OR v_is_officer OR v_actor_role IN ('admin','lead_troll_officer','troll_officer')) THEN
    INSERT INTO public.moderation_actions(actor_id, target_user_id, action_type, reason, status, error_message)
    VALUES (v_actor_id, target, 'ban_user', reason, 'rejected', 'Not authorized');
    RETURN jsonb_build_object('status','error','message','Not authorized');
  END IF;

  -- Block banning admin
  SELECT (role = 'admin' OR is_admin = true)
  INTO v_target_is_admin
  FROM public.user_profiles
  WHERE id = target;

  IF v_target_is_admin THEN
    INSERT INTO public.moderation_actions(actor_id, target_user_id, action_type, reason, status, error_message)
    VALUES (v_actor_id, target, 'ban_user', reason, 'rejected', 'Cannot ban admin');
    RETURN jsonb_build_object('status','error','message','Cannot ban admin');
  END IF;

  -- Duration
  v_until := CASE WHEN minutes > 0 THEN now() + (minutes || ' minutes')::interval ELSE NULL END;

  UPDATE public.user_profiles
  SET
    is_banned = true,
    banned_until = v_until,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('ban_reason', reason),
    updated_at = now()
  WHERE id = target;

  INSERT INTO public.moderation_actions(actor_id, target_user_id, action_type, reason, payload, status)
  VALUES (
    v_actor_id,
    target,
    'ban_user',
    reason,
    jsonb_build_object('minutes', minutes, 'banned_until', v_until),
    'active'
  );

  RETURN jsonb_build_object('status','ok','banned_until', v_until);

EXCEPTION WHEN others THEN
  INSERT INTO public.moderation_actions(actor_id, target_user_id, action_type, reason, status, error_message)
  VALUES (v_actor_id, target, 'ban_user', reason, 'rejected', sqlerrm);
  RETURN jsonb_build_object('status','error','message','Ban failed','error', sqlerrm);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Migration: Low-Minute Protection Mode (LMPM) - Fix & Alignment
-- Description: Corrects admin_settings column names and enforces strict limits on broadcasts.

-- 1. Create or Update admin_app_settings for LMPM flag (Using actual schema: setting_key, setting_value)
INSERT INTO public.admin_app_settings (setting_key, setting_value, description)
VALUES (
    'low_minute_protection_mode', 
    '{"enabled": true}', 
    'When enabled, limits to 1 broadcast per day, 30 min max, 1 simultaneous stream.'
)
ON CONFLICT (setting_key) DO UPDATE 
SET setting_value = EXCLUDED.setting_value,
    description = EXCLUDED.description,
    updated_at = NOW();

-- 2. Update can_start_broadcast RPC with LMPM logic
CREATE OR REPLACE FUNCTION public.can_start_broadcast(p_user_id UUID DEFAULT auth.uid())
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_is_admin BOOLEAN;
    v_lockdown_enabled BOOLEAN;
    v_is_locked BOOLEAN;
    v_has_badge BOOLEAN;
    v_lmpm_enabled BOOLEAN;
    v_active_streams_count INT;
    v_daily_broadcast_count INT;
BEGIN
    -- Get user info
    SELECT
        (COALESCE(is_admin, false) = true OR role IN ('admin', 'secretary', 'lead_troll_officer', 'troll_officer')),
        COALESCE(is_broadcast_locked, false),
        COALESCE(has_broadcast_badge, false)
    INTO v_is_admin, v_is_locked, v_has_badge
    FROM public.user_profiles
    WHERE id = p_user_id;

    -- 1. Immediate Lock Check
    IF v_is_locked THEN
        RETURN jsonb_build_object('can_start', false, 'message', 'Your broadcasting permit has been suspended.');
    END IF;

    -- 2. Global Lockdown Check (Using admin_app_settings)
    SELECT (setting_value::jsonb->>'enabled')::boolean
    INTO v_lockdown_enabled
    FROM public.admin_app_settings
    WHERE setting_key = 'broadcast_lockdown_enabled'
    LIMIT 1;

    IF COALESCE(v_lockdown_enabled, false) AND NOT v_is_admin THEN
        RETURN jsonb_build_object('can_start', false, 'message', 'City bandwidth exhausted for today.');
    END IF;

    -- 3. Low-Minute Protection Mode (LMPM) Checks
    SELECT (setting_value::jsonb->>'enabled')::boolean
    INTO v_lmpm_enabled
    FROM public.admin_app_settings
    WHERE setting_key = 'low_minute_protection_mode'
    LIMIT 1;

    IF COALESCE(v_lmpm_enabled, false) THEN
        -- Rule: 1 simultaneous stream globally
        SELECT count(*) INTO v_active_streams_count 
        FROM public.streams 
        WHERE status = 'active' OR is_live = true;

        IF v_active_streams_count >= 1 THEN
            RETURN jsonb_build_object('can_start', false, 'message', 'Arena capacity reached. Another session is in progress.');
        END IF;

        -- Rule: 1 broadcast per calendar day (UTC Safe)
        SELECT count(*) INTO v_daily_broadcast_count
        FROM public.streams
        WHERE created_at >= ((NOW() AT TIME ZONE 'utc')::date)
        AND (status IN ('active', 'completed', 'ended'));

        IF v_daily_broadcast_count >= 1 THEN
            RETURN jsonb_build_object('can_start', false, 'message', 'Daily broadcast limit reached. Next session tomorrow.');
        END IF;
    END IF;

    -- 4. Category/Gaming check
    -- All users can broadcast normally without restrictions
    -- Gaming/Trollmers streams require 100 followers (admins bypass)

    RETURN jsonb_build_object('can_start', true);
END;
$$;

-- Function: bulk_update_beta_feedback
CREATE OR REPLACE FUNCTION public.bulk_update_beta_feedback(
  p_ids uuid[],
  p_status text DEFAULT NULL,
  p_priority text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_archive boolean DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET statement_timeout = '30s'
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_id uuid;
  v_old public.beta_feedback%ROWTYPE;
  v_updated integer := 0;
  v_valid_status boolean := (p_status IS NULL OR p_status IN (
    'submitted','under_review','needs_information','confirmed','planned','in_progress',
    'fixed','declined','duplicate','closed'));
  v_valid_priority boolean := (p_priority IS NULL OR p_priority IN ('low','normal','high','critical'));
  v_valid_category boolean := (p_category IS NULL OR p_category IN (
    'Bug Report','Mobile / PWA','Broadcast','Chat','Neighborhoods','Troll Court',
    'Troll Coins','Performance','Account / Login','Design / UI','Feature Request','Other'));
BEGIN
  IF v_actor IS NULL OR NOT public.is_beta_feedback_moderator(v_actor) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  IF NOT (v_valid_status AND v_valid_priority AND v_valid_category) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid bulk value');
  END IF;
  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No ids provided');
  END IF;

  FOREACH v_id IN ARRAY p_ids LOOP
    SELECT * INTO v_old FROM public.beta_feedback WHERE id = v_id;
    IF v_old.id IS NULL THEN
      CONTINUE;
    END IF;
    UPDATE public.beta_feedback
    SET status = COALESCE(p_status, status),
        priority = COALESCE(p_priority, priority),
        category = COALESCE(p_category, category),
        archived_at = CASE WHEN p_archive IS NULL THEN archived_at
                           WHEN p_archive THEN now() ELSE NULL END,
        updated_at = now()
    WHERE id = v_id;
    PERFORM public.log_beta_feedback_audit(v_id, v_actor, 'bulk_update',
      jsonb_build_object('status', v_old.status, 'priority', v_old.priority, 'category', v_old.category),
      jsonb_build_object('status', COALESCE(p_status, v_old.status),
                         'priority', COALESCE(p_priority, v_old.priority),
                         'category', COALESCE(p_category, v_old.category),
                         'archive', p_archive));
    v_updated := v_updated + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'updated', v_updated);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: buy_property_with_loan
CREATE OR REPLACE FUNCTION public.buy_property_with_loan(p_property_id UUID, p_down_payment numeric)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_property RECORD;
    v_price numeric(20, 2);
    v_loan_amount numeric(20, 2);
    v_min_down numeric(20, 2);
    v_balance numeric(20, 2);
    v_loan_id UUID;
    v_prev_owner_id UUID;
BEGIN
    SELECT * INTO v_property FROM public.properties WHERE id = p_property_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Property not found');
    END IF;

    -- Use price column
    v_price := v_property.price;
    v_min_down := ceil(v_price * 0.10); -- 10% minimum

    IF p_down_payment < v_min_down THEN
        RETURN jsonb_build_object('success', false, 'error', 'Down payment must be at least 10%');
    END IF;

    -- Check Balance
    SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    IF v_balance < p_down_payment THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds for down payment');
    END IF;

    v_loan_amount := v_price - p_down_payment;
    v_prev_owner_id := v_property.owner_id;

    -- Deduct Down Payment
    UPDATE public.user_profiles SET troll_coins = troll_coins - p_down_payment WHERE id = v_user_id;
    
    -- Update Property Ownership
    UPDATE public.properties 
    SET owner_id = v_user_id, 
        owner_user_id = v_user_id, 
        is_for_sale = false, 
        is_for_rent = true 
    WHERE id = p_property_id;

    -- Create Loan if amount > 0
    IF v_loan_amount > 0 THEN
        INSERT INTO public.property_loans (
            user_id, property_id, total_amount, remaining_amount, monthly_payment, next_payment_due_at
        ) VALUES (
            v_user_id, p_property_id, v_loan_amount, v_loan_amount, ceil(v_loan_amount / 4.0), NOW() + INTERVAL '7 days'
        );
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: buy_raffle_ticket
CREATE OR REPLACE FUNCTION public.buy_raffle_ticket(
  p_raffle_id uuid,
  p_quantity integer DEFAULT 1
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_raffle record;
  v_user_id uuid;
  v_cost integer;
  v_balance integer;
  v_ticket_count integer;
  i integer;
BEGIN
  v_user_id := auth.uid();

  IF p_quantity < 1 OR p_quantity > 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid quantity (1-10)');
  END IF;

  SELECT * INTO v_raffle FROM public.stream_raffles
  WHERE id = p_raffle_id AND status = 'active';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Raffle not found or not active');
  END IF;

  v_cost := v_raffle.ticket_cost * p_quantity;

  UPDATE public.user_profiles
  SET troll_coins = troll_coins - v_cost,
      total_spent_coins = COALESCE(total_spent_coins, 0) + v_cost,
      updated_at = now()
  WHERE id = v_user_id AND COALESCE(troll_coins, 0) >= v_cost;

  IF NOT FOUND THEN
    SELECT COALESCE(troll_coins, 0) INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient coins', 'required', v_cost, 'balance', v_balance);
  END IF;

  FOR i IN 1..p_quantity LOOP
    INSERT INTO public.stream_raffle_tickets (raffle_id, stream_id, user_id, round_number, cost)
    VALUES (p_raffle_id, v_raffle.stream_id, v_user_id, v_raffle.current_round, v_raffle.ticket_cost);
  END LOOP;

  SELECT COUNT(*) INTO v_ticket_count FROM public.stream_raffle_tickets
  WHERE raffle_id = p_raffle_id AND user_id = v_user_id AND round_number = v_raffle.current_round;

  SELECT COALESCE(troll_coins, 0) INTO v_balance FROM public.user_profiles WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'tickets_purchased', p_quantity,
    'total_tickets', v_ticket_count,
    'cost', v_cost,
    'new_balance', v_balance
  );
END;
$$;

-- Function: can_send_utromail
CREATE OR REPLACE FUNCTION public.can_send_utromail(sender_id uuid, recipient_id uuid)
RETURNS boolean AS $$
DECLARE
  v_privacy text;
  v_blocked boolean;
  v_sender_follows boolean;
  v_recipient_follows boolean;
  v_mutual boolean;
  v_recipient_verified boolean;
  v_sender_staff boolean;
  v_recipient_staff boolean;
BEGIN
  -- Staff can always send
  SELECT EXISTS(SELECT 1 FROM public.user_profiles WHERE id = sender_id AND (
    is_admin OR role IN ('admin','ceo','superadmin','troll_officer','lead_troll_officer','secretary',
    'academy_teacher','academy_director','admissions_officer','moderator','attorney','prosecutor')
  )) INTO v_sender_staff;
  
  IF v_sender_staff THEN RETURN true; END IF;

  -- Check if sender is utromail_disabled
  IF EXISTS(SELECT 1 FROM public.user_profiles WHERE id = sender_id AND utromail_disabled = true) THEN
    RETURN false;
  END IF;

  -- Check if recipient blocks sender
  SELECT EXISTS(SELECT 1 FROM public.utromail_blocks WHERE blocker_id = recipient_id AND blocked_id = sender_id) INTO v_blocked;
  IF v_blocked THEN RETURN false; END IF;

  -- Allow anyone to message admin/staff recipients
  SELECT EXISTS(SELECT 1 FROM public.user_profiles WHERE id = recipient_id AND (
    is_admin OR role IN ('admin','ceo','superadmin','troll_officer','lead_troll_officer','secretary',
    'academy_teacher','academy_director','admissions_officer','moderator','attorney','prosecutor')
  )) INTO v_recipient_staff;
  
  IF v_recipient_staff THEN RETURN true; END IF;

  -- Get recipient privacy setting
  SELECT mail_privacy_setting INTO v_privacy FROM public.user_profiles WHERE id = recipient_id;
  IF v_privacy IS NULL THEN v_privacy := 'mutual_followers'; END IF;

  -- Check verified status
  SELECT (is_verified = true) INTO v_recipient_verified FROM public.user_profiles WHERE id = sender_id;

  -- Check follow relationships
  SELECT EXISTS(SELECT 1 FROM public.user_follows WHERE follower_id = sender_id AND following_id = recipient_id) INTO v_sender_follows;
  SELECT EXISTS(SELECT 1 FROM public.user_follows WHERE follower_id = recipient_id AND following_id = sender_id) INTO v_recipient_follows;
  v_mutual := v_sender_follows AND v_recipient_follows;

  CASE v_privacy
    WHEN 'everyone' THEN RETURN true;
    WHEN 'following' THEN RETURN v_sender_follows;
    WHEN 'mutual_followers' THEN RETURN v_mutual;
    WHEN 'verified_only' THEN RETURN v_recipient_verified;
    ELSE RETURN v_mutual;
  END CASE;
END;
$$ LANGUAGE plpgsql;

-- Allow conversation creators (or members inserting themselves) to add members
create policy "members_insert_owner_or_self"
  on public.conversation_members
  for insert
  to authenticated
  with check (
    user_id = auth.uid()
    or exists (
      select 1
      from public.conversations c
      where c.id = conversation_members.conversation_id
        and c.created_by = auth.uid()
    )
  );

DO $$ BEGIN
