EXCEPTION WHEN duplicate_column THEN NULL; END $$;

-- Function: can_set_to_user
CREATE OR REPLACE FUNCTION public.can_set_to_user(
  p_actor_id uuid,
  p_target_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor record;
  v_target record;
BEGIN
  -- Allow service_role to bypass (used by edge functions)
  IF auth.role() = 'service_role' THEN
    RETURN jsonb_build_object('allowed', true);
  END IF;

  -- Load actor profile
  SELECT role, is_admin, is_lead_officer, is_troll_officer, is_secretary
  INTO v_actor
  FROM user_profiles
  WHERE id = p_actor_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Actor not found');
  END IF;

  -- Only Lead Troll Officer, Admin, or Secretary can set users to user role
  IF NOT (
    v_actor.is_admin = true
    OR v_actor.role IN ('admin', 'superadmin', 'secretary')
    OR v_actor.is_lead_officer = true
    OR v_actor.role = 'lead_troll_officer'
    OR v_actor.is_secretary = true
  ) THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Unauthorized: Lead Officer, Admin, or Secretary role required');
  END IF;

  -- Load target profile
  SELECT role, is_admin, is_lead_officer, is_troll_officer, is_secretary
  INTO v_target
  FROM user_profiles
  WHERE id = p_target_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Target user not found');
  END IF;

  -- Cannot demote admin/CEO/owner
  IF v_target.is_admin = true
    OR v_target.role IN ('admin', 'superadmin', 'ceo', 'owner')
    OR v_target.is_lead_officer = true
    OR v_target.role = 'lead_troll_officer'
  THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Cannot demote elevated staff roles');
  END IF;

  RETURN jsonb_build_object('allowed', true);
END;
$$;

-- Function: can_user_broadcast
CREATE OR REPLACE FUNCTION public.can_user_broadcast(p_user_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_license_status TEXT;
  v_has_restriction BOOLEAN;
BEGIN
  SELECT drivers_license_status INTO v_license_status
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF v_license_status IS NULL OR v_license_status = 'none' OR v_license_status = 'suspended' THEN
    RETURN jsonb_build_object('can_broadcast', false);
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.user_broadcast_restrictions
    WHERE user_id = p_user_id AND status = 'active'
  ) INTO v_has_restriction;

  IF v_has_restriction THEN
    RETURN jsonb_build_object('can_broadcast', false);
  END IF;

  RETURN jsonb_build_object('can_broadcast', true);
END;
$$;

-- Function: cancel_battle_challenge
CREATE OR REPLACE FUNCTION public.cancel_battle_challenge(
    p_battle_id UUID,
    p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_battle RECORD;
    v_challenger_owner UUID;
    v_opponent_owner UUID;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
    END IF;

    SELECT * INTO v_battle
    FROM public.battles
    WHERE id = p_battle_id;

    IF v_battle IS NULL OR v_battle.status <> 'pending' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Battle not pending');
    END IF;

    SELECT user_id INTO v_challenger_owner FROM public.streams WHERE id = v_battle.challenger_stream_id;
    SELECT user_id INTO v_opponent_owner FROM public.streams WHERE id = v_battle.opponent_stream_id;

    IF p_user_id IS DISTINCT FROM v_challenger_owner AND p_user_id IS DISTINCT FROM v_opponent_owner THEN
        RETURN jsonb_build_object('success', false, 'message', 'Not a participant');
    END IF;

    UPDATE public.battles
    SET status = 'ended', ended_at = NOW()
    WHERE id = p_battle_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: cancel_event_registration
CREATE OR REPLACE FUNCTION public.cancel_event_registration(
  p_event_id UUID,
  p_user_id UUID
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_registration RECORD;
  v_next_waitlisted RECORD;
BEGIN
  SELECT * INTO v_registration FROM public.event_participants
  WHERE event_id = p_event_id AND user_id = p_user_id;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Registration not found');
  END IF;

  IF v_registration.status = 'cancelled' THEN
    RETURN json_build_object('success', false, 'error', 'Registration already cancelled');
  END IF;

  UPDATE public.event_participants
  SET status = 'cancelled'
  WHERE id = v_registration.id;

  -- If there was a waitlist, promote the first person
  IF v_registration.status IN ('registered', 'confirmed') THEN
    SELECT * INTO v_next_waitlisted FROM public.event_participants
    WHERE event_id = p_event_id AND status = 'waitlisted'
    ORDER BY registered_at ASC
    LIMIT 1;

    IF FOUND THEN
      UPDATE public.event_participants
      SET status = 'registered'
      WHERE id = v_next_waitlisted.id;
    END IF;
  END IF;

  RETURN json_build_object('success', true);
END;
$$;

-- Function: cancel_trollmers_tournament
CREATE OR REPLACE FUNCTION public.cancel_trollmers_tournament(p_tournament_id UUID)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    UPDATE public.trollmers_monthly_tournaments
    SET status = 'cancelled'
    WHERE id = p_tournament_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Tournament not found');
    END IF;

    RETURN jsonb_build_object('success', true, 'tournament_id', p_tournament_id);
END;
$$;

-- Function: check_game_cooldown
CREATE OR REPLACE FUNCTION check_game_cooldown(
  p_user_id UUID,
  p_game_type VARCHAR(50),
  p_seconds INTEGER DEFAULT 30
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_recent_match BOOLEAN;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM game_matches
    WHERE game_type = p_game_type
      AND p_user_id = ANY(players)
      AND created_at > NOW() - (p_seconds || ' seconds')::interval
  ) INTO v_recent_match;

  RETURN v_recent_match;
END;
$$;

-- Function: check_trade_cooldown
CREATE OR REPLACE FUNCTION public.check_trade_cooldown(
    p_user_id UUID, 
    p_stock_id UUID
)
RETURNS TABLE(
    can_trade BOOLEAN,
    cooldown_remaining INTEGER,
    message TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_last_trade TIMESTAMPTZ;
    v_cooldown_seconds INTEGER := 30;
    v_seconds_since_trade INTEGER;
BEGIN
    SELECT value::INTEGER INTO v_cooldown_seconds FROM public.stock_market_settings WHERE key = 'trading_cooldown_seconds';
    SELECT last_trade_at INTO v_last_trade FROM public.stock_trade_cooldowns WHERE user_id = p_user_id AND stock_id = p_stock_id;
    IF v_last_trade IS NULL THEN
        RETURN QUERY SELECT TRUE, 0, 'Can trade';
        RETURN;
    END IF;
    v_seconds_since_trade := EXTRACT(EPOCH FROM (NOW() - v_last_trade))::INTEGER;
    IF v_seconds_since_trade >= v_cooldown_seconds THEN
        RETURN QUERY SELECT TRUE, 0, 'Can trade';
    ELSE
        RETURN QUERY SELECT FALSE, v_cooldown_seconds - v_seconds_since_trade, format('Please wait %s seconds before trading this stock again', v_cooldown_seconds - v_seconds_since_trade);
    END IF;
END;
$$;

-- Function: check_verification_eligibility
CREATE OR REPLACE FUNCTION public.check_verification_eligibility(
  p_user_id UUID
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_profile RECORD;
  v_account_age_hours INTEGER;
  v_has_reports BOOLEAN;
  v_is_jailed BOOLEAN;
BEGIN
  SELECT
    created_at,
    account_state,
    EXISTS(SELECT 1 FROM public.user_history WHERE user_id = p_user_id AND action_type = 'report' AND created_at > now() - INTERVAL '24 hours') as has_recent_reports,
    EXISTS(SELECT 1 FROM public.jail WHERE user_id = p_user_id AND status = 'jailed') as is_jailed
  INTO v_profile
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RETURN json_build_object('eligible', false, 'reason', 'User not found');
  END IF;

  v_account_age_hours := EXTRACT(EPOCH FROM (now() - v_profile.created_at)) / 3600;

  IF v_account_age_hours < 24 THEN
    RETURN json_build_object(
      'eligible', false,
      'reason', 'Account must be active for at least 24 hours'
    );
  END IF;

  IF v_profile.is_jailed THEN
    RETURN json_build_object(
      'eligible', false,
      'reason', 'Jailed accounts cannot apply for verification'
    );
  END IF;

  IF v_profile.has_recent_reports THEN
    RETURN json_build_object(
      'eligible', false,
      'reason', 'Accounts with recent reports cannot apply for verification'
    );
  END IF;

  IF v_profile.account_state IN ('banned', 'exiled') THEN
    RETURN json_build_object(
      'eligible', false,
      'reason', 'Banned or exiled accounts cannot apply for verification'
    );
  END IF;

  RETURN json_build_object('eligible', true);
END;
$$;

-- Function: claim_giveaway_reward
CREATE OR REPLACE FUNCTION claim_giveaway_reward(p_reward_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_reward RECORD;
    v_user_id UUID;
    v_new_balance INTEGER;
    v_discount_code TEXT;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    -- Get reward details
    SELECT * INTO v_reward
    FROM user_rewards
    WHERE id = p_reward_id AND user_id = v_user_id;

    IF v_reward IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Reward not found');
    END IF;

    IF v_reward.is_claimed THEN
        RETURN jsonb_build_object('success', false, 'error', 'Reward already claimed');
    END IF;

    -- Process based on reward type
    IF v_reward.reward_type = 'troll_coins' THEN
        -- Add coins to user profile
        UPDATE user_profiles
        SET troll_coins = COALESCE(troll_coins, 0) + v_reward.reward_amount
        WHERE id = v_user_id;

        -- Log transaction
        INSERT INTO trollz_transactions (user_id, amount, type, description, metadata)
        VALUES (
            v_user_id, 
            v_reward.reward_amount, 
            'giveaway_win', 
            'Won Troll Coins from giveaway',
            jsonb_build_object('reward_id', p_reward_id, 'giveaway_id', v_reward.giveaway_id)
        );

    ELSIF v_reward.reward_type = 'vip_badge' THEN
        -- Update VIP status
        UPDATE user_profiles
        SET 
            vip_tier = v_reward.vip_tier,
            vip_expires_at = CASE 
                WHEN vip_expires_at IS NULL OR vip_expires_at < NOW() THEN NOW() + (v_reward.vip_duration_days || ' days')::INTERVAL
                ELSE vip_expires_at + (v_reward.vip_duration_days || ' days')::INTERVAL
            END
        WHERE id = v_user_id;

    ELSIF v_reward.reward_type = 'gift_pack' THEN
        -- Create discount code for user
        v_discount_code := 'GIFT' || upper(substring(md5(random()::text) from 1 for 8));
        
        INSERT INTO discount_codes (code, discount_percent, max_uses, valid_until, created_by)
        VALUES (
            v_discount_code,
            v_reward.gift_pack_discount,
            1,
            NOW() + INTERVAL '30 days',
            v_user_id
        );
    END IF;

    -- Mark reward as claimed
    UPDATE user_rewards
    SET is_claimed = true, claimed_at = NOW()
    WHERE id = p_reward_id;

    RETURN jsonb_build_object(
        'success', true,
        'reward_type', v_reward.reward_type,
        'reward_amount', v_reward.reward_amount,
        'discount_code', v_discount_code
    );
END;
$$;

-- Function: claim_troll_drop_bill
CREATE OR REPLACE FUNCTION public.claim_troll_drop_bill(
  p_troll_drop_id uuid,
  p_bill_index integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_drop record;
  v_user_id uuid;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_drop FROM public.troll_drops
  WHERE id = p_troll_drop_id AND status = 'active' AND ends_at > now();

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Drop not found or expired');
  END IF;

  -- FIX: Validate bill_index is within valid range
  IF p_bill_index < 1 OR p_bill_index > v_drop.total_bills THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid bill index');
  END IF;

  -- ATOMIC CLAIM: Insert first, unique constraint prevents duplicates
  BEGIN
    INSERT INTO public.troll_drop_claims (troll_drop_id, stream_id, user_id, bill_index, coin_value)
    VALUES (p_troll_drop_id, v_drop.stream_id, v_user_id, p_bill_index, v_drop.coin_value);
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bill already claimed');
  END;

  -- Credit user
  UPDATE public.user_profiles
  SET troll_coins = COALESCE(troll_coins, 0) + v_drop.coin_value,
      total_earned_coins = COALESCE(total_earned_coins, 0) + v_drop.coin_value,
      updated_at = now()
  WHERE id = v_user_id;

  -- Log to coin_ledger if table exists (best-effort)
  BEGIN
    INSERT INTO public.coin_ledger (user_id, counterparty_id, type, direction, coins, amount_usd, meta, created_at)
    VALUES (v_user_id, v_drop.created_by, 'troll_drop', 'credit', v_drop.coin_value, 0,
            jsonb_build_object('drop_id', p_troll_drop_id, 'bill_index', p_bill_index), now());
  EXCEPTION WHEN undefined_table THEN
    NULL; -- coin_ledger not available, skip
  END;

  RETURN jsonb_build_object(
    'success', true,
    'coins_earned', v_drop.coin_value,
    'message', 'Claimed ' || v_drop.coin_value || ' coins!'
  );
END;
$$;

-- Function: claim_user_league_mission
CREATE OR REPLACE FUNCTION public.claim_user_league_mission(
    p_user_id UUID,
    p_mission_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_mission public.user_league_missions%ROWTYPE;
BEGIN
  SELECT * INTO v_mission
  FROM public.user_league_missions
  WHERE id = p_mission_id
    AND user_id = p_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Mission not found');
  END IF;

  IF v_mission.status = 'claimed' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Mission already claimed');
  END IF;

  IF v_mission.status <> 'completed' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Mission must be completed before claiming');
  END IF;

  UPDATE public.user_league_missions
  SET status = 'claimed',
      claimed_at = now(),
      updated_at = now()
  WHERE id = p_mission_id;

  PERFORM public.award_league_points(
      p_user_id,
      'mission_claimed',
      v_mission.reward_points,
      NULL,
      jsonb_build_object('mission_id', p_mission_id, 'mission_key', v_mission.mission_key)
  );

  IF v_mission.reward_xp > 0 AND EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'grant_xp') THEN
    PERFORM public.grant_xp(
      p_user_id,
      v_mission.reward_xp,
      'mission_claim',
      p_mission_id::text,
      jsonb_build_object('mission_key', v_mission.mission_key)
    );
  END IF;

  v_mission.reward_coins := LEAST(v_mission.reward_coins, 10);

  IF v_mission.reward_coins > 0 THEN
    BEGIN
      UPDATE public.user_profiles
      SET trollmonds = COALESCE(trollmonds, 0) + v_mission.reward_coins
      WHERE id = p_user_id;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Unable to award mission trollmonds: %', SQLERRM;
    END;
  END IF;

  RETURN jsonb_build_object(
      'success', true,
      'claimed', true,
      'reward_points', v_mission.reward_points,
      'reward_xp', v_mission.reward_xp,
      'reward_coins', v_mission.reward_coins
  );
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'claim_user_league_mission failed: %', SQLERRM;
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- Function: cleanup_expired_user_purchases
CREATE OR REPLACE FUNCTION public.cleanup_expired_user_purchases()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  cutoff_time timestamptz;
BEGIN
  -- Set cutoff time to 10 seconds ago
  cutoff_time := NOW() - INTERVAL '10 seconds';

  -- 1. Delete expired from user_inventory
  DELETE FROM public.user_inventory
  WHERE expires_at IS NOT NULL 
    AND expires_at < cutoff_time;

  -- 2. Delete expired from user_perks
  DELETE FROM public.user_perks
  WHERE expires_at IS NOT NULL 
    AND expires_at < cutoff_time;

  -- 3. Delete expired from user_insurances
  DELETE FROM public.user_insurances
  WHERE expires_at IS NOT NULL 
    AND expires_at < cutoff_time;

  -- 4. Also clean up user_purchases if it exists
  IF EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'user_purchases') THEN
      DELETE FROM public.user_purchases
      WHERE expires_at IS NOT NULL 
        AND expires_at < cutoff_time;
  END IF;

  -- 5. Remove items from user_active_items if the user no longer owns a valid copy
  DELETE FROM public.user_active_items uai
  WHERE NOT EXISTS (
      SELECT 1 FROM public.user_inventory ui
      WHERE ui.user_id = uai.user_id 
      AND ui.item_id = uai.item_id
      AND (ui.expires_at IS NULL OR ui.expires_at > cutoff_time)
  );
  
END;
$$;

-- Function: confirm_delivery
CREATE OR REPLACE FUNCTION confirm_delivery(
    p_order_id UUID,
    p_user_id UUID
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_order RECORD;
    v_escrow RECORD;
BEGIN
    -- Get order
    SELECT * INTO v_order
    FROM public.shop_orders
    WHERE id = p_order_id AND buyer_id = p_user_id AND status = 'shipped';

    IF v_order IS NULL THEN
        RAISE EXCEPTION 'Order not found or not authorized';
    END IF;

    -- Update order status
    UPDATE public.shop_orders
    SET status = 'completed',
        delivered_at = NOW(),
        completed_at = NOW(),
        escrow_status = 'released',
        escrow_released_at = NOW(),
        updated_at = NOW()
    WHERE id = p_order_id;

    -- Release escrow
    UPDATE public.wallet_escrow
    SET status = 'released',
        released_at = NOW()
    WHERE order_id = p_order_id AND status = 'held';

    -- Move coins to seller available balance
    UPDATE public.profiles
    SET coins = coins + v_order.total_coins
    WHERE id = v_order.seller_id;

    -- Log transaction for seller
    INSERT INTO public.coin_transactions (user_id, coins, source, type, description)
    VALUES (
        v_order.seller_id,
        v_order.total_coins,
        'order_complete',
        'credit',
        v_order.order_number || ': Order completed - escrow released'
    );

    RETURN FOUND;
END;
$$;

-- Function: consume_gas
CREATE OR REPLACE FUNCTION public.consume_gas(p_amount NUMERIC DEFAULT 5.0)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_current_gas NUMERIC;
BEGIN
    v_user_id := auth.uid();
    
    UPDATE public.user_profiles
    SET gas_balance = GREATEST(gas_balance - p_amount, 0.0),
        last_gas_update = now()
    WHERE id = v_user_id
    RETURNING gas_balance INTO v_current_gas;
    
    RETURN jsonb_build_object('success', true, 'new_balance', v_current_gas);
END;
$$;

-- Function: create_battle_challenge
CREATE OR REPLACE FUNCTION public.create_battle_challenge(
  p_challenger_id UUID,
  p_opponent_id UUID
) RETURNS UUID AS $$
DECLARE
  v_battle_id UUID;
  v_challenger_kind TEXT;
  v_opponent_kind TEXT;
  v_battle_type TEXT := 'standard';
  v_challenger_user_id UUID;
  v_opponent_user_id UUID;
  v_challenger_stream RECORD;
  v_opponent_stream RECORD;
  v_tournament_battle_id UUID;
BEGIN
  -- Validate both streams exist and are live BEFORE creating battle
  SELECT * INTO v_challenger_stream
  FROM public.streams
  WHERE id = p_challenger_id
    AND status = 'live'
    AND is_live = TRUE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Challenger stream not found or not live: %', p_challenger_id;
  END IF;
  
  SELECT * INTO v_opponent_stream
  FROM public.streams
  WHERE id = p_opponent_id
    AND status = 'live'
    AND is_live = TRUE;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Opponent stream not found or not live: %', p_opponent_id;
  END IF;

  -- Get stream kinds and user IDs from validated streams
  v_challenger_kind := v_challenger_stream.stream_kind;
  v_challenger_user_id := v_challenger_stream.user_id;
  v_opponent_kind := v_opponent_stream.stream_kind;
  v_opponent_user_id := v_opponent_stream.user_id;

  IF COALESCE(v_challenger_kind, 'regular') = 'trollmers'
     AND COALESCE(v_opponent_kind, 'regular') = 'trollmers' THEN
    v_battle_type := 'trollmers';
  END IF;

  INSERT INTO public.battles (challenger_stream_id, opponent_stream_id, battle_type)
  VALUES (p_challenger_id, p_opponent_id, v_battle_type)
  RETURNING id INTO v_battle_id;

  -- Auto-link to tournament if both participants are in pending tournament match
  IF v_battle_type = 'trollmers' THEN
    SELECT tb.id INTO v_tournament_battle_id
    FROM public.trollmers_tournament_battles tb
    JOIN public.trollmers_monthly_tournaments t ON t.id = tb.tournament_id
    WHERE t.status = 'active'
      AND tb.status = 'pending'
      AND (
        (tb.participant1_id = v_challenger_user_id AND tb.participant2_id = v_opponent_user_id)
        OR
        (tb.participant1_id = v_opponent_user_id AND tb.participant2_id = v_challenger_user_id)
      )
    LIMIT 1;

    IF v_tournament_battle_id IS NOT NULL THEN
      UPDATE public.trollmers_tournament_battles
      SET battle_id = v_battle_id,
          status = 'active'
      WHERE id = v_tournament_battle_id;
    END IF;
  END IF;

  RETURN v_battle_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 7b. Helper: check if user meets Trollmers eligibility (100+ followers, camera ready)
CREATE OR REPLACE FUNCTION public.is_trollmers_eligible(
    p_user_id UUID
)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_followers_count INTEGER;
    v_user_role TEXT;
BEGIN
    -- Check if user is admin (bypass follower requirement)
    SELECT role INTO v_user_role
    FROM public.user_profiles
    WHERE id = p_user_id;

    IF v_user_role = 'admin' THEN
        RETURN TRUE;
    END IF;

    -- Check follower count for non-admins
    SELECT COUNT(*)
    INTO v_followers_count
    FROM public.user_follows
    WHERE following_id = p_user_id;

    RETURN v_followers_count >= 100;
END;
$$;

-- Function: create_court_case
CREATE OR REPLACE FUNCTION public.create_court_case(
    p_defendant_id UUID,
    p_reason TEXT,
    p_plaintiff_id UUID DEFAULT NULL,
    p_docket_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_docket_id UUID;
    v_case_id UUID;
    v_staff_id UUID;
BEGIN
    v_staff_id := COALESCE(p_plaintiff_id, auth.uid());
    
    -- Resolve docket
    IF p_docket_id IS NOT NULL THEN
        v_docket_id := p_docket_id;
    ELSE
        v_docket_id := public.get_or_create_next_docket(CURRENT_DATE);
    END IF;

    -- Create case
    INSERT INTO public.court_cases (
        docket_id,
        defendant_id,
        plaintiff_id,
        reason,
        status,
        warrant_active
    ) VALUES (
        v_docket_id,
        p_defendant_id,
        v_staff_id,
        p_reason,
        'pending',
        false
    )
    RETURNING id INTO v_case_id;

    -- Update docket status if full
    IF (
        SELECT COUNT(*) FROM public.court_cases 
        WHERE docket_id = v_docket_id
    ) >= (
        SELECT COALESCE(max_cases, 20) FROM public.court_dockets WHERE id = v_docket_id
    ) THEN
        UPDATE public.court_dockets SET status = 'full' WHERE id = v_docket_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'case_id', v_case_id,
        'docket_id', v_docket_id
    );
END;
$$;

-- Function: create_document
CREATE OR REPLACE FUNCTION public.create_document(
  p_title TEXT,
  p_content TEXT,
  p_submitter_id UUID,
  p_document_type_slug TEXT DEFAULT 'custom',
  p_priority TEXT DEFAULT 'normal',
  p_tags TEXT[] DEFAULT '{}',
  p_metadata JSONB DEFAULT '{}',
  p_assigned_to UUID DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_document_id UUID;
  v_type_id UUID;
  v_username TEXT;
  v_checksum TEXT;
BEGIN
  -- Get document type
  SELECT id INTO v_type_id FROM public.document_types WHERE slug = p_document_type_slug AND is_active = true;
  IF v_type_id IS NULL THEN
    SELECT id INTO v_type_id FROM public.document_types WHERE slug = 'custom';
  END IF;

  -- Get username
  SELECT username INTO v_username FROM public.user_profiles WHERE id = p_submitter_id;

  -- Compute checksum
  v_checksum := public.compute_document_checksum(p_content, p_title, p_submitter_id);

  -- Create document
  INSERT INTO public.documents (
    document_type_id, document_type_slug, title, content,
    status, priority, submitted_by, tags, metadata,
    assigned_to, checksum, version
  ) VALUES (
    v_type_id, p_document_type_slug, p_title, p_content,
    'draft', p_priority, p_submitter_id, p_tags, p_metadata,
    p_assigned_to, v_checksum, 1
  ) RETURNING id INTO v_document_id;

  -- Create initial version
  INSERT INTO public.document_versions (document_id, version, content, title, changed_by, change_summary, checksum)
  VALUES (v_document_id, 1, p_content, p_title, p_submitter_id, 'Initial version', v_checksum);

  -- Log
  PERFORM public.log_document_event(
    v_document_id, p_submitter_id, COALESCE(v_username, 'Unknown'),
    (SELECT role FROM public.user_profiles WHERE id = p_submitter_id),
    'document_created',
    jsonb_build_object('title', p_title, 'type', p_document_type_slug)
  );

  RETURN json_build_object('success', true, 'document_id', v_document_id);
END;
$$;

-- Function: create_event
CREATE OR REPLACE FUNCTION public.create_event(
  p_title TEXT,
  p_description TEXT,
  p_category_slug TEXT,
  p_event_date DATE,
  p_creator_id UUID,
  p_creator_username TEXT,
  p_start_time TIMESTAMP WITH TIME ZONE DEFAULT NULL,
  p_end_time TIMESTAMP WITH TIME ZONE DEFAULT NULL,
  p_timezone TEXT DEFAULT 'UTC',
  p_banner_image_url TEXT DEFAULT NULL,
  p_thumbnail_url TEXT DEFAULT NULL,
  p_event_color TEXT DEFAULT '#8B5CF6',
  p_max_participants INTEGER DEFAULT NULL,
  p_visibility TEXT DEFAULT 'public',
  p_access_level TEXT DEFAULT 'everyone',
  p_min_level INTEGER DEFAULT 1,
  p_requirements TEXT[] DEFAULT '{}',
  p_rules TEXT DEFAULT NULL,
  p_location_type TEXT DEFAULT 'virtual',
  p_location_details TEXT DEFAULT NULL,
  p_tags TEXT[] DEFAULT '{}',
  p_metadata JSONB DEFAULT '{}'
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_event_id UUID;
  v_category_id UUID;
BEGIN
  SELECT id INTO v_category_id FROM public.event_categories WHERE slug = p_category_slug AND is_active = true;
  IF v_category_id IS NULL THEN
    SELECT id INTO v_category_id FROM public.event_categories WHERE slug = 'custom_event';
  END IF;

  INSERT INTO public.events (
    title, description, category_id, category_slug,
    event_date, start_time, end_time, timezone,
    banner_image_url, thumbnail_url, event_color,
    creator_id, creator_username,
    max_participants, visibility, access_level, min_level,
    requirements, rules, location_type, location_details,
    tags, metadata
  ) VALUES (
    p_title, p_description, v_category_id, p_category_slug,
    p_event_date, p_start_time, p_end_time, p_timezone,
    p_banner_image_url, p_thumbnail_url, p_event_color,
    p_creator_id, p_creator_username,
    p_max_participants, p_visibility, p_access_level, p_min_level,
    p_requirements, p_rules, p_location_type, p_location_details,
    p_tags, p_metadata
  ) RETURNING id INTO v_event_id;

  RETURN json_build_object('success', true, 'event_id', v_event_id);
END;
$$;

