-- Function: create_game_match
CREATE OR REPLACE FUNCTION public.create_game_match(
    p_game_type TEXT,
    p_player_ids UUID[]
) RETURNS UUID AS $$
DECLARE
    v_match_id UUID;
    v_game_state JSONB;
    v_player_states JSONB[] = '{}';
    v_player_id UUID;
    v_username TEXT;
    v_initial_game_state JSONB;
BEGIN
    -- Basic validation for game type
    IF p_game_type NOT IN (
        'reaction-speed', 
        'two-truths-lie', 
        'fame-shame-wheel', 
        'troll-identity-hunt', 
        'multiplayer-solitaire', 
        'multiplayer-dominoes'
    ) THEN
        RAISE EXCEPTION 'Unsupported game type: %s', p_game_type;
    END IF;

    -- Ensure only one player ID is passed for now, as multiplayer logic is not fully developed in RPC
    IF array_length(p_player_ids, 1) IS NULL OR array_length(p_player_ids, 1) != 1 THEN
        RAISE EXCEPTION 'create_game_match currently only supports one player at creation.';
    END IF;

    -- Fetch username for the initial player
    SELECT username INTO v_username FROM public.user_profiles WHERE id = p_player_ids[1];
    IF v_username IS NULL THEN
        RAISE EXCEPTION 'Player with ID %s not found.', p_player_ids[1];
    END IF;

    -- Initialize game_state based on game_type
    -- For 'reaction-speed', the initial state is defined here.
    IF p_game_type = 'reaction-speed' THEN
        v_initial_game_state := jsonb_build_object(
            'matchId', NULL, -- Will be set after INSERT
            'gameType', p_game_type,
            'players', jsonb_build_array(jsonb_build_object(
                'id', p_player_ids[1],
                'username', v_username,
                'score', 0,
                'isHost', TRUE,
                'reactionTime', NULL,
                'hasReacted', FALSE
            )),
            'status', 'pending',
            'phase', 'countdown',
            'timerRemaining', 3, -- Initial countdown for reaction speed
            'triggerTimestamp', NULL,
            'countdownStartTime', NULL
        );
    ELSE
        -- Generic initial state for other games
        v_initial_game_state := jsonb_build_object(
            'matchId', NULL,
            'gameType', p_game_type,
            'players', jsonb_build_array(jsonb_build_object(
                'id', p_player_ids[1],
                'username', v_username,
                'score', 0,
                'isHost', TRUE
            )),
            'status', 'pending'
        );
    END IF;

    -- Insert new match into troll_battles
    INSERT INTO public.troll_battles (host_id, game_type, status, game_state)
    VALUES (p_player_ids[1], p_game_type, 'pending', v_initial_game_state)
    RETURNING id INTO v_match_id;

    -- Update the game_state with the actual matchId
    UPDATE public.troll_battles
    SET
        game_state = jsonb_set(game_state, '{matchId}', to_jsonb(v_match_id))
    WHERE id = v_match_id;

    RETURN v_match_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.create_game_match(TEXT, UUID[]) TO authenticated, service_role;

CREATE TABLE IF NOT EXISTS global_events (
  id BIGSERIAL PRIMARY KEY,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  title TEXT NOT NULL,
  icon TEXT,
  priority INTEGER DEFAULT 1
);

ALTER TABLE global_events ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Global events are viewable by everyone" ON global_events
  FOR SELECT
  USING (true);

CREATE OR REPLACE FUNCTION public.join_game_match(
    p_match_id UUID,
    p_user_id UUID,
    p_username TEXT
) RETURNS JSONB AS $$
DECLARE
    v_match_record public.troll_battles;
    v_game_state JSONB;
    v_player_exists BOOLEAN;
    v_current_players JSONB[];
    v_num_players INTEGER;
    v_min_players INTEGER;
    v_updated_game_state JSONB;
    v_player_state JSONB;
BEGIN
    -- Fetch the current match record and lock it for update
    SELECT * INTO v_match_record FROM public.troll_battles WHERE id = p_match_id FOR UPDATE;

    IF v_match_record IS NULL THEN
        RAISE EXCEPTION 'Match not found.';
    END IF;

    v_game_state := v_match_record.game_state;

    -- Check if player already in game_state
    v_player_exists := EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_game_state->'players') AS player
        WHERE (player->>'id')::UUID = p_user_id
    );

    IF v_player_exists THEN
        RETURN jsonb_build_object('success', TRUE, 'message', 'Player already in match.');
    END IF;

    -- Add player to game_state.players array
    v_player_state := jsonb_build_object(
        'id', p_user_id,
        'username', p_username,
        'score', 0,
        'isHost', FALSE, -- Newly joined player is not the initial host
        'reactionTime', NULL, -- Specific to reaction-speed
        'hasReacted', FALSE  -- Specific to reaction-speed
    );

    v_updated_game_state := jsonb_set(v_game_state, '{players, -1}', v_player_state, TRUE);

    -- Determine min players based on game type (e.g., Reaction Speed needs 2)
    IF v_match_record.game_type = 'reaction-speed' THEN
        v_min_players := 2; 
    ELSE
        -- Default or other game types
        v_min_players := 2;
    END IF;

    -- Check if match can start (e.g., 2 players for Reaction Speed)
    v_current_players := jsonb_array_elements(v_updated_game_state->'players');
    SELECT COUNT(*) INTO v_num_players FROM jsonb_array_elements(v_updated_game_state->'players');

    IF v_num_players >= v_min_players AND v_updated_game_state->>'status' = 'waiting' THEN
        v_updated_game_state := jsonb_set(v_updated_game_state, '{status}', '"ready"'::jsonb);
        -- For reaction-speed, start countdown immediately if enough players
        IF v_match_record.game_type = 'reaction-speed' THEN
            v_updated_game_state := jsonb_set(v_updated_game_state, '{phase}', '"countdown"'::jsonb);
            v_updated_game_state := jsonb_set(v_updated_game_state, '{countdownStartTime}', to_jsonb(EXTRACT(EPOCH FROM NOW()) * 1000)); -- Current server time in ms
            v_updated_game_state := jsonb_set(v_updated_game_state, '{timerRemaining}', '3'::jsonb); -- 3 second countdown
        END IF;
    END IF;

    -- Update the troll_battles record with the new game_state
    UPDATE public.troll_battles
    SET
        game_state = v_updated_game_state,
        -- Also update player2_id for convenience if it's the second player joining
        player2_id = CASE WHEN v_match_record.player2_id IS NULL AND v_num_players = 2 THEN p_user_id ELSE v_match_record.player2_id END,
        status = (v_updated_game_state->>'status')::TEXT
    WHERE id = p_match_id;

    RETURN jsonb_build_object('success', TRUE);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.join_game_match(UUID, UUID, TEXT) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.process_game_action(
    p_match_id UUID,
    p_user_id UUID,
    p_action_type TEXT,
    p_payload JSONB DEFAULT '{}'::jsonb
) RETURNS JSONB AS $$
DECLARE
    v_match_record public.troll_battles;
    v_game_state JSONB;
    v_player_found BOOLEAN := FALSE;
    v_current_timestamp BIGINT := (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT;
    v_updated_game_state JSONB;
    v_winner_id UUID;
BEGIN
    -- Fetch the current match record and lock it for update
    SELECT * INTO v_match_record FROM public.troll_battles WHERE id = p_match_id FOR UPDATE;

    IF v_match_record IS NULL THEN
        RAISE EXCEPTION 'Match not found.';
    END IF;

    v_game_state := v_match_record.game_state;

    -- Validate player is part of the match
    IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_game_state->'players') AS player
        WHERE (player->>'id')::UUID = p_user_id
    ) THEN
        RAISE EXCEPTION 'Player %s is not part of match %s.', p_user_id, p_match_id;
    END IF;

    -- General match status validation
    IF v_game_state->>'status' != 'active' AND v_game_state->>'status' != 'ready' THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Match is not active or ready.');
    END IF;

    -- Apply game-specific action logic
    IF v_match_record.game_type = 'reaction-speed' THEN
        IF p_action_type = 'react_to_trigger' THEN
            -- Validate game phase
            IF v_game_state->>'phase' != 'waiting_for_reaction' THEN
                RETURN jsonb_build_object('success', FALSE, 'message', 'Not in reaction phase.');
            END IF;

            -- Validate if player has already reacted
            IF EXISTS (
                SELECT 1 FROM jsonb_array_elements(v_game_state->'players') AS player
                WHERE (player->>'id')::UUID = p_user_id AND (player->>'hasReacted')::BOOLEAN = TRUE
            ) THEN
                RETURN jsonb_build_object('success', FALSE, 'message', 'Player already reacted.');
            END IF;

            -- Record reaction
            v_updated_game_state := jsonb_set(
                v_game_state,
                ARRAY['players', (SELECT idx::text FROM jsonb_array_elements(v_game_state->'players') WITH ORDINALITY arr(player, idx) WHERE (player->>'id')::UUID = p_user_id)-1::text, 'reactionTime'],
                to_jsonb(v_current_timestamp - (v_game_state->>'triggerTimestamp')::BIGINT)
            );
            v_updated_game_state := jsonb_set(
                v_updated_game_state,
                ARRAY['players', (SELECT idx::text FROM jsonb_array_elements(v_game_state->'players') WITH ORDINALITY arr(player, idx) WHERE (player->>'id')::UUID = p_user_id)-1::text, 'hasReacted'],
                'true'::jsonb
            );

            -- Check if all active players have reacted or if reaction window has passed (handled by timer)
            -- For now, we only update the player's reaction.
            -- The game state will be advanced by a timer-based function or when all players react.

        ELSIF p_action_type = 'update_timer_and_state' THEN
            -- This action is expected to be called by a trusted source (e.g., MatchController on client or a server function)
            -- It updates the game state based on elapsed time and phase transitions
            -- This simulates the GameEngine.updateState function in the DB
            
            -- Re-evaluate game state based on current time
            IF v_game_state->>'phase' = 'countdown' AND (v_game_state->>'countdownStartTime')::BIGINT + 3000 <= v_current_timestamp THEN
                -- Countdown finished, transition to waiting_for_reaction
                v_updated_game_state := jsonb_set(v_game_state, '{phase}', '"waiting_for_reaction"'::jsonb);
                v_updated_game_state := jsonb_set(v_updated_game_state, '{triggerTimestamp}', to_jsonb(v_current_timestamp + (FLOOR(RANDOM() * (5000 - 2000 + 1)) + 2000)::BIGINT)); -- Random trigger between 2-5 seconds
                v_updated_game_state := jsonb_set(v_updated_game_state, '{timerRemaining}', '5'::jsonb); -- Max 5 seconds until trigger

            ELSIF v_game_state->>'phase' = 'waiting_for_reaction' AND (v_game_state->>'triggerTimestamp')::BIGINT + 1000 <= v_current_timestamp THEN
                -- Reaction window ended, determine winner
                v_updated_game_state := v_game_state; -- Start with current state

                -- Determine fastest reaction
                DECLARE
                    fastest_time BIGINT := NULL;
                    current_player_reaction_time BIGINT;
                    p_id UUID;
                BEGIN
                    FOR p_id IN SELECT (player->>'id')::UUID FROM jsonb_array_elements(v_game_state->'players') AS player
                    LOOP
                        current_player_reaction_time := (SELECT (player->>'reactionTime')::BIGINT FROM jsonb_array_elements(v_game_state->'players') AS player WHERE (player->>'id')::UUID = p_id);
                        IF current_player_reaction_time IS NOT NULL THEN
                            IF fastest_time IS NULL OR current_player_reaction_time < fastest_time THEN
                                fastest_time := current_player_reaction_time;
                                v_winner_id := p_id;
                            END IF;
                        END IF;
                    END LOOP;
                END;

                -- Set winner and update status
                IF v_winner_id IS NOT NULL THEN
                    v_updated_game_state := jsonb_set(v_updated_game_state, '{winnerId}', to_jsonb(v_winner_id));
                    v_updated_game_state := jsonb_set(v_updated_game_state, '{status}', '"finished"'::jsonb);
                    v_updated_game_state := jsonb_set(v_updated_game_state, '{phase}', '"finished"'::jsonb);
                    v_updated_game_state := jsonb_set(v_updated_game_state, '{timerRemaining}', '0'::jsonb);
                ELSE
                    -- No winner (e.g., no one reacted), can be a draw or no reward
                    v_updated_game_state := jsonb_set(v_updated_game_state, '{status}', '"finished"'::jsonb);
                    v_updated_game_state := jsonb_set(v_updated_game_state, '{phase}', '"finished"'::jsonb);
                    v_updated_game_state := jsonb_set(v_updated_game_state, '{timerRemaining}', '0'::jsonb);
                END IF;

            ELSE
                -- No state change based on timer, just update timer remaining for countdown
                IF v_game_state->>'phase' = 'countdown' THEN
                    v_updated_game_state := jsonb_set(v_game_state, '{timerRemaining}', to_jsonb(GREATEST(0, CEIL(((v_game_state->>'countdownStartTime')::BIGINT + 3000 - v_current_timestamp) / 1000.0))));
                ELSIF v_game_state->>'phase' = 'waiting_for_reaction' AND (v_game_state->>'triggerTimestamp')::BIGINT IS NOT NULL THEN
                    IF v_current_timestamp < (v_game_state->>'triggerTimestamp')::BIGINT THEN
                         -- Time until trigger
                        v_updated_game_state := jsonb_set(v_game_state, '{timerRemaining}', to_jsonb(GREATEST(0, CEIL(((v_game_state->>'triggerTimestamp')::BIGINT - v_current_timestamp) / 1000.0))));
                    ELSE
                         -- Time within reaction window
                        v_updated_game_state := jsonb_set(v_game_state, '{timerRemaining}', to_jsonb(GREATEST(0, CEIL(((v_game_state->>'triggerTimestamp')::BIGINT + 1000 - v_current_timestamp) / 1000.0))));
                    END IF;
                END IF;
            END IF;
        ELSE
            RAISE EXCEPTION 'Unsupported action type for reaction-speed: %s', p_action_type;
        END IF;
    ELSE
        RAISE EXCEPTION 'Unsupported game type: %s', v_match_record.game_type;
    END IF;

    -- Update the troll_battles record with the new game_state
    UPDATE public.troll_battles
    SET
        game_state = COALESCE(v_updated_game_state, v_game_state),
        status = COALESCE(v_updated_game_state->>'status', v_game_state->>'status')::TEXT,
        winner_id = COALESCE((v_updated_game_state->>'winnerId')::UUID, v_match_record.winner_id)
    WHERE id = p_match_id;

    -- If winner determined, call set_match_winner RPC (already exists and handles awarding coins)
    IF (v_updated_game_state->>'winnerId')::UUID IS NOT NULL AND v_match_record.winner_id IS NULL THEN
        PERFORM public.set_match_winner(p_match_id, (v_updated_game_state->>'winnerId')::UUID);
    END IF;

    RETURN jsonb_build_object('success', TRUE, 'game_state', COALESCE(v_updated_game_state, v_game_state));
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.process_game_action(UUID, UUID, TEXT, JSONB) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.get_waiting_matches()
RETURNS TABLE (
    match_id UUID,
    game_type TEXT,
    player1_username TEXT
) LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    RETURN QUERY
    SELECT
        tb.id AS match_id,
        tb.game_type,
        p.username AS player1_username
    FROM
        public.troll_battles AS tb
    JOIN
        public.user_profiles AS p ON tb.host_id = p.id
    WHERE
        tb.status = 'pending' AND tb.challenger_id IS NULL;
END;
$$;

-- Function: create_marketplace_appeal
CREATE OR REPLACE FUNCTION create_marketplace_appeal(
  p_order_id uuid,
  p_user_id uuid,
  p_category text,
  p_description text,
  p_desired_resolution text DEFAULT null
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_order marketplace_purchases%ROWTYPE;
  v_appeal_id uuid;
  v_appeal_category appeal_category;
BEGIN
  -- Get the order
  SELECT * INTO v_order FROM marketplace_purchases WHERE id = p_order_id;
  
  IF v_order IS NULL THEN
    RAISE EXCEPTION 'Order not found';
  END IF;
  
  -- Map category to appeal_category type
  v_appeal_category := CASE p_category
    WHEN 'non_delivery' THEN 'non_delivery'::appeal_category
    WHEN 'not_as_described' THEN 'not_as_described'::appeal_category
    WHEN 'damaged_item' THEN 'damaged_item'::appeal_category
    WHEN 'seller_issue' THEN 'seller_issue'::appeal_category
    WHEN 'buyer_issue' THEN 'buyer_issue'::appeal_category
    WHEN 'payment_issue' THEN 'payment_issue'::appeal_category
    ELSE 'other'::appeal_category
  END;
  
  -- Create appeal in transaction_appeals table
  INSERT INTO transaction_appeals (
    user_id,
    order_id,
    category,
    description,
    desired_resolution,
    related_user_id,
    amount_in_dispute,
    escrow_release_status
  )
  VALUES (
    p_user_id,
    p_order_id,
    v_appeal_category,
    p_description,
    p_desired_resolution,
    v_order.seller_id,
    v_order.price_paid,
    'held'
  )
  RETURNING id INTO v_appeal_id;
  
  -- Update order with appeal link and hold payout if needed
  PERFORM hold_marketplace_payout_for_appeal(p_order_id, v_appeal_id);
  
  RETURN v_appeal_id;
END;
$$;

-- Function: create_marketplace_listing
CREATE OR REPLACE FUNCTION create_marketplace_listing(
    p_title TEXT,
    p_description TEXT,
    p_price_coins INTEGER,
    p_price_usd NUMERIC,
    p_category TEXT,
    p_condition TEXT,
    p_delivery_type TEXT,
    p_latitude DOUBLE PRECISION,
    p_longitude DOUBLE PRECISION,
    p_city TEXT,
    p_state TEXT,
    p_images JSONB,
    p_stock INTEGER
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_listing_id UUID;
    v_seller_id UUID;
    v_flag_reason TEXT;
BEGIN
    -- Get seller ID from auth
    SELECT auth.uid() INTO v_seller_id;
    
    IF v_seller_id IS NULL THEN
        RAISE EXCEPTION 'User must be authenticated';
    END IF;

    -- Check for prohibited keywords
    v_flag_reason := NULL;
    IF LOWER(p_title) ~ '(gun|weapon|ammo|drug|cocaine|weed|pills|fentanyl|explosive|illegal)' THEN
        v_flag_reason := 'Prohibited keyword in title';
    ELSIF LOWER(p_description) ~ '(gun|weapon|ammo|drug|cocaine|weed|pills|fentanyl|explosive|illegal)' THEN
        v_flag_reason := 'Prohibited keyword in description';
    END IF;

    -- Insert listing
    INSERT INTO public.marketplace_items (
        seller_id, title, description, price_coins, price_usd, 
        category, condition, delivery_type, latitude, longitude, 
        city, state, images, stock, status
    ) VALUES (
        v_seller_id, p_title, p_description, p_price_coins, p_price_usd,
        p_category, p_condition, p_delivery_type, p_latitude, p_longitude,
        p_city, p_state, p_images, p_stock, 
        CASE WHEN v_flag_reason IS NOT NULL THEN 'flagged' ELSE 'active' END
    )
    RETURNING id INTO v_listing_id;

    -- Create flag if prohibited content detected
    IF v_flag_reason IS NOT NULL THEN
        INSERT INTO public.listing_flags (listing_id, listing_type, reason, reported_by, status)
        VALUES (v_listing_id, 'marketplace', v_flag_reason, v_seller_id, 'pending');
    END IF;

    RETURN v_listing_id;
END;
$$;

-- Function: create_marketplace_payout_hold
CREATE OR REPLACE FUNCTION create_marketplace_payout_hold(
  p_order_id uuid,
  p_amount bigint
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_hold_id uuid;
BEGIN
  -- Check if hold already exists
  SELECT id INTO v_hold_id FROM marketplace_payout_holds 
  WHERE order_id = p_order_id AND status = 'active';
  
  IF v_hold_id IS NOT NULL THEN
    RETURN v_hold_id; -- Already exists
  END IF;
  
  -- Create new hold
  INSERT INTO marketplace_payout_holds (order_id, amount, status, hold_reason)
  VALUES (p_order_id, p_amount, 'active', 'awaiting_delivery')
  RETURNING id INTO v_hold_id;
  
  -- Update order payout status
  UPDATE marketplace_purchases 
  SET payout_status = 'held', payout_held_at = now()
  WHERE id = p_order_id;
  
  RETURN v_hold_id;
END;
$$;

-- Function: create_marketplace_review
CREATE OR REPLACE FUNCTION public.create_marketplace_review(
    p_order_id UUID,
    p_seller_id UUID,
    p_buyer_id UUID,
    p_listing_id UUID,
    p_listing_type TEXT,
    p_rating INTEGER,
    p_comment TEXT DEFAULT NULL,
    p_images JSONB DEFAULT '[]',
    p_delivery_rating INTEGER DEFAULT NULL,
    p_item_as_described BOOLEAN DEFAULT true,
    p_would_recommend BOOLEAN DEFAULT true
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_review_id UUID;
    v_existing_review RECORD;
    v_seller_avg_rating NUMERIC(3,2);
    v_seller_total_reviews INTEGER;
BEGIN
    -- Check if review already exists for this order/seller
    SELECT * INTO v_existing_review
    FROM public.marketplace_reviews
    WHERE order_id = p_order_id AND seller_id = p_seller_id;
    
    IF FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Review already exists for this order');
    END IF;
    
    -- Create the review
    INSERT INTO public.marketplace_reviews (
        order_id, seller_id, buyer_id, listing_id, listing_type,
        rating, comment, images, delivery_rating, item_as_described, would_recommend
    )
    VALUES (
        p_order_id, p_seller_id, p_buyer_id, p_listing_id, p_listing_type,
        p_rating, p_comment, p_images, p_delivery_rating, p_item_as_described, p_would_recommend
    )
    RETURNING id INTO v_review_id;
    
    -- Update seller review counts
    UPDATE public.user_profiles
    SET positive_reviews = COALESCE(positive_reviews, 0) + 
        CASE WHEN p_rating >= 4 THEN 1 ELSE 0 END,
        negative_reviews = COALESCE(negative_reviews, 0) + 
        CASE WHEN p_rating <= 2 THEN 1 ELSE 0 END,
        total_positive_reviews = COALESCE(total_positive_reviews, 0) + 
        CASE WHEN p_rating >= 4 THEN 1 ELSE 0 END,
        total_negative_reviews = COALESCE(total_negative_reviews, 0) + 
        CASE WHEN p_rating <= 2 THEN 1 ELSE 0 END
    WHERE id = p_seller_id;
    
    -- Calculate new average rating
    SELECT AVG(rating)::NUMERIC(3,2), COUNT(*)
    INTO v_seller_avg_rating, v_seller_total_reviews
    FROM public.marketplace_reviews
    WHERE seller_id = p_seller_id;
    
    -- Update seller's average rating on their profile
    UPDATE public.user_profiles
    SET rating = v_seller_avg_rating,
        total_reviews = v_seller_total_reviews
    WHERE id = p_seller_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'review_id', v_review_id,
        'seller_avg_rating', v_seller_avg_rating,
        'seller_total_reviews', v_seller_total_reviews
    );
END;
$$;

-- Function: create_notification
CREATE OR REPLACE FUNCTION public.create_notification(
  p_user_id UUID,
  p_type TEXT,
  p_title TEXT,
  p_message TEXT,
  p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id UUID;
BEGIN
  -- Validate inputs if necessary
  IF p_message IS NULL OR p_message = '' THEN
    RAISE EXCEPTION 'Message cannot be empty';
  END IF;

  INSERT INTO notifications (
    user_id,
    type,
    title,
    message,
    metadata,
    is_read,
    created_at
  ) VALUES (
    p_user_id,
    p_type,
    p_title,
    p_message,
    p_metadata,
    false,
    now()
  )
  RETURNING id INTO v_id;
  
  RETURN v_id;
END;
$$;

-- Function: create_order_with_escrow
CREATE OR REPLACE FUNCTION create_order_with_escrow(
    p_buyer_id UUID,
    p_product_id UUID,
    p_quantity INTEGER DEFAULT 1,
    p_shipping_name TEXT,
    p_shipping_address TEXT,
    p_shipping_city TEXT,
    p_shipping_state TEXT,
    p_shipping_zip TEXT
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_order_id UUID;
    v_order_number TEXT;
    v_product RECORD;
    v_shop RECORD;
    v_total_coins INTEGER;
    v_buyer_balance INTEGER;
    v_escrow_id UUID;
BEGIN
    -- Get product and shop info
    SELECT si.*, ts.id as shop_id, ts.owner_id as seller_id
    INTO v_product
    FROM public.shop_items si
    JOIN public.Mai Troll_shops ts ON ts.id = si.shop_id
    WHERE si.id = p_product_id;

    IF v_product IS NULL THEN
        RAISE EXCEPTION 'Product not found';
    END IF;

    -- Check stock
    IF v_product.stock_quantity IS NOT NULL AND v_product.stock_quantity < p_quantity THEN
        RAISE EXCEPTION 'Insufficient stock';
    END IF;

    -- Get buyer balance
    SELECT COALESCE(coins, 0) INTO v_buyer_balance
    FROM public.profiles
    WHERE id = p_buyer_id;

    -- Calculate total
    v_total_coins := v_product.price * p_quantity;

    -- Check balance
    IF v_buyer_balance < v_total_coins THEN
        RAISE EXCEPTION 'Insufficient coins';
    END IF;

    -- Generate order number
    v_order_number := 'ORD-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LEFT(gen_random_uuid()::TEXT, 8);

    -- Deduct coins from buyer
    UPDATE public.profiles
    SET coins = coins - v_total_coins
    WHERE id = p_buyer_id;

    -- Create order
    INSERT INTO public.shop_orders (
        order_number, buyer_id, seller_id, shop_id,
        status, subtotal, total_coins, escrow_status,
        shipping_name, shipping_address, shipping_city,
        shipping_state, shipping_zip, paid_at
    ) VALUES (
        v_order_number, p_buyer_id, v_product.seller_id, v_product.shop_id,
        'paid', v_product.price * p_quantity, v_total_coins, 'held',
        p_shipping_name, p_shipping_address, p_shipping_city,
        p_shipping_state, p_shipping_zip, NOW()
    )
    RETURNING id INTO v_order_id;

    -- Create order item
    INSERT INTO public.order_items (order_id, product_id, quantity, unit_price, total_price)
    VALUES (v_order_id, p_product_id, p_quantity, v_product.price, v_total_coins);

    -- Reduce stock
    IF v_product.stock_quantity IS NOT NULL THEN
        UPDATE public.shop_items
        SET stock_quantity = stock_quantity - p_quantity
        WHERE id = p_product_id;
    END IF;

    -- Create escrow entry
    INSERT INTO public.wallet_escrow (user_id, order_id, amount, status)
    VALUES (v_product.seller_id, v_order_id, v_total_coins, 'held')
    RETURNING id INTO v_escrow_id;

    -- Log transaction
    INSERT INTO public.coin_transactions (user_id, coins, source, type, description)
    VALUES (
        p_buyer_id, 
        -v_total_coins, 
        'order_purchase', 
        'debit',
        v_order_number || ': Purchase ' || v_product.name || ' x' || p_quantity
    );

    -- Seller notification transaction
    INSERT INTO public.coin_transactions (user_id, coins, source, type, description)
    VALUES (
        v_product.seller_id, 
        v_total_coins, 
        'order_escrow', 
        'escrow_hold',
        v_order_number || ': Escrow hold for ' || v_product.name
    );

    RETURN v_order_id;
END;
$$;

-- Function: create_president_election
create or replace function create_president_election()
returns uuid
security definer
language plpgsql
as $$
declare
  new_id uuid;
begin
  -- Check permission (Admin/Secretary)
  if not exists (select 1 from user_profiles where id = auth.uid() and (is_admin = true or role = 'secretary')) then
     raise exception 'Not authorized';
  end if;

  -- Check existing open election
  if exists (select 1 from president_elections where status in ('open', 'draft') and ends_at > now()) then
     raise exception 'Election already in progress';
  end if;

  insert into president_elections (status, starts_at, ends_at, created_by)
  values ('open', now(), now() + interval '3 weeks', auth.uid())
  returning id into new_id;

  return new_id;
end;
$$;

-- Function: create_president_proposal
create or replace function create_president_proposal(
  p_title text,
  p_description text,
  p_type text
)
returns uuid
security definer
language plpgsql
as $$
declare
  v_id uuid;
begin
  -- Check Role
  if not exists (
    select 1 from user_role_grants urg
    join system_roles sr on urg.role_id = sr.id
    where urg.user_id = auth.uid()
    and sr.name in ('president', 'vice_president')
    and (urg.expires_at is null or urg.expires_at > now())
  ) then
    raise exception 'Not authorized';
  end if;

  insert into president_proposals (title, description, type, created_by)
  values (p_title, p_description, p_type, auth.uid())
  returning id into v_id;

  -- Log
  perform log_president_action('create_proposal', jsonb_build_object('title', p_title, 'type', p_type), v_id);

  return v_id;
end;
$$;

-- Function: create_subscription
CREATE OR REPLACE FUNCTION create_subscription(
    p_broadcaster_id UUID,
    p_tier_id UUID,
    p_auto_renew BOOLEAN DEFAULT true
) RETURNS JSONB AS $$
DECLARE
    v_subscriber user_profiles%ROWTYPE;
    v_broadcaster user_profiles%ROWTYPE;
    v_tier subscription_tiers%ROWTYPE;
    v_existing user_subscriptions%ROWTYPE;
    v_new_subscription user_subscriptions%ROWTYPE;
    v_pay_success BOOLEAN;
    v_creator_amount INTEGER;
    v_admin_amount INTEGER;
    v_pool_id UUID;
BEGIN
    SELECT * INTO v_subscriber FROM user_profiles WHERE id = auth.uid();
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Subscriber not authenticated');
    END IF;

    IF COALESCE(v_subscriber.level, 1) < 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Level 1 required to subscribe. Your level: ' || COALESCE(v_subscriber.level, 1));
    END IF;

    SELECT * INTO v_broadcaster FROM user_profiles WHERE id = p_broadcaster_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Broadcaster not found');
    END IF;

    IF v_subscriber.id = v_broadcaster.id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot subscribe to yourself');
    END IF;

    SELECT * INTO v_tier FROM subscription_tiers
    WHERE id = p_tier_id AND is_active = true;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid subscription tier');
    END IF;

    SELECT * INTO v_existing
    FROM user_subscriptions
    WHERE subscriber_id = v_subscriber.id
      AND broadcaster_id = p_broadcaster_id
      AND is_active = true;

    IF FOUND THEN
        IF v_existing.tier_id = p_tier_id THEN
            RETURN jsonb_build_object('success', false, 'error', 'Already subscribed at this tier');
        END IF;

        UPDATE user_subscriptions
        SET
            tier_id = p_tier_id,
            total_paid_coins = total_paid_coins + v_tier.price_coins,
            updated_at = NOW()
        WHERE id = v_existing.id
        RETURNING * INTO v_new_subscription;

        v_pay_success := public.try_pay_coins(v_subscriber.id, v_tier.price_coins, 'subscription_upgrade', jsonb_build_object(
            'broadcaster_id', p_broadcaster_id,
            'tier_id', p_tier_id,
            'type', 'tier_upgrade'
        ));

        IF NOT v_pay_success THEN
            UPDATE user_subscriptions
            SET
                tier_id = v_existing.tier_id,
                total_paid_coins = total_paid_coins - v_tier.price_coins,
                updated_at = NOW()
            WHERE id = v_existing.id;

            RETURN jsonb_build_object('success', false, 'error', 'Insufficient coins for upgrade');
        END IF;

        v_creator_amount := (v_tier.price_coins * 90 / 100);
        v_admin_amount := (v_tier.price_coins * 10 / 100);

        UPDATE user_profiles
        SET
            total_subscriber_revenue_coins = total_subscriber_revenue_coins + v_tier.price_coins,
            troll_coins = troll_coins + v_creator_amount,
            subscriber_badge_color_hex = v_tier.color_hex
        WHERE id = p_broadcaster_id;

        SELECT id INTO v_pool_id FROM admin_pool LIMIT 1;
        IF v_pool_id IS NOT NULL THEN
            UPDATE admin_pool SET trollcoins_balance = trollcoins_balance + v_admin_amount WHERE id = v_pool_id;
            INSERT INTO admin_pool_ledger (amount, reason, ref_user_id, source_type, streamer_id)
            VALUES (v_admin_amount, 'Subscription upgrade fee', v_subscriber.id, 'subscription', p_broadcaster_id);
        END IF;

        INSERT INTO subscription_revenue_log (
            broadcaster_id, subscription_id, amount_coins,
            transaction_type, status, notes
        ) VALUES (
            p_broadcaster_id, v_existing.id, v_tier.price_coins,
            'upgrade', 'completed', 'Tier upgrade - 90% to creator, 10% to admin pool'
        );
    ELSE
        v_pay_success := public.try_pay_coins(v_subscriber.id, v_tier.price_coins, 'subscription', jsonb_build_object(
            'broadcaster_id', p_broadcaster_id,
            'tier_id', p_tier_id,
            'type', 'new_subscription'
        ));

        IF NOT v_pay_success THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Insufficient coins. Required: ' || v_tier.price_coins || '. You have: ' || v_subscriber.troll_coins
            );
        END IF;

        v_creator_amount := (v_tier.price_coins * 90 / 100);
        v_admin_amount := (v_tier.price_coins * 10 / 100);

        INSERT INTO user_subscriptions (
            subscriber_id, broadcaster_id, tier_id,
            started_at, expires_at, is_active,
            auto_renew, total_paid_coins
        ) VALUES (
            v_subscriber.id, p_broadcaster_id, p_tier_id,
            NOW(),
            CASE
                WHEN p_auto_renew THEN (NOW() + INTERVAL '30 days')
                ELSE NULL
            END,
            true,
            p_auto_renew,
            v_tier.price_coins
        ) RETURNING * INTO v_new_subscription;

        BEGIN
            INSERT INTO user_follows (follower_id, following_id)
            VALUES (v_subscriber.id, p_broadcaster_id)
            ON CONFLICT (follower_id, following_id) DO NOTHING;
        EXCEPTION
            WHEN OTHERS THEN
                RAISE NOTICE 'Follow creation failed: %', SQLERRM;
        END;

        UPDATE user_profiles
        SET
            total_subscriber_revenue_coins = total_subscriber_revenue_coins + v_tier.price_coins,
            troll_coins = troll_coins + v_creator_amount,
            subscriber_badge_color_hex = v_tier.color_hex
        WHERE id = p_broadcaster_id;

        SELECT id INTO v_pool_id FROM admin_pool LIMIT 1;
        IF v_pool_id IS NOT NULL THEN
            UPDATE admin_pool SET trollcoins_balance = trollcoins_balance + v_admin_amount WHERE id = v_pool_id;
            INSERT INTO admin_pool_ledger (amount, reason, ref_user_id, source_type, streamer_id)
            VALUES (v_admin_amount, 'New subscription fee', v_subscriber.id, 'subscription', p_broadcaster_id);
        END IF;

        INSERT INTO subscription_revenue_log (
            broadcaster_id, subscription_id, amount_coins,
            transaction_type, status
        ) VALUES (
            p_broadcaster_id, v_new_subscription.id, v_tier.price_coins,
            'monthly_fee', 'completed'
        );

        PERFORM pg_notify(
            'subscription_created',
            jsonb_build_object(
                'broadcaster_id', p_broadcaster_id,
                'subscriber_id', v_subscriber.id,
                'subscriber_username', v_subscriber.username,
                'tier_id', p_tier_id,
                'tier_name', v_tier.name,
                'amount', v_tier.price_coins
            )::text
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'subscription', row_to_json(v_new_subscription),
        'tier', row_to_json(v_tier)
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION create_subscription(UUID, UUID, BOOLEAN) TO authenticated;

-- ============================================================================
-- Fix ensure_league_system_ready: invalid input syntax for type json
-- ============================================================================
-- The issue: to_jsonb(v_event) fails when metadata column contains a value
-- that cannot be cast to JSONB. Also the CASE expression for metadata type
-- checking is unnecessary since the column is already JSONB type.
-- Fix: Use jsonb_build_object instead of to_jsonb(v_event) and handle
-- metadata safely with a TRY/CATCH pattern.

CREATE OR REPLACE FUNCTION public.ensure_league_system_ready()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_event public.league_events%ROWTYPE;
BEGIN
  PERFORM public.close_expired_league_events();

  SELECT
      id,
      name,
      slug,
      type,
      status,
      starts_at,
      ends_at,
      created_by,
      theme_key,
      points_multiplier,
      metadata,
      created_at,
      updated_at
  INTO v_event
  FROM public.league_events
  WHERE status = 'active'
    AND now() BETWEEN starts_at AND ends_at
  ORDER BY starts_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    SELECT
        id,
        name,
        slug,
        type,
        status,
        starts_at,
        ends_at,
        created_by,
        theme_key,
        points_multiplier,
        metadata,
        created_at,
        updated_at
    INTO v_event
    FROM public.create_system_league_event();
  END IF;

  IF v_event.id IS NOT NULL THEN
    PERFORM public.refresh_league_leaderboard(v_event.id);
  END IF;

  -- Safely build JSON response, handling potential metadata corruption
  RETURN jsonb_build_object(
    'id', v_event.id,
    'name', v_event.name,
    'slug', v_event.slug,
    'type', v_event.type,
    'status', v_event.status,
    'starts_at', v_event.starts_at,
    'ends_at', v_event.ends_at,
    'created_by', v_event.created_by,
    'theme_key', v_event.theme_key,
    'points_multiplier', v_event.points_multiplier,
    'metadata', CASE
      WHEN v_event.metadata IS NULL THEN '{}'::jsonb
      ELSE v_event.metadata
    END,
    'created_at', v_event.created_at,
    'updated_at', v_event.updated_at
  );
END;
$$;

-- Function: create_system_league_event
CREATE OR REPLACE FUNCTION public.create_system_league_event()
RETURNS TABLE (
    id UUID,
    name TEXT,
    slug TEXT,
    type TEXT,
    status TEXT,
    starts_at TIMESTAMPTZ,
    ends_at TIMESTAMPTZ,
    created_by TEXT,
    theme_key TEXT,
    points_multiplier NUMERIC,
    metadata JSONB,
    created_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_template RECORD;
  v_slug TEXT;
  v_event_name TEXT;
  v_duration INTERVAL;
BEGIN
  PERFORM public.close_expired_league_events();
  SELECT * INTO v_template
  FROM public.league_event_templates
  WHERE is_enabled
  ORDER BY random() * weight DESC
  LIMIT 1;

  IF NOT FOUND THEN
    v_template := ROW(
      'default_rush',
      'maitroll Rush',
      'weekly_clash',
      'A fast city competition to keep the pulse beating.',
      168,
      1,
      'ma_city',
      1,
      TRUE,
      '{}'::jsonb
    );
  END IF;

  v_event_name := v_template.name_template;
  v_slug := lower(regexp_replace(v_event_name || '-' || substring(md5(random()::text) FROM 1 FOR 6), '[^a-z0-9]+', '-', 'g'));
  v_duration := (v_template.duration_hours || ' hours')::interval;

  RETURN QUERY INSERT INTO public.league_events (
      name,
      slug,
      type,
      status,
      starts_at,
      ends_at,
      created_by,
      theme_key,
      points_multiplier,
      metadata
  ) VALUES (
      v_event_name,
      v_slug,
      v_template.type,
      'active',
      now(),
      now() + v_duration,
      'system',
      v_template.theme_key,
      v_template.points_multiplier,
      jsonb_build_object('template_key', v_template.template_key, 'auto_created', true)
  )
  RETURNING id, name, slug, type, status, starts_at, ends_at, created_by, theme_key, points_multiplier, metadata, created_at, updated_at;
END;
$$;

-- Function: create_transaction_appeal
CREATE OR REPLACE FUNCTION create_transaction_appeal(
    p_user_id UUID,
    p_order_id UUID,
    p_category appeal_category,
    p_description TEXT,
    p_desired_resolution TEXT DEFAULT NULL,
    p_evidence_urls TEXT[] DEFAULT ARRAY[]::TEXT[]
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_limit_check JSONB;
    v_order RECORD;
    v_appeal_id UUID;
    v_escrow_status TEXT;
BEGIN
    -- Check weekly limit
    v_limit_check := check_appeal_limit(p_user_id);
    IF NOT (v_limit_check->>'allowed')::BOOLEAN THEN
        RETURN v_limit_check;
    END IF;
    
    -- Get order details
    SELECT * INTO v_order FROM public.shop_orders WHERE id = p_order_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Order not found');
    END IF;
    
    -- Verify user is part of this transaction (buyer or seller)
    IF v_order.buyer_id != p_user_id AND v_order.seller_id != p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'You are not authorized to appeal this order');
    END IF;
    
    -- Get escrow status
    v_escrow_status := COALESCE(v_order.escrow_status, 'none');
    
    -- Create the appeal
    INSERT INTO public.transaction_appeals (
        user_id,
        order_id,
        shop_id,
        category,
        description,
        desired_resolution,
        evidence_urls,
        related_user_id,
        amount_in_dispute,
        escrow_release_status
    ) VALUES (
        p_user_id,
        p_order_id,
        v_order.shop_id,
        p_category,
        p_description,
        p_desired_resolution,
        p_evidence_urls,
        CASE WHEN v_order.buyer_id = p_user_id THEN v_order.seller_id ELSE v_order.buyer_id END,
        v_order.total_coins,
        v_escrow_status
    )
    RETURNING id INTO v_appeal_id;
    
    -- Update order to show appeal
    UPDATE public.shop_orders 
    SET appeal_id = v_appeal_id, delivery_status = 'disputed'
    WHERE id = p_order_id;
    
    -- Log the action
    INSERT INTO public.appeal_actions (appeal_id, user_id, action_type, new_status, notes)
    VALUES (v_appeal_id, p_user_id, 'created', 'pending', 'Appeal filed by user');
    
    RETURN jsonb_build_object(
        'success', true,
        'appeal_id', v_appeal_id,
        'message', 'Appeal filed successfully',
        'appeals_remaining', (v_limit_check->>'appeals_remaining')::INTEGER
    );
END;
$$;

-- Function: create_weekly_treasury_payout_run
CREATE OR REPLACE FUNCTION public.create_weekly_treasury_payout_run()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_uid uuid;
    v_allowed boolean := false;
    v_week_start date;
    v_week_end date;
    v_existing_run_id uuid;
    v_new_run_id uuid;
    v_item_count bigint := 0;
    v_total_amount bigint := 0;
    v_allocation_count bigint := 0;
    v_eligible_user_count bigint := 0;
    v_debug_json jsonb := '{}'::jsonb;
BEGIN
    v_uid := auth.uid();

    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    -- Check permissions (admin/president/CEO)
    SELECT EXISTS (
        SELECT 1
        FROM public.user_profiles
        WHERE id = v_uid
          AND (
            role IN ('admin', 'president', 'owner')
            OR is_admin = true
            OR role = 'ceo'
            OR troll_role IN ('admin', 'president', 'owner', 'ceo')
          )
    ) INTO v_allowed;

    IF NOT v_allowed THEN
        RAISE EXCEPTION 'Only admins, CEOs, or the president can create weekly treasury payout runs';
    END IF;

    v_week_start := date_trunc('week', current_date)::date;
    v_week_end := v_week_start + interval '6 days';

    -- Check for existing run
    SELECT id
      INTO v_existing_run_id
      FROM public.treasury_payout_runs
     WHERE run_week_start = v_week_start
       AND status <> 'cancelled'
     LIMIT 1;

    IF FOUND THEN
        RAISE EXCEPTION 'A weekly treasury payout run already exists for %', v_week_start;
    END IF;

    -- Create new payout run
    INSERT INTO public.treasury_payout_runs (
        run_week_start,
        run_week_end,
        status,
        total_amount_coins,
        created_by,
        notes
    )
    VALUES (
        v_week_start,
        v_week_end,
        'draft',
        0,
        v_uid,
        jsonb_build_object('created_from', 'weekly_treasury_run')
    )
    RETURNING id INTO v_new_run_id;

    -- Get active allocations with positive amounts
    WITH active_allocations AS (
        SELECT *
          FROM public.treasury_role_allocations
         WHERE is_active = true
           AND weekly_amount_coins > 0
    ),
    -- Get users with active career assignments for those roles
    eligible_assignments AS (
        SELECT
            cra.user_id,
            cra.role_key
          FROM public.career_role_assignments cra
          JOIN active_allocations aa ON aa.role_key = cra.role_key
         WHERE cra.status = 'active'
           AND (cra.expires_at IS NULL OR cra.expires_at > NOW())
    ),
    -- Fallback to user_profiles.role if no assignment table exists (for backward compatibility)
    fallback_eligible AS (
        SELECT
            up.id AS user_id,
            CASE
                WHEN lower(COALESCE(up.role, '')) IN ('troll_officer', 'lead_troll_officer', 'officer') OR lower(COALESCE(up.troll_role, '')) IN ('troll_officer', 'lead_troll_officer', 'officer') OR up.is_troll_officer = true OR up.is_lead_officer = true THEN 'troll_officer'
                WHEN lower(COALESCE(up.role, '')) IN ('secretary', 'executive_secretary', 'troll_city_secretary') OR lower(COALESCE(up.troll_role, '')) IN ('secretary', 'executive_secretary', 'troll_city_secretary') THEN 'secretary'
                WHEN lower(COALESCE(up.role, '')) = 'president' OR lower(COALESCE(up.troll_role, '')) = 'president' THEN 'president'
                WHEN lower(COALESCE(up.role, '')) IN ('agency_hr_manager', 'hr_admin') OR lower(COALESCE(up.troll_role, '')) IN ('agency_hr_manager', 'hr_admin') THEN 'agency_hr_manager'
                WHEN lower(COALESCE(up.role, '')) = 'assistant' OR lower(COALESCE(up.troll_role, '')) = 'assistant' THEN 'assistant'
                WHEN lower(COALESCE(up.role, '')) = 'city_operations_runner' OR lower(COALESCE(up.troll_role, '')) = 'city_operations_runner' THEN 'city_operations_runner'
                WHEN lower(COALESCE(up.role, '')) = 'creator_support_representative' OR lower(COALESCE(up.troll_role, '')) = 'creator_support_representative' THEN 'creator_support_representative'
                WHEN lower(COALESCE(up.role, '')) = 'auctioneer' OR lower(COALESCE(up.troll_role, '')) = 'auctioneer' THEN 'auctioneer'
                ELSE lower(COALESCE(up.role, up.troll_role, ''))
            END AS effective_role_key
          FROM public.user_profiles up
    ),
    -- Use career assignments if table has data, otherwise fallback
    final_eligible AS (
        SELECT
            ea.user_id,
            ea.role_key
          FROM eligible_assignments ea
        UNION ALL
        SELECT
            fe.user_id,
            fe.effective_role_key
          FROM fallback_eligible fe
          WHERE NOT EXISTS (SELECT 1 FROM public.career_role_assignments WHERE status = 'active' LIMIT 1)
    )
    -- Insert payout items
    INSERT INTO public.treasury_payout_items (payout_run_id, user_id, role_key, amount_coins, status, details)
    SELECT
        v_new_run_id,
        fe.user_id,
        fe.role_key,
        aa.weekly_amount_coins,
        'pending',
        jsonb_build_object(
            'role_label', aa.role_label,
            'assignment_source', CASE WHEN cra.user_id IS NOT NULL THEN 'career_role_assignments' ELSE 'user_profiles.role' END
        )
      FROM final_eligible fe
      JOIN active_allocations aa ON aa.role_key = fe.role_key
      LEFT JOIN public.career_role_assignments cra ON cra.user_id = fe.user_id AND cra.role_key = fe.role_key AND cra.status = 'active'
     WHERE aa.is_active = true
       AND aa.weekly_amount_coins > 0
     ON CONFLICT (payout_run_id, user_id, role_key) DO NOTHING;

    -- Get counts
    SELECT COUNT(*)
      INTO v_allocation_count
      FROM public.treasury_role_allocations
     WHERE is_active = true
       AND weekly_amount_coins > 0;

    SELECT COUNT(DISTINCT fe.user_id)
      INTO v_eligible_user_count
      FROM final_eligible fe
      JOIN active_allocations aa ON aa.role_key = fe.role_key;

    SELECT COUNT(*), COALESCE(SUM(amount_coins), 0)
      INTO v_item_count, v_total_amount
      FROM public.treasury_payout_items
     WHERE payout_run_id = v_new_run_id;

    -- Update run total
    UPDATE public.treasury_payout_runs
       SET total_amount_coins = v_total_amount,
           updated_at = now()
     WHERE id = v_new_run_id;

    -- Build debug info
    v_debug_json := jsonb_build_object(
        'allocation_count', v_allocation_count,
        'eligible_user_count', v_eligible_user_count,
        'item_count', v_item_count,
        'total_amount_coins', v_total_amount,
        'run_id', v_new_run_id::text,
        'week_start', v_week_start::text,
        'week_end', v_week_end::text
    );

    RAISE NOTICE 'Treasury payout run created: %', v_debug_json;

    RETURN jsonb_build_object(
        'run_id', v_new_run_id,
        'run_week_start', v_week_start,
        'run_week_end', v_week_end,
        'item_count', v_item_count,
        'total_amount_coins', v_total_amount,
        'debug', v_debug_json
    );
END;
$$;

-- Function: credit_coins
CREATE OR REPLACE FUNCTION public.credit_coins(
    p_user_id uuid,
    p_coins int,
    p_reason text DEFAULT 'legacy_credit'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT public.troll_bank_credit_coins(
        p_user_id,
        p_coins,
        'paid',
        'legacy_credit',
        NULL,
        jsonb_build_object('reason', p_reason, 'legacy_function', 'credit_coins')
    ) INTO v_result;

    RETURN v_result;
END;
$$;

-- Function: credit_treasury_revenue
CREATE OR REPLACE FUNCTION public.credit_treasury_revenue(
  p_source_type text,
  p_amount_coins bigint,
  p_created_by uuid,
  p_details jsonb DEFAULT '{}'::jsonb,
  p_source_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_uid uuid;
  v_treasury_id uuid;
  v_balance_before bigint;
  v_balance_after bigint;
  v_total_earned bigint;
  v_allowed boolean := false;
BEGIN
  v_uid := auth.uid();

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_amount_coins IS NULL OR p_amount_coins <= 0 THEN
    RAISE EXCEPTION 'amount_coins must be greater than zero';
  END IF;

  IF p_created_by IS NULL OR p_created_by <> v_uid THEN
    RAISE EXCEPTION 'created_by must match the authenticated user';
  END IF;

  IF p_source_type IS NULL OR btrim(p_source_type) = '' THEN
    RAISE EXCEPTION 'source_type is required';
  END IF;

  IF p_source_type NOT IN ('auction_fee', 'agency_fee', 'marketplace_fee', 'profile_view_fee', 'message_fee', 'house_fee', 'city_tax', 'permit_fee', 'manual_admin_deposit', 'other') THEN
    RAISE EXCEPTION 'Unsupported source_type: %', p_source_type;
  END IF;

  IF p_source_type = 'manual_admin_deposit' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.user_profiles
      WHERE id = v_uid
        AND (
          role IN ('admin', 'owner')
          OR is_admin = true
          OR role = 'ceo'
          OR troll_role IN ('admin', 'owner', 'ceo')
        )
    ) INTO v_allowed;

    IF NOT v_allowed THEN
      RAISE EXCEPTION 'Only admin or CEO can add a manual treasury deposit';
    END IF;
  END IF;

  SELECT id, balance_coins, total_earned_coins
    INTO v_treasury_id, v_balance_before, v_total_earned
  FROM public.troll_city_treasury
  ORDER BY created_at ASC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.troll_city_treasury (treasury_name, balance_coins, total_earned_coins, total_distributed_coins, status)
    VALUES ('maitroll Treasury', 0, 0, 0, 'active')
    RETURNING id, balance_coins, total_earned_coins INTO v_treasury_id, v_balance_before, v_total_earned;
  END IF;

  v_balance_after := v_balance_before + p_amount_coins;

  UPDATE public.troll_city_treasury
  SET balance_coins = v_balance_after,
      total_earned_coins = v_total_earned + p_amount_coins,
      updated_at = now()
  WHERE id = v_treasury_id;

  INSERT INTO public.treasury_transactions (
    treasury_id,
    user_id,
    transaction_type,
    source_type,
    source_id,
    direction,
    amount_coins,
    balance_before,
    balance_after,
    created_by,
    details
  )
  VALUES (
    v_treasury_id,
    NULL,
    CASE WHEN p_source_type = 'manual_admin_deposit' THEN 'manual_credit' ELSE 'revenue_credit' END,
    p_source_type,
    p_source_id,
    'credit',
    p_amount_coins,
    v_balance_before,
    v_balance_after,
    v_uid,
    COALESCE(p_details, '{}'::jsonb)
  );

  RETURN jsonb_build_object(
    'treasury_id', v_treasury_id,
    'balance_before', v_balance_before,
    'balance_after', v_balance_after,
    'amount_coins', p_amount_coins,
    'source_type', p_source_type
  );
END;
$$;

-- Function: crypt_password
CREATE OR REPLACE FUNCTION public.crypt_password(
  p_password TEXT
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN crypt(p_password, gen_salt('bf'));
END;
$$;

-- Function: deduct_call_minutes
CREATE OR REPLACE FUNCTION public.deduct_call_minutes(
    p_user_id UUID,
    p_minutes INTEGER,
    p_type TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
    v_current_audio INTEGER := 0;
    v_current_video INTEGER := 0;
    v_new_audio INTEGER;
    v_new_video INTEGER;
BEGIN
    -- Get current balance
    SELECT COALESCE(audio_minutes, 0), COALESCE(video_minutes, 0)
    INTO v_current_audio, v_current_video
    FROM public.call_minutes
    WHERE user_id = p_user_id;

    -- Calculate new balances
    IF p_type = 'audio' THEN
        v_new_audio := GREATEST(0, v_current_audio - p_minutes);
        v_new_video := v_current_video;
    ELSE -- video uses 2x minutes
        v_new_audio := v_current_audio;
        v_new_video := GREATEST(0, v_current_video - (p_minutes * 2));
    END IF;

    -- Update balance
    UPDATE public.call_minutes
    SET
        audio_minutes = v_new_audio,
        video_minutes = v_new_video,
        updated_at = NOW()
    WHERE user_id = p_user_id;

    -- Handle case where no row existed
    IF NOT FOUND THEN
        INSERT INTO public.call_minutes (user_id, audio_minutes, video_minutes)
        VALUES (p_user_id, 0, 0);
        v_new_audio := 0;
        v_new_video := 0;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'has_minutes', CASE WHEN p_type = 'audio' THEN v_new_audio > 0 ELSE v_new_video > 0 END,
        'audio_minutes', v_new_audio,
        'video_minutes', v_new_video
    );
END;
$$;

-- Function: deny_advertisement
CREATE OR REPLACE FUNCTION public.deny_advertisement(
    p_ad_id UUID,
    p_reason TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_is_admin BOOLEAN;
BEGIN
    SELECT (role IN ('admin', 'secretary', 'lead_troll_officer') OR is_admin = true)
    INTO v_is_admin
    FROM public.user_profiles
    WHERE id = auth.uid();

    IF NOT v_is_admin THEN
        RETURN jsonb_build_object('success', false, 'message', 'Permission denied');
    END IF;

    UPDATE public.user_advertisements
    SET 
        status = 'denied',
        denied_at = NOW(),
        denied_reason = p_reason,
        updated_at = NOW()
    WHERE id = p_ad_id;

    RETURN jsonb_build_object('success', true, 'message', 'Advertisement denied');
END;
$$;

-- Function: disable_payout_window
CREATE OR REPLACE FUNCTION public.disable_payout_window()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_config JSONB;
BEGIN
  SELECT setting_value INTO v_config
  FROM public.admin_app_settings
  WHERE setting_key = 'payout_window_config'
  FOR UPDATE;

  IF v_config IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'No payout window config found');
  END IF;

  v_config := jsonb_set(v_config, '{enabled}', 'false');
  v_config := jsonb_set(v_config, '{message}', 'Payout window closed by administrator');

  UPDATE public.admin_app_settings
  SET setting_value = v_config,
      updated_at = now()
  WHERE setting_key = 'payout_window_config';

  RETURN jsonb_build_object('success', true, 'message', 'Payout window disabled');
END;
$$;

-- Function: distribute_battle_winnings
CREATE OR REPLACE FUNCTION public.distribute_battle_winnings(
    p_battle_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $function$
DECLARE
    v_battle RECORD;
    v_total_pot numeric;
    v_winner_stream_id uuid;
    v_loser_stream_id uuid;
    v_winner_host_id uuid;
    v_loser_host_id uuid;
    v_winner_participants uuid[];
    v_share_per_person numeric;
    v_admin_cut numeric;
    v_final_pot numeric;
BEGIN
    -- Get Battle Info with row-level lock
    SELECT * INTO v_battle FROM battles WHERE id = p_battle_id FOR UPDATE;

    IF v_battle IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Battle not found');
    END IF;

    IF v_battle.payout_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Winnings already distributed');
    END IF;

    IF v_battle.status = 'ended' AND v_battle.winner_stream_id IS NOT NULL THEN
        -- Determine Winner Side
        IF v_battle.score_challenger > v_battle.score_opponent THEN
            v_winner_stream_id := v_battle.challenger_stream_id;
            v_loser_stream_id := v_battle.opponent_stream_id;
            v_total_pot := COALESCE(v_battle.pot_challenger, 0) + COALESCE(v_battle.pot_opponent, 0);
        ELSE
            v_winner_stream_id := v_battle.opponent_stream_id;
            v_loser_stream_id := v_battle.challenger_stream_id;
            v_total_pot := COALESCE(v_battle.pot_challenger, 0) + COALESCE(v_battle.pot_opponent, 0);
        END IF;

        -- Identify Hosts
        SELECT user_id INTO v_winner_host_id FROM streams WHERE id = v_winner_stream_id;
        SELECT user_id INTO v_loser_host_id FROM streams WHERE id = v_loser_stream_id;

        -- Update Host Stats (Wins/Losses)
        IF v_winner_host_id IS NOT NULL THEN
            UPDATE user_profiles SET battle_wins = battle_wins + 1 WHERE id = v_winner_host_id;
        END IF;
        IF v_loser_host_id IS NOT NULL THEN
            UPDATE user_profiles SET battle_losses = battle_losses + 1 WHERE id = v_loser_host_id;
        END IF;

        -- Get Winner Guests (accepted/joined)
        SELECT array_agg(user_id) INTO v_winner_participants
        FROM stream_guests
        WHERE stream_id = v_winner_stream_id AND status = 'accepted';

        -- Combine Winner Participants for Pot
        IF v_winner_participants IS NULL THEN
            v_winner_participants := ARRAY[v_winner_host_id];
        ELSE
            v_winner_participants := array_append(v_winner_participants, v_winner_host_id);
        END IF;

        -- Apply Admin Cut (10%) to the POT
        v_admin_cut := floor(v_total_pot * 0.10);
        v_final_pot := v_total_pot - v_admin_cut;

        -- Split evenly
        v_share_per_person := floor(v_final_pot / array_length(v_winner_participants, 1));

        -- Distribute Pot (using troll_coins)
        IF v_share_per_person > 0 THEN
            UPDATE user_profiles
            SET troll_coins = troll_coins + v_share_per_person
            WHERE id = ANY(v_winner_participants);

            -- Log Ledger
            INSERT INTO coin_ledger (user_id, amount, transaction_type, reason, metadata)
            SELECT
                u_id,
                v_share_per_person,
                'income',
                'battle_win',
                jsonb_build_object('battle_id', p_battle_id, 'role', 'winner')
            FROM unnest(v_winner_participants) AS u_id;
        END IF;

        -- Mark as paid
        UPDATE battles SET payout_at = NOW() WHERE id = p_battle_id;

        -- Update Trollmers weekly leaderboard (if applicable)
        PERFORM public.update_trollmers_weekly_leaderboard(p_battle_id);

        RETURN jsonb_build_object('success', true, 'distributed', v_final_pot, 'recipients', array_length(v_winner_participants, 1));
    END IF;

    RETURN jsonb_build_object('success', false, 'message', 'Battle not ended or no winner');
END;
$function$;

-- ============================================================================
-- MONTHLY TOURNAMENT SYSTEM
-- ============================================================================

-- 9. Get month start (1st day of given month in America/Denver timezone)
CREATE OR REPLACE FUNCTION public.get_trollmers_month_start(p_ts TIMESTAMPTZ DEFAULT NOW())
RETURNS DATE
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
    RETURN DATE_TRUNC('month', p_ts AT TIME ZONE 'America/Denver')::DATE;
END;
$$;

-- Function: distribute_officer_payroll
CREATE OR REPLACE FUNCTION public.distribute_officer_payroll(p_admin_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
SET row_security = off
AS $$
DECLARE
  v_pool_balance bigint;
  v_pool_before bigint;
  v_total_due bigint := 0;
  v_total_paid bigint := 0;
  v_officer_count int := 0;
  v_paid_count int := 0;
  v_prorate_ratio numeric := 1.0;
  v_pay_period_start date := date_trunc('week', now())::date;
  v_pay_period_end date := (date_trunc('week', now()) + interval '6 days')::date;
  v_dist_record record;
  v_base_pay bigint;
  v_bonus_pay bigint;
  v_total_due_for_officer bigint;
  v_payout_amount bigint;
  v_is_corrupt boolean;
  v_status text;
  v_reason text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = p_admin_user_id AND (role IN ('admin', 'secretary') OR is_admin = true)
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT COALESCE(SUM(coin_amount), 0)
  INTO v_pool_balance
  FROM public.officer_pay_ledger;

  v_pool_before := v_pool_balance;

  IF v_pool_balance <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'No funds in officer pool');
  END IF;

  FOR v_dist_record IN
    SELECT up.id, up.role, up.is_troll_officer, up.is_lead_officer, up.is_officer_active
    FROM public.user_profiles up
    WHERE (
      up.role IN ('troll_officer', 'lead_troll_officer', 'lead_officer', 'secretary')
      OR up.is_troll_officer = true
      OR up.is_lead_officer = true
    )
    AND COALESCE(up.is_officer_active, true) = true
  LOOP
    SELECT EXISTS (
      SELECT 1 FROM public.officer_corruption_flags cf
      WHERE cf.officer_id = v_dist_record.id AND cf.resolved = false
    ) INTO v_is_corrupt;

    IF v_is_corrupt THEN
      CONTINUE;
    END IF;

    v_base_pay := CASE
      WHEN v_dist_record.role IN ('lead_troll_officer', 'lead_officer') OR v_dist_record.is_lead_officer = true THEN 1800
      WHEN v_dist_record.role = 'secretary' THEN 2700
      ELSE 900
    END;

    v_bonus_pay := floor(v_base_pay * 0.10)::bigint;
    v_total_due := v_total_due + v_base_pay + v_bonus_pay;
  END LOOP;

  IF v_total_due <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'No eligible officers to pay');
  END IF;

  IF v_pool_balance < v_total_due THEN
    v_prorate_ratio := v_pool_balance::numeric / v_total_due::numeric;
  END IF;

  FOR v_dist_record IN
    SELECT up.id, up.role, up.username, up.is_troll_officer, up.is_lead_officer, up.is_officer_active
    FROM public.user_profiles up
    WHERE (
      up.role IN ('troll_officer', 'lead_troll_officer', 'lead_officer', 'secretary')
      OR up.is_troll_officer = true
      OR up.is_lead_officer = true
    )
    AND COALESCE(up.is_officer_active, true) = true
  LOOP
    v_officer_count := v_officer_count + 1;

    SELECT EXISTS (
      SELECT 1 FROM public.officer_corruption_flags cf
      WHERE cf.officer_id = v_dist_record.id AND cf.resolved = false
    ) INTO v_is_corrupt;

    v_base_pay := CASE
      WHEN v_dist_record.role IN ('lead_troll_officer', 'lead_officer') OR v_dist_record.is_lead_officer = true THEN 1800
      WHEN v_dist_record.role = 'secretary' THEN 2700
      ELSE 900
    END;

    v_bonus_pay := floor(v_base_pay * 0.10)::bigint;
    v_total_due_for_officer := v_base_pay + v_bonus_pay;
    v_payout_amount := floor(v_total_due_for_officer * v_prorate_ratio)::bigint;
    v_status := 'paid';
    v_reason := NULL;

    IF v_is_corrupt THEN
      v_status := 'frozen';
      v_reason := 'corruption_flag';
      v_payout_amount := 0;
    ELSIF v_total_due_for_officer <= 0 THEN
      v_status := 'skipped';
      v_reason := 'no_due';
      v_payout_amount := 0;
    ELSIF v_payout_amount <= 0 THEN
      v_status := 'skipped';
      v_reason := 'insufficient_pool';
      v_payout_amount := 0;
    ELSIF v_prorate_ratio < 1 THEN
      v_status := 'prorated';
      v_reason := 'pool_prorated';
    END IF;

    IF v_payout_amount > 0 THEN
      UPDATE public.user_profiles
      SET troll_coins = troll_coins + v_payout_amount
      WHERE id = v_dist_record.id;

      INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, metadata)
      VALUES (
        v_dist_record.id,
        v_payout_amount,
        'payroll',
        'officer_salary',
        'Weekly Officer Salary',
        jsonb_build_object(
          'base_pay', v_base_pay,
          'bonus_pay', v_bonus_pay,
          'prorate_ratio', v_prorate_ratio,
          'pay_period_start', v_pay_period_start,
          'pay_period_end', v_pay_period_end
        )
      );

      INSERT INTO public.officer_pay_ledger (source_type, source_id, coin_amount, metadata)
      VALUES (
        'officer_payout',
        v_dist_record.id::text,
        -v_payout_amount,
        jsonb_build_object(
          'base_pay', v_base_pay,
          'bonus_pay', v_bonus_pay,
          'prorate_ratio', v_prorate_ratio,
          'pay_period_start', v_pay_period_start,
          'pay_period_end', v_pay_period_end
        )
      );

      v_total_paid := v_total_paid + v_payout_amount;
      v_paid_count := v_paid_count + 1;
    END IF;

    INSERT INTO public.officer_payroll_logs (
      officer_id,
      role,
      pay_period_start,
      pay_period_end,
      base_pay,
      bonus_pay,
      total_paid,
      status,
      reason,
      pool_balance_before,
      pool_balance_after,
      metadata
    ) VALUES (
      v_dist_record.id,
      CASE
        WHEN v_dist_record.role IS NOT NULL THEN v_dist_record.role
        WHEN v_dist_record.is_lead_officer = true THEN 'lead_officer'
        ELSE 'troll_officer'
      END,
      v_pay_period_start,
      v_pay_period_end,
      v_base_pay,
      v_bonus_pay,
      v_payout_amount,
      v_status,
      v_reason,
      v_pool_before,
      v_pool_before - v_total_paid,
      jsonb_build_object(
        'total_due', v_total_due_for_officer,
        'prorate_ratio', v_prorate_ratio
      )
    );
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_paid', v_total_paid,
    'officers_paid', v_paid_count,
    'officers_considered', v_officer_count,
    'remaining_pool', v_pool_before - v_total_paid,
    'prorate_ratio', v_prorate_ratio
  );
END;
$$;

-- Function: donate_to_public_pool
CREATE OR REPLACE FUNCTION public.donate_to_public_pool(
    p_amount NUMERIC,
    p_message TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_current_balance NUMERIC;
BEGIN
    v_user_id := auth.uid();
    
    -- Check if user exists
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Check amount
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Invalid amount';
    END IF;

    -- Check user balance
    SELECT troll_coins INTO v_current_balance
    FROM public.user_profiles
    WHERE id = v_user_id;

    IF v_current_balance < p_amount THEN
        RAISE EXCEPTION 'Insufficient funds';
    END IF;

    -- Deduct from user
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - p_amount
    WHERE id = v_user_id;

    -- Add to Admin Pool (System Wallet)
    -- We assume there is at least one row.
    UPDATE public.admin_pool
    SET trollcoins_balance = trollcoins_balance + p_amount
    WHERE id = (SELECT id FROM public.admin_pool LIMIT 1);

    -- Log donation
    INSERT INTO public.pool_donations (user_id, amount, message)
    VALUES (v_user_id, p_amount, p_message);

    RETURN jsonb_build_object(
        'success', true,
        'new_balance', v_current_balance - p_amount
    );
END;
$$;

-- Function: draw_raffle_winners
CREATE OR REPLACE FUNCTION public.draw_raffle_winners(p_raffle_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_raffle record;
  v_stream_id uuid;
  v_winner1 uuid;
  v_winner2 uuid;
  v_winner3 uuid;
  v_round integer;
BEGIN
  -- Lock the raffle row to prevent concurrent draws
  SELECT r.*, s.id AS sid INTO v_raffle
  FROM public.stream_raffles r
  JOIN public.streams s ON s.id = r.stream_id
  WHERE r.id = p_raffle_id AND r.status = 'active'
  FOR UPDATE OF r;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Raffle not found or not active');
  END IF;

  v_stream_id := v_raffle.sid;

  IF NOT public._smoke_check_admin_or_host(v_stream_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only admin or stream host can draw winners');
  END IF;

  v_round := v_raffle.current_round;

  SELECT user_id INTO v_winner1 FROM public.stream_raffle_tickets
  WHERE raffle_id = p_raffle_id AND round_number = v_round
  GROUP BY user_id ORDER BY random() LIMIT 1;

  SELECT user_id INTO v_winner2 FROM public.stream_raffle_tickets
  WHERE raffle_id = p_raffle_id AND round_number = v_round AND user_id != v_winner1
  GROUP BY user_id ORDER BY random() LIMIT 1;

  SELECT user_id INTO v_winner3 FROM public.stream_raffle_tickets
  WHERE raffle_id = p_raffle_id AND round_number = v_round AND user_id != v_winner1 AND user_id != v_winner2
  GROUP BY user_id ORDER BY random() LIMIT 1;

  IF v_winner1 IS NOT NULL THEN
    INSERT INTO public.stream_raffle_winners (raffle_id, stream_id, round_number, place, user_id, prize_usd)
    VALUES (p_raffle_id, v_stream_id, v_round, 1, v_winner1, 25.00);
  END IF;

  IF v_winner2 IS NOT NULL THEN
    INSERT INTO public.stream_raffle_winners (raffle_id, stream_id, round_number, place, user_id, prize_usd)
    VALUES (p_raffle_id, v_stream_id, v_round, 2, v_winner2, 15.00);
  END IF;

  IF v_winner3 IS NOT NULL THEN
    INSERT INTO public.stream_raffle_winners (raffle_id, stream_id, round_number, place, user_id, prize_usd)
    VALUES (p_raffle_id, v_stream_id, v_round, 3, v_winner3, 5.00);
  END IF;

  UPDATE public.stream_raffles
  SET current_round = current_round + 1,
      next_draw_at = now() + (draw_interval_minutes || ' minutes')::interval,
      updated_at = now()
  WHERE id = p_raffle_id;

  RETURN jsonb_build_object(
    'success', true,
    'round', v_round,
    'winners', jsonb_build_array(
      jsonb_build_object('place', 1, 'user_id', v_winner1, 'prize', 25.00),
      jsonb_build_object('place', 2, 'user_id', v_winner2, 'prize', 15.00),
      jsonb_build_object('place', 3, 'user_id', v_winner3, 'prize', 5.00)
    )
  );
END;
$$;

-- Function: earn_coins
CREATE OR REPLACE FUNCTION public.earn_coins(
    p_user_id    UUID,
    p_amount     NUMERIC(20, 2),
    p_bucket     TEXT    DEFAULT 'paid',
    p_source     TEXT    DEFAULT 'purchase',
    p_ref_id     TEXT    DEFAULT NULL,
    p_metadata   JSONB   DEFAULT '{}'::jsonb,
    p_description TEXT   DEFAULT 'Coin credit'
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_new_balance NUMERIC(20, 2);
BEGIN
    -- Validate amount
    IF p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Amount must be positive');
    END IF;

    -- Check user exists and get current balance
    SELECT troll_coins INTO v_new_balance
    FROM public.user_profiles
    WHERE id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'User not found');
    END IF;

    -- Credit coins via user_profiles
    UPDATE public.user_profiles
    SET troll_coins = troll_coins + p_amount
    WHERE id = p_user_id
    RETURNING troll_coins INTO v_new_balance;

    -- Log to coin_ledger (matching schema: user_id, delta, bucket, source, metadata, direction)
    INSERT INTO public.coin_ledger (
        user_id, delta, bucket, source, ref_id, metadata, direction
    ) VALUES (
        p_user_id, p_amount, p_bucket, p_source, p_ref_id,
        jsonb_build_object('description', COALESCE(p_description, ''), 'earned_via', p_source),
        'in'
    );

    RETURN jsonb_build_object(
        'success', true,
        'new_balance', v_new_balance
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: earn_hype_coin_watch_reward
CREATE OR REPLACE FUNCTION public.earn_hype_coin_watch_reward(p_stream_id uuid)
RETURNS TABLE(
  success boolean,
  hype_coins bigint,
  earned_amount integer,
  daily_earned integer,
  daily_cap integer,
  weekly_earned integer,
  weekly_cap integer,
  message text
) AS $$
DECLARE
  v_user_id uuid;
  v_stream record;
  v_daily_earned integer;
  v_weekly_earned integer;
  v_last_award_time timestamptz;
  v_current_user_hype integer;
  v_earning_window_start timestamptz;
  v_error_msg text;
  v_attempted_amount integer := 1;
  v_awarded_amount integer;
  v_remaining_allowance integer;
BEGIN
  -- 1. Check authentication
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN QUERY SELECT
      false,
      0::bigint,
      0,
      0,
      25,
      0,
      175,
      'Not authenticated'::text;
    RETURN;
  END IF;

  -- 2. Fetch stream details
  SELECT id, user_id, status, is_live, ended_at
  INTO v_stream
  FROM public.streams
  WHERE id = p_stream_id;

  IF v_stream IS NULL THEN
    RETURN QUERY SELECT
      false,
      0::bigint,
      0,
      0,
      25,
      0,
      175,
      'Stream not found'::text;
    RETURN;
  END IF;

  -- 3. Verify stream is live
  IF (v_stream.status != 'live' AND v_stream.is_live != true) OR v_stream.ended_at IS NOT NULL THEN
    RETURN QUERY SELECT
      false,
      0::bigint,
      0,
      0,
      25,
      0,
      175,
      'Stream is not live'::text;
    RETURN;
  END IF;

  -- 4. Verify viewer is not the broadcaster
  IF v_stream.user_id = v_user_id THEN
    RETURN QUERY SELECT
      false,
      0::bigint,
      0,
      0,
      25,
      0,
      175,
      'Cannot earn from your own stream'::text;
    RETURN;
  END IF;

  -- 5. Lock user's profile to prevent concurrent awards for the same user
  -- This prevents race conditions where multiple concurrent calls could exceed the daily cap
  SELECT user_profiles.hype_coins
  INTO v_current_user_hype
  FROM public.user_profiles
  WHERE id = v_user_id
  FOR UPDATE;

  -- 6. Check daily cap (25 Hype Coins per day)
  SELECT COALESCE(SUM(amount), 0)::integer
  INTO v_daily_earned
  FROM public.hype_coin_ledger
  WHERE user_id = v_user_id
    AND action = 'hype_watch_earned'
    AND created_at >= NOW()::date;

  -- Calculate remaining daily allowance
  v_remaining_allowance := 25 - v_daily_earned;
  
  IF v_remaining_allowance <= 0 THEN
    RETURN QUERY SELECT
      false,
      0::bigint,
      0, -- earned_amount
      v_daily_earned,
      25,
      0,
      175,
      'Daily earning cap reached'::text;
    RETURN;
  END IF;

  -- 7. Check weekly cap (175 Hype Coins per week)
  SELECT COALESCE(SUM(amount), 0)::integer
  INTO v_weekly_earned
  FROM public.hype_coin_ledger
  WHERE user_id = v_user_id
    AND action = 'hype_watch_earned'
    AND created_at >= NOW() - interval '7 days';

  IF v_weekly_earned >= 175 THEN
    RETURN QUERY SELECT
      false,
      0::bigint,
      0,
      v_daily_earned,
      25,
      v_weekly_earned,
      175,
      'Weekly earning cap reached'::text;
    RETURN;
  END IF;

  -- 8. Check for duplicate rewards in same 5-minute window
  v_earning_window_start := to_timestamp(EXTRACT(EPOCH FROM NOW())::integer / 300 * 300);

  SELECT created_at
  INTO v_last_award_time
  FROM public.hype_coin_ledger
  WHERE user_id = v_user_id
    AND action = 'hype_watch_earned'
    AND created_at >= v_earning_window_start
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_last_award_time IS NOT NULL THEN
    RETURN QUERY SELECT
      false,
      0::bigint,
      0,
      v_daily_earned,
      25,
      v_weekly_earned,
      175,
      'Already earned in this 5-minute window'::text;
    RETURN;
  END IF;

  -- 9. Calculate actual awarded amount (respect daily cap)
  v_awarded_amount := LEAST(v_attempted_amount, v_remaining_allowance);

  -- 10. Credit awarded Hype Coins
  IF v_awarded_amount > 0 THEN
    UPDATE public.user_profiles
    SET hype_coins = hype_coins + v_awarded_amount
    WHERE id = v_user_id;
  END IF;

  -- 11. Insert ledger entry with actual awarded amount
  IF v_awarded_amount > 0 THEN
    INSERT INTO public.hype_coin_ledger (user_id, stream_id, broadcaster_id, amount, action, metadata)
    VALUES (v_user_id, p_stream_id, v_stream.user_id, v_awarded_amount, 'hype_watch_earned', jsonb_build_object(
      'stream_title', v_stream.id,
      'earned_at', NOW(),
      'attempted_amount', v_attempted_amount,
      'awarded_amount', v_awarded_amount,
      'earned_today_before', v_daily_earned,
      'daily_cap', 25
    ));
  END IF;

  -- 12. Fetch updated balance
  SELECT user_profiles.hype_coins INTO v_current_user_hype
  FROM public.user_profiles
  WHERE id = v_user_id;

  -- 13. Return success
  IF v_awarded_amount > 0 THEN
    RETURN QUERY SELECT
      true,
      v_current_user_hype::bigint,
      v_awarded_amount,
      v_daily_earned + v_awarded_amount,
      25,
      v_weekly_earned + v_awarded_amount,
      175,
      'Hype Coin earned'::text;
  ELSE
    RETURN QUERY SELECT
      false,
      0::bigint,
      0,
      v_daily_earned,
      25,
      0,
      175,
      'Daily earning cap reached'::text;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ============================================================================
-- 7. RPC: GIFT_HYPE_COIN_TO_VIEWER (Broadcaster gifts hype coin to viewer)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.gift_hype_coin_to_viewer(p_stream_id uuid, p_viewer_id uuid)
RETURNS TABLE(
  success boolean,
  hype_coins bigint,
  earned_amount integer,
  daily_earned integer,
  daily_cap integer,
  weekly_earned integer,
  weekly_cap integer,
  message text
) AS $$
DECLARE
  v_broadcaster_id uuid;
  v_viewer_record record;
  v_stream record;
  v_daily_earned integer;
  v_weekly_earned integer;
  v_last_award_time timestamptz;
  v_current_viewer_hype integer;
  v_earning_window_start timestamptz;
  v_attempted_amount integer := 1;
  v_awarded_amount integer;
  v_remaining_allowance integer;
  v_existing_balance integer;
BEGIN
  -- 1. Check authentication
  v_broadcaster_id := auth.uid();
  IF v_broadcaster_id IS NULL THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, 0, 25, 0, 175, 'Not authenticated'::text;
    RETURN;
  END IF;

  -- 2. Fetch stream details and verify broadcaster owns it
  SELECT id, user_id, status, is_live, ended_at
  INTO v_stream
  FROM public.streams
  WHERE id = p_stream_id;

  IF v_stream IS NULL THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, 0, 25, 0, 175, 'Stream not found'::text;
    RETURN;
  END IF;

  -- Only the broadcaster can gift hype coins
  IF v_stream.user_id != v_broadcaster_id THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, 0, 25, 0, 175, 'Only the broadcaster can gift hype coins'::text;
    RETURN;
  END IF;

  -- 3. Verify stream is live
  IF (v_stream.status != 'live' AND v_stream.is_live != true) OR v_stream.ended_at IS NOT NULL THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, 0, 25, 0, 175, 'Stream is not live'::text;
    RETURN;
  END IF;

  -- 4. Verify viewer is not the broadcaster
  IF p_viewer_id = v_broadcaster_id THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, 0, 25, 0, 175, 'Cannot gift hype coins to yourself'::text;
    RETURN;
  END IF;

  -- 5. Lock viewer's profile to prevent concurrent awards
  SELECT hype_coins
  INTO v_existing_balance
  FROM public.user_profiles
  WHERE id = p_viewer_id
  FOR UPDATE;

  IF v_existing_balance IS NULL THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, 0, 25, 0, 175, 'Viewer not found'::text;
    RETURN;
  END IF;

  -- 6. Check daily cap (25 Hype Coins per day per viewer)
  SELECT COALESCE(SUM(amount), 0)::integer
  INTO v_daily_earned
  FROM public.hype_coin_ledger
  WHERE user_id = p_viewer_id
    AND action = 'hype_gift_received'
    AND created_at >= NOW()::date;

  v_remaining_allowance := 25 - v_daily_earned;

  IF v_remaining_allowance <= 0 THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, v_daily_earned, 25, 0, 175, 'Viewer daily hype cap reached'::text;
    RETURN;
  END IF;

  -- 7. Check weekly cap (175 Hype Coins per week per viewer)
  SELECT COALESCE(SUM(amount), 0)::integer
  INTO v_weekly_earned
  FROM public.hype_coin_ledger
  WHERE user_id = p_viewer_id
    AND action = 'hype_gift_received'
    AND created_at >= NOW() - interval '7 days';

  IF v_weekly_earned >= 175 THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, v_daily_earned, 25, v_weekly_earned, 175, 'Viewer weekly hype cap reached'::text;
    RETURN;
  END IF;

  -- 8. Check for duplicate gifts in same 5-minute window (per viewer)
  v_earning_window_start := to_timestamp(EXTRACT(EPOCH FROM NOW())::integer / 300 * 300);

  SELECT created_at
  INTO v_last_award_time
  FROM public.hype_coin_ledger
  WHERE user_id = p_viewer_id
    AND action = 'hype_gift_received'
    AND created_at >= v_earning_window_start
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_last_award_time IS NOT NULL THEN
    RETURN QUERY SELECT
      false, 0::bigint, 0, v_daily_earned, 25, v_weekly_earned, 175,
      'Hype coin already gifted to this viewer in the last 5 minutes'::text;
    RETURN;
  END IF;

  -- 9. Calculate actual awarded amount (respect daily cap)
  v_awarded_amount := LEAST(v_attempted_amount, v_remaining_allowance);

  -- 10. Credit awarded Hype Coins to viewer
  IF v_awarded_amount > 0 THEN
    UPDATE public.user_profiles
    SET hype_coins = hype_coins + v_awarded_amount
    WHERE id = p_viewer_id;
  END IF;

  -- 11. Insert ledger entry
  IF v_awarded_amount > 0 THEN
    INSERT INTO public.hype_coin_ledger (user_id, stream_id, broadcaster_id, amount, action, metadata)
    VALUES (p_viewer_id, p_stream_id, v_broadcaster_id, v_awarded_amount, 'hype_gift_received', jsonb_build_object(
      'stream_id', p_stream_id,
      'gifted_at', NOW(),
      'broadcaster_id', v_broadcaster_id,
      'awarded_amount', v_awarded_amount
    ));
  END IF;

  -- 12. Fetch updated balance
  SELECT user_profiles.hype_coins INTO v_current_viewer_hype
  FROM public.user_profiles
  WHERE id = p_viewer_id;

  -- 13. Return success
  IF v_awarded_amount > 0 THEN
    RETURN QUERY SELECT
      true,
      v_current_viewer_hype::bigint,
      v_awarded_amount,
      v_daily_earned + v_awarded_amount,
      25,
      v_weekly_earned + v_awarded_amount,
      175,
      'Hype Coin gifted to viewer'::text;
  ELSE
    RETURN QUERY SELECT
      false,
      v_current_viewer_hype::bigint,
      0,
      v_daily_earned,
      25,
      v_weekly_earned,
      175,
      'Viewer daily hype cap reached'::text;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.gift_hype_coin_to_viewer(uuid, uuid) TO authenticated;

COMMENT ON FUNCTION public.gift_hype_coin_to_viewer(uuid, uuid) IS 'RPC for broadcasters to gift 1 hype coin to a viewer. Enforces 5-min cooldown per viewer, daily (25) and weekly (175) caps. Row-level locking prevents race conditions.';

-- maitroll Level + Achievement Engine
-- Adds unified level reward engine, level reward metadata, inventory, achievement events,
-- and XP processing RPCs for automatic level reward granting.

-- 1. Ensure canonical profile balance fields exist
ALTER TABLE public.user_profiles
  ADD COLUMN IF NOT EXISTS level integer NOT NULL DEFAULT 1;

ALTER TABLE public.user_profiles
  ADD COLUMN IF NOT EXISTS xp integer NOT NULL DEFAULT 0;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'user_profiles_level_min' AND conrelid = 'public.user_profiles'::regclass
  ) THEN
    ALTER TABLE public.user_profiles
      ADD CONSTRAINT user_profiles_level_min CHECK (level >= 1);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'user_profiles_xp_nonnegative' AND conrelid = 'public.user_profiles'::regclass
  ) THEN
    ALTER TABLE public.user_profiles
      ADD CONSTRAINT user_profiles_xp_nonnegative CHECK (xp >= 0);
  END IF;
END $$;

-- Function: enable_payout_window
CREATE OR REPLACE FUNCTION public.enable_payout_window(
  p_duration_minutes INT DEFAULT 20,
  p_min_coins INT DEFAULT 5000,
  p_special_tier_usd NUMERIC DEFAULT 1.00
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_config JSONB;
  v_result JSONB;
BEGIN
  -- Get current config
  SELECT setting_value INTO v_config
  FROM public.admin_app_settings
  WHERE setting_key = 'payout_window_config'
  FOR UPDATE;

  IF v_config IS NULL THEN
    v_config := jsonb_build_object(
      'enabled', false,
      'min_coins', 5000,
      'special_tier_enabled', true,
      'special_tier_coins', 5000,
      'special_tier_usd', 1,
      'duration_minutes', 20,
      'notified_users', false
    );
  END IF;

  -- Update config with new window
  v_config := jsonb_set(v_config, '{enabled}', 'true');
  v_config := jsonb_set(v_config, '{enabled_at}', to_jsonb(now()));
  v_config := jsonb_set(v_config, '{duration_minutes}', to_jsonb(p_duration_minutes));
  v_config := jsonb_set(v_config, '{min_coins}', to_jsonb(p_min_coins));
  v_config := jsonb_set(v_config, '{special_tier_usd}', to_jsonb(p_special_tier_usd));
  v_config := jsonb_set(v_config, '{notified_users}', 'false');

  -- Save config
  UPDATE public.admin_app_settings
  SET setting_value = v_config,
      updated_at = now()
  WHERE setting_key = 'payout_window_config';

  -- Return success
  RETURN jsonb_build_object(
    'success', true,
    'enabled', true,
    'duration_minutes', p_duration_minutes,
    'min_coins', p_min_coins,
    'special_tier_coins', 5000,
    'special_tier_usd', p_special_tier_usd,
    'message', 'Payout window enabled for ' || p_duration_minutes || ' minutes'
  );
END;
$$;

-- Function: end_anonymous_round
CREATE OR REPLACE FUNCTION end_anonymous_round(p_show_id uuid)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_show_record record;
BEGIN
  SELECT * INTO v_show_record FROM auction_shows WHERE id = p_show_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'reason', 'Show not found');
  END IF;

  -- Check if user is the auctioneer or admin
  IF NOT EXISTS (
    SELECT 1 FROM auctioneer_profiles ap
    WHERE ap.id = v_show_record.auctioneer_id AND ap.user_id = auth.uid()
  ) AND NOT EXISTS (
    SELECT 1 FROM user_profiles WHERE id = auth.uid() AND (is_admin = true OR role = 'admin')
  ) THEN
    RETURN json_build_object('success', false, 'reason', 'Only the auctioneer or admin can end an anonymous round');
  END IF;

  UPDATE auction_shows SET
    is_anonymous_round_active = false,
    anonymous_round_ends_at = NULL,
    updated_at = now()
  WHERE id = p_show_id;

  RETURN json_build_object('success', true);
END;
$$;

-- Function: end_battle_guarded
CREATE OR REPLACE FUNCTION public.end_battle_guarded(
  p_battle_id UUID,
  p_min_duration_seconds INTEGER DEFAULT 180,
  p_sudden_death_seconds INTEGER DEFAULT 10
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_battle RECORD;
  v_required INTERVAL;
  v_winner_stream_id UUID;
  v_winner_user_id UUID;
  v_loser_user_id UUID;
BEGIN
  SELECT * INTO v_battle FROM public.battles WHERE id = p_battle_id FOR UPDATE;

  IF v_battle IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle not found');
  END IF;

  IF v_battle.status <> 'active' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle not active');
  END IF;

  IF v_battle.started_at IS NULL OR v_battle.started_at > now() THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle not started');
  END IF;

  v_required := make_interval(secs => p_min_duration_seconds + p_sudden_death_seconds - 10);

  IF now() < v_battle.started_at + v_required THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle timer not elapsed');
  END IF;

  IF v_battle.score_challenger > v_battle.score_opponent THEN
    v_winner_stream_id := v_battle.challenger_stream_id;
  ELSIF v_battle.score_opponent > v_battle.score_challenger THEN
    v_winner_stream_id := v_battle.opponent_stream_id;
  END IF;

  IF v_winner_stream_id IS NOT NULL THEN
    SELECT user_id INTO v_winner_user_id FROM public.streams WHERE id = v_winner_stream_id;

    IF v_winner_stream_id = v_battle.challenger_stream_id THEN
      SELECT user_id INTO v_loser_user_id FROM public.streams WHERE id = v_battle.opponent_stream_id;
    ELSE
      SELECT user_id INTO v_loser_user_id FROM public.streams WHERE id = v_battle.challenger_stream_id;
    END IF;
  END IF;

  UPDATE public.battles
  SET status = 'ended', ended_at = now(), winner_stream_id = v_winner_stream_id
  WHERE id = p_battle_id;

  IF v_winner_user_id IS NOT NULL THEN
    UPDATE public.user_profiles
    SET battle_wins = COALESCE(battle_wins, 0) + 1
    WHERE id = v_winner_user_id;

    PERFORM public.award_family_battle_points(v_winner_user_id, 1, p_battle_id, 'battle_won');
    PERFORM public.award_agency_battle_points(v_winner_user_id, 1, p_battle_id);
  END IF;

  IF v_loser_user_id IS NOT NULL THEN
    UPDATE public.user_profiles
    SET battle_losses = COALESCE(battle_losses, 0) + 1,
        battle_crown_streak = 0
    WHERE id = v_loser_user_id;

    PERFORM public.award_family_battle_points(v_loser_user_id, -10, p_battle_id, 'battle_lost');
    PERFORM public.award_agency_battle_points(v_loser_user_id, -10, p_battle_id);
  END IF;

  UPDATE public.streams
  SET battle_id = NULL, is_battle = false,
      battle_status = 'waiting', battle_mode = 'manual'
  WHERE battle_id = p_battle_id;

  DELETE FROM public.battle_participants WHERE battle_id = p_battle_id;
  DELETE FROM public.battle_queue WHERE battle_id = p_battle_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: end_smoke_event
CREATE OR REPLACE FUNCTION public.end_smoke_event(p_stream_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NOT public._smoke_check_admin_or_host(p_stream_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only admin or stream host can end a smoke event');
  END IF;

  UPDATE public.stream_smoke_events
  SET is_active = false, ended_at = now(), updated_at = now()
  WHERE stream_id = p_stream_id AND is_active = true;

  UPDATE public.stream_raffles
  SET status = 'completed', ended_at = now(), updated_at = now()
  WHERE stream_id = p_stream_id AND status = 'active';

  RETURN jsonb_build_object('success', true, 'message', 'Smoke Event ended');
END;
$$;

-- Function: end_stream
CREATE OR REPLACE FUNCTION public.end_stream(p_stream_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_stream_owner UUID;
    v_battle_id UUID;
    v_is_admin BOOLEAN := FALSE;
BEGIN
    -- Check ownership
    SELECT user_id, battle_id INTO v_stream_owner, v_battle_id
    FROM public.streams
    WHERE id = p_stream_id;

    IF v_stream_owner IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Stream not found');
    END IF;

    -- Check if user is admin
    SELECT (role = 'admin' OR is_admin = true) INTO v_is_admin
    FROM public.user_profiles 
    WHERE id = auth.uid();

    -- BATTLE PROTECTION: Prevent ending streams that are in active battles
    IF v_battle_id IS NOT NULL THEN
        -- Check if battle is still active
        IF EXISTS (
            SELECT 1 FROM public.battles 
            WHERE id = v_battle_id 
            AND status IN ('pending', 'active')
        ) THEN
            -- Log the attempt
            INSERT INTO public.audit_logs (action, user_id, metadata)
            VALUES (
                'end_stream_blocked_battle',
                auth.uid(),
                jsonb_build_object(
                    'stream_id', p_stream_id,
                    'battle_id', v_battle_id,
                    'reason', 'Stream is in active battle'
                )
            );
            
            RETURN jsonb_build_object(
                'success', false, 
                'message', 'Cannot end stream during active battle. End the battle first.',
                'battle_id', v_battle_id
            );
        END IF;
    END IF;

    -- Allow owner or admin
    IF v_stream_owner != auth.uid() AND NOT v_is_admin THEN
        -- Log unauthorized attempt
        INSERT INTO public.audit_logs (action, user_id, metadata)
        VALUES (
            'end_stream_unauthorized',
            auth.uid(),
            jsonb_build_object(
                'stream_id', p_stream_id,
                'stream_owner', v_stream_owner
            )
        );
        
        RETURN jsonb_build_object('success', false, 'message', 'Not authorized');
    END IF;

    -- Log the stream end
    INSERT INTO public.audit_logs (action, user_id, metadata)
    VALUES (
        'end_stream',
        auth.uid(),
        jsonb_build_object(
            'stream_id', p_stream_id,
            'stream_owner', v_stream_owner,
            'ended_by_admin', v_is_admin
        )
    );

    -- Update stream
    UPDATE public.streams
    SET 
        status = 'ended',
        is_live = false,
        ended_at = NOW()
    WHERE id = p_stream_id;

    -- Clean up viewers
    DELETE FROM public.stream_viewers WHERE stream_id = p_stream_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: ensure_league_system_ready
CREATE OR REPLACE FUNCTION public.ensure_league_system_ready()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_event public.league_events%ROWTYPE;
BEGIN
  PERFORM public.close_expired_league_events();

  SELECT
      id,
      name,
      slug,
      type,
      status,
      starts_at,
      ends_at,
      created_by,
      theme_key,
      points_multiplier,
      CASE WHEN pg_typeof(metadata)::text = 'text' THEN to_jsonb(metadata) ELSE metadata END AS metadata,
      created_at,
      updated_at
  INTO v_event
  FROM public.league_events
  WHERE status = 'active'
    AND now() BETWEEN starts_at AND ends_at
  ORDER BY starts_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    SELECT
        id,
        name,
        slug,
        type,
        status,
        starts_at,
        ends_at,
        created_by,
        theme_key,
        points_multiplier,
        CASE WHEN pg_typeof(metadata)::text = 'text' THEN to_jsonb(metadata) ELSE metadata END AS metadata,
        created_at,
        updated_at
    INTO v_event
    FROM public.create_system_league_event();
  END IF;

  IF v_event.id IS NOT NULL THEN
    PERFORM public.refresh_league_leaderboard(v_event.id);
  END IF;
  RETURN to_jsonb(v_event);
END;
$$;

-- Function: enter_giveaway
CREATE OR REPLACE FUNCTION public.enter_giveaway(
    p_user_id UUID,
    p_giveaway_id UUID,
    p_use_free_entry BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_giveaway RECORD;
    v_entry RECORD;
    v_balance INTEGER;
    v_cost INTEGER;
    v_existing_free_entry BOOLEAN;
    v_total_entries INTEGER;
BEGIN
    -- Get giveaway details
    SELECT * INTO v_giveaway 
    FROM public.giveaways 
    WHERE id = p_giveaway_id AND is_active = true AND ends_at > NOW();
    
    IF v_giveaway IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Giveaway not found or has ended');
    END IF;
    
    -- Check for existing free entry
    IF p_use_free_entry THEN
        SELECT EXISTS(
            SELECT 1 FROM public.giveaway_entries 
            WHERE giveaway_id = p_giveaway_id AND user_id = p_user_id AND is_free_entry = true
        ) INTO v_existing_free_entry;
        
        IF v_existing_free_entry THEN
            RETURN jsonb_build_object('success', false, 'error', 'You have already used your free entry');
        END IF;
    END IF;
    
    -- Calculate cost
    IF p_use_free_entry THEN
        v_cost := 0;
    ELSE
        v_cost := v_giveaway.entry_cost;
    END IF;
    
    -- Check user balance (server-side validation)
    IF v_cost > 0 THEN
        SELECT coins INTO v_balance FROM public.user_profiles WHERE id = p_user_id;
        
        IF v_balance IS NULL OR v_balance < v_cost THEN
            RETURN jsonb_build_object('success', false, 'error', 'Insufficient Trollz balance');
        END IF;
        
        -- Deduct Trollz
        UPDATE public.user_profiles 
        SET coins = coins - v_cost 
        WHERE id = p_user_id;
    END IF;
    
    -- Check for existing entry (merge entries)
    SELECT * INTO v_entry 
    FROM public.giveaway_entries 
    WHERE giveaway_id = p_giveaway_id AND user_id = p_user_id AND is_free_entry = false;
    
    IF v_entry IS NOT NULL THEN
        -- Add to existing entry
        UPDATE public.giveaway_entries 
        SET entries_count = entries_count + 1 
        WHERE id = v_entry.id;
    ELSE
        -- Create new entry
        INSERT INTO public.giveaway_entries (giveaway_id, user_id, entries_count, is_free_entry)
        VALUES (p_giveaway_id, p_user_id, 1, p_use_free_entry);
    END IF;
    
    -- Get total entries for response
    SELECT SUM(entries_count) INTO v_total_entries
    FROM public.giveaway_entries
    WHERE giveaway_id = p_giveaway_id AND user_id = p_user_id;
    
    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Entry added successfully',
        'entries', v_total_entries,
        'cost', v_cost
    );
END;
$$;

-- Function: escalate_to_troll_court
CREATE OR REPLACE FUNCTION escalate_to_troll_court(
  p_order_id uuid,
  p_plaintiff_id uuid,
  p_defendant_id uuid,
  p_description text,
  p_claim_amount bigint DEFAULT 0
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_order marketplace_purchases%ROWTYPE;
  v_case_id uuid;
  v_appeal_id uuid;
BEGIN
  -- Get the order
  SELECT * INTO v_order FROM marketplace_purchases WHERE id = p_order_id;
  
  IF v_order IS NULL THEN
    RAISE EXCEPTION 'Order not found';
  END IF;
  
  -- Get existing appeal if any
  SELECT appeal_id INTO v_appeal_id FROM marketplace_purchases WHERE id = p_order_id;
  
  -- Create Troll Court case
  INSERT INTO troll_court_cases (
    plaintiff_id,
    defendant_id,
    case_type,
    description,
    claim_amount,
    status,
    related_order_id
  )
  VALUES (
    p_plaintiff_id,
    p_defendant_id,
    'civil',
    p_description,
    p_claim_amount,
    'pending',
    p_order_id
  )
  RETURNING id INTO v_case_id;
  
  -- Link case to order
  UPDATE marketplace_purchases
  SET troll_court_case_id = v_case_id,
      fulfillment_status = 'lawsuit_filed',
      updated_at = now()
  WHERE id = p_order_id;
  
  -- If appeal exists, update its status to escalated
  IF v_appeal_id IS NOT NULL THEN
    UPDATE transaction_appeals
    SET status = 'escalated',
        updated_at = now()
    WHERE id = v_appeal_id;
  END IF;
  
  RETURN v_case_id;
END;
$$;

-- Function: evaluate_seller_tier
CREATE OR REPLACE FUNCTION public.evaluate_seller_tier(p_seller_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_seller RECORD;
    v_old_tier TEXT;
    v_new_tier TEXT;
    v_upgraded BOOLEAN := false;
    v_downgraded BOOLEAN := false;
BEGIN
    -- Get current seller data
    SELECT * INTO v_seller 
    FROM public.user_profiles 
    WHERE id = p_seller_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Seller not found');
    END IF;
    
    v_old_tier := COALESCE(v_seller.seller_tier, 'standard');
    v_new_tier := v_old_tier;
    
    -- DOWNGRADE RULES (take priority)
    IF v_seller.fraud_flags > 1 THEN
        v_new_tier := 'standard';
        v_downgraded := true;
    ELSIF v_seller.dispute_count >= 5 THEN
        -- Excessive disputes - downgrade
        IF v_seller.seller_tier IN ('enterprise', 'merchant') THEN
            v_new_tier := 'verified_pro';
            v_downgraded := true;
        ELSIF v_seller.seller_tier = 'verified_pro' THEN
            v_new_tier := 'verified';
            v_downgraded := true;
        END IF;
    ELSE
        -- UPGRADE LOGIC (only if no fraud flags and good standing)
        IF v_seller.completed_sales >= 500 AND v_seller.fraud_flags = 0 THEN
            v_new_tier := 'enterprise';
        ELSIF v_seller.completed_sales >= 100 AND v_seller.fraud_flags = 0 THEN
            v_new_tier := 'merchant';
        ELSIF v_seller.completed_sales >= 20 AND v_seller.fraud_flags = 0 AND v_seller.dispute_count < 3 THEN
            v_new_tier := 'verified_pro';
        ELSIF v_seller.completed_sales >= 20 AND v_seller.fraud_flags <= 1 THEN
            v_new_tier := 'verified';
        ELSE
            v_new_tier := 'standard';
        END IF;
        
        -- Only upgrade if new tier is higher
        IF v_new_tier > v_old_tier THEN
            v_upgraded := true;
        ELSE
            v_new_tier := v_old_tier;
        END IF;
    END IF;
    
    -- Update seller tier
    UPDATE public.user_profiles
    SET seller_tier = v_new_tier,
        tier_updated_at = NOW()
    WHERE id = p_seller_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'seller_id', p_seller_id,
        'old_tier', v_old_tier,
        'new_tier', v_new_tier,
        'upgraded', v_upgraded,
        'downgraded', v_downgraded,
        'completed_sales', v_seller.completed_sales,
        'fraud_flags', v_seller.fraud_flags,
        'dispute_count', v_seller.dispute_count
    );
END;
$$;

-- Function: evict_tenant
CREATE OR REPLACE FUNCTION evict_tenant(p_lease_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_lease RECORD;
  v_property RECORD;
  v_is_owner BOOLEAN := false;
  v_is_admin BOOLEAN := false;
BEGIN
  -- Get lease - first check if lease exists at all
  SELECT * INTO v_lease FROM public.leases WHERE id = p_lease_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lease not found. The lease ID does not exist.');
  END IF;
  
  -- Check if lease is active
  IF v_lease.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lease is not active. Current status: ' || v_lease.status || '. Rent can only be collected from active leases.');
  END IF;

  -- Get property and verify caller is the landlord
  SELECT * INTO v_property FROM public.properties WHERE id = v_lease.property_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Property not found for this lease');
  END IF;
  IF v_property.owner_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Property has no owner. Cannot collect rent.');
  END IF;
  IF v_property.owner_id != v_landlord_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'You are not the owner of this property. Owner ID: ' || v_property.owner_id || ', Your ID: ' || v_landlord_id);
  END IF;

  -- Get property
  SELECT * INTO v_property FROM public.properties WHERE id = v_lease.property_id;

  -- Check if caller is property owner or admin
  v_is_owner := (v_property.owner_id = auth.uid());
  SELECT is_admin OR role = 'admin' INTO v_is_admin FROM public.user_profiles WHERE id = auth.uid();

  IF NOT (v_is_owner OR v_is_admin) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only the property owner or admin can evict tenants');
  END IF;

  -- Check for active court case tied to this lease (prevent unauthorized eviction)
  -- If there IS a court case, eviction is allowed as part of court ruling
  -- If there is NO court case and no overdue rent, eviction is blocked
  IF NOT v_is_admin THEN
    -- Non-admin landlords can only evict if rent is overdue by 7+ days
    IF v_lease.last_rent_paid_at > NOW() - INTERVAL '7 days' THEN
      RETURN jsonb_build_object('success', false, 'error', 'Cannot evict: rent is not overdue. File a court case for other violations.');
    END IF;
  END IF;

  -- Evict: end lease
  UPDATE public.leases SET status = 'evicted' WHERE id = p_lease_id;

  -- Update tenant housing status
  UPDATE public.user_profiles SET housing_status = 'homeless', home_type = NULL WHERE id = v_lease.tenant_id;

  -- Make property available again
  UPDATE public.properties SET is_for_rent = true WHERE id = v_lease.property_id;

  -- Log the eviction
  INSERT INTO public.coin_transactions (user_id, type, amount, description, created_at)
    VALUES (v_lease.tenant_id, 'eviction', 0, 'Evicted from property ' || v_property.name, NOW());

  RETURN jsonb_build_object('success', true, 'message', 'Tenant evicted successfully');
END;
$$;

-- Function: execute_buy_order
CREATE OR REPLACE FUNCTION public.execute_buy_order(
    p_user_id UUID,
    p_stock_id UUID,
    p_coins DECIMAL(20,2),
    p_stock_symbol VARCHAR
)
RETURNS TABLE(
    success BOOLEAN,
    message TEXT,
    shares_purchased DECIMAL(20,8),
    price_per_share DECIMAL(15,2),
    total_spent DECIMAL(20,2),
    coins_remaining DECIMAL(20,2)
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_current_price DECIMAL(15,2);
    v_shares DECIMAL(20,8);
    v_total_spent DECIMAL(20,2);
    v_user_coins DECIMAL(20,2);
    v_portfolio_id UUID;
    v_avg_price DECIMAL(15,2);
    v_existing_shares DECIMAL(20,8);
    v_existing_invested DECIMAL(20,2);
    v_total_shares DECIMAL(20,8);
    v_market_cap DECIMAL(20,2);
    v_ownership_pct DECIMAL(10,2);
    v_fee_amount DECIMAL(20,2);
    v_buy_spread DECIMAL(10,4) := 1.02;
BEGIN
    -- Validate inputs
    IF p_user_id IS NULL OR p_stock_id IS NULL OR p_coins IS NULL OR p_coins <= 0 THEN
        RETURN QUERY SELECT FALSE, 'Invalid input parameters', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2);
        RETURN;
    END IF;

    -- Lock the stock row to prevent race conditions
    SELECT current_price INTO v_current_price
    FROM public.stocks
    WHERE id = p_stock_id AND is_active = TRUE
    FOR UPDATE;

    IF v_current_price IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Stock not found or inactive', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2);
        RETURN;
    END IF;

    v_current_price := v_current_price * v_buy_spread;

    -- Lock the user profile row
    SELECT troll_coins INTO v_user_coins
    FROM public.user_profiles
    WHERE id = p_user_id
    FOR UPDATE;

    IF v_user_coins IS NULL THEN
        RETURN QUERY SELECT FALSE, 'User profile not found', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2);
        RETURN;
    END IF;

    v_fee_amount := p_coins * 0.02;
    v_total_spent := p_coins + v_fee_amount;

    IF v_user_coins < v_total_spent THEN
        RETURN QUERY SELECT FALSE, 'Insufficient coins (fee included)', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), v_user_coins;
        RETURN;
    END IF;

    -- Guard against division by zero
    IF v_current_price <= 0 THEN
        RETURN QUERY SELECT FALSE, 'Invalid stock price', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), v_user_coins;
        RETURN;
    END IF;

    v_shares := p_coins / v_current_price;

    -- Check ownership limit
    SELECT COALESCE(SUM(up.shares), 0) INTO v_total_shares
    FROM public.user_portfolio up
    JOIN public.stocks s ON s.id = up.stock_id
    WHERE up.user_id = p_user_id AND s.stock_symbol = p_stock_symbol;

    SELECT market_cap INTO v_market_cap FROM public.stocks WHERE id = p_stock_id;

    IF v_market_cap > 0 AND v_current_price > 0 THEN
        v_ownership_pct := (v_total_shares / (v_market_cap / v_current_price)) * 100;
        IF v_ownership_pct >= 10 THEN
            RETURN QUERY SELECT FALSE, 'Maximum ownership limit reached (10%)', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), v_user_coins;
            RETURN;
        END IF;
    END IF;

    -- Deduct coins
    UPDATE public.user_profiles SET troll_coins = troll_coins - v_total_spent WHERE id = p_user_id;

    -- Update or insert portfolio
    SELECT id, shares, total_invested INTO v_portfolio_id, v_existing_shares, v_existing_invested
    FROM public.user_portfolio WHERE user_id = p_user_id AND stock_id = p_stock_id;

    IF v_portfolio_id IS NOT NULL THEN
        v_avg_price := (v_existing_invested + v_total_spent) / NULLIF(v_existing_shares + v_shares, 0);
        UPDATE public.user_portfolio SET
            shares = shares + v_shares,
            avg_price = v_avg_price,
            total_invested = total_invested + v_total_spent,
            updated_at = NOW()
        WHERE id = v_portfolio_id;
    ELSE
        INSERT INTO public.user_portfolio (user_id, stock_id, shares, avg_price, total_invested)
        VALUES (p_user_id, p_stock_id, v_shares, v_current_price, v_total_spent);
    END IF;

    -- Record transaction
    INSERT INTO public.stock_transactions (user_id, stock_id, transaction_type, shares, price_per_share, total_amount, coins_before, coins_after)
    VALUES (p_user_id, p_stock_id, 'buy', v_shares, v_current_price, v_total_spent, v_user_coins, v_user_coins - v_total_spent);

    -- Update volume
    UPDATE public.stocks SET volume = volume + 1 WHERE id = p_stock_id;

    RETURN QUERY SELECT TRUE, 'Purchase successful (2% fee)', v_shares, v_current_price, v_total_spent, v_user_coins - v_total_spent;
END;
$$;

-- Function: execute_sell_order
CREATE OR REPLACE FUNCTION public.execute_sell_order(
    p_user_id UUID,
    p_stock_id UUID,
    p_shares DECIMAL(20,8)
)
RETURNS TABLE(
    success BOOLEAN,
    message TEXT,
    shares_sold DECIMAL(20,8),
    price_per_share DECIMAL(15,2),
    total_received DECIMAL(20,2),
    profit_loss DECIMAL(20,2),
    coins_remaining DECIMAL(20,2)
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_current_price DECIMAL(15,2);
    v_total_received DECIMAL(20,2);
    v_user_coins DECIMAL(20,2);
    v_portfolio_id UUID;
    v_existing_shares DECIMAL(20,8);
    v_avg_price DECIMAL(15,2);
    v_existing_invested DECIMAL(20,2);
    v_profit_loss DECIMAL(20,2);
    v_fee_amount DECIMAL(20,2);
    v_sell_spread DECIMAL(10,4) := 0.98;
BEGIN
    -- Validate inputs
    IF p_user_id IS NULL OR p_stock_id IS NULL OR p_shares IS NULL OR p_shares <= 0 THEN
        RETURN QUERY SELECT FALSE, 'Invalid input parameters', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2);
        RETURN;
    END IF;

    -- Lock stock row
    SELECT current_price INTO v_current_price
    FROM public.stocks
    WHERE id = p_stock_id AND is_active = TRUE
    FOR UPDATE;

    IF v_current_price IS NULL THEN
        RETURN QUERY SELECT FALSE, 'Stock not found or inactive', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2);
        RETURN;
    END IF;

    v_current_price := v_current_price * v_sell_spread;

    -- Get portfolio with lock
    SELECT id, shares, avg_price, total_invested
    INTO v_portfolio_id, v_existing_shares, v_avg_price, v_existing_invested
    FROM public.user_portfolio
    WHERE user_id = p_user_id AND stock_id = p_stock_id
    FOR UPDATE;

    IF v_portfolio_id IS NULL OR v_existing_shares < p_shares THEN
        SELECT troll_coins INTO v_user_coins FROM public.user_profiles WHERE id = p_user_id;
        RETURN QUERY SELECT FALSE, 'Insufficient shares', 0::DECIMAL(20,8), 0::DECIMAL(15,2), 0::DECIMAL(20,2), 0::DECIMAL(20,2), COALESCE(v_user_coins, 0);
        RETURN;
    END IF;

    v_total_received := p_shares * v_current_price;
    v_profit_loss := v_total_received - (p_shares * v_avg_price);
    v_fee_amount := v_total_received * 0.02;
    v_total_received := v_total_received - v_fee_amount;

    -- Get current coins
    SELECT troll_coins INTO v_user_coins FROM public.user_profiles WHERE id = p_user_id;

    -- Add coins to user
    UPDATE public.user_profiles SET troll_coins = troll_coins + v_total_received WHERE id = p_user_id;

    -- Update or delete portfolio
    IF v_existing_shares = p_shares THEN
        DELETE FROM public.user_portfolio WHERE id = v_portfolio_id;
    ELSE
        UPDATE public.user_portfolio SET
            shares = shares - p_shares,
            total_invested = total_invested - (p_shares * v_avg_price),
            updated_at = NOW()
        WHERE id = v_portfolio_id;
    END IF;

    -- Record transaction
    INSERT INTO public.stock_transactions (user_id, stock_id, transaction_type, shares, price_per_share, total_amount, coins_before, coins_after, profit_loss)
    VALUES (p_user_id, p_stock_id, 'sell', p_shares, v_current_price, v_total_received, v_user_coins, v_user_coins + v_total_received, v_profit_loss - v_fee_amount);

    -- Update volume
    UPDATE public.stocks SET volume = volume + 1 WHERE id = p_stock_id;

    RETURN QUERY SELECT TRUE, 'Sale successful (2% fee)', p_shares, v_current_price, v_total_received, v_profit_loss - v_fee_amount, v_user_coins + v_total_received;
END;
$$;

-- Function: extend_court_date
CREATE OR REPLACE FUNCTION public.extend_court_date(p_case_id uuid, p_new_date date)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_old_docket_id uuid;
  v_new_docket_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_court_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Only court staff can extend court cases';
  END IF;

  IF p_new_date IS NULL THEN
    RAISE EXCEPTION 'New court date is required';
  END IF;

  SELECT docket_id INTO v_old_docket_id
  FROM public.court_cases
  WHERE id = p_case_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Case not found');
  END IF;

  SELECT id INTO v_new_docket_id
  FROM public.court_dockets
  WHERE court_date = p_new_date
  LIMIT 1;

  IF v_new_docket_id IS NULL THEN
    INSERT INTO public.court_dockets (court_date, status, max_cases, cases_count, created_by, updated_at)
    VALUES (p_new_date, 'open', 20, 0, auth.uid(), now())
    RETURNING id INTO v_new_docket_id;
  END IF;

  UPDATE public.court_cases
  SET docket_id = v_new_docket_id,
      updated_at = now()
  WHERE id = p_case_id;

  IF v_old_docket_id IS NOT NULL AND v_old_docket_id <> v_new_docket_id THEN
    UPDATE public.court_dockets
    SET cases_count = GREATEST(COALESCE(cases_count, 1) - 1, 0),
        updated_at = now()
    WHERE id = v_old_docket_id;
  END IF;

  UPDATE public.court_dockets
  SET cases_count = COALESCE(cases_count, 0) + CASE WHEN v_old_docket_id IS DISTINCT FROM v_new_docket_id THEN 1 ELSE 0 END,
      updated_at = now()
  WHERE id = v_new_docket_id;

  RETURN jsonb_build_object(
    'success', true,
    'case_id', p_case_id,
    'court_date', p_new_date,
    'docket_id', v_new_docket_id
  );
END;
$$;

-- Function: file_civil_lawsuit
CREATE OR REPLACE FUNCTION file_civil_lawsuit(
  p_defendant_id UUID,
  p_category TEXT,
  p_description TEXT,
  p_evidence_url TEXT,
  p_claim_amount INTEGER
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $func$
DECLARE
  v_case_id UUID;
BEGIN
  INSERT INTO troll_court_cases (
    plaintiff_id,
    defendant_id,
    category,
    accusation, -- mapping description to accusation
    evidence_url,
    claim_amount,
    status,
    created_at
  ) VALUES (
    auth.uid(),
    p_defendant_id,
    p_category,
    p_description,
    p_evidence_url,
    p_claim_amount,
    'pending',
    NOW()
  ) RETURNING id INTO v_case_id;

  RETURN jsonb_build_object('success', true, 'case_id', v_case_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$func$;

-- 5. Vehicle auction bids table
CREATE TABLE IF NOT EXISTS vehicle_auction_bids (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id UUID NOT NULL REFERENCES vehicle_listings(id) ON DELETE CASCADE,
  bidder_id UUID NOT NULL REFERENCES user_profiles(id),
  bid_amount INTEGER NOT NULL CHECK (bid_amount >= 0),
  created_at TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE vehicle_auction_bids ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  CREATE POLICY "Users can view bids they are involved in" ON vehicle_auction_bids
  FOR SELECT USING (
    auth.uid() = bidder_id
    OR auth.uid() IN (SELECT seller_id FROM vehicle_listings WHERE id = listing_id)
  );
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- Function: file_impeachment_case
CREATE OR REPLACE FUNCTION public.file_impeachment_case(
    p_president_id uuid,
    p_reason text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_docket_id uuid;
    v_case_id uuid;
    v_is_president boolean;
BEGIN
    -- Verify target is actually president
    SELECT EXISTS (
        SELECT 1 FROM public.user_role_grants 
        WHERE user_id = p_president_id AND role = 'president'
    ) INTO v_is_president;

    IF NOT v_is_president THEN
        RAISE EXCEPTION 'Target user is not the President.';
    END IF;

    -- Get or Create Docket for today (using existing logic pattern)
    SELECT id INTO v_docket_id
    FROM public.court_dockets
    WHERE court_date = CURRENT_DATE;

    IF v_docket_id IS NULL THEN
        INSERT INTO public.court_dockets (court_date, status)
        VALUES (CURRENT_DATE, 'open')
        RETURNING id INTO v_docket_id;
    END IF;

    -- Insert Case
    INSERT INTO public.court_cases (
        docket_id,
        defendant_id,
        plaintiff_id, -- The filer (caller)
        reason,
        status,
        incident_date,
        case_type
    )
    VALUES (
        v_docket_id,
        p_president_id,
        auth.uid(),
        p_reason,
        'pending',
        NOW(),
        'president_impeachment'
    )
    RETURNING id INTO v_case_id;

    -- Log it
    INSERT INTO public.president_audit_logs (
        action_type,
        actor_id,
        target_id,
        details
    ) VALUES (
        'impeachment_filed',
        auth.uid(),
        p_president_id,
        jsonb_build_object('case_id', v_case_id, 'reason', p_reason)
    );

    RETURN v_case_id;
END;
$$;

-- Function: finalize_president_election
CREATE OR REPLACE FUNCTION public.finalize_president_election(p_election_id uuid)
RETURNS void
SECURITY DEFINER
LANGUAGE plpgsql
AS $$
DECLARE
  v_winner_id UUID;
  v_role_id UUID;
  v_candidate_count INT;
BEGIN
  -- Check permission (Admin/Secretary)
  if not exists (select 1 from user_profiles where id = auth.uid() and (is_admin = true or role = 'secretary')) then
     raise exception 'Not authorized';
  end if;

  -- Get role ID
  SELECT id INTO v_role_id FROM system_roles WHERE name = 'president';
  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'President role not found';
  END IF;

  -- Count approved candidates
  SELECT COUNT(*) INTO v_candidate_count
  FROM president_candidates 
  WHERE election_id = p_election_id AND status = 'approved';

  -- If no candidates, create a placeholder president (don't void)
  IF v_candidate_count = 0 THEN
    -- Find any candidate (pending or rejected) to appoint
    SELECT user_id INTO v_winner_id
    FROM president_candidates
    WHERE election_id = p_election_id
    ORDER BY created_at ASC
    LIMIT 1;

    -- If still no candidates, election can't proceed
    IF v_winner_id IS NULL THEN
      UPDATE president_elections SET status = 'void' WHERE id = p_election_id;
      RETURN;
    END IF;
  ELSE
    -- Get winner with MOST votes (even if 0 - don't void!)
    SELECT user_id INTO v_winner_id
    FROM president_candidates
    WHERE election_id = p_election_id AND status = 'approved'
    ORDER BY vote_count DESC, created_at ASC
    LIMIT 1;
  END IF;

  -- Expire old president(s)
  UPDATE user_role_grants
  SET expires_at = NOW()
  WHERE role_id = v_role_id 
    AND (expires_at IS NULL OR expires_at > NOW());

  -- Remove existing president badge from all users
  UPDATE user_profiles SET badge = NULL WHERE badge = 'president';

  -- Grant new president role (14 day term)
  INSERT INTO user_role_grants (user_id, role_id, expires_at)
  VALUES (v_winner_id, v_role_id, NOW() + INTERVAL '14 days');

  -- Award Badge and Gold Style
  UPDATE user_profiles
  SET badge = 'president', username_style = 'gold'
  WHERE id = v_winner_id;

  -- Update election status to finalized
  UPDATE president_elections 
  SET status = 'finalized', 
      winner_candidate_id = (SELECT id FROM president_candidates WHERE election_id = p_election_id AND user_id = v_winner_id LIMIT 1),
      updated_at = NOW()
  WHERE id = p_election_id;

  -- Log
  INSERT INTO president_audit_logs (action_type, description, actor_id)
  VALUES ('election_finalized', 'Election finalized. Winner: ' || v_winner_id, auth.uid());
END;
$$;

-- Function: find_5v5_match
CREATE OR REPLACE FUNCTION public.find_5v5_match(p_stream_id TEXT)
RETURNS TABLE (
  id TEXT,
  user_id UUID,
  title TEXT,
  category TEXT,
  current_viewers INTEGER
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_stream RECORD;
BEGIN
  SELECT s.user_id, s.category INTO v_stream
  FROM public.streams s
  WHERE s.id::text = p_stream_id AND s.is_live = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Stream not found or not live';
  END IF;

  IF v_stream.category != 'general' THEN
    RAISE EXCEPTION '5v5 battles are only available in General Chat category';
  END IF;

  RETURN QUERY
  SELECT s.id::text, s.user_id, s.title, s.category, s.current_viewers
  FROM public.streams s
  WHERE s.is_live = true
    AND s.category = 'general'
    AND s.id::text != p_stream_id
    AND s.user_id != v_stream.user_id
    AND NOT EXISTS (
      SELECT 1 FROM public.battle_sessions bs
      WHERE (bs.stream_id::text = s.id::text OR bs.opponent_stream_id::text = s.id::text)
        AND bs.status IN ('pending', 'active')
    )
  ORDER BY RANDOM()
  LIMIT 1;
END;
$$;

-- Function: find_match_candidate
CREATE OR REPLACE FUNCTION find_match_candidate(
    p_stream_id UUID
)
RETURNS TABLE (
    id UUID,
    user_id UUID,
    title TEXT,
    viewer_count INTEGER
) 
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_recent_opponent_ids UUID[];
    v_busy_stream_ids UUID[];
    v_my_kind TEXT;
    v_my_user_id UUID;
BEGIN
    -- Get kind and user_id of requester
    SELECT stream_kind, s.user_id INTO v_my_kind, v_my_user_id
    FROM streams s WHERE s.id = p_stream_id;

    -- 1. Get IDs of recent opponents (last 10 battles involving p_stream_id)
    SELECT ARRAY_AGG(
        CASE 
            WHEN challenger_stream_id = p_stream_id THEN opponent_stream_id
            ELSE challenger_stream_id
        END
    )
    INTO v_recent_opponent_ids
    FROM (
        SELECT challenger_stream_id, opponent_stream_id
        FROM battles
        WHERE (challenger_stream_id = p_stream_id OR opponent_stream_id = p_stream_id)
        AND status IN ('ended', 'active')
        ORDER BY created_at DESC
        LIMIT 10
    ) recent;

    -- 2. Get IDs of streams currently in a pending or active battle (busy)
    SELECT ARRAY_AGG(
        CASE 
            WHEN challenger_stream_id = p_stream_id THEN opponent_stream_id -- Should not happen if we filter p_stream_id
            WHEN opponent_stream_id = p_stream_id THEN challenger_stream_id -- Should not happen
            ELSE 
                CASE 
                    WHEN challenger_stream_id IS NOT NULL THEN challenger_stream_id
                    ELSE opponent_stream_id
                END
        END
    )
    INTO v_busy_stream_ids
    FROM battles
    WHERE status IN ('pending', 'active');

    -- 3. Return a random stream meeting criteria
    -- If Trollmers stream, only match with other Trollmers streams and eligible users
    IF COALESCE(v_my_kind, 'regular') = 'trollmers' THEN
        RETURN QUERY
        SELECT s.id::UUID, s.user_id::UUID, s.title::TEXT, s.viewer_count::INTEGER
        FROM streams s
        WHERE s.is_live = TRUE
          AND s.is_battle = FALSE
          AND COALESCE(s.stream_kind, 'regular') = 'trollmers'
          AND s.id != p_stream_id
          AND (v_recent_opponent_ids IS NULL OR NOT (s.id = ANY(v_recent_opponent_ids)))
          AND (v_busy_stream_ids IS NULL OR NOT (s.id = ANY(v_busy_stream_ids)))
          AND public.is_trollmers_eligible(s.user_id) = true
        ORDER BY RANDOM()
        LIMIT 1;
    ELSE
        -- Standard matching (unchanged)
        RETURN QUERY
        SELECT s.id::UUID, s.user_id::UUID, s.title::TEXT, s.viewer_count::INTEGER
        FROM streams s
        WHERE s.is_live = TRUE
          AND s.is_battle = FALSE
          AND s.id != p_stream_id
          AND (v_recent_opponent_ids IS NULL OR NOT (s.id = ANY(v_recent_opponent_ids)))
          AND (v_busy_stream_ids IS NULL OR NOT (s.id = ANY(v_busy_stream_ids)))
        ORDER BY RANDOM()
        LIMIT 1;
    END IF;
END;
$$;

-- Function: find_random_battle_match
CREATE OR REPLACE FUNCTION public.find_random_battle_match(
  p_stream_id uuid,
  p_broadcaster_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_self public.streams%ROWTYPE;
  v_opponent public.streams%ROWTYPE;
  v_battle_id uuid;
  v_started_at timestamptz := now() + interval '10 seconds';
  v_ends_at timestamptz := now() + interval '3 minutes 10 seconds';
BEGIN
  SELECT *
    INTO v_self
  FROM public.streams
  WHERE id = p_stream_id
    AND user_id = p_broadcaster_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('matched', false, 'message', 'Stream not found');
  END IF;

  IF v_self.category <> 'general'
    OR v_self.status <> 'live'
    OR COALESCE(v_self.random_battle_queue_enabled, false) = false
    OR COALESCE(v_self.is_battle, false) = true
    OR v_self.battle_id IS NOT NULL
    OR (v_self.random_battle_cooldown_until IS NOT NULL AND v_self.random_battle_cooldown_until > now())
  THEN
    RETURN jsonb_build_object('matched', false, 'message', 'Stream not eligible');
  END IF;

  SELECT *
    INTO v_opponent
  FROM public.streams
  WHERE id <> p_stream_id
    AND category = 'general'
    AND status = 'live'
    AND COALESCE(random_battle_queue_enabled, false) = true
    AND COALESCE(is_battle, false) = false
    AND battle_id IS NULL
    AND user_id <> p_broadcaster_id
    AND (random_battle_cooldown_until IS NULL OR random_battle_cooldown_until <= now())
  ORDER BY random_battle_queued_at NULLS FIRST, started_at NULLS LAST, created_at
  LIMIT 1
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    UPDATE public.streams
    SET random_battle_queue_enabled = true,
        random_battle_queued_at = COALESCE(random_battle_queued_at, now())
    WHERE id = p_stream_id;

    RETURN jsonb_build_object('matched', false, 'message', 'No opponent available');
  END IF;

  INSERT INTO public.battles (
    challenger_stream_id,
    opponent_stream_id,
    status,
    started_at,
    ends_at,
    score_challenger,
    score_opponent
  )
  VALUES (
    p_stream_id,
    v_opponent.id,
    'active',
    v_started_at,
    v_ends_at,
    0,
    0
  )
  RETURNING id INTO v_battle_id;

  INSERT INTO public.battle_participants (battle_id, user_id, team, role, source_stream_id, seat_index)
  VALUES
    (v_battle_id, v_self.user_id, 'challenger', 'host', v_self.id, 0),
    (v_battle_id, v_opponent.user_id, 'opponent', 'host', v_opponent.id, 0)
  ON CONFLICT (battle_id, user_id) DO NOTHING;

  INSERT INTO public.battle_participants (battle_id, user_id, team, role, source_stream_id, seat_index)
  SELECT v_battle_id, user_id, 'challenger', 'stage', v_self.id, seat_index
  FROM public.stream_seat_sessions
  WHERE stream_id = v_self.id
    AND status = 'active'
    AND user_id IS NOT NULL
  ON CONFLICT (battle_id, user_id) DO NOTHING;

  INSERT INTO public.battle_participants (battle_id, user_id, team, role, source_stream_id, seat_index)
  SELECT v_battle_id, user_id, 'opponent', 'stage', v_opponent.id, seat_index
  FROM public.stream_seat_sessions
  WHERE stream_id = v_opponent.id
    AND status = 'active'
    AND user_id IS NOT NULL
  ON CONFLICT (battle_id, user_id) DO NOTHING;

  UPDATE public.streams
  SET random_battle_queue_enabled = false,
      random_battle_queued_at = null,
      battle_mode = 'random_queue',
      battle_status = 'starting',
      is_battle = true,
      battle_id = v_battle_id,
      battle_start_time = v_started_at,
      battle_end_time = v_ends_at,
      battle_end_reason = null,
      battle_winner_id = null,
      battle_forfeited_by = null
  WHERE id IN (p_stream_id, v_opponent.id);

  RETURN jsonb_build_object(
    'matched', true,
    'battle_id', v_battle_id,
    'opponent_stream_id', v_opponent.id,
    'opponent_broadcaster_id', v_opponent.user_id,
    'battle_started_at', v_started_at,
    'battle_ends_at', v_ends_at
  );
END;
$$;

-- Function: find_shared_conversation
CREATE OR REPLACE FUNCTION public.find_shared_conversation(p_user_id UUID, p_other_user_id UUID)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_conversation_id UUID;
BEGIN
  SELECT cm1.conversation_id INTO v_conversation_id
  FROM public.conversation_members cm1
  INNER JOIN public.conversation_members cm2
    ON cm1.conversation_id = cm2.conversation_id
  WHERE cm1.user_id = p_user_id
    AND cm2.user_id = p_other_user_id
  LIMIT 1;

  RETURN v_conversation_id;
END;
$$;

-- Function: find_state_battle_match
CREATE OR REPLACE FUNCTION public.find_state_battle_match(
    p_stream_id UUID,
    p_broadcaster_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    v_broadcaster_state TEXT;
    v_matched_stream RECORD;
    v_battle_id UUID;
BEGIN
    -- Get broadcaster's state
    SELECT state_code INTO v_broadcaster_state
    FROM public.state_members
    WHERE user_id = p_broadcaster_id;

    IF v_broadcaster_state IS NULL THEN
        RETURN jsonb_build_object('matched', false, 'error', 'No state assigned');
    END IF;

    -- Find a live stream with state_battle_mode enabled, preferring different state
    -- Exclude streams that have been recently matched (cooldown)
    SELECT s.id as stream_id, s.user_id as broadcaster_id, sm.state_code as opponent_state
    INTO v_matched_stream
    FROM public.streams s
    JOIN public.state_members sm ON sm.user_id = s.user_id
    WHERE s.state_battle_mode = 'state'
      AND s.status = 'live'
      AND s.id != p_stream_id
      AND s.user_id != p_broadcaster_id
      AND (s.random_battle_cooldown_until IS NULL OR s.random_battle_cooldown_until < NOW())
    ORDER BY
        -- Prefer different state
        CASE WHEN sm.state_code != v_broadcaster_state THEN 0 ELSE 1 END,
        -- Then by most recent
        s.started_at DESC NULLS LAST
    LIMIT 1;

    IF v_matched_stream IS NULL THEN
        RETURN jsonb_build_object('matched', false, 'error', 'No opponent found');
    END IF;

    -- Create the battle
    INSERT INTO public.troll_battles (host_id, challenger_id, status, stream_id)
    VALUES (p_broadcaster_id, v_matched_stream.broadcaster_id, 'starting', p_stream_id)
    RETURNING id INTO v_battle_id;

    -- Update both streams
    UPDATE public.streams SET
        battle_id = v_battle_id,
        battle_mode = 'random_queue',
        battle_status = 'starting',
        battle_start_time = NOW() + INTERVAL '10 seconds',
        battle_end_time = NOW() + INTERVAL '10 minutes',
        state_battle_mode = 'state',
        random_battle_queue_enabled = false,
        random_battle_queued_at = NULL
    WHERE id = p_stream_id;

    UPDATE public.streams SET
        battle_id = v_battle_id,
        battle_mode = 'random_queue',
        battle_status = 'starting',
        battle_start_time = NOW() + INTERVAL '10 seconds',
        battle_end_time = NOW() + INTERVAL '10 minutes',
        state_battle_mode = 'state',
        random_battle_queue_enabled = false,
        random_battle_queued_at = NULL,
        random_battle_cooldown_until = NOW() + INTERVAL '5 minutes'
    WHERE id = v_matched_stream.stream_id;

    RETURN jsonb_build_object(
        'matched', true,
        'battle_id', v_battle_id,
        'battle_started_at', (NOW() + INTERVAL '10 seconds')::TEXT,
        'battle_ends_at', (NOW() + INTERVAL '10 minutes')::TEXT,
        'opponent_stream_id', v_matched_stream.stream_id,
        'opponent_state', v_matched_stream.opponent_state,
        'broadcaster_state', v_broadcaster_state
    );
END;
$$;

-- Function: finish_random_battle
CREATE OR REPLACE FUNCTION public.finish_random_battle(
  p_battle_id uuid,
  p_end_reason text DEFAULT 'timer_expired'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_battle public.battles%ROWTYPE;
  v_winner_stream_id uuid;
  v_winner_id uuid;
  v_loser_stream_id uuid;
  v_loser_id uuid;
BEGIN
  SELECT *
    INTO v_battle
  FROM public.battles
  WHERE id = p_battle_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle not found');
  END IF;

  IF v_battle.status = 'ended' THEN
    RETURN jsonb_build_object('success', true, 'winner_stream_id', v_battle.winner_stream_id, 'already_ended', true);
  END IF;

  IF v_battle.started_at IS NULL OR now() < v_battle.started_at + interval '90 seconds' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle minimum duration not elapsed');
  END IF;

  IF COALESCE(v_battle.score_challenger, 0) > COALESCE(v_battle.score_opponent, 0) THEN
    v_winner_stream_id := v_battle.challenger_stream_id;
    v_loser_stream_id := v_battle.opponent_stream_id;
  ELSIF COALESCE(v_battle.score_opponent, 0) > COALESCE(v_battle.score_challenger, 0) THEN
    v_winner_stream_id := v_battle.opponent_stream_id;
    v_loser_stream_id := v_battle.challenger_stream_id;
  END IF;

  IF v_winner_stream_id IS NOT NULL THEN
    SELECT user_id INTO v_winner_id
    FROM public.streams
    WHERE id = v_winner_stream_id;
  END IF;

  IF v_loser_stream_id IS NOT NULL THEN
    SELECT user_id INTO v_loser_id
    FROM public.streams
    WHERE id = v_loser_stream_id;
  END IF;

  UPDATE public.battles
  SET status = 'ended',
      ended_at = now(),
      winner_stream_id = v_winner_stream_id,
      winner_id = v_winner_id
  WHERE id = p_battle_id;

  UPDATE public.streams
  SET is_battle = false,
      battle_id = null,
      battle_mode = 'manual',
      battle_status = 'waiting',
      battle_start_time = null,
      battle_end_time = now(),
      battle_end_reason = p_end_reason,
      battle_winner_id = v_winner_id,
      battle_forfeited_by = null,
      random_battle_queue_enabled = false,
      random_battle_queued_at = null,
      random_battle_cooldown_until = null
  WHERE battle_id = p_battle_id
    AND battle_mode = 'random_queue';

  DELETE FROM public.battle_participants WHERE battle_id = p_battle_id;

  IF v_winner_id IS NOT NULL THEN
    UPDATE public.user_profiles
    SET battle_crowns = COALESCE(battle_crowns, 0) + 1,
        battle_crown_streak = COALESCE(battle_crown_streak, 0) + 1,
        total_battle_wins = COALESCE(total_battle_wins, 0) + 1
    WHERE id = v_winner_id;

    PERFORM public.award_family_battle_points(v_winner_id, 1, p_battle_id, 'battle_won');
    PERFORM public.award_agency_battle_points(v_winner_id, 1, p_battle_id);
  END IF;

  IF v_loser_id IS NOT NULL THEN
    UPDATE public.user_profiles
    SET battle_crown_streak = 0
    WHERE id = v_loser_id;

    PERFORM public.award_family_battle_points(v_loser_id, -10, p_battle_id, 'battle_lost');
    PERFORM public.award_agency_battle_points(v_loser_id, -10, p_battle_id);
  END IF;

  IF v_winner_stream_id IS NULL THEN
    UPDATE public.user_profiles
    SET battle_crown_streak = 0
    WHERE id IN (SELECT user_id FROM public.streams WHERE id IN (v_battle.challenger_stream_id, v_battle.opponent_stream_id));
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'winner_stream_id', v_winner_stream_id,
    'winner_id', v_winner_id,
    'loser_id', v_loser_id
  );
END;
$$;

-- Function: forfeit_random_battle
CREATE OR REPLACE FUNCTION public.forfeit_random_battle(
  p_stream_id uuid,
  p_broadcaster_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_battle record;
  v_forfeiter_stream_id uuid;
  v_winner_stream_id uuid;
  v_winner_id uuid;
  v_loser_id uuid;
BEGIN
  SELECT b.*
    INTO v_battle
  FROM public.battles b
  JOIN public.streams s ON s.id IN (b.challenger_stream_id, b.opponent_stream_id)
  WHERE s.id = p_stream_id
    AND s.user_id = p_broadcaster_id
    AND s.battle_mode = 'random_queue'
    AND b.status <> 'ended'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Random battle not found');
  END IF;

  v_forfeiter_stream_id := p_stream_id;
  v_winner_stream_id := CASE
    WHEN v_battle.challenger_stream_id = p_stream_id THEN v_battle.opponent_stream_id
    ELSE v_battle.challenger_stream_id
  END;

  SELECT user_id INTO v_winner_id
  FROM public.streams
  WHERE id = v_winner_stream_id
  FOR UPDATE;

  v_loser_id := p_broadcaster_id;

  UPDATE public.battles
  SET status = 'ended',
      ended_at = now(),
      winner_stream_id = v_winner_stream_id
  WHERE id = v_battle.id;

  UPDATE public.streams
  SET is_battle = false,
      battle_id = null,
      battle_mode = 'manual',
      battle_status = 'waiting',
      battle_start_time = null,
      battle_end_time = now(),
      battle_end_reason = 'forfeit',
      battle_winner_id = v_winner_id,
      battle_forfeited_by = p_broadcaster_id,
      random_battle_queue_enabled = false,
      random_battle_queued_at = null,
      random_battle_cooldown_until = null
  WHERE id = v_forfeiter_stream_id;

  DELETE FROM public.battle_participants WHERE battle_id = v_battle.id;

  UPDATE public.user_profiles
  SET battle_crowns = COALESCE(battle_crowns, 0) + 2,
      battle_crown_streak = COALESCE(battle_crown_streak, 0) + 1
  WHERE id = v_winner_id;

  UPDATE public.user_profiles
  SET battle_crown_streak = 0
  WHERE id = v_loser_id;

  PERFORM public.award_family_battle_points(v_winner_id, 1, v_battle.id, 'battle_won');
  PERFORM public.award_agency_battle_points(v_winner_id, 1, v_battle.id);

  PERFORM public.award_family_battle_points(v_loser_id, -10, v_battle.id, 'battle_lost');
  PERFORM public.award_agency_battle_points(v_loser_id, -10, v_battle.id);

  RETURN jsonb_build_object(
    'success', true,
    'battle_id', v_battle.id,
    'winner_id', v_winner_id,
    'winner_stream_id', v_winner_stream_id,
    'coins_awarded_to_forfeiter', 0,
    'crowns_awarded_to_winner', 2
  );
END;
$$;

-- Function: fulfill_marketplace_order
CREATE OR REPLACE FUNCTION public.fulfill_marketplace_order(
  p_order_id uuid,
  p_tracking_number text,
  p_carrier text,
  p_shipped_date timestamptz DEFAULT now()
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_order marketplace_purchases%ROWTYPE;
  v_tracking_url text;
  v_shipment_id uuid;
  v_seller_id uuid := auth.uid();
BEGIN
  IF v_seller_id IS NULL THEN
    RETURN 'Not authenticated';
  END IF;

  SELECT * INTO v_order
  FROM public.marketplace_purchases
  WHERE id = p_order_id
    AND seller_id = v_seller_id;

  IF v_order IS NULL THEN
    RETURN 'Order not found';
  END IF;

  IF v_order.status NOT IN ('paid', 'processing', 'shipped', 'delivered', 'completed') THEN
    RETURN 'Order cannot be fulfilled in current status';
  END IF;

  v_tracking_url := CASE
    WHEN p_carrier = 'usps' THEN 'https://tools.usps.com/go/TrackConfirmAction?tLabels=' || p_tracking_number
    WHEN p_carrier = 'fedex' THEN 'https://www.fedex.com/fedextrack/?trknbr=' || p_tracking_number
    WHEN p_carrier = 'ups' THEN 'https://www.ups.com/track?tracknum=' || p_tracking_number
    WHEN p_carrier = 'dhl' THEN 'https://www.dhl.com/en/express/tracking.html?AWB=' || p_tracking_number
    ELSE NULL
  END;

  INSERT INTO public.order_shipments (order_id, carrier, tracking_number, tracking_url, tracking_status, shipped_date)
  VALUES (p_order_id, p_carrier, p_tracking_number, v_tracking_url, 'label_created', p_shipped_date)
  ON CONFLICT (order_id) DO UPDATE SET
    carrier = p_carrier,
    tracking_number = p_tracking_number,
    tracking_url = v_tracking_url,
    shipped_date = p_shipped_date,
    tracking_status = 'label_created',
    updated_at = now()
  RETURNING id INTO v_shipment_id;

  -- Only update order status if not already shipped (avoid overwriting shipped_at)
  IF v_order.status NOT IN ('shipped', 'delivered', 'completed') THEN
    UPDATE public.marketplace_purchases
    SET status = 'shipped',
        fulfillment_status = 'fulfilled',
        tracking_number = p_tracking_number,
        shipping_carrier = p_carrier,
        tracking_url = v_tracking_url,
        shipped_at = now(),
        shipped_date = p_shipped_date,
        updated_at = now()
    WHERE id = p_order_id;

    INSERT INTO public.notifications (user_id, type, title, message, metadata, is_read, created_at)
    VALUES (
      v_order.buyer_id,
      'marketplace_order_shipped',
      'Order Shipped',
      'Your marketplace order has been shipped.',
      jsonb_build_object('order_id', p_order_id, 'tracking_number', p_tracking_number, 'carrier', p_carrier, 'route', '/my-orders'),
      false,
      now()
    );
  ELSE
    -- Just update tracking info for already-shipped orders
    UPDATE public.marketplace_purchases
    SET tracking_number = p_tracking_number,
        shipping_carrier = p_carrier,
        tracking_url = v_tracking_url,
        shipped_date = p_shipped_date,
        updated_at = now()
    WHERE id = p_order_id;
  END IF;

  RETURN 'Order fulfilled successfully';
END;
$$;

-- Function: generate_user_league_missions
CREATE OR REPLACE FUNCTION public.generate_user_league_missions(
    p_user_id UUID,
    p_league_event_id UUID DEFAULT NULL,
    p_count INTEGER DEFAULT 3
)
RETURNS SETOF public.user_league_missions
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_event public.league_events%ROWTYPE;
  v_existing_active INTEGER;
  v_needed INTEGER;
  v_template RECORD;
  v_target INTEGER;
  v_query TEXT;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;

  IF p_league_event_id IS NULL THEN
    SELECT * INTO v_event FROM public.get_active_league_event();
  ELSE
    SELECT * INTO v_event FROM public.league_events WHERE id = p_league_event_id;
  END IF;

  IF NOT FOUND THEN
    SELECT * INTO v_event FROM public.create_system_league_event();
  END IF;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_existing_active
  FROM public.user_league_missions
  WHERE user_id = p_user_id
    AND league_event_id = v_event.id
    AND status = 'active';

  v_needed := GREATEST(0, p_count - v_existing_active);
  IF v_needed <= 0 THEN
    RETURN;
  END IF;

  FOR v_template IN
    SELECT *
    FROM public.mission_templates
    WHERE is_enabled
      AND mission_key NOT IN (
          SELECT mission_key
          FROM public.user_league_missions
          WHERE user_id = p_user_id
            AND league_event_id = v_event.id
            AND status = 'active'
      )
    ORDER BY random() * weight DESC
    LIMIT v_needed
  LOOP
    v_target := (v_template.target_min + floor(random() * (v_template.target_max - v_template.target_min + 1)))::INT;

    RETURN QUERY INSERT INTO public.user_league_missions (
        user_id,
        league_event_id,
        mission_key,
        title,
        description,
        event_type,
        target_value,
        current_value,
        reward_points,
        reward_xp,
        reward_coins,
        status,
        generated_by,
        expires_at,
        metadata
    ) VALUES (
        p_user_id,
        v_event.id,
        v_template.mission_key,
        replace(v_template.title_template, '{{target}}', v_target::text),
        replace(v_template.description_template, '{{target}}', v_target::text),
        v_template.event_type,
        v_target,
        0,
        v_template.reward_points,
        v_template.reward_xp,
        v_template.reward_coins,
        'active',
        'system',
        v_event.ends_at,
        v_template.metadata
    )
    RETURNING *;
  END LOOP;

  IF v_needed > 0 THEN
    FOR v_template IN
      SELECT *
      FROM public.mission_templates
      WHERE is_enabled
      ORDER BY random() * weight DESC
      LIMIT v_needed
    LOOP
      v_target := (v_template.target_min + floor(random() * (v_template.target_max - v_template.target_min + 1)))::INT;

      RETURN QUERY INSERT INTO public.user_league_missions (
          user_id,
          league_event_id,
          mission_key,
          title,
          description,
          event_type,
          target_value,
          current_value,
          reward_points,
          reward_xp,
          reward_coins,
          status,
          generated_by,
          expires_at,
          metadata
      ) VALUES (
          p_user_id,
          v_event.id,
          v_template.mission_key,
          replace(v_template.title_template, '{{target}}', v_target::text),
          replace(v_template.description_template, '{{target}}', v_target::text),
          v_template.event_type,
          v_target,
          0,
          v_template.reward_points,
          v_template.reward_xp,
          LEAST(v_template.reward_coins, 10),
          'active',
          'system',
          v_event.ends_at,
          v_template.metadata
      ) RETURNING *;
    END LOOP;
  END IF;
END;
$$;

-- Function: get_active_giveaways
CREATE OR REPLACE FUNCTION get_active_giveaways()
RETURNS TABLE (
    id UUID,
    title TEXT,
    description TEXT,
    prize_type TEXT,
    prize_amount INTEGER,
    prize_tier TEXT,
    prize_duration_days INTEGER,
    gift_pack_discount INTEGER,
    entry_cost_trollz INTEGER,
    max_entries INTEGER,
    allow_free_entry BOOLEAN,
    end_time TIMESTAMPTZ,
    entry_count BIGINT,
    user_entry_count BIGINT,
    user_has_free_entry BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        g.id,
        g.title,
        g.description,
        g.prize_type,
        g.prize_amount,
        g.prize_tier,
        g.prize_duration_days,
        g.gift_pack_discount,
        g.entry_cost_trollz,
        g.max_entries,
        g.allow_free_entry,
        g.end_time,
        (SELECT COUNT(*) FROM giveaway_entries WHERE giveaway_id = g.id)::BIGINT AS entry_count,
        COALESCE((SELECT COUNT(*) FROM giveaway_entries WHERE giveaway_id = g.id AND user_id = auth.uid())::BIGINT, 0) AS user_entry_count,
        CASE 
            WHEN g.allow_free_entry AND NOT EXISTS (
                SELECT 1 FROM giveaway_entries 
                WHERE giveaway_id = g.id AND user_id = auth.uid() AND is_free_entry = true
            ) THEN true
            ELSE false
        END AS user_has_free_entry
    FROM giveaways g
    WHERE g.is_active = true 
        AND g.end_time > NOW()
    ORDER BY g.end_time ASC;
END;
$$;

-- Function: get_active_streams_paged
CREATE OR REPLACE FUNCTION get_active_streams_paged(
    p_limit INTEGER DEFAULT 20,
    p_offset INTEGER DEFAULT 0
)
RETURNS TABLE (
    id UUID,
    broadcaster_id UUID,
    title TEXT,
    category TEXT,
    current_viewers INTEGER,
    start_time TIMESTAMPTZ,
    thumbnail_url TEXT,
    broadcaster_username TEXT,
    broadcaster_avatar TEXT,
    broadcaster_dob TEXT, -- Added for compatibility
    stream_momentum JSONB
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        s.id,
        s.broadcaster_id,
        s.title,
        s.category,
        s.current_viewers,
        s.start_time,
        s.thumbnail_url,
        u.username,
        u.avatar_url,
        u.date_of_birth,
        NULL::jsonb
    FROM public.streams s
    JOIN public.user_profiles u ON s.broadcaster_id = u.id
    WHERE s.is_live = true
    ORDER BY s.current_viewers DESC, s.start_time DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;

-- Function: get_active_trollmers_tournament
CREATE OR REPLACE FUNCTION public.get_active_trollmers_tournament()
RETURNS TABLE (
    tournament_id UUID,
    month_start DATE,
    status TEXT,
    started_at TIMESTAMPTZ,
    winner_user_id UUID,
    participant_count BIGINT,
    current_round INTEGER
)
LANGUAGE plpgsql
STABLE
AS $$
BEGIN
    RETURN QUERY
    SELECT
        t.id,
        t.month_start,
        t.status,
        t.started_at,
        t.winner_user_id,
        (SELECT COUNT(*) FROM public.trollmers_tournament_participants WHERE tournament_id = t.id),
        COALESCE((SELECT MAX(round) FROM public.trollmers_tournament_battles WHERE tournament_id = t.id AND status = 'active'), 1)
    FROM public.trollmers_monthly_tournaments t
    WHERE t.status IN ('pending', 'active')
    ORDER BY t.month_start DESC
    LIMIT 1;
END;
$$;

-- Function: get_admin_dashboard_metrics_v1
CREATE OR REPLACE FUNCTION public.get_admin_dashboard_metrics_v1()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_finance JSONB;
    v_result JSONB;
BEGIN
    -- Delegate to the existing production RPC that has full admin authorization checks
    v_finance := public.get_admin_finance_summary_live();

    -- Return only the fields the non-admin frontend expects, with safe defaults
    -- This ensures non-admin users calling this RPC get zeros, not real data
    -- because get_admin_finance_summary_live already gates on is_bug_center_staff()
    v_result := jsonb_build_object(
        'success', true,
        'total_users', COALESCE((v_finance->>'total_users')::integer, 0),
        'coin_revenue', COALESCE((v_finance->>'coin_sales_revenue')::numeric, 0),
        'coins_sold', COALESCE((v_finance->>'purchased_coins')::bigint, 0),
        'platform_profit', COALESCE((v_finance->>'platform_profit')::numeric, 0),
        'coins_in_circulation', COALESCE((v_finance->>'total_troll_coins')::bigint, 0),
        'gift_coins', COALESCE((v_finance->>'gift_coins')::bigint, 0),
        'total_liability_coins', COALESCE((v_finance->>'total_liability_coins')::bigint, 0),
        'kick_ban_revenue', COALESCE((v_finance->>'kick_ban_revenue')::numeric, 0),
        'total_payouts', COALESCE((v_finance->>'total_payouts')::numeric, 0),
        'fees_collected', COALESCE((v_finance->>'fees_collected')::numeric, 0),
        'free_coins', COALESCE((v_finance->>'free_coins')::bigint, 0),
        'earned_coins', COALESCE((v_finance->>'earned_coins')::bigint, 0),
        'admin_count', COALESCE((v_finance->>'admin_count')::integer, 0),
        'troll_officer_count', COALESCE((v_finance->>'troll_officer_count')::integer, 0),
        'pending_applications', COALESCE((v_finance->>'pending_applications')::integer, 0),
        'pending_payouts', COALESCE((v_finance->>'pending_payouts')::integer, 0),
        'ai_flag_count', COALESCE((v_finance->>'ai_flag_count')::integer, 0),
        'last_updated', now()
    );

    RETURN v_result;
END;
$$;

-- Function: get_admin_finance_summary_live
CREATE OR REPLACE FUNCTION public.get_admin_finance_summary_live()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_total_users integer := 0;
  v_admin_count integer := 0;
  v_troll_officers integer := 0;
  v_pending_apps integer := 0;
  v_pending_payouts integer := 0;
  v_ai_flags integer := 0;
  v_total_coins numeric := 0;
  v_purchased_coins numeric := 0;
  v_earned_coins numeric := 0;
  v_free_coins numeric := 0;
  v_gift_coins numeric := 0;
  v_coin_sales_revenue numeric := 0;
  v_coin_sales_ct numeric := 0;
  v_coin_sales_pp numeric := 0;
  v_coin_sales_ledger numeric := 0;
  v_platform_profit numeric := 0;
  v_total_payouts numeric := 0;
  v_fees_collected numeric := 0;
  v_coin_kind_column text := NULL;
  v_payment_status_filter text := '';
  v_pp_coin_fallback numeric := 0;
  v_coins_pp numeric := 0;
  v_money_sql text := 'usd_amount';
BEGIN
  IF NOT public.is_bug_center_staff(auth.uid()) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (
           WHERE COALESCE(role, '') IN ('admin', 'superadmin', 'ceo', 'super_admin', 'platform_admin', 'moderator')
             OR COALESCE(is_admin, false)
             OR COALESCE(is_superadmin, false)
         ),
         COUNT(*) FILTER (
           WHERE COALESCE(role, '') IN ('troll_officer', 'lead_troll_officer')
             OR COALESCE(is_troll_officer, false)
             OR COALESCE(is_lead_officer, false)
         ),
         COALESCE(SUM(COALESCE(troll_coins, 0)), 0),
         COALESCE(SUM(COALESCE(total_earned_coins, 0)), 0)
    INTO v_total_users, v_admin_count, v_troll_officers, v_total_coins, v_earned_coins
  FROM public.user_profiles;

BEGIN
     -- Count pending applications from both creator_applications and applications tables
     -- creator_applications: broadcaster/empire partner applications
     -- applications: seller, troll_officer, lead_officer, attorney, prosecutor, auctioneer, job applications
     IF EXISTS (
       SELECT 1 FROM information_schema.tables
       WHERE table_schema = 'public' AND table_name = 'creator_applications'
     ) THEN
       EXECUTE 'SELECT COUNT(*) FROM public.creator_applications WHERE status = ''pending''' INTO v_pending_apps;
     END IF;
     IF EXISTS (
       SELECT 1 FROM information_schema.tables
       WHERE table_schema = 'public' AND table_name = 'applications'
     ) THEN
       EXECUTE 'SELECT COUNT(*) FROM public.applications WHERE status = ''pending''' INTO v_pending_apps;
     END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'payout_requests'
    ) THEN
      EXECUTE
        'SELECT COUNT(*) FROM public.payout_requests WHERE status IN (''pending'', ''requested'', ''review'')'
        INTO v_pending_payouts;
      EXECUTE
        'SELECT COALESCE(SUM(amount), 0) FROM public.payout_requests WHERE status IN (''paid'', ''approved'', ''completed'')'
        INTO v_total_payouts;
    END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'type'
    ) THEN
      v_coin_kind_column := 'type';
    ELSIF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'transaction_type'
    ) THEN
      v_coin_kind_column := 'transaction_type';
    END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'payment_transactions' AND column_name = 'status'
    ) THEN
      v_payment_status_filter := ' WHERE COALESCE(status, ''completed'') IN (''completed'', ''paid'', ''success'')';
    END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'amount_usd'
    ) THEN
      v_money_sql := 'amount_usd';
    ELSIF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'usd_amount'
    ) THEN
      v_money_sql := '';
    END IF;

    IF v_coin_kind_column IS NOT NULL
       AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'amount'
       )
       AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'metadata'
       )
       AND v_money_sql <> ''
    THEN
      EXECUTE format($q$
        SELECT COALESCE(SUM(ct.amount), 0)
        FROM public.coin_transactions ct
        WHERE ct.amount > 0 AND (
          ct.%I IN (
            'purchase', 'store_purchase', 'paypal_purchase', 'coin_purchase',
            'cashapp_purchase', 'stripe_purchase', 'square_purchase'
          )
          OR ct.%I::text LIKE '%%paypal%%'
          OR (
            EXISTS (
              SELECT 1 FROM information_schema.columns c
              WHERE c.table_schema = 'public' AND c.table_name = 'coin_transactions' AND c.column_name = 'paypal_order_id'
            )
            AND ct.paypal_order_id IS NOT NULL AND trim(ct.paypal_order_id) <> ''
          )
          OR (
            EXISTS (
              SELECT 1 FROM information_schema.columns c
              WHERE c.table_schema = 'public' AND c.table_name = 'coin_transactions' AND c.column_name = 'paypal_capture_id'
            )
            AND ct.paypal_capture_id IS NOT NULL AND trim(ct.paypal_capture_id) <> ''
          )
          OR COALESCE(trim(ct.metadata->>'paypal_order_id'), '') <> ''
          OR COALESCE(trim(ct.metadata->>'paypal_capture_id'), '') <> ''
          OR (
            EXISTS (
              SELECT 1 FROM information_schema.columns c
              WHERE c.table_schema = 'public' AND c.table_name = 'coin_transactions' AND c.column_name = 'source'
            )
            AND COALESCE(ct.source, '') IN ('purchase', 'paypal', 'coin_store', 'stripe', 'cashapp')
            AND ct.%I NOT IN ('gift', 'gift_received', 'admin_grant', 'reward', 'bonus', 'daily_login')
          )
        )
      $q$, v_coin_kind_column, v_coin_kind_column, v_coin_kind_column) INTO v_purchased_coins;

      EXECUTE format($q$
        SELECT COALESCE(SUM(
          CASE
            WHEN COALESCE(ct.%I, 0)::numeric <> 0 THEN ct.%I::numeric
            WHEN EXISTS (
              SELECT 1 FROM information_schema.columns x
              WHERE x.table_schema = 'public' AND x.table_name = 'coin_transactions' AND x.column_name = 'platform_profit'
            )
             AND COALESCE(ct.platform_profit, 0) <> 0 THEN ct.platform_profit::numeric
            ELSE GREATEST(
              COALESCE(NULLIF(trim(ct.metadata->>'amount_paid'), '')::numeric, 0),
              COALESCE(NULLIF(trim(ct.metadata->>'amount_usd'), '')::numeric, 0),
              COALESCE(NULLIF(trim(ct.metadata->>'amount'), '')::numeric, 0),
              CASE
                WHEN (
                  EXISTS (
                    SELECT 1 FROM information_schema.columns x
                    WHERE x.table_schema = 'public' AND x.table_name = 'coin_transactions'
                      AND x.column_name = 'paypal_order_id'
                  )
                  AND ct.paypal_order_id IS NOT NULL
                ) OR COALESCE(trim(ct.metadata->>'paypal_order_id'), '') <> ''
                THEN GREATEST(0::numeric, ct.amount::numeric / NULLIF(100::numeric, 0))
                ELSE 0::numeric
              END
            )
          END
        ), 0)
        FROM public.coin_transactions ct
        WHERE ct.amount > 0 AND (
          ct.%I IN (
            'purchase', 'store_purchase', 'paypal_purchase', 'coin_purchase',
            'cashapp_purchase', 'stripe_purchase', 'square_purchase'
          )
          OR ct.%I::text LIKE '%%paypal%%'
          OR (
            EXISTS (
              SELECT 1 FROM information_schema.columns c
              WHERE c.table_schema = 'public' AND c.table_name = 'coin_transactions'
                AND c.column_name = 'paypal_order_id'
            )
            AND ct.paypal_order_id IS NOT NULL AND trim(ct.paypal_order_id) <> ''
          )
          OR COALESCE(trim(ct.metadata->>'paypal_order_id'), '') <> ''
          OR COALESCE(trim(ct.metadata->>'paypal_capture_id'), '') <> ''
          OR (
            EXISTS (
              SELECT 1 FROM information_schema.columns c
              WHERE c.table_schema = 'public' AND c.table_name = 'coin_transactions'
                AND c.column_name = 'source'
            )
            AND COALESCE(ct.source, '') IN ('purchase', 'paypal', 'coin_store', 'stripe', 'cashapp')
            AND ct.%I NOT IN ('gift', 'gift_received', 'admin_grant', 'reward', 'bonus', 'daily_login')
          )
        )
      $q$, v_money_sql, v_money_sql, v_coin_kind_column, v_coin_kind_column, v_coin_kind_column) INTO v_coin_sales_ct;

      EXECUTE format(
        'SELECT COALESCE(SUM(amount), 0) FROM public.coin_transactions WHERE %I IN (%L,%L,%L) AND amount > 0',
        v_coin_kind_column, 'gift', 'gift_received', 'trollmond_gift'
      ) INTO v_gift_coins;
      EXECUTE format(
        'SELECT COALESCE(SUM(ABS(amount)), 0) FROM public.coin_transactions WHERE %I IN (%L,%L,%L,%L) AND amount > 0',
        v_coin_kind_column, 'reward', 'bonus', 'daily_login', 'admin_grant'
      ) INTO v_free_coins;
    END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'paypal_transactions'
    )
       AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'paypal_transactions' AND column_name = 'amount'
       )
    THEN
      EXECUTE $sql$
        SELECT COALESCE(SUM(amount), 0)
        FROM public.paypal_transactions
        WHERE COALESCE(lower(status), '') IN ('completed', 'credited', '')
      $sql$ INTO v_coin_sales_pp;

      IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'paypal_transactions' AND column_name = 'coins'
      ) THEN
        EXECUTE $sql$
          SELECT COALESCE(SUM(coins), 0)
          FROM public.paypal_transactions
          WHERE COALESCE(lower(status), '') IN ('completed', 'credited', '')
            AND coins IS NOT NULL AND coins > 0
        $sql$ INTO v_coins_pp;
      END IF;
    END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'purchase_ledger'
    )
       AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'purchase_ledger' AND column_name = 'usd_amount'
       )
       AND EXISTS (
         SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'purchasable_items'
       )
       AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'purchasable_items' AND column_name = 'is_coin_pack'
       )
    THEN
      EXECUTE $sql$
        SELECT COALESCE(SUM(pl.usd_amount), 0)
        FROM public.purchase_ledger pl
        JOIN public.purchasable_items pi ON pi.id = pl.item_id
        WHERE pi.is_coin_pack IS TRUE AND pl.usd_amount IS NOT NULL
      $sql$ INTO v_coin_sales_ledger;
    ELSIF EXISTS (
      SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'purchase_ledger'
    )
           AND EXISTS (
             SELECT 1 FROM information_schema.columns
             WHERE table_schema = 'public' AND table_name = 'purchase_ledger' AND column_name = 'usd_amount'
           )
    THEN
      EXECUTE $sql$
        SELECT COALESCE(SUM(usd_amount), 0)
        FROM public.purchase_ledger
        WHERE usd_amount IS NOT NULL
      $sql$ INTO v_coin_sales_ledger;
    END IF;

    v_coin_sales_revenue :=
      GREATEST(COALESCE(v_coin_sales_ct, 0), COALESCE(v_coin_sales_pp, 0), COALESCE(v_coin_sales_ledger, 0));

    IF COALESCE(v_purchased_coins, 0) = 0 AND COALESCE(v_coins_pp, 0) > 0 THEN
      v_purchased_coins := v_coins_pp;
    END IF;

    IF COALESCE(v_coin_sales_revenue, 0) = 0
       AND v_coin_kind_column IS NOT NULL
       AND EXISTS (
         SELECT 1 FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'platform_profit'
       )
    THEN
      EXECUTE format($q$
        SELECT COALESCE(SUM(ct.platform_profit), 0)
        FROM public.coin_transactions ct
        WHERE COALESCE(ct.platform_profit, 0) <> 0
          AND (
            ct.%I IN ('purchase', 'store_purchase', 'paypal_purchase', 'coin_purchase')
            OR (
              EXISTS (
                SELECT 1 FROM information_schema.columns c
                WHERE c.table_schema = 'public'
                  AND c.table_name = 'coin_transactions'
                  AND c.column_name = 'paypal_order_id'
              )
              AND ct.paypal_order_id IS NOT NULL
            )
            OR COALESCE(trim(ct.metadata->>'paypal_order_id'), '') <> ''
          )
      $q$, v_coin_kind_column) INTO v_pp_coin_fallback;
      IF COALESCE(v_pp_coin_fallback, 0) > 0 THEN
        v_coin_sales_revenue := v_pp_coin_fallback;
      END IF;
    END IF;

    IF COALESCE(v_coin_sales_revenue, 0) = 0 AND EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'payment_transactions' AND column_name = 'amount_paid'
    ) THEN
      EXECUTE
        'SELECT COALESCE(SUM(amount_paid), 0) FROM public.payment_transactions'
        || v_payment_status_filter
        INTO v_coin_sales_revenue;
    END IF;

    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'coin_transactions' AND column_name = 'platform_profit'
    ) THEN
      EXECUTE 'SELECT COALESCE(SUM(platform_profit), 0) FROM public.coin_transactions'
        INTO v_platform_profit;
    END IF;

    IF COALESCE(v_platform_profit, 0) = 0 AND EXISTS (
      SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'platform_profit'
    ) THEN
      EXECUTE 'SELECT COALESCE(SUM(total_profit), 0) FROM public.platform_profit' INTO v_platform_profit;
    END IF;

v_fees_collected := GREATEST(v_coin_sales_revenue - v_total_payouts, 0);
    -- Count stream reports for AI/flags count (reports needing moderation review)
    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'stream_reports'
    ) THEN
      EXECUTE 'SELECT COUNT(*) FROM public.stream_reports WHERE status = ''pending''' INTO v_ai_flags;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'get_admin_finance_summary_live aggregates skipped: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'total_users', v_total_users,
    'admin_count', v_admin_count,
    'pending_applications', v_pending_apps,
    'pending_payouts', v_pending_payouts,
    'troll_officer_count', v_troll_officers,
    'ai_flag_count', v_ai_flags,
    'coin_sales_revenue', v_coin_sales_revenue,
    'total_payouts', v_total_payouts,
    'fees_collected', v_fees_collected,
    'platform_profit', v_platform_profit,
    'purchased_coins', v_purchased_coins,
    'earned_coins', v_earned_coins,
    'free_coins', v_free_coins,
    'total_troll_coins', v_total_coins,
    'gift_coins', v_gift_coins,
    'app_sponsored_gifts', 0,
    'total_liability_coins', v_total_coins,
    'kick_ban_revenue', 0,
    'last_updated', now()
  );
END;
$$;

-- Function: get_bank_reserves
CREATE OR REPLACE FUNCTION public.get_bank_reserves()
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_balance BIGINT;
BEGIN
    SELECT troll_coins INTO v_balance
    FROM public.user_profiles
    WHERE role = 'admin' OR is_admin = true
    ORDER BY created_at ASC
    LIMIT 1;
    
    RETURN COALESCE(v_balance, 0);
END;
$$;

-- Function: get_beta_feedback_stats
CREATE OR REPLACE FUNCTION public.get_beta_feedback_stats()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET statement_timeout = '15s'
AS $$
DECLARE
  v_total integer := 0;
  v_submitted integer := 0;
  v_under_review integer := 0;
  v_critical integer := 0;
  v_fixed integer := 0;
  v_unique_reporters integer := 0;
BEGIN
  IF NOT public.is_beta_feedback_moderator(auth.uid()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status = 'submitted'),
    COUNT(*) FILTER (WHERE status = 'under_review'),
    COUNT(*) FILTER (WHERE priority = 'critical' AND archived_at IS NULL),
    COUNT(*) FILTER (WHERE status = 'fixed'),
    COUNT(DISTINCT user_id)
  INTO v_total, v_submitted, v_under_review, v_critical, v_fixed, v_unique_reporters
  FROM public.beta_feedback;
  RETURN jsonb_build_object(
    'success', true,
    'total', v_total,
    'submitted', v_submitted,
    'under_review', v_under_review,
    'critical', v_critical,
    'fixed', v_fixed,
    'unique_reporters', v_unique_reporters
  );
END;
$$;

-- Function: get_beta_feedback_user_groups
CREATE OR REPLACE FUNCTION public.get_beta_feedback_user_groups(
  p_limit integer DEFAULT 50,
  p_offset integer DEFAULT 0
)
RETURNS TABLE (
  user_id uuid,
  username text,
  avatar_url text,
  submission_count bigint,
  latest_submission_at timestamptz,
  unresolved_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET statement_timeout = '15s'
AS $$
BEGIN
  IF NOT public.is_beta_feedback_moderator(auth.uid()) THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT
    bf.user_id,
    up.username,
    up.avatar_url,
    COUNT(*) AS submission_count,
    MAX(bf.created_at) AS latest_submission_at,
    COUNT(*) FILTER (WHERE bf.status NOT IN ('fixed','closed','declined','duplicate')) AS unresolved_count
  FROM public.beta_feedback bf
  JOIN public.user_profiles up ON up.id = bf.user_id
  GROUP BY bf.user_id, up.username, up.avatar_url
  ORDER BY latest_submission_at DESC NULLS LAST
  LIMIT p_limit OFFSET p_offset;
END;
$$;

-- Function: get_call_balances
CREATE OR REPLACE FUNCTION public.get_call_balances(p_user_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $$
DECLARE
    v_audio INTEGER := 0;
    v_video INTEGER := 0;
BEGIN
    SELECT COALESCE(audio_minutes, 0), COALESCE(video_minutes, 0)
    INTO v_audio, v_video
    FROM public.call_minutes
    WHERE user_id = p_user_id;

    RETURN jsonb_build_object(
        'audio_minutes', v_audio,
        'video_minutes', v_video
    );
END;
$$;

-- Function: get_cashout_forecast
CREATE OR REPLACE FUNCTION get_cashout_forecast(
  projection_percent integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  result jsonb;
  eligible_users_count bigint;
  total_eligible_coins numeric;
  total_exposure_usd numeric;
  median_payout numeric;
  top_earners jsonb;
BEGIN
  -- Check permissions
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid() AND (role IN ('admin', 'secretary', 'president') OR is_admin = true)
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- 1. Base Stats (Count & Total Coins)
  SELECT
    COUNT(*),
    COALESCE(SUM(coins_eligible_for_cashout), 0)
  INTO eligible_users_count, total_eligible_coins
  FROM public.user_earnings_summary
  WHERE is_cashout_eligible = true;

  -- 2. USD Exposure (Tiered Calculation)
  SELECT COALESCE(SUM(
    CASE
      WHEN coins_eligible_for_cashout >= 120000 THEN coins_eligible_for_cashout * (355.0 / 120000.0)
      WHEN coins_eligible_for_cashout >= 60000 THEN coins_eligible_for_cashout * (150.0 / 60000.0)
      WHEN coins_eligible_for_cashout >= 26375 THEN coins_eligible_for_cashout * (70.0 / 26375.0)
      WHEN coins_eligible_for_cashout >= 12000 THEN coins_eligible_for_cashout * (25.0 / 12000.0)
      ELSE 0
    END
  ), 0)
  INTO total_exposure_usd
  FROM public.user_earnings_summary
  WHERE is_cashout_eligible = true;

  -- 3. Apply Projection
  -- If projection is < 100, we assume a linear reduction for simple forecasting
  IF projection_percent < 100 THEN
    total_eligible_coins := total_eligible_coins * (projection_percent::numeric / 100.0);
    total_exposure_usd := total_exposure_usd * (projection_percent::numeric / 100.0);
    eligible_users_count := (eligible_users_count * (projection_percent::numeric / 100.0))::bigint;
  END IF;

  -- 4. Top 10 Earners (Always show actual top earners)
  SELECT jsonb_agg(t) INTO top_earners
  FROM (
    SELECT user_id, username, coins_eligible_for_cashout
    FROM public.user_earnings_summary
    WHERE is_cashout_eligible = true
    ORDER BY coins_eligible_for_cashout DESC
    LIMIT 10
  ) t;

  -- 5. Median Payout
  SELECT PERCENTILE_CONT(0.5) WITHIN GROUP(ORDER BY coins_eligible_for_cashout)
  INTO median_payout
  FROM public.user_earnings_summary
  WHERE is_cashout_eligible = true;

  result := jsonb_build_object(
    'eligible_users_count', eligible_users_count,
    'total_eligible_coins', total_eligible_coins,
    'total_exposure_usd', total_exposure_usd,
    'top_earners', COALESCE(top_earners, '[]'::jsonb),
    'median_payout', COALESCE(median_payout, 0)
  );

  RETURN result;
END;
$$;

-- Function: get_current_court_session
CREATE OR REPLACE FUNCTION public.get_current_court_session()
RETURNS TABLE (
    id UUID,
    status text,
    started_by UUID,
    started_at TIMESTAMPTZ,
    ended_at TIMESTAMPTZ
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        cs.id,
        cs.status,
        cs.started_by,
        cs.started_at,
        cs.ended_at
    FROM court_sessions cs
    WHERE cs.status IN ('waiting', 'live', 'active', 'scheduled')
