-- Migration: Inventory Expiration Logic
-- 1. Function to clean up expired purchases and sync active items
-- 2. Optional cron job to run it hourly

-- Create the cleanup function
CREATE OR REPLACE FUNCTION public.cleanup_expired_user_purchases()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  deleted_count integer;
BEGIN
  -- 1. Delete expired purchases
  WITH deleted AS (
    DELETE FROM public.user_purchases
    WHERE expires_at IS NOT NULL 
      AND expires_at < NOW()
    RETURNING *
  )
  SELECT count(*) INTO deleted_count FROM deleted;

  -- 2. Remove items from user_active_items if the user no longer owns a valid copy
  -- (i.e., all copies are expired or deleted)
  DELETE FROM public.user_active_items uai
  WHERE NOT EXISTS (
      SELECT 1 FROM public.user_purchases up
      WHERE up.user_id = uai.user_id 
      AND up.item_id = uai.item_id
      AND (up.expires_at IS NULL OR up.expires_at > NOW())
  );
  
END;
$$;

-- Function: get_delinquent_loan_users
CREATE OR REPLACE FUNCTION public.get_delinquent_loan_users()
RETURNS TABLE (
    user_id UUID,
    username TEXT,
    total_balance BIGINT,
    days_overdue INTEGER,
    owned_properties JSONB,
    owned_vehicles JSONB
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN QUERY
    SELECT
        l.user_id,
        up.username,
        SUM(l.balance) as total_balance,
        EXTRACT(DAY FROM (NOW() - l.created_at))::INTEGER as days_overdue,
        (
            SELECT json_agg(json_build_object(
                'id', p.id,
                'name', p.property_name,
                'is_repossessed', p.is_repossessed
            ))
            FROM public.properties p
            WHERE p.owner_user_id = l.user_id
            AND p.is_repossessed = false
        ) as owned_properties,
        (
            SELECT json_agg(json_build_object(
                'id', uv.id,
                'name', vc.name,
                'is_repossessed', uv.is_repossessed
            ))
            FROM public.user_vehicles uv
            JOIN public.vehicles_catalog vc ON uv.catalog_id = vc.id
            WHERE uv.user_id = l.user_id
            AND uv.is_repossessed = false
        ) as owned_vehicles
    FROM public.loans l
    JOIN public.user_profiles up ON l.user_id = up.id
    WHERE l.status = 'active'
    AND l.balance > 0
    GROUP BY l.user_id, up.username, l.created_at
    ORDER BY total_balance DESC;
END;
$$;

-- Function: get_gift_leaderboard
CREATE OR REPLACE FUNCTION public.get_gift_leaderboard(
  p_window text DEFAULT 'day',
  p_direction text DEFAULT 'received',
  p_limit integer DEFAULT 20
)
RETURNS TABLE (
  user_id uuid,
  username text,
  avatar_url text,
  rgb_username_expires_at timestamptz,
  glowing_username_color text,
  created_at timestamptz,
  total_gift_coins bigint,
  gift_count bigint
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  WITH bounds AS (
    SELECT CASE lower(COALESCE(p_window, 'day'))
      WHEN '30m' THEN interval '30 minutes'
      WHEN '30min' THEN interval '30 minutes'
      WHEN 'hour' THEN interval '1 hour'
      WHEN '1h' THEN interval '1 hour'
      WHEN 'week' THEN interval '7 days'
      WHEN 'month' THEN interval '30 days'
      ELSE interval '1 day'
    END AS window_interval
  ),
  normalized AS (
    SELECT
      sg.sender_id,
      COALESCE(sg.receiver_id, sg.recipient_id) AS receiver_id,
      GREATEST(
        COALESCE(
          sg.coins_amount,
          sg.coins_spent,
          sg.amount,
          CASE
            WHEN (sg.metadata->>'gift_value') ~ '^[0-9]+(\.[0-9]+)?$'
              THEN (sg.metadata->>'gift_value')::numeric
            ELSE 0
          END,
          0
        ),
        0
      )::bigint AS coin_value,
      sg.created_at
    FROM public.stream_gifts sg, bounds b
    WHERE sg.created_at >= now() - b.window_interval
      AND sg.sender_id IS NOT NULL
      AND COALESCE(sg.receiver_id, sg.recipient_id) IS NOT NULL
  ),
  ranked AS (
    SELECT
      CASE
        WHEN lower(COALESCE(p_direction, 'received')) IN ('sent', 'gifters', 'sender') THEN sender_id
        ELSE receiver_id
      END AS leaderboard_user_id,
      SUM(coin_value)::bigint AS total_gift_coins,
      COUNT(*)::bigint AS gift_count
    FROM normalized
    WHERE coin_value > 0
    GROUP BY 1
  )
  SELECT
    up.id AS user_id,
    up.username,
    up.avatar_url,
    up.rgb_username_expires_at,
    up.glowing_username_color,
    up.created_at,
    r.total_gift_coins,
    r.gift_count
  FROM ranked r
  JOIN public.user_profiles up ON up.id = r.leaderboard_user_id
  WHERE r.total_gift_coins > 0
  ORDER BY r.total_gift_coins DESC, r.gift_count DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
$$;

-- Function: get_live_auction_state
CREATE OR REPLACE FUNCTION get_live_auction_state(p_show_id UUID)
RETURNS JSONB AS $$
DECLARE
  v_current_lot auction_lots%ROWTYPE;
  v_bids JSONB;
  v_viewer_count INTEGER;
  v_anonymous_active BOOLEAN;
  v_anonymous_ends_at TIMESTAMPTZ;
BEGIN
  -- Get current lot
  SELECT * INTO v_current_lot
  FROM auction_lots
  WHERE auction_show_id = p_show_id
    AND status = 'live'
  ORDER BY queue_position NULLS LAST
  LIMIT 1;

  -- Get anonymous round state
  SELECT is_anonymous_round_active, anonymous_round_ends_at
  INTO v_anonymous_active, v_anonymous_ends_at
  FROM auction_shows
  WHERE id = p_show_id;

  -- Get recent bids (handle anonymous display)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', ab.id,
      'lot_id', ab.lot_id,
      'bidder_id', ab.bidder_id,
      'bid_amount', ab.bid_amount,
      'created_at', ab.created_at,
      'is_anonymous', COALESCE(ab.is_anonymous, false),
      'anonymous_label', ab.anonymous_label,
      'is_boost_bid', COALESCE(ab.is_boost_bid, false),
      'boost_amount', COALESCE(ab.boost_amount, 0),
      'bidder', CASE
        WHEN COALESCE(ab.is_anonymous, false) AND v_anonymous_active THEN
          jsonb_build_object(
            'username', COALESCE(ab.anonymous_label, 'Anonymous'),
            'display_name', COALESCE(ab.anonymous_label, 'Anonymous'),
            'avatar_url', NULL
          )
        ELSE
          jsonb_build_object(
            'username', up.username,
            'display_name', up.display_name,
            'avatar_url', up.avatar_url
          )
      END
    ) ORDER BY ab.created_at DESC
  ), '[]'::JSONB)
  INTO v_bids
  FROM auction_bids ab
  LEFT JOIN user_profiles up ON up.id = ab.bidder_id
  WHERE ab.auction_show_id = p_show_id
    AND ab.created_at > now() - interval '5 minutes';

  -- Get viewer count
  SELECT COUNT(DISTINCT user_id) INTO v_viewer_count
  FROM auction_presence
  WHERE auction_show_id = p_show_id AND is_active = true;

  RETURN jsonb_build_object(
    'current_lot', CASE WHEN v_current_lot.id IS NOT NULL THEN
      jsonb_build_object(
        'id', v_current_lot.id,
        'title', v_current_lot.title,
        'description', v_current_lot.description,
        'image_url', v_current_lot.image_url,
        'starting_bid', v_current_lot.starting_bid,
        'bid_increment', v_current_lot.bid_increment,
        'current_highest_bid', v_current_lot.current_highest_bid,
        'current_highest_bidder_id', v_current_lot.current_highest_bidder_id,
        'status', v_current_lot.status,
        'countdown_end_at', v_current_lot.countdown_end_at,
        'condition', v_current_lot.condition,
        'quantity', v_current_lot.quantity
      )
    ELSE NULL END,
    'recent_bids', v_bids,
    'viewer_count', v_viewer_count,
    'anonymous_round', jsonb_build_object(
      'active', COALESCE(v_anonymous_active, false),
      'ends_at', v_anonymous_ends_at,
      'seconds_remaining', CASE
        WHEN v_anonymous_ends_at IS NOT NULL THEN
          GREATEST(0, EXTRACT(EPOCH FROM (v_anonymous_ends_at - now()))::int)
        ELSE 0
      END
    )
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

COMMENT ON FUNCTION get_live_auction_state IS 'Get live auction state including anonymous round info';

-- ============================================================
-- Post Media Video Support
-- Date: 2026-06-14
-- Purpose: Enable video uploads in post-media bucket with
--          proper size limits, MIME types, and RLS policies
-- ============================================================

-- 1. Update post-media bucket: enable file size limit and video MIME types
UPDATE storage.buckets SET
  file_size_limit = 104857600,  -- 100MB max file size (5 min video @ ~20Mbps)
  allowed_mime_types = ARRAY[
    'image/jpeg',
    'image/png',
    'image/gif',
    'image/webp',
    'video/mp4',
    'video/webm',
    'video/quicktime',
    'video/x-matroska'
  ]
WHERE id = 'post-media';

-- 2. Ensure bucket is public
UPDATE storage.buckets SET public = true WHERE id = 'post-media';

-- 3. RLS Policies for post-media bucket
-- Public can view post media
CREATE POLICY "Public can view post media"
ON storage.objects FOR SELECT
TO public
USING (bucket_id = 'post-media');

-- Authenticated users can upload post media
CREATE POLICY "Authenticated users can upload post media"
ON storage.objects FOR INSERT
TO authenticated
WITH CHECK (
  bucket_id = 'post-media'
  AND auth.uid()::text = (storage.foldername(name))[1]
);

-- Users can update their own post media
CREATE POLICY "Users can update own post media"
ON storage.objects FOR UPDATE
TO authenticated
USING (
  bucket_id = 'post-media'
  AND auth.uid()::text = (storage.foldername(name))[1]
);

-- Users can delete their own post media
CREATE POLICY "Users can delete own post media"
ON storage.objects FOR DELETE
TO authenticated
USING (
  bucket_id = 'post-media'
  AND auth.uid()::text = (storage.foldername(name))[1]
);

-- 4. Add video_url column to troll_wall_posts if it doesn't exist
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'troll_wall_posts'
    AND column_name = 'video_url'
  ) THEN
    ALTER TABLE public.troll_wall_posts
      ADD COLUMN video_url text,
      ADD COLUMN thumbnail_url text,
      ADD COLUMN media_type text DEFAULT 'image' CHECK (media_type IN ('image', 'video'));
  END IF;
END $$;

-- Function: get_market_stats
CREATE OR REPLACE FUNCTION public.get_market_stats()
RETURNS TABLE(
    total_stocks INTEGER,
    total_volume BIGINT,
    avg_price DECIMAL(15,2),
    top_gainer_stock VARCHAR,
    top_gainer_change DECIMAL(10,2),
    most_traded_stock VARCHAR,
    most_traded_volume BIGINT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
    RETURN QUERY
    SELECT
        (SELECT COUNT(*)::INTEGER FROM public.stocks WHERE is_active = TRUE),
        (SELECT COALESCE(SUM(volume), 0)::BIGINT FROM public.stocks WHERE is_active = TRUE),
        (SELECT COALESCE(AVG(current_price), 0)::DECIMAL(15,2) FROM public.stocks WHERE is_active = TRUE),
        (SELECT stock_symbol FROM public.stocks WHERE is_active = TRUE ORDER BY price_change_pct_24h DESC NULLS LAST LIMIT 1),
        (SELECT MAX(price_change_pct_24h)::DECIMAL(10,2) FROM public.stocks WHERE is_active = TRUE),
        (SELECT stock_symbol FROM public.stocks WHERE is_active = TRUE ORDER BY volume DESC NULLS LAST LIMIT 1),
        (SELECT MAX(volume)::BIGINT FROM public.stocks WHERE is_active = TRUE);
END;
$$;

-- Function: get_moderation_logs
CREATE OR REPLACE FUNCTION public.get_moderation_logs(limit_count INTEGER DEFAULT 50)
RETURNS TABLE (
    id UUID,
    moderator_username TEXT,
    target_username TEXT,
    action_type TEXT,
    reason TEXT,
    created_at TIMESTAMPTZ,
    expires_at TIMESTAMPTZ
)
LANGUAGE sql
SECURITY DEFINER
AS $$
    SELECT 
        l.id,
        m.username as moderator_username,
        t.username as target_username,
        l.action_type,
        l.reason,
        l.created_at,
        l.expires_at
    FROM public.moderation_logs l
    LEFT JOIN public.user_profiles m ON l.moderator_id = m.id
    LEFT JOIN public.user_profiles t ON l.target_user_id = t.id
    ORDER BY l.created_at DESC
    LIMIT limit_count;
$$;

-- Function: get_my_universe_matches
CREATE OR REPLACE FUNCTION public.get_my_universe_matches(p_event_id UUID)
RETURNS TABLE (
  match_id UUID,
  my_side TEXT,
  my_registration_id UUID,
  opponent_registration_id UUID,
  opponent_captain_id UUID,
  opponent_hidden BOOLEAN,
  scheduled_start TIMESTAMPTZ,
  opponent_reveal_at TIMESTAMPTZ,
  status TEXT
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    m.id AS match_id,
    CASE WHEN m.box_one_captain_id = v_uid THEN 'A' ELSE 'B' END AS my_side,
    CASE WHEN m.box_one_captain_id = v_uid THEN m.registration_one_id ELSE m.registration_two_id END AS my_registration_id,
    CASE
      WHEN public.universe_match_revealed(m.id) THEN
        CASE WHEN m.box_one_captain_id = v_uid THEN m.registration_two_id ELSE m.registration_one_id END
      ELSE NULL
    END AS opponent_registration_id,
    CASE
      WHEN public.universe_match_revealed(m.id) THEN
        CASE WHEN m.box_one_captain_id = v_uid THEN m.box_two_captain_id ELSE m.box_one_captain_id END
      ELSE NULL
    END AS opponent_captain_id,
    (NOT public.universe_match_revealed(m.id)) AS opponent_hidden,
    m.scheduled_start,
    m.opponent_reveal_at,
    m.status
  FROM public.universe_match_assignments m
  WHERE m.event_id = p_event_id
    AND (m.box_one_captain_id = v_uid OR m.box_two_captain_id = v_uid);
END;
$$;

-- Function: get_nearby_neighbors_events
CREATE OR REPLACE FUNCTION get_nearby_neighbors_events(lat DOUBLE PRECISION, lng DOUBLE PRECISION, radius DOUBLE PRECISION)
RETURNS TABLE (
  id UUID,
  title TEXT,
  description TEXT,
  category TEXT,
  latitude DOUBLE PRECISION,
  longitude DOUBLE PRECISION,
  city TEXT,
  state TEXT,
  start_time TIMESTAMPTZ,
  end_time TIMESTAMPTZ,
  duration_minutes INTEGER,
  max_participants INTEGER,
  reward_coins INTEGER,
  created_by_user_id UUID,
  business_id UUID,
  status TEXT,
  created_at TIMESTAMPTZ,
  distance DOUBLE PRECISION
) AS $$
BEGIN
  RETURN QUERY
  SELECT
    ne.*,
    ST_Distance(
      ST_GeographyFromText('POINT(' || lng || ' ' || lat || ')'),
      ST_GeographyFromText('POINT(' || ne.longitude || ' ' || ne.latitude || ')')
    ) / 1000 AS distance
  FROM neighbors_events ne
  WHERE
    ne.status = 'active'
    AND ST_Distance(
      ST_GeographyFromText('POINT(' || lng || ' ' || lat || ')'),
      ST_GeographyFromText('POINT(' || ne.longitude || ' ' || ne.latitude || ')')
    ) / 1000 <= radius;
END;
$$ LANGUAGE plpgsql STABLE;

-- Create function to verify event completion and reward coins
CREATE OR REPLACE FUNCTION verify_event_participation(participant_id UUID)
RETURNS BOOLEAN AS $$
DECLARE
  v_participant neighbors_participants;
  v_event neighbors_events;
BEGIN
  -- Get participant and event details
  SELECT * INTO v_participant FROM neighbors_participants WHERE id = participant_id;
  SELECT * INTO v_event FROM neighbors_events WHERE id = v_participant.event_id;

  -- Check if participant has completed the event
  IF v_participant.status != 'completed' THEN
    RETURN FALSE;
  END IF;

  -- Check if participant is already verified
  IF v_participant.verified THEN
    RETURN FALSE;
  END IF;

  -- Update participant status to verified
  UPDATE neighbors_participants
  SET verified = TRUE
  WHERE id = participant_id;

  -- Add reward coins to user balance
  UPDATE user_profiles
  SET coins = coins + v_event.reward_coins
  WHERE user_id = v_participant.user_id;

  -- Log transaction (assuming there's a transactions table)
  INSERT INTO wallet_transactions (
    user_id,
    type,
    amount,
    description,
    source
  ) VALUES (
    v_participant.user_id,
    'credit',
    v_event.reward_coins,
    'Event participation reward: ' || v_event.title,
    'events'
  );

  RETURN TRUE;
END;
$$ LANGUAGE plpgsql VOLATILE;

s are
-- Featured Broadcast System
-- Tracks featured broadcasts, top 100 rankings, and weekly top saved for Universe Events

-- Table to track featured broadcasts (1000+ likes, 2000+ gifts)
CREATE TABLE IF NOT EXISTS featured_broadcasts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id),
  likes_count INTEGER DEFAULT 0,
  gifts_value INTEGER DEFAULT 0,
  featured_at TIMESTAMPTZ DEFAULT NOW(),
  is_featured BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table for hourly top 100 rankings
CREATE TABLE IF NOT EXISTS broadcast_rankings (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id UUID NOT NULL REFERENCES streams(id) ON DELETE CASCADE,
  user_id UUID NOT NULL REFERENCES auth.users(id),
  rank_position INTEGER NOT NULL,
  likes_count INTEGER DEFAULT 0,
  gifts_value INTEGER DEFAULT 0,
  viewer_count INTEGER DEFAULT 0,
  total_score INTEGER DEFAULT 0,
  ranking_hour TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Table to save weekly top featured broadcasters for Universe Events
CREATE TABLE IF NOT EXISTS weekly_top_broadcasters (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id),
  week_start_date DATE NOT NULL,
  week_end_date DATE NOT NULL,
  rank_position INTEGER NOT NULL,
  total_likes INTEGER DEFAULT 0,
  total_gifts INTEGER DEFAULT 0,
  total_viewers INTEGER DEFAULT 0,
  avg_viewers INTEGER DEFAULT 0,
  is_universe_invited BOOLEAN DEFAULT FALSE,
  universe_event_id UUID,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, week_start_date)
);

-- Enable RLS
ALTER TABLE featured_broadcasts ENABLE ROW LEVEL SECURITY;
ALTER TABLE broadcast_rankings ENABLE ROW LEVEL SECURITY;
ALTER TABLE weekly_top_broadcasters ENABLE ROW LEVEL SECURITY;

-- RLS Policies for featured_broadcasts
CREATE POLICY "Anyone can view featured broadcasts"
ON featured_broadcasts FOR SELECT USING (is_featured = true);

CREATE POLICY "System can manage featured broadcasts"
ON featured_broadcasts FOR ALL USING (
  auth.uid() IN (SELECT id FROM auth.users WHERE email LIKE '%@system%')
  OR auth.uid() IN (SELECT user_id FROM user_roles WHERE role = 'admin')
);

-- RLS Policies for broadcast_rankings
CREATE POLICY "Anyone can view rankings"
ON broadcast_rankings FOR SELECT USING (true);

CREATE POLICY "System can manage rankings"
ON broadcast_rankings FOR ALL USING (
  auth.uid() IN (SELECT id FROM auth.users WHERE email LIKE '%@system%')
  OR auth.uid() IN (SELECT user_id FROM user_roles WHERE role = 'admin')
);

-- RLS Policies for weekly_top_broadcasters
CREATE POLICY "Anyone can view weekly top"
ON weekly_top_broadcasters FOR SELECT USING (true);

CREATE POLICY "System can manage weekly top"
ON weekly_top_broadcasters FOR ALL USING (
  auth.uid() IN (SELECT id FROM auth.users WHERE email LIKE '%@system%')
  OR auth.uid() IN (SELECT user_id FROM user_roles WHERE role = 'admin')
);

-- Add columns to streams table if they don't exist
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'streams' AND column_name = 'likes_count'
  ) THEN
    ALTER TABLE streams ADD COLUMN likes_count INTEGER DEFAULT 0;
  END IF;
  
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'streams' AND column_name = 'gifts_value'
  ) THEN
    ALTER TABLE streams ADD COLUMN gifts_value INTEGER DEFAULT 0;
  END IF;
  
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'streams' AND column_name = 'is_featured'
  ) THEN
    ALTER TABLE streams ADD COLUMN is_featured BOOLEAN DEFAULT FALSE;
  END IF;
  
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'streams' AND column_name = 'featured_until'
  ) THEN
    ALTER TABLE streams ADD COLUMN featured_until TIMESTAMPTZ;
  END IF;
  
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'streams' AND column_name = 'boosted_until'
  ) THEN
    ALTER TABLE streams ADD COLUMN boosted_until TIMESTAMPTZ;
  END IF;
  
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'streams' AND column_name = 'featured_at'
  ) THEN
    ALTER TABLE streams ADD COLUMN featured_at TIMESTAMPTZ;
  END IF;
  
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'streams' AND column_name = 'featured_by'
  ) THEN
    ALTER TABLE streams ADD COLUMN featured_by UUID REFERENCES auth.users(id);
  END IF;
END
$$;

-- Function: get_officer_payroll_stats
CREATE OR REPLACE FUNCTION get_officer_payroll_stats()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  pool_balance bigint;
  weekly_earnings bigint;
  weekly_payouts bigint;
  distributions jsonb;
BEGIN
  -- Check permissions
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid() AND (role IN ('admin', 'secretary', 'president', 'troll_officer', 'lead_officer', 'chief_officer') OR is_admin = true)
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Pool Balance (Sum of all transactions)
  SELECT COALESCE(SUM(coin_amount), 0) INTO pool_balance
  FROM public.officer_pay_ledger;
  
  -- Weekly Earnings (Inflows > 0 this week)
  SELECT COALESCE(SUM(coin_amount), 0) INTO weekly_earnings
  FROM public.officer_pay_ledger
  WHERE created_at >= date_trunc('week', now())
  AND coin_amount > 0;

  -- Weekly Payouts (Outflows < 0 this week, e.g. payouts)
  SELECT COALESCE(ABS(SUM(coin_amount)), 0) INTO weekly_payouts
  FROM public.officer_pay_ledger
  WHERE created_at >= date_trunc('week', now())
  AND coin_amount < 0;

  -- Get Active Distributions
  SELECT jsonb_agg(d) INTO distributions
  FROM (
    SELECT 
      od.officer_user_id,
      up.username,
      od.percentage_share,
      od.role
    FROM public.officer_distribution od
    JOIN public.user_profiles up ON up.id = od.officer_user_id
    WHERE od.is_active = true
    ORDER BY od.percentage_share DESC
  ) d;

  RETURN jsonb_build_object(
    'pool_balance', pool_balance,
    'weekly_earnings', weekly_earnings,
    'weekly_payouts', weekly_payouts,
    'distributions', COALESCE(distributions, '[]'::jsonb)
  );
END;
$$;

-- Function: get_or_create_wheel_session
CREATE OR REPLACE FUNCTION public.get_or_create_wheel_session()
RETURNS TABLE(
  id UUID,
  user_id UUID,
  session_start TIMESTAMPTZ,
  bankrupt_landed BOOLEAN,
  total_spins INTEGER
) AS $$
DECLARE
  v_session RECORD;
  v_user_id UUID;
  v_today DATE;
BEGIN
  SELECT auth.uid() INTO v_user_id;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_today := CURRENT_DATE;

  -- Check for existing session today (fully qualified column reference)
  SELECT * INTO v_session
  FROM wheel_sessions
  WHERE wheel_sessions.user_id = v_user_id
    AND DATE(wheel_sessions.session_start) = v_today
  ORDER BY wheel_sessions.session_start DESC
  LIMIT 1;

  -- Create new session if none exists
  IF v_session IS NULL THEN
    INSERT INTO wheel_sessions (user_id, session_start, bankrupt_landed, total_spins)
    VALUES (v_user_id, NOW(), false, 0)
    RETURNING * INTO v_session;
  END IF;

  -- Return session data
  RETURN QUERY
    SELECT v_session.id, v_session.user_id, v_session.session_start, v_session.bankrupt_landed, v_session.total_spins;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.get_or_create_wheel_session TO authenticated;

-- Fix SQL 42803: aggregate function calls cannot be nested
-- Fixes three functions that use SUM/COUNT inside jsonb_agg (nested aggregates)
-- Solution: pre-aggregate via CTE/subquery, then apply jsonb_agg on pre-aggregated results

-- ============================================================
-- 1. Fix get_cashout_request_details: fallback path (lines 748-774 of original)
-- ============================================================
-- Find the function and get its full definition, then fix only the nested aggregate part.
-- We use CREATE OR REPLACE to update the function body.

-- We need to read the full function to replace it. Let's find the complete function:
-- (The function name is get_cashout_request_details)
-- Since we can't easily get the exact full body from the audit, we fix just the
-- problematic pattern by creating a helper function and updating the main one.

-- First create a helper function to build the gift breakdown safely
CREATE OR REPLACE FUNCTION public.build_gift_breakdown_from_transactions(p_user_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_result JSONB;
BEGIN
    WITH sender_totals AS (
        SELECT
            from_user_id,
            from_user_name,
            SUM(amount) AS total_coins,
            COUNT(*) AS gift_count
        FROM public.coin_transactions
        WHERE user_id = p_user_id
          AND type = 'gift_received'
          AND amount > 0
          AND (metadata->>'is_friday_bonus') IS NOT DISTINCT FROM NULL
        GROUP BY from_user_id, from_user_name
    )
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'sender_id', from_user_id,
                'sender_username', from_user_name,
                'total_coins', total_coins,
                'gift_count', gift_count,
                'coin_type', 'paid',
                'is_eligible', TRUE,
                'is_manually_verified', FALSE,
                'verified_by', NULL,
                'verified_at', NULL,
                'notes', NULL
            )
            ORDER BY total_coins DESC
        ),
        '[]'::jsonb
    )
    INTO v_result
    FROM sender_totals;

    RETURN v_result;
END;
$$;

-- Function: get_pending_payouts_for_review
CREATE OR REPLACE FUNCTION public.get_pending_payouts_for_review()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_result JSONB;
BEGIN
    WITH payout_data AS (
        SELECT
            p.id,
            p.user_id,
            up.username,
            up.display_name,
            up.role,
            p.coin_amount,
            p.cash_amount,
            p.net_amount,
            p.provider_type,
            p.provider_username,
            p.user_tag,
            p.status,
            p.created_at,
            COALESCE(up.troll_coins, 0) AS troll_coins_balance,
            COALESCE(w.total_earned_this_week, 0) AS total_earned_this_week
        FROM public.payout_requests p
        JOIN public.user_profiles up ON up.id = p.user_id
        LEFT JOIN LATERAL (
            SELECT SUM(w.amount_coins) AS total_earned_this_week
            FROM public.weekly_working_earnings w
            WHERE w.user_id = p.user_id
              AND w.status IN ('pending', 'converted')
              AND w.week_start = date_trunc('week', CURRENT_DATE)::date
        ) w ON TRUE
        WHERE p.status = 'pending'
          AND p.forwarded_to_admin = FALSE
    ),
    aggregated AS (
        SELECT
            COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'id', pd.id,
                        'user_id', pd.user_id,
                        'username', pd.username,
                        'display_name', pd.display_name,
                        'role', pd.role,
                        'coin_amount', pd.coin_amount,
                        'cash_amount', pd.cash_amount,
                        'net_amount', pd.net_amount,
                        'provider_type', pd.provider_type,
                        'provider_username', pd.provider_username,
                        'user_tag', pd.user_tag,
                        'status', pd.status,
                        'created_at', pd.created_at,
                        'troll_coins_balance', pd.troll_coins_balance,
                        'total_earned_this_week', pd.total_earned_this_week
                    )
                    ORDER BY pd.created_at ASC
                ),
                '[]'::jsonb
            ) AS payouts_json,
            COUNT(pd.id) AS total_pending,
            COALESCE(SUM(pd.coin_amount), 0) AS total_coins,
            COALESCE(SUM(pd.cash_amount), 0) AS total_cash
        FROM payout_data pd
    )
    SELECT jsonb_build_object(
        'success', true,
        'payouts', payouts_json,
        'total_pending', total_pending,
        'total_coins', total_coins,
        'total_cash', total_cash
    )
    INTO v_result
    FROM aggregated;

    RETURN v_result;
END;
$$;

