-- Function: get_seller_reviews
CREATE OR REPLACE FUNCTION public.get_seller_reviews(
    p_seller_id UUID,
    p_limit INTEGER DEFAULT 20,
    p_offset INTEGER DEFAULT 0
)
RETURNS TABLE (
    id UUID,
    order_id UUID,
    buyer_id UUID,
    listing_id UUID,
    listing_type TEXT,
    rating INTEGER,
    comment TEXT,
    images JSONB,
    delivery_rating INTEGER,
    item_as_described BOOLEAN,
    would_recommend BOOLEAN,
    is_verified_purchase BOOLEAN,
    created_at TIMESTAMPTZ,
    buyer_username TEXT,
    buyer_avatar TEXT
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id,
        r.order_id,
        r.buyer_id,
        r.listing_id,
        r.listing_type,
        r.rating,
        r.comment,
        r.images,
        r.delivery_rating,
        r.item_as_described,
        r.would_recommend,
        r.is_verified_purchase,
        r.created_at,
        u.username as buyer_username,
        u.avatar_url as buyer_avatar
    FROM public.marketplace_reviews r
    JOIN public.user_profiles u ON r.buyer_id = u.id
    WHERE r.seller_id = p_seller_id
    ORDER BY r.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;

-- Function: get_state_leaderboard
CREATE OR REPLACE FUNCTION public.get_state_leaderboard(p_limit INTEGER DEFAULT 50)
RETURNS TABLE (
    rank BIGINT,
    state_code TEXT,
    state_name TEXT,
    battle_points BIGINT,
    wins INTEGER,
    losses INTEGER,
    representative_user_id UUID,
    representative_username TEXT
)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT
        ROW_NUMBER() OVER (ORDER BY s.battle_points DESC, s.wins DESC)::BIGINT as rank,
        s.state_code,
        s.state_name,
        s.battle_points,
        s.wins,
        s.losses,
        s.representative_user_id,
        up.username as representative_username
    FROM public.states s
    LEFT JOIN public.user_profiles up ON up.id = s.representative_user_id
    ORDER BY s.battle_points DESC, s.wins DESC
    LIMIT p_limit;
END;
$$;

-- Function: get_stream_seats
CREATE OR REPLACE FUNCTION public.get_stream_seats(p_stream_id UUID)
RETURNS TABLE (
    id UUID,
    seat_index INTEGER,
    user_id UUID,
    guest_id TEXT,
    status TEXT,
    joined_at TIMESTAMPTZ,
    left_at TIMESTAMPTZ,
    livekit_participant_identity TEXT,
    price_paid INTEGER,
    username TEXT,
    display_name TEXT,
    avatar_url TEXT,
    is_gold BOOLEAN,
    role TEXT,
    troll_coins BIGINT,
    rgb_username_expires_at TIMESTAMPTZ,
    glowing_username_color TEXT,
    troll_role TEXT,
    created_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN QUERY
    SELECT
        s.id::UUID,
        s.seat_index::INTEGER,
        s.user_id::UUID,
        s.guest_id::TEXT,
        s.status::TEXT,
        s.joined_at::TIMESTAMPTZ,
        s.left_at::TIMESTAMPTZ,
        s.livekit_participant_identity::TEXT,
        s.price_paid::INTEGER,
        (CASE
            WHEN s.user_id IS NOT NULL THEN COALESCE(u.username, 'Unknown')
            ELSE COALESCE(s.guest_id, 'Guest')
        END)::TEXT as username,
        (CASE
            WHEN s.user_id IS NOT NULL THEN COALESCE(u.display_name, u.username)
            ELSE COALESCE(s.guest_id, 'Guest')
        END)::TEXT as display_name,
        (CASE
            WHEN s.user_id IS NOT NULL THEN COALESCE(u.avatar_url, 'https://ui-avatars.com/api/?name=' || COALESCE(u.username, 'User') || '&background=random')
            ELSE 'https://ui-avatars.com/api/?name=' || COALESCE(s.guest_id, 'Guest') || '&background=random'
        END)::TEXT as avatar_url,
        COALESCE(u.is_gold, false)::BOOLEAN as is_gold,
        COALESCE(u.role, 'guest')::TEXT as role,
        COALESCE(u.troll_coins, 0)::BIGINT as troll_coins,
        u.rgb_username_expires_at::TIMESTAMPTZ,
        u.glowing_username_color::TEXT,
        u.troll_role::TEXT,
        u.created_at::TIMESTAMPTZ
    FROM public.stream_seat_sessions s
    LEFT JOIN public.user_profiles u ON s.user_id = u.id
    WHERE s.stream_id = p_stream_id
    AND s.status IN ('active', 'live', 'reserved', 'camera_starting');
END;
$$;

-- Function: get_tromail_admin
CREATE OR REPLACE FUNCTION get_tromail_admin(p_user_id UUID)
RETURNS TABLE(
  id UUID,
  message_id UUID,
  recipient_user_id UUID,
  recipient_role TEXT,
  recipient_tromail_address TEXT,
  read_at TIMESTAMP WITH TIME ZONE,
  archived_at TIMESTAMP WITH TIME ZONE,
  deleted_at TIMESTAMP WITH TIME ZONE,
  is_starred BOOLEAN,
  created_at TIMESTAMP WITH TIME ZONE,
  sender_user_id UUID,
  sender_role TEXT,
  sender_tromail_address TEXT,
  subject TEXT,
  body TEXT,
  is_admin_email BOOLEAN,
  is_important BOOLEAN,
  related_meeting_id UUID,
  message_created_at TIMESTAMP WITH TIME ZONE,
  message_updated_at TIMESTAMP WITH TIME ZONE,
  sender_username TEXT
)
LANGUAGE sql
AS $$
  SELECT
    tr.id,
    tr.message_id,
    tr.recipient_user_id,
    tr.recipient_role,
    tr.recipient_tromail_address,
    tr.read_at,
    tr.archived_at,
    tr.deleted_at,
    tr.is_starred,
    tr.created_at,
    tm.sender_user_id,
    tm.sender_role,
    tm.sender_tromail_address,
    tm.subject,
    tm.body,
    tm.is_admin_email,
    tm.is_important,
    tm.related_meeting_id,
    tm.created_at as message_created_at,
    tm.updated_at as message_updated_at,
    up.username as sender_username
  FROM tromail_recipients tr
  JOIN tromail_messages tm ON tm.id = tr.message_id
  LEFT JOIN user_profiles up ON up.id = tm.sender_user_id
  WHERE tr.recipient_user_id = p_user_id
  AND tr.deleted_at IS NULL
  AND tm.is_admin_email = true
  ORDER BY tr.created_at DESC;
$$;

