-- Function: get_unread_notification_count
CREATE OR REPLACE FUNCTION get_unread_notification_count(p_user_id UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN (
    SELECT COUNT(*)::INTEGER
    FROM notifications
    WHERE user_id = p_user_id
      AND is_read = FALSE
      AND (is_dismissed = FALSE OR is_dismissed IS NULL)
  );
END;
$$;

-- Function: get_user_conversations_optimized
CREATE OR REPLACE FUNCTION get_user_conversations_optimized(p_user_id UUID)
RETURNS TABLE (
  conversation_id UUID,
  other_user_id UUID,
  other_username TEXT,
  other_avatar_url TEXT,
  last_message TEXT,
  last_timestamp TIMESTAMPTZ,
  unread_count BIGINT,
  is_online BOOLEAN,
  rgb_username_expires_at TIMESTAMPTZ,
  glowing_username_color TEXT,
  other_created_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  WITH user_conversations AS (
    SELECT cm.conversation_id AS conv_id
    FROM conversation_members cm
    WHERE cm.user_id = p_user_id
  ),
  other_members AS (
    SELECT 
      cm.conversation_id AS conv_id,
      cm.user_id AS other_user_id,
      up.username AS other_username,
      COALESCE(up.avatar_url, '') AS other_avatar_url,
      COALESCE(up.rgb_username_expires_at, '1970-01-01'::TIMESTAMPTZ) AS rgb_username_expires_at,
      COALESCE(up.glowing_username_color, '') AS glowing_username_color,
      COALESCE(up.created_at, NOW()) AS other_created_at
    FROM conversation_members cm
    LEFT JOIN user_profiles up ON cm.user_id = up.id
    WHERE cm.conversation_id IN (SELECT uc.conv_id FROM user_conversations uc)
      AND cm.user_id != p_user_id
  ),
  last_messages AS (
    SELECT DISTINCT ON (msg.conversation_id)
      msg.conversation_id AS conv_id,
      msg.content AS last_message,
      msg.created_at AS last_timestamp
    FROM tcps_messages msg
    WHERE msg.conversation_id IN (SELECT uc.conv_id FROM user_conversations uc)
      AND msg.is_deleted = FALSE
    ORDER BY msg.conversation_id, msg.created_at DESC
  ),
  unread_counts AS (
    SELECT
      msg.conversation_id AS conv_id,
      COUNT(*)::BIGINT AS unread_count
    FROM tcps_messages msg
    WHERE msg.conversation_id IN (SELECT uc.conv_id FROM user_conversations uc)
      AND msg.sender_id != p_user_id
      AND msg.read_at IS NULL
      AND msg.is_deleted = FALSE
    GROUP BY msg.conversation_id
  )
  SELECT 
    om.conv_id,
    om.other_user_id,
    om.other_username,
    om.other_avatar_url,
    COALESCE(lm.last_message, 'No messages yet'::TEXT),
    COALESCE(lm.last_timestamp, '1970-01-01'::TIMESTAMPTZ),
    COALESCE(uc.unread_count, 0::BIGINT),
    FALSE,
    om.rgb_username_expires_at,
    om.glowing_username_color,
    om.other_created_at
  FROM other_members om
  LEFT JOIN last_messages lm ON om.conv_id = lm.conv_id
  LEFT JOIN unread_counts uc ON om.conv_id = uc.conv_id

  ORDER BY lm.last_timestamp DESC NULLS LAST;
END;
$$;

-- Function: get_user_promo_cards
CREATE OR REPLACE FUNCTION public.get_user_promo_cards(
  p_user_id uuid DEFAULT auth.uid()
)
RETURNS TABLE (
  id uuid,
  code text,
  token_amount numeric,
  source_type text,
  issued_at timestamptz,
  expires_at timestamptz,
  redeemed_at timestamptz,
  status text,
  metadata jsonb,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO public
AS $$
  SELECT
    id, code, token_amount, source_type, issued_at, expires_at,
    redeemed_at, status, metadata, created_at, updated_at
  FROM public.promo_cards
  WHERE user_id = p_user_id
  ORDER BY issued_at DESC;
$$;

-- Function: get_user_rewards
CREATE OR REPLACE FUNCTION get_user_rewards()
RETURNS TABLE (
    id UUID,
    reward_type TEXT,
    reward_amount INTEGER,
    vip_tier TEXT,
    vip_duration_days INTEGER,
    gift_pack_discount INTEGER,
    is_claimed BOOLEAN,
    claimed_at TIMESTAMPTZ,
    giveaway_title TEXT,
    created_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        r.id,
        r.reward_type,
        r.reward_amount,
        r.vip_tier,
        r.vip_duration_days,
        r.gift_pack_discount,
        r.is_claimed,
        r.claimed_at,
        g.title AS giveaway_title,
        r.created_at
    FROM user_rewards r
    LEFT JOIN giveaways g ON g.id = r.giveaway_id
    WHERE r.user_id = auth.uid()
    ORDER BY r.created_at DESC;
END;
$$;

-- Function: get_user_state
CREATE OR REPLACE FUNCTION public.get_user_state(p_user_id UUID)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
    v_state TEXT;
BEGIN
    -- Check if user already has a state assigned
    SELECT state_code INTO v_state
    FROM public.state_members
    WHERE user_id = p_user_id;

    -- If not assigned, try to derive from profile state_region
    IF v_state IS NULL THEN
        SELECT state_region INTO v_state
        FROM public.user_profiles
        WHERE id = p_user_id AND state_region IS NOT NULL AND state_region != '';

        -- If we found a state, assign the user
        IF v_state IS NOT NULL THEN
            INSERT INTO public.state_members (user_id, state_code)
            VALUES (p_user_id, v_state)
            ON CONFLICT (user_id) DO UPDATE SET state_code = v_state;
        END IF;
    END IF;

    RETURN v_state;
END;
$$;

-- Function: get_user_storage_replay_status
CREATE OR REPLACE FUNCTION public.get_user_storage_replay_status(p_user_id UUID)
RETURNS JSONB AS $$
DECLARE
    v_plan_tier_label TEXT;
    v_plan_monthly_fee INTEGER;
    v_plan_bytes_granted BIGINT;
    v_plan_is_active BOOLEAN;
    v_plan_next_billing_at TIMESTAMPTZ;
    v_plan_top_up_bytes BIGINT;
    v_plan_credit_bytes BIGINT;

    v_usage_total_bytes BIGINT;

    v_replay_balance BIGINT;
    v_replay_minutes_today INTEGER;
    v_replay_minutes_this_month INTEGER;
    v_replay_coins_charged_today BIGINT;
    v_replay_coins_charged_this_month BIGINT;
    v_replay_status TEXT;

    v_total_limit BIGINT;
    v_total_used BIGINT;
    v_total_available BIGINT;
    v_storage_pct NUMERIC;
    v_renewal_date TEXT;
BEGIN
    SELECT tier_label, monthly_fee, bytes_granted, is_active, next_billing_at, top_up_bytes, credit_bytes
    INTO v_plan_tier_label, v_plan_monthly_fee, v_plan_bytes_granted, v_plan_is_active, v_plan_next_billing_at, v_plan_top_up_bytes, v_plan_credit_bytes
    FROM public.user_storage_purchases
    WHERE user_id = p_user_id AND is_active = true
    ORDER BY purchased_at DESC
    LIMIT 1;

    IF NOT FOUND OR v_plan_is_active IS NULL THEN
        RETURN jsonb_build_object(
            'has_plan', false,
            'plan_label', '', 'plan_storage_bytes', 0, 'top_up_bytes', 0, 'credit_bytes', 0,
            'total_limit_bytes', 0, 'total_used_bytes', 0, 'total_available_bytes', 0,
            'storage_percentage', 0, 'renewal_date', NULL, 'monthly_fee', 0,
            'replay_balance', 0, 'replay_minutes_today', 0, 'replay_minutes_month', 0,
            'replay_coins_today', 0, 'replay_coins_month', 0, 'replay_status', 'active',
            'replay_cost_per_minute', 5
        );
    END IF;

    SELECT total_bytes INTO v_usage_total_bytes
    FROM public.user_storage_usage
    WHERE user_id = p_user_id;

    SELECT balance, minutes_today, minutes_this_month, coins_charged_today, coins_charged_this_month, status
    INTO v_replay_balance, v_replay_minutes_today, v_replay_minutes_this_month, v_replay_coins_charged_today, v_replay_coins_charged_this_month, v_replay_status
    FROM public.replay_balances
    WHERE user_id = p_user_id;

    v_total_limit := COALESCE(v_plan_bytes_granted, 0) + COALESCE(v_plan_top_up_bytes, 0) + COALESCE(v_plan_credit_bytes, 0);
    v_total_used := COALESCE(v_usage_total_bytes, 0);
    v_total_available := GREATEST(0, v_total_limit - v_total_used);
    v_storage_pct := CASE WHEN v_total_limit > 0 THEN ROUND((v_total_used::NUMERIC / v_total_limit::NUMERIC) * 100, 1) ELSE 0 END;
    v_renewal_date := CASE WHEN v_plan_next_billing_at IS NOT NULL THEN v_plan_next_billing_at::TEXT ELSE NULL END;

    RETURN jsonb_build_object(
        'has_plan', true,
        'plan_label', v_plan_tier_label,
        'plan_storage_bytes', v_plan_bytes_granted,
        'top_up_bytes', COALESCE(v_plan_top_up_bytes, 0),
        'credit_bytes', COALESCE(v_plan_credit_bytes, 0),
        'total_limit_bytes', v_total_limit,
        'total_used_bytes', v_total_used,
        'total_available_bytes', v_total_available,
        'storage_percentage', v_storage_pct,
        'renewal_date', v_renewal_date,
        'monthly_fee', v_plan_monthly_fee,
        'replay_balance', COALESCE(v_replay_balance, 0),
        'replay_minutes_today', COALESCE(v_replay_minutes_today, 0),
        'replay_minutes_month', COALESCE(v_replay_minutes_this_month, 0),
        'replay_coins_today', COALESCE(v_replay_coins_charged_today, 0),
        'replay_coins_month', COALESCE(v_replay_coins_charged_this_month, 0),
        'replay_status', COALESCE(v_replay_status, 'active'),
        'replay_cost_per_minute', 5
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 8. RPC: CHECK IF USER CAN RECORD
CREATE OR REPLACE FUNCTION public.can_user_record(p_user_id UUID)
RETURNS JSONB AS $$
DECLARE
    v_plan RECORD;
    v_usage RECORD;
    v_total_limit BIGINT;
    v_total_used BIGINT;
    v_replay_status TEXT;
BEGIN
    -- Admins can always record
    IF EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = p_user_id
        AND (role = 'admin' OR is_admin = true OR role = 'superadmin' OR is_superadmin = true)
    ) THEN
        RETURN jsonb_build_object('can_record', true, 'reason', 'admin');
    END IF;

    -- Check for active storage plan
    SELECT * INTO v_plan
    FROM public.user_storage_purchases
    WHERE user_id = p_user_id AND is_active = true
    ORDER BY purchased_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('can_record', false, 'reason', 'no_plan', 'action', 'purchase_storage');
    END IF;

    -- Check storage remaining
    SELECT * INTO v_usage
    FROM public.user_storage_usage
    WHERE user_id = p_user_id;

    v_total_limit := COALESCE(v_plan.bytes_granted, 0) + COALESCE(v_plan.top_up_bytes, 0) + COALESCE(v_plan.credit_bytes, 0);
    v_total_used := COALESCE(v_usage.total_bytes, 0);

    IF v_total_used >= v_total_limit THEN
        RETURN jsonb_build_object('can_record', false, 'reason', 'storage_full', 'action', 'upgrade_storage');
    END IF;

    -- Check replay balance status
    SELECT status INTO v_replay_status
    FROM public.replay_balances
    WHERE user_id = p_user_id;

    IF v_replay_status = 'restricted' THEN
        RETURN jsonb_build_object('can_record', false, 'reason', 'replay_restricted', 'action', 'add_replay_balance');
    END IF;

    RETURN jsonb_build_object(
        'can_record', true,
        'storage_available_gb', ROUND(GREATEST(0, v_total_limit - v_total_used)::NUMERIC / (1024*1024*1024), 2)
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 9. RPC: RECORD REPLAY VIEW (called when viewer watches recorded content)
CREATE OR REPLACE FUNCTION public.record_replay_view(
    p_creator_user_id UUID,
    p_stream_id UUID,
    p_viewer_user_id UUID DEFAULT NULL,
    p_minutes_watched NUMERIC DEFAULT 1
)
RETURNS JSONB AS $$
DECLARE
    v_cost BIGINT;
    v_balance BIGINT;
    v_new_balance BIGINT;
BEGIN
    -- Admins are exempt from replay charges
    IF EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = p_creator_user_id
        AND (role = 'admin' OR is_admin = true OR role = 'superadmin' OR is_superadmin = true)
    ) THEN
        RETURN jsonb_build_object('success', true, 'charged', false, 'reason', 'admin_exempt');
    END IF;

    -- Calculate cost: 5 coins per minute
    v_cost := (p_minutes_watched * 5)::BIGINT;

    -- Get or create replay balance
    INSERT INTO public.replay_balances (user_id, balance, minutes_today, minutes_this_month, coins_charged_today, coins_charged_this_month)
    VALUES (p_creator_user_id, 0, 0, 0, 0, 0)
    ON CONFLICT (user_id) DO NOTHING;

    -- Check balance
    SELECT balance INTO v_balance
    FROM public.replay_balances
    WHERE user_id = p_creator_user_id;

    IF v_balance < v_cost THEN
        -- Restrict the creator
        UPDATE public.replay_balances
        SET status = 'restricted', last_updated = NOW()
        WHERE user_id = p_creator_user_id;

        RETURN jsonb_build_object('success', false, 'error', 'Replay playback unavailable. Creator replay balance exhausted.', 'restricted', true);
    END IF;

    -- Deduct from creator's replay balance (comes from their troll_coins)
    SELECT troll_coins INTO v_new_balance
    FROM public.user_profiles
    WHERE id = p_creator_user_id;

    IF v_new_balance < v_cost THEN
        UPDATE public.replay_balances SET status = 'restricted', last_updated = NOW() WHERE user_id = p_creator_user_id;
        RETURN jsonb_build_object('success', false, 'error', 'Replay playback unavailable. Creator replay balance exhausted.', 'restricted', true);
    END IF;

    -- Deduct troll coins from creator
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - v_cost, updated_at = NOW()
    WHERE id = p_creator_user_id;

    -- Record coin transaction
    INSERT INTO public.coin_transactions (user_id, amount, type, description, metadata)
    VALUES (p_creator_user_id, -v_cost, 'replay_view',
            format('Replay view: %s min on stream %s', p_minutes_watched, p_stream_id),
            jsonb_build_object('stream_id', p_stream_id, 'minutes', p_minutes_watched, 'cost', v_cost));

    -- Update replay balance tracking
    UPDATE public.replay_balances
    SET balance = balance - v_cost,
        minutes_today = minutes_today + p_minutes_watched::INTEGER,
        minutes_this_month = minutes_this_month + p_minutes_watched::INTEGER,
        coins_charged_today = coins_charged_today + v_cost,
        coins_charged_this_month = coins_charged_this_month + v_cost,
        last_updated = NOW()
    WHERE user_id = p_creator_user_id;

    -- Log playback
    INSERT INTO public.replay_playback_log (stream_id, creator_user_id, viewer_user_id, minutes_watched, coins_charged)
    VALUES (p_stream_id, p_creator_user_id, p_viewer_user_id, p_minutes_watched, v_cost);

    RETURN jsonb_build_object(
        'success', true,
        'charged', v_cost,
        'minutes_watched', p_minutes_watched,
        'remaining_balance', v_balance - v_cost
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 10. RPC: ADD REPLAY BALANCE (creator purchases replay coins)
CREATE OR REPLACE FUNCTION public.add_replay_balance(
    p_user_id UUID,
    p_coins_amount BIGINT
)
RETURNS JSONB AS $$
DECLARE
    v_current_balance BIGINT;
BEGIN
    IF p_coins_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid amount');
    END IF;

    -- Check user has enough troll coins
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = p_user_id AND troll_coins >= p_coins_amount
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not enough Troll Coins');
    END IF;

    -- Deduct troll coins
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - p_coins_amount, updated_at = NOW()
    WHERE id = p_user_id;

    -- Record transaction
    INSERT INTO public.coin_transactions (user_id, amount, type, description, metadata)
    VALUES (p_user_id, -p_coins_amount, 'replay_purchase',
            format('Replay balance purchase: %s coins', p_coins_amount),
            jsonb_build_object('coins', p_coins_amount));

    -- Add to replay balance
    INSERT INTO public.replay_balances (user_id, balance)
    VALUES (p_user_id, p_coins_amount)
    ON CONFLICT (user_id) DO UPDATE SET
        balance = replay_balances.balance + p_coins_amount,
        status = CASE WHEN replay_balances.status = 'restricted' AND replay_balances.balance + p_coins_amount > 0 THEN 'active' ELSE replay_balances.status END,
        last_updated = NOW();

    SELECT balance INTO v_current_balance FROM public.replay_balances WHERE user_id = p_user_id;

    RETURN jsonb_build_object('success', true, 'new_balance', v_current_balance, 'coins_spent', p_coins_amount);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 11. RPC: PURCHASE STORAGE TOP-UP
CREATE OR REPLACE FUNCTION public.purchase_storage_top_up(
    p_user_id UUID,
    p_gb_amount BIGINT,
    p_coins_cost BIGINT
)
RETURNS JSONB AS $$
DECLARE
    v_plan_id UUID;
BEGIN
    IF p_gb_amount <= 0 OR p_coins_cost <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid amount');
    END IF;

    -- Check user has enough troll coins
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = p_user_id AND troll_coins >= p_coins_cost
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not enough Troll Coins');
    END IF;

    -- Check user has an active plan
    SELECT id INTO v_plan_id
    FROM public.user_storage_purchases
    WHERE user_id = p_user_id AND is_active = true
    ORDER BY purchased_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'You need an active storage plan before purchasing top-ups');
    END IF;

    -- Deduct troll coins
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - p_coins_cost, updated_at = NOW()
    WHERE id = p_user_id;

    -- Record transaction
    INSERT INTO public.coin_transactions (user_id, amount, type, description, metadata)
    VALUES (p_user_id, -p_coins_cost, 'storage_top_up',
            format('Storage top-up: +%s GB', p_gb_amount),
            jsonb_build_object('gb_added', p_gb_amount, 'coins', p_coins_cost));

    -- Add top-up to plan
    UPDATE public.user_storage_purchases
    SET top_up_bytes = COALESCE(top_up_bytes, 0) + (p_gb_amount * 1024 * 1024 * 1024)
    WHERE id = v_plan_id;

    -- Log top-up
    INSERT INTO public.storage_top_ups (user_id, gb_added, coins_charged)
    VALUES (p_user_id, p_gb_amount, p_coins_cost);

    RETURN jsonb_build_object('success', true, 'gb_added', p_gb_amount, 'coins_spent', p_coins_cost);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 12. RPC: ADMIN GRANT STORAGE CREDIT
CREATE OR REPLACE FUNCTION public.admin_grant_storage_credit(
    p_target_user_id UUID,
    p_gb_amount BIGINT,
    p_reason TEXT DEFAULT 'Admin grant'
)
RETURNS JSONB AS $$
DECLARE
    v_admin_id UUID;
    v_plan_id UUID;
BEGIN
    v_admin_id := auth.uid();

    -- Only admins can grant credits
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = v_admin_id
        AND (role = 'admin' OR is_admin = true OR role = 'superadmin' OR is_superadmin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Only admins can grant storage credits');
    END IF;

    IF p_gb_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid amount');
    END IF;

    -- Find or create active plan for target user
    SELECT id INTO v_plan_id
    FROM public.user_storage_purchases
    WHERE user_id = p_target_user_id AND is_active = true
    ORDER BY purchased_at DESC
    LIMIT 1;

    IF NOT FOUND THEN
        -- Create a starter plan for them
        INSERT INTO public.user_storage_purchases (user_id, tier_index, tier_label, monthly_fee, bytes_granted, is_active, next_billing_at)
        VALUES (p_target_user_id, 0, 'Starter (Credit)', 0, 25 * 1024 * 1024 * 1024, true, NOW() + INTERVAL '30 days')
        RETURNING id INTO v_plan_id;
    END IF;

    -- Add credit to plan
    UPDATE public.user_storage_purchases
    SET credit_bytes = COALESCE(credit_bytes, 0) + (p_gb_amount * 1024 * 1024 * 1024)
    WHERE id = v_plan_id;

    -- Log credit
    INSERT INTO public.storage_credits (user_id, gb_amount, granted_by, reason, is_bonus)
    VALUES (p_target_user_id, p_gb_amount, v_admin_id, p_reason, true);

    RETURN jsonb_build_object('success', true, 'gb_granted', p_gb_amount, 'target_user', p_target_user_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 13. RPC: ADMIN GRANT REPLAY BALANCE
CREATE OR REPLACE FUNCTION public.admin_grant_replay_balance(
    p_target_user_id UUID,
    p_coins_amount BIGINT,
    p_reason TEXT DEFAULT 'Admin grant'
)
RETURNS JSONB AS $$
DECLARE
    v_admin_id UUID;
BEGIN
    v_admin_id := auth.uid();

    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = v_admin_id
        AND (role = 'admin' OR is_admin = true OR role = 'superadmin' OR is_superadmin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Only admins can grant replay balance');
    END IF;

    IF p_coins_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid amount');
    END IF;

    -- Add to replay balance
    INSERT INTO public.replay_balances (user_id, balance, status)
    VALUES (p_target_user_id, p_coins_amount, 'active')
    ON CONFLICT (user_id) DO UPDATE SET
        balance = replay_balances.balance + p_coins_amount,
        status = 'active',
        last_updated = NOW();

    RETURN jsonb_build_object('success', true, 'coins_granted', p_coins_amount, 'target_user', p_target_user_id);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 14. RPC: GET ALL CREATORS STORAGE & REPLAY STATUS (for admin dashboard)
CREATE OR REPLACE FUNCTION public.admin_get_all_storage_replay()
RETURNS TABLE (
    user_id UUID,
    username TEXT,
    plan_label TEXT,
    storage_limit_bytes BIGINT,
    storage_used_bytes BIGINT,
    storage_percentage NUMERIC,
    replay_balance BIGINT,
    replay_minutes_today INTEGER,
    replay_minutes_month INTEGER,
    replay_coins_month BIGINT,
    recording_count BIGINT,
    status TEXT,
    renewal_date TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        up.id,
        up.username,
        COALESCE(usp.tier_label, 'No Plan'),
        COALESCE(usp.bytes_granted, 0) + COALESCE(usp.top_up_bytes, 0) + COALESCE(usp.credit_bytes, 0),
        COALESCE(us.total_bytes, 0),
        CASE
            WHEN (COALESCE(usp.bytes_granted, 0) + COALESCE(usp.top_up_bytes, 0) + COALESCE(usp.credit_bytes, 0)) > 0
            THEN ROUND((COALESCE(us.total_bytes, 0)::NUMERIC / (COALESCE(usp.bytes_granted, 0) + COALESCE(usp.top_up_bytes, 0) + COALESCE(usp.credit_bytes, 0))::NUMERIC) * 100, 1)
            ELSE 0
        END,
        COALESCE(rb.balance, 0),
        COALESCE(rb.minutes_today, 0),
        COALESCE(rb.minutes_this_month, 0),
        COALESCE(rb.coins_charged_this_month, 0),
        (SELECT COUNT(*) FROM public.broadcast_replays br WHERE br.user_id = up.id),
        COALESCE(rb.status, 'active'),
        CASE WHEN usp.next_billing_at IS NOT NULL THEN usp.next_billing_at::TEXT ELSE NULL END
    FROM public.user_profiles up
    LEFT JOIN public.user_storage_purchases usp ON usp.user_id = up.id AND usp.is_active = true
    LEFT JOIN public.user_storage_usage us ON us.user_id = up.id
    LEFT JOIN public.replay_balances rb ON rb.user_id = up.id
    ORDER BY COALESCE(us.total_bytes, 0) DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 15. RPC: GET CREATOR RECORDING ANALYTICS
CREATE OR REPLACE FUNCTION public.get_recording_analytics(p_creator_user_id UUID)
RETURNS TABLE (
    stream_id UUID,
    title TEXT,
    duration_seconds INTEGER,
    file_size_bytes BIGINT,
    total_views BIGINT,
    replay_minutes NUMERIC,
    coins_charged BIGINT,
    created_at TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT
        br.stream_id,
        br.title,
        br.duration_seconds,
        br.file_size_bytes,
        COALESCE((SELECT COUNT(*) FROM public.replay_playback_log rpl WHERE rpl.stream_id = br.stream_id), 0),
        COALESCE((SELECT SUM(rpl.minutes_watched) FROM public.replay_playback_log rpl WHERE rpl.stream_id = br.stream_id), 0),
        COALESCE((SELECT SUM(rpl.coins_charged) FROM public.replay_playback_log rpl WHERE rpl.stream_id = br.stream_id), 0),
        br.created_at::TEXT
    FROM public.broadcast_replays br
    WHERE br.user_id = p_creator_user_id
    ORDER BY br.created_at DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 16. FUNCTION: RESET DAILY/MONTHLY REPLAY COUNTERS (call via cron)
CREATE OR REPLACE FUNCTION public.reset_replay_daily_counters()
RETURNS void AS $$
BEGIN
    UPDATE public.replay_balances
    SET minutes_today = 0, coins_charged_today = 0, last_updated = NOW();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION public.reset_replay_monthly_counters()
RETURNS void AS $$
BEGIN
    UPDATE public.replay_balances
    SET minutes_this_month = 0, coins_charged_this_month = 0, last_updated = NOW();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 17. RPC: ADMIN CREDIT ALL USERS (storage or replay) with notification
CREATE OR REPLACE FUNCTION public.admin_credit_all_users(
    p_gb_amount BIGINT DEFAULT 0,
    p_replay_coins BIGINT DEFAULT 0,
    p_reason TEXT DEFAULT 'Admin bonus'
)
RETURNS JSONB AS $$
DECLARE
    v_admin_id UUID;
    v_user RECORD;
    v_count INTEGER := 0;
BEGIN
    v_admin_id := auth.uid();

    -- Only admins can credit all users
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = v_admin_id
        AND (role = 'admin' OR is_admin = true OR role = 'superadmin' OR is_superadmin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Only admins can credit all users');
    END IF;

    IF p_gb_amount <= 0 AND p_replay_coins <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Must specify storage GB or replay coins amount');
    END IF;

    -- Credit each user
    FOR v_user IN SELECT id FROM public.user_profiles LOOP
        -- Grant storage if specified
        IF p_gb_amount > 0 THEN
            -- Find or create active plan
            DECLARE
                v_plan_id UUID;
            BEGIN
                SELECT id INTO v_plan_id
                FROM public.user_storage_purchases
                WHERE user_id = v_user.id AND is_active = true
                ORDER BY purchased_at DESC
                LIMIT 1;

                IF NOT FOUND THEN
                    INSERT INTO public.user_storage_purchases (user_id, tier_index, tier_label, monthly_fee, bytes_granted, is_active, next_billing_at)
                    VALUES (v_user.id, 0, 'Starter (Credit)', 0, 25 * 1024 * 1024 * 1024, true, NOW() + INTERVAL '30 days')
                    RETURNING id INTO v_plan_id;
                END IF;

                UPDATE public.user_storage_purchases
                SET credit_bytes = COALESCE(credit_bytes, 0) + (p_gb_amount * 1024 * 1024 * 1024)
                WHERE id = v_plan_id;

                INSERT INTO public.storage_credits (user_id, gb_amount, granted_by, reason, is_bonus)
                VALUES (v_user.id, p_gb_amount, v_admin_id, p_reason, true);
            END;
        END IF;

        -- Grant replay balance if specified
        IF p_replay_coins > 0 THEN
            INSERT INTO public.replay_balances (user_id, balance, status)
            VALUES (v_user.id, p_replay_coins, 'active')
            ON CONFLICT (user_id) DO UPDATE SET
                balance = replay_balances.balance + p_replay_coins,
                status = 'active',
                last_updated = NOW();
        END IF;

        -- Create notification for user
        INSERT INTO public.notifications (user_id, type, title, message, metadata, is_read)
        VALUES (
            v_user.id,
            'admin_credit',
            'Bonus Credits Received!',
            CASE
                WHEN p_gb_amount > 0 AND p_replay_coins > 0 THEN format('You received %s GB storage + %s replay coins from admin!', p_gb_amount, p_replay_coins)
                WHEN p_gb_amount > 0 THEN format('You received %s GB storage bonus from admin!', p_gb_amount)
                ELSE format('You received %s replay coins from admin!', p_replay_coins)
            END,
            jsonb_build_object('gb_amount', p_gb_amount, 'replay_coins', p_replay_coins, 'reason', p_reason),
            false
        );

        v_count := v_count + 1;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'users_credited', v_count, 'gb_per_user', p_gb_amount, 'replay_coins_per_user', p_replay_coins);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 18. Allow SECURITY DEFINER functions to insert notifications
DROP POLICY IF EXISTS "Service role can insert notifications" ON notifications;
CREATE POLICY "Service role can insert notifications" ON notifications FOR INSERT TO service_role WITH CHECK (true);
CREATE POLICY "Admins can insert notifications" ON notifications FOR INSERT TO authenticated WITH CHECK (
  EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND (role = 'admin' OR is_admin = true OR role = 'superadmin'))
);

-- Enable Realtime on utromail tables
-- Without this, postgres_changes subscriptions never fire for these tables

DO $$
BEGIN
  -- Add utromail_messages to realtime publication
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'utromail_messages'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.utromail_messages;
    RAISE NOTICE 'Added utromail_messages to supabase_realtime';
  END IF;

  -- Add utromail_notifications to realtime publication
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'utromail_notifications'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.utromail_notifications;
    RAISE NOTICE 'Added utromail_notifications to supabase_realtime';
  END IF;

  -- Add utromail_threads to realtime publication (for thread list updates)
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'utromail_threads'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.utromail_threads;
    RAISE NOTICE 'Added utromail_threads to supabase_realtime';
  END IF;

  -- Add utromail_thread_members to realtime publication
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'utromail_thread_members'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.utromail_thread_members;
    RAISE NOTICE 'Added utromail_thread_members to supabase_realtime';
  END IF;
END $$;

-- Function: get_user_vehicle_assets
CREATE OR REPLACE FUNCTION public.get_user_vehicle_assets(
  p_user_id UUID DEFAULT auth.uid()
)
RETURNS TABLE (
  id UUID,
  vehicle_name TEXT,
  tier TEXT,
  purchase_price NUMERIC,
  buyback_value NUMERIC,
  buyback_percentage NUMERIC,
  purchase_date TIMESTAMPTZ,
  image_url TEXT,
  status TEXT
)
LANGUAGE sql
SECURITY DEFINER
AS $$
  SELECT
    uva.id,
    COALESCE(vc.name, uva.vehicle_name) as vehicle_name,
    COALESCE(vc.tier, 'Unknown') as tier,
    uva.purchase_price,
    ROUND(uva.purchase_price * uva.buyback_percentage / 100) as buyback_value,
    uva.buyback_percentage,
    uva.purchase_date,
    vc.image_url,
    uva.status
  FROM public.user_vehicle_assets uva
  LEFT JOIN public.vehicle_catalog vc ON uva.catalog_id = vc.id
  WHERE uva.user_id = p_user_id AND uva.status = 'owned'
  ORDER BY uva.purchase_date DESC;
$$;

-- Function: get_vehicle_catalog
CREATE OR REPLACE FUNCTION public.get_vehicle_catalog()
RETURNS TABLE (
  vehicle_id TEXT,
  name TEXT,
  description TEXT,
  tier TEXT,
  image_url TEXT,
  base_price NUMERIC,
  buyback_value NUMERIC,
  buyback_percentage NUMERIC,
  stock_quantity NUMERIC
)
LANGUAGE sql
SECURITY DEFINER
AS $$
  SELECT
    vc.vehicle_id,
    vc.name,
    vc.description,
    vc.tier,
    vc.image_url,
    vc.base_price,
    ROUND(vc.base_price * vc.buyback_percentage / 100) as buyback_value,
    vc.buyback_percentage,
    CASE WHEN vc.stock_quantity < 0 THEN 999999 ELSE vc.stock_quantity END as stock_quantity
  FROM public.vehicle_catalog vc
  WHERE vc.is_active = true
  ORDER BY vc.base_price ASC;
$$;

-- Function: get_vehicle_transactions
CREATE OR REPLACE FUNCTION public.get_vehicle_transactions(
  p_user_id UUID DEFAULT auth.uid(),
  p_limit INTEGER DEFAULT 50,
  p_offset INTEGER DEFAULT 0
)
RETURNS TABLE (
  id UUID,
  transaction_type TEXT,
  vehicle_name TEXT,
  amount NUMERIC,
  metadata JSONB,
  created_at TIMESTAMPTZ
)
LANGUAGE sql
SECURITY DEFINER
AS $$
  SELECT
    vt.id,
    vt.transaction_type,
    vt.vehicle_name,
    vt.amount,
    vt.metadata,
    vt.created_at
  FROM public.vehicle_transactions vt
  WHERE vt.user_id = p_user_id
  ORDER BY vt.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
$$;

-- Function: get_viewed_me_users
CREATE OR REPLACE FUNCTION public.get_viewed_me_users(
    p_user_id UUID
)
RETURNS TABLE (
    viewer_id UUID,
    username TEXT,
    avatar_url TEXT,
    viewed_at TIMESTAMPTZ,
    is_online BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pv.viewer_id,
        up.username,
        up.avatar_url,
        pv.created_at as viewed_at,
        up.is_online
    FROM public.profile_views pv
    JOIN public.user_profiles up ON pv.viewer_id = up.id
    WHERE pv.viewed_user_id = p_user_id
    ORDER BY pv.created_at DESC;
END;
$$;

-- Function: get_viewer_mod_context
CREATE OR REPLACE FUNCTION public.get_viewer_mod_context(p_stream_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
STABLE
AS $$
DECLARE
    v_user       uuid := auth.uid();
    v_profile    public.user_profiles;
    v_is_host    boolean := false;
    v_clocked_in boolean := false;
    v_is_staff   boolean := false;
    v_is_bo      boolean := false;
BEGIN
    IF v_user IS NULL THEN
        RETURN jsonb_build_object('is_authenticated', false);
    END IF;

    SELECT * INTO v_profile FROM public.user_profiles WHERE id = v_user;

    IF p_stream_id IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1 FROM public.streams WHERE id = p_stream_id AND user_id = v_user
        ) INTO v_is_host;
        v_is_bo := public.is_stream_broadofficer(p_stream_id, v_user);
    END IF;

    v_clocked_in := public.is_staff_clocked_in(v_user);

    v_is_staff := COALESCE(v_profile.is_admin, false)
        OR COALESCE(v_profile.is_troll_officer, false)
        OR COALESCE(v_profile.is_lead_officer, false)
        OR COALESCE(v_profile.is_ceo, false)
        OR COALESCE(v_profile.is_secretary, false)
        OR COALESCE(v_profile.is_prosecutor, false)
        OR COALESCE(v_profile.is_attorney, false)
        OR v_profile.role IN (
            'admin','superadmin','owner','ceo','staff','moderator',
            'lead_troll_officer','troll_officer','officer','secretary',
            'executive_secretary','prosecutor','attorney','judge','president',
            'vice_president'
        );

    RETURN jsonb_build_object(
        'is_authenticated', true,
        'is_host', v_is_host,
        'is_staff', COALESCE(v_is_staff, false),
        'is_clocked_in', v_clocked_in,
        'is_broadofficer', v_is_bo,
        'staff_role', v_profile.role,
        -- Effective authority:
        --  full staff tools require staff AND clocked in (or high-priv/host)
        'has_full_staff_tools', (COALESCE(v_is_staff,false) AND v_clocked_in)
            OR public.is_high_privilege(v_user) OR v_is_host,
        --  staff who are NOT clocked in still get arrest + summon
        'can_arrest', COALESCE(v_is_staff, false) OR v_is_host OR public.is_high_privilege(v_user),
        'can_summon', COALESCE(v_is_staff, false) OR public.is_high_privilege(v_user)
    );
END;
$$;

-- Function: gift_post
CREATE OR REPLACE FUNCTION public.gift_post(
    p_post_id UUID,
    p_amount NUMERIC,
    p_message TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_post_owner_id UUID;
    v_sender_id UUID := auth.uid();
    v_spend_result JSONB;
BEGIN
    -- Get post owner
    SELECT user_id INTO v_post_owner_id
    FROM public.troll_posts
    WHERE id = p_post_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Post not found');
    END IF;

    IF v_sender_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    IF v_sender_id = v_post_owner_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot gift your own post');
    END IF;

    -- Spend coins from sender
    -- Note: Ensure troll_bank_spend_coins_secure exists. If not, this function creation might warn but will succeed.
    -- Execution will fail if the dependent function is missing.
    v_spend_result := public.troll_bank_spend_coins_secure(
        v_sender_id,
        p_amount,
        'paid', -- default bucket
        'post_gift',
        p_post_id::text,
        jsonb_build_object('post_id', p_post_id, 'message', p_message)
    );

    IF (v_spend_result->>'success')::boolean = false THEN
        RETURN v_spend_result;
    END IF;

    -- Credit coins to post owner
    PERFORM public.troll_bank_credit_coins(
        v_post_owner_id,
        p_amount,
        'gifted',
        'post_gift_received',
        p_post_id::text,
        jsonb_build_object('sender_id', v_sender_id, 'post_id', p_post_id, 'message', p_message)
    );

    -- Record the gift
    INSERT INTO public.troll_post_gifts (post_id, sender_id, gift_type, amount, metadata)
    VALUES (p_post_id, v_sender_id, 'coins', p_amount, jsonb_build_object('message', p_message));

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: grant_xp
CREATE OR REPLACE FUNCTION grant_xp(
    p_user_id UUID,
    p_amount BIGINT,
    p_source TEXT,
    p_source_id TEXT,
    p_metadata JSONB DEFAULT '{}'::jsonb
) RETURNS JSONB AS $$
DECLARE
    new_total BIGINT;
    new_level INT;
    new_next BIGINT;
    new_prog FLOAT;
    current_stats RECORD;
BEGIN
    -- Check deduplication
    IF EXISTS (SELECT 1 FROM public.xp_ledger WHERE source = p_source AND source_id = p_source_id) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Duplicate source_id');
    END IF;

    -- Insert into ledger
    INSERT INTO public.xp_ledger (user_id, source, source_id, xp_amount, metadata)
    VALUES (p_user_id, p_source, p_source_id, p_amount, p_metadata);

    -- Get current stats or init
    INSERT INTO public.user_stats (user_id, xp_total)
    VALUES (p_user_id, 0)
    ON CONFLICT (user_id) DO NOTHING;

    -- Update stats atomically
    UPDATE public.user_stats
    SET xp_total = xp_total + p_amount,
        updated_at = NOW()
    WHERE user_id = p_user_id
    RETURNING xp_total INTO new_total;

    -- Recalculate level
    SELECT lvl, xp_next, progress INTO new_level, new_next, new_prog
    FROM calculate_level(new_total);

    UPDATE public.user_stats
    SET level = new_level,
        xp_to_next_level = new_next,
        xp_progress = new_prog
    WHERE user_id = p_user_id;

    -- Return result
    RETURN jsonb_build_object(
        'success', true,
        'user_id', p_user_id,
        'xp_total', new_total,
        'level', new_level,
        'xp_added', p_amount
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

ALTER TABLE user_profiles ADD COLUMN IF NOT EXISTS banner_notifications_enabled BOOLEAN DEFAULT true;

create or replace function kick_church_member(target_user_id uuid, reason text)
returns void
language plpgsql
security definer
as $$
declare
  current_user_id uuid;
begin
  current_user_id := auth.uid();
  
  -- 1. Create Court Case
  insert into troll_court_cases (
    defendant_id,
    plaintiff_id,
    accusation,
    status,
    created_at
  ) values (
    target_user_id,
    current_user_id,
    'Kicked from Troll Church: ' || reason,
    'pending',
    now()
  );

  -- 2. Issue Warrant (Restricts site access)
  update user_profiles
  set has_active_warrant = true
  where id = target_user_id;
end;
$$;

-- Function: handle_battle_guest_leave
CREATE OR REPLACE FUNCTION public.handle_battle_guest_leave(
    p_battle_id UUID,
    p_guest_user_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_participant RECORD;
    v_stream_id UUID;
    v_current_box_count INTEGER;
    v_new_box_count INTEGER;
BEGIN
    -- Get participant info
    SELECT * INTO v_participant
    FROM public.battle_participants
    WHERE battle_id = p_battle_id AND user_id = p_guest_user_id;
    
    IF v_participant IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Guest not found in battle');
    END IF;
    
    -- Mark participant as left
    UPDATE public.battle_participants
    SET 
        role = 'viewer',
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('left_at', NOW(), 'was_stage', true)
    WHERE battle_id = p_battle_id AND user_id = p_guest_user_id;
    
    -- Get the source stream to update box count
    v_stream_id := v_participant.source_stream_id;
    
    -- Get current box count
    SELECT box_count INTO v_current_box_count
    FROM public.streams
    WHERE id = v_stream_id;
    
    -- Auto-decrement box count (but keep at least 1)
    v_new_box_count := GREATEST(1, COALESCE(v_current_box_count, 1) - 1);
    
    UPDATE public.streams
    SET box_count = v_new_box_count
    WHERE id = v_stream_id;
    
    -- Log the event
    INSERT INTO public.battle_events (
        battle_id,
        event_type,
        user_id,
        metadata
    ) VALUES (
        p_battle_id,
        'guest_leave',
        p_guest_user_id,
        jsonb_build_object(
            'team', v_participant.team,
            'seat_index', v_participant.seat_index,
            'stream_id', v_stream_id,
            'box_count_before', v_current_box_count,
            'box_count_after', v_new_box_count
        )
    );
    
    -- Broadcast the box count change via realtime
    PERFORM pg_notify('box_count_changed', jsonb_build_object(
        'stream_id', v_stream_id,
        'box_count', v_new_box_count,
        'battle_id', p_battle_id,
        'guest_left', p_guest_user_id
    )::text);
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Guest left battle',
        'box_count_updated', v_new_box_count != v_current_box_count,
        'new_box_count', v_new_box_count
    );
END;
$$;

-- Function: hard_delete_court_case
CREATE OR REPLACE FUNCTION public.hard_delete_court_case(p_case_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_docket_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_court_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Only court staff can delete court cases';
  END IF;

  SELECT docket_id INTO v_docket_id
  FROM public.court_cases
  WHERE id = p_case_id;

  DELETE FROM public.court_cases
  WHERE id = p_case_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Case not found');
  END IF;

  IF v_docket_id IS NOT NULL AND to_regclass('public.court_dockets') IS NOT NULL THEN
    UPDATE public.court_dockets
    SET cases_count = GREATEST(COALESCE(cases_count, 1) - 1, 0),
        updated_at = now()
    WHERE id = v_docket_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: hard_delete_docket_entry
CREATE OR REPLACE FUNCTION public.hard_delete_docket_entry(p_docket_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_court_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Only court staff can delete docket entries';
  END IF;

  IF to_regclass('public.court_docket') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'court_docket table not found');
  END IF;

  DELETE FROM public.court_docket
  WHERE id = p_docket_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Docket entry not found');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

