-- ----------------------------------------------------------------------------
-- 2. Ask PostgREST to reload its schema cache so newly created/updated
--    functions (e.g. is_universe_admin, increment_ad_clicks) become visible.
--    PGRST202 for public.is_universe_admin indicates the function migration
--    (20260718000002_universe_battles_rls.sql) had not been picked up by the
--    running API's schema cache.
-- ----------------------------------------------------------------------------
DO $$
BEGIN
    -- Re-assert is_universe_admin in case the battles migration was skipped.
    IF NOT EXISTS (
        SELECT 1 FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public' AND p.proname = 'is_universe_admin'
    ) THEN
        RAISE NOTICE 'is_universe_admin missing — ensure 20260718000002_universe_battles_rls.sql was applied';
    END IF;
END $$;

-- Function: increment_family_stats
CREATE OR REPLACE FUNCTION public.increment_family_stats(
    p_family_id uuid,
    p_coin_bonus bigint,
    p_xp_bonus bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_new_coins bigint;
    v_new_xp bigint;
BEGIN
    -- Update family_stats using correct column names (family_coins, not coins)
    UPDATE public.family_stats
    SET 
        family_coins = COALESCE(family_coins, 0) + p_coin_bonus,
        total_coins = COALESCE(total_coins, 0) + p_coin_bonus,
        family_xp = COALESCE(family_xp, 0) + p_xp_bonus,
        updated_at = now()
    WHERE family_id = p_family_id
    RETURNING family_coins, family_xp INTO v_new_coins, v_new_xp;

    IF NOT FOUND THEN
        -- Create stats if missing
        INSERT INTO public.family_stats (family_id, family_coins, total_coins, family_xp)
        VALUES (p_family_id, p_coin_bonus, p_coin_bonus, p_xp_bonus)
        RETURNING family_coins, family_xp INTO v_new_coins, v_new_xp;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'new_coins', v_new_coins,
        'new_xp', v_new_xp
    );
END;
$$;

