-- 6. Replace sold-out model with a new unique model from pool
CREATE OR REPLACE FUNCTION public.dealership_replace_sold_out(
    p_inventory_id UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_inventory RECORD;
    v_pool RECORD;
    v_new_catalog_id INTEGER;
    v_unique_suffix TEXT;
BEGIN
    SELECT * INTO v_inventory
    FROM public.dealership_inventory
    WHERE id = p_inventory_id
    FOR UPDATE;

    IF v_inventory IS NULL OR v_inventory.status <> 'active' THEN
        RETURN;
    END IF;

    UPDATE public.dealership_inventory
    SET status = 'retired', retired_at = now()
    WHERE id = p_inventory_id;

    -- Pick next unused pool item
    SELECT * INTO v_pool
    FROM public.dealership_vehicle_pool
    WHERE used_at IS NULL
    ORDER BY created_at ASC
    FOR UPDATE SKIP LOCKED
    LIMIT 1;

    IF v_pool IS NULL THEN
        -- Fallback: generate a unique placeholder model (never repeats)
        v_unique_suffix := replace(gen_random_uuid()::text, '-', '')::text;

        INSERT INTO public.vehicles_catalog (name, tier, style, price, speed, armor, color_from, color_to, image, model_url)
        VALUES (
            'KT Limited ' || substring(v_unique_suffix, 1, 6),
            'Mid',
            'Limited',
            30000,
            72,
            40,
            '#64748b',
            '#94a3b8',
            '/assets/cars/vehicle_7_original.png',
            '/models/vehicles/kt_limited_' || substring(v_unique_suffix, 1, 10) || '.glb'
        )
        RETURNING id INTO v_new_catalog_id;
    ELSE
        INSERT INTO public.vehicles_catalog (name, tier, style, price, speed, armor, color_from, color_to, image, model_url)
        VALUES (
            v_pool.name,
            v_pool.tier,
            v_pool.style,
            v_pool.price,
            v_pool.speed,
            v_pool.armor,
            v_pool.color_from,
            v_pool.color_to,
            v_pool.image,
            v_pool.model_url
        )
        RETURNING id INTO v_new_catalog_id;

        UPDATE public.dealership_vehicle_pool
        SET used_at = now()
        WHERE id = v_pool.id;
    END IF;

    INSERT INTO public.dealership_inventory (dealership, catalog_id, quantity, max_quantity)
    VALUES (v_inventory.dealership, v_new_catalog_id, v_inventory.max_quantity, v_inventory.max_quantity);
END;
$$;

-- Function: invite_followers_to_broadcast
CREATE OR REPLACE FUNCTION public.invite_followers_to_broadcast(
    p_stream_id UUID,
    p_inviter_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_stream public.streams%ROWTYPE;
    v_inviter_username TEXT;
    v_inviter_display_name TEXT;
    v_invitee_ids UUID[];
    v_invitee_count INTEGER := 0;
    v_notification_id UUID;
    v_created_at TIMESTAMPTZ := NOW();
BEGIN
    -- Get stream info
    SELECT * INTO v_stream
    FROM public.streams
    WHERE id = p_stream_id;

    IF v_stream.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Stream not found');
    END IF;

    -- Verify inviter is the host
    IF v_stream.user_id != p_inviter_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Only host can invite');
    END IF;

    -- Get inviter display name
    SELECT username, display_name
    INTO v_inviter_username, v_inviter_display_name
    FROM public.user_profiles
    WHERE id = p_inviter_id;

    -- Get all invitees: followers AND following
    SELECT ARRAY(
        SELECT DISTINCT uf.following_id
        FROM public.user_follows uf
        WHERE uf.follower_id = p_inviter_id
        
        UNION
        
        SELECT DISTINCT uf.follower_id
        FROM public.user_follows uf
        WHERE uf.following_id = p_inviter_id
    ) INTO v_invitee_ids;

    -- Filter out the inviter themselves and users already in the stream
    v_invitee_ids := ARRAY(
        SELECT UNNEST(v_invitee_ids) EXCEPT
        SELECT user_id FROM public.streams WHERE id = p_stream_id
    );

    v_invitee_count := array_length(v_invitee_ids, 1);

    IF v_invitee_count = 0 THEN
        RETURN jsonb_build_object('success', true, 'invited_count', 0, 'message', 'No followers/following to invite');
    END IF;

    -- Create notification for each invitee
    FOR i IN 1..array_length(v_invitee_ids, 1) LOOP
        INSERT INTO public.notifications (
            user_id,
            message,
            type,
            metadata
        ) VALUES (
            v_invitee_ids[i],
            v_inviter_username || ' invited you to their broadcast: ' || COALESCE(v_stream.title, 'Live Stream') || ' → Join now',
            'broadcast_invite',
            jsonb_build_object(
                'stream_id', p_stream_id::TEXT,
                'inviter_id', p_inviter_id::TEXT,
                'inviter_username', v_inviter_username,
                'stream_title', v_stream.title,
                'stream_category', v_stream.category
            )
        );
    END LOOP;

    -- Log the invite action in stream_messages
    INSERT INTO public.stream_messages (
        stream_id,
        user_id,
        content,
        type
    ) VALUES (
        p_stream_id,
        p_inviter_id,
        'INVITE_EVENT:' || v_invitee_count || ' followers/following invited',
        'system'
    );

    RETURN jsonb_build_object(
        'success', true,
        'invited_count', v_invitee_count,
        'message', 'Invited ' || v_invitee_count || ' followers and following'
    );
END;
$$;

-- Function: is_beta_feedback_moderator
CREATE OR REPLACE FUNCTION public.is_beta_feedback_moderator(p_user_id uuid)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = p_user_id
      AND (
        role IN ('admin','superadmin','ceo','moderator','lead_troll_officer','troll_officer','secretary','pastor')
        OR troll_role IN ('admin','superadmin','ceo','moderator','lead_troll_officer','troll_officer')
        OR COALESCE(is_admin, false) = true
        OR COALESCE(is_lead_officer, false) = true
        OR COALESCE(is_troll_officer, false) = true
      )
  )
  OR EXISTS (
    SELECT 1 FROM public.user_role_grants ur
    JOIN public.system_roles r ON ur.role_id = r.id
    WHERE ur.user_id = p_user_id
      AND r.is_staff = true
      AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
      AND ur.revoked_at IS NULL
  );
$$;

-- Function: is_ip_banned
CREATE OR REPLACE FUNCTION is_ip_banned(p_ip_address text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM ip_bans
        WHERE ip_address = p_ip_address
        AND (banned_until IS NULL OR banned_until > now())
    );
END;
$$;

-- Function: is_universe_admin
CREATE OR REPLACE FUNCTION public.is_universe_admin()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid()
      AND (
        role = 'admin'
        OR is_admin = true
        OR account_state = 'staff'
        OR EXISTS (
          SELECT 1 FROM public.staff_roles sr
          WHERE sr.user_id = auth.uid()
            AND sr.role IN ('rtc','admin','moderator','broadcaster_admin')
        )
      )
  );
$$;

-- Function: is_user_chat_blocked
CREATE OR REPLACE FUNCTION public.is_user_chat_blocked(
  p_user_id uuid,
  p_stream_id uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.chat_blocks cb
    WHERE cb.user_id = p_user_id
      AND (
        cb.is_permanent = true
        OR cb.expires_at > now()
      )
      AND (p_stream_id IS NULL OR cb.stream_id = p_stream_id OR cb.stream_id IS NULL)
  );
$$;

-- Function: is_user_chat_disabled
CREATE OR REPLACE FUNCTION public.is_user_chat_disabled(p_user_id uuid)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_broadcast_restrictions
    WHERE user_id = p_user_id
      AND chat_disabled = true
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > NOW())
  )
  OR EXISTS (
    SELECT 1 FROM public.broadcast_mod_actions
    WHERE target_user_id = p_user_id
      AND action_type = 'disable_chat'
      AND status = 'active'
      AND (expires_at IS NULL OR expires_at > NOW())
  );
$$;

-- Function: issue_promo_card
CREATE OR REPLACE FUNCTION issue_promo_card(
    p_user_id uuid,
    p_source_type text,
    p_token_amount numeric DEFAULT 20,
    p_expires_in interval DEFAULT '24 hours',
    p_metadata jsonb DEFAULT '{}'::jsonb
) RETURNS TABLE (
    promo_card_id uuid,
    code text,
    token_amount numeric,
    issued_at timestamp with time zone,
    expires_at timestamp with time zone,
    status text,
    next_available_at timestamp with time zone,
    message text
) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
    v_can_issue boolean;
    v_next timestamp with time zone;
    v_reason text;
    v_code text;
    v_result can_issue_promo_card%ROWTYPE;
BEGIN
    SELECT * INTO v_result
    FROM can_issue_promo_card(p_user_id, p_source_type);

    v_can_issue := v_result.can_issue;
    v_next := v_result.next_available_at;
    v_reason := v_result.reason;

    IF NOT v_can_issue THEN
        RETURN QUERY SELECT NULL, NULL, NULL, NULL, NULL, NULL, v_next, v_reason;
    END IF;

    LOOP
        v_code := format('TC-%s-%s', substring(md5(random()::text || clock_timestamp()::text) FROM 1 FOR 3), floor(random()*1000)+1000);
        EXIT WHEN NOT EXISTS (SELECT 1 FROM promo_cards WHERE code = v_code);
    END LOOP;

    INSERT INTO promo_cards (code, token_amount, user_id, source_type, issued_at, expires_at, status, metadata)
    VALUES (v_code, p_token_amount, p_user_id, p_source_type, NOW(), NOW() + p_expires_in, 'available', p_metadata)
    RETURNING id, code, token_amount, issued_at, expires_at, status
    INTO promo_card_id, code, token_amount, issued_at, expires_at, status;

    RETURN QUERY SELECT promo_card_id, code, token_amount, issued_at, expires_at, status, NULL, 'Promo card issued';
END;
$$;

-- Function: issue_warrant
CREATE OR REPLACE FUNCTION public.issue_warrant(
    p_target_id UUID,
    p_reason TEXT,
    p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_officer_id UUID;
    v_case_id UUID;
BEGIN
    v_officer_id := auth.uid();

    -- Check if officer has authority
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = v_officer_id AND authority_level >= 3
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient authority level');
    END IF;

    -- Create court case
    INSERT INTO public.troll_court_cases (
        defendant_id,
        case_type,
        title,
        description,
        status,
        filed_by
    ) VALUES (
        p_target_id,
        'warrant',
        'Arrest Warrant',
        p_reason,
        'pending',
        v_officer_id
    ) RETURNING id INTO v_case_id;

    -- Mark defendant as having active warrant
    UPDATE public.user_profiles
    SET has_active_warrant = true
    WHERE id = p_target_id;

    RETURN jsonb_build_object(
        'success', true,
        'warrant_id', v_case_id,
        'message', 'Warrant issued successfully'
    );
END;
$$;

-- Function: join_court_session
CREATE OR REPLACE FUNCTION public.join_court_session(
    p_court_session_id UUID,
    p_role TEXT DEFAULT 'observer'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_existing_participant court_participants%ROWTYPE;
    v_result JSONB;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    -- Check if already in session
    SELECT * INTO v_existing_participant
    FROM court_participants
    WHERE court_session_id = p_court_session_id AND user_id = v_user_id;

    IF FOUND THEN
        -- Update existing participant role
        UPDATE court_participants
        SET role = p_role, updated_at = NOW()
        WHERE id = v_existing_participant.id
        RETURNING * INTO v_existing_participant;
        
        RETURN jsonb_build_object(
            'success', true,
            'participant', jsonb_build_object(
                'id', v_existing_participant.id,
                'role', v_existing_participant.role,
                'box_number', v_existing_participant.box_number,
                'queue_position', v_existing_participant.queue_position
            )
        );
    END IF;

    -- Join with role - judges/prosecutors get boxes automatically
    INSERT INTO court_participants (court_session_id, user_id, role, box_number)
    VALUES (
        p_court_session_id, 
        v_user_id, 
        p_role,
        CASE 
            WHEN p_role IN ('judge', 'prosecutor') THEN 1
            WHEN p_role = 'defendant' THEN 2
            WHEN p_role = 'attorney' THEN 3
            ELSE NULL
        END
    )
    RETURNING * INTO v_existing_participant;

    RETURN jsonb_build_object(
        'success', true,
        'participant', jsonb_build_object(
            'id', v_existing_participant.id,
            'role', v_existing_participant.role,
            'box_number', v_existing_participant.box_number,
            'queue_position', v_existing_participant.queue_position
        )
    );
END;
$$;

-- Function: join_family
CREATE OR REPLACE FUNCTION public.join_family(
  p_family_id UUID,
  p_user_id UUID
)
RETURNS JSONB AS $$
DECLARE
  v_result JSONB;
BEGIN
  -- Check if user is already in a family
  IF EXISTS (SELECT 1 FROM public.family_members WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'You are already in a family'
    );
  END IF;

  -- Check if user is already in troll_family_members
  IF EXISTS (SELECT 1 FROM public.troll_family_members WHERE user_id = p_user_id) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'You are already in a family'
    );
  END IF;

  -- Add user to family_members
  INSERT INTO public.family_members (user_id, family_id, role)
  VALUES (p_user_id, p_family_id, 'member')
  ON CONFLICT (family_id, user_id) DO NOTHING;

  -- Also add to troll_family_members if it exists
  INSERT INTO public.troll_family_members (user_id, family_id, role)
  VALUES (p_user_id, p_family_id, 'member')
  ON CONFLICT (family_id, user_id) DO NOTHING;

  -- Create welcome notification
  INSERT INTO public.family_notifications (
    family_id,
    title,
    message,
    severity,
    is_read,
    notification_type
  ) VALUES (
    p_family_id,
    '👋 New Member!',
    'A new member has joined the family!',
    'info',
    false,
    'member_join'
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Successfully joined family'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 9. Create function to kick a member (only leaders can do this)
CREATE OR REPLACE FUNCTION public.kick_family_member(
  p_family_id UUID,
  p_target_user_id UUID,
  p_admin_user_id UUID
)
RETURNS JSONB AS $$
DECLARE
  v_admin_role TEXT;
BEGIN
  -- Check if admin is leader or co_leader
  SELECT fm.role INTO v_admin_role
  FROM public.family_members fm
  WHERE fm.family_id = p_family_id AND fm.user_id = p_admin_user_id;

  IF v_admin_role NOT IN ('leader', 'co_leader') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Only leaders can kick members'
    );
  END IF;

  -- Cannot kick the leader
  IF EXISTS (
    SELECT 1 FROM public.family_members 
    WHERE family_id = p_family_id 
    AND user_id = p_target_user_id 
    AND role = 'leader'
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Cannot kick the family leader'
    );
  END IF;

  -- Remove from family_members
  DELETE FROM public.family_members
  WHERE family_id = p_family_id AND user_id = p_target_user_id;

  -- Remove from troll_family_members if exists
  DELETE FROM public.troll_family_members
  WHERE family_id = p_family_id AND user_id = p_target_user_id;

  -- Create notification about kick
  INSERT INTO public.family_notifications (
    family_id,
    title,
    message,
    severity,
    is_read,
    notification_type,
    related_user_id
  ) VALUES (
    p_family_id,
    'Member Removed',
    'A member has been removed from the family',
    'warning',
    false,
    'member_kick',
    p_target_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Member kicked successfully'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 10. Create function to promote a member (only leaders can do this)
CREATE OR REPLACE FUNCTION public.promote_family_member(
  p_family_id UUID,
  p_target_user_id UUID,
  p_new_role TEXT,
  p_admin_user_id UUID
)
RETURNS JSONB AS $$
DECLARE
  v_admin_role TEXT;
BEGIN
  -- Check if admin is leader
  SELECT fm.role INTO v_admin_role
  FROM public.family_members fm
  WHERE fm.family_id = p_family_id AND fm.user_id = p_admin_user_id;

  IF v_admin_role != 'leader' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Only the leader can promote members'
    );
  END IF;

  -- Validate role
  IF p_new_role NOT IN ('co_leader', 'scout', 'recruiter', 'mentor', 'member') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Invalid role'
    );
  END IF;

  -- Update role
  UPDATE public.family_members
  SET role = p_new_role, updated_at = NOW()
  WHERE family_id = p_family_id AND user_id = p_target_user_id;

  -- Also update in troll_family_members if exists
  UPDATE public.troll_family_members
  SET role = p_new_role
  WHERE family_id = p_family_id AND user_id = p_target_user_id;

  -- Create notification about promotion
  INSERT INTO public.family_notifications (
    family_id,
    title,
    message,
    severity,
    is_read,
    notification_type,
    related_user_id
  ) VALUES (
    p_family_id,
    '🎉 Member Promoted!',
    'A member has been promoted to ' || p_new_role,
    'info',
    false,
    'member_promote',
    p_target_user_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Member promoted successfully'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 11. Grant execute permissions
GRANT EXECUTE ON FUNCTION public.bootstrap_new_family() TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.join_family(UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.kick_family_member(UUID, UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.promote_family_member(UUID, UUID, TEXT, UUID) TO authenticated, service_role;

-- 12. Run backfill for all families - add any missing member entries
-- This is a safety check
DO $$
DECLARE
  fam RECORD;
BEGIN
  FOR fam IN SELECT id FROM public.troll_families LOOP
    -- If no members, insert a placeholder (would need creator_id)
    IF (SELECT COUNT(*) FROM public.family_members WHERE family_id = fam.id) = 0 THEN
      RAISE NOTICE 'Family % has no members', fam.id;
    END IF;
  END LOOP;
END $$;

-- Function: join_seat_atomic
CREATE OR REPLACE FUNCTION public.join_seat_atomic(
    p_stream_id UUID,
    p_seat_index INTEGER,
    p_price INTEGER,
    p_user_id UUID DEFAULT auth.uid()
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := p_user_id;
    v_user_balance INTEGER;
    v_active_session_id UUID;
    v_already_paid BOOLEAN := FALSE;
    v_stream_owner UUID;
    v_new_session_id UUID;
    v_ledger_item_id UUID;
BEGIN
    -- 1. Validate Stream & Owner
    SELECT user_id INTO v_stream_owner FROM public.streams WHERE id = p_stream_id;
    IF v_stream_owner IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Stream not found');
    END IF;

    -- 2. Check if seat is occupied
    IF EXISTS (
        SELECT 1 FROM public.stream_seat_sessions 
        WHERE stream_id = p_stream_id 
        AND seat_index = p_seat_index 
        AND status = 'active'
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Seat already taken');
    END IF;

    -- 3. Check Payment History
    IF EXISTS (
        SELECT 1 FROM public.stream_seat_sessions
        WHERE stream_id = p_stream_id
        AND user_id = v_user_id
        AND seat_index = p_seat_index
        AND price_paid >= p_price
    ) THEN
        v_already_paid := TRUE;
    END IF;

    -- 4. Process Payment
    IF p_price > 0 AND NOT v_already_paid THEN
        -- Lock & Check Balance
        SELECT troll_coins INTO v_user_balance FROM public.user_profiles WHERE id = v_user_id FOR UPDATE;
        
        IF v_user_balance < p_price THEN
            RETURN jsonb_build_object('success', false, 'message', 'Insufficient coins');
        END IF;

        -- Deduct from User
        UPDATE public.user_profiles 
        SET troll_coins = troll_coins - p_price 
        WHERE id = v_user_id;

        -- Credit to Host (90%)
        UPDATE public.user_profiles
        SET troll_coins = troll_coins + FLOOR(p_price * 0.9)
        WHERE id = v_stream_owner;
        
        -- Log to Purchase Ledger (CRITICAL SYNC)
        SELECT id INTO v_ledger_item_id FROM public.purchasable_items WHERE item_key = 'broadcast-seat';
        
        IF v_ledger_item_id IS NOT NULL THEN
            INSERT INTO public.purchase_ledger (
                user_id, item_id, coin_amount, payment_method, source_context, created_at
            ) VALUES (
                v_user_id, v_ledger_item_id, p_price, 'coins', p_stream_id::text, now()
            );
        END IF;

        -- Log Transaction (Legacy)
        INSERT INTO public.coin_transactions (user_id, amount, type, metadata)
        VALUES (v_user_id, -p_price, 'purchase', jsonb_build_object('description', 'Seat ' || p_seat_index || ' in stream ' || p_stream_id));
    END IF;

    -- 5. Create Session
    INSERT INTO public.stream_seat_sessions (
        stream_id, user_id, seat_index, price_paid, status, joined_at
    ) VALUES (
        p_stream_id, v_user_id, p_seat_index, CASE WHEN v_already_paid THEN 0 ELSE p_price END, 'active', now()
    ) RETURNING id INTO v_new_session_id;

    RETURN jsonb_build_object(
        'success', true, 
        'session_id', v_new_session_id,
        'paid', CASE WHEN v_already_paid THEN 0 ELSE p_price END
    );

EXCEPTION 
    WHEN unique_violation THEN
        RETURN jsonb_build_object('success', false, 'message', 'Seat already taken (race)');
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- Function: join_stream_as_viewer
CREATE OR REPLACE FUNCTION public.join_stream_as_viewer(
  p_stream_id uuid,
  p_user_id uuid DEFAULT NULL,
  p_guest_id text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_stream public.streams%ROWTYPE;
  v_count integer;
  v_cap integer;
  v_cap_enabled boolean;
  v_restrictions_disabled boolean;
BEGIN
  -- At least one stable identity must be supplied.
  IF p_user_id IS NULL AND (p_guest_id IS NULL OR trim(p_guest_id) = '') THEN
    RETURN jsonb_build_object(
      'allowed', false, 'reason', 'missing_identity',
      'viewer_count', 0, 'viewer_cap', NULL
    );
  END IF;

  IF p_user_id IS NOT NULL THEN
    -- Caller must be the authenticated user they claim to be.
    IF p_user_id <> auth.uid() THEN
      RETURN jsonb_build_object(
        'allowed', false, 'reason', 'identity_mismatch',
        'viewer_count', 0, 'viewer_cap', NULL
      );
    END IF;
  END IF;

  -- Lock the stream row so concurrent joins serialize on it.
  SELECT *
    INTO v_stream
  FROM public.streams
  WHERE id = p_stream_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'allowed', false, 'reason', 'stream_not_found',
      'viewer_count', 0, 'viewer_cap', NULL
    );
  END IF;

  -- Only live, joinable streams accept viewers.
  IF v_stream.is_live IS DISTINCT FROM true
     OR COALESCE(v_stream.status, '') <> 'live' THEN
    RETURN jsonb_build_object(
      'allowed', false, 'reason', 'stream_not_live',
      'viewer_count', 0, 'viewer_cap', NULL
    );
  END IF;

  -- Read configured restrictions (same settings used by useBroadcastViewerCap).
  v_restrictions_disabled := public._cap_setting_bool('broadcast_all_restrictions_disabled', false);
  v_cap_enabled := public._cap_setting_bool('broadcast_viewer_cap_enabled', false);
  v_cap := COALESCE(public._cap_setting_numeric('broadcast_viewer_cap_max', NULL)::integer, NULL);

  -- If all restrictions disabled, allow regardless of cap.
  IF NOT v_restrictions_disabled AND v_cap_enabled AND v_cap IS NOT NULL THEN
    -- Authoritative count of currently seated viewers in this stream.
    SELECT COUNT(*)
      INTO v_count
    FROM public.stream_viewers sv
    WHERE sv.stream_id = p_stream_id
      AND (
        (p_user_id IS NOT NULL AND sv.user_id = p_user_id)
        OR (p_guest_id IS NOT NULL AND sv.guest_id = p_guest_id)
      );

    -- Already present? Count them in the total (they already occupy a slot).
    -- If not present, count distinct other viewers and add 1 for the candidate.
    IF v_count = 0 THEN
      SELECT COUNT(*)
        INTO v_count
      FROM public.stream_viewers sv
      WHERE sv.stream_id = p_stream_id;

      IF v_count >= v_cap THEN
        RETURN jsonb_build_object(
          'allowed', false, 'reason', 'viewer_cap_reached',
          'viewer_count', v_count, 'viewer_cap', v_cap
        );
      END IF;
    END IF;
  END IF;

  -- Admit: insert an idempotent capacity row (one slot per viewer).
  INSERT INTO public.stream_viewers (stream_id, user_id, guest_id, joined_at)
  VALUES (
    p_stream_id,
    p_user_id,
    NULLIF(p_guest_id, ''),
    now()
  )
  ON CONFLICT (stream_id, user_id) DO NOTHING
  ON CONFLICT (stream_id, guest_id) WHERE guest_id IS NOT NULL DO NOTHING;

  -- Recompute authoritative occupancy for the response.
  SELECT COUNT(*)
    INTO v_count
  FROM public.stream_viewers sv
  WHERE sv.stream_id = p_stream_id;

  RETURN jsonb_build_object(
    'allowed', true, 'reason', null,
    'viewer_count', v_count, 'viewer_cap', v_cap
  );
END;
$$;

-- Function: join_tournament
CREATE OR REPLACE FUNCTION public.join_tournament(p_tournament_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_tournament RECORD;
  v_entry_fee INTEGER;
  v_user_coins INTEGER;
BEGIN
  -- 1. Get Tournament Details
  SELECT * INTO v_tournament
  FROM public.tournaments
  WHERE id = p_tournament_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Tournament not found');
  END IF;

  IF v_tournament.status NOT IN ('open', 'upcoming') THEN
    RETURN jsonb_build_object('success', false, 'message', 'Tournament is not open for registration');
  END IF;

  IF v_tournament.max_participants IS NOT NULL THEN
    IF (SELECT COUNT(*) FROM public.tournament_participants WHERE tournament_id = p_tournament_id) >= v_tournament.max_participants THEN
      RETURN jsonb_build_object('success', false, 'message', 'Tournament is full');
    END IF;
  END IF;

  -- 2. Check if already joined
  IF EXISTS (SELECT 1 FROM public.tournament_participants WHERE tournament_id = p_tournament_id AND user_id = v_user_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Already joined');
  END IF;

  -- 3. Check Balance and Deduct Fee
  v_entry_fee := COALESCE(v_tournament.entry_fee, 0);
  
  IF v_entry_fee > 0 THEN
    SELECT troll_coins INTO v_user_coins
    FROM public.user_profiles
    WHERE id = v_user_id;

    IF v_user_coins < v_entry_fee THEN
      RETURN jsonb_build_object('success', false, 'message', 'Insufficient Troll Coins');
    END IF;

    -- Deduct coins
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - v_entry_fee,
        total_spent_coins = total_spent_coins + v_entry_fee
    WHERE id = v_user_id;

    -- Log transaction
    INSERT INTO public.coin_transactions (user_id, amount, type, description, metadata)
    VALUES (
      v_user_id, 
      -v_entry_fee, 
      'tournament_entry', 
      'Entry fee for ' || v_tournament.title, 
      jsonb_build_object('tournament_id', p_tournament_id)
    );
  END IF;

  -- 4. Insert Participant
  INSERT INTO public.tournament_participants (tournament_id, user_id, status, joined_at)
  VALUES (p_tournament_id, v_user_id, 'active', NOW());

  RETURN jsonb_build_object('success', true, 'message', 'Successfully joined');
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- Function: join_trollmin_queue
CREATE OR REPLACE FUNCTION join_trollmin_queue(p_user_id UUID, p_username VARCHAR, p_coins BIGINT)
RETURNS JSONB AS $$
DECLARE
    v_entry_cost BIGINT := 5000;
    v_result JSONB;
    v_position INTEGER;
    v_existing_queue RECORD;
BEGIN
    SELECT * INTO v_existing_queue 
    FROM trollmin_queue 
    WHERE user_id = p_user_id AND status = 'waiting';
    
    IF FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already in queue');
    END IF;
    
    IF EXISTS (SELECT 1 FROM trollmin_queue WHERE user_id = p_user_id AND is_banned_from_queue = true) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Banned from Power Queue');
    END IF;
    
    IF p_coins < v_entry_cost THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not enough coins. Need ' || v_entry_cost);
    END IF;
    
    SELECT COALESCE(MAX(queue_position), 0) + 1 INTO v_position FROM trollmin_queue WHERE status = 'waiting';
    
    INSERT INTO trollmin_queue (user_id, username, coins_spent, queue_position, status)
    VALUES (p_user_id, p_username, v_entry_cost, v_position, 'waiting')
    RETURNING jsonb_build_object(
        'success', true,
        'position', queue_position,
        'coins_spent', coins_spent
    ) INTO v_result;
    
    RETURN v_result;
END;
$$ LANGUAGE plpgsql;

-- Migration: Update cashout tiers to final values
-- Date: 2026-03-21
-- Replaces old tiers with:
-- 7,500 coins = $25
-- 15,000 coins = $50
-- 30,000 coins = $150
-- 60,000 coins = $300
-- 120,000 coins = $600
-- 200,000 coins = $1,000 (Manual Review Required)

-- First, deactivate all existing tiers
UPDATE cashout_tiers SET is_active = false;

-- Insert new tiers (or update if they exist)
INSERT INTO cashout_tiers (coin_amount, cash_amount, currency, processing_fee_percentage, is_active, created_at)
VALUES 
  (7500, 25, 'USD', 0, true, NOW()),
  (15000, 50, 'USD', 0, true, NOW()),
  (30000, 150, 'USD', 0, true, NOW()),
  (60000, 300, 'USD', 0, true, NOW()),
  (120000, 600, 'USD', 0, true, NOW()),
  (200000, 1000, 'USD', 0, true, NOW())
ON CONFLICT DO NOTHING;

-- If there are conflicts, update instead
UPDATE cashout_tiers 
SET 
  cash_amount = CASE coin_amount
    WHEN 7500 THEN 25
    WHEN 15000 THEN 50
    WHEN 30000 THEN 150
    WHEN 60000 THEN 300
    WHEN 120000 THEN 600
    WHEN 200000 THEN 1000
    ELSE cash_amount
  END,
  is_active = true,
  processing_fee_percentage = 0
WHERE coin_amount IN (7500, 15000, 30000, 60000, 120000, 200000);

-- Ensure old/unwanted tiers are deactivated
UPDATE cashout_tiers 
SET is_active = false 
WHERE coin_amount NOT IN (7500, 15000, 30000, 60000, 120000, 200000);

-- Create rtc_sessions table for tracking LiveKit RTC usage
CREATE TABLE IF NOT EXISTS rtc_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  room_name TEXT NOT NULL,
  started_at TIMESTAMPTZ DEFAULT NOW(),
  ended_at TIMESTAMPTZ,
  duration_seconds INTEGER DEFAULT 0,
  is_active BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Add indexes for common queries
CREATE INDEX IF NOT EXISTS idx_rtc_sessions_user_id ON rtc_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_rtc_sessions_room_name ON rtc_sessions(room_name);
CREATE INDEX IF NOT EXISTS idx_rtc_sessions_is_active ON rtc_sessions(is_active);
CREATE INDEX IF NOT EXISTS idx_rtc_sessions_started_at ON rtc_sessions(started_at);

-- Enable RLS
ALTER TABLE rtc_sessions ENABLE ROW LEVEL SECURITY;

-- RLS Policy for admins to manage all sessions
CREATE POLICY "Admins can manage all rtc_sessions" ON rtc_sessions
  FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM user_profiles
      WHERE user_profiles.id = auth.uid()
      AND (user_profiles.role = 'admin' OR user_profiles.is_admin = true)
    )
  );

-- RLS Policy for users to see their own sessions
CREATE POLICY "Users can view own rtc_sessions" ON rtc_sessions
  FOR SELECT
  USING (auth.uid() = user_id);

-- RLS Policy for broadcasters to manage sessions for their streams
CREATE POLICY "Broadcasters can manage stream rtc_sessions" ON rtc_sessions
  FOR ALL USING (
    EXISTS (
      SELECT 1 FROM public.streams
      WHERE streams.id::text = REPLACE(rtc_sessions.room_name, 'stream-', '')
      AND streams.broadcaster_id = auth.uid()
    )
  );

-- Fix RLS policies for troll_station_hosts and officer_members tables
-- Enable RLS and add SELECT policies if not exist

-- Check if officer_members table exists
SELECT EXISTS (
   SELECT FROM information_schema.tables 
   WHERE table_schema = 'public' 
   AND table_name = 'officer_members'
);

-- If officer_members exists but has no read policy, add one
DO $$
BEGIN
  -- Add policy for officer_members if table exists
  IF EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema = 'public' 
    AND table_name = 'officer_members'
  ) THEN
    -- Enable RLS if not enabled
    ALTER TABLE IF EXISTS public.officer_members ENABLE ROW LEVEL SECURITY;
    
    -- Create read policy if not exists
    DROP POLICY IF EXISTS "Anyone can view officer members" ON public.officer_members;
    CREATE POLICY "Anyone can view officer members" ON public.officer_members FOR SELECT USING (true);
  END IF;
  
  -- Add policy for troll_station_hosts if table exists
  IF EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema = 'public' 
    AND table_name = 'troll_station_hosts'
  ) THEN
    ALTER TABLE IF EXISTS public.troll_station_hosts ENABLE ROW LEVEL SECURITY;
    
    DROP POLICY IF EXISTS "Anyone can view hosts" ON public.troll_station_hosts;
    CREATE POLICY "Anyone can view hosts" ON public.troll_station_hosts FOR SELECT USING (true);
  END IF;
  
  -- Add policy for troll_station_sessions
  IF EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema = 'public' 
    AND table_name = 'troll_station_sessions'
  ) THEN
    ALTER TABLE IF EXISTS public.troll_station_sessions ENABLE ROW LEVEL SECURITY;
    
    DROP POLICY IF EXISTS "Anyone can view station sessions" ON public.troll_station_sessions;
    CREATE POLICY "Anyone can view station sessions" ON public.troll_station_sessions FOR SELECT USING (true);
  END IF;
  
  -- Add policy for troll_families and troll_family_members
  IF EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema = 'public' 
    AND table_name = 'troll_families'
  ) THEN
    ALTER TABLE IF EXISTS public.troll_families ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "Anyone can view families" ON public.troll_families;
    CREATE POLICY "Anyone can view families" ON public.troll_families FOR SELECT USING (true);
  END IF;
  
  IF EXISTS (
    SELECT 1 FROM information_schema.tables 
    WHERE table_schema = 'public' 
    AND table_name = 'troll_family_members'
  ) THEN
    ALTER TABLE IF EXISTS public.troll_family_members ENABLE ROW LEVEL SECURITY;
    DROP POLICY IF EXISTS "Anyone can view family members" ON public.troll_family_members;
    CREATE POLICY "Anyone can view family members" ON public.troll_family_members FOR SELECT USING (true);
  END IF;
END $$;

-- Function: kick_church_member
create or replace function kick_church_member(target_user_id uuid, reason text)
returns void
language plpgsql
security definer
as $$
declare
  current_user_id uuid;
begin
  current_user_id := auth.uid();
  
  -- 1. Create Court Case
  insert into troll_court_cases (
    defendant_id,
    plaintiff_id,
    accusation,
    status,
    created_at
  ) values (
    target_user_id,
    current_user_id,
    'Kicked from Troll Church: ' || reason,
    'pending',
    now()
  );

  -- 2. Issue Warrant (Restricts site access)
  update user_profiles
  set has_active_warrant = true
  where id = target_user_id;
end;
$$;

-- Function: leave_battle
CREATE OR REPLACE FUNCTION public.leave_battle(
    p_battle_id UUID,
    p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_battle RECORD;
    v_challenger_owner UUID;
    v_opponent_owner UUID;
    v_winner_stream_id UUID;
    v_forfeiting_stream_id UUID;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
    END IF;

    SELECT * INTO v_battle
    FROM public.battles
    WHERE id = p_battle_id;

    IF v_battle IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Battle not found');
    END IF;

    SELECT user_id INTO v_challenger_owner FROM public.streams WHERE id = v_battle.challenger_stream_id;
    SELECT user_id INTO v_opponent_owner FROM public.streams WHERE id = v_battle.opponent_stream_id;

    -- Determine winner and who is forfeiting
    IF p_user_id = v_challenger_owner THEN
        v_winner_stream_id := v_battle.opponent_stream_id;
        v_forfeiting_stream_id := v_battle.challenger_stream_id;
    ELSIF p_user_id = v_opponent_owner THEN
        v_winner_stream_id := v_battle.challenger_stream_id;
        v_forfeiting_stream_id := v_battle.opponent_stream_id;
    ELSE
        RETURN jsonb_build_object('success', false, 'message', 'Not a participant');
    END IF;

    -- Update battle status and winner
    UPDATE public.battles
    SET 
        status = 'ended', 
        ended_at = NOW(),
        winner_id = v_winner_stream_id,
        winner_stream_id = v_winner_stream_id
    WHERE id = p_battle_id;

    -- Only clear battle_id from the forfeiting user's stream, not both
    -- This keeps the other broadcaster in their broadcast
    UPDATE public.streams
    SET battle_id = NULL
    WHERE id = v_forfeiting_stream_id;

    RETURN jsonb_build_object(
        'success', true, 
        'winner_stream_id', v_winner_stream_id,
        'forfeiting_stream_id', v_forfeiting_stream_id
    );
END;
$$;

-- Function: leave_family
CREATE OR REPLACE FUNCTION public.leave_family(
  p_user_id UUID,
  p_family_id UUID
)
RETURNS JSONB AS $$
DECLARE
  v_exit_fee INTEGER;
  v_remaining_members INTEGER;
  v_distribution_amount INTEGER;
  v_user_balance INTEGER;
  v_family_coins INTEGER;
BEGIN
  -- Check if user is actually in the family
  IF NOT EXISTS (
    SELECT 1 FROM public.family_members
    WHERE user_id = p_user_id AND family_id = p_family_id
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'You are not a member of this family'
    );
  END IF;

  -- Cannot leave if you're the only leader
  IF EXISTS (
    SELECT 1 FROM public.family_members
    WHERE family_id = p_family_id AND role = 'leader' AND user_id = p_user_id
  ) AND (
    SELECT COUNT(*) FROM public.family_members
    WHERE family_id = p_family_id AND role = 'leader'
  ) = 1 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'You cannot leave the family as the only leader. Promote another member first.'
    );
  END IF;

  -- Get family vault total
  SELECT COALESCE(family_coins, 0) INTO v_family_coins
  FROM public.family_stats
  WHERE family_id = p_family_id;

  -- Calculate exit fee (10% of family earnings)
  v_exit_fee := GREATEST(0, FLOOR(v_family_coins * 0.1));

  -- Check user's balance
  SELECT COALESCE(troll_coins, 0) INTO v_user_balance
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF v_user_balance < v_exit_fee THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Insufficient Troll Coins to pay the exit fee'
    );
  END IF;

  -- Get count of remaining members (excluding the leaving user)
  SELECT COUNT(*) - 1 INTO v_remaining_members
  FROM public.family_members
  WHERE family_id = p_family_id;

  -- If no remaining members, exit fee goes to family vault (but user still leaves)
  IF v_remaining_members <= 0 THEN
    v_distribution_amount := 0;
  ELSE
    v_distribution_amount := FLOOR(v_exit_fee / v_remaining_members);
  END IF;

  -- Start transaction
  BEGIN
    -- Deduct exit fee from user's balance
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - v_exit_fee
    WHERE id = p_user_id;

    -- Distribute to remaining members
    IF v_distribution_amount > 0 THEN
      UPDATE public.user_profiles
      SET troll_coins = troll_coins + v_distribution_amount
      FROM public.family_members fm
      WHERE fm.user_id = user_profiles.id
        AND fm.family_id = p_family_id
        AND fm.user_id != p_user_id;
    END IF;

    -- Remove user from family_members
    DELETE FROM public.family_members
    WHERE user_id = p_user_id AND family_id = p_family_id;

    -- Remove from troll_family_members if exists
    DELETE FROM public.troll_family_members
    WHERE user_id = p_user_id AND family_id = p_family_id;

    -- Create notification for remaining members
    INSERT INTO public.family_notifications (
      family_id,
      title,
      message,
      severity,
      is_read,
      notification_type,
      related_user_id
    ) VALUES (
      p_family_id,
      'Member Left Family',
      'A member has left the family',
      'info',
      false,
      'member_leave',
      p_user_id
    );

    -- Log the exit fee transaction
    INSERT INTO public.coin_transactions (
      user_id,
      amount,
      transaction_type,
      description,
      created_at
    ) VALUES (
      p_user_id,
      -v_exit_fee,
      'family_exit_fee',
      'Family exit fee payment',
      NOW()
    );

    -- Log distribution transactions for remaining members
    IF v_distribution_amount > 0 THEN
      INSERT INTO public.coin_transactions (
        user_id,
        amount,
        transaction_type,
        description,
        created_at
      )
      SELECT
        fm.user_id,
        v_distribution_amount,
        'family_exit_bonus',
        'Family exit fee distribution',
        NOW()
      FROM public.family_members fm
      WHERE fm.family_id = p_family_id;
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'exit_fee', v_exit_fee,
      'distribution_amount', v_distribution_amount,
      'remaining_members', v_remaining_members
    );

  EXCEPTION
    WHEN OTHERS THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Failed to leave family: ' || SQLERRM
      );
  END;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Grant execute permissions
GRANT EXECUTE ON FUNCTION public.leave_family(UUID, UUID) TO authenticated, service_role;

-- Add comment
COMMENT ON FUNCTION public.leave_family(UUID, UUID) IS 'Allows a family member to leave the family by paying 10% of family earnings as exit fee, distributed to remaining members';
-- Advertisement System for maitroll
-- Users can submit ads for 1000 troll coins, last 7 days, admin approval required

CREATE TABLE IF NOT EXISTS public.user_advertisements (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    subtitle TEXT,
    description TEXT,
    image_url TEXT NOT NULL,
    link_url TEXT,
    status TEXT NOT NULL DEFAULT 'pending', -- pending, approved, denied, expired
    cost_paid BIGINT NOT NULL DEFAULT 1000,
    submitted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    approved_at TIMESTAMP WITH TIME ZONE,
    expires_at TIMESTAMP WITH TIME ZONE,
    denied_at TIMESTAMP WITH TIME ZONE,
    denied_reason TEXT,
    approved_by UUID REFERENCES public.user_profiles(id),
    clicks_count INTEGER DEFAULT 0,
    impressions_count INTEGER DEFAULT 0,
    placement TEXT NOT NULL DEFAULT 'any' -- any, sidebar, banner
);

-- RLS Policies
ALTER TABLE public.user_advertisements ENABLE ROW LEVEL SECURITY;

-- Users can view their own ads
CREATE POLICY "Users can view their own advertisements" ON public.user_advertisements
    FOR SELECT USING (user_id = auth.uid());

-- Users can create ads
CREATE POLICY "Users can submit advertisements" ON public.user_advertisements
    FOR INSERT WITH CHECK (user_id = auth.uid());

-- Admins can view all ads
CREATE POLICY "Admins can view all advertisements" ON public.user_advertisements
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.user_profiles 
            WHERE id = auth.uid() 
            AND (role IN ('admin', 'secretary', 'lead_troll_officer') OR is_admin = true)
        )
    );

-- Admins can update ads (approve/deny)
CREATE POLICY "Admins can manage advertisements" ON public.user_advertisements
    FOR UPDATE USING (
        EXISTS (
            SELECT 1 FROM public.user_profiles 
            WHERE id = auth.uid() 
            AND (role IN ('admin', 'secretary', 'lead_troll_officer') OR is_admin = true)
        )
    );

-- Everyone can view approved active ads
CREATE POLICY "Everyone can view approved active advertisements" ON public.user_advertisements
    FOR SELECT USING (status = 'approved' AND expires_at > NOW());

-- Function to approve ad and set expiry date
CREATE OR REPLACE FUNCTION public.approve_advertisement(
    p_ad_id UUID,
    p_placement TEXT DEFAULT 'any'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_is_admin BOOLEAN;
BEGIN
    SELECT (role IN ('admin', 'secretary', 'lead_troll_officer') OR is_admin = true)
    INTO v_is_admin
    FROM public.user_profiles
    WHERE id = auth.uid();

    IF NOT v_is_admin THEN
        RETURN jsonb_build_object('success', false, 'message', 'Permission denied');
    END IF;

    UPDATE public.user_advertisements
    SET 
        status = 'approved',
        approved_at = NOW(),
        approved_by = auth.uid(),
        expires_at = NOW() + INTERVAL '7 days',
        placement = p_placement,
        updated_at = NOW()
    WHERE id = p_ad_id;

    RETURN jsonb_build_object('success', true, 'message', 'Advertisement approved successfully');
END;
$$;

-- Function: leave_seat_atomic
CREATE OR REPLACE FUNCTION public.leave_seat_atomic(p_session_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_row public.stream_seat_sessions%ROWTYPE;
BEGIN
    -- Fetch the session first to verify it exists and is active
    SELECT * INTO v_row
    FROM public.stream_seat_sessions
    WHERE id = p_session_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Session not found or not yours');
    END IF;

    IF v_row.status != 'active' AND v_row.status != 'live' AND v_row.status != 'camera_starting' AND v_row.status != 'reserved' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Session not found or not yours');
    END IF;

    UPDATE public.stream_seat_sessions
    SET status = 'left',
        left_at = NOW(),
        updated_at = NOW()
    WHERE id = p_session_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: leave_stream_as_viewer
CREATE OR REPLACE FUNCTION public.leave_stream_as_viewer(
  p_stream_id uuid,
  p_user_id uuid DEFAULT NULL,
  p_guest_id text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_deleted integer := 0;
BEGIN
  IF p_user_id IS NOT NULL AND p_user_id <> auth.uid() THEN
    RETURN jsonb_build_object('released', false, 'reason', 'identity_mismatch');
  END IF;

  DELETE FROM public.stream_viewers sv
  WHERE sv.stream_id = p_stream_id
    AND (
      (p_user_id IS NOT NULL AND sv.user_id = p_user_id)
      OR (p_guest_id IS NOT NULL AND sv.guest_id = p_guest_id)
    );

  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object('released', true, 'rows', v_deleted);
END;
$$;

-- Function: lock_predictions
CREATE OR REPLACE FUNCTION lock_predictions(p_show_id uuid)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_show_record record;
BEGIN
  SELECT * INTO v_show_record FROM auction_shows WHERE id = p_show_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'reason', 'Show not found');
  END IF;

  -- Check if user is the auctioneer or admin
  IF NOT EXISTS (
    SELECT 1 FROM auctioneer_profiles ap
    WHERE ap.id = v_show_record.auctioneer_id AND ap.user_id = auth.uid()
  ) AND NOT EXISTS (
    SELECT 1 FROM user_profiles WHERE id = auth.uid() AND (is_admin = true OR role = 'admin')
  ) THEN
    RETURN json_build_object('success', false, 'reason', 'Only the auctioneer or admin can lock predictions');
  END IF;

  -- Lock predictions
  UPDATE auction_shows SET
    predictions_locked = true,
    predictions_lock_at = now(),
    updated_at = now()
  WHERE id = p_show_id;

  -- Lock all unlocked predictions for this show
  UPDATE auction_predictions SET
    is_locked = true,
    locked_at = now()
  WHERE auction_show_id = p_show_id AND is_locked = false;

  RETURN json_build_object('success', true);
END;
$$;

-- Function: log_admin_action
CREATE OR REPLACE FUNCTION public.log_admin_action(
    p_action_type TEXT,
    p_target_user_id UUID DEFAULT NULL,
    p_reason TEXT DEFAULT NULL,
    p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    INSERT INTO public.admin_actions_log (admin_user_id, target_user_id, action_type, reason, metadata)
    VALUES (auth.uid(), p_target_user_id, p_action_type, p_reason, p_metadata);
END;
$$;

-- Function: log_app_bug_report
CREATE OR REPLACE FUNCTION public.log_app_bug_report(payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET statement_timeout = '5s'
AS $$
DECLARE
  v_id uuid;
  v_now timestamptz := now();
  v_source text := COALESCE(payload->>'source', 'frontend');
  v_severity text := COALESCE(payload->>'severity', 'medium');
  v_page_url text := COALESCE(payload->>'page_url', payload->>'pageUrl');
  v_route_path text := COALESCE(payload->>'route_path', payload->>'routePath');
  v_user_id uuid := nullif(COALESCE(payload->>'user_id', payload->>'userId'), '')::uuid;
  v_user_email text := COALESCE(payload->>'user_email', payload->>'userEmail');
  v_user_role text := COALESCE(payload->>'user_role', payload->>'userRole');
  v_stream_id uuid := nullif(COALESCE(payload->>'stream_id', payload->>'streamId'), '')::uuid;
  v_function_name text := COALESCE(payload->>'function_name', payload->>'functionName');
  v_table_name text := COALESCE(payload->>'table_name', payload->>'tableName');
  v_error_code text := COALESCE(payload->>'error_code', payload->>'errorCode');
  v_error_message text := COALESCE(payload->>'error_message', payload->>'errorMessage', 'Unknown application error');
  v_error_details text := COALESCE(payload->>'error_details', payload->>'errorDetails');
  v_error_hint text := COALESCE(payload->>'error_hint', payload->>'errorHint');
  v_stack_trace text := COALESCE(payload->>'stack_trace', payload->>'stackTrace');
  v_is_duplicate boolean := false;
BEGIN
  IF v_severity NOT IN ('low', 'medium', 'high', 'critical') THEN
    v_severity := 'medium';
  END IF;

  -- Try to update existing duplicate first (uses index, single row lock)
  UPDATE public.app_bug_reports
  SET occurrence_count = COALESCE(occurrence_count, 1) + 1,
      last_seen_at = v_now,
      updated_at = v_now,
      page_url = COALESCE(v_page_url, page_url),
      error_code = COALESCE(v_error_code, error_code),
      error_details = COALESCE(v_error_details, error_details),
      error_hint = COALESCE(v_error_hint, error_hint),
      stack_trace = COALESCE(v_stack_trace, stack_trace),
      request_payload = COALESCE(payload->'request_payload', payload->'requestPayload', request_payload),
      response_payload = COALESCE(payload->'response_payload', payload->'responsePayload', response_payload),
      browser_info = COALESCE(payload->'browser_info', payload->'browserInfo', browser_info),
      app_context = COALESCE(payload->'app_context', payload->'appContext', app_context)
  WHERE id = (
    SELECT id
    FROM public.app_bug_reports
    WHERE source = v_source
      AND route_path IS NOT DISTINCT FROM v_route_path
      AND error_message = v_error_message
      AND status IN ('open', 'in_progress')
      AND last_seen_at > v_now - interval '60 seconds'
    LIMIT 1
    FOR UPDATE SKIP LOCKED
  )
  RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    v_is_duplicate := true;
  ELSE
    -- No duplicate found — insert new row
    BEGIN
      INSERT INTO public.app_bug_reports (
        source, severity, page_url, route_path, user_id, user_email, user_role, stream_id,
        function_name, table_name, error_code, error_message, error_details, error_hint,
        stack_trace, request_payload, response_payload, browser_info, app_context,
        created_at, updated_at, occurrence_count, last_seen_at
      )
      VALUES (
        v_source, v_severity, v_page_url, v_route_path, v_user_id, v_user_email, v_user_role, v_stream_id,
        v_function_name, v_table_name, v_error_code, v_error_message, v_error_details, v_error_hint,
        v_stack_trace,
        COALESCE(payload->'request_payload', payload->'requestPayload'),
        COALESCE(payload->'response_payload', payload->'responsePayload'),
        COALESCE(payload->'browser_info', payload->'browserInfo'),
        COALESCE(payload->'app_context', payload->'appContext'),
        v_now, v_now, 1, v_now
      )
      RETURNING id INTO v_id;
    EXCEPTION
      WHEN unique_violation THEN
        -- Race condition: concurrent insert — fall back to update
        UPDATE public.app_bug_reports
        SET occurrence_count = COALESCE(occurrence_count, 1) + 1,
            last_seen_at = v_now,
            updated_at = v_now
        WHERE source = v_source
          AND route_path IS NOT DISTINCT FROM v_route_path
          AND error_message = v_error_message
          AND status IN ('open', 'in_progress')
        RETURNING id INTO v_id;
        v_is_duplicate := true;
    END;
  END IF;

  RETURN jsonb_build_object('success', true, 'id', v_id, 'duplicate', v_is_duplicate);
EXCEPTION WHEN OTHERS THEN
  RAISE LOG 'log_app_bug_report failed: %', SQLERRM;
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: log_employee_audit
create or replace function public.log_employee_audit(
  p_actor uuid,
  p_action text,
  p_target uuid default null,
  p_previous jsonb default null,
  p_new jsonb default null,
  p_reason text default null,
  p_department text default null,
  p_related text default null
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_id uuid;
  v_actor_role text;
begin
  if p_actor is null or auth.uid() is null then
    raise exception 'unauthorized';
  end if;
  -- Actor must be the caller, or an admin acting on someone's behalf.
  select role into v_actor_role from user_profiles where id = p_actor;
  if p_actor <> auth.uid() and coalesce((select is_admin from user_profiles where id = auth.uid()), false) = false
     and (select role from user_profiles where id = auth.uid()) not in ('admin','superadmin','ceo') then
    raise exception 'unauthorized';
  end if;

  insert into public.employee_audit_log
    (actor_id, target_id, action, previous_value, new_value, reason, department, related_record)
  values (p_actor, p_target, p_action, p_previous, p_new, p_reason, p_department, p_related)
  returning id into v_id;
  return v_id;
end;
$$;

-- Function: log_security_event
CREATE OR REPLACE FUNCTION public.log_security_event(
            p_event_type text,
            p_severity text DEFAULT 'low',
            p_user_id uuid DEFAULT NULL,
            p_actor_id uuid DEFAULT NULL,
            p_target_user_id uuid DEFAULT NULL,
            p_stream_id uuid DEFAULT NULL,
            p_agency_id uuid DEFAULT NULL,
            p_cashout_id uuid DEFAULT NULL,
            p_route text DEFAULT NULL,
            p_source text DEFAULT 'frontend',
            p_title text,
            p_description text DEFAULT NULL,
            p_metadata jsonb DEFAULT '{}'::jsonb,
            p_risk_score integer DEFAULT 0
        )
        RETURNS jsonb AS $$
        DECLARE
            v_event_id uuid;
            v_current_risk_score integer;
            v_new_risk_score integer;
            v_risk_level text;
        BEGIN
            -- Insert the security event
            INSERT INTO public.security_events (
                event_type, severity, user_id, actor_id, target_user_id, stream_id, agency_id, cashout_id,
                ip_address, user_agent, device_fingerprint, route, source, title, description, metadata, risk_score
            ) VALUES (
                p_event_type, p_severity, p_user_id, p_actor_id, p_target_user_id, p_stream_id, p_agency_id, p_cashout_id,
                NULL, NULL, NULL, p_route, p_source, p_title, p_description, p_metadata, p_risk_score
            )
            RETURNING id INTO v_event_id;

            -- Update or insert security_user_risk_scores for the related user
            -- We'll update for p_user_id if provided, otherwise for p_actor_id
            IF p_user_id IS NOT NULL THEN
                -- Get current risk score
                SELECT risk_score INTO v_current_risk_score
                FROM public.security_user_risk_scores
                WHERE user_id = p_user_id;

                IF FOUND THEN
                    v_new_risk_score := LEAST(v_current_risk_score + p_risk_score, 100); -- Cap at 100
                ELSE
                    v_new_risk_score := LEAST(p_risk_score, 100);
                END IF;

                v_risk_level := CASE
                    WHEN v_new_risk_score >= 90 THEN 'critical'
                    WHEN v_new_risk_score >= 60 THEN 'high'
                    WHEN v_new_risk_score >= 25 THEN 'medium'
                    ELSE 'low'
                END;

                INSERT INTO public.security_user_risk_scores (
                    user_id, risk_score, risk_level, last_event_at
                ) VALUES (
                    p_user_id, v_new_risk_score, v_risk_level, now()
                )
                ON CONFLICT (user_id) DO UPDATE
                SET risk_score = EXCLUDED.risk_score,
                    risk_level = EXCLUDED.risk_level,
                    last_event_at = EXCLUDED.last_event_at,
                    updated_at = now();
            ELSIF p_actor_id IS NOT NULL THEN
                -- Also update for actor if no user_id provided
                SELECT risk_score INTO v_current_risk_score
                FROM public.security_user_risk_scores
                WHERE user_id = p_actor_id;

                IF FOUND THEN
                    v_new_risk_score := LEAST(v_current_risk_score + p_risk_score, 100);
                ELSE
                    v_new_risk_score := LEAST(p_risk_score, 100);
                END IF;

                v_risk_level := CASE
                    WHEN v_new_risk_score >= 90 THEN 'critical'
                    WHEN v_new_risk_score >= 60 THEN 'high'
                    WHEN v_new_risk_score >= 25 THEN 'medium'
                    ELSE 'low'
                END;

                INSERT INTO public.security_user_risk_scores (
                    user_id, risk_score, risk_level, last_event_at
                ) VALUES (
                    p_actor_id, v_new_risk_score, v_risk_level, now()
                )
                ON CONFLICT (user_id) DO UPDATE
                SET risk_score = EXCLUDED.risk_score,
                    risk_level = EXCLUDED.risk_level,
                    last_event_at = EXCLUDED.last_event_at,
                    updated_at = now();
            END IF;

            -- Return success
            RETURN jsonb_build_object(
                'success', true,
                'event_id', v_event_id
            );
        END;
        $$ LANGUAGE plpgsql SECURITY DEFINER;
    END IF;
END $$;

-- Function: log_stream_analytics_event
CREATE OR REPLACE FUNCTION public.log_stream_analytics_event(
  p_stream_id uuid,
  p_user_id uuid,
  p_event_type text,
  p_gift_amount bigint DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_event_type NOT IN ('join', 'leave', 'gift', 'stream_start', 'stream_end') THEN
    RETURN;
  END IF;

  IF p_event_type IN ('join', 'leave') AND (p_stream_id IS NULL OR p_user_id IS NULL) THEN
    RETURN;
  END IF;

  -- Prevent duplicate browser/realtime events from StrictMode, refreshes, and reconnect churn.
  IF p_event_type IN ('join', 'leave') AND EXISTS (
    SELECT 1
    FROM public.stream_analytics_events e
    WHERE e.stream_id = p_stream_id
      AND e.user_id = p_user_id
      AND e.event_type = p_event_type
      AND e.created_at > now() - interval '30 seconds'
  ) THEN
    RETURN;
  END IF;

  INSERT INTO public.stream_analytics_events (stream_id, user_id, event_type, gift_amount)
  VALUES (p_stream_id, p_user_id, p_event_type, GREATEST(COALESCE(p_gift_amount, 0), 0));
EXCEPTION WHEN unique_violation THEN
  RETURN;
END;
$$;

-- Function: manage_agency_member
CREATE OR REPLACE FUNCTION public.manage_agency_member(
    p_member_id UUID,
    p_actor_id UUID,
    p_action TEXT,
    p_reason TEXT DEFAULT ''
)
RETURNS public.agency_members
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
    v_member public.agency_members;
    v_actor_role TEXT;
BEGIN
    SELECT m.*
    INTO v_member
    FROM public.agency_members m
    WHERE m.id = p_member_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agency membership not found';
    END IF;

    SELECT role
    INTO v_actor_role
    FROM public.agency_members
    WHERE agency_id = v_member.agency_id
      AND user_id = p_actor_id
      AND status = 'active'
    LIMIT 1;

    IF v_actor_role IS NULL THEN
        RAISE EXCEPTION 'You do not have permission to manage this agency';
    END IF;

    IF v_member.role = 'owner' THEN
        RAISE EXCEPTION 'You cannot manage the agency owner';
    END IF;

    IF v_actor_role = 'manager' AND v_member.role = 'manager' THEN
        RAISE EXCEPTION 'Managers cannot manage other managers';
    END IF;

    IF p_action NOT IN ('suspend', 'remove', 'restore') THEN
        RAISE EXCEPTION 'Unsupported action %', p_action;
    END IF;

    CASE p_action
        WHEN 'suspend' THEN
            UPDATE public.agency_members
            SET status = 'suspended', removed_at = NULL
            WHERE id = p_member_id
            RETURNING *
            INTO v_member;

            INSERT INTO public.agency_enforcement_actions (
                agency_id,
                actor_id,
                target_user_id,
                action_type,
                reason,
                metadata
            )
            VALUES (
                v_member.agency_id,
                p_actor_id,
                v_member.user_id,
                'member_suspended',
                p_reason,
                jsonb_build_object('member_id', p_member_id, 'action', p_action)
            );

        WHEN 'remove' THEN
            UPDATE public.agency_members
            SET status = 'removed', removed_at = NOW()
            WHERE id = p_member_id
            RETURNING *
            INTO v_member;

            INSERT INTO public.agency_enforcement_actions (
                agency_id,
                actor_id,
                target_user_id,
                action_type,
                reason,
                metadata
            )
            VALUES (
                v_member.agency_id,
                p_actor_id,
                v_member.user_id,
                'member_removed',
                p_reason,
                jsonb_build_object('member_id', p_member_id, 'action', p_action)
            );

        WHEN 'restore' THEN
            UPDATE public.agency_members
            SET status = 'active', removed_at = NULL
            WHERE id = p_member_id
            RETURNING *
            INTO v_member;

            INSERT INTO public.agency_enforcement_actions (
                agency_id,
                actor_id,
                target_user_id,
                action_type,
                reason,
                metadata
            )
            VALUES (
                v_member.agency_id,
                p_actor_id,
                v_member.user_id,
                'member_restored',
                p_reason,
                jsonb_build_object('member_id', p_member_id, 'action', p_action)
            );
    END CASE;

    INSERT INTO public.agency_activity_logs (
        agency_id,
        actor_id,
        target_user_id,
        action,
        metadata
    )
    VALUES (
        v_member.agency_id,
        p_actor_id,
        v_member.user_id,
        'agency_member_' || p_action,
        jsonb_build_object('member_id', p_member_id, 'reason', p_reason)
    );

    RETURN v_member;
END;
$$;

-- Function: manage_court_case_safe
CREATE OR REPLACE FUNCTION public.manage_court_case_safe(
    p_defendant_id UUID,
    p_reason TEXT,
    p_court_date DATE
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_caller_role TEXT;
    v_caller_id UUID;
    v_is_authorized BOOLEAN;
BEGIN
    v_caller_id := auth.uid();
    
    -- Check if caller is authorized (Admin, Officer, Lead, Secretary)
    SELECT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = v_caller_id 
        AND (
            role IN ('admin', 'secretary', 'troll_officer', 'lead_troll_officer') 
            OR is_admin = true 
            OR is_troll_officer = true
            OR is_lead_officer = true
            OR troll_role IN ('admin', 'secretary', 'troll_officer', 'lead_troll_officer')
        )
    ) INTO v_is_authorized;

    IF NOT v_is_authorized THEN
        RAISE EXCEPTION 'Unauthorized: You do not have permission to create court cases.';
    END IF;

    -- Call the internal function
    RETURN public.manage_court_case(p_defendant_id, v_caller_id, p_reason, p_court_date);
END;
$$;

-- Function: manual_clock_in
CREATE OR REPLACE FUNCTION public.manual_clock_in(p_officer_id uuid DEFAULT auth.uid())
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_active_session_id uuid;
BEGIN
    -- Check if officer already has an active session
    SELECT id INTO v_active_session_id
    FROM officer_work_sessions
    WHERE officer_id = p_officer_id 
    AND clock_out IS NULL 
    LIMIT 1;

    IF v_active_session_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Officer already has an active session');
    END IF;

    -- Create new session
    INSERT INTO officer_work_sessions (officer_id, clock_in, status)
    VALUES (p_officer_id, now(), 'active');

    -- Update officer status in user_profiles
    UPDATE user_profiles 
    SET is_officer_active = true,
        last_activity_at = now()
    WHERE id = p_officer_id;

    RETURN jsonb_build_object('success', true, 'message', 'Clocked in successfully');
END;
$$;

-- Function: manual_clock_out
CREATE OR REPLACE FUNCTION public.manual_clock_out(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_session public.officer_work_sessions%rowtype;
    v_now timestamptz := now();
    v_hours numeric;
    v_coins bigint;
    v_hourly_rate bigint := 500;
    v_break_minutes int := 0;
BEGIN
    SELECT * INTO v_session FROM public.officer_work_sessions WHERE id = p_session_id;

    IF v_session.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Session not found');
    END IF;

    -- If on break, close it first
    IF v_session.status = 'break' THEN
        v_break_minutes := EXTRACT(EPOCH FROM (v_now - v_session.last_break_start)) / 60;
        -- Update total break minutes in memory for calculation
        v_session.total_break_minutes := COALESCE(v_session.total_break_minutes, 0) + v_break_minutes;
    END IF;

    -- Calculate hours worked (excluding breaks)
    -- Total duration in hours
    v_hours := EXTRACT(EPOCH FROM (v_now - v_session.clock_in)) / 3600;
    -- Subtract break hours
    v_hours := v_hours - (COALESCE(v_session.total_break_minutes, 0)::numeric / 60.0);
    
    IF v_hours < 0 THEN v_hours := 0; END IF;

    v_coins := floor(v_hours * v_hourly_rate);

    UPDATE public.officer_work_sessions
    SET clock_out = v_now,
        status = 'completed',
        hours_worked = v_hours,
        coins_earned = v_coins,
        last_break_start = NULL, -- Clear temporary state
        total_break_minutes = COALESCE(total_break_minutes, 0) + CASE WHEN v_session.status = 'break' THEN v_break_minutes ELSE 0 END
    WHERE id = p_session_id;

    -- Update profile
    UPDATE public.user_profiles
    SET is_officer_active = false,
        last_activity_at = v_now
    WHERE id = v_session.officer_id;

    RETURN jsonb_build_object('success', true, 'message', 'Clocked out successfully', 'hours', v_hours, 'coins', v_coins);
END;
$$;

-- Function: manual_end_break
CREATE OR REPLACE FUNCTION public.manual_end_break(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_session public.officer_work_sessions%rowtype;
    v_minutes int;
BEGIN
    SELECT * INTO v_session FROM public.officer_work_sessions WHERE id = p_session_id;
    
    IF v_session.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Session not found');
    END IF;

    IF v_session.status != 'break' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Not on break');
    END IF;

    -- Calculate minutes
    v_minutes := EXTRACT(EPOCH FROM (now() - v_session.last_break_start)) / 60;

    UPDATE public.officer_work_sessions
    SET status = 'active',
        last_break_start = NULL,
        total_break_minutes = COALESCE(total_break_minutes, 0) + v_minutes
    WHERE id = p_session_id;

    RETURN jsonb_build_object('success', true, 'message', 'Break ended', 'minutes', v_minutes);
END;
$$;

-- Function: manual_start_break
CREATE OR REPLACE FUNCTION public.manual_start_break(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_session public.officer_work_sessions%rowtype;
BEGIN
    SELECT * INTO v_session FROM public.officer_work_sessions WHERE id = p_session_id;
    
    IF v_session.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Session not found');
    END IF;

    IF v_session.status = 'break' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Already on break');
    END IF;
    
    IF v_session.clock_out IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Session already ended');
    END IF;

    UPDATE public.officer_work_sessions
    SET status = 'break',
        last_break_start = now()
    WHERE id = p_session_id;

    RETURN jsonb_build_object('success', true, 'message', 'Break started');
END;
$$;

-- Function: mark_conversation_read
