-- Function: mark_onboarding_complete
CREATE OR REPLACE FUNCTION public.mark_onboarding_complete(p_user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_profile_exists boolean;
BEGIN
  -- Verify user exists and has required fields
  SELECT EXISTS(
    SELECT 1 FROM public.user_profiles
    WHERE id = p_user_id
      AND username IS NOT NULL
      AND length(username) >= 2
  ) INTO v_profile_exists;

  IF NOT v_profile_exists THEN
    RETURN false;
  END IF;

  UPDATE public.user_profiles
  SET onboarding_complete = true
  WHERE id = p_user_id
    AND (onboarding_complete = false OR onboarding_complete IS NULL);

  RETURN true;
END;
$$;

-- Function: mark_payout_window_notified
CREATE OR REPLACE FUNCTION public.mark_payout_window_notified()
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_config JSONB;
BEGIN
  SELECT setting_value INTO v_config
  FROM public.admin_app_settings
  WHERE setting_key = 'payout_window_config'
  FOR UPDATE;

  IF v_config IS NOT NULL THEN
    v_config := jsonb_set(v_config, '{notified_users}', 'true');
    UPDATE public.admin_app_settings
    SET setting_value = v_config,
        updated_at = now()
    WHERE setting_key = 'payout_window_config';
  END IF;
END;
$$;

-- Function: mark_sidebar_viewed
CREATE OR REPLACE FUNCTION public.mark_sidebar_viewed(p_path TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    INSERT INTO public.user_sidebar_views (user_id, path, last_viewed_at)
    VALUES (auth.uid(), p_path, NOW())
