-- Function: mark_stream_seat_live
CREATE OR REPLACE FUNCTION public.mark_stream_seat_live(
    p_stream_id UUID,
    p_seat_index INTEGER,
    p_livekit_participant_identity TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    UPDATE public.stream_seat_sessions
    SET status = 'live',
        livekit_participant_identity = COALESCE(p_livekit_participant_identity, livekit_participant_identity),
        updated_at = NOW()
    WHERE stream_id = p_stream_id
      AND seat_index = p_seat_index
      AND status IN ('active', 'camera_starting', 'reserved');

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    IF v_updated = 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'No active seat session found for this seat');
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: mod_arrest_user
CREATE OR REPLACE FUNCTION public.mod_arrest_user(
    p_target_user_id UUID,
    p_stream_id UUID,
    p_reason TEXT,
    p_severity TEXT DEFAULT 'moderate',
    p_bail_amount NUMERIC(12,2) DEFAULT 100,
    p_duration_minutes INTEGER DEFAULT 60,
    p_broadcast_recorded BOOLEAN DEFAULT false,
    p_fine_amount NUMERIC(12,2) DEFAULT 0,
    p_internal_notes TEXT DEFAULT NULL,
    p_evidence_urls JSONB DEFAULT '[]'::jsonb,
    p_evidence_type TEXT DEFAULT NULL,
    p_evidence_notes TEXT DEFAULT NULL,
    p_actor_id UUID DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_actor_id UUID;
    v_actor_role TEXT;
    v_target_username TEXT;
    v_action_id UUID;
    v_expires TIMESTAMPTZ;
    v_risk_score INTEGER;
    v_strikes INTEGER;
BEGIN
    v_actor_id := COALESCE(p_actor_id, auth.uid());

    IF p_reason IS NULL OR TRIM(p_reason) = '' THEN
        RETURN json_build_object('success', false, 'message', 'Arrest reason is required');
    END IF;
    IF NOT public.is_staff_user(v_actor_id) THEN
        RETURN json_build_object('success', false, 'message', 'Not authorized to arrest');
    END IF;

    SELECT COALESCE(role, troll_role, 'unknown') INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;
    SELECT username INTO v_target_username FROM public.user_profiles WHERE id = p_target_user_id;
    v_expires := NOW() + (p_duration_minutes || ' minutes')::INTERVAL;

    INSERT INTO public.broadcast_mod_actions (
        actor_id, actor_role, target_user_id, action_type,
        stream_id, reason, severity, bail_amount, duration_minutes,
        broadcast_recorded, fine_amount, internal_notes,
        evidence_urls, evidence_type, evidence_notes,
        expires_at, status
    ) VALUES (
        v_actor_id, v_actor_role, p_target_user_id, 'arrest',
        p_stream_id, p_reason, p_severity, p_bail_amount, p_duration_minutes,
        p_broadcast_recorded, p_fine_amount, p_internal_notes,
        p_evidence_urls, p_evidence_type, p_evidence_notes,
        v_expires, 'active'
    ) RETURNING id INTO v_action_id;

    v_risk_score := public.update_user_risk_score(p_target_user_id, 'arrest', p_severity);
    v_strikes := public.update_user_strikes(p_target_user_id, 'arrest');
    PERFORM public.insert_mod_audit(v_action_id, 'created', v_actor_id, NULL,
        json_build_object('action_type', 'arrest', 'severity', p_severity, 'fine_amount', p_fine_amount));

    RETURN json_build_object(
        'success', true, 'action_id', v_action_id,
        'message', COALESCE(v_target_username, 'User') || ' has been arrested. Reason: ' || p_reason,
        'expires_at', v_expires, 'bail_amount', p_bail_amount,
        'risk_score', v_risk_score, 'strike_count', v_strikes
    );
END;
$$;

-- Function: moderator_delete_stream_message
CREATE OR REPLACE FUNCTION public.moderator_delete_stream_message(
  p_stream_id uuid,
  p_message_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
BEGIN
  IF NOT public.can_moderate_stream(p_stream_id, v_actor_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;

  DELETE FROM public.stream_messages
  WHERE id = p_message_id
    AND stream_id = p_stream_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: moderator_disable_chat
CREATE OR REPLACE FUNCTION public.moderator_disable_chat(
  p_stream_id uuid,
  p_target_user_id uuid,
  p_duration_minutes integer DEFAULT NULL,
  p_reason text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_existing_strike_count integer := 0;
  v_effective_duration integer;
  v_expires_at timestamptz;
  v_is_permanent boolean := false;
BEGIN
  IF NOT public.can_moderate_stream(p_stream_id, v_actor_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;

  -- Check for existing active block to determine strike count
  SELECT COALESCE(MAX(strike_count), 0)
  INTO v_existing_strike_count
  FROM public.chat_blocks
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  -- If caller explicitly provided a duration, use it; otherwise calculate from strike count
  IF p_duration_minutes IS NOT NULL THEN
    v_effective_duration := GREATEST(p_duration_minutes, 1);
  ELSE
    -- Escalating durations based on previous strikes
    v_effective_duration := CASE v_existing_strike_count
      WHEN 0 THEN 5
      WHEN 1 THEN 10
      WHEN 2 THEN 15
      WHEN 3 THEN 30
      WHEN 4 THEN 60
      ELSE NULL  -- permanent
    END;
  END IF;

  -- If duration is NULL, it means permanent (6+ strikes)
  IF v_effective_duration IS NULL THEN
    v_is_permanent := true;
    v_expires_at := now() + interval '100 years';
  ELSE
    v_expires_at := now() + make_interval(mins => v_effective_duration);
  END IF;

  -- Upsert the chat block with incremented strike count
  INSERT INTO public.chat_blocks (stream_id, user_id, blocked_by, expires_at, reason, strike_count, is_permanent)
  VALUES (
    p_stream_id,
    p_target_user_id,
    v_actor_id,
    v_expires_at,
    COALESCE(p_reason, 'Chat disabled by moderator'),
    v_existing_strike_count + 1,
    v_is_permanent
  )
  ON CONFLICT (stream_id, user_id)
  DO UPDATE SET
    blocked_by = v_actor_id,
    expires_at = v_expires_at,
    reason = COALESCE(p_reason, 'Chat disabled by moderator'),
    created_at = now(),
    strike_count = v_existing_strike_count + 1,
    is_permanent = v_is_permanent;

  RETURN jsonb_build_object(
    'success', true,
    'expires_at', v_expires_at,
    'is_permanent', v_is_permanent,
    'strike_count', v_existing_strike_count + 1,
    'duration_minutes', v_effective_duration
  );
END;
$$;

-- Function: moderator_kick_user
CREATE OR REPLACE FUNCTION public.moderator_kick_user(
  p_stream_id uuid,
  p_target_user_id uuid,
  p_reason text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_expires_at timestamptz := now() + interval '24 hours';
  v_identity_text text := p_target_user_id::text;
BEGIN
  IF NOT public.can_moderate_stream(p_stream_id, v_actor_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;

  INSERT INTO public.stream_kicks (stream_id, user_id, kicked_by, created_by, reason)
  VALUES (p_stream_id, p_target_user_id, v_actor_id, v_actor_id, COALESCE(p_reason, 'Kicked by moderator'));

  UPDATE public.stream_bans
  SET banned_by = v_actor_id,
      created_by = v_actor_id,
      reason = COALESCE(p_reason, 'Kicked by moderator'),
      expires_at = v_expires_at
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  IF NOT FOUND THEN
    INSERT INTO public.stream_bans (stream_id, user_id, banned_by, created_by, reason, expires_at)
    VALUES (p_stream_id, p_target_user_id, v_actor_id, v_actor_id, COALESCE(p_reason, 'Kicked by moderator'), v_expires_at);
  END IF;

  -- Mark active seat sessions as kicked (supports both user_id and guest_id identities).
  UPDATE public.stream_seat_sessions
  SET status = 'kicked',
      kick_reason = COALESCE(p_reason, 'Kicked by moderator'),
      left_at = now()
  WHERE stream_id = p_stream_id
    AND status = 'active'
    AND (
      user_id = p_target_user_id
      OR guest_id = v_identity_text
    );

  -- Remove participant rows from legacy presence table.
  DELETE FROM public.stream_participants
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  -- Remove live viewer heartbeat rows so UI updates immediately.
  DELETE FROM public.stream_viewers
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  RETURN jsonb_build_object('success', true, 'expires_at', v_expires_at);
END;
$$;

-- Function: moderator_mute_user
CREATE OR REPLACE FUNCTION public.moderator_mute_user(
  p_stream_id uuid,
  p_target_user_id uuid,
  p_duration_minutes integer DEFAULT 5,
  p_reason text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_host_id uuid;
  v_expires_at timestamptz := now() + make_interval(mins => GREATEST(COALESCE(p_duration_minutes, 5), 1));
BEGIN
  IF NOT public.can_moderate_stream(p_stream_id, v_actor_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;

  SELECT user_id INTO v_host_id FROM public.streams WHERE id = p_stream_id;

  UPDATE public.stream_mutes
  SET muted_by = v_actor_id,
      expires_at = v_expires_at,
      reason = COALESCE(p_reason, 'Muted by moderator'),
      created_at = now()
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  IF NOT FOUND THEN
    INSERT INTO public.stream_mutes (stream_id, user_id, muted_by, expires_at, reason)
    VALUES (p_stream_id, p_target_user_id, v_actor_id, v_expires_at, COALESCE(p_reason, 'Muted by moderator'));
  END IF;

  IF p_target_user_id = v_host_id THEN
    UPDATE public.user_profiles
    SET broadcast_mic_muted = true
    WHERE id = p_target_user_id;
  END IF;

  UPDATE public.stream_participants
  SET mic_muted = true
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  RETURN jsonb_build_object('success', true, 'expires_at', v_expires_at);
END;
$$;

-- Function: moderator_unmute_user
CREATE OR REPLACE FUNCTION public.moderator_unmute_user(
  p_stream_id uuid,
  p_target_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_host_id uuid;
BEGIN
  IF NOT public.can_moderate_stream(p_stream_id, v_actor_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;

  SELECT user_id INTO v_host_id FROM public.streams WHERE id = p_stream_id;

  DELETE FROM public.stream_mutes
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  IF p_target_user_id = v_host_id THEN
    UPDATE public.user_profiles
    SET broadcast_mic_muted = false
    WHERE id = p_target_user_id;
  END IF;

  UPDATE public.stream_participants
  SET mic_muted = false
  WHERE stream_id = p_stream_id
    AND user_id = p_target_user_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: notify_payouts_open_if_needed
CREATE OR REPLACE FUNCTION public.notify_payouts_open_if_needed()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_count integer := 0;
  v_exists boolean := false;
  v_day integer;
  v_hour integer;
BEGIN
  -- Get current day of week (0=Sunday, 1=Monday, ..., 6=Saturday) in UTC
  SELECT EXTRACT(DOW FROM NOW() AT TIME ZONE 'UTC') INTO v_day;
  -- Get current hour in UTC
  SELECT EXTRACT(HOUR FROM NOW() AT TIME ZONE 'UTC') INTO v_hour;

  -- Only allow notification on Monday (1) or Friday (5)
  IF v_day NOT IN (1, 5) THEN
    RETURN 0;
  END IF;

  -- Only allow notification at 1:00 AM MST (8:00 AM UTC)
  -- We use a window of 8 to 9 AM to ensure it triggers once
  IF v_hour != 8 THEN
    RETURN 0;
  END IF;

  -- Check if we already notified today
  SELECT EXISTS (
    SELECT 1
    FROM public.notifications
    WHERE title = 'Payouts are now open'
      AND type = 'system_update'
      AND created_at::date = now()::date
  ) INTO v_exists;

  IF v_exists THEN
    RETURN 0;
  END IF;

  SELECT public.notify_all_users(
    'Payouts are now open',
    'Payouts are now open!',
    'system_update'
  ) INTO v_count;

  RETURN v_count;
END;
$$;

-- Function: org_get_moderation_history
CREATE OR REPLACE FUNCTION public.org_get_moderation_history(
    p_org_type text,
    p_org_id   uuid,
    p_limit    integer DEFAULT 100
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_actor uuid := auth.uid();
    v_rows  jsonb;
BEGIN
    IF v_actor IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    IF NOT public.org_can_moderate(p_org_type, p_org_id, v_actor) THEN
        RETURN jsonb_build_object('success', false, 'error', 'You do not lead this organization');
    END IF;

    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_rows
    FROM (
        SELECT
            oma.id, oma.actor_id, oma.target_user_id, oma.action, oma.reason,
            oma.duration_minutes, oma.status, oma.created_at, oma.expires_at,
            oma.revoked_at, oma.revoked_by,
            actor.username  AS actor_username,
            target.username AS target_username
        FROM public.org_moderation_actions oma
        LEFT JOIN public.user_profiles actor  ON actor.id  = oma.actor_id
        LEFT JOIN public.user_profiles target ON target.id = oma.target_user_id
        WHERE oma.org_type = p_org_type AND oma.org_id = p_org_id
        ORDER BY oma.created_at DESC
        LIMIT COALESCE(p_limit, 100)
    ) t;

    RETURN jsonb_build_object('success', true, 'history', v_rows);
END;
$$;

-- Function: org_moderate_member
CREATE OR REPLACE FUNCTION public.org_moderate_member(
    p_org_type         text,
    p_org_id           uuid,
    p_target_user_id   uuid,
    p_action           text,
    p_reason           text DEFAULT NULL,
    p_duration_minutes integer DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_actor       uuid := auth.uid();
    v_expires_at  timestamptz;
    v_action_id   uuid;
    v_target_name text;
    v_org_name    text;
BEGIN
    IF v_actor IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    IF p_org_type NOT IN ('family','agency') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid organization type');
    END IF;

    IF p_action NOT IN ('warn','mute','remove_from_chat','remove_from_org','restrict','report') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid action');
    END IF;

    -- Authority check: actor must control this org (scoped, never global)
    IF NOT public.org_can_moderate(p_org_type, p_org_id, v_actor) THEN
        RETURN jsonb_build_object('success', false, 'error', 'You do not lead this organization');
    END IF;

    -- Target must belong to the same org
    IF NOT public.org_is_member(p_org_type, p_org_id, p_target_user_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Target is not a member of this organization');
    END IF;

    -- Cannot moderate yourself
    IF p_target_user_id = v_actor THEN
        RETURN jsonb_build_object('success', false, 'error', 'You cannot moderate yourself');
    END IF;

    -- Leaders cannot moderate the org leader/owner
    IF p_org_type = 'family' AND EXISTS (
        SELECT 1 FROM public.troll_families WHERE id = p_org_id AND leader_id = p_target_user_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'You cannot moderate the family leader');
    END IF;
    IF p_org_type = 'agency' AND EXISTS (
        SELECT 1 FROM public.agencies WHERE id = p_org_id AND owner_id = p_target_user_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'You cannot moderate the agency owner');
    END IF;

    -- Compute expiration for time-boxed actions
    IF p_duration_minutes IS NOT NULL AND p_duration_minutes > 0
       AND p_action IN ('mute','remove_from_chat','restrict') THEN
        v_expires_at := now() + (p_duration_minutes || ' minutes')::interval;
    END IF;

    -- Resolve names for notifications
    SELECT COALESCE(username, display_name, 'Unknown') INTO v_target_name
        FROM public.user_profiles WHERE id = p_target_user_id;
    IF p_org_type = 'family' THEN
        SELECT COALESCE(family_name, name, 'your family') INTO v_org_name
            FROM public.troll_families WHERE id = p_org_id;
    ELSE
        SELECT COALESCE(name, 'your agency') INTO v_org_name
            FROM public.agencies WHERE id = p_org_id;
    END IF;

    -- Perform the action side-effects
    IF p_action = 'remove_from_chat' THEN
        IF p_org_type = 'agency' THEN
            RETURN jsonb_build_object('success', false, 'error', 'Agency chat is not available');
        END IF;
        -- Supersede any earlier active chat restriction for this member
        UPDATE public.org_moderation_actions
            SET status = 'revoked', revoked_at = now(), revoked_by = v_actor
            WHERE org_type = p_org_type AND org_id = p_org_id
              AND target_user_id = p_target_user_id
              AND action = 'remove_from_chat' AND status = 'active';

    ELSIF p_action = 'mute' THEN
        UPDATE public.org_moderation_actions
            SET status = 'revoked', revoked_at = now(), revoked_by = v_actor
            WHERE org_type = p_org_type AND org_id = p_org_id
              AND target_user_id = p_target_user_id
              AND action = 'mute' AND status = 'active';

    ELSIF p_action = 'restrict' THEN
        UPDATE public.org_moderation_actions
            SET status = 'revoked', revoked_at = now(), revoked_by = v_actor
            WHERE org_type = p_org_type AND org_id = p_org_id
              AND target_user_id = p_target_user_id
              AND action = 'restrict' AND status = 'active';

    ELSIF p_action = 'remove_from_org' THEN
        IF p_org_type = 'family' THEN
            DELETE FROM public.family_members
                WHERE family_id = p_org_id AND user_id = p_target_user_id;
        ELSE
            UPDATE public.agency_members
                SET status = 'removed', removed_at = now(), updated_at = now()
                WHERE agency_id = p_org_id AND user_id = p_target_user_id;
        END IF;

    ELSIF p_action = 'report' THEN
        -- Report to staff (best-effort; do not fail the audit if schema differs)
        BEGIN
            INSERT INTO public.user_safety_warnings
                (target_user_id, actor_user_id, source, severity, category, note, status)
            VALUES
                (p_target_user_id, v_actor,
                 CASE WHEN p_org_type = 'family' THEN 'family' ELSE 'agency' END,
                 'medium', 'organization',
                 COALESCE(p_reason, 'Reported by ' || p_org_type || ' leader'),
                 'open');
        EXCEPTION WHEN OTHERS THEN
            NULL; -- audit record below is the durable trail
        END;
    END IF;

    -- Write audit record
    INSERT INTO public.org_moderation_actions
        (actor_id, target_user_id, org_type, org_id, action, reason,
         duration_minutes, expires_at, status)
    VALUES
        (v_actor, p_target_user_id, p_org_type, p_org_id, p_action, p_reason,
         p_duration_minutes, v_expires_at, 'active')
    RETURNING id INTO v_action_id;

    -- Notify the target member (best-effort)
    BEGIN
        INSERT INTO public.notifications (user_id, type, title, message, metadata)
        VALUES (
            p_target_user_id,
            'org_moderation',
            CASE p_action
                WHEN 'warn' THEN 'Warning from ' || v_org_name
                WHEN 'mute' THEN 'You were muted in ' || v_org_name
                WHEN 'remove_from_chat' THEN 'Removed from chat in ' || v_org_name
                WHEN 'remove_from_org' THEN 'Removed from ' || v_org_name
                WHEN 'restrict' THEN 'Restricted in ' || v_org_name
                WHEN 'report' THEN 'You were reported to staff'
                ELSE 'Moderation action'
            END,
            COALESCE(p_reason, 'A moderation action was taken by your ' || p_org_type || ' leader.'),
            jsonb_build_object(
                'org_type', p_org_type, 'org_id', p_org_id,
                'action', p_action, 'action_id', v_action_id,
                'expires_at', v_expires_at
            )
        );
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;

    RETURN jsonb_build_object(
        'success', true,
        'action_id', v_action_id,
        'action', p_action,
        'expires_at', v_expires_at
    );
END;
$$;

-- Function: pay_bank_loan
CREATE OR REPLACE FUNCTION public.pay_bank_loan(
    p_loan_id UUID,
    p_amount BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_loan RECORD;
    v_balance BIGINT;
    v_credit_increase BIGINT;
    v_new_score INTEGER;
    v_current_score INTEGER;
    v_actual_pay BIGINT;
BEGIN
    -- 1. Verify Loan
    SELECT * INTO v_loan FROM public.loans WHERE id = p_loan_id;

    IF NOT FOUND OR v_loan.user_id != v_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Loan not found');
    END IF;

    IF v_loan.status != 'active' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Loan is not active');
    END IF;

    -- Cap amount to remaining balance
    v_actual_pay := p_amount;
    IF v_actual_pay > v_loan.balance THEN
        v_actual_pay := v_loan.balance;
    END IF;

    IF v_actual_pay <= 0 THEN
         RETURN jsonb_build_object('success', false, 'error', 'Invalid amount');
    END IF;

    -- 2. Check User Balance
    SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    IF v_balance < v_actual_pay THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient coins');
    END IF;

    -- 3. Process Payment
    -- Deduct coins
    UPDATE public.user_profiles 
    SET troll_coins = troll_coins - v_actual_pay 
    WHERE id = v_user_id;

    -- Log Ledger
    INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, metadata)
    VALUES (v_user_id, -v_actual_pay, 'loan_repayment', 'bank', 'Manual Loan Repayment', jsonb_build_object('loan_id', p_loan_id));

    -- Update Loan
    UPDATE public.loans
    SET balance = balance - v_actual_pay,
        status = CASE WHEN (balance - v_actual_pay) <= 0 THEN 'paid' ELSE 'active' END
    WHERE id = p_loan_id;

    -- 4. Check for Full Payment & Credit Score Increase
    IF (v_loan.balance - v_actual_pay) <= 0 THEN
        -- Calculate 5% of principal
        v_credit_increase := FLOOR(v_loan.principal * 0.05);

        IF v_credit_increase > 0 THEN
            -- Get current score (lock for update)
            SELECT score INTO v_current_score FROM public.user_credit WHERE user_id = v_user_id FOR UPDATE;
            
            IF v_current_score IS NULL THEN
                v_current_score := 400; -- Default
                INSERT INTO public.user_credit (user_id, score, tier, trend_7d, updated_at)
                VALUES (v_user_id, 400, 'Building', 0, NOW());
            END IF;

            -- Update Score (Cap at 800)
            v_new_score := LEAST(800, v_current_score + v_credit_increase);

            IF v_new_score > v_current_score THEN
                UPDATE public.user_credit
                SET score = v_new_score,
                    tier = public.get_credit_tier(v_new_score),
                    updated_at = NOW(),
                    last_event_at = NOW()
                WHERE user_id = v_user_id;

                -- Log Credit Event
                INSERT INTO public.credit_events (
                    user_id,
                    event_type,
                    delta,
                    source_table,
                    source_id,
                    metadata
                ) VALUES (
                    v_user_id,
                    'loan_repaid',
                    v_new_score - v_current_score,
                    'loans',
                    p_loan_id,
                    jsonb_build_object('principal', v_loan.principal, 'percentage', '5%', 'increase', v_credit_increase)
                );
            END IF;
        END IF;
    END IF;

    RETURN jsonb_build_object('success', true, 'paid', v_actual_pay, 'remaining', v_loan.balance - v_actual_pay);
END;
$$;

-- Function: pay_broadofficer_individual
CREATE OR REPLACE FUNCTION public.pay_broadofficer_individual(
    p_stream_id UUID,
    p_officer_id UUID,
    p_amount INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_stream RECORD;
    v_officer_id UUID;
    v_broadcaster_balance BIGINT;
    v_officer_balance BIGINT;
BEGIN
    SELECT user_id INTO v_stream.user_id FROM public.streams WHERE id = p_stream_id;
    IF v_stream.user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Stream not found');
    END IF;

    IF auth.uid() != v_stream.user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Only the stream broadcaster can pay officers');
    END IF;

    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Amount must be positive');
    END IF;

    IF p_officer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Officer ID is required');
    END IF;

    SELECT officer_id INTO v_officer_id
    FROM public.broadcast_officers
    WHERE broadcaster_id = v_stream.user_id
      AND stream_id = p_stream_id
      AND officer_id = p_officer_id;

    IF v_officer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Officer not found for this stream');
    END IF;

    UPDATE public.user_profiles SET troll_coins = troll_coins - p_amount WHERE id = v_stream.user_id RETURNING troll_coins INTO v_broadcaster_balance;
    UPDATE public.user_profiles SET troll_coins = troll_coins + p_amount WHERE id = v_officer_id RETURNING troll_coins INTO v_officer_balance;

    BEGIN
      UPDATE public.broadcast_officers
      SET last_paid_at = NOW(),
          total_paid = COALESCE(total_paid, 0) + p_amount
      WHERE broadcaster_id = v_stream.user_id
        AND stream_id = p_stream_id
        AND officer_id = p_officer_id;
    EXCEPTION
      WHEN undefined_column THEN
        NULL;
    END;

    RETURN jsonb_build_object(
        'success', true,
        'broadcaster_balance', v_broadcaster_balance,
        'officer_balance', v_officer_balance,
        'paid_amount', p_amount
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: pay_credit_card
CREATE OR REPLACE FUNCTION public.pay_credit_card(p_amount BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_profile RECORD;
    v_pay_amount BIGINT;
    v_new_credit_used BIGINT;
    v_new_credit_score INTEGER;
    v_new_tier TEXT;
    v_score_increase INTEGER := 5;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Not authenticated');
    END IF;

    IF p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Amount must be positive');
    END IF;

    SELECT * INTO v_profile
    FROM public.user_profiles
    WHERE id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'User profile not found');
    END IF;

    IF v_profile.credit_used <= 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'No credit debt to pay');
    END IF;

    -- Cap payment to debt
    v_pay_amount := LEAST(p_amount, v_profile.credit_used);

    -- Check Coin Balance
    IF v_profile.troll_coins < v_pay_amount THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient Troll Coins');
    END IF;

    -- Calculate new credit score (raise by 5 per payment, capped at 800)
    v_new_credit_score := LEAST(COALESCE(v_profile.credit_score, 400) + v_score_increase, 800);

    -- Compute new tier
    v_new_tier := CASE
        WHEN v_new_credit_score < 300 THEN 'Untrusted'
        WHEN v_new_credit_score < 450 THEN 'Shaky'
        WHEN v_new_credit_score < 600 THEN 'Building'
        WHEN v_new_credit_score < 700 THEN 'Reliable'
        WHEN v_new_credit_score < 800 THEN 'Trusted'
        ELSE 'Elite'
    END;

    -- Atomic update with credit score raise
    UPDATE public.user_profiles
    SET
        troll_coins = troll_coins - v_pay_amount,
        credit_used = credit_used - v_pay_amount,
        last_credit_payment_at = NOW(),
        credit_default_warning_sent = FALSE,
        credit_score = v_new_credit_score
    WHERE id = v_user_id
    RETURNING credit_used INTO v_new_credit_used;

    -- Update user_credit table to keep scores in sync
    INSERT INTO public.user_credit (user_id, score, tier, updated_at, last_event_at)
    VALUES (v_user_id, v_new_credit_score, v_new_tier, NOW(), NOW())
    ON CONFLICT (user_id)
    DO UPDATE SET
        score = v_new_credit_score,
        tier = v_new_tier,
        updated_at = NOW(),
        last_event_at = NOW();

    -- Log credit event
    INSERT INTO public.credit_events (user_id, event_type, delta, metadata)
    VALUES (
        v_user_id,
        'credit_card_payment',
        v_score_increase,
        jsonb_build_object('payment_amount', v_pay_amount, 'remaining_debt', v_new_credit_used)
    );

    RETURN jsonb_build_object(
        'success', true,
        'amount_paid', v_pay_amount,
        'new_credit_used', v_new_credit_used,
        'new_credit_score', v_new_credit_score,
        'new_tier', v_new_tier
    );
END;
$$;

-- Function: pay_house_rent
CREATE OR REPLACE FUNCTION public.pay_house_rent(p_rental_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rental record;
  v_user_id uuid := auth.uid();
  v_balance numeric;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT * INTO v_rental
  FROM public.house_rentals
  WHERE id = p_rental_id
    AND tenant_user_id = v_user_id
    AND status IN ('active', 'late');

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Rental not found for this tenant.');
  END IF;

  IF v_rental.next_due_at IS NOT NULL AND now() < v_rental.next_due_at THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Rent is not due until ' || to_char(v_rental.next_due_at, 'YYYY-MM-DD') || '.',
      'next_due_at', v_rental.next_due_at
    );
  END IF;

  SELECT COALESCE(troll_coins, 0) INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
  IF v_balance < COALESCE(v_rental.rent_amount, 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient balance. Need ' || COALESCE(v_rental.rent_amount, 0) || ' coins.');
  END IF;

  UPDATE public.user_profiles
  SET troll_coins = COALESCE(troll_coins, 0) - COALESCE(v_rental.rent_amount, 0),
      updated_at = now()
  WHERE id = v_user_id;

  UPDATE public.user_profiles
  SET troll_coins = COALESCE(troll_coins, 0) + COALESCE(v_rental.rent_amount, 0),
      updated_at = now()
  WHERE id = v_rental.landlord_user_id;

  UPDATE public.house_rentals
  SET last_paid_at = now(),
      next_due_at = now() + interval '7 days',
      status = 'active'
  WHERE id = p_rental_id;

  INSERT INTO public.coin_transactions (user_id, type, amount, description, created_at)
  VALUES (v_user_id, 'rent', -COALESCE(v_rental.rent_amount, 0), 'House rent payment ' || p_rental_id, now()),
         (v_rental.landlord_user_id, 'rent_income', COALESCE(v_rental.rent_amount, 0), 'House rent income ' || p_rental_id, now());

  INSERT INTO public.notifications (user_id, type, title, message, metadata, is_read, created_at)
  VALUES (
    v_rental.landlord_user_id,
    'rent_paid',
    'Rent Paid',
    'A tenant paid house rent.',
    jsonb_build_object('rental_id', p_rental_id, 'tenant_id', v_user_id, 'route', '/living?tab=tenants'),
    false,
    now()
  );

  RETURN jsonb_build_object('success', true, 'total_paid', COALESCE(v_rental.rent_amount, 0));
END;
$$;

-- Function: pay_rent
CREATE OR REPLACE FUNCTION public.pay_rent(p_lease_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_lease RECORD;
    v_property RECORD;
    v_total_cost INTEGER;
    v_rent INTEGER;
    v_utilities INTEGER;
    v_balance INTEGER;
    v_owner_id UUID;
    v_tax_amount INTEGER;
    v_owner_payout INTEGER;
BEGIN
    -- Get Lease
    SELECT * INTO v_lease FROM public.leases WHERE id = p_lease_id;
    IF NOT FOUND OR v_lease.tenant_id != v_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Lease not found or unauthorized');
    END IF;

    -- Get Property
    SELECT * INTO v_property FROM public.properties WHERE id = v_lease.property_id;

    v_rent := v_property.rent_amount;
    v_utilities := v_property.utility_cost;
    v_total_cost := v_rent + v_utilities;
    v_owner_id := v_property.owner_id;

    -- Check Balance
    SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    IF v_balance < v_total_cost THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds');
    END IF;

    -- Deduct from Tenant
    UPDATE public.user_profiles SET troll_coins = troll_coins - v_total_cost WHERE id = v_user_id;

    -- Distribute Revenue (Same logic as Sign Lease)
    -- 1. Utilities -> Admin Pool
    INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
    VALUES (v_user_id, -v_utilities, 'utility_payment', 'housing', 'Utility Payment', 'out');

    -- 2. Rent -> Split
    IF v_owner_id IS NULL THEN
        -- System owned
        INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
        VALUES (v_user_id, -v_rent, 'rent_payment', 'housing', 'Rent Payment (System)', 'out');
    ELSE
        -- User owned: 10% Tax
        v_tax_amount := floor(v_rent * 0.10);
        v_owner_payout := v_rent - v_tax_amount;

        -- Pay Owner
        UPDATE public.user_profiles SET troll_coins = troll_coins + v_owner_payout WHERE id = v_owner_id;
        INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
        VALUES (v_owner_id, v_owner_payout, 'rent_income', 'housing', 'Rent Received', 'in');

        -- Tax Ledger Entry
        INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
        VALUES (v_user_id, -v_tax_amount, 'officer_tax', 'housing', 'Rent Tax (10%)', 'out');
    END IF;

    -- Update Lease
    UPDATE public.leases 
    SET last_rent_paid_at = NOW(), 
        last_utility_paid_at = NOW() 
    WHERE id = p_lease_id;

    -- Create Invoice Record
    INSERT INTO public.invoices (lease_id, tenant_id, type, amount, status, paid_at)
    VALUES (p_lease_id, v_user_id, 'rent', v_rent, 'paid', NOW()),
           (p_lease_id, v_user_id, 'electric', v_utilities, 'paid', NOW());

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: payout_trollmers_weekly
CREATE OR REPLACE FUNCTION public.payout_trollmers_weekly(
    p_week_start DATE DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_weekly_total BIGINT := 2000;
    v_week_start DATE;
    v_pool_id UUID;
    v_pool_balance BIGINT;
    v_first BIGINT;
    v_second BIGINT;
    v_third BIGINT;
    v_paid_total BIGINT := 0;
    v_rows RECORD;
    v_rank INTEGER := 0;
BEGIN
    v_week_start := COALESCE(p_week_start, public.get_trollmers_week_start(NOW() - INTERVAL '7 days'));

    -- Prevent double payouts
    IF EXISTS (
        SELECT 1 FROM public.trollmers_weekly_payouts
        WHERE week_start = v_week_start
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Weekly payout already processed');
    END IF;

    -- Lock admin pool
    SELECT id, COALESCE(trollcoins_balance, 0)::BIGINT
    INTO v_pool_id, v_pool_balance
    FROM public.admin_pool
    LIMIT 1
    FOR UPDATE;

    IF v_pool_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Admin pool not configured');
    END IF;

    IF v_pool_balance < v_weekly_total THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient pool funds for weekly payout');
    END IF;

    v_first := FLOOR(v_weekly_total * 0.50);
    v_second := FLOOR(v_weekly_total * 0.30);
    v_third := v_weekly_total - v_first - v_second;

    FOR v_rows IN
        SELECT user_id, score
        FROM public.trollmers_weekly_leaderboard
        WHERE week_start = v_week_start
        ORDER BY score DESC, coins_earned DESC, wins DESC
        LIMIT 3
    LOOP
        v_rank := v_rank + 1;

        v_paid_total := v_paid_total + CASE
            WHEN v_rank = 1 THEN v_first
            WHEN v_rank = 2 THEN v_second
            ELSE v_third
        END;

        INSERT INTO public.trollmers_weekly_payouts (week_start, user_id, rank, payout_coins)
        VALUES (
            v_week_start,
            v_rows.user_id,
            v_rank,
            CASE
                WHEN v_rank = 1 THEN v_first
                WHEN v_rank = 2 THEN v_second
                ELSE v_third
            END
        );

        UPDATE public.user_profiles
        SET troll_coins = COALESCE(troll_coins, 0) +
            CASE
                WHEN v_rank = 1 THEN v_first
                WHEN v_rank = 2 THEN v_second
                ELSE v_third
            END
        WHERE id = v_rows.user_id;
        INSERT INTO public.coin_ledger (user_id, amount, transaction_type, reason, metadata)
        VALUES (
            v_rows.user_id,
            CASE
                WHEN v_rank = 1 THEN v_first
                WHEN v_rank = 2 THEN v_second
                ELSE v_third
            END,
            'income',
            'trollmers_weekly_payout',
            jsonb_build_object('week_start', v_week_start, 'rank', v_rank)
        );

        INSERT INTO public.admin_pool_ledger (amount, reason, ref_user_id, created_at)
        VALUES (
            -1 * CASE
                WHEN v_rank = 1 THEN v_first
                WHEN v_rank = 2 THEN v_second
                ELSE v_third
            END,
            'trollmers_weekly_payout_rank_' || v_rank,
            v_rows.user_id,
            NOW()
        );
    END LOOP;

    IF v_rank = 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'No leaderboard entries for the week');
    END IF;

    -- Deduct from admin pool
    UPDATE public.admin_pool
    SET trollcoins_balance = COALESCE(trollcoins_balance, 0) - v_paid_total,
        updated_at = NOW()
    WHERE id = v_pool_id;

    RETURN jsonb_build_object(
        'success', true,
        'week_start', v_week_start,
        'total_payout', v_paid_total,
        'rank1', v_first,
        'rank2', v_second,
        'rank3', v_third
    );
END;
$$;

-- Function: perform_church_mod_action
CREATE OR REPLACE FUNCTION perform_church_mod_action(
    target_user_id UUID,
    action_type TEXT,
    reason TEXT DEFAULT NULL,
    duration_minutes INTEGER DEFAULT NULL,
    prayer_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    current_user_id UUID;
    is_moderator BOOLEAN;
    result JSONB;
BEGIN
    current_user_id := auth.uid();

    -- Check moderator status
    SELECT (
        up.is_pastor = true OR up.role = 'admin' OR up.is_admin = true OR
        up.is_troll_officer = true OR up.is_lead_officer = true
    ) INTO is_moderator
    FROM public.user_profiles up
    WHERE up.id = current_user_id;

    IF NOT is_moderator THEN
        RETURN jsonb_build_object('success', false, 'error', 'You do not have permission to perform moderation actions');
    END IF;

    -- Log the action
    INSERT INTO public.church_mod_actions (moderator_id, target_user_id, action_type, reason, prayer_id, duration_minutes, expires_at)
    VALUES (
        current_user_id, target_user_id, action_type, reason, prayer_id, duration_minutes,
        CASE WHEN duration_minutes IS NOT NULL THEN now() + (duration_minutes || ' minutes')::INTERVAL ELSE NULL END
    );

    -- Handle ban action
    IF action_type IN ('kick', 'ban') THEN
        INSERT INTO public.church_banned_users (user_id, banned_by, reason, expires_at)
        VALUES (
            target_user_id, current_user_id, reason,
            CASE WHEN duration_minutes IS NOT NULL THEN now() + (duration_minutes || ' minutes')::INTERVAL ELSE NULL END
        )
        ON CONFLICT (user_id) DO UPDATE SET
            banned_by = EXCLUDED.banned_by,
            reason = EXCLUDED.reason,
            is_active = true,
            expires_at = EXCLUDED.expires_at;
    END IF;

    -- Handle unban
    IF action_type IN ('unmute', 'unban') THEN
        UPDATE public.church_banned_users SET is_active = false WHERE church_banned_users.user_id = target_user_id;
    END IF;

    -- Handle prayer delete
    IF action_type = 'prayer_delete' AND prayer_id IS NOT NULL THEN
        DELETE FROM public.church_prayers WHERE id = prayer_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'action', action_type, 'target_user_id', target_user_id);
END;
$$;

-- Function: perform_moderation_action
CREATE OR REPLACE FUNCTION public.perform_moderation_action(
    p_target_id UUID,
    p_action_type TEXT,
    p_reason TEXT,
    p_duration_minutes INTEGER DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_mod_id UUID := auth.uid();
    v_expires_at TIMESTAMPTZ;
    v_target_role TEXT;
BEGIN
    -- Check permissions (Admin, Officer, or Admin-for-Week)
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = v_mod_id 
        AND (
            role IN ('admin', 'troll_officer', 'lead_troll_officer') 
            OR id IN (SELECT user_id FROM public.admin_for_week_queue WHERE status = 'active')
            OR is_admin = true
        )
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Prevent action against Admins (unless self?)
    SELECT role INTO v_target_role FROM public.user_profiles WHERE id = p_target_id;
    IF v_target_role = 'admin' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot moderate an Admin');
    END IF;

    IF p_duration_minutes IS NOT NULL THEN
        v_expires_at := NOW() + (p_duration_minutes || ' minutes')::INTERVAL;
    END IF;

    -- Log action
    INSERT INTO public.moderation_logs (moderator_id, target_user_id, action_type, reason, expires_at)
    VALUES (v_mod_id, p_target_id, p_action_type, p_reason, v_expires_at);

    -- Execute Action Logic
    IF p_action_type = 'ban' THEN
        UPDATE public.user_profiles SET is_banned = true, ban_expires_at = v_expires_at WHERE id = p_target_id;
    ELSIF p_action_type = 'mute' THEN
         UPDATE public.user_profiles SET is_muted = true, mute_expires_at = v_expires_at WHERE id = p_target_id;
    ELSIF p_action_type = 'kick' THEN
        -- Kick user from all active streams for 24 hours (or specified duration)
        -- Set default 24 hour duration if not specified
        v_expires_at := COALESCE(v_expires_at, NOW() + INTERVAL '24 hours');

        -- Insert/update ban record for all active streams the user is viewing
        INSERT INTO public.stream_bans (stream_id, user_id, banned_by, reason, expires_at)
        SELECT sv.stream_id, p_target_id, v_mod_id, COALESCE(p_reason, 'Moderator kick'), v_expires_at
        FROM public.stream_viewers sv
        WHERE sv.user_id = p_target_id
        ON CONFLICT (stream_id, user_id)
        DO UPDATE SET
            banned_by = v_mod_id,
            reason = COALESCE(p_reason, 'Moderator kick'),
            expires_at = v_expires_at,
            created_at = NOW();

        -- Remove user from all stream viewers (instant disconnect)
        DELETE FROM public.stream_viewers WHERE user_id = p_target_id; 
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: pin_product_to_broadcast
CREATE OR REPLACE FUNCTION pin_product_to_broadcast(
    p_stream_id UUID,
    p_product_id UUID,
    p_pinned_by UUID
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_pinned_id UUID;
    v_existing_count INTEGER;
BEGIN
    -- Check if product exists and belongs to user
    IF NOT EXISTS (
        SELECT 1 FROM public.shop_items si
        JOIN public.Mai Troll_shops ts ON ts.id = si.shop_id
        WHERE si.id = p_product_id AND ts.owner_id = p_pinned_by
    ) THEN
        RAISE EXCEPTION 'Product not found or does not belong to you';
    END IF;

    -- Check if already pinned
    SELECT id INTO v_pinned_id
    FROM public.broadcast_pinned_products
    WHERE stream_id = p_stream_id AND product_id = p_product_id AND is_active = true;

    IF v_pinned_id IS NOT NULL THEN
        RETURN v_pinned_id;
    END IF;

    -- Get current pinned count
    SELECT COUNT(*) INTO v_existing_count
    FROM public.broadcast_pinned_products
    WHERE stream_id = p_stream_id AND is_active = true;

    -- Insert pinned product
    INSERT INTO public.broadcast_pinned_products (stream_id, product_id, pinned_by, position)
    VALUES (p_stream_id, p_product_id, p_pinned_by, v_existing_count + 1)
    RETURNING id INTO v_pinned_id;

    RETURN v_pinned_id;
END;
$$;

-- Function: place_bid
CREATE OR REPLACE FUNCTION public.place_bid(p_auction_id UUID, p_amount BIGINT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_auction RECORD;
    v_paid BOOLEAN;
BEGIN
    SELECT * INTO v_auction FROM public.asset_auctions WHERE id = p_auction_id;
    
    IF v_auction.status != 'active' OR v_auction.ends_at < NOW() THEN
        RETURN jsonb_build_object('success', false, 'error', 'Auction ended');
    END IF;
    
    IF p_amount <= v_auction.current_bid OR p_amount < v_auction.starting_bid THEN
        RETURN jsonb_build_object('success', false, 'error', 'Bid too low');
    END IF;
    
    -- Hold funds
    v_paid := public.try_pay_coins(v_user_id, p_amount, 'auction_bid', jsonb_build_object('auction_id', p_auction_id));
    
    IF v_paid THEN
        -- Refund previous winner
        IF v_auction.current_winner_user_id IS NOT NULL THEN
            -- Refund
            PERFORM public.try_pay_coins(v_auction.current_winner_user_id, -1 * v_auction.current_bid, 'auction_refund', jsonb_build_object('auction_id', p_auction_id));
        END IF;
        
        -- Update Auction
        UPDATE public.asset_auctions
        SET current_bid = p_amount,
            current_winner_user_id = v_user_id
        WHERE id = p_auction_id;
        
        -- Log Bid
        INSERT INTO public.auction_bids (auction_id, bidder_user_id, amount)
        VALUES (p_auction_id, v_user_id, p_amount);
        
        RETURN jsonb_build_object('success', true);
    ELSE
         RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds');
    END IF;
END;
$$;

-- Function: place_boost_bid
CREATE OR REPLACE FUNCTION place_boost_bid(
  p_show_id uuid,
  p_lot_id uuid,
  p_bid_amount int,
  p_boost_amount int DEFAULT 0
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_show_record record;
  v_lot_record record;
  v_user_coins int;
  v_min_bid int;
  v_allowed_increments int[];
  v_max_boost int;
  v_custom_enabled boolean;
  v_bid_id uuid;
  v_is_anonymous boolean := false;
  v_anonymous_label text;
  v_spend_result json;
BEGIN
  -- Get show
  SELECT * INTO v_show_record FROM auction_shows WHERE id = p_show_id;
  IF NOT FOUND THEN
    RETURN json_build_object('accepted', false, 'reason', 'Show not found');
  END IF;

  -- Check if anonymous round is active
  IF v_show_record.is_anonymous_round_active = true THEN
    IF v_show_record.anonymous_round_ends_at IS NOT NULL AND v_show_record.anonymous_round_ends_at > now() THEN
      v_is_anonymous := true;
      v_anonymous_label := 'Anonymous Bidder #' || (
        SELECT COUNT(DISTINCT bidder_id) + 1
        FROM auction_bids
        WHERE auction_show_id = p_show_id AND is_anonymous = true
      );
    END IF;
  END IF;

  -- Check if boost bids are enabled
  IF NOT v_show_record.boost_bids_enabled THEN
    RETURN json_build_object('accepted', false, 'reason', 'Boost bids are not enabled for this show');
  END IF;

  -- Get lot
  SELECT * INTO v_lot_record FROM auction_lots WHERE id = p_lot_id;
  IF NOT FOUND THEN
    RETURN json_build_object('accepted', false, 'reason', 'Lot not found');
  END IF;

  IF v_lot_record.status != 'live' THEN
    RETURN json_build_object('accepted', false, 'reason', 'Lot is not accepting bids');
  END IF;

  -- Calculate minimum bid
  v_min_bid := COALESCE(v_lot_record.current_highest_bid + v_lot_record.bid_increment, v_lot_record.starting_bid);

  -- Validate boost amount
  v_allowed_increments := COALESCE(v_show_record.boost_bid_allowed_increments, ARRAY[2, 5, 10]);
  v_max_boost := COALESCE(v_show_record.boost_bid_max_amount, 100);
  v_custom_enabled := COALESCE(v_show_record.boost_bid_custom_enabled, false);

  IF p_boost_amount > 0 THEN
    IF p_boost_amount > v_max_boost THEN
      RETURN json_build_object('accepted', false, 'reason', 'Boost amount exceeds maximum of ' || v_max_boost);
    END IF;
    IF NOT v_custom_enabled AND NOT (p_boost_amount = ANY(v_allowed_increments)) THEN
      RETURN json_build_object('accepted', false, 'reason', 'Boost amount not in allowed increments');
    END IF;
  END IF;

  -- Validate total bid
  IF p_bid_amount < v_min_bid + p_boost_amount THEN
    RETURN json_build_object('accepted', false, 'reason', 'Bid too low. Minimum is ' || (v_min_bid + p_boost_amount) || ' coins');
  END IF;

  -- Check user balance
  SELECT troll_coins INTO v_user_coins FROM user_profiles WHERE id = auth.uid();
  IF v_user_coins IS NULL OR v_user_coins < p_bid_amount THEN
    RETURN json_build_object('accepted', false, 'reason', 'Insufficient troll coins');
  END IF;

  -- Deduct coins via the Troll Bank (user_profiles.troll_coins is a restricted
  -- column, so direct updates are blocked by column privileges).
  SELECT public.troll_bank_spend_coins_secure(
    p_user_id := auth.uid(),
    p_amount := p_bid_amount,
    p_bucket := 'paid',
    p_source := 'auction_bid',
    p_ref_id := p_lot_id::text,
    p_metadata := jsonb_build_object('show_id', p_show_id, 'lot_id', p_lot_id, 'boost_amount', p_boost_amount)
  )::json INTO v_spend_result;

  IF (v_spend_result->>'success') IS DISTINCT FROM 'true' THEN
    RETURN json_build_object('accepted', false, 'reason', COALESCE(v_spend_result->>'error', 'Failed to deduct coins for bid'));
  END IF;

  -- Insert bid
  INSERT INTO auction_bids (lot_id, auction_show_id, bidder_id, bid_amount, is_anonymous, anonymous_label, is_boost_bid, boost_amount, created_at)
  VALUES (p_lot_id, p_show_id, auth.uid(), p_bid_amount, v_is_anonymous, v_anonymous_label, p_boost_amount > 0, p_boost_amount, now())
  RETURNING id INTO v_bid_id;

  -- Update lot
  UPDATE auction_lots SET
    current_highest_bid = p_bid_amount,
    current_highest_bidder_id = auth.uid(),
    updated_at = now()
  WHERE id = p_lot_id;

  -- Log transaction
  INSERT INTO coin_transactions (user_id, amount, direction, type, reference_id, description)
  VALUES (auth.uid(), p_bid_amount, 'OUT', 'boost_bid', v_bid_id, 'Boost bid on lot: ' || v_lot_record.title);

  RETURN json_build_object(
    'accepted', true,
    'bid_id', v_bid_id,
    'new_highest_bid', p_bid_amount,
    'boost_amount', p_boost_amount,
    'is_anonymous', v_is_anonymous,
    'anonymous_label', v_anonymous_label
  );
END;
$$;

-- Function: post_president_announcement
create or replace function post_president_announcement(p_message text)
returns uuid
security definer
language plpgsql
as $$
declare
  v_last_post timestamptz;
  v_id uuid;
  v_limit_hours int := 4; -- Configurable limit
begin
  -- Check Role
  if not exists (
    select 1 from user_role_grants urg
    join system_roles sr on urg.role_id = sr.id
    where urg.user_id = auth.uid()
    and sr.name in ('president', 'vice_president')
    and (urg.expires_at is null or urg.expires_at > now())
  ) then
    raise exception 'Not authorized';
  end if;

  -- Check Rate Limit
  select created_at into v_last_post
  from president_announcements
  where created_by = auth.uid()
  order by created_at desc
  limit 1;

  if v_last_post is not null and v_last_post > now() - (v_limit_hours || ' hours')::interval then
    raise exception 'Rate limit exceeded. Try again later.';
  end if;

  -- Insert into President Announcements (for record keeping and rate limiting)
  insert into president_announcements (message, created_by, expires_at)
  values (p_message, auth.uid(), now() + interval '24 hours')
  returning id into v_id;

  -- Insert into Troll Posts (for public feed visibility)
  -- We use 'announcement' as post_type to trigger special styling
  insert into troll_posts (user_id, content, post_type)
  values (auth.uid(), p_message, 'announcement');

  -- Log
  perform log_president_action('post_announcement', jsonb_build_object('message_snippet', substring(p_message from 1 for 50)), v_id);

  return v_id;
end;
$$;

-- Function: president_flag_user
create or replace function president_flag_user(
  p_target_user_id uuid,
  p_reason text
)
returns void
security definer
language plpgsql
as $$
begin
   -- Check Role
  if not exists (
    select 1 from user_role_grants urg
    join system_roles sr on urg.role_id = sr.id
    where urg.user_id = auth.uid()
    and sr.name in ('president', 'vice_president')
    and (urg.expires_at is null or urg.expires_at > now())
  ) then
    raise exception 'Not authorized';
  end if;

  -- Create Report (assuming reports table exists and has standard structure, if not, we insert into a president specific log or use an existing function)
  -- Based on AdminDashboard, there is a 'reports' table.
  -- Let's try to insert into 'weekly_reports' or just use 'president_audit_logs' tagged as 'flag'.
  -- Better: Create a new report in the system.
  -- Since I don't have the exact 'reports' insert policy/schema handy (it was in AdminDashboard but schema not fully shown), I'll use the audit log and a specific 'flag' action that Admins can filter.
  
  perform log_president_action('flag_user', jsonb_build_object('reason', p_reason), p_target_user_id);
  
  -- Also notify admins via notification system (if exists)
  -- This part is optional but good practice.
end;
$$;

-- Function: president_raise_payouts
CREATE OR REPLACE FUNCTION public.president_raise_payouts(p_amount_cents BIGINT)
RETURNS VOID
SECURITY DEFINER
LANGUAGE plpgsql
AS $$
DECLARE
  v_balance BIGINT;
BEGIN
  -- Check President
  IF NOT EXISTS (
    SELECT 1 FROM user_role_grants urg
    JOIN system_roles sr ON urg.role_id = sr.id
    WHERE urg.user_id = auth.uid() 
    AND sr.name = 'president'
    AND (urg.expires_at IS NULL OR urg.expires_at > NOW())
  ) THEN
    RAISE EXCEPTION 'Not President';
  END IF;

  -- Check Treasury
  SELECT COALESCE(SUM(amount_cents), 0) INTO v_balance FROM president_treasury_ledger WHERE currency = 'USD';
  
  IF v_balance < p_amount_cents THEN
    RAISE EXCEPTION 'Insufficient funds';
  END IF;

  -- Deduct/Reserve
  INSERT INTO president_treasury_ledger (amount_cents, kind, currency, actor_id)
  VALUES (-p_amount_cents, 'reserve', 'USD', auth.uid());
  
  -- Update Policy
  UPDATE payout_policy
  SET max_payout_cents = max_payout_cents + p_amount_cents; 
  
  -- Log to Government Actions Log
  PERFORM public.log_government_action(
    auth.uid(),
    'president',
    'raise_payouts',
    'payout_policy',
    jsonb_build_object(
        'amount_cents', p_amount_cents,
        'currency', 'USD'
    )
  );
END;
$$;

-- Function: pride_complete_challenge
CREATE OR REPLACE FUNCTION public.pride_complete_challenge(
    p_user_id UUID,
    p_challenge_id UUID
)
RETURNS JSONB AS $$
DECLARE
    v_challenge RECORD;
    v_progress RECORD;
    v_xp_reward BIGINT;
BEGIN
    -- Skip guest users
    IF p_user_id IS NULL OR p_user_id::text LIKE 'TC-%' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Guest users cannot complete challenges');
    END IF;

    -- Get challenge details
    SELECT * INTO v_challenge
    FROM public.pride_challenges
    WHERE id = p_challenge_id AND is_active = true;

    IF v_challenge IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Challenge not found or inactive');
    END IF;

    -- Get or create user progress
    SELECT * INTO v_progress
    FROM public.pride_user_progress
    WHERE user_id = p_user_id AND challenge_id = p_challenge_id;

    IF v_progress IS NULL THEN
        -- Create progress entry
        INSERT INTO public.pride_user_progress (user_id, challenge_id, progress_value, completion_percentage, is_completed, completed_at)
        VALUES (p_user_id, p_challenge_id, v_challenge.target_value, 100, true, now())
        RETURNING * INTO v_progress;
    ELSIF v_progress.is_completed THEN
        RETURN jsonb_build_object('success', false, 'error', 'Challenge already completed');
    ELSE
        -- Mark as completed
        UPDATE public.pride_user_progress
        SET progress_value = v_challenge.target_value,
            completion_percentage = 100,
            is_completed = true,
            completed_at = now(),
            updated_at = now()
        WHERE user_id = p_user_id AND challenge_id = p_challenge_id
        RETURNING * INTO v_progress;
    END IF;

    -- Grant XP
    v_xp_reward := v_challenge.xp_reward;
    IF v_xp_reward > 0 THEN
        PERFORM grant_xp(p_user_id, v_xp_reward, 'pride_challenge', p_challenge_id::text,
            jsonb_build_object('challenge_slug', v_challenge.slug, 'challenge_title', v_challenge.title));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'xp_awarded', v_xp_reward,
        'challenge_title', v_challenge.title
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 6. RPC: Increment progress on a pride challenge
CREATE OR REPLACE FUNCTION public.pride_increment_progress(
    p_user_id UUID,
    p_challenge_id UUID,
    p_amount BIGINT DEFAULT 1
)
RETURNS JSONB AS $$
DECLARE
    v_challenge RECORD;
    v_progress RECORD;
    v_new_progress BIGINT;
    v_new_percentage FLOAT;
    v_just_completed BOOLEAN := false;
BEGIN
    -- Skip guest users
    IF p_user_id IS NULL OR p_user_id::text LIKE 'TC-%' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Guest users cannot progress challenges');
    END IF;

    -- Get challenge details
    SELECT * INTO v_challenge
    FROM public.pride_challenges
    WHERE id = p_challenge_id AND is_active = true;

    IF v_challenge IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Challenge not found or inactive');
    END IF;

    -- Get or create user progress
    SELECT * INTO v_progress
    FROM public.pride_user_progress
    WHERE user_id = p_user_id AND challenge_id = p_challenge_id;

    IF v_progress IS NULL THEN
        v_new_progress := LEAST(p_amount, v_challenge.target_value);
        v_new_percentage := (v_new_progress::float / v_challenge.target_value) * 100;
        v_just_completed := v_new_progress >= v_challenge.target_value;

        INSERT INTO public.pride_user_progress (user_id, challenge_id, progress_value, completion_percentage, is_completed, completed_at)
        VALUES (p_user_id, p_challenge_id, v_new_progress, v_new_percentage, v_just_completed,
                CASE WHEN v_just_completed THEN now() ELSE NULL END);
    ELSIF v_progress.is_completed THEN
        RETURN jsonb_build_object('success', true, 'message', 'Already completed', 'is_completed', true);
    ELSE
        v_new_progress := LEAST(v_progress.progress_value + p_amount, v_challenge.target_value);
        v_new_percentage := (v_new_progress::float / v_challenge.target_value) * 100;
        v_just_completed := v_new_progress >= v_challenge.target_value AND NOT v_progress.is_completed;

        UPDATE public.pride_user_progress
        SET progress_value = v_new_progress,
            completion_percentage = v_new_percentage,
            is_completed = v_just_completed,
            completed_at = CASE WHEN v_just_completed THEN now() ELSE completed_at END,
            updated_at = now()
        WHERE user_id = p_user_id AND challenge_id = p_challenge_id;
    END IF;

    -- Grant XP if just completed
    IF v_just_completed AND v_challenge.xp_reward > 0 THEN
        PERFORM grant_xp(p_user_id, v_challenge.xp_reward, 'pride_challenge', p_challenge_id::text,
            jsonb_build_object('challenge_slug', v_challenge.slug, 'challenge_title', v_challenge.title));
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'progress', v_new_progress,
        'target', v_challenge.target_value,
        'percentage', v_new_percentage,
        'is_completed', v_just_completed,
        'xp_awarded', CASE WHEN v_just_completed THEN v_challenge.xp_reward ELSE 0 END
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 7. Helper: get the current pride week number (1-4) based on current date
CREATE OR REPLACE FUNCTION public.get_pride_week()
RETURNS INT AS $$
DECLARE
    v_day INT;
BEGIN
    -- Only return week number during June (Pride Month)
    IF EXTRACT(MONTH FROM now()) != 5 THEN
        RETURN 0;
    END IF;
    v_day := EXTRACT(DAY FROM now());
    RETURN LEAST(4, GREATEST(1, CEIL(v_day::float / 7)));
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- 8. Trigger: auto-track chat messages for pride challenges
CREATE OR REPLACE FUNCTION public.pride_track_chat_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_message TEXT;
    v_compliment_keywords TEXT[] := ARRAY['nice','awesome','great','amazing','love','beautiful','proud','congrats','congratulations','well done','good job','fantastic','wonderful','excellent','brilliant','🔥','❤️','👏','💯','🙌','💪','✨','😊','😍'];
    v_keyword TEXT;
BEGIN
    -- Only during June (Pride Month)
    IF EXTRACT(MONTH FROM now()) != 5 THEN
        RETURN NEW;
    END IF;

    -- Get message content from either content or column
    v_message := LOWER(COALESCE(NEW.content, NEW.message, ''));

    IF v_message = '' THEN
        RETURN NEW;
    END IF;

    -- Track generic chat message for send_chat challenge
    BEGIN
        -- Find the send_chat challenge for the current week
        PERFORM pride_increment_progress(NEW.user_id, pc.id, 1)
        FROM public.pride_challenges pc
        WHERE pc.action_type = 'send_chat'
          AND pc.is_active = true
          AND pc.week_number = public.get_pride_week()
          AND pc.starts_at <= now()
          AND (pc.ends_at IS NULL OR pc.ends_at >= now());
    EXCEPTION WHEN OTHERS THEN
        NULL; -- Silent fail
    END;

    -- Check for compliment keywords for give_compliments challenge
    IF v_message != '' THEN
        FOREACH v_keyword IN ARRAY v_compliment_keywords
        LOOP
            IF v_message LIKE '%' || v_keyword || '%' THEN
                BEGIN
                    PERFORM pride_increment_progress(NEW.user_id, pc.id, 1)
                    FROM public.pride_challenges pc
                    WHERE pc.action_type = 'give_compliments'
                      AND pc.is_active = true
                      AND pc.week_number = public.get_pride_week()
                      AND pc.starts_at <= now()
                      AND (pc.ends_at IS NULL OR pc.ends_at >= now());
                EXCEPTION WHEN OTHERS THEN
                    NULL; -- Silent fail
                END;
                EXIT; -- Only count one compliment per message
            END IF;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$;

-- Function: pride_track_wall_action
CREATE OR REPLACE FUNCTION public.pride_track_wall_action(
    p_user_id UUID,
    p_action_type TEXT,
    p_target_user_id UUID DEFAULT NULL
)
RETURNS JSONB AS $$
DECLARE
    v_challenge RECORD;
    v_result JSONB := '[]'::jsonb;
    v_entry JSONB;
BEGIN
    IF p_user_id IS NULL OR p_user_id::text LIKE 'TC-%' THEN
        RETURN '[]'::jsonb;
    END IF;

    FOR v_challenge IN
        SELECT * FROM public.pride_challenges
        WHERE action_type = p_action_type
          AND is_active = true
          AND starts_at <= now()
          AND (ends_at IS NULL OR ends_at >= now())
    LOOP
        IF v_challenge.target_value = 1 THEN
            -- Boolean challenge: complete once
            INSERT INTO public.pride_user_progress (user_id, challenge_id, progress_value, completion_percentage, is_completed, completed_at)
            VALUES (p_user_id, v_challenge.id, 1, 100, true, now())
            ON CONFLICT (user_id, challenge_id) DO NOTHING;
        ELSE
            -- Count challenge: increment
            INSERT INTO public.pride_user_progress (user_id, challenge_id, progress_value, completion_percentage, is_completed, completed_at)
            VALUES (p_user_id, v_challenge.id, 1,
                LEAST(100, (1.0 / v_challenge.target_value) * 100),
                (1 >= v_challenge.target_value),
                CASE WHEN 1 >= v_challenge.target_value THEN now() ELSE NULL END)
            ON CONFLICT (user_id, challenge_id)
            DO UPDATE SET
                progress_value = LEAST(public.pride_user_progress.progress_value + 1, v_challenge.target_value),
                completion_percentage = LEAST(100, ((public.pride_user_progress.progress_value + 1)::float / v_challenge.target_value) * 100),
                is_completed = (public.pride_user_progress.progress_value + 1) >= v_challenge.target_value,
                completed_at = CASE
                    WHEN (public.pride_user_progress.progress_value + 1) >= v_challenge.target_value
                    THEN now()
                    ELSE public.pride_user_progress.completed_at
                END,
                updated_at = now();
        END IF;

        v_entry := jsonb_build_object(
            'challenge_id', v_challenge.id,
            'slug', v_challenge.slug,
            'xp_reward', v_challenge.xp_reward
        );
        v_result := v_result || v_entry;
    END LOOP;

    -- Also track add_friends if this is a reply to a new interaction
    IF p_action_type = 'reply_posts' AND p_target_user_id IS NOT NULL THEN
        -- Check if this is a new unique interaction for add_friends
        DECLARE
            v_friend_challenge RECORD;
        BEGIN
            SELECT * INTO v_friend_challenge
            FROM public.pride_challenges
            WHERE action_type = 'add_friends'
              AND is_active = true
              AND starts_at <= now()
              AND (ends_at IS NULL OR ends_at >= now())
            LIMIT 1;

            IF FOUND THEN
                -- Count unique users interacted with today
                INSERT INTO public.pride_user_progress (user_id, challenge_id, progress_value, completion_percentage, is_completed, completed_at)
                VALUES (p_user_id, v_friend_challenge.id, 1, 0, false, NULL)
                ON CONFLICT (user_id, challenge_id)
                DO UPDATE SET
                    progress_value = LEAST(public.pride_user_progress.progress_value + 1, v_friend_challenge.target_value),
                    completion_percentage = LEAST(100, ((public.pride_user_progress.progress_value + 1)::float / v_friend_challenge.target_value) * 100),
                    is_completed = (public.pride_user_progress.progress_value + 1) >= v_friend_challenge.target_value,
                    updated_at = now();
            END IF;
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;

    RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 6. RPC: Track gift sending for send_gifts and send_pride_gift challenges
CREATE OR REPLACE FUNCTION public.pride_track_gift(
    p_user_id UUID,
    p_recipient_user_id UUID,
    p_gift_type TEXT DEFAULT 'generic'
)
RETURNS JSONB AS $$
DECLARE
    v_challenge RECORD;
    v_result JSONB := '[]'::jsonb;
BEGIN
    IF p_user_id IS NULL OR p_user_id::text LIKE 'TC-%' THEN
        RETURN '[]'::jsonb;
    END IF;

    -- Track send_gifts (support different users with gifts)
    FOR v_challenge IN
        SELECT * FROM public.pride_challenges
        WHERE action_type = 'send_gifts'
          AND is_active = true
          AND starts_at <= now()
          AND (ends_at IS NULL OR ends_at >= now())
    LOOP
        INSERT INTO public.pride_user_progress (user_id, challenge_id, progress_value, completion_percentage, is_completed, completed_at)
        VALUES (p_user_id, v_challenge.id, 1, 0, false, NULL)
        ON CONFLICT (user_id, challenge_id)
        DO UPDATE SET
            progress_value = LEAST(public.pride_user_progress.progress_value + 1, v_challenge.target_value),
            completion_percentage = LEAST(100, ((public.pride_user_progress.progress_value + 1)::float / v_challenge.target_value) * 100),
            is_completed = (public.pride_user_progress.progress_value + 1) >= v_challenge.target_value,
            completed_at = CASE
                WHEN (public.pride_user_progress.progress_value + 1) >= v_challenge.target_value
                THEN now()
                ELSE public.pride_user_progress.completed_at
            END,
            updated_at = now();
    END LOOP;

    -- Track send_pride_gift (send Pride-themed gifts)
    IF p_gift_type ILIKE '%pride%' OR p_gift_type ILIKE '%rainbow%' THEN
        FOR v_challenge IN
            SELECT * FROM public.pride_challenges
            WHERE action_type = 'send_pride_gift'
              AND is_active = true
              AND starts_at <= now()
              AND (ends_at IS NULL OR ends_at >= now())
        LOOP
            INSERT INTO public.pride_user_progress (user_id, challenge_id, progress_value, completion_percentage, is_completed, completed_at)
            VALUES (p_user_id, v_challenge.id, 1, 0, false, NULL)
            ON CONFLICT (user_id, challenge_id)
            DO UPDATE SET
                progress_value = LEAST(public.pride_user_progress.progress_value + 1, v_challenge.target_value),
                completion_percentage = LEAST(100, ((public.pride_user_progress.progress_value + 1)::float / v_challenge.target_value) * 100),
                is_completed = (public.pride_user_progress.progress_value + 1) >= v_challenge.target_value,
                completed_at = CASE
                    WHEN (public.pride_user_progress.progress_value + 1) >= v_challenge.target_value
                    THEN now()
                    ELSE public.pride_user_progress.completed_at
                END,
                updated_at = now();
        END LOOP;
    END IF;

    RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

