-- Agora Stream Sessions Table
-- Tracks Agora streaming sessions for HytroGaming
-- Architecture: OBS → Agora RTMP Ingest → Agora Channel → maitroll Viewers
--
-- NOTE: This is a NEW table (agora_stream_sessions), separate from the existing
-- stream_sessions table which is used by the backend API for regular broadcasts.
-- This avoids any conflicts with the main broadcast system.

-- Ensure streams table has Agora-related fields
ALTER TABLE public.streams
  ADD COLUMN IF NOT EXISTS stream_key TEXT;

ALTER TABLE public.streams
  ADD COLUMN IF NOT EXISTS game_title TEXT DEFAULT '';

ALTER TABLE public.streams
  ADD COLUMN IF NOT EXISTS is_featured BOOLEAN DEFAULT false;

ALTER TABLE public.streams
  ADD COLUMN IF NOT EXISTS layout_mode TEXT DEFAULT 'grid';

ALTER TABLE public.streams
  ADD COLUMN IF NOT EXISTS battle_id UUID;

-- Create Agora stream sessions table (separate from existing stream_sessions)
CREATE TABLE IF NOT EXISTS public.agora_stream_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  streamer_id UUID NOT NULL,
  stream_id UUID REFERENCES public.streams(id) ON DELETE SET NULL,

  -- Agora streaming credentials
  agora_channel TEXT NOT NULL UNIQUE,
  stream_key TEXT NOT NULL,
  host_uid INTEGER NOT NULL DEFAULT 0,

  -- Stream status: starting | waiting | signal_detected | ready | live | ended | error
  status TEXT NOT NULL DEFAULT 'starting',

  -- Viewer tracking
  viewer_count INTEGER NOT NULL DEFAULT 0,
  peak_viewers INTEGER NOT NULL DEFAULT 0,

  -- Timestamps
  started_at TIMESTAMPTZ,
  ended_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  -- Agora session metadata (for future co-hosting, PK battles, multi-guest, voice chats, live events)
  session_metadata JSONB DEFAULT '{}'::jsonb,

  -- Recording
  recording_url TEXT,
  is_recording BOOLEAN NOT NULL DEFAULT false
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_agora_stream_sessions_streamer_id ON public.agora_stream_sessions(streamer_id);
CREATE INDEX IF NOT EXISTS idx_agora_stream_sessions_stream_id ON public.agora_stream_sessions(stream_id);
CREATE INDEX IF NOT EXISTS idx_agora_stream_sessions_status ON public.agora_stream_sessions(status);
CREATE INDEX IF NOT EXISTS idx_agora_stream_sessions_agora_channel ON public.agora_stream_sessions(agora_channel);
CREATE INDEX IF NOT EXISTS idx_agora_stream_sessions_created_at ON public.agora_stream_sessions(created_at DESC);

-- Enable RLS
ALTER TABLE public.agora_stream_sessions ENABLE ROW LEVEL SECURITY;

-- RLS Policies (drop existing first to allow re-running)
DROP POLICY IF EXISTS "Anyone can view all agora stream sessions" ON public.agora_stream_sessions;
DROP POLICY IF EXISTS "Users can create their own agora stream sessions" ON public.agora_stream_sessions;
DROP POLICY IF EXISTS "Users can update their own agora stream sessions" ON public.agora_stream_sessions;
DROP POLICY IF EXISTS "Users can delete their own agora stream sessions" ON public.agora_stream_sessions;

-- Anyone can view all stream sessions (for browsing)
CREATE POLICY "Anyone can view all agora stream sessions"
  ON public.agora_stream_sessions
  FOR SELECT
  USING (true);

-- Authenticated users can create their own stream sessions
CREATE POLICY "Users can create their own agora stream sessions"
  ON public.agora_stream_sessions
  FOR INSERT
  WITH CHECK (streamer_id = auth.uid());

-- Users can update their own stream sessions
CREATE POLICY "Users can update their own agora stream sessions"
  ON public.agora_stream_sessions
  FOR UPDATE
  USING (streamer_id = auth.uid())
  WITH CHECK (streamer_id = auth.uid());

-- Users can delete their own stream sessions
CREATE POLICY "Users can delete their own agora stream sessions"
  ON public.agora_stream_sessions
  FOR DELETE
  USING (streamer_id = auth.uid());

-- Function to auto-update updated_at
CREATE OR REPLACE FUNCTION public.handle_agora_stream_session_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger for updated_at
DROP TRIGGER IF EXISTS agora_stream_sessions_updated_at ON public.agora_stream_sessions;
CREATE TRIGGER agora_stream_sessions_updated_at
  BEFORE UPDATE ON public.agora_stream_sessions
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_agora_stream_session_updated_at();

-- Function to increment viewer count
CREATE OR REPLACE FUNCTION public.increment_agora_stream_session_viewers(session_id UUID)
RETURNS void AS $$
BEGIN
  UPDATE public.agora_stream_sessions
  SET viewer_count = viewer_count + 1,
      peak_viewers = GREATEST(peak_viewers, viewer_count + 1)
  WHERE id = session_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to decrement viewer count
CREATE OR REPLACE FUNCTION public.decrement_agora_stream_session_viewers(session_id UUID)
RETURNS void AS $$
BEGIN
  UPDATE public.agora_stream_sessions
  SET viewer_count = GREATEST(0, viewer_count - 1)
  WHERE id = session_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Grant permissions
GRANT ALL ON public.agora_stream_sessions TO authenticated;
GRANT SELECT ON public.agora_stream_sessions TO anon;
GRANT EXECUTE ON FUNCTION public.increment_agora_stream_session_viewers(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.decrement_agora_stream_session_viewers(UUID) TO authenticated;

-- Simplify gaming streams for Agora-based browser screen sharing
-- Only removes columns that were added exclusively for the old HytroGaming
-- OBS/RTMP/Ingest workflow and are NOT used by the main broadcast system.
--
-- SAFE TO DROP (gaming-only, not in baseline, not used by any active code):
--   stream_key        — added by add_broadcast_category_columns.sql for OBS RTMP
--   rtmp_url          — added by 20260607000000_add_livekit_rtmp_url.sql for OBS RTMP
--   rtmp_ingest_url   — added by add_broadcast_category_columns.sql for OBS RTMP
--   is_obs_stream     — added by add_broadcast_category_columns.sql to flag OBS streams
--   obs_playback_url  — added by 20290609000000_add_gaming_stream_columns.sql for OBS playback
--
-- NOT DROPPED (used by main broadcast system):
--   livekit_room_name — core column from baseline, used by ViewerPage, SetupPage, etc.

-- Step 1: Add agora_channel if it doesn't exist (may already be in baseline)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'streams' AND column_name = 'agora_channel'
  ) THEN
    ALTER TABLE streams ADD COLUMN agora_channel TEXT;
  END IF;
END $$;

-- Function: process_gift_xp
CREATE OR REPLACE FUNCTION public.process_gift_xp(
    p_gift_tx_id UUID,
    p_stream_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $
DECLARE
    v_gift_record RECORD;
    v_stream_record RECORD;
    v_xp_rates JSONB;
    v_is_live BOOLEAN := false;
    v_gifter_rate NUMERIC;
    v_gifter_xp NUMERIC;
    v_broadcaster_xp NUMERIC;
    v_sender_ip TEXT;
    v_sender_fingerprint TEXT;
BEGIN
    -- 1. Fetch Gift Transaction from stream_gifts table (primary source)
    SELECT * INTO v_gift_record
    FROM public.stream_gifts
    WHERE id = p_gift_tx_id;

    IF NOT FOUND THEN
        -- Fallback to gift_ledger if stream_gifts doesn't have it
        SELECT * INTO v_gift_record
        FROM public.gift_ledger
        WHERE id = p_gift_tx_id;
        
        IF NOT FOUND THEN
            -- Fallback to coin_transactions for older transactions
            SELECT 
                (metadata->>'sender_id')::uuid as sender_id,
                (metadata->>'recipient_id')::uuid as receiver_id,
                abs(amount) as amount,
                (metadata->>'stream_id')::uuid as stream_id,
                metadata
            INTO v_gift_record
            FROM public.coin_transactions
            WHERE id = p_gift_tx_id AND type = 'gift_sent';
            
            IF NOT FOUND THEN
                RETURN jsonb_build_object('success', false, 'message', 'Gift transaction not found.');
            END IF;
        END IF;
    END IF;

    -- 2. Anti-Farming: Self-Gifting Check
    IF v_gift_record.sender_id = v_gift_record.receiver_id THEN
        RETURN jsonb_build_object('success', false, 'message', 'Self-gifting does not award XP.');
    END IF;

    -- 2b. Fraud Detection: Fingerprint/IP Sharing
    IF (v_gift_record.metadata->>'fingerprint' IS NOT NULL AND 
        v_gift_record.metadata->>'fingerprint' = v_gift_record.metadata->>'receiver_fingerprint') OR
       (v_gift_record.metadata->>'ip_address' IS NOT NULL AND 
        v_gift_record.metadata->>'ip_address' = v_gift_record.metadata->>'receiver_ip') THEN
        
        v_gift_record.metadata := COALESCE(v_gift_record.metadata, '{}'::jsonb) || jsonb_build_object('suspicious', true, 'reason', 'shared_identity');
    END IF;

    -- 3. Fetch XP Rates from Single Source of Truth
    SELECT setting_value INTO v_xp_rates
    FROM public.admin_app_settings
    WHERE setting_key = 'xp_rates';

    -- 4. Server-Side Live Validation
    IF p_stream_id IS NOT NULL THEN
        SELECT * INTO v_stream_record
        FROM public.streams
        WHERE id = p_stream_id AND (status = 'active' OR is_live = true);
        
        IF FOUND THEN
            v_is_live := true;
        END IF;
    END IF;

    -- 5. Calculate XP
    v_gifter_rate := CASE WHEN v_is_live THEN (v_xp_rates->>'gifter_live_bonus')::numeric ELSE (v_xp_rates->>'gifter_base')::numeric END;
    v_gifter_xp := FLOOR(v_gift_record.amount * v_gifter_rate);
    v_broadcaster_xp := FLOOR(v_gift_record.amount * (v_xp_rates->>'broadcaster_base')::numeric);

    -- 6. Award XP (Idempotent calls)
    PERFORM public.grant_xp(
        v_gift_record.sender_id, 
        v_gifter_xp, 
        'gift_sent', 
        p_gift_tx_id::text, 
        jsonb_build_object('receiver_id', v_gift_record.receiver_id, 'is_live', v_is_live)
    );

    PERFORM public.grant_xp(
        v_gift_record.receiver_id, 
        v_broadcaster_xp, 
        'gift_received', 
        p_gift_tx_id::text, 
        jsonb_build_object('sender_id', v_gift_record.sender_id, 'is_live', v_is_live)
    );

    RETURN jsonb_build_object(
        'success', true, 
        'is_live', v_is_live, 
        'gifter_xp', v_gifter_xp, 
        'broadcaster_xp', v_broadcaster_xp
    );
END;
$;

-- Permissions
GRANT EXECUTE ON FUNCTION public.grant_xp(UUID, NUMERIC, TEXT, TEXT, JSONB, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.reverse_xp(TEXT, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.process_gift_xp(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.process_gift_xp(UUID, UUID) TO service_role;

-- Compatibility shim: notify_admins wrapper
-- Some triggers/functions expect public.notify_admins(...) to exist.

CREATE OR REPLACE FUNCTION public.notify_admins(
  p_type TEXT,
  p_title TEXT,
  p_message TEXT,
  p_metadata JSONB DEFAULT '{}'::jsonb,
  p_priority TEXT DEFAULT 'normal'
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Prefer the newer unified staff notifier if it exists
  IF to_regprocedure('public.notify_staff(text,text,text,jsonb)') IS NOT NULL THEN
    PERFORM public.notify_staff(p_type, p_title, p_message, p_metadata);
    RETURN;
  END IF;

  -- Fallback: notify admins only
  INSERT INTO public.notifications (user_id, type, title, message, metadata, priority, created_at, is_read)
  SELECT id, p_type, p_title, p_message, COALESCE(p_metadata, '{}'::jsonb), COALESCE(p_priority, 'normal'), NOW(), FALSE
  FROM public.user_profiles
  WHERE role = 'admin' OR is_admin = true;
END;
$$;

-- Function: process_treasury_payout_run
CREATE OR REPLACE FUNCTION public.process_treasury_payout_run(p_payout_run_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_uid uuid;
  v_allowed boolean := false;
  v_treasury_id uuid;
  v_balance_before bigint;
  v_balance_after bigint;
  v_total_amount bigint := 0;
  v_item record;
  v_before_balance bigint;
  v_after_balance bigint;
BEGIN
  v_uid := auth.uid();

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_profiles
    WHERE id = v_uid
      AND (
        role IN ('admin', 'president', 'owner')
        OR is_admin = true
        OR role = 'ceo'
        OR troll_role IN ('admin', 'president', 'owner', 'ceo')
      )
  ) INTO v_allowed;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Only admins, CEOs, or the president can process treasury payout runs';
  END IF;

  SELECT id, balance_coins
    INTO v_treasury_id, v_balance_before
  FROM public.troll_city_treasury
  ORDER BY created_at ASC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.troll_city_treasury (treasury_name, balance_coins, total_earned_coins, total_distributed_coins, status)
    VALUES ('maitroll Treasury', 0, 0, 0, 'active')
    RETURNING id, balance_coins INTO v_treasury_id, v_balance_before;
  END IF;

  SELECT COALESCE(SUM(amount_coins), 0)
    INTO v_total_amount
  FROM public.treasury_payout_items
  WHERE payout_run_id = p_payout_run_id
    AND status = 'pending';

  IF v_total_amount <= 0 THEN
    RAISE EXCEPTION 'There are no pending treasury payout items to process';
  END IF;

  IF v_total_amount > v_balance_before THEN
    RAISE EXCEPTION 'Insufficient treasury balance to process this payout run';
  END IF;

  UPDATE public.treasury_payout_runs
  SET status = 'paid',
      processed_by = v_uid,
      processed_at = now(),
      updated_at = now()
  WHERE id = p_payout_run_id
    AND status = 'approved';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Only approved treasury payout runs can be processed';
  END IF;

  FOR v_item IN
    SELECT id, user_id, amount_coins, role_key
    FROM public.treasury_payout_items
    WHERE payout_run_id = p_payout_run_id
      AND status = 'pending'
    FOR UPDATE
  LOOP
    SELECT COALESCE(troll_coins, 0), COALESCE(total_earned_coins, 0)
      INTO v_before_balance, v_after_balance
    FROM public.user_profiles
    WHERE id = v_item.user_id
    FOR UPDATE;

    UPDATE public.user_profiles
    SET troll_coins = v_before_balance + v_item.amount_coins,
        total_earned_coins = v_after_balance + v_item.amount_coins,
        updated_at = now()
    WHERE id = v_item.user_id;

    INSERT INTO public.coin_transactions (
      user_id,
      amount,
      type,
      description,
      metadata
    )
    VALUES (
      v_item.user_id,
      v_item.amount_coins,
      'treasury_role_payout',
      'President-approved treasury allocation',
      jsonb_build_object(
        'payout_run_id', p_payout_run_id,
        'role_key', v_item.role_key,
        'processed_by', v_uid
      )
    );

    UPDATE public.treasury_payout_items
    SET status = 'paid',
        paid_at = now()
    WHERE id = v_item.id;
  END LOOP;

  v_balance_after := v_balance_before - v_total_amount;

  UPDATE public.troll_city_treasury
  SET balance_coins = v_balance_after,
      total_distributed_coins = total_distributed_coins + v_total_amount,
      updated_at = now()
  WHERE id = v_treasury_id;

  INSERT INTO public.treasury_transactions (
    treasury_id,
    user_id,
    transaction_type,
    source_type,
    source_id,
    direction,
    amount_coins,
    balance_before,
    balance_after,
    created_by,
    details
  )
  VALUES (
    v_treasury_id,
    NULL,
    'role_distribution',
    'weekly_role_payout',
    p_payout_run_id,
    'debit',
    v_total_amount,
    v_balance_before,
    v_balance_after,
    v_uid,
    jsonb_build_object('payout_run_id', p_payout_run_id, 'processed_by', v_uid)
  );

  RETURN jsonb_build_object(
    'payout_run_id', p_payout_run_id,
    'status', 'paid',
    'total_distributed_coins', v_total_amount,
    'balance_after', v_balance_after
  );
END;
$$;

-- Function: purchase_admin_for_week
CREATE OR REPLACE FUNCTION public.purchase_admin_for_week()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_cost INTEGER := 200000; -- Updated to 200k
    v_balance INTEGER;
BEGIN
    -- Check balance
    SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    IF v_balance < v_cost THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient coins');
    END IF;

    -- Check if already in queue
    IF EXISTS (SELECT 1 FROM public.admin_for_week_queue WHERE user_id = v_user_id AND status IN ('queued', 'active')) THEN
        RETURN jsonb_build_object('success', false, 'error', 'You are already in the queue or active');
    END IF;

    -- Deduct coins
    UPDATE public.user_profiles SET troll_coins = troll_coins - v_cost WHERE id = v_user_id;
    
    -- Add to ledger
    INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason)
    VALUES (v_user_id, -v_cost, 'purchase', 'store', 'Purchase Admin For A Week');

    -- Add to queue
    INSERT INTO public.admin_for_week_queue (user_id, status)
    VALUES (v_user_id, 'queued');

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: purchase_broadcast_theme
CREATE OR REPLACE FUNCTION public.purchase_broadcast_theme(
  p_user_id uuid,
  p_theme_id uuid,
  p_set_active boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_theme record;
  v_spend_result jsonb;
  v_cost numeric; -- Changed from int
BEGIN
  -- 1. Get theme details
  SELECT * INTO v_theme
  FROM public.broadcast_background_themes
  WHERE id = p_theme_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Theme not found');
  END IF;

  v_cost := COALESCE(v_theme.price_coins, 0);

  -- 2. Check if already owned
  IF EXISTS (
    SELECT 1 FROM public.user_broadcast_theme_purchases
    WHERE user_id = p_user_id AND theme_id = p_theme_id
  ) THEN
    -- Already owned, just activate if requested
    IF p_set_active THEN
      INSERT INTO public.user_broadcast_theme_state (user_id, active_theme_id, updated_at)
      VALUES (p_user_id, p_theme_id, now())
      ON CONFLICT (user_id) DO UPDATE
      SET active_theme_id = EXCLUDED.active_theme_id,
          updated_at = now();
    END IF;
    RETURN jsonb_build_object('success', true, 'message', 'Already owned');
  END IF;

  -- 3. Deduct coins if cost > 0
  IF v_cost > 0 THEN
    v_spend_result := public.troll_bank_spend_coins_secure(
      p_user_id,
      v_cost,
      'paid',
      'broadcast_theme_purchase',
      NULL,
      jsonb_build_object('theme_id', p_theme_id, 'theme_name', v_theme.name)
    );

    IF (v_spend_result->>'success')::boolean = false THEN
      RETURN v_spend_result;
    END IF;
  END IF;

  -- 4. Record purchase
  INSERT INTO public.user_broadcast_theme_purchases (user_id, theme_id, purchased_at, cost)
  VALUES (p_user_id, p_theme_id, now(), v_cost);

  -- 5. Activate if requested
  IF p_set_active THEN
    INSERT INTO public.user_broadcast_theme_state (user_id, active_theme_id, updated_at)
    VALUES (p_user_id, p_theme_id, now())
    ON CONFLICT (user_id) DO UPDATE
    SET active_theme_id = EXCLUDED.active_theme_id,
          updated_at = now();
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: purchase_broadcast_theme_with_credit
CREATE OR REPLACE FUNCTION public.purchase_broadcast_theme_with_credit(
    p_user_id UUID,
    p_theme_id UUID,
    p_set_active BOOLEAN DEFAULT false,
    p_use_credit BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_theme record;
    v_cost numeric;
    v_credit_ok boolean;
    v_spend_result jsonb;
BEGIN
    -- 1. Get theme details
    SELECT * INTO v_theme
    FROM public.broadcast_background_themes
    WHERE id = p_theme_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Theme not found');
    END IF;

    v_cost := COALESCE(v_theme.price_coins, 0);

    -- 2. Check if already owned
    IF EXISTS (
        SELECT 1 FROM public.user_broadcast_theme_purchases
        WHERE user_id = p_user_id AND theme_id = p_theme_id
    ) THEN
        IF p_set_active THEN
            INSERT INTO public.user_broadcast_theme_state (user_id, active_theme_id, updated_at)
            VALUES (p_user_id, p_theme_id, now())
            ON CONFLICT (user_id) DO UPDATE
            SET active_theme_id = EXCLUDED.active_theme_id,
                updated_at = now();
        END IF;
        RETURN jsonb_build_object('success', true, 'message', 'Already owned');
    END IF;

    -- 3. Spend coins or credit
    IF v_cost > 0 THEN
        IF p_use_credit THEN
            v_credit_ok := public.try_pay_with_credit_card(
                p_user_id,
                v_cost,
                'shop_purchase',
                jsonb_build_object('theme_id', p_theme_id, 'theme_name', v_theme.name)
            );
            IF NOT v_credit_ok THEN
                RETURN jsonb_build_object('success', false, 'error', 'Credit card payment failed');
            END IF;
        ELSE
            -- Use regular coin spending
            v_spend_result := public.troll_bank_spend_coins_secure(
                p_user_id,
                v_cost,
                'paid',
                'broadcast_theme_purchase',
                NULL,
                jsonb_build_object('theme_id', p_theme_id, 'theme_name', v_theme.name)
            );
            IF (v_spend_result->>'success')::boolean = false THEN
                RETURN v_spend_result;
            END IF;
        END IF;
    END IF;

    -- 4. Record purchase
    INSERT INTO public.user_broadcast_theme_purchases (user_id, theme_id, purchased_at, cost)
    VALUES (p_user_id, p_theme_id, now(), v_cost);

    -- 5. Activate if requested
    IF p_set_active THEN
        INSERT INTO public.user_broadcast_theme_state (user_id, active_theme_id, updated_at)
        VALUES (p_user_id, p_theme_id, now())
        ON CONFLICT (user_id) DO UPDATE
        SET active_theme_id = EXCLUDED.active_theme_id,
            updated_at = now();
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Theme purchased',
        'theme_name', v_theme.name,
        'cost', v_cost,
        'payment_method', CASE WHEN p_use_credit THEN 'credit' ELSE 'coins' END
    );
END;
$$;

-- Function: purchase_from_ktauto
CREATE OR REPLACE FUNCTION purchase_from_ktauto(
    p_catalog_id INTEGER,
    p_plate_type TEXT DEFAULT 'temp',
    p_use_credit BOOLEAN DEFAULT FALSE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_car RECORD;
    v_user_balance BIGINT;
    v_title_fee INTEGER;
    v_reg_fee INTEGER;
    v_total_cost INTEGER;
    v_purchase_count INTEGER;
    v_user_vehicle_id UUID;
    v_plate_number TEXT;
    v_reg_expiry TIMESTAMPTZ;
    v_credit_success BOOLEAN;
    v_inventory_ok BOOLEAN;
BEGIN
    v_user_id := auth.uid();
    
    -- 1. Validate User
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Not authenticated');
    END IF;

    -- 2. Get Car Details
    SELECT * INTO v_car FROM public.vehicles_catalog WHERE id = p_catalog_id;
    IF v_car IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Vehicle not found');
    END IF;

    -- 3. Verify Inventory (lock row to prevent race)
    PERFORM 1
    FROM public.dealership_inventory
    WHERE dealership = 'KTAuto'
      AND catalog_id = p_catalog_id
      AND status = 'active'
      AND quantity > 0
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Vehicle out of stock');
    END IF;

    -- 4. Check Purchase Limit
    SELECT COUNT(*) INTO v_purchase_count 
    FROM public.vehicle_transactions 
    WHERE user_id = v_user_id 
      AND type = 'purchase' 
      AND created_at > NOW() - INTERVAL '30 days';

    IF v_purchase_count >= 25 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Monthly purchase limit reached (25 cars/month)');
    END IF;

    -- 5. Calculate Costs
    SELECT amount INTO v_title_fee FROM public.tmv_fee_schedule WHERE fee_type = 'title_issue';
    
    IF p_plate_type = 'hard' THEN
        SELECT amount INTO v_reg_fee FROM public.tmv_fee_schedule WHERE fee_type = 'registration_new_hard';
        v_reg_expiry := NOW() + INTERVAL '60 days';
    ELSE
        SELECT amount INTO v_reg_fee FROM public.tmv_fee_schedule WHERE fee_type = 'registration_new_temp';
        v_reg_expiry := NOW() + INTERVAL '7 days';
    END IF;

    v_total_cost := v_car.price + COALESCE(v_title_fee, 500) + COALESCE(v_reg_fee, 200);

    -- 6. Payment Processing
    IF p_use_credit THEN
        v_credit_success := public.try_pay_with_credit_card(
            v_user_id, 
            v_total_cost::BIGINT, 
            'vehicle_purchase', 
            jsonb_build_object('car_id', p_catalog_id, 'plate_type', p_plate_type)
        );
        
        IF NOT v_credit_success THEN
             RETURN jsonb_build_object('success', false, 'message', 'Credit card declined (Limit exceeded or restricted)');
        END IF;
    ELSE
        -- Cash Payment
        SELECT troll_coins INTO v_user_balance FROM public.user_profiles WHERE id = v_user_id FOR UPDATE;
        
        IF v_user_balance < v_total_cost THEN
            RETURN jsonb_build_object('success', false, 'message', 'Insufficient funds: ' || v_total_cost || ' required');
        END IF;

        UPDATE public.user_profiles 
        SET troll_coins = troll_coins - v_total_cost 
        WHERE id = v_user_id;
    END IF;

    -- 7. Create User Vehicle
    INSERT INTO public.user_vehicles (user_id, catalog_id)
    VALUES (v_user_id, p_catalog_id)
    RETURNING id INTO v_user_vehicle_id;

    -- 8. Generate Plate
    v_plate_number := public.generate_license_plate();

    -- 9. Create Title
    INSERT INTO public.vehicle_titles (user_vehicle_id, user_id, status)
    VALUES (v_user_vehicle_id, v_user_id, 'clean');

    -- 10. Create Registration
    INSERT INTO public.vehicle_registrations (user_vehicle_id, plate_number, plate_type, expires_at, status)
    VALUES (v_user_vehicle_id, v_plate_number, p_plate_type, v_reg_expiry, 'active');

    -- 11. Create Insurance (Unpaid)
    INSERT INTO public.vehicle_insurance_policies (user_vehicle_id, status)
    VALUES (v_user_vehicle_id, 'unpaid');

    -- 12. Decrement Inventory (after successful purchase)
    v_inventory_ok := public.dealership_decrement_inventory('KTAuto', p_catalog_id);
    IF NOT v_inventory_ok THEN
        RAISE EXCEPTION 'Vehicle out of stock';
    END IF;

    -- 13. Log Transaction
    INSERT INTO public.vehicle_transactions (user_id, user_vehicle_id, type, amount, details)
    VALUES (
        v_user_id, 
        v_user_vehicle_id, 
        'purchase', 
        v_total_cost, 
        jsonb_build_object(
            'car_name', v_car.name, 
            'plate', v_plate_number, 
            'payment_method', CASE WHEN p_use_credit THEN 'credit_card' ELSE 'cash' END
        )
    );

    RETURN jsonb_build_object('success', true, 'message', 'Vehicle purchased successfully', 'vehicle_id', v_user_vehicle_id);
END;
$$;

-- Function: purchase_house
CREATE OR REPLACE FUNCTION public.purchase_house(p_house_catalog_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_house_catalog RECORD;
    v_paid BOOLEAN;
    v_new_house_id UUID;
BEGIN
    -- Get Catalog Info
    SELECT * INTO v_house_catalog FROM public.houses_catalog WHERE id = p_house_catalog_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'House type not found');
    END IF;

    -- Check if user already owns a primary house? 
    -- Kain doesn't strictly forbid multiple houses, but usually games limit 1 per type or just 1 primary.
    -- Let's allow multiple, but only one is primary (handled by app logic later). 
    -- For now, just buy it.

    -- Attempt Payment
    v_paid := public.try_pay_coins(v_user_id, v_house_catalog.base_price, 'house_purchase', jsonb_build_object('catalog_id', p_house_catalog_id, 'name', v_house_catalog.name));

    IF v_paid THEN
        -- Insert User House
        INSERT INTO public.user_houses (
            user_id, 
            house_catalog_id, 
            purchase_price, 
            condition, 
            status, 
            influence_active,
            last_tax_paid_at,
            last_maintenance_paid_at
        )
        VALUES (
            v_user_id, 
            p_house_catalog_id, 
            v_house_catalog.base_price, 
            100, 
            'active', 
            true,
            NOW(), -- Paid up front for today? Or starts accruing? Let's say grace period starts now.
            NOW()
        )
        RETURNING id INTO v_new_house_id;

        RETURN jsonb_build_object('success', true, 'house_id', v_new_house_id);
    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds');
    END IF;
END;
$$;

-- Function: purchase_house_upgrade
CREATE OR REPLACE FUNCTION public.purchase_house_upgrade(
  p_user_house_id UUID,
  p_upgrade_id UUID
) RETURNS JSONB 
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_user_id UUID;
  v_house_owner_id UUID;
  v_price BIGINT;
  v_upgrade_exists BOOLEAN;
  v_upgrade_record RECORD;
  v_house_status TEXT;
  v_balance BIGINT;
BEGIN
  v_user_id := auth.uid();
  
  -- Get Upgrade Info
  SELECT * INTO v_upgrade_record FROM public.house_upgrades_catalog WHERE id = p_upgrade_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Upgrade not found');
  END IF;
  v_price := v_upgrade_record.base_price;

  -- Check house ownership
  SELECT user_id, status INTO v_house_owner_id, v_house_status
  FROM public.user_houses
  WHERE id = p_user_house_id;
  
  IF v_house_owner_id IS NULL OR v_house_owner_id != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'You do not own this house');
  END IF;
  
  IF v_house_status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'message', 'House must be active to upgrade');
  END IF;

  -- Check Balance
  SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
  IF v_balance < v_price THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient funds');
  END IF;

  -- Deduct
  UPDATE public.user_profiles SET troll_coins = troll_coins - v_price WHERE id = v_user_id;

  -- User Ledger
  INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, metadata)
  VALUES (v_user_id, -v_price, 'spend', 'house_upgrade', 'Purchased ' || v_upgrade_record.name, jsonb_build_object('house_id', p_user_house_id));

  -- Officer Ledger
  INSERT INTO public.officer_pay_ledger (source_type, source_id, coin_amount, metadata)
  VALUES ('house_upgrade', p_user_house_id::text, v_price, jsonb_build_object('user_id', v_user_id, 'upgrade_name', v_upgrade_record.name));

  -- Install
  INSERT INTO public.house_installations (user_house_id, upgrade_id)
  VALUES (p_user_house_id, p_upgrade_id);

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: purchase_landlord_license
CREATE OR REPLACE FUNCTION public.purchase_landlord_license()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_cost INTEGER := 7000;
    v_balance INTEGER;
BEGIN
    -- Check if already landlord
    IF EXISTS (SELECT 1 FROM public.user_profiles WHERE id = v_user_id AND is_landlord = true) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already a landlord');
    END IF;

    -- Check balance
    SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    IF v_balance < v_cost THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds');
    END IF;

    -- Deduct coins
    UPDATE public.user_profiles SET troll_coins = troll_coins - v_cost WHERE id = v_user_id;

    -- Record transaction (to Admin Pool)
    INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
    VALUES (v_user_id, -v_cost, 'purchase', 'landlord_license', 'Landlord License Purchase', 'out');

    -- Grant License
    UPDATE public.user_profiles SET is_landlord = true WHERE id = v_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: purchase_rgb_broadcast
CREATE OR REPLACE FUNCTION public.purchase_rgb_broadcast(
  p_stream_id UUID,
  p_enable BOOLEAN DEFAULT TRUE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_user_id UUID;
  v_stream RECORD;
  v_balance INT;
  v_cost INT := 10;
  v_ledger_item_id UUID;
BEGIN
  v_user_id := auth.uid();
  
  -- 1. Verify Stream Ownership
  SELECT * INTO v_stream 
  FROM public.streams 
  WHERE id = p_stream_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Stream not found');
  END IF;
  
  IF v_stream.user_id != v_user_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- 2. Handle Logic
  IF v_stream.rgb_purchased THEN
    -- Already purchased, just toggle
    UPDATE public.streams
    SET has_rgb_effect = p_enable
    WHERE id = p_stream_id;
    
    RETURN jsonb_build_object('success', true, 'message', 'Toggled RGB');
  ELSE
    -- Not purchased yet
    IF NOT p_enable THEN
       RETURN jsonb_build_object('success', false, 'error', 'Must purchase to enable');
    END IF;

    -- Check Balance
    SELECT troll_coins INTO v_balance
    FROM public.user_profiles
    WHERE id = v_user_id;
    
    IF v_balance < v_cost THEN
      RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds');
    END IF;

    -- Deduct Coins
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - v_cost
    WHERE id = v_user_id;
    
    -- Enable & Mark Purchased
    UPDATE public.streams
    SET has_rgb_effect = TRUE,
        rgb_purchased = TRUE
    WHERE id = p_stream_id;
    
    -- Log to Purchase Ledger (CRITICAL SYNC)
    SELECT id INTO v_ledger_item_id FROM public.purchasable_items WHERE item_key = 'stream-rgb';
    
    IF v_ledger_item_id IS NOT NULL THEN
        INSERT INTO public.purchase_ledger (
            user_id, item_id, coin_amount, payment_method, source_context, created_at
        ) VALUES (
            v_user_id, v_ledger_item_id, v_cost, 'coins', p_stream_id::text, now()
        );
    END IF;

    -- Log Transaction (Legacy)
    INSERT INTO public.coin_transactions (
      user_id,
      amount,
      type,
      metadata
    ) VALUES (
      v_user_id,
      -v_cost,
      'purchase',
      jsonb_build_object('description', 'Purchased RGB Broadcast Box', 'stream_id', p_stream_id)
    );

    RETURN jsonb_build_object('success', true, 'message', 'Purchased and Enabled');
  END IF;
END;
$$;

-- Function: purchase_vehicle_asset
CREATE OR REPLACE FUNCTION public.purchase_vehicle_asset(
  p_vehicle_id TEXT,
  p_user_id UUID DEFAULT auth.uid()
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_catalog RECORD;
  v_user_coins NUMERIC;
  v_asset_id UUID;
BEGIN
  -- Validate user
  IF p_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Authentication required');
  END IF;

  -- Set bypass flag for coin protection trigger
  PERFORM set_config('app.bypass_coin_protection', 'true', true);

  -- Get vehicle catalog entry
  SELECT * INTO v_catalog
  FROM public.vehicle_catalog
  WHERE vehicle_id = p_vehicle_id AND is_active = true;

  IF v_catalog IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Vehicle not found or not available');
  END IF;

  -- Check stock (if limited)
  IF v_catalog.stock_quantity >= 0 THEN
    IF v_catalog.stock_quantity = 0 THEN
      RETURN json_build_object('success', false, 'error', 'Vehicle out of stock');
    END IF;
  END IF;

  -- Get user's coin balance
  SELECT COALESCE(troll_coins, 0) INTO v_user_coins
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF v_user_coins IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'User profile not found');
  END IF;

  -- Check sufficient funds
  IF v_user_coins < v_catalog.base_price THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Insufficient coins. Need ' || v_catalog.base_price || ' but have ' || v_user_coins
    );
  END IF;

  -- Deduct coins from user
  UPDATE public.user_profiles
  SET troll_coins = troll_coins - v_catalog.base_price
  WHERE id = p_user_id AND troll_coins >= v_catalog.base_price;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Failed to deduct coins');
  END IF;

  -- Create user vehicle asset
  INSERT INTO public.user_vehicle_assets (
    user_id,
    catalog_id,
    vehicle_name,
    purchase_price,
    buyback_percentage
  ) VALUES (
    p_user_id,
    v_catalog.id,
    v_catalog.name,
    v_catalog.base_price,
    v_catalog.buyback_percentage
  ) RETURNING id INTO v_asset_id;

  -- Decrease stock if limited
  IF v_catalog.stock_quantity > 0 THEN
    UPDATE public.vehicle_catalog
    SET stock_quantity = stock_quantity - 1
    WHERE id = v_catalog.id;
  END IF;

  -- Record transaction
  INSERT INTO public.vehicle_transactions (
    user_id,
    catalog_id,
    asset_id,
    transaction_type,
    vehicle_name,
    amount,
    metadata
  ) VALUES (
    p_user_id,
    v_catalog.id,
    v_asset_id,
    'purchase',
    v_catalog.name,
    -v_catalog.base_price,
    jsonb_build_object(
      'buyback_percentage', v_catalog.buyback_percentage,
      'tier', v_catalog.tier
    )
  );

  RETURN json_build_object(
    'success', true,
    'asset_id', v_asset_id,
    'vehicle_name', v_catalog.name,
    'purchase_price', v_catalog.base_price,
    'buyback_percentage', v_catalog.buyback_percentage,
    'buyback_value', ROUND(v_catalog.base_price * v_catalog.buyback_percentage / 100)
  );
END;
$$;

-- Function: record_battle_skip
CREATE OR REPLACE FUNCTION public.record_battle_skip(
    p_user_id UUID,
    p_free_limit INTEGER DEFAULT 5,
    p_cost INTEGER DEFAULT 50
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_skips RECORD;
    v_balance BIGINT;
    v_charged BOOLEAN := FALSE;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
    END IF;

    SELECT * INTO v_skips
    FROM public.battle_skips
    WHERE user_id = p_user_id AND skip_date = CURRENT_DATE;

    IF v_skips IS NULL THEN
        INSERT INTO public.battle_skips (user_id, skips_used)
        VALUES (p_user_id, 0)
        RETURNING * INTO v_skips;
    END IF;

    IF v_skips.skips_used >= p_free_limit THEN
        SELECT troll_coins INTO v_balance
        FROM public.user_profiles
        WHERE id = p_user_id
        FOR UPDATE;

        IF v_balance IS NULL OR v_balance < p_cost THEN
            RETURN jsonb_build_object('success', false, 'message', 'Insufficient Troll Coins');
        END IF;

        UPDATE public.user_profiles
        SET troll_coins = troll_coins - p_cost
        WHERE id = p_user_id;

        v_charged := TRUE;
    END IF;

    UPDATE public.battle_skips
    SET skips_used = skips_used + 1,
        last_skip_time = NOW()
    WHERE id = v_skips.id;

    RETURN jsonb_build_object(
        'success', true,
        'skips_used', v_skips.skips_used + 1,
        'charged', v_charged,
        'cost', CASE WHEN v_charged THEN p_cost ELSE 0 END
    );
END;
$$;

-- Function: record_completed_sale
CREATE OR REPLACE FUNCTION public.record_completed_sale(p_seller_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_result JSONB;
BEGIN
    -- Increment completed sales
    UPDATE public.user_profiles
    SET completed_sales = COALESCE(completed_sales, 0) + 1
    WHERE id = p_seller_id;
    
    -- Re-evaluate tier
    SELECT * INTO v_result FROM public.evaluate_seller_tier(p_seller_id);
    
    RETURN v_result;
END;
$$;

-- Function: record_dispute
CREATE OR REPLACE FUNCTION public.record_dispute(p_seller_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_result JSONB;
BEGIN
    -- Increment dispute count
    UPDATE public.user_profiles
    SET dispute_count = COALESCE(dispute_count, 0) + 1
    WHERE id = p_seller_id;
    
    -- Re-evaluate tier
    SELECT * INTO v_result FROM public.evaluate_seller_tier(p_seller_id);
    
    RETURN v_result;
END;
$$;

-- Function: record_fraud_flag
CREATE OR REPLACE FUNCTION public.record_fraud_flag(p_seller_id UUID, p_flag_count INTEGER DEFAULT 1)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_result JSONB;
BEGIN
    -- Increment fraud flags
    UPDATE public.user_profiles
    SET fraud_flags = COALESCE(fraud_flags, 0) + p_flag_count
    WHERE id = p_seller_id;
    
    -- Re-evaluate tier (may trigger downgrade)
    SELECT * INTO v_result FROM public.evaluate_seller_tier(p_seller_id);
    
    RETURN v_result;
END;
$$;

