-- Function: record_state_battle
CREATE OR REPLACE FUNCTION public.record_state_battle(
    p_battle_id UUID,
    p_host_user_id UUID,
    p_challenger_user_id UUID,
    p_winner_user_id UUID,
    p_host_score INTEGER,
    p_challenger_score INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
AS $$
DECLARE
    v_host_state TEXT;
    v_challenger_state TEXT;
    v_winner_state TEXT;
    v_loser_state TEXT;
    v_points INTEGER := 500;
    v_state_battle_id UUID;
BEGIN
    -- Get states for both participants
    SELECT state_code INTO v_host_state FROM public.state_members WHERE user_id = p_host_user_id;
    SELECT state_code INTO v_challenger_state FROM public.state_members WHERE user_id = p_challenger_user_id;

    IF v_host_state IS NULL OR v_challenger_state IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'One or both users have no state assigned');
    END IF;

    -- Determine winner state
    IF p_winner_user_id = p_host_user_id THEN
        v_winner_state := v_host_state;
        v_loser_state := v_challenger_state;
    ELSIF p_winner_user_id = p_challenger_user_id THEN
        v_winner_state := v_challenger_state;
        v_loser_state := v_host_state;
    ELSE
        -- Draw - no points awarded, just record
        INSERT INTO public.state_battles (battle_id, state_a, state_b, winner_state, points_awarded, host_user_id, challenger_user_id)
        VALUES (p_battle_id, v_host_state, v_challenger_state, NULL, 0, p_host_user_id, p_challenger_user_id)
        RETURNING id INTO v_state_battle_id;

        RETURN jsonb_build_object('success', true, 'draw', true, 'state_battle_id', v_state_battle_id);
    END IF;

    -- Insert state battle record
    INSERT INTO public.state_battles (battle_id, state_a, state_b, winner_state, points_awarded, host_user_id, challenger_user_id)
    VALUES (p_battle_id, v_host_state, v_challenger_state, v_winner_state, v_points, p_host_user_id, p_challenger_user_id)
    RETURNING id INTO v_state_battle_id;

    -- Update winner state
    UPDATE public.states SET
        battle_points = battle_points + v_points,
        wins = wins + 1,
        monthly_points = monthly_points + v_points,
        monthly_wins = monthly_wins + 1,
        updated_at = NOW()
    WHERE state_code = v_winner_state;

    -- Update loser state
    UPDATE public.states SET
        losses = losses + 1,
        monthly_losses = monthly_losses + 1,
        updated_at = NOW()
    WHERE state_code = v_loser_state;

    -- Update winner's state member stats
    UPDATE public.state_members SET
        battle_points_earned = battle_points_earned + v_points,
        battles_participated = battles_participated + 1,
        battles_won = battles_won + 1
    WHERE user_id = p_winner_user_id;

    -- Update loser's state member stats
    UPDATE public.state_members SET
        battles_participated = battles_participated + 1
    WHERE user_id = CASE WHEN p_winner_user_id = p_host_user_id THEN p_challenger_user_id ELSE p_host_user_id END;

    -- Check and update representative for winner state
    PERFORM public.update_state_representative(v_winner_state);

    RETURN jsonb_build_object(
        'success', true,
        'winner_state', v_winner_state,
        'loser_state', v_loser_state,
        'points_awarded', v_points,
        'state_battle_id', v_state_battle_id
    );
END;
$$;

-- Function: record_troll_family_activity
CREATE OR REPLACE FUNCTION public.record_troll_family_activity(
    p_user_id uuid,
    p_event_type text,
    p_amount numeric DEFAULT 1,
    p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_family_id uuid;
    v_event_id uuid;
    v_current_season_id uuid;
    v_goals_matched integer := 0;
    v_progress_updated integer := 0;
    v_result jsonb;
    v_goal record;
    v_current_progress integer;
    v_target_value integer;
    v_is_duplicate boolean := false;
    v_dedup_key text;
BEGIN
    -- Validate inputs
    IF p_user_id IS NULL OR p_event_type IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Missing required parameters'
        );
    END IF;

    -- Get user's family and verify approval status
    SELECT fm.family_id INTO v_family_id
    FROM public.family_members fm
    WHERE fm.user_id = p_user_id
    AND fm.approval_status = 'approved'
    LIMIT 1;

    IF v_family_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'User is not an approved member of any Troll Family'
        );
    END IF;

    -- Get current active season
    SELECT id INTO v_current_season_id
    FROM public.troll_family_league_seasons
    WHERE is_active = true
    AND CURRENT_DATE BETWEEN season_start_date AND season_end_date
    LIMIT 1;

    IF v_current_season_id IS NULL THEN
        -- Create a new season if none exists
        INSERT INTO public.troll_family_league_seasons (
            season_number,
            season_start_date,
            season_end_date,
            is_active,
            name
        ) VALUES (
            COALESCE((SELECT MAX(season_number) FROM public.troll_family_league_seasons) + 1, 1),
            DATE_TRUNC('month', CURRENT_DATE)::date,
            (DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month' - INTERVAL '1 day')::date,
            true,
            'Season ' || COALESCE((SELECT MAX(season_number) FROM public.troll_family_league_seasons) + 1, 1)
        )
        RETURNING id INTO v_current_season_id;
    END IF;

    -- Check for duplicates using dedup_key in metadata
    v_dedup_key := p_metadata->>'dedup_key';
    IF v_dedup_key IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1 FROM public.troll_family_activity_events
            WHERE family_id = v_family_id
            AND user_id = p_user_id
            AND event_type = p_event_type
            AND metadata->>'dedup_key' = v_dedup_key
        ) INTO v_is_duplicate;

        IF v_is_duplicate THEN
            RETURN jsonb_build_object(
                'success', false,
                'message', 'Duplicate event detected'
            );
        END IF;
    END IF;

    -- Record the activity event
    INSERT INTO public.troll_family_activity_events (
        family_id,
        user_id,
        event_type,
        amount,
        metadata,
        recorded_at
    ) VALUES (
        v_family_id,
        p_user_id,
        p_event_type,
        p_amount,
        p_metadata,
        NOW()
    )
    RETURNING id INTO v_event_id;

    -- Find and update relevant goals
    FOR v_goal IN
        SELECT id, target_value, current_value, category, goal_type
        FROM public.family_goals
        WHERE family_id = v_family_id
        AND status = 'active'
        AND (
            -- Match goals to event types
            (p_event_type = 'broadcast_gift_earned' AND goal_type IN ('broadcast', 'coins'))
            OR (p_event_type = 'broadcast_gift_sent' AND goal_type IN ('broadcast', 'generosity'))
            OR (p_event_type = 'broadcast_watch_time' AND goal_type IN ('watch', 'engagement'))
            OR (p_event_type = 'battle_won' AND goal_type IN ('battle', 'competition'))
            OR (p_event_type = 'battle_joined' AND goal_type IN ('battle', 'participation'))
            OR (p_event_type = 'stream_started' AND goal_type IN ('broadcast', 'creation'))
            OR (p_event_type = 'hype_coin_earned' AND goal_type IN ('engagement', 'watch'))
            OR (p_event_type = 'troll_coin_earned' AND goal_type IN ('coins', 'earnings'))
            OR (p_event_type = 'chat_message_sent' AND goal_type IN ('engagement', 'activity'))
        )
    LOOP
        v_target_value := v_goal.target_value;

        -- Update or insert goal progress for this user
        INSERT INTO public.family_goal_progress (
            goal_id,
            user_id,
            family_id,
            contribution_value,
            last_activity_at
        ) VALUES (
            v_goal.id,
            p_user_id,
            v_family_id,
            p_amount::integer,
            NOW()
        )
        ON CONFLICT (goal_id, user_id) DO UPDATE SET
            contribution_value = family_goal_progress.contribution_value + EXCLUDED.contribution_value,
            last_activity_at = NOW();

        -- Update goal's current_value (sum of all contributions)
        UPDATE public.family_goals
        SET current_value = (
            SELECT COALESCE(SUM(contribution_value), 0)::integer
            FROM public.family_goal_progress
            WHERE goal_id = v_goal.id
        )
        WHERE id = v_goal.id;

        -- Check if goal is now complete
        IF (SELECT current_value FROM public.family_goals WHERE id = v_goal.id) >= v_target_value THEN
            UPDATE public.family_goals
            SET status = 'completed', completed_at = NOW()
            WHERE id = v_goal.id;

            -- Award coins/XP and league points
            UPDATE public.troll_family_league_standings
            SET 
                points = points + v_goal.target_value,
                goals_completed = goals_completed + 1,
                coins_earned = coins_earned + COALESCE((SELECT reward_coins FROM public.family_goals WHERE id = v_goal.id), 0)
            WHERE season_id = v_current_season_id AND family_id = v_family_id;
        END IF;

        v_goals_matched := v_goals_matched + 1;
    END LOOP;

    -- Update family standings for this season
    INSERT INTO public.troll_family_league_standings (season_id, family_id)
    VALUES (v_current_season_id, v_family_id)
    ON CONFLICT (season_id, family_id) DO UPDATE SET
        updated_at = NOW(),
        total_member_activity = troll_family_league_standings.total_member_activity + p_amount;

    v_result := jsonb_build_object(
        'success', true,
        'message', 'Activity recorded successfully',
        'event_id', v_event_id,
        'family_id', v_family_id,
        'event_type', p_event_type,
        'amount', p_amount,
        'goals_matched', v_goals_matched,
        'season_id', v_current_season_id
    );

    RETURN v_result;
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'message', 'Error recording activity: ' || SQLERRM
    );
END;
$$;

-- Function: redeem_crowns_for_coins
CREATE OR REPLACE FUNCTION public.redeem_crowns_for_coins(
  p_user_id UUID,
  p_crowns INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_current_crowns INTEGER;
  v_new_crowns INTEGER;
  v_redemption_id UUID;
BEGIN
  -- Bypass security trigger for coin updates
  PERFORM set_config('app.bypass_coin_protection', 'true', true);

  -- Lock the user profile row to prevent race conditions
  SELECT COALESCE(battle_crowns, 0) INTO v_current_crowns
  FROM public.user_profiles
  WHERE id = p_user_id
  FOR UPDATE;

  IF v_current_crowns IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'User profile not found');
  END IF;

  IF p_crowns <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Must redeem at least 1 crown');
  END IF;

  IF v_current_crowns < p_crowns THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient crowns', 'current_crowns', v_current_crowns);
  END IF;

  -- Deduct crowns
  UPDATE public.user_profiles
  SET battle_crowns = COALESCE(battle_crowns, 0) - p_crowns,
      updated_at = now()
  WHERE id = p_user_id
  RETURNING COALESCE(battle_crowns, 0) INTO v_new_crowns;

  -- Add troll coins (1 crown = 1 troll coin)
  UPDATE public.user_profiles
  SET troll_coins = COALESCE(troll_coins, 0) + p_crowns,
      updated_at = now()
  WHERE id = p_user_id;

  -- Create redemption record
  INSERT INTO public.crown_redemptions (
    user_id, reward_type, crowns_redeemed, reward_value, status
  ) VALUES (
    p_user_id, 'troll_coins', p_crowns, p_crowns || ' Troll Coins', 'fulfilled'
  ) RETURNING id INTO v_redemption_id;

  -- Record coin transaction
  INSERT INTO public.coin_transactions (
    user_id, type, amount, description, metadata
  ) VALUES (
    p_user_id, 'crown_redemption', p_crowns,
    'Converted ' || p_crowns || ' crowns to ' || p_crowns || ' Troll Coins',
    jsonb_build_object('crown_redemption_id', v_redemption_id, 'crowns_redeemed', p_crowns)
  );

  RETURN jsonb_build_object(
    'success', true,
    'redemption_id', v_redemption_id,
    'crowns_redeemed', p_crowns,
    'coins_awarded', p_crowns,
    'new_crown_balance', v_new_crowns
  );
END;
$$;

-- Function: refresh_user_earnings_summary
CREATE OR REPLACE FUNCTION public.refresh_user_earnings_summary()
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.user_earnings_summary;
END;
$$;

-- Function: refund_marketplace_order
CREATE OR REPLACE FUNCTION refund_marketplace_order(p_order_id uuid)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_purchase marketplace_purchases%ROWTYPE;
BEGIN
  SELECT * INTO v_purchase FROM marketplace_purchases WHERE id = p_order_id;
  
  IF v_purchase IS NULL THEN
    RETURN 'Order not found';
  END IF;

  IF v_purchase.status IN ('cancelled', 'refunded') THEN
    RETURN 'Order already cancelled or refunded';
  END IF;

  UPDATE marketplace_purchases
  SET status = 'refunded',
      refunded_at = now()
  WHERE id = p_order_id;

  RETURN 'Order refunded successfully';
END;
$$;

-- Function: refund_payout_run
CREATE OR REPLACE FUNCTION refund_payout_run(p_run_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_payout RECORD;
BEGIN
  FOR v_payout IN SELECT * FROM payouts WHERE run_id = p_run_id AND status = 'queued'
  LOOP
    -- Refund User
    UPDATE user_profiles
    SET troll_coins = troll_coins + v_payout.amount_coins
    WHERE id = v_payout.user_id;
    
    -- Ledger Entry
    INSERT INTO coin_ledger (user_id, delta, bucket, source, ref_id, reason)
    VALUES (v_payout.user_id, v_payout.amount_coins, 'payout', 'payout_refund', p_run_id::text, 'Refund: PayPal Batch Failed');
    
    -- Update Payout Status
    UPDATE payouts
    SET status = 'returned', failure_reason = 'PayPal Batch Submission Failed'
    WHERE id = v_payout.id;
  END LOOP;
  
  UPDATE payout_runs
  SET status = 'failed'
  WHERE id = p_run_id;
END;
$$;

-- Function: register_for_event
CREATE OR REPLACE FUNCTION public.register_for_event(
  p_event_id UUID,
  p_user_id UUID,
  p_username TEXT,
  p_avatar_url TEXT DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_event RECORD;
  v_participant_count INTEGER;
  v_existing_registration RECORD;
BEGIN
  -- Get event
  SELECT * INTO v_event FROM public.events WHERE id = p_event_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Event not found');
  END IF;

  -- Check if event is open for registration
  IF v_event.status IN ('completed', 'cancelled', 'archived') THEN
    RETURN json_build_object('success', false, 'error', 'Event is not open for registration');
  END IF;

  -- Check if registration is locked
  IF v_event.registration_locked THEN
    RETURN json_build_object('success', false, 'error', 'Registration is locked for this event');
  END IF;

  -- Check if already registered
  SELECT * INTO v_existing_registration FROM public.event_participants
  WHERE event_id = p_event_id AND user_id = p_user_id;

  IF FOUND THEN
    IF v_existing_registration.status = 'cancelled' THEN
      -- Re-register
      UPDATE public.event_participants
      SET status = 'registered', registered_at = now()
      WHERE id = v_existing_registration.id;
      RETURN json_build_object('success', true, 'status', 'registered');
    END IF;
    RETURN json_build_object('success', false, 'error', 'Already registered for this event');
  END IF;

  -- Check capacity
  IF v_event.max_participants IS NOT NULL THEN
    SELECT COUNT(*) INTO v_participant_count
    FROM public.event_participants
    WHERE event_id = p_event_id AND status IN ('registered', 'confirmed');

    IF v_participant_count >= v_event.max_participants THEN
      -- Add to waitlist
      INSERT INTO public.event_participants (event_id, user_id, username, avatar_url, status)
      VALUES (p_event_id, p_user_id, p_username, p_avatar_url, 'waitlisted');
      RETURN json_build_object('success', true, 'status', 'waitlisted');
    END IF;
  END IF;

  -- Register
  INSERT INTO public.event_participants (event_id, user_id, username, avatar_url, status)
  VALUES (p_event_id, p_user_id, p_username, p_avatar_url, 'registered');

  RETURN json_build_object('success', true, 'status', 'registered');
END;
$$;

-- Function: reject_creator_claim
CREATE OR REPLACE FUNCTION public.reject_creator_claim(
    p_claim_id UUID,
    p_admin_id UUID,
    p_reason TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    -- Check permissions
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = p_admin_id 
        AND (role IN ('admin', 'secretary', 'lead_troll_officer') OR is_admin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Update Claim Status
    UPDATE public.creator_migration_claims
    SET verification_status = 'rejected',
        rejection_reason = p_reason,
        reviewed_by = p_admin_id,
        updated_at = NOW()
    WHERE id = p_claim_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: reject_document
CREATE OR REPLACE FUNCTION public.reject_document(
  p_document_id UUID,
  p_rejecter_id UUID,
  p_reason TEXT DEFAULT 'No reason provided',
  p_ip_address INET DEFAULT NULL,
  p_user_agent TEXT DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_document RECORD;
  v_rejecter RECORD;
BEGIN
  SELECT * INTO v_document FROM public.documents WHERE id = p_document_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Document not found');
  END IF;

  IF v_document.status NOT IN ('pending', 'draft') THEN
    RETURN json_build_object('success', false, 'error', 'Document cannot be rejected. Status: ' || v_document.status);
  END IF;

  SELECT * INTO v_rejecter FROM public.user_profiles WHERE id = p_rejecter_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'User not found');
  END IF;

  IF NOT (v_rejecter.is_admin = true OR v_rejecter.role IN ('admin', 'ceo', 'founder', 'owner', 'moderator', 'staff', 'lead_troll_officer')) THEN
    RETURN json_build_object('success', false, 'error', 'You do not have rejection privileges');
  END IF;

  INSERT INTO public.document_approvals (
    document_id, approver_id, approver_username, approver_role,
    approval_type, decision, comments
  ) VALUES (
    p_document_id, p_rejecter_id, v_rejecter.username, v_rejecter.role,
    'final', 'rejected', p_reason
  );

  UPDATE public.documents SET
    status = 'rejected',
    rejected_by = p_rejecter_id,
    rejected_at = now(),
    rejection_reason = p_reason,
    updated_at = now()
  WHERE id = p_document_id;

  PERFORM public.log_document_event(
    p_document_id, p_rejecter_id, v_rejecter.username, v_rejecter.role,
    'document_rejected',
    jsonb_build_object('reason', p_reason),
    p_ip_address, p_user_agent
  );

  RETURN json_build_object('success', true);
END;
$$;

-- Function: reject_family_agency_conversion
CREATE OR REPLACE FUNCTION public.reject_family_agency_conversion(
    p_application_id UUID,
    p_actor_id UUID,
    p_reason TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth, extensions
AS $$
DECLARE
    v_app public.agency_applications;
    v_actor_role TEXT;
    v_actor_is_hr BOOLEAN;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_actor_id THEN
        RAISE EXCEPTION 'Authentication required for the requesting actor';
    END IF;

    SELECT a.*
    INTO v_app
    FROM public.agency_applications a
    WHERE a.id = p_application_id
      AND a.status = 'pending'
      AND a.content_type = 'family_conversion'
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Family conversion request not found or already reviewed';
    END IF;

    SELECT lower(COALESCE(role, ''))
    INTO v_actor_role
    FROM public.user_profiles
    WHERE id = p_actor_id
    LIMIT 1;

    SELECT COALESCE((SELECT is_admin FROM public.user_profiles WHERE id = p_actor_id), false)
    INTO v_actor_is_hr;

    IF v_actor_is_hr IS NOT TRUE AND COALESCE(v_actor_role, '') NOT IN ('admin', 'agency hr manager', 'agency_hr_manager') THEN
        RAISE EXCEPTION 'You do not have permission to reject family conversion requests';
    END IF;

    UPDATE public.agency_applications
    SET status = 'denied',
        reviewed_by = p_actor_id,
        reviewed_at = NOW()
    WHERE id = p_application_id;

    INSERT INTO public.agency_enforcement_actions (
        agency_id,
        actor_id,
        target_user_id,
        action_type,
        reason,
        metadata
    )
    VALUES (
        v_app.agency_id,
        p_actor_id,
        v_app.applicant_id,
        'application_denied',
        COALESCE(nullif(btrim(p_reason), ''), 'Family conversion rejected'),
        jsonb_build_object('application_id', p_application_id, 'source', 'family_conversion')
    );

    INSERT INTO public.agency_activity_logs (
        agency_id,
        actor_id,
        target_user_id,
        action,
        metadata
    )
    VALUES (
        v_app.agency_id,
        p_actor_id,
        v_app.applicant_id,
        'family_conversion_rejected',
        jsonb_build_object('application_id', p_application_id, 'reason', COALESCE(nullif(btrim(p_reason), ''), 'Family conversion rejected'))
    );

    DELETE FROM public.agencies
    WHERE id = v_app.agency_id;

    RETURN jsonb_build_object(
        'success', true,
        'application_id', p_application_id,
        'agency_id', v_app.agency_id
    );
END;
$$;

-- Function: reject_president_candidate
create or replace function reject_president_candidate(p_candidate_id uuid)
returns void
security definer
language plpgsql
as $$
begin
  if not exists (select 1 from user_profiles where id = auth.uid() and (role = 'secretary' or is_admin = true)) then
    raise exception 'Not authorized';
  end if;

  update president_candidates
  set status = 'rejected'
  where id = p_candidate_id;
end;
$$;

-- Function: remove_stream_broadofficer
CREATE OR REPLACE FUNCTION public.remove_stream_broadofficer(
    p_stream_id  uuid,
    p_officer_id uuid
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_actor   uuid := auth.uid();
    v_owner   uuid;
    v_deleted integer := 0;
BEGIN
    IF v_actor IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    SELECT user_id INTO v_owner FROM public.streams WHERE id = p_stream_id;
    IF v_owner IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Stream not found');
    END IF;

    IF NOT public.is_stream_owner_or_admin(p_stream_id, v_actor) THEN
        RETURN jsonb_build_object('success', false, 'error', 'You do not control this stream');
    END IF;

    DELETE FROM public.broadcast_officers
        WHERE broadcaster_id = v_owner
          AND officer_id = p_officer_id
          AND stream_id = p_stream_id;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    RETURN jsonb_build_object('success', true, 'removed', v_deleted > 0);
END;
$$;

-- Function: rent_property
CREATE OR REPLACE FUNCTION public.rent_property(p_user_house_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_tenant_id UUID := auth.uid();
    v_house RECORD;
    v_rent_price BIGINT;
    v_paid BOOLEAN;
    v_rental_id UUID;
BEGIN
    SELECT * INTO v_house FROM public.user_houses WHERE id = p_user_house_id;
    
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'House not found'); END IF;
    
    -- Check if for rent
    IF NOT (v_house.feature_flags->>'is_for_rent')::boolean THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not for rent');
    END IF;
    
    v_rent_price := (v_house.feature_flags->>'rent_price')::bigint;
    
    -- Pay first month
    v_paid := public.try_pay_coins(v_tenant_id, v_rent_price, 'rent_payment', jsonb_build_object('house_id', p_user_house_id));
    
    IF v_paid THEN
        -- Create Rental Record
        INSERT INTO public.house_rentals (landlord_user_id, tenant_user_id, user_house_id, rent_amount, status, last_paid_at, next_due_at)
        VALUES (v_house.user_id, v_tenant_id, p_user_house_id, v_rent_price, 'active', NOW(), NOW() + INTERVAL '7 days') -- Weekly rent
        RETURNING id INTO v_rental_id;
        
        -- Pay Landlord (minus fee)
        -- Fee 10%
        PERFORM public.try_pay_coins(v_house.user_id, -1 * (v_rent_price * 0.9)::bigint, 'rent_income', jsonb_build_object('rental_id', v_rental_id));
        -- Note: try_pay_coins handles deduction. To GIVE coins, we pass negative amount?
        -- `try_pay_coins` implementation: `UPDATE ... SET troll_coins = troll_coins - p_amount`.
        -- So yes, negative amount ADDS coins.
        
        -- Unlist house
        UPDATE public.user_houses 
        SET feature_flags = feature_flags || jsonb_build_object('is_for_rent', false)
        WHERE id = p_user_house_id;

        RETURN jsonb_build_object('success', true, 'rental_id', v_rental_id);
    ELSE
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds');
    END IF;
END;
$$;

-- Function: request_friday_cashout
CREATE OR REPLACE FUNCTION public.request_friday_cashout(
    p_user_id UUID,
    p_coins_to_redeem BIGINT,
    p_provider_type TEXT,
    p_provider_username TEXT,
    p_user_tag TEXT DEFAULT NULL,
    p_id_verification_url TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user RECORD;
    v_available_coins BIGINT;
    v_tier RECORD;
    v_cash_amount NUMERIC(12,2);
    v_fee_amount NUMERIC(12,2) := 0;
    v_net_amount NUMERIC(12,2);
    v_payout_id UUID;
    v_last_approved_at TIMESTAMPTZ;
    v_now TIMESTAMPTZ := NOW();
    v_is_admin BOOLEAN := FALSE;
    v_is_cashout_approved BOOLEAN := FALSE;
BEGIN
    SELECT * INTO v_user
    FROM public.user_profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'User not found');
    END IF;

    v_is_admin := (
        v_user.role = 'admin'
        OR v_user.is_admin = TRUE
        OR v_user.is_superadmin = TRUE
        OR v_user.role = 'owner'
        OR v_user.role = 'ceo_assistant'
        OR v_user.role = 'noah_assistant'
        OR v_user.role = 'secretary'
        OR v_user.troll_role = 'admin'
    );

    v_is_cashout_approved := COALESCE(v_user.cashout_approved, false);

    IF v_user.role = 'troller' OR v_user.is_troller = TRUE OR v_user.troll_role = 'troller' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Trollers do not earn coins and cannot request cashouts.');
    END IF;

    IF NOT v_is_admin AND NOT v_is_cashout_approved THEN
        -- All approved users may request payouts through MAI Pay anytime; no weekend restriction.
    END IF;

    IF p_id_verification_url IS NULL AND NOT v_is_cashout_approved THEN
        SELECT created_at INTO v_last_approved_at
        FROM public.payout_requests
        WHERE user_id = p_user_id
          AND status IN ('approved', 'completed')
        ORDER BY created_at DESC
        LIMIT 1;

        IF NOT FOUND OR v_last_approved_at < (v_now - INTERVAL '30 days') THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Please upload a government-issued ID in your MAI Pay application before requesting cashouts.'
            );
        END IF;
    END IF;

    v_available_coins := COALESCE(v_user.cashout_coins, 0) - COALESCE(v_user.cashout_reserved_coins, 0);

    IF v_available_coins < p_coins_to_redeem THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Insufficient cashout coin balance. Please move eligible coins to Cashout Escrow first.',
            'available_coins', v_available_coins,
            'requested', p_coins_to_redeem
        );
    END IF;

    SELECT * INTO v_tier
    FROM public.cashout_tiers
    WHERE coin_amount <= p_coins_to_redeem
      AND is_active = TRUE
    ORDER BY coin_amount DESC
    LIMIT 1;

    IF NOT FOUND THEN
        SELECT * INTO v_tier
        FROM public.cashout_tiers
        WHERE is_active = TRUE
        ORDER BY coin_amount ASC
        LIMIT 1;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'No active cashout tiers configured.');
        END IF;
    END IF;

    v_cash_amount := v_tier.cash_amount;
    v_fee_amount := ROUND(p_coins_to_redeem * 0.029, 0);
    v_net_amount := v_cash_amount;

    UPDATE public.user_profiles
    SET cashout_reserved_coins = COALESCE(cashout_reserved_coins, 0) + p_coins_to_redeem,
        updated_at = v_now
    WHERE id = p_user_id;

    INSERT INTO public.payout_requests (
        user_id,
        coin_amount,
        cash_amount,
        net_amount,
        status,
        provider_type,
        provider_username,
        user_tag,
        id_verification_url,
        id_verification_uploaded_at,
        created_at,
        updated_at
    ) VALUES (
        p_user_id,
        p_coins_to_redeem,
        v_cash_amount,
        v_net_amount,
        'pending',
        p_provider_type,
        p_provider_username,
        p_user_tag,
        p_id_verification_url,
        CASE WHEN p_id_verification_url IS NOT NULL THEN v_now ELSE NULL END,
        v_now,
        v_now
    )
    RETURNING id INTO v_payout_id;

    RETURN jsonb_build_object(
        'success', true,
        'payout_id', v_payout_id,
        'coins_reserved', p_coins_to_redeem,
        'usd_amount', v_cash_amount,
        'fee_coins', v_fee_amount,
        'status', 'pending'
    );
END;
$$;

-- Function: request_marketplace_cancellation
CREATE OR REPLACE FUNCTION request_marketplace_cancellation(
  p_order_id uuid,
  p_reason text
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_purchase marketplace_purchases%ROWTYPE;
  v_minutes_since_purchase int;
BEGIN
  -- Get the purchase record
  SELECT * INTO v_purchase FROM marketplace_purchases WHERE id = p_order_id;
  
  IF v_purchase IS NULL THEN
    RETURN 'Order not found';
  END IF;

  -- Check if already cancelled or refunded
  IF v_purchase.status IN ('cancelled', 'refunded') THEN
    RETURN 'Order already cancelled or refunded';
  END IF;

  -- Check if already shipped
  IF v_purchase.status = 'shipped' THEN
    RETURN 'Cannot cancel shipped order';
  END IF;

  -- Check 30 minute window
  v_minutes_since_purchase := EXTRACT(EPOCH FROM (now() - v_purchase.created_at)) / 60;
  IF v_minutes_since_purchase > 30 THEN
    RETURN 'Cancellation window expired (30 minutes)';
  END IF;

  -- Update the order
  UPDATE marketplace_purchases
  SET cancellation_requested_at = now(),
      cancellation_reason = p_reason,
      status = 'cancelled',
      cancelled_at = now()
  WHERE id = p_order_id;

  -- Refund the buyer (this would need additional logic to actually refund coins)
  -- The actual refund logic would be handled by the application

  RETURN 'Cancellation requested successfully';
END;
$$;

-- Function: request_marketplace_payout_release
CREATE OR REPLACE FUNCTION request_marketplace_payout_release(
  p_order_id uuid,
  p_seller_id uuid,
  p_tracking_number text,
  p_carrier text DEFAULT 'usps',
  p_seller_notes text DEFAULT null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_order marketplace_purchases%ROWTYPE;
  v_existing_request uuid;
  v_completed_sales int;
  v_has_appeals boolean;
  v_tracking_url text;
  v_min_sales int := 10;
BEGIN
  -- Get order
  SELECT * INTO v_order FROM marketplace_purchases WHERE id = p_order_id;
  IF v_order IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  -- Verify seller owns this order
  IF v_order.seller_id != p_seller_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized for this order');
  END IF;

  -- Check order status
  IF v_order.payout_status != 'held' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payout is not in held status');
  END IF;

  -- Check if request already exists
  SELECT id INTO v_existing_request FROM marketplace_payout_release_requests
  WHERE order_id = p_order_id AND status IN ('pending', 'approved');
  IF v_existing_request IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'A pending or approved request already exists for this order');
  END IF;

  -- Gate: check seller's completed sales count (excluding this order)
  SELECT COUNT(*) INTO v_completed_sales FROM marketplace_purchases
  WHERE seller_id = p_seller_id
    AND status IN ('delivered', 'completed')
    AND id != p_order_id
    AND fulfillment_status NOT IN ('cancelled', 'refunded', 'lawsuit_filed');

  -- Gate: check for open appeals/lawsuits on seller's other orders
  SELECT EXISTS(
    SELECT 1 FROM marketplace_purchases mp
    WHERE mp.seller_id = p_seller_id
      AND mp.id != p_order_id
      AND (mp.appeal_id IS NOT NULL OR mp.troll_court_case_id IS NOT NULL)
  ) INTO v_has_appeals;

  -- Build tracking URL
  v_tracking_url := CASE p_carrier
    WHEN 'usps' THEN 'https://tools.usps.com/go/TrackConfirmAction?tLabels=' || p_tracking_number
    WHEN 'fedex' THEN 'https://www.fedex.com/fedextrack/?trknbr=' || p_tracking_number
    WHEN 'ups' THEN 'https://www.ups.com/track?tracknum=' || p_tracking_number
    WHEN 'dhl' THEN 'https://www.dhl.com/en/express/tracking.html?AWB=' || p_tracking_number
    ELSE null
  END;

  -- Insert request
  INSERT INTO marketplace_payout_release_requests (
    order_id, seller_id, tracking_number, carrier, tracking_url,
    seller_notes, completed_sales_count, has_open_appeals
  ) VALUES (
    p_order_id, p_seller_id, p_tracking_number, p_carrier, v_tracking_url,
    p_seller_notes, v_completed_sales, v_has_appeals
  );

  RETURN jsonb_build_object(
    'success', true,
    'request_created', true,
    'completed_sales', v_completed_sales,
    'has_open_appeals', v_has_appeals,
    'min_sales_required', v_min_sales
  );
END;
$$;

-- Function: request_payout
CREATE OR REPLACE FUNCTION request_payout(p_user_id uuid, p_coins_to_redeem bigint)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_user_profile record;
  v_min_payout bigint := 1000; -- Example limit
  v_conversion_rate numeric := 0.01; -- Example rate
  v_payout_amount numeric;
BEGIN
  -- Check admin or self
  IF auth.uid() != p_user_id THEN
     -- Allow admins? For now strict self
     RETURN json_build_object('success', false, 'error', 'Unauthorized');
  END IF;

  SELECT * INTO v_user_profile FROM user_profiles WHERE id = p_user_id;
  
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'User not found');
  END IF;

  -- CREDIT CARD BLOCK
  IF v_user_profile.credit_used > 0 THEN
    RETURN json_build_object('success', false, 'error', 'You must pay your Credit Card balance before requesting a cashout.');
  END IF;

  IF p_coins_to_redeem < v_min_payout THEN
    RETURN json_build_object('success', false, 'error', 'Minimum payout is ' || v_min_payout);
  END IF;

  IF v_user_profile.troll_coins < p_coins_to_redeem THEN
    RETURN json_build_object('success', false, 'error', 'Insufficient balance');
  END IF;

  -- Create payout request (Assuming payout_requests table exists from previous context)
  -- If not, we just log it. But typically there is a table.
  -- Based on 'run_missing_migrations.sql', we didn't see the table creation, but let's assume it exists or just return success mock for now if not found.
  -- Actually, let's try to insert if table exists.
  
  -- Deduct coins
  UPDATE user_profiles SET troll_coins = troll_coins - p_coins_to_redeem WHERE id = p_user_id;

  -- Insert request (Generic implementation)
  INSERT INTO public.payout_requests (user_id, coin_amount, status)
  VALUES (p_user_id, p_coins_to_redeem, 'pending');

  RETURN json_build_object('success', true, 'message', 'Payout requested');
EXCEPTION WHEN OTHERS THEN
  RETURN json_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: request_random_battle_rematch
CREATE OR REPLACE FUNCTION public.request_random_battle_rematch(
  p_battle_id uuid,
  p_stream_id uuid,
  p_broadcaster_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_battle public.battles%ROWTYPE;
  v_started_at timestamptz := now() + interval '10 seconds';
  v_ends_at timestamptz := now() + interval '3 minutes 10 seconds';
BEGIN
  SELECT *
    INTO v_battle
  FROM public.battles
  WHERE id = p_battle_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle not found');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.streams
    WHERE id = p_stream_id
      AND user_id = p_broadcaster_id
      AND battle_id = p_battle_id
      AND battle_mode = 'random_queue'
  ) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Unauthorized');
  END IF;

  UPDATE public.battles
  SET status = 'pending',
      started_at = v_started_at,
      ends_at = v_ends_at,
      ended_at = null,
      winner_stream_id = null,
      winner_id = null,
      score_challenger = 0,
      score_opponent = 0
  WHERE id = p_battle_id;

  UPDATE public.streams
  SET is_battle = true,
      battle_status = 'starting',
      battle_start_time = v_started_at,
      battle_end_time = v_ends_at,
      battle_end_reason = null,
      battle_winner_id = null,
      battle_forfeited_by = null,
      random_battle_cooldown_until = null
  WHERE battle_id = p_battle_id
    AND battle_mode = 'random_queue';

  RETURN jsonb_build_object('success', true, 'battle_started_at', v_started_at, 'battle_ends_at', v_ends_at);
END;
$$;

-- Function: request_stream_song
CREATE OR REPLACE FUNCTION public.request_stream_song(
  p_stream_id uuid,
  p_song_title text,
  p_artist text DEFAULT NULL,
  p_song_link text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_smoke_event record;
  v_stream record;
  v_balance integer;
  v_dj_credited boolean := false;
BEGIN
  v_user_id := auth.uid();

  SELECT * INTO v_smoke_event FROM public.stream_smoke_events
  WHERE stream_id = p_stream_id AND is_active = true AND song_queue_enabled = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Song queue not available for this stream');
  END IF;

  -- ATOMIC: Check balance AND deduct
  UPDATE public.user_profiles
  SET troll_coins = troll_coins - 10,
      total_spent_coins = COALESCE(total_spent_coins, 0) + 10,
      updated_at = now()
  WHERE id = v_user_id AND COALESCE(troll_coins, 0) >= 10;

  IF NOT FOUND THEN
    SELECT COALESCE(troll_coins, 0) INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    RETURN jsonb_build_object('success', false, 'error', 'Need 10 troll coins to request a song', 'balance', v_balance);
  END IF;

  -- Get stream host for admin pool
  SELECT * INTO v_stream FROM public.streams WHERE id = p_stream_id;

  -- Credit 5 coins to DJ if exists
  IF v_smoke_event.dj_user_id IS NOT NULL THEN
    UPDATE public.user_profiles
    SET troll_coins = COALESCE(troll_coins, 0) + 5,
        total_earned_coins = COALESCE(total_earned_coins, 0) + 5,
        updated_at = now()
    WHERE id = v_smoke_event.dj_user_id;
    v_dj_credited := true;
  END IF;

  -- Credit 5 coins to stream host (admin pool) - always, even if same as DJ
  IF v_stream.user_id IS NOT NULL THEN
    UPDATE public.user_profiles
    SET troll_coins = COALESCE(troll_coins, 0) + 5,
        total_earned_coins = COALESCE(total_earned_coins, 0) + 5,
        updated_at = now()
    WHERE id = v_stream.user_id;
  END IF;

  INSERT INTO public.stream_song_requests (stream_id, requested_by, dj_user_id, song_title, artist, song_link)
  VALUES (p_stream_id, v_user_id, v_smoke_event.dj_user_id, p_song_title, p_artist, p_song_link);

  SELECT COALESCE(troll_coins, 0) INTO v_balance FROM public.user_profiles WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Song request submitted!',
    'cost', 10,
    'new_balance', v_balance
  );
END;
$$;

-- Function: reserve_auction_inventory
CREATE OR REPLACE FUNCTION reserve_auction_inventory(
  p_source_lot_id uuid,
  p_dest_lot_id uuid,
  p_show_id uuid,
  p_qty integer
)
RETURNS jsonb
AS $$
DECLARE
  v_src auction_lots%ROWTYPE;
  v_reserved integer;
  v_available integer;
BEGIN
  IF p_qty IS NULL OR p_qty < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Quantity must be at least 1');
  END IF;

  -- Lock the source row so concurrent reservations serialize.
  SELECT * INTO v_src FROM auction_lots WHERE id = p_source_lot_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Source inventory item not found');
  END IF;

  -- Only the owning auctioneer may reserve.
  IF NOT is_show_auctioneer(v_src.auction_show_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized to reserve this inventory');
  END IF;

  -- Already reserved for this destination? Return current state (idempotent).
  SELECT quantity_reserved INTO v_reserved
  FROM auction_lots WHERE id = p_dest_lot_id;

  v_available := GREATEST(0, v_src.quantity_total - v_src.quantity_reserved - v_src.quantity_sold);

  IF v_reserved IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Destination lot not found');
  END IF;

  IF v_reserved >= p_qty THEN
    RETURN jsonb_build_object(
      'success', true, 'already_reserved', true,
      'reserved', v_reserved, 'available', v_available
    );
  END IF;

  IF v_available < p_qty THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Not enough available stock',
      'available', v_available, 'requested', p_qty
    );
  END IF;

  -- Reserve on the source, reflect on the destination.
  UPDATE auction_lots
  SET quantity_reserved = quantity_reserved + p_qty,
      quantity_available = GREATEST(0, quantity_total - quantity_reserved - p_qty - quantity_sold),
      updated_at = now()
  WHERE id = p_source_lot_id;

  UPDATE auction_lots
  SET quantity_reserved = p_qty,
      updated_at = now()
  WHERE id = p_dest_lot_id;

  RETURN jsonb_build_object(
    'success', true,
    'reserved', p_qty,
    'available', GREATEST(0, v_src.quantity_total - v_src.quantity_reserved - p_qty - v_src.quantity_sold)
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 6. Restore reservation when an item is removed from a show or the show is
--    cancelled. Returns reserved units back to available on the source.
CREATE OR REPLACE FUNCTION restore_auction_inventory_reservation(
  p_source_lot_id uuid,
  p_dest_lot_id uuid
)
RETURNS jsonb
AS $$
DECLARE
  v_reserved integer := 0;
BEGIN
  SELECT quantity_reserved INTO v_reserved FROM auction_lots WHERE id = p_dest_lot_id FOR UPDATE;
  IF v_reserved IS NULL OR v_reserved <= 0 THEN
    RETURN jsonb_build_object('success', true, 'restored', 0);
  END IF;

  UPDATE auction_lots
  SET quantity_reserved = GREATEST(0, quantity_reserved - v_reserved),
      quantity_available = GREATEST(0, quantity_total - GREATEST(0, quantity_reserved - v_reserved) - quantity_sold),
      updated_at = now()
  WHERE id = p_source_lot_id;

  UPDATE auction_lots
  SET quantity_reserved = 0, updated_at = now()
  WHERE id = p_dest_lot_id;

  RETURN jsonb_build_object('success', true, 'restored', v_reserved);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 7. Move reserved -> sold after a successful sale, and restore any remaining
--    unsold reserved units. Called from mark_lot_sold / the create-order path.
CREATE OR REPLACE FUNCTION finalize_auction_inventory_sale(
  p_source_lot_id uuid,
  p_dest_lot_id uuid,
  p_sold_qty integer
)
RETURNS jsonb
AS $$
DECLARE
  v_reserved integer := 0;
  v_sold integer := 0;
  v_restore integer := 0;
BEGIN
  SELECT quantity_reserved, quantity_sold INTO v_reserved, v_sold
  FROM auction_lots WHERE id = p_dest_lot_id FOR UPDATE;

  v_sold := GREATEST(0, p_sold_qty);
  v_restore := GREATEST(0, v_reserved - v_sold);

  -- Source: reserved decreases by sold units; available increases by restored.
  UPDATE auction_lots
  SET quantity_reserved = GREATEST(0, quantity_reserved - LEAST(v_reserved, v_sold + v_restore)),
      quantity_sold = quantity_sold + v_sold,
      quantity_available = GREATEST(0, quantity_total - GREATEST(0, quantity_reserved - LEAST(v_reserved, v_sold + v_restore)) - (quantity_sold + v_sold)),
      updated_at = now()
  WHERE id = p_source_lot_id;

  -- Destination: record sold; clear reservation (already covered by source math).
  UPDATE auction_lots
  SET quantity_sold = quantity_sold + v_sold,
      quantity_reserved = GREATEST(0, quantity_reserved - (v_sold + v_restore)),
      quantity_available = GREATEST(0, quantity_total - GREATEST(0, quantity_reserved - (v_sold + v_restore)) - (quantity_sold + v_sold)),
      updated_at = now()
  WHERE id = p_dest_lot_id;

  RETURN jsonb_build_object('success', true, 'sold', v_sold, 'restored', v_restore);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 8. Trigger: keep quantity_available consistent whenever reserved/sold change
--    as a safety net (the functions above already maintain it).
CREATE OR REPLACE FUNCTION trg_auction_lot_qty_sync()
RETURNS TRIGGER
AS $$
BEGIN
  NEW.quantity_available := GREATEST(0,
    NEW.quantity_total - GREATEST(0, NEW.quantity_reserved) - GREATEST(0, NEW.quantity_sold));
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_auction_lot_qty_sync ON auction_lots;
CREATE TRIGGER trigger_auction_lot_qty_sync
  BEFORE UPDATE ON auction_lots
  FOR EACH ROW
  WHEN (NEW.quantity_reserved IS DISTINCT FROM OLD.quantity_reserved
        OR NEW.quantity_sold IS DISTINCT FROM OLD.quantity_sold
        OR NEW.quantity_total IS DISTINCT FROM OLD.quantity_total)
  EXECUTE FUNCTION trg_auction_lot_qty_sync();

-- 9. Grants
GRANT EXECUTE ON FUNCTION reserve_auction_inventory(uuid, uuid, uuid, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION restore_auction_inventory_reservation(uuid, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION finalize_auction_inventory_sale(uuid, uuid, integer) TO authenticated;

-- 10. Realtime: expose auction_lots quantity changes to live clients.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname='public' AND tablename='auction_lots')
     AND NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND tablename='auction_lots') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE auction_lots;
  END IF;
END $$;

-- Function: reset_troll_coins
CREATE OR REPLACE FUNCTION public.reset_troll_coins(
    p_user_id UUID,
    p_new_balance BIGINT DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_old_balance BIGINT;
BEGIN
    -- Check if caller is admin
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = auth.uid() AND is_admin = true
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Admin access required');
    END IF;

    -- Get old balance
    SELECT troll_coins INTO v_old_balance
    FROM public.user_profiles
    WHERE id = p_user_id;

    IF v_old_balance IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'User profile not found');
    END IF;

    -- Reset balance
    UPDATE public.user_profiles
    SET troll_coins = p_new_balance,
        updated_at = now()
    WHERE id = p_user_id;

    -- Log the reset
    INSERT INTO public.coin_ledger (user_id, delta, bucket, source, ref_id, metadata, direction)
    VALUES (
        p_user_id,
        p_new_balance - v_old_balance,
        'admin',
        'admin_reset',
        p_user_id::text,
        jsonb_build_object('admin_id', auth.uid(), 'old_balance', v_old_balance, 'new_balance', p_new_balance),
        'in'
    );

    RETURN jsonb_build_object(
        'success', true,
        'user_id', p_user_id,
        'old_balance', v_old_balance,
        'new_balance', p_new_balance
    );
END;
$$;

-- Function: reset_user_permissions
CREATE OR REPLACE FUNCTION public.reset_user_permissions(p_target_user_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.require_admin();

  UPDATE user_profiles
  SET
    role = 'user',
    is_troll_officer = false,
    is_lead_officer = false,
    is_prosecutor = false,
    is_attorney = false,
    is_secretary = false,
    troll_role = NULL,
    officer_level = 0,
    updated_at = now()
  WHERE id = p_target_user_id;
END;
$$;

-- Function: resolve_security_event
CREATE OR REPLACE FUNCTION public.resolve_security_event(
            p_event_id uuid,
            p_status text,
            p_note text DEFAULT NULL
        )
        RETURNS void AS $$
        DECLARE
            v_metadata jsonb;
        BEGIN
            -- Get existing metadata
            SELECT metadata INTO v_metadata
            FROM public.security_events
            WHERE id = p_event_id;

            IF v_metadata IS NULL THEN
                v_metadata := '{}'::jsonb;
            END IF;

            -- Update the event
            UPDATE public.security_events
            SET
                status = p_status,
                reviewed_by = auth.uid(), -- Assuming the caller is the admin performing the action
                reviewed_at = now(),
                resolved_at = CASE 
                    WHEN p_status IN ('resolved', 'ignored', 'false_positive') THEN now()
                    ELSE NULL
                END,
                metadata = jsonb_set(
                    COALESCE(metadata, '{}'::jsonb),
                    '{review_notes}',
                    COALESCE(metadata->'review_notes', '[]'::jsonb) || to_jsonb(p_note)::jsonb,
                    true
                )
            WHERE id = p_event_id;
        END;
        $$ LANGUAGE plpgsql SECURITY DEFINER;
    END IF;
END $$;

-- Function: restore_banned_account
CREATE OR REPLACE FUNCTION restore_banned_account()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id uuid := auth.uid();
    v_coins bigint;
    v_cost bigint := 2000;
BEGIN
    -- Get current coins
    SELECT coins INTO v_coins
    FROM user_profiles
    WHERE id = v_user_id;

    IF v_coins IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'User profile not found');
    END IF;

    IF v_coins < v_cost THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient coins');
    END IF;

    -- Deduct coins and unban
    -- Reset logic: User pays 2000 to unban, but loses everything (UI requirement)
    UPDATE user_profiles
    SET 
        coins = 0,
        xp = 0,
        level = 0, -- Assuming level column exists, otherwise ignore
        is_banned = false,
        ban_expires_at = null
    WHERE id = v_user_id;

    -- Log event
    INSERT INTO audit_logs (action, user_id, details)
    VALUES ('account_restored', v_user_id, jsonb_build_object('cost', v_cost));

    RETURN jsonb_build_object('success', true, 'message', 'Account restored');
END;
$$;

-- Function: review_appeal
CREATE OR REPLACE FUNCTION review_appeal(
    p_appeal_id UUID,
    p_reviewer_id UUID,
    p_new_status appeal_status,
    p_review_notes TEXT DEFAULT NULL,
    p_action TEXT DEFAULT 'status_changed'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_appeal RECORD;
    v_previous_status TEXT;
BEGIN
    -- Get current appeal
    SELECT * INTO v_appeal FROM public.transaction_appeals WHERE id = p_appeal_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Appeal not found');
    END IF;
    
    v_previous_status := v_appeal.status;
    
    -- Update appeal
    UPDATE public.transaction_appeals
    SET status = p_new_status,
        reviewer_id = p_reviewer_id,
        reviewed_at = NOW(),
        review_notes = p_review_notes,
        updated_at = NOW()
    WHERE id = p_appeal_id;
    
    -- Handle escrow based on decision
    IF p_new_status = 'approved' AND v_appeal.escrow_release_status = 'held' THEN
        -- Refund to buyer
        UPDATE public.shop_orders
        SET escrow_status = 'refunded', delivery_status = 'returned', updated_at = NOW()
        WHERE id = v_appeal.order_id;
        
        UPDATE public.transaction_appeals
        SET escrow_release_status = 'refunded'
        WHERE id = p_appeal_id;
        
    ELSIF p_new_status = 'denied' AND v_appeal.escrow_release_status = 'held' THEN
        -- Release to seller
        UPDATE public.shop_orders
        SET escrow_status = 'released', delivery_status = 'delivered', delivered_at = NOW(), updated_at = NOW()
        WHERE id = v_appeal.order_id;
        
        UPDATE public.transaction_appeals
        SET escrow_release_status = 'released'
        WHERE id = p_appeal_id;
    END IF;
    
    -- Log the action
    INSERT INTO public.appeal_actions (appeal_id, user_id, action_type, previous_status, new_status, notes)
    VALUES (p_appeal_id, p_reviewer_id, p_action, v_previous_status, p_new_status, p_review_notes);
    
    RETURN jsonb_build_object(
        'success', true,
        'message', 'Appeal reviewed successfully',
        'previous_status', v_previous_status,
        'new_status', p_new_status
    );
END;
$$;

-- Function: review_fast_pay_application
CREATE OR REPLACE FUNCTION public.review_fast_pay_application(
  p_application_id uuid,
  p_new_status text,
  p_admin_notes text DEFAULT null,
  p_rejection_reason text DEFAULT null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_app fast_pay_applications;
  v_admin_id uuid := auth.uid();
BEGIN
  IF v_admin_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = v_admin_id
    AND role IN ('admin', 'superadmin', 'secretary')
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: admin role required');
  END IF;

  SELECT * INTO v_app FROM public.fast_pay_applications WHERE id = p_application_id;
  IF v_app IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application not found');
  END IF;

  IF v_app.status NOT IN ('pending', 'under_review') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application is not in a reviewable state');
  END IF;

  IF p_new_status NOT IN ('approved', 'rejected', 'under_review') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid status');
  END IF;

  UPDATE public.fast_pay_applications
  SET status = p_new_status,
      reviewed_by = v_admin_id,
      reviewed_at = now(),
      admin_notes = p_admin_notes,
      rejection_reason = CASE WHEN p_new_status = 'rejected' THEN COALESCE(p_rejection_reason, '') ELSE admin_notes END,
      updated_at = now()
  WHERE id = p_application_id;

  IF p_new_status = 'approved' THEN
    UPDATE public.user_profiles
    SET cashout_approved = true,
        cashout_approved_at = now(),
        updated_at = now()
    WHERE id = v_app.user_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', CASE
      WHEN p_new_status = 'approved' THEN 'Fast Pay application approved'
      WHEN p_new_status = 'rejected' THEN 'Fast Pay application rejected'
      ELSE 'Application marked as under review'
    END
  );
END;
$$;

-- Function: rollback_moderation_action
CREATE OR REPLACE FUNCTION public.rollback_moderation_action(
    p_log_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_log RECORD;
    v_mod_id UUID := auth.uid();
BEGIN
    -- Check permissions
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles 
        WHERE id = v_mod_id 
        AND (role IN ('admin', 'lead_troll_officer') OR is_admin = true)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    SELECT * INTO v_log FROM public.moderation_logs WHERE id = p_log_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Log not found');
    END IF;

    IF v_log.action_type = 'ban' THEN
        UPDATE public.user_profiles SET is_banned = false, ban_expires_at = NULL WHERE id = v_log.target_user_id;
    ELSIF v_log.action_type = 'mute' THEN
        UPDATE public.user_profiles SET is_muted = false, mute_expires_at = NULL WHERE id = v_log.target_user_id;
    END IF;
    
    INSERT INTO public.moderation_logs (moderator_id, target_user_id, action_type, reason, metadata)
    VALUES (v_mod_id, v_log.target_user_id, 'rollback', 'Rolled back action ' || p_log_id, jsonb_build_object('original_log_id', p_log_id));

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: rotate_ad_queue
CREATE OR REPLACE FUNCTION public.rotate_ad_queue(p_force BOOLEAN DEFAULT false)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_next_ad UUID;
    v_current_active UUID;
    v_current_slot_start TIMESTAMP WITH TIME ZONE;
    v_rotation_count INT := 0;
    v_should_rotate BOOLEAN := false;
BEGIN
    -- Check for active ads
    SELECT id, slot_start_time INTO v_current_active, v_current_slot_start
    FROM public.user_advertisements
    WHERE status = 'active'
    ORDER BY slot_start_time ASC
    LIMIT 1;

    -- Determine if we should rotate
    IF p_force THEN
        v_should_rotate := TRUE;
    ELSIF v_current_active IS NULL THEN
        v_should_rotate := TRUE;
    ELSIF v_current_slot_start < (NOW() - INTERVAL '7 days') THEN
        v_should_rotate := TRUE;
    END IF;

    IF v_should_rotate THEN
        -- Mark current active ad as queued (if any)
        IF v_current_active IS NOT NULL THEN
            UPDATE public.user_advertisements
            SET status = 'queued', is_active_slot = false
            WHERE id = v_current_active;

            v_rotation_count := v_rotation_count + 1;
        END IF;

        -- Get next ad in queue
        SELECT id INTO v_next_ad
        FROM public.user_advertisements
        WHERE status = 'queued'
        ORDER BY queue_position ASC NULLS LAST, approved_at ASC
        LIMIT 1;

        IF v_next_ad IS NOT NULL THEN
            -- Activate next ad
            UPDATE public.user_advertisements
            SET 
                status = 'active', 
                is_active_slot = true,
                slot_start_time = NOW()
            WHERE id = v_next_ad;

            v_rotation_count := v_rotation_count + 1;
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 
        'rotations_performed', v_rotation_count,
        'current_active_ad', v_current_active,
        'next_active_ad', v_next_ad
    );
END;
$$;

-- Function: run_employee_payroll
create or replace function public.run_employee_payroll(
  p_period_start date,
  p_period_end date,
  p_actor uuid
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  v_run uuid;
  v_rec record;
  v_perk numeric;
  v_hours numeric;
  v_rate numeric;
  v_gross numeric;
  v_fed numeric;
  v_state numeric;
  v_fica numeric;
  v_medicare numeric;
  v_net numeric;
begin
  if not public.employee_can(p_actor, 'edit_payroll') then
    raise exception 'unauthorized';
  end if;

  insert into public.employee_payroll_runs (period_start, period_end, status, created_by)
  values (p_period_start, p_period_end, 'approved', p_actor)
  returning id into v_run;

  for v_rec in
    select up.id as user_id, up.role, er.location_city, er.location_state
    from user_profiles up
    left join employee_records er on er.user_id = up.id
    where coalesce((select employment_status from employee_records where user_id = up.id), 'active') = 'active'
      and up.role in (
        'troll_officer','lead_troll_officer','secretary','ceo_assistant','noah_assistant',
        'ceo','ceo','pastor','attorney','prosecutor','journalist','auctioneer','troller',
        'agency_hr_manager','agency_leader','agency_hr','hr_admin','hr_manager','president',
        'vice_president','troll_city_secretary','troll_city_treasurer','executive_secretary',
        'academy_teacher','admissions_officer'
      )
  loop
    select coalesce(amount,0) into v_perk from employee_perk_pay where role = v_rec.role;
    v_rate := v_perk;

    select coalesce(sum(
      extract(epoch from (coalesce(clock_out, now()) - clock_in)) / 3600.0), 0)
      into v_hours
    from officer_work_sessions
    where officer_id = v_rec.user_id
      and clock_in::date between p_period_start and p_period_end;

    v_gross := round((v_hours * v_rate)::numeric, 2);
    v_fed := round((v_gross * 0.12)::numeric, 2);
    v_state := round((v_gross * 0.05)::numeric, 2);
    v_fica := round((v_gross * 0.062)::numeric, 2);
    v_medicare := round((v_gross * 0.0145)::numeric, 2);
    v_net := round((v_gross - v_fed - v_state - v_fica - v_medicare)::numeric, 2);

    insert into public.employee_paystubs
      (run_id, user_id, pay_period_start, pay_period_end, pay_date, hours, rate,
       gross_pay, federal_tax, state_tax, fica, medicare, net_pay, location_city, location_state)
    values (v_run, v_rec.user_id, p_period_start, p_period_end, p_period_end + interval '3 days',
       v_hours, v_rate, v_gross, v_fed, v_state, v_fica, v_medicare, v_net,
       v_rec.location_city, v_rec.location_state);
  end loop;

  return v_run;
end;
$$;

-- Function: sell_all_houses_to_bank
CREATE OR REPLACE FUNCTION public.sell_all_houses_to_bank()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_house RECORD;
    v_admin_id UUID;
    v_admin_pool_id UUID;
    
    v_price BIGINT;
    v_third BIGINT;
    
    v_total_seller_share BIGINT := 0;
    v_total_admin_pool_share BIGINT := 0;
    v_count INTEGER := 0;
    
    v_house_price BIGINT;
    v_house_seller_share BIGINT;
    v_house_admin_share BIGINT;
BEGIN
    -- Get Admin ID (Bank Admin)
    SELECT id INTO v_admin_id 
    FROM public.user_profiles 
    WHERE role = 'admin' OR is_admin = true 
    ORDER BY created_at ASC 
    LIMIT 1;
    
    IF v_admin_id IS NULL THEN
        -- Fallback to any admin or system user if specific bank admin not found
        SELECT id INTO v_admin_id FROM auth.users LIMIT 1;
    END IF;

    IF v_admin_id IS NULL THEN
        RAISE EXCEPTION 'Bank admin not found';
    END IF;

    -- Iterate through all properties owned by the user
    FOR v_house IN 
        SELECT * FROM public.properties 
        WHERE owner_user_id = auth.uid()
    LOOP
        -- Calculate Price (Logic matches sell_house_to_bank)
        v_house_price := COALESCE(v_house.base_value, 0);
        
        IF v_house_price <= 0 THEN
           v_house_price := COALESCE(v_house.ask_price, 0);
        END IF;
        
        IF v_house_price <= 0 THEN
            IF v_house.is_starter THEN
                 v_house_price := 1500;
            ELSE
                 -- Skip worthless properties or default to 0? 
                 -- Existing RPC raises exception. We'll skip or set to 0 to avoid breaking the batch.
                 v_house_price := 0;
            END IF;
        END IF;

        IF v_house_price > 0 THEN
            v_third := FLOOR(v_house_price / 3);
            v_house_seller_share := v_third;
            v_house_admin_share := v_house_price - v_house_seller_share; -- The rest (2/3) goes to pool/bank logic implies 2/3 to pool?
            -- Wait, sell_house_to_bank says:
            -- v_seller_share := v_third; (1/3)
            -- v_admin_pool_share_1 := v_third;
            -- v_admin_pool_share_2 := v_price - v_seller_share - v_admin_pool_share_1;
            -- v_admin_pool_total := v_admin_pool_share_1 + v_admin_pool_share_2; (Which is 2/3)
            
            v_total_seller_share := v_total_seller_share + v_house_seller_share;
            v_total_admin_pool_share := v_total_admin_pool_share + v_house_admin_share;
            v_count := v_count + 1;
        END IF;
    END LOOP;

    IF v_count = 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'No eligible properties to sell');
    END IF;

    -- Credit Seller
    PERFORM public.troll_bank_credit_coins(
        auth.uid(),
        v_total_seller_share::INT,
        'paid', 
        'property_sale_bulk',
        'bulk_sale_' || NOW()::TEXT
    );

    -- Credit Admin Pool
    SELECT id INTO v_admin_pool_id FROM public.admin_pool LIMIT 1;

    IF v_admin_pool_id IS NOT NULL THEN
        UPDATE public.admin_pool
        SET trollcoins_balance = COALESCE(trollcoins_balance, 0) + v_total_admin_pool_share,
            updated_at = NOW()
        WHERE id = v_admin_pool_id;
    ELSE
         -- Should exist due to previous migration, but safe fallback
         INSERT INTO public.admin_pool (user_id, trollcoins_balance)
         VALUES (v_admin_id, v_total_admin_pool_share);
    END IF;

    -- Log to Ledger
    INSERT INTO public.admin_pool_ledger (amount, reason, ref_user_id, created_at)
    VALUES (
        v_total_admin_pool_share,
        'Bulk Property Sale Profit (2x33.3% to Admin Pool) - ' || v_count || ' homes',
        auth.uid(),
        NOW()
    );

    -- Transfer Properties
    UPDATE public.properties
    SET owner_user_id = v_admin_id,
        is_listed = false,
        is_active_home = false,
        updated_at = NOW()
    WHERE owner_user_id = auth.uid();

    RETURN jsonb_build_object(
        'success', true,
        'count', v_count,
        'total_seller_share', v_total_seller_share,
        'total_admin_share', v_total_admin_pool_share
    );
END;
$$;

-- Function: sell_house_to_bank
CREATE OR REPLACE FUNCTION public.sell_house_to_bank(
    house_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_house RECORD;
    v_seller_id UUID;
    v_admin_id UUID;
    v_price BIGINT;
    v_third BIGINT;
    v_seller_share BIGINT;
    v_admin_pool_share_1 BIGINT;
    v_admin_pool_share_2 BIGINT;
    v_admin_pool_total BIGINT;
    v_admin_pool_id UUID;
BEGIN
    -- Get House Details
    SELECT * INTO v_house FROM public.properties WHERE id = house_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Property not found';
    END IF;

    v_seller_id := v_house.owner_user_id;
    
    IF v_seller_id <> auth.uid() THEN
        RAISE EXCEPTION 'You do not own this property';
    END IF;

    -- Get Admin ID (Bank Admin) - Exclude current user
    SELECT id INTO v_admin_id 
    FROM public.user_profiles 
    WHERE (role = 'admin' OR is_admin = true)
    AND id != auth.uid()
    ORDER BY created_at ASC 
    LIMIT 1;
    
    IF v_admin_id IS NULL THEN
         -- Fallback: Try to find ANY other user (oldest non-me user) to act as bank holder
         SELECT id INTO v_admin_id 
         FROM public.user_profiles 
         WHERE id != auth.uid()
         ORDER BY created_at ASC 
         LIMIT 1;
    END IF;

    IF v_admin_id IS NULL THEN
        RAISE EXCEPTION 'Bank admin/user not found (cannot sell to yourself)';
    END IF;

    -- Calculate Values
    v_price := COALESCE(v_house.base_value, 0);
    
    IF v_price <= 0 THEN
       v_price := COALESCE(v_house.ask_price, 0);
    END IF;
    
    IF v_price <= 0 THEN
        IF v_house.is_starter THEN
             v_price := 1500;
        ELSE
             RAISE EXCEPTION 'Property has no value';
        END IF;
    END IF;

    v_third := FLOOR(v_price / 3);
    v_seller_share := v_third;
    v_admin_pool_share_1 := v_third;
    v_admin_pool_share_2 := v_price - v_seller_share - v_admin_pool_share_1;
    v_admin_pool_total := v_admin_pool_share_1 + v_admin_pool_share_2;

    -- Pay Seller (1/3)
    PERFORM public.troll_bank_credit_coins(
        v_seller_id,
        v_seller_share::INT,
        'paid', 
        'property_sale_seller',
        house_id::TEXT
    );

    -- Ensure Admin Pool Exists
    SELECT id INTO v_admin_pool_id FROM public.admin_pool LIMIT 1;

    IF v_admin_pool_id IS NULL THEN
        -- Create pool owned by the bank admin
        INSERT INTO public.admin_pool (user_id, trollcoins_balance)
        VALUES (v_admin_id, 0)
        RETURNING id INTO v_admin_pool_id;
    END IF;

    -- Update Admin Pool (2/3)
    UPDATE public.admin_pool
    SET trollcoins_balance = COALESCE(trollcoins_balance, 0) + v_admin_pool_total,
        updated_at = NOW()
    WHERE id = v_admin_pool_id;

    -- Log to Ledger
    INSERT INTO public.admin_pool_ledger (amount, reason, ref_user_id, created_at)
    VALUES (
        v_admin_pool_total,
        'Property Sale Profit (2x33.3% to Admin Pool) - House ' || house_id,
        v_seller_id,
        NOW()
    );

    -- Transfer Property
    UPDATE public.properties
    SET owner_user_id = v_admin_id,
        is_listed = false,
        is_active_home = false,
        updated_at = NOW()
    WHERE id = house_id;

    RETURN jsonb_build_object(
        'success', true,
        'seller_share', v_seller_share,
        'admin_pool_share_1', v_admin_pool_share_1,
        'admin_pool_share_2', v_admin_pool_share_2
    );
END;
$$;

-- Function: sell_vehicle
CREATE OR REPLACE FUNCTION public.sell_vehicle(p_user_vehicle_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_vehicle RECORD;
    v_catalog RECORD;
    v_sell_price INTEGER;
    v_restocked BOOLEAN;
BEGIN
    v_user_id := auth.uid();
    
    -- Check authentication
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Not authenticated');
    END IF;

    -- Get vehicle and verify ownership
    SELECT * INTO v_vehicle FROM public.user_vehicles 
    WHERE id = p_user_vehicle_id AND user_id = v_user_id;
    
    IF v_vehicle IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Vehicle not found or not owned by you');
    END IF;

    -- Get catalog details for pricing
    SELECT * INTO v_catalog FROM public.vehicles_catalog WHERE id = v_vehicle.catalog_id;
    
    -- Calculate sell price (50% of base price)
    v_sell_price := FLOOR(v_catalog.price * 0.5);

    -- Restock dealership if model is still active
    v_restocked := public.dealership_increment_inventory('KTAuto', v_vehicle.catalog_id, 1);

    -- Delete vehicle (Cascades to titles, registrations, insurance due to FK constraints)
    DELETE FROM public.user_vehicles WHERE id = p_user_vehicle_id;

    -- Add Coins
    UPDATE public.user_profiles 
    SET troll_coins = troll_coins + v_sell_price 
    WHERE id = v_user_id;

    -- Log Transaction
    INSERT INTO public.vehicle_transactions (user_id, type, amount, details)
    VALUES (
        v_user_id, 
        'sale', 
        v_sell_price, 
        jsonb_build_object(
            'vehicle_id', p_user_vehicle_id,
            'catalog_id', v_vehicle.catalog_id,
            'car_name', v_catalog.name,
            'reason', 'User sold to dealer',
            'restocked', v_restocked
        )
    );

    -- Coin Transaction Log
    INSERT INTO public.coin_transactions (user_id, amount, type, description)
    VALUES (
        v_user_id, 
        v_sell_price, 
        'sale', 
        'Sold ' || v_catalog.name || ' to KTAuto'
    );

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Vehicle sold for ' || v_sell_price || ' coins',
        'amount', v_sell_price,
        'restocked', v_restocked
    );
END;
$$;

-- Function: sell_vehicle_asset
CREATE OR REPLACE FUNCTION public.sell_vehicle_asset(
  p_asset_id UUID,
  p_user_id UUID DEFAULT auth.uid()
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_asset RECORD;
  v_buyback_value NUMERIC;
  v_catalog_name TEXT;
BEGIN
  -- Validate user
  IF p_user_id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Authentication required');
  END IF;

  -- Set bypass flag for coin protection trigger
  PERFORM set_config('app.bypass_coin_protection', 'true', true);

  -- Get user's vehicle asset
  SELECT * INTO v_asset
  FROM public.user_vehicle_assets
  WHERE id = p_asset_id AND user_id = p_user_id AND status = 'owned';

  IF v_asset IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Vehicle not found or already sold');
  END IF;

  -- Get catalog name (use stored name if catalog deleted)
  SELECT name INTO v_catalog_name
  FROM public.vehicle_catalog
  WHERE id = v_asset.catalog_id;

  IF v_catalog_name IS NULL THEN
    v_catalog_name := v_asset.vehicle_name;
  END IF;

  -- Calculate buyback value
  v_buyback_value := ROUND(v_asset.purchase_price * v_asset.buyback_percentage / 100);

  -- Update asset status
  UPDATE public.user_vehicle_assets
  SET
    status = 'sold',
    sold_at = now(),
    sale_price = v_buyback_value
  WHERE id = p_asset_id;

  -- Add coins to user
  UPDATE public.user_profiles
  SET troll_coins = troll_coins + v_buyback_value
  WHERE id = p_user_id;

  -- Record transaction
  INSERT INTO public.vehicle_transactions (
    user_id,
    catalog_id,
    asset_id,
    transaction_type,
    vehicle_name,
    amount,
    metadata
  ) VALUES (
    p_user_id,
    v_asset.catalog_id,
    p_asset_id,
    'sale',
    v_catalog_name,
    v_buyback_value,
    jsonb_build_object(
      'purchase_price', v_asset.purchase_price,
      'buyback_value', v_buyback_value,
      'buyback_percentage', v_asset.buyback_percentage,
      'profit_loss', v_buyback_value - v_asset.purchase_price
    )
  );

  RETURN json_build_object(
    'success', true,
    'vehicle_name', v_catalog_name,
    'purchase_price', v_asset.purchase_price,
    'buyback_value', v_buyback_value,
    'buyback_percentage', v_asset.buyback_percentage
  );
END;
$$;

-- Function: send_ar_gift
CREATE OR REPLACE FUNCTION send_ar_gift(
  p_sender_id UUID,
  p_receiver_id UUID,
  p_stream_id UUID DEFAULT NULL,
  p_battle_id UUID DEFAULT NULL,
  p_gift_id TEXT DEFAULT NULL,
  p_quantity INTEGER DEFAULT 1
)
RETURNS JSON
LANGUAGE plpgsql
AS $$
DECLARE
  v_gift RECORD;
  v_total_cost INTEGER;
  v_sender_coins INTEGER;
  v_transaction_id UUID;
  v_duration_ms INTEGER;
BEGIN
  -- Get gift details
  SELECT * INTO v_gift FROM gift_items WHERE gift_slug = p_gift_id AND is_active = true;

  IF v_gift IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Gift not found');
  END IF;

  v_total_cost := COALESCE(v_gift.coin_cost, v_gift.value) * p_quantity;
  v_duration_ms := COALESCE(v_gift.duration, 15) * 1000;

  -- Check sender balance
  SELECT troll_coins INTO v_sender_coins FROM user_profiles WHERE id = p_sender_id;

  IF v_sender_coins < v_total_cost THEN
    RETURN json_build_object('success', false, 'message', 'Insufficient coins');
  END IF;

  -- Deduct coins
  UPDATE user_profiles SET troll_coins = troll_coins - v_total_cost WHERE id = p_sender_id;

  -- Add coins to receiver
  UPDATE user_profiles SET troll_coins = troll_coins + v_total_cost WHERE id = p_receiver_id;

  -- Generate transaction ID
  v_transaction_id := gen_random_uuid();

  -- Record in AR gift ledger
  INSERT INTO ar_gift_ledger (
    transaction_id, sender_id, receiver_id, stream_id, battle_id,
    gift_id, gift_name, gift_category, tracking_point, amount, duration_ms,
    is_active, activated_at, expires_at
  ) VALUES (
    v_transaction_id, p_sender_id, p_receiver_id, p_stream_id, p_battle_id,
    v_gift.gift_slug, v_gift.name, v_gift.category,
    CASE
      WHEN v_gift.animation_type = 'ar_face' THEN 'face'
      WHEN v_gift.animation_type = 'ar_body' THEN 'body'
      WHEN v_gift.animation_type = 'ar_presidential' THEN 'presidential'
      WHEN v_gift.animation_type = 'ar_troll' THEN 'ma_city'
      WHEN v_gift.animation_type = 'ar_shoulder' THEN 'shoulder'
      WHEN v_gift.animation_type = 'ar_legendary' THEN 'legendary'
      ELSE 'face'
    END,
    v_total_cost, v_duration_ms,
    true, now(), now() + (v_duration_ms || ' milliseconds')::INTERVAL
  );

  -- Also record in existing gift_ledger for compatibility
  INSERT INTO gift_ledger (
    transaction_id, sender_id, receiver_id, stream_id, gift_id, amount, currency_used, status
  ) VALUES (
    v_transaction_id, p_sender_id, p_receiver_id, p_stream_id, v_gift.id, v_total_cost, 'troll_coins', 'processed'
  );

  RETURN json_build_object(
    'success', true,
    'transaction_id', v_transaction_id,
    'gift_value', v_total_cost,
    'duration_ms', v_duration_ms
  );
END;
$$;

-- Function: send_gift
CREATE OR REPLACE FUNCTION public.send_gift(
  p_stream_id uuid,
  p_recipient_id uuid,
  p_gift_id uuid,
  p_quantity integer DEFAULT 1
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN public.send_gift_in_stream(
    auth.uid(),
    p_recipient_id,
    p_stream_id,
    p_gift_id::text,
    p_quantity,
    '{}'::jsonb
  );
END;
$$;

-- Function: send_gift_in_stream
CREATE OR REPLACE FUNCTION public.send_gift_in_stream(
  p_sender_id uuid,
  p_receiver_id uuid,
  p_stream_id uuid,
  p_gift_id text,
  p_quantity integer,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_sender public.user_profiles%ROWTYPE;
  v_gift_cost integer;
  v_total_cost integer;
  v_gift_name text;
  v_battle_id uuid;
  v_is_challenger boolean;
  v_currency_used text := 'coins';
  v_trollmonds_to_deduct integer := 0;
  v_trollmonds_transferred integer := 0;
  v_coins_back integer := 0;
  v_recipient_share integer;
   v_txn_key text := nullif(p_metadata->>'txn_key', '');
   v_existing_id text;
   v_sender_name text;
   v_agency_id uuid;
  v_agency_status text;
  v_default_split_percent integer := 0;
  v_agency_split_percent integer := 0;
  v_creator_share integer := 0;
  v_agency_share integer := 0;
  v_leader_bonus integer := 0;
  v_recruiter_bonus integer := 0;
  v_leader_commission_percent integer := 0;
  v_recruiter_commission_percent integer := 0;
  v_leader_user_id uuid;
  v_recruiter_user_id uuid;
  v_manager_user_id uuid;
  v_owner_user_id uuid;
  v_recipient_is_banned boolean := false;
  v_recipient_is_jailed boolean := false;
  v_contract_split_percent integer := NULL;
  v_per_gift_trollmond_cost integer := 0;
  v_is_friday boolean := false;
  v_bonus_result jsonb;
  v_sender_troll_coins bigint;
BEGIN
   -- Bypass coin protection trigger for this SECURITY DEFINER function
   PERFORM set_config('app.bypass_coin_protection', 'true', true);

   IF p_quantity IS NULL OR p_quantity < 1 THEN
     p_quantity := 1;
   END IF;

   -- Idempotency check
   IF v_txn_key IS NOT NULL THEN
      SELECT id::text INTO v_existing_id
      FROM public.stream_gifts
     WHERE sender_id = p_sender_id
       AND metadata->>'txn_key' = v_txn_key
     LIMIT 1;

     IF v_existing_id IS NOT NULL THEN
       RETURN jsonb_build_object('success', true, 'duplicate', true, 'transaction_id', v_existing_id);
     END IF;
   END IF;

    -- Look up gift cost — PRIMARY: gift_items
    SELECT COALESCE(coin_cost, value)::integer, name
      INTO v_gift_cost, v_gift_name
     FROM public.gift_items
     WHERE status = 'active'
       AND (
         id::text = p_gift_id
         OR gift_slug = p_gift_id
         OR name = p_gift_id
       )
     LIMIT 1;

   -- Fallback: purchasable_items (category: gift)
   IF v_gift_cost IS NULL THEN
     SELECT coin_price::integer, display_name
       INTO v_gift_cost, v_gift_name
     FROM public.purchasable_items
     WHERE (id::text = p_gift_id OR item_key = p_gift_id)
       AND category = 'gift'
       AND is_active = true
     LIMIT 1;
   END IF;

   -- Last resort: public.gifts (backward compat for old gift slugs like 'rose', 'diamond')
   IF v_gift_cost IS NULL THEN
     SELECT cost::integer, name
       INTO v_gift_cost, v_gift_name
     FROM public.gifts
     WHERE id::text = p_gift_id OR slug = p_gift_id
     LIMIT 1;
   END IF;

   IF v_gift_cost IS NULL THEN
     RETURN jsonb_build_object('success', false, 'message', 'Gift not found');
   END IF;

   v_total_cost := v_gift_cost * p_quantity;

   -- ── Determine trollmond deduction ──────────────────────────────────────
   IF v_gift_cost >= 100 THEN
     v_per_gift_trollmond_cost := 100;
   ELSE
     v_per_gift_trollmond_cost := 0;
   END IF;

   v_trollmonds_to_deduct := v_per_gift_trollmond_cost * p_quantity;

   -- Plain SELECT (no lock) — we only need the sender's current balance
   -- and trollmonds for the deduct step below.
   SELECT * INTO v_sender
   FROM public.user_profiles
   WHERE id = p_sender_id;

    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'message', 'Sender not found');
    END IF;

    -- Prevent self-gifting: all gifts must go to other users
    IF p_sender_id = p_receiver_id THEN
      RETURN jsonb_build_object('success', false, 'message', 'Cannot send gifts to yourself');
    END IF;

    IF v_trollmonds_to_deduct > 0 AND COALESCE(v_sender.trollmonds, 0) < v_trollmonds_to_deduct THEN
      v_trollmonds_to_deduct := 0;
    END IF;

   -- ── Agency split lookup ────────────────────────────────────────────────
   SELECT am.agency_id,
          a.status,
          COALESCE(a.default_split_percent, 0),
          COALESCE(up.is_banned, false),
          COALESCE(up.is_jailed, false)
     INTO v_agency_id,
          v_agency_status,
          v_default_split_percent,
          v_recipient_is_banned,
          v_recipient_is_jailed
   FROM public.agency_members am
   JOIN public.agencies a ON a.id = am.agency_id
   JOIN public.user_profiles up ON up.id = am.user_id
   WHERE am.user_id = p_receiver_id
     AND am.role = 'creator'
     AND am.status = 'active'
   ORDER BY am.joined_at DESC
   LIMIT 1;

   IF FOUND
      AND v_agency_status = 'approved'
      AND NOT v_recipient_is_banned
      AND NOT v_recipient_is_jailed THEN
     SELECT split_percent
       INTO v_contract_split_percent
     FROM public.agency_contracts
     WHERE agency_id = v_agency_id
       AND creator_id = p_receiver_id
       AND status = 'active'
       AND (creator_accepted_at IS NOT NULL OR agency_accepted_at IS NOT NULL)
       AND (starts_at IS NULL OR starts_at <= NOW())
       AND (ends_at IS NULL OR ends_at >= NOW())
     ORDER BY created_at DESC
     LIMIT 1;

     v_agency_split_percent := COALESCE(v_contract_split_percent, v_default_split_percent, 0);
     IF v_agency_split_percent < 0 THEN
       v_agency_split_percent := 0;
     ELSIF v_agency_split_percent > 50 THEN
       v_agency_split_percent := 50;
     END IF;

     SELECT owner_id
       INTO v_owner_user_id
     FROM public.agencies
     WHERE id = v_agency_id;

     SELECT user_id
       INTO v_manager_user_id
     FROM public.agency_members
     WHERE agency_id = v_agency_id
       AND role = 'manager'
       AND status = 'active'
     ORDER BY joined_at
     LIMIT 1;

     IF v_owner_user_id IS NOT NULL AND v_owner_user_id <> p_receiver_id THEN
       v_leader_user_id := v_owner_user_id;
     ELSIF v_manager_user_id IS NOT NULL THEN
       v_leader_user_id := v_manager_user_id;
     END IF;

     SELECT COALESCE(leader_commission_percent, 0), COALESCE(recruiter_commission_percent, 0)
       INTO v_leader_commission_percent, v_recruiter_commission_percent
     FROM public.agencies
     WHERE id = v_agency_id;

     IF v_leader_commission_percent < 0 THEN
       v_leader_commission_percent := 0;
     ELSIF v_leader_commission_percent > 100 THEN
       v_leader_commission_percent := 100;
     END IF;

     IF v_recruiter_commission_percent < 0 THEN
       v_recruiter_commission_percent := 0;
     ELSIF v_recruiter_commission_percent > 100 THEN
       v_recruiter_commission_percent := 100;
     END IF;
   ELSE
     v_agency_split_percent := 0;
   END IF;

   -- Calculate agency/creator split
   IF v_agency_split_percent > 0 THEN
     v_agency_share := (v_total_cost * v_agency_split_percent) / 100;
     v_creator_share := v_total_cost - v_agency_share;
   ELSE
     v_agency_share := 0;
     v_creator_share := v_total_cost;
   END IF;

   v_leader_bonus := 0;
   v_recruiter_bonus := 0;

   IF v_agency_split_percent > 0 AND v_leader_user_id IS NOT NULL THEN
     v_leader_bonus := (v_creator_share * v_leader_commission_percent) / 100;
   END IF;

   IF v_recruiter_user_id IS NOT NULL AND v_agency_split_percent > 0 THEN
     v_recruiter_bonus := (v_creator_share * v_recruiter_commission_percent) / 100;
   END IF;

   IF v_leader_bonus + v_recruiter_bonus > v_creator_share THEN
     v_leader_bonus := LEAST(v_leader_bonus, v_creator_share);
     v_recruiter_bonus := GREATEST(0, v_creator_share - v_leader_bonus);
   END IF;

   v_recipient_share := v_creator_share - v_leader_bonus - v_recruiter_bonus;

   -- ── Spend coins from sender (atomic, no row lock) ─────────────────────
   v_coins_back := floor(v_total_cost * 0.10);

   UPDATE public.user_profiles
   SET troll_coins = COALESCE(troll_coins, 0) - v_total_cost + v_coins_back
   WHERE id = p_sender_id
     AND COALESCE(troll_coins, 0) >= v_total_cost;

   IF NOT FOUND THEN
     RETURN jsonb_build_object('success', false, 'message', 'Insufficient coins');
   END IF;

   -- ── Deduct trollmonds from sender and transfer to receiver ─────────────
   IF v_trollmonds_to_deduct > 0 THEN
     UPDATE public.user_profiles
     SET trollmonds = COALESCE(trollmonds, 0) - v_trollmonds_to_deduct
     WHERE id = p_sender_id
       AND COALESCE(trollmonds, 0) >= v_trollmonds_to_deduct;

     IF FOUND THEN
       UPDATE public.user_profiles
       SET trollmonds = COALESCE(trollmonds, 0) + v_trollmonds_to_deduct
       WHERE id = p_receiver_id;
       v_trollmonds_transferred := v_trollmonds_to_deduct;
     ELSE
       v_trollmonds_to_deduct := 0;
       v_trollmonds_transferred := 0;
     END IF;
   END IF;

   -- ── Credit receiver with FULL coins (no fees) ─────────────────────────
   UPDATE public.user_profiles
   SET troll_coins = COALESCE(troll_coins, 0) + v_recipient_share,
       total_earned_coins = COALESCE(total_earned_coins, 0) + v_recipient_share
   WHERE id = p_receiver_id;

   IF NOT FOUND THEN
     RETURN jsonb_build_object('success', false, 'message', 'Recipient profile not found');
   END IF;

   -- ── Update stream totals ───────────────────────────────────────────────
   IF p_stream_id IS NOT NULL THEN
     UPDATE public.streams
     SET total_gifts_coins = COALESCE(total_gifts_coins, 0) + v_total_cost
     WHERE id = p_stream_id;
   END IF;

   -- ── Record stream_gifts ────────────────────────────────────────────────
   INSERT INTO public.stream_gifts (
     stream_id, sender_id, receiver_id, recipient_id,
     gift_id, gift_type, quantity, amount, coins_spent,
     coins_amount, currency_used, trollmonds_spent,
     trollmonds_transferred, coins_back, transaction_type, metadata
   ) VALUES (
     p_stream_id, p_sender_id, p_receiver_id, p_receiver_id,
     p_gift_id, p_gift_id, p_quantity, v_total_cost, v_total_cost,
     v_total_cost, 'coins', v_trollmonds_to_deduct,
     v_trollmonds_transferred, v_coins_back,
     CASE WHEN v_trollmonds_transferred > 0 THEN 'gift_with_trollmonds' ELSE 'gift' END,
     p_metadata || jsonb_build_object(
       'gift_value', v_total_cost,
       'currency_used', 'coins',
       'trollmonds_spent', v_trollmonds_to_deduct,
       'trollmonds_transferred', v_trollmonds_transferred,
       'coins_back', v_coins_back,
       'transaction_type', CASE WHEN v_trollmonds_transferred > 0 THEN 'gift_with_trollmonds' ELSE 'gift' END,
       'coins_back_source', 'gift_return_reward',
       'agency_split_percent', v_agency_split_percent,
       'agency_share_coins', v_agency_share,
       'creator_share_coins', v_recipient_share,
       'leader_bonus_coins', v_leader_bonus,
       'recruiter_bonus_coins', v_recruiter_bonus
     )
   )
   RETURNING id::text INTO v_existing_id;

   -- ── Agency earnings ───────────────────────────────────────────────────
   IF v_agency_id IS NOT NULL THEN
     INSERT INTO public.agency_earnings (
       agency_id, creator_id, source_type, source_id,
       gross_coins, split_percent, agency_coins, creator_coins
     ) VALUES (
       v_agency_id, p_receiver_id, 'gift', v_existing_id,
       v_total_cost, v_agency_split_percent, v_agency_share, v_recipient_share
     );

     IF v_leader_bonus > 0 AND v_leader_user_id IS NOT NULL THEN
       INSERT INTO public.agency_earnings (
         agency_id, creator_id, source_type, source_id,
         gross_coins, split_percent, agency_coins, creator_coins
       ) VALUES (
         v_agency_id, v_leader_user_id, 'gift', v_existing_id,
         v_leader_bonus, v_agency_split_percent, 0, v_leader_bonus
       );
     END IF;

     IF v_recruiter_bonus > 0 AND v_recruiter_user_id IS NOT NULL THEN
       INSERT INTO public.agency_earnings (
         agency_id, creator_id, source_type, source_id,
         gross_coins, split_percent, agency_coins, creator_coins
       ) VALUES (
         v_agency_id, v_recruiter_user_id, 'gift', v_existing_id,
         v_recruiter_bonus, v_agency_split_percent, 0, v_recruiter_bonus
       );
     END IF;
   END IF;

   -- ── Leader/recruiter bonus credit ─────────────────────────────────────
   IF v_leader_bonus > 0 AND v_leader_user_id IS NOT NULL THEN
     UPDATE public.user_profiles
     SET troll_coins = COALESCE(troll_coins, 0) + v_leader_bonus,
         total_earned_coins = COALESCE(total_earned_coins, 0) + v_leader_bonus
     WHERE id = v_leader_user_id;

     INSERT INTO public.coin_transactions (
       user_id, amount, type, currency, transaction_type, stream_id, metadata
     ) VALUES (
       v_leader_user_id, v_leader_bonus, 'agency_leader_bonus', 'coins', 'agency_leader_bonus', p_stream_id,
       jsonb_build_object(
         'stream_gift_id', v_existing_id, 'gift_id', p_gift_id,
         'gift_value', v_total_cost, 'bonus_amount', v_leader_bonus,
         'agency_id', v_agency_id, 'recipient_id', p_receiver_id
       )
     );
   END IF;

   IF v_recruiter_bonus > 0 AND v_recruiter_user_id IS NOT NULL THEN
     UPDATE public.user_profiles
     SET troll_coins = COALESCE(troll_coins, 0) + v_recruiter_bonus,
         total_earned_coins = COALESCE(total_earned_coins, 0) + v_recruiter_bonus
     WHERE id = v_recruiter_user_id;

     INSERT INTO public.coin_transactions (
       user_id, amount, type, currency, transaction_type, stream_id, metadata
     ) VALUES (
       v_recruiter_user_id, v_recruiter_bonus, 'agency_recruiter_bonus', 'coins', 'agency_recruiter_bonus', p_stream_id,
       jsonb_build_object(
         'stream_gift_id', v_existing_id, 'gift_id', p_gift_id,
         'gift_value', v_total_cost, 'bonus_amount', v_recruiter_bonus,
         'agency_id', v_agency_id, 'recipient_id', p_receiver_id
       )
     );
   END IF;

   -- ── Coin transactions ──────────────────────────────────────────────────
   INSERT INTO public.coin_transactions (user_id, amount, type, currency, transaction_type, stream_id, from_user_id, to_user_id, metadata)
   VALUES
   (p_sender_id, -v_total_cost, 'gift_sent', 'coins', 'gift_sent', p_stream_id, p_sender_id, p_receiver_id,
     jsonb_build_object(
       'recipient_id', p_receiver_id, 'stream_id', p_stream_id,
       'gift_id', p_gift_id, 'gift_value', v_total_cost,
       'trollmonds_spent', v_trollmonds_to_deduct,
       'trollmonds_transferred', v_trollmonds_transferred,
       'coins_back', v_coins_back, 'stream_gift_id', v_existing_id
     )),
   (p_receiver_id, v_recipient_share, 'gift_received', 'coins', 'gift_received', p_stream_id, p_sender_id, p_receiver_id,
     jsonb_build_object(
       'sender_id', p_sender_id, 'stream_id', p_stream_id,
       'gift_id', p_gift_id, 'gift_value', v_total_cost,
       'stream_gift_id', v_existing_id
     ));

   IF v_coins_back > 0 THEN
     INSERT INTO public.coin_transactions (user_id, amount, type, currency, transaction_type, stream_id, from_user_id, to_user_id, metadata)
     VALUES (
       p_sender_id, v_coins_back, 'gift_return_reward', 'coins', 'gift_return_reward', p_stream_id, NULL, p_sender_id,
       jsonb_build_object(
         'stream_id', p_stream_id, 'gift_id', p_gift_id,
         'gift_value', v_total_cost, 'stream_gift_id', v_existing_id
       )
     );
   END IF;

   -- ── Stream messages ────────────────────────────────────────────────────
   IF p_stream_id IS NOT NULL THEN
     INSERT INTO public.stream_messages (stream_id, user_id, content, type)
     VALUES (
       p_stream_id, p_sender_id,
       'GIFT_EVENT:' || COALESCE(v_gift_name, p_gift_id) || ':' || p_quantity || ':' || v_total_cost || ':coins:' || v_coins_back || ':' || v_trollmonds_transferred,
       'system'
     );

     IF v_coins_back > 0 THEN
       SELECT COALESCE(username, display_name, split_part(email, '@', 1), 'Troll Citizen')
         INTO v_sender_name
       FROM public.user_profiles
       WHERE id = p_sender_id;

       INSERT INTO public.stream_messages (stream_id, user_id, content, type)
       VALUES (
         p_stream_id, p_sender_id,
         COALESCE(v_sender_name, 'Troll Citizen') || ' got ' || v_coins_back || ' coins back',
         'system'
       );
     END IF;
   END IF;

   -- ── Battle scoring ─────────────────────────────────────────────────────
   SELECT id, (challenger_stream_id = p_stream_id) INTO v_battle_id, v_is_challenger
   FROM public.battles
   WHERE (challenger_stream_id = p_stream_id OR opponent_stream_id = p_stream_id)
     AND status = 'active'
   LIMIT 1;

   IF v_battle_id IS NOT NULL THEN
     IF v_is_challenger THEN
       UPDATE public.battles
       SET score_challenger = COALESCE(score_challenger, 0) + v_total_cost,
           pot_challenger = COALESCE(pot_challenger, 0) + v_total_cost
       WHERE id = v_battle_id;
     ELSE
       UPDATE public.battles
       SET score_opponent = COALESCE(score_opponent, 0) + v_total_cost,
           pot_opponent = COALESCE(pot_opponent, 0) + v_total_cost
       WHERE id = v_battle_id;
     END IF;
   END IF;

   -- ── Friday Battle Bonus ────────────────────────────────────────────────
   IF v_battle_id IS NOT NULL THEN
     v_is_friday := EXTRACT(DOW FROM (NOW() AT TIME ZONE 'America/Denver')) = 5;
     IF v_is_friday THEN
       v_bonus_result := public.award_friday_battle_gifter_bonus(p_sender_id, v_battle_id, v_total_cost::BIGINT);
     END IF;
   END IF;

   RETURN jsonb_build_object(
     'success', true,
     'transaction_id', v_existing_id,
     'currency_used', 'coins',
     'gift_value', v_total_cost,
     'trollmonds_spent', v_trollmonds_to_deduct,
     'trollmonds_transferred', v_trollmonds_transferred,
     'coins_back', v_coins_back,
     'agency_split_percent', v_agency_split_percent,
     'agency_share_coins', v_agency_share,
     'creator_share_coins', v_recipient_share,
     'leader_bonus_coins', v_leader_bonus,
     'recruiter_bonus_coins', v_recruiter_bonus,
     'friday_battle_bonus', COALESCE(v_bonus_result->>'success', 'false')::BOOLEAN,
     'message', 'Gift sent successfully'
   );
END;
$$;

-- Function: send_marketplace_message
CREATE OR REPLACE FUNCTION send_marketplace_message(
    p_recipient_id UUID,
    p_message TEXT,
    p_listing_id UUID DEFAULT NULL,
    p_listing_type TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_sender_id UUID;
    v_conversation_id UUID;
    v_message_id UUID;
BEGIN
    SELECT auth.uid() INTO v_sender_id;
    
    IF v_sender_id IS NULL THEN
        RAISE EXCEPTION 'User must be authenticated';
    END IF;

    IF v_sender_id = p_recipient_id THEN
        RAISE EXCEPTION 'Cannot message yourself';
    END IF;

    -- Find or create conversation
    SELECT id INTO v_conversation_id
    FROM public.marketplace_conversations
    WHERE buyer_id = v_sender_id 
        AND seller_id = p_recipient_id
        AND (listing_id = p_listing_id OR (listing_id IS NULL AND p_listing_id IS NULL))
    LIMIT 1;

    IF v_conversation_id IS NULL THEN
        -- Check if conversation exists the other way
        SELECT id INTO v_conversation_id
        FROM public.marketplace_conversations
        WHERE buyer_id = p_recipient_id 
            AND seller_id = v_sender_id
            AND (listing_id = p_listing_id OR (listing_id IS NULL AND p_listing_id IS NULL))
        LIMIT 1;

        IF v_conversation_id IS NULL THEN
            -- Create new conversation
            INSERT INTO public.marketplace_conversations (buyer_id, seller_id, listing_id, listing_type)
            VALUES (v_sender_id, p_recipient_id, p_listing_id, p_listing_type)
            RETURNING id INTO v_conversation_id;
        ELSE
            -- Swap buyer/seller roles
            UPDATE public.marketplace_conversations
            SET buyer_id = v_sender_id, seller_id = p_recipient_id, updated_at = NOW()
            WHERE id = v_conversation_id;
        END IF;
    END IF;

    -- Insert message
    INSERT INTO public.marketplace_messages (conversation_id, sender_id, message)
    VALUES (v_conversation_id, v_sender_id, p_message)
    RETURNING id INTO v_message_id;

    -- Update conversation timestamp
    UPDATE public.marketplace_conversations
    SET updated_at = NOW()
    WHERE id = v_conversation_id;

    RETURN v_message_id;
END;
$$;

-- Function: send_premium_gift
CREATE OR REPLACE FUNCTION public.send_premium_gift(
  p_sender_id uuid,
  p_receiver_id uuid,
  p_stream_id uuid,
  p_gift_id text,
  p_cost bigint,
  p_quantity integer
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_sender_balance BIGINT;
  v_cashback INTEGER;
  v_bonus_cashback INTEGER := 0;
  v_total_cashback INTEGER;
  v_is_tier_iv_v BOOLEAN := FALSE;
  v_is_gold_trigger BOOLEAN := FALSE;
BEGIN
  -- 1. Check Balance
  SELECT troll_coins INTO v_sender_balance FROM user_profiles WHERE id = p_sender_id;
  IF v_sender_balance < p_cost THEN
    RETURN jsonb_build_object('success', false, 'message', 'Insufficient funds');
  END IF;

  -- 2. Determine Tier/Bonuses
  IF p_cost >= 10000 THEN
    v_is_tier_iv_v := TRUE;
    v_bonus_cashback := FLOOR(p_cost * 0.05); -- 5%
  END IF;

  IF p_cost = 1000000 THEN
    v_is_gold_trigger := TRUE;
  END IF;

  -- Random Cashback 1-50
  v_cashback := floor(random() * 50 + 1)::int;
  v_total_cashback := v_cashback + v_bonus_cashback;

  -- 3. Deduct Cost
  UPDATE user_profiles 
  SET troll_coins = troll_coins - p_cost + v_total_cashback
  WHERE id = p_sender_id;

  -- 4. Credit Receiver (95% share)
  UPDATE user_profiles
  SET troll_coins = troll_coins + FLOOR(p_cost * 0.95),
      total_earned_coins = COALESCE(total_earned_coins, 0) + FLOOR(p_cost * 0.95)
  WHERE id = p_receiver_id;

  -- 5. Apply Status
  IF v_is_tier_iv_v THEN
    -- RGB for 30 days
    UPDATE user_profiles
    SET rgb_username_expires_at = GREATEST(now(), COALESCE(rgb_username_expires_at, now())) + INTERVAL '30 days'
    WHERE id = p_sender_id;
  END IF;

  IF v_is_gold_trigger THEN
    -- GOLD PERMANENT
    UPDATE user_profiles
    SET is_gold = TRUE, gold_granted_at = now()
    WHERE id = p_sender_id;
  END IF;

  -- 6. Record Transaction
  INSERT INTO coin_transactions (user_id, amount, type, metadata)
  VALUES 
    (p_sender_id, -p_cost, 'gift_sent', jsonb_build_object('gift_id', p_gift_id, 'receiver_id', p_receiver_id, 'stream_id', p_stream_id, 'cashback', v_total_cashback)),
    (p_receiver_id, FLOOR(p_cost * 0.95), 'gift_received', jsonb_build_object('gift_id', p_gift_id, 'sender_id', p_sender_id, 'stream_id', p_stream_id));
    
  -- Also insert into stream_messages for visibility
  INSERT INTO stream_messages (stream_id, user_id, content, type)
  VALUES (p_stream_id, p_sender_id, 'GIFT_EVENT:' || p_gift_id || ':' || p_cost, 'system');

  RETURN jsonb_build_object(
    'success', true, 
    'cashback', v_total_cashback,
    'rgb_awarded', v_is_tier_iv_v,
    'gold_awarded', v_is_gold_trigger
  );
END;
$$;

-- Function: send_tromail_message
CREATE OR REPLACE FUNCTION send_tromail_message(
  p_sender_user_id UUID,
  p_sender_role TEXT,
  p_sender_tromail_address TEXT,
  p_subject TEXT,
  p_body TEXT,
  p_is_admin_email BOOLEAN,
  p_is_important BOOLEAN,
  p_related_meeting_id UUID,
  p_recipient_user_ids UUID[],
  p_recipient_roles TEXT[]
) RETURNS TABLE(success BOOLEAN, message_id UUID, error TEXT)
LANGUAGE plpgsql
AS $$
DECLARE
  v_message_id UUID;
  v_recipient_user_id UUID;
  v_recipient_role TEXT;
  v_recipient_tromail_address TEXT;
  v_index INTEGER;
BEGIN
  -- Verify sender has active Tromail account
  IF NOT EXISTS (
    SELECT 1 FROM tromail_accounts
    WHERE user_id = p_sender_user_id
    AND is_active = true
  ) THEN
    RETURN QUERY SELECT false, NULL::UUID, 'Sender does not have an active Tromail account'::TEXT;
    RETURN;
  END IF;

  -- Verify sender can send admin emails if flagged
  IF p_is_admin_email THEN
    IF NOT EXISTS (
      SELECT 1 FROM user_profiles
      WHERE id = p_sender_user_id
      AND (is_admin = true OR role IN ('admin', 'ceo', 'secretary', 'admin_assistant', 'ceo_assistant'))
    ) THEN
      RETURN QUERY SELECT false, NULL::UUID, 'Sender not authorized to send admin emails'::TEXT;
      RETURN;
    END IF;
  END IF;

  -- Verify recipient count matches
  IF array_length(p_recipient_user_ids, 1) IS NULL OR array_length(p_recipient_roles, 1) IS NULL THEN
    RETURN QUERY SELECT false, NULL::UUID, 'Recipient arrays cannot be empty'::TEXT;
    RETURN;
  END IF;

  IF array_length(p_recipient_user_ids, 1) != array_length(p_recipient_roles, 1) THEN
    RETURN QUERY SELECT false, NULL::UUID, 'Recipient arrays must have same length'::TEXT;
    RETURN;
  END IF;

  -- Insert the message
  INSERT INTO tromail_messages (
    sender_user_id,
    sender_role,
    sender_tromail_address,
    subject,
    body,
    is_admin_email,
    is_important,
    related_meeting_id
  ) VALUES (
    p_sender_user_id,
    p_sender_role,
    p_sender_tromail_address,
    p_subject,
    p_body,
    p_is_admin_email,
    p_is_important,
    p_related_meeting_id
  ) RETURNING id INTO v_message_id;

  -- Create recipients
  FOR v_index IN 1..array_length(p_recipient_user_ids, 1) LOOP
    v_recipient_user_id := p_recipient_user_ids[v_index];
    v_recipient_role := p_recipient_roles[v_index];

    -- Get recipient's Tromail address
    SELECT tromail_address INTO v_recipient_tromail_address
    FROM tromail_accounts
    WHERE user_id = v_recipient_user_id
    AND is_active = true;

    IF v_recipient_tromail_address IS NOT NULL THEN
      INSERT INTO tromail_recipients (
        message_id,
        recipient_user_id,
        recipient_role,
        recipient_tromail_address
      ) VALUES (
        v_message_id,
        v_recipient_user_id,
        v_recipient_role,
        v_recipient_tromail_address
      );
    END IF;
  END LOOP;

  RETURN QUERY SELECT true, v_message_id, NULL::TEXT;
EXCEPTION
  WHEN OTHERS THEN
    RETURN QUERY SELECT false, NULL::UUID, SQLERRM::TEXT;
END;
$$;

-- Function: set_active_property
CREATE OR REPLACE FUNCTION public.set_active_property(p_property_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Verify ownership
    IF NOT EXISTS (SELECT 1 FROM public.properties WHERE id = p_property_id AND owner_user_id = v_user_id) THEN
        RAISE EXCEPTION 'Property not owned by user';
    END IF;

    -- Update all properties to inactive for this user
    UPDATE public.properties 
    SET is_active_home = false 
    WHERE owner_user_id = v_user_id;

    -- Set the specific property to active
    UPDATE public.properties 
    SET is_active_home = true 
    WHERE id = p_property_id;

    RETURN true;
END;
$$;

-- Function: set_broadcaster_moderation_lock
CREATE OR REPLACE FUNCTION public.set_broadcaster_moderation_lock(
  p_broadcaster_id UUID,
  p_chat_disabled BOOLEAN DEFAULT NULL,
  p_mic_muted BOOLEAN DEFAULT NULL,
  p_reason TEXT DEFAULT NULL,
  p_chat_disabled_until TIMESTAMPTZ DEFAULT NULL,
  p_chat_disable_strike_count INTEGER DEFAULT NULL,
  p_chat_disabled_stream_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor_id UUID := auth.uid();
  v_actor public.user_profiles%ROWTYPE;
  v_chat_disabled BOOLEAN;
  v_mic_muted BOOLEAN;
  v_chat_disabled_until TIMESTAMPTZ;
  v_chat_disable_strike_count INTEGER;
  v_chat_disabled_stream_id UUID;
BEGIN
  IF v_actor_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
  END IF;

  SELECT *
  INTO v_actor
  FROM public.user_profiles
  WHERE id = v_actor_id;

  IF NOT COALESCE(v_actor.is_admin, false)
     AND NOT COALESCE(v_actor.is_troll_officer, false)
     AND NOT COALESCE(v_actor.is_lead_officer, false)
     AND COALESCE(v_actor.role, '') NOT IN ('admin', 'troll_officer', 'lead_troll_officer')
     AND COALESCE(v_actor.troll_role, '') NOT IN ('admin', 'troll_officer', 'lead_troll_officer') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Forbidden');
  END IF;

  UPDATE public.user_profiles
  SET
    broadcast_chat_disabled = COALESCE(p_chat_disabled, broadcast_chat_disabled),
    broadcast_chat_disabled_until = CASE
      WHEN p_chat_disabled = false THEN NULL
      ELSE COALESCE(p_chat_disabled_until, broadcast_chat_disabled_until)
    END,
    broadcast_chat_disable_strike_count = CASE
      WHEN p_chat_disabled = false THEN 0
      ELSE COALESCE(p_chat_disable_strike_count, broadcast_chat_disable_strike_count)
    END,
    broadcast_chat_disabled_stream_id = CASE
      WHEN p_chat_disabled = false THEN NULL
      ELSE COALESCE(p_chat_disabled_stream_id, broadcast_chat_disabled_stream_id)
    END,
    broadcast_mic_muted = COALESCE(p_mic_muted, broadcast_mic_muted),
    updated_at = now()
  WHERE id = p_broadcaster_id
  RETURNING
    broadcast_chat_disabled,
    broadcast_mic_muted,
    broadcast_chat_disabled_until,
    broadcast_chat_disable_strike_count,
    broadcast_chat_disabled_stream_id
  INTO
    v_chat_disabled,
    v_mic_muted,
    v_chat_disabled_until,
    v_chat_disable_strike_count,
    v_chat_disabled_stream_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Broadcaster not found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'broadcaster_id', p_broadcaster_id,
    'broadcast_chat_disabled', v_chat_disabled,
    'broadcast_mic_muted', v_mic_muted,
    'broadcast_chat_disabled_until', v_chat_disabled_until,
    'broadcast_chat_disable_strike_count', v_chat_disable_strike_count,
    'broadcast_chat_disabled_stream_id', v_chat_disabled_stream_id,
    'reason', COALESCE(p_reason, '')
  );
END;
$$;

-- Function: set_match_winner
CREATE OR REPLACE FUNCTION set_match_winner(
  p_match_id UUID,
  p_winner_id UUID
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  -- Only the winner or service role can set the winner
  IF auth.uid() != p_winner_id AND auth.role() != 'service_role' THEN
    RAISE EXCEPTION 'Unauthorized to set winner';
  END IF;

  UPDATE game_matches
  SET winner_id = p_winner_id
  WHERE id = p_match_id
    AND winner_id IS NULL;

  RETURN FOUND;
END;
$$;

-- Function: set_stream_box_count
CREATE OR REPLACE FUNCTION public.set_stream_box_count(
    p_stream_id UUID,
    p_new_box_count INTEGER
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    UPDATE public.streams
    SET box_count = p_new_box_count
    WHERE id = p_stream_id;
END;
$$;

-- Function: set_treasury_role_allocation
CREATE OR REPLACE FUNCTION public.set_treasury_role_allocation(
  p_role_key text,
  p_role_label text,
  p_weekly_amount_coins bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_uid uuid;
  v_user_allowed boolean := false;
  v_treasury_id uuid;
  v_balance_before bigint;
  v_balance_after bigint;
  v_allocation_id uuid;
BEGIN
  v_uid := auth.uid();

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_role_key IS NULL OR btrim(p_role_key) = '' THEN
    RAISE EXCEPTION 'role_key is required';
  END IF;

  IF p_role_label IS NULL OR btrim(p_role_label) = '' THEN
    RAISE EXCEPTION 'role_label is required';
  END IF;

  IF p_weekly_amount_coins IS NULL OR p_weekly_amount_coins < 0 THEN
    RAISE EXCEPTION 'weekly_amount_coins must be zero or greater';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_profiles
    WHERE id = v_uid
      AND (
        role IN ('admin', 'president', 'owner')
        OR is_admin = true
        OR role = 'ceo'
        OR troll_role IN ('admin', 'president', 'owner', 'ceo')
      )
  ) INTO v_user_allowed;

  IF NOT v_user_allowed THEN
    RAISE EXCEPTION 'Only admins, CEOs, or the president can update treasury role allocations';
  END IF;

  INSERT INTO public.treasury_role_allocations (
    role_key,
    role_label,
    weekly_amount_coins,
    is_active,
    created_by,
    updated_by
  )
  VALUES (
    lower(btrim(p_role_key)),
    btrim(p_role_label),
    p_weekly_amount_coins,
    p_weekly_amount_coins > 0,
    v_uid,
    v_uid
  )
  ON CONFLICT (role_key)
  DO UPDATE SET
    role_label = EXCLUDED.role_label,
    weekly_amount_coins = EXCLUDED.weekly_amount_coins,
    is_active = EXCLUDED.is_active,
    updated_by = EXCLUDED.updated_by,
    updated_at = now()
  RETURNING id INTO v_allocation_id;

  SELECT id, balance_coins
    INTO v_treasury_id, v_balance_before
  FROM public.troll_city_treasury
  ORDER BY created_at ASC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.troll_city_treasury (treasury_name, balance_coins, total_earned_coins, total_distributed_coins, status)
    VALUES ('maitroll Treasury', 0, 0, 0, 'active')
    RETURNING id, balance_coins INTO v_treasury_id, v_balance_before;
  END IF;

  v_balance_after := v_balance_before;

  INSERT INTO public.treasury_transactions (
    treasury_id,
    transaction_type,
    source_type,
    direction,
    amount_coins,
    balance_before,
    balance_after,
    created_by,
    details
  )
  VALUES (
    v_treasury_id,
    'correction',
    'role_allocation_update',
    'credit',
    0,
    v_balance_before,
    v_balance_after,
    v_uid,
    jsonb_build_object(
      'action', 'role_allocation_updated',
      'role_key', lower(btrim(p_role_key)),
      'role_label', btrim(p_role_label),
      'weekly_amount_coins', p_weekly_amount_coins,
      'is_active', p_weekly_amount_coins > 0
    )
  );

  RETURN jsonb_build_object(
    'allocation_id', v_allocation_id,
    'role_key', lower(btrim(p_role_key)),
    'role_label', btrim(p_role_label),
    'weekly_amount_coins', p_weekly_amount_coins,
    'is_active', p_weekly_amount_coins > 0
  );
END;
$$;

-- Function: set_user_role
CREATE OR REPLACE FUNCTION public.set_user_role(
  target_user UUID,
  new_role TEXT,
  reason TEXT,
  acting_admin_id UUID DEFAULT NULL
) RETURNS VOID AS $$
DECLARE
  v_old_role TEXT;
  v_admin_id UUID;
BEGIN
  -- Get current user (admin)
  v_admin_id := auth.uid();
  
  -- If called by service role and acting_admin_id is provided, use it
  IF auth.role() = 'service_role' AND acting_admin_id IS NOT NULL THEN
      v_admin_id := acting_admin_id;
  END IF;
  
  -- Check permissions (simple check, RLS should handle more)
  IF NOT EXISTS (SELECT 1 FROM user_profiles WHERE id = v_admin_id AND (role = 'admin' OR is_admin = true)) THEN
    RAISE EXCEPTION 'Unauthorized: Only admins can change roles. (Admin ID: %, Role: %)', v_admin_id, auth.role();
  END IF;

  -- Get old role
  SELECT role INTO v_old_role FROM user_profiles WHERE id = target_user;

  -- Update role
  UPDATE user_profiles 
  SET 
      role = new_role,
      is_admin = (new_role = 'admin'),
      is_lead_officer = (new_role = 'lead_troll_officer'),
      is_troll_officer = (new_role IN ('troll_officer', 'lead_troll_officer')),
      is_troller = (new_role = 'troller'),
      updated_at = now()
  WHERE id = target_user;

  -- Log change
  INSERT INTO role_change_log (target_user, changed_by, old_role, new_role, reason, created_at)
  VALUES (target_user, v_admin_id, v_old_role, new_role, reason, now());
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ============================================================
-- Function: remove_broadofficer
-- Source: 20290616000001_fix_critical_rpc_auth.sql
-- Signature: (p_target_user_id uuid)
-- Returns: void
-- ============================================================

CREATE OR REPLACE FUNCTION public.remove_broadofficer(p_target_user_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM public.require_admin();

  UPDATE user_profiles
  SET
    is_troll_officer = false,
    is_lead_officer = false,
    is_prosecutor = false,
    is_attorney = false,
    troll_role = NULL,
    updated_at = now()
  WHERE id = p_target_user_id;
END;
$$;

-- Function: ship_order
CREATE OR REPLACE FUNCTION ship_order(
    p_order_id UUID,
    p_tracking_number TEXT,
    p_carrier TEXT,
    p_seller_id UUID
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_tracking_url TEXT;
    v_carrier_template TEXT;
BEGIN
    -- Verify seller owns the order
    IF NOT EXISTS (
        SELECT 1 FROM public.shop_orders
        WHERE id = p_order_id AND seller_id = p_seller_id AND status = 'paid'
    ) THEN
        RAISE EXCEPTION 'Order not found or not authorized';
    END IF;

    -- Get tracking URL template
    SELECT tracking_url_template INTO v_carrier_template
    FROM public.shipping_carriers
    WHERE id = p_carrier;

    -- Generate tracking URL
    IF v_carrier_template IS NOT NULL THEN
        v_tracking_url := REPLACE(v_carrier_template, '{tracking_number}', p_tracking_number);
    END IF;

    -- Update order
    UPDATE public.shop_orders
    SET status = 'shipped',
        tracking_number = p_tracking_number,
        carrier = p_carrier,
        tracking_url = v_tracking_url,
        shipped_at = NOW(),
        updated_at = NOW()
    WHERE id = p_order_id;

    RETURN FOUND;
END;
$$;

-- Function: sign_document
CREATE OR REPLACE FUNCTION public.sign_document(
  p_document_id UUID,
  p_user_id UUID,
  p_legal_name TEXT,
  p_typed_signature TEXT,
  p_ip_address INET DEFAULT NULL,
  p_user_agent TEXT DEFAULT NULL
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_document RECORD;
  v_username TEXT;
  v_signature_hash TEXT;
  v_signature_id UUID;
BEGIN
  -- Get document
  SELECT * INTO v_document FROM public.documents WHERE id = p_document_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Document not found');
  END IF;

  -- Check document is in signable state
  IF v_document.status NOT IN ('draft', 'pending') THEN
    RETURN json_build_object('success', false, 'error', 'Document is not in a signable state. Status: ' || v_document.status);
  END IF;

  -- Check document is not locked
  IF v_document.is_locked THEN
    RETURN json_build_object('success', false, 'error', 'Document is locked and cannot be signed');
  END IF;

  -- Check user has access
  IF v_document.submitted_by != p_user_id AND v_document.assigned_to != p_user_id THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.document_access
      WHERE document_id = p_document_id AND user_id = p_user_id AND access_level IN ('sign', 'approve', 'admin') AND is_active = true
    ) AND NOT EXISTS (
      SELECT 1 FROM public.user_profiles WHERE id = p_user_id AND (is_admin = true OR role IN ('admin', 'ceo', 'founder', 'owner', 'moderator'))
    ) THEN
      RETURN json_build_object('success', false, 'error', 'You do not have permission to sign this document');
    END IF;
  END IF;

  -- Check not already signed by this user
  IF EXISTS (
    SELECT 1 FROM public.document_signatures
    WHERE document_id = p_document_id AND user_id = p_user_id AND is_revoked = false
  ) THEN
    RETURN json_build_object('success', false, 'error', 'You have already signed this document');
  END IF;

  -- Get username
  SELECT username INTO v_username FROM public.user_profiles WHERE id = p_user_id;
  IF v_username IS NULL THEN
    v_username = 'Unknown';
  END IF;

  -- Generate signature hash
  v_signature_hash := ENCODE(DIGEST(
    p_document_id::TEXT || '|' || p_user_id::TEXT || '|' || p_legal_name || '|' || p_typed_signature || '|' || NOW()::TEXT,
    'sha256'
  ), 'hex');

  -- Insert signature
  INSERT INTO public.document_signatures (
    document_id, user_id, username, legal_name, typed_signature,
    ip_address, browser_user_agent, agreement_version, signature_hash, document_type
  ) VALUES (
    p_document_id, p_user_id, v_username, p_legal_name, p_typed_signature,
    p_ip_address, p_user_agent, v_document.version, v_signature_hash, v_document.document_type_slug
  ) RETURNING id INTO v_signature_id;

  -- Update document status to pending if it was draft
  IF v_document.status = 'draft' THEN
    UPDATE public.documents SET status = 'pending', submitted_at = now(), updated_at = now() WHERE id = p_document_id;
  END IF;

  -- Log the event
  PERFORM public.log_document_event(
    p_document_id, p_user_id, v_username,
    (SELECT role FROM public.user_profiles WHERE id = p_user_id),
    'document_signed',
    jsonb_build_object('signature_id', v_signature_id, 'legal_name', p_legal_name),
    p_ip_address, p_user_agent
  );

  RETURN json_build_object(
    'success', true,
    'signature_id', v_signature_id,
    'signature_hash', v_signature_hash
  );
END;
$$;

-- Function: sign_lease
CREATE OR REPLACE FUNCTION public.sign_lease(p_property_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_property RECORD;
    v_total_cost INTEGER;
    v_rent INTEGER;
    v_utilities INTEGER;
    v_balance INTEGER;
    v_owner_id UUID;
    v_lease_id UUID;
    v_occupancy INTEGER;
    v_max_tenants INTEGER;
BEGIN
    -- Get Property
    SELECT * INTO v_property FROM public.properties WHERE id = p_property_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Property not found');
    END IF;

    IF v_property.is_for_rent = false THEN
        RETURN jsonb_build_object('success', false, 'error', 'Property not for rent');
    END IF;
    
    -- Check Occupancy
    SELECT count(*)::INTEGER INTO v_occupancy FROM public.leases WHERE property_id = p_property_id AND status = 'active';
    v_max_tenants := COALESCE(v_property.max_tenants, 1);
    
    IF v_occupancy >= v_max_tenants THEN
        RETURN jsonb_build_object('success', false, 'error', 'Property is fully occupied');
    END IF;

    -- Check if user already renting this property
    IF EXISTS (SELECT 1 FROM public.leases WHERE property_id = p_property_id AND tenant_id = v_user_id AND status = 'active') THEN
         RETURN jsonb_build_object('success', false, 'error', 'You are already renting this property');
    END IF;

    -- Calculate Cost (1st Month Rent + Utilities)
    v_rent := v_property.rent_amount;
    v_utilities := COALESCE(v_property.utility_cost, 0);
    v_total_cost := v_rent + v_utilities;
    v_owner_id := v_property.owner_id;

    -- Check Balance
    SELECT troll_coins INTO v_balance FROM public.user_profiles WHERE id = v_user_id;
    IF v_balance < v_total_cost THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient funds for first month rent + utilities');
    END IF;

    -- Deduct from Tenant
    UPDATE public.user_profiles SET troll_coins = troll_coins - v_total_cost WHERE id = v_user_id;
    
    -- Distribute Initial Payment (Rent + Utilities)
    -- 1. Utilities -> Admin Pool (Ledger only)
    INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
    VALUES (v_user_id, -v_utilities, 'utility_payment', 'housing', 'Utility Payment (Initial)', 'out');

    -- 2. Rent -> Owner or System
    IF v_owner_id IS NULL THEN
        -- System owned
         INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
         VALUES (v_user_id, -v_rent, 'rent_payment', 'housing', 'Rent Payment (System)', 'out');
    ELSE
         -- User owned: 10% Tax
         DECLARE
            v_tax_amount INTEGER := floor(v_rent * 0.10);
            v_owner_payout INTEGER := v_rent - v_tax_amount;
         BEGIN
             UPDATE public.user_profiles SET troll_coins = troll_coins + v_owner_payout WHERE id = v_owner_id;
             INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, direction)
             VALUES (v_owner_id, v_owner_payout, 'rent_income', 'housing', 'Rent Received', 'in');
         END;
    END IF;

    -- Create Lease
    INSERT INTO public.leases (property_id, tenant_id, start_date, rent_due_day, last_rent_paid_at, last_utility_paid_at, status)
    VALUES (p_property_id, v_user_id, NOW(), EXTRACT(DAY FROM NOW()), NOW(), NOW(), 'active')
    RETURNING id INTO v_lease_id;

    -- Create Invoice Record
    INSERT INTO public.invoices (lease_id, tenant_id, type, amount, status, paid_at)
    VALUES (v_lease_id, v_user_id, 'rent', v_rent, 'paid', NOW()),
           (v_lease_id, v_user_id, 'electric', v_utilities, 'paid', NOW());

    -- Update Property Status ONLY if full
    IF v_occupancy + 1 >= v_max_tenants THEN
        UPDATE public.properties SET is_for_rent = false WHERE id = p_property_id;
    END IF;

    RETURN jsonb_build_object('success', true, 'lease_id', v_lease_id);
END;
$$;

-- Function: signup_president_candidate
create or replace function signup_president_candidate(
  p_campaign_slogan text
)
returns uuid
language plpgsql
security definer
as $$
declare
  v_user_id uuid;
  v_election_id uuid;
  v_candidate_id uuid;
  v_count int;
  v_limit int;
begin
  v_user_id := auth.uid();
  
  -- Get current open election
  select id, candidate_limit into v_election_id, v_limit
  from president_elections
  where status = 'open'
  limit 1;
  
  if v_election_id is null then
    raise exception 'No open election found';
  end if;

  -- Check limit
  select count(*) into v_count
  from president_candidates
  where election_id = v_election_id;

  if v_count >= v_limit then
    raise exception 'Candidate limit reached for this election';
  end if;
  
  -- Check if already signed up
  if exists (
    select 1 from president_candidates 
    where election_id = v_election_id and user_id = v_user_id
  ) then
    raise exception 'You are already a candidate';
  end if;
  
  -- Insert candidate (Fixing column names: slogan instead of campaign_slogan, status='approved', banner_path default)
  insert into president_candidates (
      election_id, 
      user_id, 
      slogan, 
      status, 
      banner_path
  )
  values (
      v_election_id, 
      v_user_id, 
      p_campaign_slogan, 
      'approved', 
      '/default-banner.jpg' -- Placeholder to satisfy NOT NULL
  ) 
  returning id into v_candidate_id;
  
  return v_candidate_id;
end;
$$;

-- Function: spend_coins
CREATE OR REPLACE FUNCTION public.spend_coins(
    p_sender_id uuid,
    p_receiver_id uuid,
    p_coin_amount bigint,
    p_source text DEFAULT 'gift'::text,
    p_item text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_sender_balance NUMERIC(20, 2); -- Changed from BIGINT to match table
  v_sender_created_at TIMESTAMPTZ;
  v_gift_id UUID := gen_random_uuid();
  v_bank_result json;
  v_credit_increase INTEGER;
  v_current_score INTEGER;
  v_new_score INTEGER;
BEGIN
  -- Check sender's paid coin balance and get created_at
  SELECT Troll_coins, created_at INTO v_sender_balance, v_sender_created_at
  FROM user_profiles
  WHERE id = p_sender_id;

  IF v_sender_balance IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sender not found');
  END IF;

  IF v_sender_balance < p_coin_amount THEN
    RETURN jsonb_build_object(
      'success', false, 
      'error', 'Not enough coins',
      'current_balance', v_sender_balance,
      'required', p_coin_amount
    );
  END IF;

  -- Deduct coins from sender
  UPDATE user_profiles
  SET 
    Troll_coins = Troll_coins - p_coin_amount,
    total_spent_coins = COALESCE(total_spent_coins, 0) + p_coin_amount,
    updated_at = now()
  WHERE id = p_sender_id;

  -- Grant XP to Sender (Spending XP) - 1 XP per coin spent
  PERFORM public.grant_xp(
    p_sender_id,
    p_coin_amount,
    'spend_coins',
    v_gift_id::text
  );

  -- Log Sender Transaction
  INSERT INTO coin_transactions (
    user_id, type, amount, coin_type, description, metadata, created_at
  ) VALUES (
    p_sender_id, 'gift_sent', -p_coin_amount, 'troll_coins', 
    format('Sent gift: %s', COALESCE(p_item, 'Gift')),
    jsonb_build_object('receiver_id', p_receiver_id, 'source', p_source, 'item', p_item, 'gift_id', v_gift_id),
    now()
  );

  -- Credit Receiver via Troll Bank
  -- Removed ::int cast on p_coin_amount
  SELECT public.troll_bank_credit_coins(
    p_receiver_id,
    p_coin_amount, -- Was p_coin_amount::int
    'gifted',
    'gift',
    v_gift_id::text,
    jsonb_build_object('sender_id', p_sender_id, 'item', p_item, 'source', p_source)
  ) INTO v_bank_result;

  -- Grant XP to Receiver (Receiving Gift XP) - 1 XP per coin value
  PERFORM public.grant_xp(
    p_receiver_id,
    p_coin_amount,
    'gift_received',
    v_gift_id::text
  );

  -- Insert gift record
  INSERT INTO gifts (
    id, sender_id, receiver_id, coins_spent, gift_type, message, created_at
  ) VALUES (
    v_gift_id, p_sender_id, p_receiver_id, p_coin_amount, 'paid', COALESCE(p_item, 'Gift'), now()
  );

  -- =================================================================
  -- CREDIT SCORE LOGIC UPDATE
  -- Rule: Increase credit score if account > 2 months old.
  -- Rate: 1 point for every 1000 coins.
  -- =================================================================
  
  -- Calculate potential increase
  v_credit_increase := FLOOR(p_coin_amount / 1000);

  -- Check eligibility: Account age > 2 months AND increase > 0
  IF v_credit_increase > 0 AND v_sender_created_at < (now() - INTERVAL '2 months') THEN
      
      -- Lock and get current score
      SELECT score INTO v_current_score
      FROM public.user_credit
      WHERE user_id = p_sender_id
      FOR UPDATE;

      -- If no credit record exists, one should be created (triggers usually handle this, but to be safe)
      IF v_current_score IS NULL THEN
          INSERT INTO public.user_credit (user_id, score, tier, trend_7d, updated_at)
          VALUES (p_sender_id, 400, 'Building', 0, now())
          RETURNING score INTO v_current_score;
      END IF;

      -- Calculate new score (Max 800)
      v_new_score := LEAST(800, v_current_score + v_credit_increase);

      IF v_new_score > v_current_score THEN
          -- Update User Credit
          UPDATE public.user_credit
          SET 
              score = v_new_score,
              tier = public.get_credit_tier(v_new_score),
              updated_at = now(),
              last_event_at = now()
          WHERE user_id = p_sender_id;

          -- Log Credit Event
          INSERT INTO public.credit_events (
              user_id,
              event_type,
              delta,
              source_table,
              source_id,
              metadata
          ) VALUES (
              p_sender_id,
              'gift_sent_bonus',
              v_new_score - v_current_score, -- Actual delta applied
              'gifts',
              v_gift_id,
              jsonb_build_object('coins_spent', p_coin_amount, 'calculation', '1 pt per 1000 coins')
          );
      END IF;
  END IF;

  -- Notification
  BEGIN
    PERFORM create_notification(
       p_receiver_id,
       'gift_received',
       'You received a gift!',
       jsonb_build_object(
         'sender_id', p_sender_id,
         'amount', p_coin_amount,
         'item', p_item,
         'gift_id', v_gift_id
       )
    );
  EXCEPTION WHEN OTHERS THEN
    -- Ignore notification errors
  END;

  RETURN jsonb_build_object('success', true, 'gift_id', v_gift_id);
END;
$$;

-- Function: spend_president_treasury
CREATE OR REPLACE FUNCTION public.spend_president_treasury(
  p_amount_cents BIGINT,
  p_reason TEXT,
  p_recipient_id UUID DEFAULT NULL
)
RETURNS VOID
SECURITY DEFINER
LANGUAGE plpgsql
AS $$
DECLARE
  v_daily_spend BIGINT;
  v_daily_limit BIGINT := 100000; -- $1000.00 limit per day
  v_max_tx BIGINT := 25000; -- $250.00 max per transaction
  v_actor_role TEXT;
BEGIN
  -- Determine Role (President or VP)
  IF EXISTS (
    SELECT 1 FROM user_role_grants urg
    JOIN system_roles sr ON urg.role_id = sr.id
    WHERE urg.user_id = auth.uid()
    AND sr.name = 'president'
    AND (urg.expires_at IS NULL OR urg.expires_at > NOW())
  ) THEN
    v_actor_role := 'president';
  ELSIF EXISTS (
    SELECT 1 FROM user_role_grants urg
    JOIN system_roles sr ON urg.role_id = sr.id
    WHERE urg.user_id = auth.uid()
    AND sr.name = 'vice_president'
    AND (urg.expires_at IS NULL OR urg.expires_at > NOW())
  ) THEN
    v_actor_role := 'vice_president';
  ELSE
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Check Limits
  IF p_amount_cents > v_max_tx THEN
    RAISE EXCEPTION 'Transaction exceeds maximum limit';
  END IF;

  -- Check Daily Spend
  SELECT COALESCE(SUM(ABS(amount_cents)), 0) INTO v_daily_spend
  FROM president_treasury_ledger
  WHERE actor_id = auth.uid()
  AND kind = 'spend'
  AND created_at > NOW() - INTERVAL '24 hours';

  IF v_daily_spend + p_amount_cents > v_daily_limit THEN
    RAISE EXCEPTION 'Daily spend limit exceeded';
  END IF;

  -- Deduct from Treasury
  INSERT INTO president_treasury_ledger (amount_cents, kind, currency, actor_id, metadata)
  VALUES (
    -p_amount_cents, 
    'spend', 
    'USD', 
    auth.uid(),
    jsonb_build_object('reason', p_reason, 'recipient_id', p_recipient_id)
  );

  -- Log to Government Actions Log
  PERFORM public.log_government_action(
    auth.uid(),
    v_actor_role,
    'spend_treasury',
    COALESCE(p_recipient_id::text, 'treasury'),
    jsonb_build_object(
        'amount_cents', p_amount_cents,
        'reason', p_reason,
        'currency', 'USD'
    )
  );
END;
$$;

-- Function: start_anonymous_round
CREATE OR REPLACE FUNCTION start_anonymous_round(
  p_show_id uuid,
  p_duration_seconds int DEFAULT 30
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_show_record record;
  v_max_duration int;
BEGIN
  -- Get show and verify auctioneer
  SELECT * INTO v_show_record FROM auction_shows WHERE id = p_show_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'reason', 'Show not found');
  END IF;

  -- Check if user is the auctioneer or admin
  IF NOT EXISTS (
    SELECT 1 FROM auctioneer_profiles ap
    WHERE ap.id = v_show_record.auctioneer_id AND ap.user_id = auth.uid()
  ) AND NOT EXISTS (
    SELECT 1 FROM user_profiles WHERE id = auth.uid() AND (is_admin = true OR role = 'admin')
  ) THEN
    RETURN json_build_object('success', false, 'reason', 'Only the auctioneer or admin can start an anonymous round');
  END IF;

  -- Validate duration
  v_max_duration := COALESCE(v_show_record.anonymous_round_max_duration, 120);
  IF p_duration_seconds < 10 OR p_duration_seconds > v_max_duration THEN
    RETURN json_build_object('success', false, 'reason', 'Duration must be between 10 and ' || v_max_duration || ' seconds');
  END IF;

  -- Check if show is live
  IF v_show_record.status != 'live' THEN
    RETURN json_build_object('success', false, 'reason', 'Show must be live to start anonymous round');
  END IF;

  -- Activate anonymous round
  UPDATE auction_shows SET
    is_anonymous_round_active = true,
    anonymous_round_ends_at = now() + (p_duration_seconds || ' seconds')::interval,
    anonymous_round_duration_seconds = p_duration_seconds,
    updated_at = now()
  WHERE id = p_show_id;

  RETURN json_build_object(
    'success', true,
    'ends_at', (now() + (p_duration_seconds || ' seconds')::interval)::text,
    'duration', p_duration_seconds
  );
END;
$$;

-- Function: start_broadcast_with_capacity_check
CREATE OR REPLACE FUNCTION public.start_broadcast_with_capacity_check(
  p_stream_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_stream public.streams%ROWTYPE;
  v_active integer;
  v_cap integer;
  v_cap_enabled boolean;
  v_restrictions_disabled boolean;
BEGIN
  IF p_stream_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'missing_stream_id',
      'active_broadcasts', 0, 'start_cap', NULL);
  END IF;

  -- Lock the caller's stream row (also enforces ownership below).
  SELECT *
    INTO v_stream
  FROM public.streams
  WHERE id = p_stream_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'stream_not_found',
      'active_broadcasts', 0, 'start_cap', NULL);
  END IF;

  -- Only the owner (or a service role) may start/activate this stream.
  IF v_stream.user_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'not_stream_owner',
      'active_broadcasts', 0, 'start_cap', NULL);
  END IF;

  -- Reconnecting to an already-active owned stream: never block.
  IF v_stream.is_live IS NOT DISTINCT FROM true
     AND COALESCE(v_stream.status, '') = 'live' THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'already_live',
      'active_broadcasts', 0, 'start_cap', NULL);
  END IF;

  -- Read configured restrictions (same settings used by useBroadcastViewerCap).
  v_restrictions_disabled := public._cap_setting_bool('broadcast_all_restrictions_disabled', false);
  v_cap_enabled := public._cap_setting_bool('broadcast_start_cap_enabled', false);
  v_cap := COALESCE(public._cap_setting_numeric('broadcast_start_cap_max', NULL)::integer, NULL);

  -- Count currently active broadcasts under a shared lock so concurrent starts
  -- serialize. Lock an arbitrary but stable settings row (the viewer cap max)
  -- to obtain a single serialization point without scanning every stream row.
  PERFORM 1
  FROM public.admin_settings
  WHERE setting_key = 'broadcast_start_cap_max'
  FOR UPDATE;

  SELECT COUNT(*)
    INTO v_active
  FROM public.streams s
  WHERE s.is_live IS NOT DISTINCT FROM true
    AND COALESCE(s.status, '') = 'live';

  IF NOT v_restrictions_disabled AND v_cap_enabled AND v_cap IS NOT NULL AND v_active >= v_cap THEN
    RETURN jsonb_build_object(
      'allowed', false, 'reason', 'broadcast_start_cap_reached',
      'active_broadcasts', v_active, 'start_cap', v_cap
    );
  END IF;

  -- Atomically transition this stream to live.
  UPDATE public.streams
  SET is_live = true,
      status = 'live',
      started_at = COALESCE(started_at, now())
  WHERE id = p_stream_id;

  RETURN jsonb_build_object(
    'allowed', true, 'reason', 'started',
    'active_broadcasts', v_active, 'start_cap', v_cap
  );
END;
$$;

-- Function: start_smoke_event
CREATE OR REPLACE FUNCTION public.start_smoke_event(
  p_stream_id uuid,
  p_seat_count integer DEFAULT 6
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id uuid;
  v_smoke_id uuid;
BEGIN
  v_user_id := auth.uid();

  IF NOT public._smoke_check_admin_or_host(p_stream_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only admin or stream host can start a smoke event');
  END IF;

  p_seat_count := GREATEST(1, LEAST(12, p_seat_count));

  UPDATE public.stream_smoke_events
  SET is_active = false, ended_at = now(), updated_at = now()
  WHERE stream_id = p_stream_id AND is_active = true;

  INSERT INTO public.stream_smoke_events (stream_id, created_by, seat_count)
  VALUES (p_stream_id, v_user_id, p_seat_count)
  RETURNING id INTO v_smoke_id;

  INSERT INTO public.stream_raffles (stream_id, smoke_event_id, created_by, next_draw_at)
  VALUES (p_stream_id, v_smoke_id, v_user_id, now() + interval '30 minutes');

  RETURN jsonb_build_object(
    'success', true,
    'smoke_event_id', v_smoke_id,
    'seat_count', p_seat_count,
    'message', 'Smoke Event started!'
  );
END;
$$;

-- Function: start_troll_drop
CREATE OR REPLACE FUNCTION public.start_troll_drop(
  p_stream_id uuid,
  p_coin_value integer,
  p_duration_seconds integer,
  p_total_bills integer DEFAULT 25
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_drop_id uuid;
  v_smoke record;
BEGIN
  IF NOT public._smoke_check_admin_or_host(p_stream_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only admin or stream host can start a troll drop');
  END IF;

  SELECT * INTO v_smoke FROM public.stream_smoke_events
  WHERE stream_id = p_stream_id AND is_active = true AND troll_drop_enabled = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active smoke event with Troll Drop enabled');
  END IF;

  IF p_duration_seconds NOT IN (3, 10, 30) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid duration. Use 3, 10, or 30 seconds.');
  END IF;

  p_coin_value := GREATEST(1, p_coin_value);
  p_total_bills := GREATEST(1, LEAST(500, p_total_bills));

  UPDATE public.troll_drops
  SET status = 'ended', ends_at = now()
  WHERE stream_id = p_stream_id AND status = 'active';

  INSERT INTO public.troll_drops (stream_id, created_by, coin_value, duration_seconds, total_bills, ends_at)
  VALUES (p_stream_id, auth.uid(), p_coin_value, p_duration_seconds, p_total_bills,
          now() + (p_duration_seconds || ' seconds')::interval)
  RETURNING id INTO v_drop_id;

  RETURN jsonb_build_object(
    'success', true,
    'drop_id', v_drop_id,
    'coin_value', p_coin_value,
    'duration_seconds', p_duration_seconds,
    'total_bills', p_total_bills,
    'message', 'Troll Drop started!'
  );
END;
$$;

-- Function: start_trollmers_monthly_tournament
CREATE OR REPLACE FUNCTION public.start_trollmers_monthly_tournament(p_month_start DATE DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_month_start DATE;
    v_tournament_id UUID;
    v_qualifiers RECORD;
    v_seed INTEGER := 0;
    v_bracket_matches JSONB := '[]'::jsonb;
    v_round1_position INTEGER := 1;
BEGIN
    -- Determine month start
    IF p_month_start IS NULL THEN
        v_month_start := public.get_trollmers_month_start(NOW());
    ELSE
        v_month_start := p_month_start;
    END IF;

    -- Check if tournament already exists
    IF EXISTS (
        SELECT 1 FROM public.trollmers_monthly_tournaments
        WHERE month_start = v_month_start
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Tournament already exists for this month');
    END IF;

    -- Get previous month start to aggregate weekly scores
    DECLARE
        v_prev_month_start DATE := v_month_start - INTERVAL '1 month';
        v_prev_month_end DATE := v_month_start - INTERVAL '1 day';
    BEGIN
        -- Create temporary table for monthly aggregation
        CREATE TEMP TABLE IF NOT EXISTS temp_monthly_scores AS
        SELECT
            user_id,
            SUM(score) AS total_score,
            SUM(wins) AS total_wins,
            SUM(losses) AS total_losses,
            SUM(coins_earned) AS total_coins
        FROM public.trollmers_weekly_leaderboard
        WHERE week_start >= v_prev_month_start
          AND week_start <= v_prev_month_end
        GROUP BY user_id
        ORDER BY total_score DESC, total_wins DESC
        LIMIT 16;

        -- Check if we have at least 4 qualifiers (minimum for tournament)
        IF (SELECT COUNT(*) FROM temp_monthly_scores) < 4 THEN
            DROP TABLE IF EXISTS temp_monthly_scores;
            RETURN jsonb_build_object('success', false, 'message', 'Not enough qualifiers (minimum 4 required)');
        END IF;

        -- Create tournament
        INSERT INTO public.trollmers_monthly_tournaments (month_start, status, started_at)
        VALUES (v_month_start, 'active', NOW())
        RETURNING id INTO v_tournament_id;

        -- Insert qualified participants with seeding
        INSERT INTO public.trollmers_tournament_participants (tournament_id, user_id, seed, status)
        SELECT v_tournament_id, user_id, ROW_NUMBER() OVER (ORDER BY total_score DESC, total_wins DESC), 'active'
        FROM temp_monthly_scores;

        -- Drop temp table
        DROP TABLE IF EXISTS temp_monthly_scores;
    END;

    -- Generate Round 1 bracket (Single Elimination - 16 players = 8 matches)
    -- Seeding: 1v16, 2v15, 3v14, 4v13, 5v12, 6v11, 7v10, 8v9
    FOR v_qualifiers IN
        SELECT
            p1.user_id AS seed_high,
            p2.user_id AS seed_low,
            p1.seed AS seed_high_num,
            p2.seed AS seed_low_num
        FROM public.trollmers_tournament_participants p1
        JOIN public.trollmers_tournament_participants p2
          ON p1.tournament_id = p2.tournament_id
         AND p1.seed + p2.seed = 17  -- Pairs: 1+16, 2+15, etc.
        WHERE p1.tournament_id = v_tournament_id
          AND p1.seed < p2.seed
        ORDER BY p1.seed
    LOOP
        INSERT INTO public.trollmers_tournament_battles (
            tournament_id,
            round,
            bracket_position,
            participant1_id,
            participant2_id,
            status
        ) VALUES (
            v_tournament_id,
            1,  -- Round 1 (Round of 16)
            v_round1_position,
            v_qualifiers.seed_high,
            v_qualifiers.seed_low,
            'pending'
        );

        v_round1_position := v_round1_position + 1;
    END LOOP;

    -- Post tournament start announcement to wall
    INSERT INTO public.wall_posts (user_id, content, visibility, created_at)
    VALUES (
        (SELECT id FROM public.user_profiles WHERE role = 'admin' LIMIT 1),
        '🏆 TROLLMERS MONTHLY TOURNAMENT HAS BEGUN! 🏆' || E'\n\n' ||
        '16 elite Trollmers have qualified for the Universe Championship!' || E'\n' ||
        'Head-to-head elimination battles start NOW. May the best Trollmer win!' || E'\n\n' ||
        '#TrollmersUniverse #MonthlyTournament',
        'public',
        NOW()
    );

    RETURN jsonb_build_object(
        'success', true,
        'tournament_id', v_tournament_id,
        'month_start', v_month_start,
        'qualifiers', (SELECT COUNT(*) FROM public.trollmers_tournament_participants WHERE tournament_id = v_tournament_id),
        'round1_matches', v_round1_position - 1
    );
END;
$$;

-- Function: stream_top_gifters
CREATE OR REPLACE FUNCTION public.stream_top_gifters(
    p_stream_id UUID,
    p_limit INT DEFAULT 8
)
RETURNS TABLE (
    sender_id UUID,
    sender_username TEXT,
    sender_avatar_url TEXT,
    total_gift_coins NUMERIC,
    total_gifts INTEGER,
    last_gift_at TIMESTAMPTZ
)
LANGUAGE SQL
STABLE
AS $$
SELECT
    sg.sender_id,
    COALESCE(up.username, 'Unknown') as sender_username,
    up.avatar_url as sender_avatar_url,
    SUM((sg.amount::NUMERIC) * (sg.quantity::NUMERIC)) as total_gift_coins,
    SUM(sg.quantity::INTEGER) as total_gifts,
    MAX(sg.created_at) as last_gift_at
FROM public.stream_gifts sg
LEFT JOIN public.user_profiles up ON up.id = sg.sender_id
WHERE sg.stream_id = p_stream_id
GROUP BY sg.sender_id, up.username, up.avatar_url
ORDER BY total_gift_coins DESC
LIMIT p_limit
$$;

-- Function: submit_advertisement
CREATE OR REPLACE FUNCTION public.submit_advertisement(
    p_title TEXT,
    p_subtitle TEXT,
    p_description TEXT,
    p_image_url TEXT,
    p_link_url TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_balance BIGINT;
    v_ad_id UUID;
BEGIN
    -- Check user balance
    SELECT troll_coins INTO v_user_balance
    FROM public.user_profiles
    WHERE id = auth.uid();

    IF v_user_balance < 1000 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient coins. Ads cost 1000 Troll Coins.');
    END IF;

    -- Deduct coins
    UPDATE public.user_profiles
    SET troll_coins = troll_coins - 1000
    WHERE id = auth.uid();

    -- Create ad record
    INSERT INTO public.user_advertisements (
        user_id, title, subtitle, description, image_url, link_url, cost_paid
    ) VALUES (
        auth.uid(), p_title, p_subtitle, p_description, p_image_url, p_link_url, 1000
    ) RETURNING id INTO v_ad_id;

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Advertisement submitted successfully and pending approval',
        'ad_id', v_ad_id
    );
END;
$$;

-- Function: submit_beta_feedback
CREATE OR REPLACE FUNCTION public.submit_beta_feedback(
  p_category text,
  p_title text,
  p_description text,
  p_affected_feature text DEFAULT NULL,
  p_affected_route text DEFAULT NULL,
  p_device_type text DEFAULT NULL,
  p_browser_name text DEFAULT NULL,
  p_user_agent text DEFAULT NULL,
  p_viewport_width integer DEFAULT NULL,
  p_viewport_height integer DEFAULT NULL,
  p_is_pwa boolean DEFAULT false,
  p_app_version text DEFAULT NULL,
  p_screenshot_url text DEFAULT NULL,
  p_severity text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET statement_timeout = '10s'
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_profile_exists boolean := false;
  v_title text := btrim(COALESCE(p_title, ''));
  v_description text := btrim(COALESCE(p_description, ''));
  v_category text := btrim(COALESCE(p_category, ''));
  v_severity text := btrim(COALESCE(p_severity, ''));
  v_device text := btrim(COALESCE(p_device_type, ''));
  v_row public.beta_feedback%ROWTYPE;
  v_existing_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = v_user_id)
    INTO v_profile_exists;
  IF NOT v_profile_exists THEN
    RETURN jsonb_build_object('success', false, 'error', 'User profile not found');
  END IF;

  IF public.is_user_chat_disabled(v_user_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'chat_disabled');
  END IF;

  IF v_category = '' OR v_category NOT IN (
    'Bug Report','Mobile / PWA','Broadcast','Chat','Neighborhoods','Troll Court',
    'Troll Coins','Performance','Account / Login','Design / UI','Feature Request','Other'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid category');
  END IF;

  IF char_length(v_title) < 5 OR char_length(v_title) > 150 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Title must be 5-150 characters');
  END IF;

  IF char_length(v_description) < 10 OR char_length(v_description) > 5000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Description must be 10-5000 characters');
  END IF;

  IF v_severity IS NOT NULL AND v_severity <> '' AND v_severity NOT IN
    ('minor','inconvenient','feature_blocking','app_unusable') THEN
    v_severity := NULL;
  END IF;

  IF v_device IS NOT NULL AND v_device <> '' AND v_device NOT IN
    ('iPhone','iPad','Android Phone','Android Tablet','Windows','macOS','Chromebook','Other') THEN
    v_device := NULL;
  END IF;

  -- Idempotency: if an identical submission exists in the last 30 seconds, return it.
  SELECT id INTO v_existing_id
  FROM public.beta_feedback
  WHERE user_id = v_user_id
    AND category = v_category
    AND title = v_title
    AND description = v_description
    AND created_at > now() - interval '30 seconds'
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    SELECT * INTO v_row FROM public.beta_feedback WHERE id = v_existing_id;
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'feedback', to_jsonb(v_row));
  END IF;

  INSERT INTO public.beta_feedback (
    user_id, category, title, description, affected_feature, affected_route,
    device_type, browser_name, user_agent, viewport_width, viewport_height,
    is_pwa, app_version, screenshot_url, severity
  ) VALUES (
    v_user_id, v_category, v_title, v_description,
    NULLIF(btrim(COALESCE(p_affected_feature, '')), ''),
    NULLIF(btrim(COALESCE(p_affected_route, '')), ''),
    v_device,
    NULLIF(btrim(COALESCE(p_browser_name, '')), ''),
    NULLIF(btrim(COALESCE(p_user_agent, '')), ''),
    p_viewport_width, p_viewport_height,
    COALESCE(p_is_pwa, false),
    NULLIF(btrim(COALESCE(p_app_version, '')), ''),
    NULLIF(btrim(COALESCE(p_screenshot_url, '')), ''),
    v_severity
  )
  RETURNING * INTO v_row;

  PERFORM public.log_beta_feedback_audit(
    v_row.id, v_user_id, 'submit',
    NULL,
    jsonb_build_object('category', v_row.category, 'title', v_row.title, 'status', v_row.status)
  );

  RETURN jsonb_build_object('success', true, 'duplicate', false, 'feedback', to_jsonb(v_row));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: submit_cashout_request
CREATE OR REPLACE FUNCTION public.submit_cashout_request(
    p_user_id UUID,
    p_amount_coins BIGINT,
    p_usd_value NUMERIC,
    p_provider TEXT,
    p_delivery_method TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_req_id UUID;
    v_has_prior_payouts BOOLEAN;
    v_is_held BOOLEAN := false;
    v_held_reason TEXT := NULL;
    v_release_date TIMESTAMPTZ := NULL;
    v_is_new_user_hold BOOLEAN := false;
BEGIN
    -- Check for prior successful payouts to determine if new user hold applies
    SELECT EXISTS (
        SELECT 1 FROM public.cashout_requests 
        WHERE user_id = p_user_id 
        AND status IN ('paid', 'fulfilled')
    ) INTO v_has_prior_payouts;

    IF NOT v_has_prior_payouts THEN
        v_is_held := true;
        v_held_reason := 'New User 7 Day Hold';
        v_release_date := NOW() + INTERVAL '7 days';
        v_is_new_user_hold := true;
    END IF;

    -- Create Request
    INSERT INTO public.cashout_requests (
        user_id, 
        requested_coins, 
        usd_value, 
        payout_method, 
        payout_details, 
        status,
        is_held,
        held_reason,
        release_date,
        is_new_user_hold
    ) VALUES (
        p_user_id, 
        p_amount_coins, 
        p_usd_value, 
        p_provider, 
        p_delivery_method, 
        'pending',
        v_is_held,
        v_held_reason,
        v_release_date,
        v_is_new_user_hold
    ) RETURNING id INTO v_req_id;

    -- Lock Coins
    BEGIN
        PERFORM public.troll_bank_escrow_coins(p_user_id, p_amount_coins, v_req_id);
    EXCEPTION WHEN OTHERS THEN
        -- If escrow fails, delete the request and re-raise
        DELETE FROM public.cashout_requests WHERE id = v_req_id;
        RAISE EXCEPTION 'Failed to escrow coins: %', SQLERRM;
    END;

    RETURN json_build_object(
        'success', true, 
        'request_id', v_req_id, 
        'is_held', v_is_held,
        'release_date', v_release_date
    );
END;
$$;

-- Function: submit_prediction
CREATE OR REPLACE FUNCTION submit_prediction(
  p_show_id uuid,
  p_predicted_winner_id uuid DEFAULT NULL,
  p_predicted_price int DEFAULT NULL,
  p_prediction_type text DEFAULT 'combined'
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_show_record record;
  v_settings record;
  v_existing_id uuid;
  v_result_id uuid;
BEGIN
  -- Check if predictions are enabled globally
  SELECT * INTO v_settings FROM auction_prediction_settings WHERE id = 1;
  IF NOT FOUND OR NOT v_settings.enabled_global THEN
    RETURN json_build_object('success', false, 'reason', 'Predictions are disabled globally');
  END IF;

  -- Get show
  SELECT * INTO v_show_record FROM auction_shows WHERE id = p_show_id;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'reason', 'Show not found');
  END IF;

  -- Check if predictions are enabled for this show
  IF NOT v_show_record.predictions_enabled THEN
    RETURN json_build_object('success', false, 'reason', 'Predictions are not enabled for this show');
  END IF;

  -- Check if predictions are locked
  IF v_show_record.predictions_locked THEN
    RETURN json_build_object('success', false, 'reason', 'Predictions are locked for this show');
  END IF;

  -- Check if show is live or scheduled
  IF v_show_record.status NOT IN ('live', 'scheduled') THEN
    RETURN json_build_object('success', false, 'reason', 'Predictions are only available for live or scheduled shows');
  END IF;

  -- Validate prediction type
  IF p_prediction_type NOT IN ('winner', 'price', 'combined') THEN
    RETURN json_build_object('success', false, 'reason', 'Invalid prediction type');
  END IF;

  -- Validate inputs based on type
  IF p_prediction_type = 'winner' AND p_predicted_winner_id IS NULL THEN
    RETURN json_build_object('success', false, 'reason', 'Predicted winner ID is required for winner predictions');
  END IF;

  IF p_prediction_type = 'price' AND p_predicted_price IS NULL THEN
    RETURN json_build_object('success', false, 'reason', 'Predicted price is required for price predictions');
  END IF;

  IF p_prediction_type = 'combined' AND (p_predicted_winner_id IS NULL OR p_predicted_price IS NULL) THEN
    RETURN json_build_object('success', false, 'reason', 'Both winner and price are required for combined predictions');
  END IF;

  -- Check for existing prediction
  SELECT id INTO v_existing_id FROM auction_predictions
  WHERE user_id = auth.uid() AND auction_show_id = p_show_id;

  IF v_existing_id IS NOT NULL THEN
    -- Update existing prediction (only if not locked)
    UPDATE auction_predictions SET
      predicted_winner_id = p_predicted_winner_id,
      predicted_price = p_predicted_price,
      prediction_type = p_prediction_type,
      updated_at = now()
    WHERE id = v_existing_id AND is_locked = false
    RETURNING id INTO v_result_id;

    IF v_result_id IS NULL THEN
      RETURN json_build_object('success', false, 'reason', 'Cannot update locked prediction');
    END IF;

    RETURN json_build_object('success', true, 'prediction_id', v_result_id, 'action', 'updated');
  ELSE
    -- Insert new prediction
    INSERT INTO auction_predictions (
      user_id, auction_show_id, predicted_winner_id, predicted_price,
      prediction_type, submitted_at, updated_at
    ) VALUES (
      auth.uid(), p_show_id, p_predicted_winner_id, p_predicted_price,
      p_prediction_type, now(), now()
    )
    RETURNING id INTO v_result_id;

    RETURN json_build_object('success', true, 'prediction_id', v_result_id, 'action', 'created');
  END IF;
END;
$$;

-- Function: subscribe_to_creator
CREATE OR REPLACE FUNCTION subscribe_to_creator(p_creator_id UUID)
RETURNS JSONB AS $$
DECLARE
    v_subscriber user_profiles%ROWTYPE;
    v_creator user_profiles%ROWTYPE;
    v_existing user_subscriptions%ROWTYPE;
    v_subscription_id UUID;
    v_price INTEGER;
    v_creator_amount INTEGER;
    v_ceo_amount INTEGER;
    v_ceo_id UUID;
    v_pay_success BOOLEAN;
BEGIN
    -- Get subscriber from auth
    SELECT * INTO v_subscriber FROM user_profiles WHERE id = auth.uid();
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Subscriber not authenticated');
    END IF;

    -- Get creator (broadcaster) - must have subscriptions enabled
    SELECT * INTO v_creator FROM user_profiles WHERE id = p_creator_id;
    IF NOT FOUND OR NOT v_creator.creator_subscription_enabled THEN
        RETURN jsonb_build_object('success', false, 'error', 'Creator subscriptions not available');
    END IF;

    v_price := COALESCE(v_creator.creator_subscription_price_coins, 100);
    v_creator_amount := (v_price * 90 / 100);
    v_ceo_amount := (v_price * 10 / 100);

    -- Prevent self-subscription
    IF v_subscriber.id = v_creator.id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot subscribe to yourself');
    END IF;

    -- Check for existing active subscription
    SELECT * INTO v_existing
    FROM user_subscriptions
    WHERE subscriber_id = v_subscriber.id 
      AND broadcaster_id = v_creator.id
      AND is_active = true;

    IF FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already subscribed to this creator');
    END IF;

    -- Level check from user_profiles only
    IF COALESCE(v_subscriber.level, 1) < 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Level 1 required to subscribe. Your level: ' || COALESCE(v_subscriber.level, 1));
    END IF;

    -- Check coin balance
    IF v_subscriber.troll_coins < v_price THEN
        RETURN jsonb_build_object(
            'success', false, 
            'error', 'Insufficient coins. Required: ' || v_price || '. You have: ' || v_subscriber.troll_coins
        );
    END IF;

    -- Get CEO ID (admin user)
    SELECT id INTO v_ceo_id
    FROM user_profiles
    WHERE role = 'admin' OR role = 'ceo'
    LIMIT 1;

    -- Use try_pay_coins (canonical coin spending with ledger logging)
    v_pay_success := public.try_pay_coins(v_subscriber.id, v_price, 'subscription', jsonb_build_object(
        'creator_id', p_creator_id,
        'type', 'creator_subscription'
    ));
    
    IF NOT v_pay_success THEN
        RETURN jsonb_build_object('success', false, 'error', 'Payment failed. Please try again.');
    END IF;

    -- Credit creator (90%)
    UPDATE user_profiles
    SET troll_coins = troll_coins + v_creator_amount
    WHERE id = v_creator.id;

    -- Credit CEO (10%) if found
    IF v_ceo_id IS NOT NULL THEN
        UPDATE user_profiles
        SET troll_coins = troll_coins + v_ceo_amount
        WHERE id = v_ceo_id;
    END IF;

    -- Create subscription record
    INSERT INTO user_subscriptions (
        subscriber_id, 
        broadcaster_id,
        price_paid_coins,
        creator_amount_coins,
        ceo_amount_coins,
        started_at,
        expires_at,
        is_active
    ) VALUES (
        v_subscriber.id,
        v_creator.id,
        v_price,
        v_creator_amount,
        v_ceo_amount,
        NOW(),
        NOW() + INTERVAL '30 days',
        true
    ) RETURNING id INTO v_subscription_id;

    -- Log revenue for creator
    INSERT INTO subscription_revenue_log (
        broadcaster_id, 
        subscription_id, 
        amount_coins,
        transaction_type, 
        status,
        notes
    ) VALUES (
        v_creator.id, 
        v_subscription_id, 
        v_price,
        'monthly_fee', 
        'completed',
        'Creator subscription - 90% to creator, 10% to CEO'
    );

    -- Update creator stats
    UPDATE user_profiles
    SET monthly_subscriber_count = COALESCE(monthly_subscriber_count, 0) + 1
    WHERE id = v_creator.id;

    -- Notify via realtime
    PERFORM pg_notify(
        'subscription_created',
        jsonb_build_object(
            'broadcaster_id', v_creator.id,
            'subscriber_id', v_subscriber.id,
            'subscriber_username', v_subscriber.username,
            'amount', v_price
        )::text
    );

    RETURN jsonb_build_object(
        'success', true,
        'subscription', jsonb_build_object(
            'id', v_subscription_id,
            'price_paid_coins', v_price,
            'creator_amount_coins', v_creator_amount,
            'ceo_amount_coins', v_ceo_amount
        )
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION subscribe_to_creator(UUID) TO authenticated;

-- ============================================
-- 2. FIX: create_subscription RPC
--    - Use auth.uid() for subscriber (NOT client-provided)
--    - Use try_pay_coins instead of direct UPDATE
--    - Check level from user_profiles only
--    - Add self-subscription check
-- ============================================

CREATE OR REPLACE FUNCTION create_subscription(
    p_broadcaster_id UUID,
    p_tier_id UUID,
    p_auto_renew BOOLEAN DEFAULT true
) RETURNS JSONB AS $$
DECLARE
    v_subscriber user_profiles%ROWTYPE;
    v_broadcaster user_profiles%ROWTYPE;
    v_tier subscription_tiers%ROWTYPE;
    v_existing user_subscriptions%ROWTYPE;
    v_new_subscription user_subscriptions%ROWTYPE;
    v_pay_success BOOLEAN;
BEGIN
    -- Get subscriber from auth (NOT from client parameter)
    SELECT * INTO v_subscriber FROM user_profiles WHERE id = auth.uid();
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Subscriber not authenticated');
    END IF;

    -- Level check from user_profiles only
    IF COALESCE(v_subscriber.level, 1) < 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Level 1 required to subscribe. Your level: ' || COALESCE(v_subscriber.level, 1));
    END IF;

    -- Get broadcaster
    SELECT * INTO v_broadcaster FROM user_profiles WHERE id = p_broadcaster_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Broadcaster not found');
    END IF;

    -- Prevent self-subscription
    IF v_subscriber.id = v_broadcaster.id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot subscribe to yourself');
    END IF;

    -- Get tier
    SELECT * INTO v_tier FROM subscription_tiers 
    WHERE id = p_tier_id AND is_active = true;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid subscription tier');
    END IF;

    -- Check existing subscription
    SELECT * INTO v_existing
    FROM user_subscriptions
    WHERE subscriber_id = v_subscriber.id 
      AND broadcaster_id = p_broadcaster_id 
      AND is_active = true;

    IF FOUND THEN
        -- Upgrade/Downgrade logic
        IF v_existing.tier_id = p_tier_id THEN
            RETURN jsonb_build_object('success', false, 'error', 'Already subscribed at this tier');
        END IF;
        
        -- Update subscription tier
        UPDATE user_subscriptions
        SET 
            tier_id = p_tier_id,
            total_paid_coins = total_paid_coins + v_tier.price_coins,
            updated_at = NOW()
        WHERE id = v_existing.id
        RETURNING * INTO v_new_subscription;
        
        -- Use try_pay_coins for upgrade payment
        v_pay_success := public.try_pay_coins(v_subscriber.id, v_tier.price_coins, 'subscription_upgrade', jsonb_build_object(
            'broadcaster_id', p_broadcaster_id,
            'tier_id', p_tier_id,
            'type', 'tier_upgrade'
        ));
        
        IF NOT v_pay_success THEN
            -- Rollback the tier update
            UPDATE user_subscriptions
            SET 
                tier_id = v_existing.tier_id,
                total_paid_coins = total_paid_coins - v_tier.price_coins,
                updated_at = NOW()
            WHERE id = v_existing.id;
            
            RETURN jsonb_build_object('success', false, 'error', 'Insufficient coins for upgrade');
        END IF;
        
        -- Add upgrade revenue
        UPDATE user_profiles
        SET total_subscriber_revenue_coins = total_subscriber_revenue_coins + v_tier.price_coins
        WHERE id = p_broadcaster_id;
        
        INSERT INTO subscription_revenue_log (
            broadcaster_id, subscription_id, amount_coins,
            transaction_type, status, notes
        ) VALUES (
            p_broadcaster_id, v_existing.id, v_tier.price_coins,
            'upgrade', 'completed', 'Tier upgrade'
        );
    ELSE
        -- New subscription - use try_pay_coins
        v_pay_success := public.try_pay_coins(v_subscriber.id, v_tier.price_coins, 'subscription', jsonb_build_object(
            'broadcaster_id', p_broadcaster_id,
            'tier_id', p_tier_id,
            'type', 'new_subscription'
        ));
        
        IF NOT v_pay_success THEN
            RETURN jsonb_build_object(
                'success', false, 
                'error', 'Insufficient coins. Required: ' || v_tier.price_coins || '. You have: ' || v_subscriber.troll_coins
            );
        END IF;

        -- Create subscription
        INSERT INTO user_subscriptions (
            subscriber_id, broadcaster_id, tier_id,
            started_at, expires_at, is_active,
            auto_renew, total_paid_coins
        ) VALUES (
            v_subscriber.id, p_broadcaster_id, p_tier_id,
            NOW(), 
            CASE 
                WHEN p_auto_renew THEN (NOW() + INTERVAL '30 days')
                ELSE NULL 
            END,
            true,
            p_auto_renew,
            v_tier.price_coins
        ) RETURNING * INTO v_new_subscription;

        -- Auto-follow: create follow relationship if not exists
        BEGIN
            INSERT INTO user_follows (follower_id, following_id)
            VALUES (v_subscriber.id, p_broadcaster_id)
            ON CONFLICT (follower_id, following_id) DO NOTHING;
        EXCEPTION
            WHEN OTHERS THEN
                RAISE NOTICE 'Follow creation failed: %', SQLERRM;
        END;

        -- Credit broadcaster's revenue balance
        UPDATE user_profiles
        SET 
            total_subscriber_revenue_coins = total_subscriber_revenue_coins + v_tier.price_coins,
            monthly_subscriber_count = monthly_subscriber_count + 1,
            subscriber_badge_color_hex = v_tier.color_hex
        WHERE id = p_broadcaster_id;

        -- Log transaction
        INSERT INTO subscription_revenue_log (
            broadcaster_id, subscription_id, amount_coins,
            transaction_type, status
        ) VALUES (
            p_broadcaster_id, v_new_subscription.id, v_tier.price_coins,
            'monthly_fee', 'completed'
        );

        -- Notify broadcaster via realtime
        PERFORM pg_notify(
            'subscription_created',
            jsonb_build_object(
                'broadcaster_id', p_broadcaster_id,
                'subscriber_id', v_subscriber.id,
                'subscriber_username', v_subscriber.username,
                'tier_id', p_tier_id,
                'tier_name', v_tier.name,
                'amount', v_tier.price_coins
            )::text
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'subscription', row_to_json(v_new_subscription),
        'tier', row_to_json(v_tier)
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION create_subscription(UUID, UUID, BOOLEAN) TO authenticated;

-- ============================================================
-- SMOKE EVENT SYSTEM - Migration (SAFE v4)
-- Tables first, then helper function, then RLS, then RPCs
-- ============================================================

-- ============================================================
-- TABLES (created first so helper function can reference them)
-- ============================================================

CREATE TABLE IF NOT EXISTS public.stream_smoke_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  created_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  is_active boolean DEFAULT true,
  seat_count integer DEFAULT 6 CHECK (seat_count >= 1 AND seat_count <= 12),
  raffle_enabled boolean DEFAULT true,
  troll_drop_enabled boolean DEFAULT true,
  song_queue_enabled boolean DEFAULT true,
  dj_user_id uuid REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  started_at timestamptz DEFAULT now(),
  ended_at timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_one_active_smoke_event_per_stream
  ON public.stream_smoke_events (stream_id) WHERE is_active = true;

CREATE TABLE IF NOT EXISTS public.troll_drops (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  created_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  coin_value integer NOT NULL CHECK (coin_value > 0),
  duration_seconds integer NOT NULL CHECK (duration_seconds IN (3, 10, 30)),
  total_bills integer NOT NULL DEFAULT 25 CHECK (total_bills > 0 AND total_bills <= 500),
  status text DEFAULT 'active' CHECK (status IN ('active', 'ended', 'cancelled')),
  started_at timestamptz DEFAULT now(),
  ends_at timestamptz NOT NULL,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.troll_drop_claims (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  troll_drop_id uuid NOT NULL REFERENCES public.troll_drops(id) ON DELETE CASCADE,
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  bill_index integer NOT NULL,
  coin_value integer NOT NULL,
  claimed_at timestamptz DEFAULT now(),
  UNIQUE(troll_drop_id, bill_index)
);

CREATE TABLE IF NOT EXISTS public.stream_song_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  requested_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  dj_user_id uuid REFERENCES public.user_profiles(id) ON DELETE SET NULL,
  song_title text NOT NULL,
  artist text,
  song_link text,
  total_cost integer DEFAULT 10,
  dj_share integer DEFAULT 5,
  admin_share integer DEFAULT 5,
  status text DEFAULT 'queued' CHECK (status IN ('queued', 'playing', 'played', 'skipped', 'refunded')),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.stream_raffles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  smoke_event_id uuid REFERENCES public.stream_smoke_events(id) ON DELETE CASCADE,
  created_by uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  ticket_cost integer DEFAULT 500,
  status text DEFAULT 'active' CHECK (status IN ('active', 'drawing', 'completed', 'cancelled')),
  draw_interval_minutes integer DEFAULT 30,
  current_round integer DEFAULT 1,
  next_draw_at timestamptz NOT NULL,
  started_at timestamptz DEFAULT now(),
  ended_at timestamptz,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.stream_raffle_tickets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  raffle_id uuid NOT NULL REFERENCES public.stream_raffles(id) ON DELETE CASCADE,
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  round_number integer NOT NULL DEFAULT 1,
  ticket_number bigint GENERATED ALWAYS AS IDENTITY,
  cost integer DEFAULT 500,
  purchased_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.stream_raffle_winners (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  raffle_id uuid NOT NULL REFERENCES public.stream_raffles(id) ON DELETE CASCADE,
  stream_id uuid NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  round_number integer NOT NULL,
  place integer NOT NULL CHECK (place IN (1, 2, 3)),
  user_id uuid NOT NULL REFERENCES public.user_profiles(id) ON DELETE CASCADE,
  prize_usd numeric(12,2) NOT NULL,
  selected_at timestamptz DEFAULT now(),
  payout_status text DEFAULT 'pending' CHECK (payout_status IN ('pending', 'approved', 'paid', 'void')),
  UNIQUE(raffle_id, round_number, place)
);

