ALTER TABLE public.stream_raffle_tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stream_raffle_winners ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "smoke_events_read" ON public.stream_smoke_events;
CREATE POLICY "smoke_events_read" ON public.stream_smoke_events FOR SELECT USING (true);
DROP POLICY IF EXISTS "smoke_events_write" ON public.stream_smoke_events;
CREATE POLICY "smoke_events_write" ON public.stream_smoke_events FOR ALL
  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND (role = 'admin' OR is_admin = true OR role = 'owner')));

DROP POLICY IF EXISTS "troll_drops_read" ON public.troll_drops;
CREATE POLICY "troll_drops_read" ON public.troll_drops FOR SELECT USING (true);
DROP POLICY IF EXISTS "troll_drops_write" ON public.troll_drops;
CREATE POLICY "troll_drops_write" ON public.troll_drops FOR ALL
  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND (role = 'admin' OR is_admin = true OR role = 'owner')));

DROP POLICY IF EXISTS "troll_drop_claims_read" ON public.troll_drop_claims;
CREATE POLICY "troll_drop_claims_read" ON public.troll_drop_claims FOR SELECT USING (true);
DROP POLICY IF EXISTS "troll_drop_claims_insert" ON public.troll_drop_claims;
CREATE POLICY "troll_drop_claims_insert" ON public.troll_drop_claims FOR INSERT
  WITH CHECK (user_id = auth.uid());

DROP POLICY IF EXISTS "song_requests_read" ON public.stream_song_requests;
CREATE POLICY "song_requests_read" ON public.stream_song_requests FOR SELECT USING (true);
DROP POLICY IF EXISTS "song_requests_insert" ON public.stream_song_requests;
CREATE POLICY "song_requests_insert" ON public.stream_song_requests FOR INSERT
  WITH CHECK (requested_by = auth.uid());

DROP POLICY IF EXISTS "raffles_read" ON public.stream_raffles;
CREATE POLICY "raffles_read" ON public.stream_raffles FOR SELECT USING (true);
DROP POLICY IF EXISTS "raffles_write" ON public.stream_raffles;
CREATE POLICY "raffles_write" ON public.stream_raffles FOR ALL
  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND (role = 'admin' OR is_admin = true OR role = 'owner')));

DROP POLICY IF EXISTS "raffle_tickets_read" ON public.stream_raffle_tickets;
CREATE POLICY "raffle_tickets_read" ON public.stream_raffle_tickets FOR SELECT USING (true);
DROP POLICY IF EXISTS "raffle_tickets_insert" ON public.stream_raffle_tickets;
CREATE POLICY "raffle_tickets_insert" ON public.stream_raffle_tickets FOR INSERT
  WITH CHECK (user_id = auth.uid());

DROP POLICY IF EXISTS "raffle_winners_read" ON public.stream_raffle_winners;
CREATE POLICY "raffle_winners_read" ON public.stream_raffle_winners FOR SELECT USING (true);
DROP POLICY IF EXISTS "raffle_winners_write" ON public.stream_raffle_winners;
CREATE POLICY "raffle_winners_write" ON public.stream_raffle_winners FOR ALL
  USING (EXISTS (SELECT 1 FROM public.user_profiles WHERE id = auth.uid() AND (role = 'admin' OR is_admin = true OR role = 'owner')));

-- ============================================================
-- HELPER FUNCTION (after tables exist)
-- ============================================================
CREATE OR REPLACE FUNCTION public._smoke_check_admin_or_host(p_stream_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.id = auth.uid()
      AND (
        up.role = 'admin'
        OR up.is_admin = true
        OR up.role = 'owner'
        OR EXISTS (
          SELECT 1 FROM public.streams s
          WHERE s.id = p_stream_id AND s.user_id = auth.uid()
        )
      )
  );
$$;

-- Function: subscribe_verification_coins
CREATE OR REPLACE FUNCTION public.subscribe_verification_coins(
  p_user_id UUID,
  p_amount_coins INTEGER DEFAULT 500
)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_now TIMESTAMP WITH TIME ZONE := now();
  v_expires TIMESTAMP WITH TIME ZONE;
  v_subscription_id TEXT;
  v_current_coins INTEGER;
BEGIN
  -- Check coin balance
  SELECT COALESCE(troll_coins, 0) INTO v_current_coins
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF v_current_coins < p_amount_coins THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Insufficient coins. Need ' || p_amount_coins || ' but have ' || v_current_coins
    );
  END IF;

  -- Calculate expiration (30 days from now)
  v_expires := v_now + INTERVAL '30 days';
  v_subscription_id := 'ver_' || substr(md5(random()::text), 1, 12);

  -- Deduct coins and update profile
  UPDATE public.user_profiles
  SET
    troll_coins = troll_coins - p_amount_coins,
    is_verified = true,
    verified_since = COALESCE(verified_since, v_now),
    verification_subscription_id = v_subscription_id,
    verification_expires_at = v_expires,
    badge_type = 'verified',
    verification_payment_method = 'coins',
    verification_paid_amount = p_amount_coins,
    updated_at = v_now
  WHERE id = p_user_id;

  -- Insert subscription record
  INSERT INTO public.verification_subscriptions (
    user_id, subscription_id, payment_method, amount_coins,
    status, started_at, expires_at
  ) VALUES (
    p_user_id, v_subscription_id, 'coins', p_amount_coins,
    'active', v_now, v_expires
  );

  RETURN json_build_object(
    'success', true,
    'subscription_id', v_subscription_id,
    'expires_at', v_expires
  );
END;
$$;

-- Function: summon_user_to_court
CREATE OR REPLACE FUNCTION public.summon_user_to_court(
--     p_defendant_id UUID,
--     p_reason TEXT,
--     p_users_involved UUID[] DEFAULT ARRAY[]::uuid[],
--     p_docket_id UUID DEFAULT NULL
-- )
-- ============================================================================

-- Create audit log table if it doesn't exist (for structured logging)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' 
        AND table_name = 'court_summons_log'
    ) THEN
        CREATE TABLE public.court_summons_log (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            defendant_id UUID NOT NULL,
            docket_id UUID NOT NULL,
            officer_id UUID NOT NULL,
            users_involved TEXT[],
            created_at TIMESTAMPTZ DEFAULT now()
        );
        
        -- Grant permissions
        GRANT SELECT ON public.court_summons_log TO authenticated;
        GRANT SELECT ON public.court_summons_log TO anon;
        
        -- Create index for querying
        CREATE INDEX idx_court_summons_log_defendant ON public.court_summons_log(defendant_id);
        CREATE INDEX idx_court_summons_log_officer ON public.court_summons_log(officer_id);
        CREATE INDEX idx_court_summons_log_created ON public.court_summons_log(created_at DESC);
        
        RAISE NOTICE 'Created court_summons_log table for audit trail';
    END IF;
END $$;

-- Function: toggle_post_like
CREATE OR REPLACE FUNCTION public.toggle_post_like(p_post_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_liked BOOLEAN;
    v_count INTEGER;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized');
    END IF;

    -- Check if already liked (reaction_type = 'like')
    IF EXISTS (SELECT 1 FROM public.troll_post_reactions WHERE post_id = p_post_id AND user_id = v_user_id AND reaction_type = 'like') THEN
        DELETE FROM public.troll_post_reactions WHERE post_id = p_post_id AND user_id = v_user_id AND reaction_type = 'like';
        v_liked := false;
    ELSE
        INSERT INTO public.troll_post_reactions (post_id, user_id, reaction_type) VALUES (p_post_id, v_user_id, 'like');
        v_liked := true;
    END IF;

    -- Get new count
    SELECT count(*) INTO v_count FROM public.troll_post_reactions WHERE post_id = p_post_id AND reaction_type = 'like';

    RETURN jsonb_build_object('success', true, 'liked', v_liked, 'count', v_count);
END;
$$;

-- Function: toggle_wall_post_pin
create or replace function public.toggle_wall_post_pin(
  p_post_id uuid,
  p_user_id uuid
) returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_is_pinned boolean;
  v_owner uuid;
  v_role text;
  v_is_admin boolean;
  v_is_secretary boolean;
  v_troll_role text;
  v_is_lead_officer boolean;
  v_can_pin boolean;
begin
  select is_pinned, user_id into v_is_pinned, v_owner from troll_wall_posts where id = p_post_id;
  if not found then
    raise exception 'Post not found';
  end if;

  select 
    role, 
    is_admin, 
    (troll_role = 'secretary') as is_secretary,
    troll_role,
    coalesce(is_lead_officer, false)
  into 
    v_role, 
    v_is_admin, 
    v_is_secretary,
    v_troll_role,
    v_is_lead_officer
  from user_profiles where id = p_user_id;

  v_can_pin := 
    p_user_id = v_owner
    or coalesce(v_is_admin, false)
    or coalesce(v_role, '') in ('admin','secretary','lead_troll_officer')
    or coalesce(v_troll_role, '') in ('secretary','lead_troll_officer','troll_officer')
    or v_is_lead_officer;

  if not v_can_pin then
    raise exception 'Forbidden';
  end if;

  update troll_wall_posts set is_pinned = not coalesce(v_is_pinned, false) where id = p_post_id returning is_pinned into v_is_pinned;
  return v_is_pinned;
end;
$$;

-- Function: troll_bank_credit_coins
CREATE OR REPLACE FUNCTION public.troll_bank_credit_coins(
    p_user_id uuid,
    p_coins numeric, -- Changed from int
    p_bucket text,        -- 'paid' | 'gifted' | 'promo' | 'loan'
    p_source text,        -- 'coin_purchase' | 'gift' | 'admin_grant' | 'loan_disbursement' | etc.
    p_ref_id text DEFAULT NULL,
    p_metadata jsonb DEFAULT NULL
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER -- Runs as owner (postgres/admin) to bypass RLS for updates
AS $$
DECLARE
    v_user_balance numeric(20, 2); -- Changed from bigint
    v_loan_record record;
    v_repay_amount numeric(20, 2) := 0; -- Changed from bigint
    v_user_gets numeric(20, 2); -- Changed from bigint
    v_new_loan_balance numeric(20, 2); -- Changed from bigint
    v_loan_status text;
    v_gift_repay_enabled boolean := false;
BEGIN
    -- Validate p_coins > 0
    IF p_coins <= 0 THEN
        RAISE EXCEPTION 'Coins must be positive';
    END IF;

    -- Check feature flags for gift repayment
    -- We assume bank_feature_flags table exists (created in 20260120000001)
    BEGIN
        SELECT is_enabled INTO v_gift_repay_enabled
        FROM public.bank_feature_flags
        WHERE key = 'gift_repayment_enabled';
    EXCEPTION WHEN OTHERS THEN
        -- If table doesn't exist or other error, default to false
        v_gift_repay_enabled := false;
    END;
    
    v_gift_repay_enabled := COALESCE(v_gift_repay_enabled, false);

    -- Lock user profile row to prevent race conditions on balance
    SELECT troll_coins INTO v_user_balance
    FROM public.user_profiles
    WHERE id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    -- Lock active loan row if exists
    SELECT * INTO v_loan_record
    FROM public.loans
    WHERE user_id = p_user_id AND status = 'active'
    LIMIT 1
    FOR UPDATE;

    -- Determine repayment eligibility
    -- Eligible if:
    -- 1. Active loan exists
    -- 2. Bucket is 'paid' OR (bucket is 'gifted' AND feature flag is on)
    IF v_loan_record IS NOT NULL THEN
        IF p_bucket = 'paid' OR (p_bucket = 'gifted' AND v_gift_repay_enabled) THEN
             -- repay = min(loan_balance, floor(p_coins * 0.50))
             v_repay_amount := LEAST(v_loan_record.balance, FLOOR(p_coins * 0.50));
        END IF;
    END IF;

    v_user_gets := p_coins - v_repay_amount;

    -- Insert ledger rows
    -- a) Repayment
    IF v_repay_amount > 0 THEN
        INSERT INTO public.coin_ledger (user_id, delta, bucket, source, ref_id, metadata)
        VALUES (p_user_id, -v_repay_amount, 'repayment', 'auto_repay', p_ref_id, p_metadata);

        -- Update loan
        UPDATE public.loans
        SET balance = balance - v_repay_amount,
            status = CASE WHEN balance - v_repay_amount <= 0 THEN 'paid' ELSE status END,
            closed_at = CASE WHEN balance - v_repay_amount <= 0 THEN now() ELSE closed_at END
        WHERE id = v_loan_record.id
        RETURNING balance, status INTO v_new_loan_balance, v_loan_status;
    ELSE
        v_new_loan_balance := CASE WHEN v_loan_record IS NOT NULL THEN v_loan_record.balance ELSE 0 END;
        v_loan_status := CASE WHEN v_loan_record IS NOT NULL THEN v_loan_record.status ELSE 'none' END;
    END IF;

    -- b) Credit
    IF v_user_gets > 0 THEN
        INSERT INTO public.coin_ledger (user_id, delta, bucket, source, ref_id, metadata)
        VALUES (p_user_id, v_user_gets, p_bucket, p_source, p_ref_id, p_metadata);
    END IF;

    -- Update user balance (troll_coins)
    UPDATE public.user_profiles
    SET troll_coins = troll_coins + v_user_gets
    WHERE id = p_user_id;

    RETURN json_build_object(
        'repay', v_repay_amount,
        'user_gets', v_user_gets,
        'new_loan_balance', v_new_loan_balance,
        'loan_status', v_loan_status
    );
END;
$$;

-- Function: troll_bank_spend_coins
CREATE OR REPLACE FUNCTION public.troll_bank_spend_coins(
  p_user_id uuid,
  p_amount numeric, -- Changed from int
  p_bucket text default 'paid',
  p_source text default 'purchase',
  p_ref_id text default null,
  p_metadata jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
as $$
declare
  v_current_balance numeric(20, 2); -- Changed from int
  v_new_balance numeric(20, 2);     -- Changed from int
  v_ledger_id uuid;
begin
  -- Validate amount
  if p_amount <= 0 then
    return jsonb_build_object('success', false, 'error', 'Amount must be positive');
  end if;

  -- Lock user profile and check balance
  select troll_coins into v_current_balance
  from user_profiles
  where id = p_user_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'error', 'User not found');
  end if;

  if v_current_balance < p_amount then
    return jsonb_build_object('success', false, 'error', 'Insufficient funds', 'current_balance', v_current_balance);
  end if;

  -- Deduct coins
  v_new_balance := v_current_balance - p_amount;
  
  update user_profiles
  set troll_coins = v_new_balance
  where id = p_user_id;

  -- Insert into ledger (negative delta)
  insert into coin_ledger (
    user_id,
    delta,
    bucket,
    source,
    ref_id,
    metadata,
    direction
  ) values (
    p_user_id,
    -p_amount,
    p_bucket,
    p_source,
    p_ref_id,
    p_metadata,
    'out'
  ) returning id into v_ledger_id;

  return jsonb_build_object(
    'success', true,
    'new_balance', v_new_balance,
    'ledger_id', v_ledger_id
  );
end;
$$;

-- Function: troll_bank_spend_coins_secure
CREATE OR REPLACE FUNCTION public.troll_bank_spend_coins_secure(
  p_user_id uuid,
  p_amount numeric, -- Changed from int
  p_bucket text default 'paid',
  p_source text default 'purchase',
  p_ref_id text default null,
  p_metadata jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
as $$
begin
  -- Check if caller is the user or service role
  if auth.uid() != p_user_id and auth.role() != 'service_role' then
    return jsonb_build_object('success', false, 'error', 'Unauthorized');
  end if;

  return troll_bank_spend_coins(p_user_id, p_amount, p_bucket, p_source, p_ref_id, p_metadata);
end;
$$;

-- Function: troll_opponent
CREATE OR REPLACE FUNCTION public.troll_opponent(
  p_battle_id uuid,
  p_troller_id uuid,
  p_target_stream_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_battle public.battles%ROWTYPE;
  v_troller_team text;
  v_target_user_id uuid;
  v_target_coins numeric;
  v_deduction_amount numeric;
  v_seconds_until_end integer;
BEGIN
  SELECT *
    INTO v_battle
  FROM public.battles
  WHERE id = p_battle_id
  FOR UPDATE;

  IF NOT FOUND OR v_battle.status <> 'active' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Battle not found or not active');
  END IF;

  IF EXISTS (SELECT 1 FROM public.streams WHERE id = v_battle.challenger_stream_id AND user_id = p_troller_id) THEN
    v_troller_team := 'challenger';
  ELSIF EXISTS (SELECT 1 FROM public.streams WHERE id = v_battle.opponent_stream_id AND user_id = p_troller_id) THEN
    v_troller_team := 'opponent';
  ELSE
    RETURN jsonb_build_object('success', false, 'message', 'User is not a broadcaster in this battle');
  END IF;

  IF v_troller_team = 'challenger' AND p_target_stream_id <> v_battle.opponent_stream_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Can only troll the opponent');
  END IF;

  IF v_troller_team = 'opponent' AND p_target_stream_id <> v_battle.challenger_stream_id THEN
    RETURN jsonb_build_object('success', false, 'message', 'Can only troll the opponent');
  END IF;

  v_seconds_until_end := EXTRACT(EPOCH FROM (COALESCE(v_battle.ends_at, v_battle.started_at + interval '3 minutes') - now()))::integer;

  IF v_seconds_until_end > 15 OR v_seconds_until_end <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Sudden troll is only available in the last 15 seconds');
  END IF;

  SELECT user_id INTO v_target_user_id
  FROM public.streams
  WHERE id = p_target_stream_id;

  SELECT troll_coins INTO v_target_coins
  FROM public.user_profiles
  WHERE id = v_target_user_id
  FOR UPDATE;

  IF COALESCE(v_target_coins, 0) <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Target has no coins to troll');
  END IF;

  v_deduction_amount := GREATEST(1, CEIL(v_target_coins * 0.01));

  UPDATE public.user_profiles
  SET troll_coins = GREATEST(0, COALESCE(troll_coins, 0) - v_deduction_amount)
  WHERE id = v_target_user_id;

  IF v_troller_team = 'challenger' THEN
    UPDATE public.battles
    SET score_challenger = COALESCE(score_challenger, 0) + v_deduction_amount::integer
    WHERE id = p_battle_id;
  ELSE
    UPDATE public.battles
    SET score_opponent = COALESCE(score_opponent, 0) + v_deduction_amount::integer
    WHERE id = p_battle_id;
  END IF;

  INSERT INTO public.battle_events (battle_id, event_type, user_id, target_user_id, amount, metadata)
  VALUES (
    p_battle_id,
    'troll',
    p_troller_id,
    v_target_user_id,
    v_deduction_amount,
    jsonb_build_object('troller_team', v_troller_team, 'target_coins_before', v_target_coins, 'sudden_troll_seconds_left', v_seconds_until_end)
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Sudden troll successful!',
    'deduction', v_deduction_amount,
    'target_coins_before', v_target_coins,
    'target_coins_after', GREATEST(0, v_target_coins - v_deduction_amount)
  );
END;
$$;

-- Function: try_pay_coins_secure
CREATE OR REPLACE FUNCTION public.try_pay_coins_secure(
    p_amount BIGINT,
    p_reason TEXT,
