-- Function: try_pay_with_credit_card
CREATE OR REPLACE FUNCTION public.try_pay_with_credit_card(
    p_user_id UUID,
    p_amount BIGINT,
    p_context TEXT,
    p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_allowed_contexts TEXT[] := ARRAY['shop_purchase', 'vehicle_purchase', 'insurance_payment', 'platform_fee', 'consumable_purchase'];
    v_forbidden_contexts TEXT[] := ARRAY['gift', 'transfer', 'rent', 'p2p_purchase', 'tip', 'payout'];
    v_charged BIGINT;
    v_description TEXT;
BEGIN
    -- Validate context
    IF p_context = ANY(v_forbidden_contexts) THEN
        RETURN FALSE;
    END IF;
    IF NOT (p_context = ANY(v_allowed_contexts)) THEN
        RETURN FALSE;
    END IF;

    BEGIN
        v_description := 'Credit Card: ' || COALESCE(p_context, 'purchase');
        v_charged := public.draw_credit_internal(
            p_user_id,
            p_amount,
            v_description,
            p_context,
            p_metadata
        );

        -- Log to coin_ledger (no coin change, just record the credit spend)
        INSERT INTO public.coin_ledger (user_id, delta, bucket, source, reason, metadata)
        VALUES (
            p_user_id,
            0,
            'credit_spend',
            'credit_card',
            v_description,
            p_metadata || jsonb_build_object('principal', v_charged, 'context', p_context)
        );

        -- Credit score penalty for using credit (smaller than before — only -5)
        -- Real credit cards don't ding you for using them, only for carrying balance
        INSERT INTO public.credit_events (user_id, event_type, delta, event_key, metadata)
        VALUES (
            p_user_id,
            'credit_cc_purchase',
            -5,
            'cc_purchase:' || p_user_id::text || ':' || EXTRACT(EPOCH FROM NOW())::bigint,
            jsonb_build_object('principal', v_charged, 'context', p_context)
        );

        -- Recalculate score
        UPDATE public.user_credit uc
           SET score = GREATEST(0, LEAST(400 + e.net_delta, 800)),
               tier = public.get_credit_tier(GREATEST(0, LEAST(400 + e.net_delta, 800))),
               updated_at = NOW(),
               last_event_at = NOW()
         FROM (SELECT user_id, SUM(delta) AS net_delta
                 FROM public.credit_events
                WHERE user_id = p_user_id
                GROUP BY user_id) e
         WHERE uc.user_id = e.user_id;

        UPDATE public.user_profiles
           SET credit_score = (SELECT score FROM public.user_credit WHERE user_id = p_user_id)
         WHERE id = p_user_id;

        RETURN TRUE;
    EXCEPTION WHEN OTHERS THEN
        RETURN FALSE;
    END;
END;
$$;

-- Function: universe_event_public_summary
CREATE OR REPLACE FUNCTION public.universe_event_public_summary(p_event_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_event public.universe_events;
  v_reg_count INTEGER;
  v_confirmed INTEGER;
BEGIN
  SELECT * INTO v_event FROM public.universe_events e WHERE e.id = p_event_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status IN ('confirmed','matched','scheduled','checked_in','active'))
    INTO v_reg_count, v_confirmed
  FROM public.universe_registrations r
  WHERE r.event_id = p_event_id
    AND status NOT IN ('withdrawn','cancelled');

  RETURN jsonb_build_object(
    'found', true,
    'event_id', v_event.id,
    'title', v_event.title,
    'event_date', v_event.event_date,
    'scheduled_start', v_event.scheduled_start,
    'timezone', v_event.timezone,
    'registration_opens_at', v_event.registration_opens_at,
    'registration_closes_at', v_event.registration_closes_at,
    'seat_lock_at', v_event.seat_lock_at,
    'check_in_opens_at', v_event.check_in_opens_at,
    'room_opens_at', v_event.room_opens_at,
    'opponent_reveal_at', v_event.opponent_reveal_at,
    'status', v_event.status,
    'registration_count', v_reg_count,
    'confirmed_count', v_confirmed
  );
END;
$$;

