-- Function: update_appeal_media
CREATE OR REPLACE FUNCTION public.update_appeal_media(
    p_appeal_id UUID,
    p_images JSONB DEFAULT '[]',
    p_videos JSONB DEFAULT '[]',
    p_image_metadata JSONB DEFAULT '[]',
    p_video_metadata JSONB DEFAULT '[]'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_appeal RECORD;
    v_user_id UUID;
BEGIN
    -- Get current user
    v_user_id := auth.uid();
    
    -- Get appeal details
    SELECT * INTO v_appeal
    FROM public.transaction_appeals
    WHERE id = p_appeal_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Appeal not found');
    END IF;
    
    -- Verify user owns the appeal
    IF v_appeal.user_id != v_user_id THEN
        -- Check if admin
        IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = v_user_id AND is_admin = true) THEN
            RETURN jsonb_build_object('success', false, 'error', 'Not authorized to update this appeal');
        END IF;
    END IF;
    
    -- Check appeal is still pending
    IF v_appeal.status NOT IN ('pending', 'under_review') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot update appeal that is already decided');
    END IF;
    
    -- Update appeal with media
    UPDATE public.transaction_appeals
    SET images = p_images,
        videos = p_videos,
        image_metadata = p_image_metadata,
        video_metadata = p_video_metadata,
        updated_at = NOW()
    WHERE id = p_appeal_id;
    
    RETURN jsonb_build_object(
        'success', true,
        'appeal_id', p_appeal_id,
        'images_count', jsonb_array_length(p_images),
        'videos_count', jsonb_array_length(p_videos)
    );
END;
$$;

-- Function: update_glow_color
CREATE OR REPLACE FUNCTION update_glow_color(
    p_color TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_user_id UUID;
    v_has_perk BOOLEAN;
BEGIN
    v_user_id := auth.uid();

    -- Check if user has active RGB perk
    SELECT EXISTS (
        SELECT 1 FROM user_perks
        WHERE user_id = v_user_id
          AND perk_id = 'perk_rgb_username'
          AND is_active = true
          AND (expires_at IS NULL OR expires_at > NOW())
    ) INTO v_has_perk;

    IF NOT v_has_perk THEN
        RAISE EXCEPTION 'You do not have an active RGB Username perk.';
    END IF;

    -- Set bypass flag to allow update to restricted column
    PERFORM set_config('app.bypass_coin_protection', 'true', true);

    UPDATE user_profiles
    SET glowing_username_color = p_color,
        updated_at = NOW()
    WHERE id = v_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Function: update_mission_progress
CREATE OR REPLACE FUNCTION update_mission_progress(
  p_stream_id UUID,
  p_user_id UUID,
  p_metric TEXT,
  p_value INTEGER
) RETURNS JSONB AS $$
DECLARE
  mission RECORD;
  user_prog RECORD;
  result JSONB := '{"updated": [], "completed": []}';
BEGIN
  -- Loop through active missions for this stream matching the metric
  FOR mission IN
    SELECT * FROM stream_missions
    WHERE stream_id = p_stream_id
    AND status = 'active'
    AND target_metric = p_metric
    AND (expires_at IS NULL OR expires_at > now())
  LOOP
    -- Update stream-level progress
    UPDATE stream_missions
    SET current_value = LEAST(current_value + p_value, target_value),
        status = CASE WHEN current_value + p_value >= target_value THEN 'completed' ELSE status END,
        completed_at = CASE WHEN current_value + p_value >= target_value THEN now() ELSE completed_at END
    WHERE id = mission.id;

    -- For solo/competitive missions, track individual progress
    IF mission.mission_type IN ('solo', 'competitive') THEN
      INSERT INTO user_mission_progress (user_id, mission_id, stream_id, progress_value)
      VALUES (p_user_id, mission.id, p_stream_id, p_value)
      ON CONFLICT (user_id, mission_id)
      DO UPDATE SET progress_value = LEAST(user_mission_progress.progress_value + p_value, mission.target_value),
                    completed_at = CASE WHEN user_mission_progress.progress_value + p_value >= mission.target_value THEN now() ELSE NULL END;
    END IF;

    -- Check if mission completed and handle chain escalation
    IF mission.current_value + p_value >= mission.target_value THEN
      result := jsonb_set(result, '{completed}', (result->'completed') || to_jsonb(mission.id));

      -- Auto-escalate chain missions
      IF mission.chain_group IS NOT NULL THEN
        UPDATE stream_missions
        SET status = 'active',
            starts_at = now()
        WHERE stream_id = p_stream_id
        AND chain_group = mission.chain_group
        AND chain_order = mission.chain_order + 1
        AND status = 'chained';
      END IF;
    END IF;

    result := jsonb_set(result, '{updated}', (result->'updated') || to_jsonb(mission.id));
  END LOOP;

  RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Auto-generate missions for a stream
CREATE OR REPLACE FUNCTION generate_stream_missions(p_stream_id UUID)
RETURNS VOID AS $$
DECLARE
  template RECORD;
BEGIN
  -- Insert missions from active templates
  FOR template IN
    SELECT * FROM mission_templates
    WHERE is_active = true
    ORDER BY difficulty, chain_group, chain_order
  LOOP
    INSERT INTO stream_missions (
      stream_id, mission_template_id, name, description, mission_type,
      target_metric, target_value, difficulty, chain_group, chain_order,
      status, expires_at, xp_reward, coin_reward, icon
    ) VALUES (
      p_stream_id, template.id, template.name, template.description, template.mission_type,
      template.target_metric, template.target_value, template.difficulty,
      template.chain_group, template.chain_order,
      CASE WHEN template.chain_order > 0 THEN 'chained' ELSE 'active' END,
      CASE WHEN template.duration_minutes IS NOT NULL THEN now() + (template.duration_minutes || ' minutes')::INTERVAL ELSE NULL END,
      template.xp_reward, template.coin_reward, template.icon
    );
  END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

