-- Marketplace Order Enhancement Migration
-- Adds: tracking, fulfillment, escrow/payout hold, appeals integration, troll court escalation
-- Run in Supabase SQL Editor

-- ==========================================
-- 1. ENHANCED ORDER STATUS & FULFILLMENT
-- ==========================================

-- Add new status values and columns to marketplace_purchases
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS fulfillment_status text 
  DEFAULT 'pending' 
  CHECK (fulfillment_status IN ('pending', 'awaiting_fulfillment', 'fulfilled', 'delivered', 'issue_reported', 'appeal_open', 'resolved', 'lawsuit_filed', 'cancelled', 'refunded'));

ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS payout_status text 
  DEFAULT 'held' 
  CHECK (payout_status IN ('held', 'released', 'on_hold', 'refunded', 'cancelled'));

ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS payout_released_at timestamptz;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS payout_held_at timestamptz DEFAULT now();
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS payout_release_transaction_id uuid;

-- Link to appeals and troll court cases
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS appeal_id uuid REFERENCES transaction_appeals(id) ON DELETE SET NULL;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS troll_court_case_id uuid REFERENCES troll_court_cases(id) ON DELETE SET NULL;

-- Tracking last updated for auto-refresh
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS tracking_last_updated_at timestamptz;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS estimated_delivery_date timestamptz;

-- Seller input fields
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS shipped_date timestamptz;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS carrier_tracking_status text;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS tracking_error text;

-- Ensure tracking columns exist (may have been added in earlier migration)
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS status text DEFAULT 'pending';
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS shipping_carrier text;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS tracking_number text;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS tracking_url text;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS shipped_at timestamptz;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS delivered_at timestamptz;

-- Ensure financial columns exist
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS buyer_id uuid;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS seller_id uuid;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS item_id uuid;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS price_paid bigint DEFAULT 0;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS platform_fee bigint DEFAULT 0;
ALTER TABLE marketplace_purchases ADD COLUMN IF NOT EXISTS seller_earnings bigint DEFAULT 0;

-- Indexes for new columns
CREATE INDEX IF NOT EXISTS idx_mp_fulfillment_status ON marketplace_purchases(fulfillment_status);
CREATE INDEX IF NOT EXISTS idx_mp_payout_status ON marketplace_purchases(payout_status);
CREATE INDEX IF NOT EXISTS idx_mp_appeal_id ON marketplace_purchases(appeal_id);
CREATE INDEX IF NOT EXISTS idx_mp_troll_case_id ON marketplace_purchases(troll_court_case_id);
CREATE INDEX IF NOT EXISTS idx_mp_seller_payout ON marketplace_purchases(seller_id, payout_status);

-- ==========================================
-- 2. ORDER SHIPMENTS TABLE
-- ==========================================

CREATE TABLE IF NOT EXISTS order_shipments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid REFERENCES marketplace_purchases(id) ON DELETE CASCADE NOT NULL,
  
  -- Carrier info
  carrier text NOT NULL CHECK (carrier IN ('usps', 'ups', 'fedex', 'dhl', 'other')),
  tracking_number text NOT NULL,
  tracking_url text,
  
  -- Internal status tracking
  tracking_status text DEFAULT 'pending' 
    CHECK (tracking_status IN ('pending', 'label_created', 'accepted', 'in_transit', 'out_for_delivery', 'delivered', 'exception', 'returned')),
  
  -- Carrier's raw status
  carrier_status text,
  carrier_error text,
  
  -- Timestamps
  shipped_date timestamptz,
  delivered_at timestamptz,
  tracking_last_updated_at timestamptz DEFAULT now(),
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  
  -- Optional: reference to external tracking API response
  external_tracking_data jsonb,
  
  UNIQUE(order_id)
);

CREATE INDEX IF NOT EXISTS idx_shipments_order ON order_shipments(order_id);
CREATE INDEX IF NOT EXISTS idx_shipments_tracking_status ON order_shipments(tracking_status);
CREATE INDEX IF NOT EXISTS idx_shipments_carrier_tracking ON order_shipments(carrier, tracking_number);

-- ==========================================
-- 3. TRACKING EVENTS TABLE
-- ==========================================

CREATE TABLE IF NOT EXISTS tracking_events (
  id uuid primary key default gen_random_uuid(),
  shipment_id uuid REFERENCES order_shipments(id) ON DELETE CASCADE NOT NULL,
  
  -- External event ID from carrier
  external_event_id text,
  
  -- Normalized status
  status text NOT NULL 
    CHECK (status IN ('label_created', 'accepted', 'in_transit', 'out_for_delivery', 'delivered', 'exception', 'returned')),
  
  -- Event details
  description text,
  location text,
  city text,
  state text,
  country text,
  zip_code text,
  
  -- Timestamps
  event_time timestamptz NOT NULL,
  created_at timestamptz DEFAULT now(),
  
  -- Raw carrier data for debugging
  raw_data jsonb
);

CREATE INDEX IF NOT EXISTS idx_tracking_events_shipment ON tracking_events(shipment_id);
CREATE INDEX IF NOT EXISTS idx_tracking_events_status ON tracking_events(status);
CREATE INDEX IF NOT EXISTS idx_tracking_events_time ON tracking_events(event_time DESC);

-- ==========================================
-- 4. PAYOUT HOLDS TABLE (Escrow)
-- ==========================================

CREATE TABLE IF NOT EXISTS marketplace_payout_holds (
  id uuid primary key default gen_random_uuid(),
  order_id uuid REFERENCES marketplace_purchases(id) ON DELETE CASCADE NOT NULL,
  
  -- Amount being held
  amount bigint NOT NULL,
  
  -- Hold status
  status text DEFAULT 'active' CHECK (status IN ('active', 'released', 'refunded', 'cancelled', 'expired')),
  
  -- Release tracking
  released_at timestamptz,
  release_transaction_id uuid,
  released_by uuid REFERENCES user_profiles(id),
  
  -- Refund tracking
  refunded_at timestamptz,
  refund_transaction_id uuid,
  
  -- Timestamps
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now(),
  
  -- Reason for hold/release
  hold_reason text DEFAULT 'awaiting_delivery',
  release_reason text,
  
  UNIQUE(order_id)
);

CREATE INDEX IF NOT EXISTS idx_payout_holds_order ON marketplace_payout_holds(order_id);
CREATE INDEX IF NOT EXISTS idx_payout_holds_status ON marketplace_payout_holds(status);
CREATE INDEX IF NOT EXISTS idx_payout_holds_seller ON marketplace_payout_holds(order_id, status);

-- ==========================================
-- 5. MARKETPLACE TYPE FOR TRACKING
-- ==========================================

DO $$ BEGIN
    CREATE TYPE tracking_event_status AS ENUM (
        'label_created', 
        'accepted', 
        'in_transit', 
        'out_for_delivery', 
        'delivered', 
        'exception', 
        'returned'
    );
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;

-- Function: update_stream_viewer_count
CREATE OR REPLACE FUNCTION public.update_stream_viewer_count(p_stream_id uuid, p_count integer)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE public.streams
  SET current_viewers = GREATEST(COALESCE(p_count, 0), 0),
      viewer_count = GREATEST(COALESCE(p_count, 0), 0)
  WHERE id = p_stream_id;
END;
$$;

-- Function: update_tracking_status
CREATE OR REPLACE FUNCTION update_tracking_status(
  p_carrier text,
  p_tracking_number text,
  p_status text,
  p_description text DEFAULT null,
  p_location text DEFAULT null,
  p_event_time timestamptz DEFAULT now()
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_shipment order_shipments%ROWTYPE;
  v_order marketplace_purchases%ROWTYPE;
  v_normalized_status tracking_event_status;
  v_event_id uuid;
BEGIN
  -- Find shipment by carrier and tracking number
  SELECT * INTO v_shipment 
  FROM order_shipments 
  WHERE carrier = p_carrier AND tracking_number = p_tracking_number;
  
  IF v_shipment IS NULL THEN
    RETURN 'Shipment not found';
  END IF;
  
  -- Normalize status
  v_normalized_status := CASE LOWER(p_status)
    WHEN 'label_created' THEN 'label_created'::tracking_event_status
    WHEN 'pre-shipment' THEN 'label_created'::tracking_event_status
    WHEN 'label created' THEN 'label_created'::tracking_event_status
    WHEN 'accepted' THEN 'accepted'::tracking_event_status
    WHEN 'picked up' THEN 'accepted'::tracking_event_status
    WHEN 'picked-up' THEN 'accepted'::tracking_event_status
    WHEN 'in possession' THEN 'accepted'::tracking_event_status
    WHEN 'in_transit' THEN 'in_transit'::tracking_event_status
    WHEN 'in transit' THEN 'in_transit'::tracking_event_status
    WHEN 'transit' THEN 'in_transit'::tracking_event_status
    WHEN 'departed' THEN 'in_transit'::tracking_event_status
    WHEN 'arrived' THEN 'in_transit'::tracking_event_status
    WHEN 'out_for_delivery' THEN 'out_for_delivery'::tracking_event_status
    WHEN 'out for delivery' THEN 'out_for_delivery'::tracking_event_status
    WHEN 'delivered' THEN 'delivered'::tracking_event_status
    WHEN 'delivery completed' THEN 'delivered'::tracking_event_status
    WHEN 'exception' THEN 'exception'::tracking_event_status
    WHEN 'delivery exception' THEN 'exception'::tracking_event_status
    WHEN 'error' THEN 'exception'::tracking_event_status
    WHEN 'failed' THEN 'exception'::tracking_event_status
    WHEN 'returned' THEN 'returned'::tracking_event_status
    WHEN 'returned to sender' THEN 'returned'::tracking_event_status
    WHEN 'return' THEN 'returned'::tracking_event_status
    ELSE 'in_transit'::tracking_event_status
  END;
  
  -- Insert tracking event
  INSERT INTO tracking_events (
    shipment_id,
    status,
    description,
    location,
    event_time
  )
  VALUES (
    v_shipment.id,
    v_normalized_status,
    p_description,
    p_location,
    p_event_time
  )
  RETURNING id INTO v_event_id;
  
  -- Update shipment status
  UPDATE order_shipments
  SET tracking_status = v_normalized_status,
      carrier_status = p_status,
      tracking_last_updated_at = now(),
      delivered_at = CASE WHEN v_normalized_status = 'delivered'::tracking_event_status THEN now() ELSE delivered_at END,
      updated_at = now()
  WHERE id = v_shipment.id;
  
  -- Get order
  SELECT * INTO v_order FROM marketplace_purchases WHERE id = v_shipment.order_id;
  
  -- Update order based on delivery status
  IF v_normalized_status = 'delivered'::tracking_event_status THEN
    UPDATE marketplace_purchases
    SET status = 'delivered',
        fulfillment_status = 'delivered',
        delivered_at = now(),
        tracking_last_updated_at = now(),
        updated_at = now()
    WHERE id = v_order.id;
    
    -- Release seller payout
    PERFORM release_marketplace_payout(v_order.id, 'carrier_confirmed_delivery');
    
    RETURN 'DELIVERED';
  ELSIF v_normalized_status = 'exception'::tracking_event_status THEN
    UPDATE marketplace_purchases
    SET carrier_tracking_status = 'exception',
        tracking_error = p_description,
        tracking_last_updated_at = now(),
        updated_at = now()
    WHERE id = v_order.id;
    
    RETURN 'EXCEPTION';
  ELSIF v_normalized_status = 'returned'::tracking_event_status THEN
    UPDATE marketplace_purchases
    SET status = 'returned',
        fulfillment_status = 'returned',
        tracking_last_updated_at = now(),
        updated_at = now()
    WHERE id = v_order.id;
    
    RETURN 'RETURNED';
  ELSE
    -- Update tracking status only
    UPDATE marketplace_purchases
    SET carrier_tracking_status = v_normalized_status::text,
        tracking_last_updated_at = now(),
        updated_at = now()
    WHERE id = v_order.id;
    
    RETURN 'UPDATED';
  END IF;
END;
$$;

-- Function: update_vehicle_plate
CREATE OR REPLACE FUNCTION public.update_vehicle_plate(
    p_user_vehicle_id UUID,
    p_new_plate TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_registration RECORD;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Not authenticated');
    END IF;

    -- Validate input
    IF length(p_new_plate) < 3 OR length(p_new_plate) > 8 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Plate must be 3-8 characters');
    END IF;

    IF NOT p_new_plate ~* '^[A-Z0-9]+$' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Plate must be alphanumeric');
    END IF;

    -- Check ownership
    IF NOT EXISTS (
        SELECT 1 FROM public.user_vehicles 
        WHERE id = p_user_vehicle_id AND user_id = v_user_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Vehicle not found or not owned by you');
    END IF;

    -- Check availability
    IF EXISTS (
        SELECT 1 FROM public.vehicle_registrations 
        WHERE plate_number = UPPER(p_new_plate)
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Plate number already taken');
    END IF;

    -- Update registration
    UPDATE public.vehicle_registrations
    SET plate_number = UPPER(p_new_plate)
    WHERE user_vehicle_id = p_user_vehicle_id;

    RETURN jsonb_build_object('success', true, 'message', 'License plate updated to ' || UPPER(p_new_plate));
END;
$$;

-- Function: upgrade_vehicle
CREATE OR REPLACE FUNCTION public.upgrade_vehicle(
    p_user_vehicle_id UUID, 
    p_upgrade_type TEXT -- 'engine', 'armor', 'rims', 'brakes', 'suspension'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_id UUID;
    v_vehicle RECORD;
    v_catalog RECORD;
    v_cost INTEGER;
    v_current_level INTEGER;
    v_new_mods JSONB;
    v_user_balance BIGINT;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Not authenticated');
    END IF;

    -- Get vehicle
    SELECT * INTO v_vehicle FROM public.user_vehicles 
    WHERE id = p_user_vehicle_id AND user_id = v_user_id;
    
    IF v_vehicle IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Vehicle not found');
    END IF;

    -- Get catalog for pricing base
    SELECT * INTO v_catalog FROM public.vehicles_catalog WHERE id = v_vehicle.catalog_id;

    -- Get current level from mods JSONB
    v_current_level := COALESCE((v_vehicle.mods->>p_upgrade_type)::INTEGER, 0);

    IF v_current_level >= 3 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Max level reached for this upgrade');
    END IF;

    -- Determine cost (10% of base price * next level, min 1000)
    -- Level 1 cost: 10%
    -- Level 2 cost: 20%
    -- Level 3 cost: 30%
    v_cost := GREATEST(FLOOR(v_catalog.price * 0.1), 1000) * (v_current_level + 1);

    -- Check balance
    SELECT troll_coins INTO v_user_balance FROM public.user_profiles WHERE id = v_user_id;
    
    IF v_user_balance < v_cost THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient funds: ' || v_cost || ' required');
    END IF;

    -- Deduct coins
    UPDATE public.user_profiles 
    SET troll_coins = troll_coins - v_cost 
    WHERE id = v_user_id;

    -- Update mods
    v_new_mods := jsonb_set(
        COALESCE(v_vehicle.mods, '{}'::jsonb), 
        ARRAY[p_upgrade_type], 
        to_jsonb(v_current_level + 1)
    );

    UPDATE public.user_vehicles
    SET mods = v_new_mods
    WHERE id = p_user_vehicle_id;

    -- Log
    INSERT INTO public.vehicle_transactions (user_id, user_vehicle_id, type, amount, details)
    VALUES (
        v_user_id, 
        p_user_vehicle_id, 
        'upgrade', 
        v_cost, 
        jsonb_build_object(
            'upgrade_type', p_upgrade_type,
            'level', v_current_level + 1
        )
    );

    INSERT INTO public.coin_transactions (user_id, amount, type, description)
    VALUES (
        v_user_id, 
        -v_cost, 
        'upgrade', 
        'Upgraded ' || p_upgrade_type || ' to lvl ' || (v_current_level + 1) || ' on ' || v_catalog.name
    );

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Vehicle upgraded successfully',
        'new_level', v_current_level + 1,
        'cost', v_cost
    );
END;
$$;

-- Function: validate_broadcast_password
CREATE OR REPLACE FUNCTION public.validate_broadcast_password(
  p_stream_id UUID,
  p_password TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_stream RECORD;
  v_is_valid BOOLEAN := false;
BEGIN
  -- Get stream info
  SELECT id, password_hash, is_protected INTO v_stream
  FROM public.streams
  WHERE id = p_stream_id;

  -- If stream doesn't exist, return error
  IF v_stream IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Broadcast not found'
    );
  END IF;

  -- If stream is not protected, allow access
  IF v_stream.is_protected = false OR v_stream.password_hash IS NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'No password required'
    );
  END IF;

  -- Validate password using crypt
  IF p_password IS NOT NULL AND v_stream.password_hash IS NOT NULL THEN
    IF v_stream.password_hash = crypt(p_password, v_stream.password_hash) THEN
      v_is_valid := true;
    END IF;
  END IF;

  IF v_is_valid THEN
    RETURN jsonb_build_object(
      'success', true,
      'message', 'Password validated'
    );
  ELSE
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Incorrect password'
    );
  END IF;
END;
$$;

-- Function: verify_stamp
CREATE OR REPLACE FUNCTION public.verify_stamp(p_verification_code TEXT)
RETURNS JSON
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_stamp RECORD;
  v_document RECORD;
BEGIN
  SELECT * INTO v_stamp FROM public.document_stamps WHERE verification_code = p_verification_code;
  IF NOT FOUND THEN
    RETURN json_build_object('valid', false, 'error', 'Verification code not found');
  END IF;

  SELECT * INTO v_document FROM public.documents WHERE id = v_stamp.document_id;

  RETURN json_build_object(
    'valid', v_stamp.is_valid,
    'stamp_id', v_stamp.stamp_id,
    'seal', v_stamp.seal_text,
    'approver', v_stamp.approver_username,
    'approver_role', v_stamp.approver_role,
    'approval_date', v_stamp.approval_date,
    'document_id', v_stamp.document_id,
    'document_title', v_document.title,
    'document_type', v_document.document_type_slug,
    'document_status', v_document.status,
    'document_checksum', v_stamp.document_checksum,
    'stamp_hash', v_stamp.stamp_hash
  );
END;
$$;

-- Function: vote_candidate_with_coins
create or replace function vote_candidate_with_coins(
   p_candidate_id uuid,
   p_amount int
)
returns jsonb
language plpgsql
security definer
as $$
declare
   v_election_id uuid;
   v_voter_id uuid;
   v_candidate_user_id uuid;
   v_week_key text;
   v_already_voted boolean;
begin
   v_voter_id := auth.uid();

   -- Check if election is open and strategy is coins
   select election_id, user_id into v_election_id, v_candidate_user_id
   from president_candidates
   where id = p_candidate_id;

   if v_election_id is null then
     raise exception 'Candidate not found';
   end if;

   if not exists (
     select 1 from president_elections
     where id = v_election_id
     and status = 'open'
     and voting_strategy = 'coins'
   ) then
     raise exception 'Election is not open for coin voting';
   end if;

   -- Check if already voted this week
   v_week_key := to_char(now(), 'IYYY-"W"IW');
   select exists (
     select 1 from president_votes
     where election_id = v_election_id
     and voter_id = v_voter_id
     and week_key = v_week_key
   ) into v_already_voted;

   if v_already_voted then
     return jsonb_build_object('success', false, 'already_voted', true, 'message', 'You already voted this week');
   end if;

   -- Deduct coins from voter
   if (select troll_coins from user_profiles where id = v_voter_id) < p_amount then
     raise exception 'Insufficient coins';
   end if;

   update user_profiles
   set troll_coins = troll_coins - p_amount
   where id = v_voter_id;

   -- Add to candidate score
   update president_candidates
   set score = score + p_amount,
       vote_count = coalesce(vote_count, 0) + 1
   where id = p_candidate_id;

   -- Log the vote
   insert into president_votes (election_id, candidate_id, voter_id)
   values (v_election_id, p_candidate_id, v_voter_id);

   return jsonb_build_object('success', true, 'already_voted', false);
end;
$$;

-- Function: vote_for_pitch
CREATE OR REPLACE FUNCTION public.vote_for_pitch(
    p_pitch_id UUID, 
    p_voter_id UUID,
    p_vote_type TEXT DEFAULT 'up'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_current_vote_type TEXT;
    v_new_counts RECORD;
BEGIN
    -- Validate vote type
    IF p_vote_type NOT IN ('up', 'down') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid vote type');
    END IF;

    -- Check if already voted
    SELECT vote_type INTO v_current_vote_type
    FROM public.pitch_votes 
    WHERE pitch_id = p_pitch_id AND voter_id = p_voter_id;

    IF v_current_vote_type IS NOT NULL THEN
        -- User has voted
        IF v_current_vote_type = p_vote_type THEN
            RETURN jsonb_build_object('success', false, 'error', 'Already voted ' || p_vote_type);
        ELSE
            -- Switch vote
            UPDATE public.pitch_votes 
            SET vote_type = p_vote_type 
            WHERE pitch_id = p_pitch_id AND voter_id = p_voter_id;

            -- Update counts
            IF p_vote_type = 'up' THEN
                -- Switched from down to up
                UPDATE public.pitches
                SET up_votes = up_votes + 1,
                    down_votes = GREATEST(0, down_votes - 1),
                    vote_count = vote_count + 2
                WHERE id = p_pitch_id
                RETURNING vote_count, up_votes, down_votes INTO v_new_counts;
            ELSE
                -- Switched from up to down
                UPDATE public.pitches
                SET down_votes = down_votes + 1,
                    up_votes = GREATEST(0, up_votes - 1),
                    vote_count = vote_count - 2
                WHERE id = p_pitch_id
                RETURNING vote_count, up_votes, down_votes INTO v_new_counts;
            END IF;

            RETURN jsonb_build_object(
                'success', true, 
                'vote_count', v_new_counts.vote_count,
                'up_votes', v_new_counts.up_votes,
                'down_votes', v_new_counts.down_votes,
                'switched', true
            );
        END IF;
    ELSE
        -- New vote
        INSERT INTO public.pitch_votes (pitch_id, voter_id, vote_type)
        VALUES (p_pitch_id, p_voter_id, p_vote_type);

        IF p_vote_type = 'up' THEN
            UPDATE public.pitches
            SET up_votes = up_votes + 1,
                vote_count = vote_count + 1
            WHERE id = p_pitch_id
            RETURNING vote_count, up_votes, down_votes INTO v_new_counts;
        ELSE
            UPDATE public.pitches
            SET down_votes = down_votes + 1,
                vote_count = vote_count - 1
            WHERE id = p_pitch_id
            RETURNING vote_count, up_votes, down_votes INTO v_new_counts;
        END IF;

        RETURN jsonb_build_object(
            'success', true, 
            'vote_count', v_new_counts.vote_count,
            'up_votes', v_new_counts.up_votes,
            'down_votes', v_new_counts.down_votes,
            'switched', false
        );
    END IF;

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;

-- Function: vote_for_president_candidate
create or replace function vote_for_president_candidate(
   p_election_id uuid,
   p_candidate_id uuid
)
returns jsonb
security definer
language plpgsql
as $$
declare
   v_voter_id uuid;
   v_already_voted boolean;
   v_week_key text;
begin
   v_voter_id := auth.uid();

   -- Check election open
   if not exists (select 1 from president_elections where id = p_election_id and status = 'open') then
     raise exception 'Election not open';
   end if;

   -- Check candidate approved
   if not exists (select 1 from president_candidates where id = p_candidate_id and status = 'approved') then
     raise exception 'Candidate not approved';
   end if;

   -- Check if already voted this week
   v_week_key := to_char(now(), 'IYYY-"W"IW');
   select exists (
     select 1 from president_votes
     where election_id = p_election_id
     and voter_id = v_voter_id
     and week_key = v_week_key
   ) into v_already_voted;

   if v_already_voted then
     return jsonb_build_object('success', false, 'already_voted', true, 'message', 'You already voted this week');
   end if;

   -- Insert vote (trigger sets week_key)
   insert into president_votes (election_id, candidate_id, voter_id)
   values (p_election_id, p_candidate_id, v_voter_id);

   -- Update candidate vote count
   update president_candidates
   set vote_count = coalesce(vote_count, 0) + 1
   where id = p_candidate_id;

   return jsonb_build_object('success', true, 'already_voted', false);
end;
$$;

-- Function: withdraw_tournament
CREATE OR REPLACE FUNCTION public.withdraw_tournament(p_tournament_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_tournament RECORD;
  v_entry_fee INTEGER;
  v_participant RECORD;
BEGIN
  -- 1. Get Tournament Details
  SELECT * INTO v_tournament
  FROM public.tournaments
  WHERE id = p_tournament_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Tournament not found');
  END IF;

  -- Optional: Check if tournament is still open/upcoming? 
  -- Usually you can't withdraw once it starts, but let's allow it if status is NOT 'ended' or strictly 'open'/'upcoming'.
  -- Let's stick to 'open' or 'upcoming' for refunds. If it's live, maybe no refund?
  -- User request didn't specify, but standard logic implies refunds only before lock-in.
  IF v_tournament.status NOT IN ('open', 'upcoming') THEN
     -- If tournament is live/ended, user can withdraw but maybe NO refund? 
     -- Or just block withdrawal?
     -- Let's assume withdrawal is allowed only during registration phase for safety.
     RETURN jsonb_build_object('success', false, 'message', 'Cannot withdraw after tournament has started');
  END IF;

  -- 2. Check participation
  SELECT * INTO v_participant
  FROM public.tournament_participants
  WHERE tournament_id = p_tournament_id AND user_id = v_user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Not a participant');
  END IF;

  -- 3. Refund Fee
  v_entry_fee := COALESCE(v_tournament.entry_fee, 0);

  IF v_entry_fee > 0 THEN
    -- Refund coins
    UPDATE public.user_profiles
    SET troll_coins = troll_coins + v_entry_fee,
        total_spent_coins = GREATEST(0, total_spent_coins - v_entry_fee) -- optional adjustment
    WHERE id = v_user_id;

    -- Log transaction
    INSERT INTO public.coin_transactions (user_id, amount, type, description, metadata)
    VALUES (
      v_user_id, 
      v_entry_fee, 
      'tournament_refund', 
      'Refund for ' || v_tournament.title, 
      jsonb_build_object('tournament_id', p_tournament_id)
    );
  END IF;

  -- 4. Remove Participant (Delete row as requested "keep them out of list")
  DELETE FROM public.tournament_participants
  WHERE id = v_participant.id;

  RETURN jsonb_build_object('success', true, 'message', 'Successfully withdrawn and refunded');
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$$;

-- Function: xtrollz_buy_viewer_subscription
CREATE OR REPLACE FUNCTION public.xtrollz_buy_viewer_subscription(
    p_user_id uuid,
    p_streamer_id uuid,
    p_amount numeric DEFAULT 800
)
RETURNS TABLE(
    success boolean,
    message text,
    subscription_id uuid,
    expires_at timestamptz,
    new_balance numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_spend_result jsonb;
    v_expires_at timestamptz;
    v_subscription_id uuid;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
        success := false;
        message := 'not_authenticated';
        subscription_id := NULL;
        expires_at := NULL;
        new_balance := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_amount <= 0 THEN
        success := false;
        message := 'invalid_amount';
        subscription_id := NULL;
        expires_at := NULL;
        new_balance := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_streamer_id = p_user_id THEN
        success := false;
        message := 'cannot_subscribe_to_self';
        subscription_id := NULL;
        expires_at := NULL;
        new_balance := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    SELECT p.xtrollz_access_status, p.age_verified, p.identity_verified
    INTO v_spend_result
    FROM public.user_profiles p
    WHERE p.id = p_user_id;

    IF NOT FOUND OR v_spend_result::text != 'approved' THEN
        success := false;
        message := 'not_approved';
        subscription_id := NULL;
        expires_at := NULL;
        new_balance := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    IF p_amount <> 800 THEN
        success := false;
        message := 'invalid_subscription_amount';
        subscription_id := NULL;
        expires_at := NULL;
        new_balance := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    v_expires_at := NOW() + INTERVAL '6 months';

    PERFORM set_config('app.bypass_coin_protection', 'true', true);

    v_spend_result := public.troll_bank_spend_coins(
        p_user_id => p_user_id,
        p_amount => p_amount,
        p_bucket => 'paid',
        p_source => 'xtrollz_viewer_subscription',
        p_ref_id => p_streamer_id,
        p_metadata => jsonb_build_object('streamer_id', p_streamer_id, 'duration_months', 6)
    );

    IF NOT (v_spend_result->>'success')::boolean THEN
        success := false;
        message := COALESCE(v_spend_result->>'error', 'Insufficient balance');
        subscription_id := NULL;
        expires_at := NULL;
        new_balance := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    INSERT INTO public.xtrollz_viewer_subscriptions (user_id, streamer_id, amount_paid, expires_at)
    VALUES (p_user_id, p_streamer_id, p_amount, v_expires_at)
    RETURNING id INTO v_subscription_id;

    success := true;
    message := 'subscription_created';
    subscription_id := v_subscription_id;
    expires_at := v_expires_at;
    new_balance := (v_spend_result->>'new_balance')::numeric;
    RETURN NEXT;
END;
$$;

-- Function: xtrollz_check_viewer_access
CREATE OR REPLACE FUNCTION public.xtrollz_check_viewer_access(
  p_stream_id uuid,
  p_user_id uuid
)
RETURNS TABLE(
  allowed boolean,
  reason text,
  stream_status text,
  streamer_id uuid,
  is_live boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_stream record;
  v_profile record;
  v_blocked boolean;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    allowed := false;
    reason := 'not_authenticated';
    stream_status := NULL;
    streamer_id := NULL;
    is_live := false;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO v_profile
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF v_profile.xtrollz_access_status IN ('suspended', 'banned')
     OR v_profile.is_banned = true
     OR v_profile.account_state IN ('banned', 'jailed') THEN
    allowed := false;
    reason := 'account_suspended_or_banned';
    stream_status := NULL;
    streamer_id := NULL;
    is_live := false;
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_profile.age_verified = false OR v_profile.identity_verified = false THEN
    allowed := false;
    reason := 'not_verified';
    stream_status := NULL;
    streamer_id := NULL;
    is_live := false;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO v_stream
  FROM public.xtrollz_streams
  WHERE id = p_stream_id;

  IF v_stream.id IS NULL THEN
    allowed := false;
    reason := 'stream_not_found';
    stream_status := NULL;
    streamer_id := NULL;
    is_live := false;
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_stream.status != 'live' THEN
    allowed := false;
    reason := 'stream_not_active';
    stream_status := v_stream.status;
    streamer_id := v_stream.user_id;
    is_live := false;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.utromail_blocked_users bu
    WHERE (bu.user_id = p_user_id AND bu.blocked_user_id = v_stream.user_id)
       OR (bu.user_id = v_stream.user_id AND bu.blocked_user_id = p_user_id)
  ) INTO v_blocked;

  IF v_blocked THEN
    allowed := false;
    reason := 'blocked';
    stream_status := v_stream.status;
    streamer_id := v_stream.user_id;
    is_live := true;
    RETURN NEXT;
    RETURN;
  END IF;

  allowed := true;
  reason := 'ok';
  stream_status := v_stream.status;
  streamer_id := v_stream.user_id;
  is_live := true;
  RETURN NEXT;
END;
$$;

-- Function: xtrollz_check_viewer_subscription
CREATE OR REPLACE FUNCTION public.xtrollz_check_viewer_subscription(
    p_user_id uuid,
    p_streamer_id uuid
)
RETURNS TABLE(
    has_subscription boolean,
    expires_at timestamptz,
    is_active boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
        has_subscription := false;
        expires_at := NULL;
        is_active := false;
        RETURN NEXT;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        s.is_active,
        s.expires_at,
        s.is_active
    FROM public.xtrollz_viewer_subscriptions s
    WHERE s.user_id = p_user_id
      AND s.streamer_id = p_streamer_id
      AND s.expires_at > NOW()
    ORDER BY s.created_at DESC
    LIMIT 1;
END;
$$;

-- Function: xtrollz_dob_gate_get_status
CREATE OR REPLACE FUNCTION public.xtrollz_dob_gate_get_status(
  p_user_id uuid
)
RETURNS TABLE(
  result text,
  application_status text,
  access_status text,
  is_age_verified boolean,
  is_identity_verified boolean,
  rules_accepted boolean,
  can_access boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    result := 'not_authenticated';
    application_status := NULL;
    access_status := NULL;
    is_age_verified := false;
    is_identity_verified := false;
    rules_accepted := false;
    can_access := false;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT
    a.status,
    up.xtrollz_access_status,
    up.age_verified,
    up.identity_verified,
    EXISTS (
      SELECT 1 FROM public.xtrollz_rules_acceptance ra
      WHERE ra.user_id = p_user_id
    )
  INTO
    application_status,
    access_status,
    is_age_verified,
    is_identity_verified,
    rules_accepted
  FROM public.xtrollz_applications a
  JOIN public.user_profiles up ON up.id = p_user_id
  WHERE a.user_id = p_user_id
  ORDER BY a.created_at DESC
  LIMIT 1;

  IF application_status IS NULL THEN
    result := 'missing_application';
    can_access := false;
    RETURN NEXT;
    RETURN;
  END IF;

  IF application_status IN ('denied', 'revoked', 'expired') THEN
    result := 'application_denied';
    can_access := false;
    RETURN NEXT;
    RETURN;
  END IF;

  IF application_status IN ('draft', 'payment_pending', 'payment_failed') THEN
    result := 'pending_application';
    can_access := false;
    RETURN NEXT;
    RETURN;
  END IF;

  IF application_status IN ('submitted', 'under_review', 'more_information_required') THEN
    result := 'pending_application';
    can_access := false;
    RETURN NEXT;
    RETURN;
  END IF;

  IF application_status = 'approved' THEN
    IF NOT is_age_verified THEN
      result := 'dob_required';
      can_access := false;
      RETURN NEXT;
      RETURN;
    END IF;
    IF NOT is_identity_verified THEN
      result := 'restricted';
      can_access := false;
      RETURN NEXT;
      RETURN;
    END IF;
    IF NOT rules_accepted THEN
      result := 'rules_acceptance_required';
      can_access := false;
      RETURN NEXT;
      RETURN;
    END IF;
    IF access_status IN ('suspended', 'banned') THEN
      result := access_status;
      can_access := false;
      RETURN NEXT;
      RETURN;
    END IF;
    result := 'approved';
    can_access := true;
    RETURN NEXT;
    RETURN;
  END IF;

  result := 'restricted';
  can_access := false;
  RETURN NEXT;
END;
$$;

-- Function: xtrollz_end_broadcast
CREATE OR REPLACE FUNCTION public.xtrollz_end_broadcast(
  p_stream_id uuid,
  p_user_id uuid
)
RETURNS TABLE(
  success boolean,
  message text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_stream record;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    success := false;
    message := 'not_authenticated';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO v_stream
  FROM public.xtrollz_streams
  WHERE id = p_stream_id AND user_id = p_user_id;

  IF v_stream.id IS NULL THEN
    success := false;
    message := 'stream_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_stream.status NOT IN ('live', 'starting') THEN
    success := false;
    message := 'stream_not_active';
    RETURN NEXT;
    RETURN;
  END IF;

  UPDATE public.xtrollz_streams
  SET status = 'ended', ended_at = now(), updated_at = now()
  WHERE id = p_stream_id;

  success := true;
  message := 'ok';
  RETURN NEXT;
END;
$$;

-- Function: xtrollz_get_favorites
CREATE OR REPLACE FUNCTION public.xtrollz_get_favorites(
  p_user_id uuid
)
RETURNS TABLE(
  streamer_id uuid,
  display_name text,
  avatar_url text,
  is_live boolean,
  title text,
  category text,
  viewer_count integer,
  last_live_at timestamptz,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    f.streamer_id,
    COALESCE(up.display_name, up.username, 'Unknown') as display_name,
    up.avatar_url,
    EXISTS (
      SELECT 1 FROM public.xtrollz_streams s
      WHERE s.user_id = f.streamer_id AND s.status = 'live'
    ) as is_live,
    (
      SELECT s.title FROM public.xtrollz_streams s
      WHERE s.user_id = f.streamer_id AND s.status = 'live'
      ORDER BY s.started_at DESC LIMIT 1
    ) as title,
    (
      SELECT s.category FROM public.xtrollz_streams s
      WHERE s.user_id = f.streamer_id AND s.status = 'live'
      ORDER BY s.started_at DESC LIMIT 1
    ) as category,
    (
      SELECT s.viewer_count FROM public.xtrollz_streams s
      WHERE s.user_id = f.streamer_id AND s.status = 'live'
      ORDER BY s.started_at DESC LIMIT 1
    ) as viewer_count,
    (
      SELECT MAX(s.started_at) FROM public.xtrollz_streams s
      WHERE s.user_id = f.streamer_id
    ) as last_live_at,
    f.created_at
  FROM public.xtrollz_favorites f
  JOIN public.user_profiles up ON up.id = f.streamer_id
  WHERE f.user_id = p_user_id
  ORDER BY f.created_at DESC;
END;
$$;

-- Function: xtrollz_get_live_streams
CREATE OR REPLACE FUNCTION public.xtrollz_get_live_streams()
RETURNS TABLE(
  id uuid,
  user_id uuid,
  title text,
  description text,
  category text,
  is_private boolean,
  viewer_count integer,
  started_at timestamptz,
  cover_image_url text,
  thumbnail_url text,
  streamer_display_name text,
  profile_image_url text,
  tags text[],
  status text,
  livekit_room_name text,
  created_at timestamptz,
  updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id, s.user_id, s.title, s.description, s.category,
    s.is_private, s.viewer_count, s.started_at,
    s.cover_image_url, s.thumbnail_url, s.streamer_display_name,
    s.profile_image_url, s.tags, s.status, s.livekit_room_name,
    s.created_at, s.updated_at
  FROM public.xtrollz_streams s
  WHERE s.status = 'live'
  ORDER BY s.viewer_count DESC, s.started_at DESC;
END;
$$;

-- Function: xtrollz_get_streamer_prices
CREATE OR REPLACE FUNCTION public.xtrollz_get_streamer_prices(
