-- Function: xtrollz_pay_application_fee
CREATE OR REPLACE FUNCTION public.xtrollz_pay_application_fee(
    p_application_id uuid,
    p_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_application public.xtrollz_applications%ROWTYPE;
    v_spend_result jsonb;
    v_fee_amount numeric := 1000;
BEGIN
    PERFORM set_config('app.bypass_coin_protection', 'true', true);

    IF p_user_id <> auth.uid() AND NOT public.is_staff() THEN
        RAISE EXCEPTION 'Unauthorized: can only pay for your own application'
        USING ERRCODE = '42501';
    END IF;

    SELECT * INTO v_application
    FROM public.xtrollz_applications
    WHERE id = p_application_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Application not found');
    END IF;

    IF v_application.user_id <> p_user_id THEN
        RETURN jsonb_build_object('success', false, 'message', 'Application does not belong to user');
    END IF;

    IF v_application.payment_status = 'completed' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Application already paid');
    END IF;

    IF v_application.status NOT IN ('draft', 'payment_pending', 'payment_failed') THEN
        RETURN jsonb_build_object('success', false, 'message', 'Application is not in a payable state');
    END IF;

    IF v_application.xtrollz_role = 'viewer' THEN
        v_fee_amount := 800;
    END IF;

    v_spend_result := public.troll_bank_spend_coins(
        p_user_id => p_user_id,
        p_amount => v_fee_amount,
        p_bucket => 'paid',
        p_source => 'xtrollz_application_fee',
        p_ref_id => p_application_id,
        p_metadata => jsonb_build_object('application_id', p_application_id, 'role', v_application.xtrollz_role, 'fee_amount', v_fee_amount)
    );

    IF NOT (v_spend_result->>'success')::boolean THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', COALESCE(v_spend_result->>'error', 'Insufficient balance'),
            'amount_deducted', 0,
            'fee_amount', v_fee_amount
        );
    END IF;

    UPDATE public.xtrollz_applications
    SET
        status = 'submitted',
        payment_status = 'completed',
        payment_amount = v_fee_amount,
        payment_currency = 'TC',
        payment_timestamp = NOW(),
        updated_at = NOW()
    WHERE id = p_application_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Application fee paid successfully',
        'application_id', p_application_id,
        'amount_deducted', v_fee_amount,
        'new_balance', (v_spend_result->>'new_balance')::numeric,
        'fee_amount', v_fee_amount,
        'status', 'completed'
    );
END;
$$;

-- Function: xtrollz_set_streamer_prices
CREATE OR REPLACE FUNCTION public.xtrollz_set_streamer_prices(
    p_user_id uuid,
    p_subscription_price numeric DEFAULT 800,
    p_private_show_price numeric DEFAULT 500,
    p_tip_message_price numeric DEFAULT 50,
    p_description text DEFAULT ''
)
RETURNS TABLE(
    success boolean,
    message text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
        success := false;
        message := 'not_authenticated';
        RETURN NEXT;
        RETURN;
    END IF;

    INSERT INTO public.xtrollz_stream_prices (
        user_id, subscription_price, private_show_price, tip_message_price, description
    ) VALUES (
        p_user_id, p_subscription_price, p_private_show_price, p_tip_message_price, p_description
    )
    ON CONFLICT (user_id) DO UPDATE SET
        subscription_price = EXCLUDED.subscription_price,
        private_show_price = EXCLUDED.private_show_price,
        tip_message_price = EXCLUDED.tip_message_price,
        description = EXCLUDED.description,
        updated_at = NOW();

    success := true;
    message := 'prices_updated';
    RETURN NEXT;
END;
$$;

-- Function: xtrollz_start_broadcast
CREATE OR REPLACE FUNCTION public.xtrollz_start_broadcast(
  p_user_id uuid,
  p_title text,
  p_category text,
  p_description text DEFAULT NULL,
  p_is_private boolean DEFAULT false,
  p_tags text[] DEFAULT '{}'
)
RETURNS TABLE(
  stream_id uuid,
  livekit_room_name text,
  success boolean,
  message text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_profile record;
  v_application record;
  v_existing_stream uuid;
  v_room_name text;
  v_stream_id uuid;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    stream_id := NULL;
    livekit_room_name := NULL;
    success := false;
    message := 'not_authenticated';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO v_profile
  FROM public.user_profiles
  WHERE id = p_user_id;

  IF v_profile.xtrollz_access_status != 'approved'
     AND NOT EXISTS (
       SELECT 1 FROM public.xtrollz_applications a
       WHERE a.user_id = p_user_id AND a.status = 'approved'
     ) THEN
    success := false;
    message := 'application_not_approved';
    stream_id := NULL;
    livekit_room_name := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_profile.age_verified = false OR v_profile.identity_verified = false THEN
    success := false;
    message := 'not_verified';
    stream_id := NULL;
    livekit_room_name := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  IF v_profile.xtrollz_access_status IN ('suspended', 'banned')
     OR v_profile.is_banned = true
     OR v_profile.account_state IN ('banned', 'jailed') THEN
    success := false;
    message := 'account_suspended_or_banned';
    stream_id := NULL;
    livekit_room_name := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO v_application
  FROM public.xtrollz_applications
  WHERE user_id = p_user_id AND status = 'approved'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_application.xtrollz_role != 'streamer' THEN
    success := false;
    message := 'not_a_streamer';
    stream_id := NULL;
    livekit_room_name := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT id INTO v_existing_stream
  FROM public.xtrollz_streams
  WHERE user_id = p_user_id AND status IN ('live', 'starting')
  LIMIT 1;

  IF v_existing_stream IS NOT NULL THEN
    success := false;
    message := 'already_broadcasting';
    stream_id := v_existing_stream;
    livekit_room_name := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  v_room_name := 'xtrollz-' || p_user_id::text || '-' || gen_random_uuid()::text;

  INSERT INTO public.xtrollz_streams (
    user_id, title, description, category, is_private,
    status, livekit_room_name, tags, started_at
  )
  VALUES (
    p_user_id, p_title, p_description, p_category, p_is_private,
    'starting', v_room_name, p_tags, now()
  )
  RETURNING id INTO v_stream_id;

  success := true;
  message := 'ok';
  stream_id := v_stream_id;
  livekit_room_name := v_room_name;
  RETURN NEXT;
END;
$$;

-- Function: xtrollz_toggle_favorite
CREATE OR REPLACE FUNCTION public.xtrollz_toggle_favorite(
  p_user_id uuid,
  p_streamer_id uuid
)
RETURNS TABLE(
  is_favorited boolean,
  streamer_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    is_favorited := false;
    streamer_id := p_streamer_id;
    RETURN NEXT;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.xtrollz_favorites f
    WHERE f.user_id = p_user_id AND f.streamer_id = p_streamer_id
  ) THEN
    DELETE FROM public.xtrollz_favorites
    WHERE user_id = p_user_id AND streamer_id = p_streamer_id;
    is_favorited := false;
  ELSE
    INSERT INTO public.xtrollz_favorites (user_id, streamer_id)
    VALUES (p_user_id, p_streamer_id);
    is_favorited := true;
  END IF;

  streamer_id := p_streamer_id;
  RETURN NEXT;
END;
$$;

-- Function: xtrollz_update_stream_status
CREATE OR REPLACE FUNCTION public.xtrollz_update_stream_status(
  p_stream_id uuid,
  p_user_id uuid,
  p_status text
)
RETURNS TABLE(
  success boolean,
  message text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_stream record;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    success := false;
    message := 'not_authenticated';
    RETURN NEXT;
    RETURN;
  END IF;

  IF p_status NOT IN ('live', 'offline', 'ended') THEN
    success := false;
    message := 'invalid_status';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT * INTO v_stream
  FROM public.xtrollz_streams
  WHERE id = p_stream_id AND user_id = p_user_id;

  IF v_stream.id IS NULL THEN
    success := false;
    message := 'stream_not_found';
    RETURN NEXT;
    RETURN;
  END IF;

  UPDATE public.xtrollz_streams
  SET status = p_status,
      started_at = CASE WHEN p_status = 'live' AND started_at IS NULL THEN now() ELSE started_at END,
      ended_at = CASE WHEN p_status = 'ended' THEN now() ELSE ended_at END,
      updated_at = now()
  WHERE id = p_stream_id;

  success := true;
  message := 'ok';
  RETURN NEXT;
END;
$$;

-- Function: xtrollz_verify_dob
CREATE OR REPLACE FUNCTION public.xtrollz_verify_dob(
  p_user_id uuid,
  p_entered_dob text
)
RETURNS TABLE(
  result text,
  message text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_app_dob date;
  v_entered_dob date;
  v_age integer;
  v_application_status text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() != p_user_id THEN
    result := 'not_authenticated';
    message := 'Not authenticated';
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT date_of_birth, status
  INTO v_app_dob, v_application_status
  FROM public.xtrollz_applications
  WHERE user_id = p_user_id
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_application_status IS NULL OR v_application_status != 'approved' THEN
    result := 'restricted';
    message := 'Application not approved';
    RETURN NEXT;
    RETURN;
  END IF;

  BEGIN
    v_entered_dob := p_entered_dob::date;
  EXCEPTION WHEN OTHERS THEN
    result := 'dob_mismatch';
    message := 'Invalid date format';
    RETURN NEXT;
  END;

  IF v_entered_dob != v_app_dob THEN
    result := 'dob_mismatch';
    message := 'Date of birth does not match';
    RETURN NEXT;
    RETURN;
  END IF;

  v_age := DATE_PART('year', AGE(CURRENT_DATE, v_entered_dob));

  IF v_age < 21 THEN
    result := 'underage';
    message := 'Must be 21 or older';
    UPDATE public.user_profiles
    SET age_verified = false, updated_at = now()
    WHERE id = p_user_id;
    RETURN NEXT;
    RETURN;
  END IF;

  UPDATE public.user_profiles
  SET age_verified = true, updated_at = now()
  WHERE id = p_user_id;

  IF EXISTS (
    SELECT 1 FROM public.xtrollz_rules_acceptance ra
    WHERE ra.user_id = p_user_id
  ) THEN
    UPDATE public.user_profiles
    SET identity_verified = true, updated_at = now()
    WHERE id = p_user_id;
  END IF;

  result := 'approved';
  message := 'Access granted';
  RETURN NEXT;
END;
$$;

