CREATE POLICY "tromail_calendar_event_recipients_insert" ON tromail_calendar_event_recipients
  FOR INSERT WITH CHECK (
    calendar_event_id IN (SELECT public.get_auth_user_created_calendar_event_ids())
    OR EXISTS (
      SELECT 1 FROM user_profiles up
      WHERE up.id = auth.uid()
      AND (
        up.role IN ('admin', 'secretary')
        OR up.is_admin = true
      )
    )
  );
CREATE POLICY "tromail_calendar_event_recipients_delete" ON tromail_calendar_event_recipients
  FOR DELETE USING (
    calendar_event_id IN (SELECT public.get_auth_user_created_calendar_event_ids())
    OR EXISTS (
      SELECT 1 FROM user_profiles up
      WHERE up.id = auth.uid()
      AND (
        up.role IN ('admin', 'secretary')
        OR up.is_admin = true
      )
    )
  );
CREATE POLICY "auth_select_own" ON public.call_minutes
    FOR SELECT TO authenticated
    USING (user_id = auth.uid());
CREATE POLICY "auth_insert_own" ON public.call_minutes
    FOR INSERT TO authenticated
    WITH CHECK (user_id = auth.uid());
CREATE POLICY "auth_update_own" ON public.call_minutes
    FOR UPDATE TO authenticated
    USING (user_id = auth.uid())
    WITH CHECK (user_id = auth.uid());
CREATE POLICY "auth_delete_own" ON public.call_minutes
    FOR DELETE TO authenticated
    USING (user_id = auth.uid());
CREATE POLICY "anon_view_active_court_sessions"
  ON public.court_sessions
  FOR SELECT
  TO anon
  USING ((status = 'active'::text) OR (status = 'live'::text));
CREATE POLICY "anon_view_active_court_sessions_service"
  ON public.court_sessions
  FOR SELECT
  TO service_role
  USING ((status = 'active'::text) OR (status = 'live'::text));
CREATE POLICY broadcast_officers_select ON public.broadcast_officers
    FOR SELECT USING (true);
CREATE POLICY "city_ads_select_policy" ON public.city_ads FOR SELECT USING (true);
CREATE POLICY "city_ads_insert_policy" ON public.city_ads FOR INSERT WITH CHECK (auth.uid() = created_by OR is_admin(auth.uid()));
CREATE POLICY "city_ads_update_policy" ON public.city_ads FOR UPDATE USING (auth.uid() = created_by OR is_admin(auth.uid()));
CREATE POLICY "city_ads_delete_policy" ON public.city_ads FOR DELETE USING (auth.uid() = created_by OR is_admin(auth.uid()));
CREATE POLICY "promo_cards_user_own" ON promo_cards
FOR SELECT USING (user_id = auth.uid());
CREATE POLICY "promo_cards_service_all" ON promo_cards FOR ALL TO service_role USING (true);
CREATE POLICY "promo_cards_user_own"
      ON public.promo_cards
      FOR SELECT
      USING (user_id = auth.uid());

